def _can_write_statement_project_data(user) -> bool:
    permissions = set(getattr(user, "permissions", []) or [])
    return getattr(user, "role", None) == "admin" or "statements:project:write" in permissions


def _require_isso_support_input_user(user=Depends(current_user)):
    permissions = set(getattr(user, "permissions", []) or [])
    if getattr(user, "role", None) == "admin" or permissions.intersection({"settings:write", "reports:edit", "reports:input"}):
        return user
    raise HTTPException(403, "Ввод площадок ИССО доступен пользователю с правом ввода отчетов")


def _dashboard_short_cache_get(cache: dict[tuple, tuple[float, dict]], key: tuple) -> Optional[dict]:
    if DASHBOARD_SHORT_CACHE_TTL_SECONDS <= 0:
        return None
    now = time.monotonic()
    with _DASHBOARD_SHORT_CACHE_LOCK:
        cached = cache.get(key)
        if not cached:
            return None
        created_at, payload = cached
        if now - created_at > DASHBOARD_SHORT_CACHE_TTL_SECONDS:
            cache.pop(key, None)
            return None
        return payload


def _dashboard_short_cache_set(cache: dict[tuple, tuple[float, dict]], key: tuple, payload: dict) -> dict:
    if DASHBOARD_SHORT_CACHE_TTL_SECONDS <= 0:
        return payload
    with _DASHBOARD_SHORT_CACHE_LOCK:
        cache[key] = (time.monotonic(), payload)
    return payload


DASHBOARD_RESPONSE_CACHE_VERSION = 4
DASHBOARD_RESPONSE_CACHE_TTL_SECONDS = int(os.getenv("DASHBOARD_RESPONSE_CACHE_TTL_SECONDS", "86400"))
DASHBOARD_RESPONSE_STALE_TTL_SECONDS = int(os.getenv("DASHBOARD_RESPONSE_STALE_TTL_SECONDS", "1800"))
DASHBOARD_RESPONSE_BUILD_WAIT_SECONDS = float(os.getenv("DASHBOARD_RESPONSE_BUILD_WAIT_SECONDS", "5"))
_DASHBOARD_RESPONSE_CACHE_READY = False
_DASHBOARD_RESPONSE_CACHE_STATE_READY = False
_DASHBOARD_RESPONSE_CACHE_LOCK = threading.Lock()
_DASHBOARD_RESPONSE_REFRESH_LOCK = threading.Lock()
_DASHBOARD_RESPONSE_REFRESHING_KEYS: set[tuple[str, str, str]] = set()
_DASHBOARD_RESPONSE_CONTEXT = threading.local()


def _dashboard_json_payload(payload: dict) -> dict:
    return json.loads(json.dumps(payload, ensure_ascii=False, default=str))


def _dashboard_response_cache_should_serve_stale() -> bool:
    return not bool(getattr(_DASHBOARD_RESPONSE_CONTEXT, "force_rebuild", False))


def _dashboard_response_cache_mark(
    payload: dict,
    *,
    status: str,
    fingerprint: str,
    created_at: Optional[str] = None,
    refreshing: bool = False,
) -> dict:
    result = _dashboard_json_payload(payload)
    result["cache_status"] = status
    result["cache_fingerprint"] = fingerprint
    result["cache_refreshing"] = bool(refreshing)
    if created_at:
        result["cache_created_at"] = created_at
    return result


def _dashboard_response_cache_refresh_async(
    endpoint: str,
    cache_key: str,
    fingerprint: str,
    refresh_fn,
    *args,
    **kwargs,
) -> bool:
    token = (endpoint, cache_key, fingerprint)
    with _DASHBOARD_RESPONSE_REFRESH_LOCK:
        if token in _DASHBOARD_RESPONSE_REFRESHING_KEYS:
            return True
        _DASHBOARD_RESPONSE_REFRESHING_KEYS.add(token)

    def runner() -> None:
        previous = bool(getattr(_DASHBOARD_RESPONSE_CONTEXT, "force_rebuild", False))
        _DASHBOARD_RESPONSE_CONTEXT.force_rebuild = True
        try:
            refresh_fn(*args, **kwargs)
        except Exception as exc:
            print(f"[dashboard-cache] background refresh failed for {endpoint}: {exc}", flush=True)
        finally:
            _DASHBOARD_RESPONSE_CONTEXT.force_rebuild = previous
            with _DASHBOARD_RESPONSE_REFRESH_LOCK:
                _DASHBOARD_RESPONSE_REFRESHING_KEYS.discard(token)

    threading.Thread(
        target=runner,
        name=f"dashboard-cache-refresh:{endpoint}",
        daemon=True,
    ).start()
    return True


def _dashboard_response_cache_stale_payload(
    endpoint: str,
    cache_key: str,
    fingerprint: str,
    refresh_fn,
    *args,
    short_cache: Optional[dict[tuple, tuple[float, dict]]] = None,
    short_cache_key: Optional[tuple] = None,
    stale_ttl_seconds: Optional[int] = None,
    **kwargs,
) -> Optional[dict]:
    if not _dashboard_response_cache_should_serve_stale():
        return None
    cached = _dashboard_response_cache_get_latest(
        endpoint,
        cache_key,
        stale_ttl_seconds if stale_ttl_seconds is not None else DASHBOARD_RESPONSE_STALE_TTL_SECONDS,
    )
    if cached is None:
        return None
    refreshing = _dashboard_response_cache_refresh_async(endpoint, cache_key, fingerprint, refresh_fn, *args, **kwargs)
    marked = _dashboard_response_cache_mark(
        cached["payload"],
        status="stale",
        fingerprint=cached.get("fingerprint") or "",
        created_at=cached.get("created_at"),
        refreshing=refreshing,
    )
    marked["cache_expected_fingerprint"] = fingerprint
    if short_cache is not None and short_cache_key is not None:
        _dashboard_short_cache_set(short_cache, short_cache_key, marked)
    return marked


def _dashboard_response_cache_try_build_lock(lock_key: str):
    conn = get_conn()
    conn.autocommit = True
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT pg_try_advisory_lock(hashtext(%s))", (lock_key,))
            locked = bool((cur.fetchone() or [False])[0])
        if locked:
            return conn
    except Exception:
        conn.close()
        raise
    conn.close()
    return None


def _dashboard_response_cache_release_build_lock(conn, lock_key: str) -> None:
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT pg_advisory_unlock(hashtext(%s))", (lock_key,))
    except Exception:
        pass
    finally:
        conn.close()


def _dashboard_response_cache_wait_for_payload(cache_get_fn, timeout_seconds: Optional[float] = None) -> Optional[dict]:
    deadline = time.monotonic() + max(0.0, DASHBOARD_RESPONSE_BUILD_WAIT_SECONDS if timeout_seconds is None else timeout_seconds)
    while time.monotonic() < deadline:
        cached = cache_get_fn()
        if cached is not None:
            return cached
        time.sleep(0.25)
    return cache_get_fn()


def _dashboard_response_cache_build_or_wait(
    endpoint: str,
    persistent_key: str,
    fingerprint: str,
    build_fn,
    *,
    cache_get_fn=None,
    cache_set_fn=None,
    short_cache: Optional[dict[tuple, tuple[float, dict]]] = None,
    short_cache_key: Optional[tuple] = None,
    stale_ttl_seconds: Optional[int] = None,
    wait_seconds: Optional[float] = None,
    locked_message: str = "Данные уже пересчитываются; обновите вкладку через несколько секунд.",
) -> dict:
    def read_current() -> Optional[dict]:
        if cache_get_fn is not None:
            return cache_get_fn()
        return _dashboard_response_cache_get(endpoint, persistent_key, fingerprint)

    def write_current(payload: dict) -> dict:
        if cache_set_fn is not None:
            return cache_set_fn(payload)
        return _dashboard_response_cache_set(endpoint, persistent_key, fingerprint, payload)

    def finish(payload: dict) -> dict:
        if short_cache is not None and short_cache_key is not None:
            return _dashboard_short_cache_set(short_cache, short_cache_key, payload)
        return payload

    lock_key = f"dashboard_response_cache:{endpoint}:{persistent_key}:{fingerprint}"
    lock_conn = _dashboard_response_cache_try_build_lock(lock_key)
    if lock_conn is None:
        cached = _dashboard_response_cache_wait_for_payload(read_current, wait_seconds)
        if cached is not None:
            return finish(_dashboard_response_cache_mark(cached, status="fresh", fingerprint=fingerprint))
        stale = _dashboard_response_cache_get_latest(
            endpoint,
            persistent_key,
            stale_ttl_seconds if stale_ttl_seconds is not None else DASHBOARD_RESPONSE_STALE_TTL_SECONDS,
        )
        if stale is not None:
            marked = _dashboard_response_cache_mark(
                stale["payload"],
                status="stale",
                fingerprint=str(stale.get("fingerprint") or ""),
                created_at=stale.get("created_at"),
                refreshing=True,
            )
            marked["cache_expected_fingerprint"] = fingerprint
            return finish(marked)
        raise HTTPException(503, locked_message)

    try:
        cached = read_current()
        if cached is not None:
            return finish(_dashboard_response_cache_mark(cached, status="fresh", fingerprint=fingerprint))
        payload = dict(build_fn())
        payload = write_current(payload)
        return finish(_dashboard_response_cache_mark(payload, status="fresh", fingerprint=fingerprint))
    finally:
        _dashboard_response_cache_release_build_lock(lock_conn, lock_key)


def _dashboard_response_cache_key(params: dict[str, object]) -> str:
    stable = json.dumps(params, ensure_ascii=False, sort_keys=True, default=str)
    return hashlib.sha256(stable.encode("utf-8")).hexdigest()


def _ensure_dashboard_response_cache_table() -> None:
    global _DASHBOARD_RESPONSE_CACHE_READY
    if _DASHBOARD_RESPONSE_CACHE_READY or DASHBOARD_RESPONSE_CACHE_TTL_SECONDS <= 0:
        return
    with _DASHBOARD_RESPONSE_CACHE_LOCK:
        if _DASHBOARD_RESPONSE_CACHE_READY:
            return
        conn = get_conn()
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        CREATE TABLE IF NOT EXISTS dashboard_response_cache (
                          endpoint text NOT NULL,
                          cache_key text NOT NULL,
                          fingerprint text NOT NULL,
                          payload jsonb NOT NULL,
                          created_at timestamptz NOT NULL DEFAULT now(),
                          PRIMARY KEY (endpoint, cache_key, fingerprint)
                        )
                        """
                    )
                    cur.execute(
                        """
                        CREATE INDEX IF NOT EXISTS idx_dashboard_response_cache_lookup
                        ON dashboard_response_cache(endpoint, cache_key, created_at DESC)
                        """
                    )
            _DASHBOARD_RESPONSE_CACHE_READY = True
        finally:
            conn.close()



def _ensure_dashboard_response_cache_state() -> None:
    global _DASHBOARD_RESPONSE_CACHE_STATE_READY
    if _DASHBOARD_RESPONSE_CACHE_STATE_READY:
        return
    with _DASHBOARD_RESPONSE_CACHE_LOCK:
        if _DASHBOARD_RESPONSE_CACHE_STATE_READY:
            return
        conn = get_conn()
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        CREATE TABLE IF NOT EXISTS dashboard_response_cache_state (
                          cache_scope text PRIMARY KEY,
                          generation bigint NOT NULL DEFAULT 1,
                          updated_at timestamptz NOT NULL DEFAULT now()
                        )
                        """
                    )
                    cur.execute(
                        """
                        INSERT INTO dashboard_response_cache_state(cache_scope, generation, updated_at)
                        VALUES ('global', 1, now())
                        ON CONFLICT (cache_scope) DO NOTHING
                        """
                    )
            _DASHBOARD_RESPONSE_CACHE_STATE_READY = True
        finally:
            conn.close()


def _dashboard_response_cache_generation() -> int:
    try:
        _ensure_dashboard_response_cache_state()
        row = query_one(
            "SELECT generation FROM dashboard_response_cache_state WHERE cache_scope = 'global' LIMIT 1"
        )
        return int(row.get("generation") or 1) if row else 1
    except Exception as exc:
        print(f"[dashboard-cache] generation read failed: {exc}", flush=True)
        return 0


def _invalidate_dashboard_response_cache(reason: str = "") -> int:
    try:
        _ensure_dashboard_response_cache_state()
        if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS > 0:
            _ensure_dashboard_response_cache_table()
        conn = get_conn()
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        INSERT INTO dashboard_response_cache_state(cache_scope, generation, updated_at)
                        VALUES ('global', 2, now())
                        ON CONFLICT (cache_scope) DO UPDATE
                        SET generation = dashboard_response_cache_state.generation + 1,
                            updated_at = now()
                        RETURNING generation
                        """
                    )
                    row = cur.fetchone()
                    generation = int(row[0] or 1) if row else 1
                    if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS > 0:
                        cur.execute(
                            """
                            DELETE FROM dashboard_response_cache
                            WHERE created_at < now() - (%s::text || ' seconds')::interval
                            """,
                            (DASHBOARD_RESPONSE_CACHE_TTL_SECONDS,),
                        )
        finally:
            conn.close()
        with _DASHBOARD_SHORT_CACHE_LOCK:
            _DASHBOARD_MATERIAL_FLOW_CACHE.clear()
            _DASHBOARD_EQUIPMENT_PULSE_CACHE.clear()
            _DASHBOARD_STAFF_RESOURCES_CACHE.clear()
            _MECHANIZATION_AGGREGATES_CACHE.clear()
            _STATEMENTS_GENERAL_WORKBOOK_CACHE.clear()
        return generation
    except Exception as exc:
        print(f"[dashboard-cache] invalidate failed ({reason or 'unknown'}): {exc}", flush=True)
        return 0

def _dashboard_response_cache_get(endpoint: str, cache_key: str, fingerprint: str) -> Optional[dict]:
    if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS <= 0:
        return None
    _ensure_dashboard_response_cache_table()
    row = query_one(
        """
        SELECT payload
        FROM dashboard_response_cache
        WHERE endpoint = %s
          AND cache_key = %s
          AND fingerprint = %s
          AND created_at >= now() - (%s::text || ' seconds')::interval
        LIMIT 1
        """,
        [endpoint, cache_key, fingerprint, DASHBOARD_RESPONSE_CACHE_TTL_SECONDS],
    )
    payload = row.get("payload") if row else None
    return payload if isinstance(payload, dict) else None


def _dashboard_response_cache_get_latest(endpoint: str, cache_key: str, max_age_seconds: int) -> Optional[dict]:
    if max_age_seconds <= 0:
        return None
    _ensure_dashboard_response_cache_table()
    row = query_one(
        """
        SELECT payload, fingerprint, created_at
        FROM dashboard_response_cache
        WHERE endpoint = %s
          AND cache_key = %s
          AND created_at >= now() - (%s::text || ' seconds')::interval
        ORDER BY created_at DESC
        LIMIT 1
        """,
        [endpoint, cache_key, max_age_seconds],
    )
    payload = row.get("payload") if row else None
    if not isinstance(payload, dict):
        return None
    created_at = row.get("created_at")
    if isinstance(created_at, datetime):
        created_at_value = created_at.astimezone(timezone.utc).isoformat()
    else:
        created_at_value = str(created_at) if created_at is not None else None
    return {
        "payload": payload,
        "fingerprint": str(row.get("fingerprint") or ""),
        "created_at": created_at_value,
    }


def _dashboard_response_cache_set(endpoint: str, cache_key: str, fingerprint: str, payload: dict) -> dict:
    if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS <= 0:
        return payload
    payload_json = json.dumps(payload, ensure_ascii=False, default=str)
    _ensure_dashboard_response_cache_table()
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO dashboard_response_cache(endpoint, cache_key, fingerprint, payload, created_at)
                    VALUES (%s, %s, %s, %s::jsonb, now())
                    ON CONFLICT (endpoint, cache_key, fingerprint) DO UPDATE
                    SET payload = EXCLUDED.payload,
                        created_at = now()
                    """,
                    (endpoint, cache_key, fingerprint, payload_json),
                )
                cur.execute(
                    """
                    DELETE FROM dashboard_response_cache
                    WHERE endpoint = %s
                      AND cache_key = %s
                      AND created_at < now() - (%s::text || ' seconds')::interval
                    """,
                    (endpoint, cache_key, DASHBOARD_RESPONSE_CACHE_TTL_SECONDS),
                )
    finally:
        conn.close()
    return payload


def _dashboard_table_exists(table_name: str) -> bool:
    row = query_one("SELECT to_regclass(%s) IS NOT NULL AS exists", [f"public.{table_name}"])
    return bool(row and row.get("exists"))


def _dashboard_table_fingerprint_piece(
    table_name: str,
    *,
    date_column: Optional[str] = None,
    d_from: Optional[date_cls] = None,
    d_to: Optional[date_cls] = None,
    as_of_column: Optional[str] = None,
    as_of: Optional[date_cls] = None,
    include_review_payload_hash: bool = False,
    timestamp_column: str = "created_at",
) -> dict:
    if not _dashboard_table_exists(table_name):
        return {"table": table_name, "missing": True}
    where: list[str] = []
    params: list[object] = []
    if date_column and d_from and d_to:
        where.append(f"{date_column} BETWEEN %s AND %s")
        params.extend([d_from, d_to])
    if as_of_column and as_of:
        where.append(f"{as_of_column} <= %s")
        params.append(as_of)
    where_sql = "WHERE " + " AND ".join(where) if where else ""
    review_hash_sql = (
        "md5(COALESCE(string_agg(md5(COALESCE(review_payload::text, '')), ',' ORDER BY id::text), '')) AS review_hash"
        if include_review_payload_hash
        else "'' AS review_hash"
    )
    updated_expr = (
        f"MAX(COALESCE(updated_at, {timestamp_column}))"
        if table_name in {"temporary_road_status_segments", "mainline_fill_status_segments", "mainline_rd_coverage", "mainline_work_schedule_ranges"}
        else f"MAX({timestamp_column})"
    )
    row = query_one(
        f"""
        SELECT COUNT(*)::int AS row_count,
               COALESCE(MAX(id::text), '') AS max_id,
               COALESCE({updated_expr}::text, '') AS max_changed_at,
               {review_hash_sql}
        FROM {table_name}
        {where_sql}
        """,
        params,
    ) or {}
    return {
        "table": table_name,
        "row_count": int(row.get("row_count") or 0),
        "max_id": row.get("max_id") or "",
        "max_changed_at": row.get("max_changed_at") or "",
        "review_hash": row.get("review_hash") or "",
    }


def _dashboard_source_fingerprint(
    d_from: date_cls,
    d_to: date_cls,
    *,
    include_work: bool = False,
    include_material: bool = False,
    include_problems: bool = False,
    include_temp_roads: bool = False,
    include_mainline_fill: bool = False,
    include_equipment: bool = False,
) -> str:
    # Cache correctness is controlled by a cheap global generation row. Write paths
    # bump it when dashboard/report facts or relevant settings change.
    base = f"v{DASHBOARD_RESPONSE_CACHE_VERSION}:g{_dashboard_response_cache_generation()}"
    if not include_mainline_fill:
        return base
    pieces = [
        _dashboard_table_fingerprint_piece("construction_sections"),
        _dashboard_table_fingerprint_piece("construction_section_versions"),
        _dashboard_table_fingerprint_piece("mainline_fill_status_segments", date_column="status_date", d_from=d_from, d_to=d_to),
        _dashboard_table_fingerprint_piece("mainline_fill_state_corrections", as_of_column="effective_date", as_of=d_to),
        _dashboard_table_fingerprint_piece("objects"),
        _dashboard_table_fingerprint_piece("object_segments"),
        _dashboard_table_fingerprint_piece("pile_fields"),
        _dashboard_table_fingerprint_piece("pipe_pile_specs"),
        _dashboard_table_fingerprint_piece("project_work_items"),
        _dashboard_table_fingerprint_piece("daily_work_items", date_column="report_date", d_from=PROJECT_START_DATE, d_to=d_to),
        _dashboard_table_fingerprint_piece("daily_work_item_segments"),
        _dashboard_table_fingerprint_piece("mainline_rd_coverage"),
        _dashboard_table_fingerprint_piece("mainline_work_schedule_ranges"),
    ]
    stable = json.dumps(pieces, ensure_ascii=False, sort_keys=True, default=str)
    return f"{base}:mainline:{hashlib.sha256(stable.encode('utf-8')).hexdigest()[:16]}"


