QUARRY_MATERIAL_SUFFIX_KEYS = {"щпгс", "щпс", "пгс", "песок", "sand", "shpgs", "shps"}


def _strip_quarry_material_suffix_key(text: str) -> str:
    parts = text.split()
    if len(parts) > 1 and parts[-1] in QUARRY_MATERIAL_SUFFIX_KEYS:
        return " ".join(parts[:-1]).strip()
    return text


def _quarry_label_key(value: object) -> str:
    text = str(value or "").strip().lower().replace("ё", "е")
    text = re.sub(r"^\s*карьер\s+", "", text, flags=re.I).strip()
    text = re.sub(r"[\"«»]", "", text)
    text = re.sub(r"\b(?:миголо[шщ]и|милогоши)\b", "миголощи", text)
    text = re.sub(r"[^0-9a-zа-я]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return _strip_quarry_material_suffix_key(text)


def _quarry_display_name(value: object) -> str:
    raw = str(value or "").strip()
    stripped = re.sub(r"^\s*карьер\s+", "", raw, flags=re.I).strip()
    stripped = re.sub(r"\s+", " ", stripped)
    key = _quarry_label_key(stripped or raw)
    return QUARRY_CANONICAL_LABELS.get(key, stripped or raw or "—")


def _quarry_source_group_key(value: object) -> Optional[str]:
    key = _quarry_label_key(_quarry_display_name(value))
    return f"quarry:{key}" if key else None


