@lru_cache(maxsize=128)
def _wip_column_exists(table_name: str, column_name: str) -> bool:
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", table_name or ""):
        return False
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", column_name or ""):
        return False
    try:
        row = query_one(
            """
            SELECT EXISTS (
              SELECT 1
              FROM information_schema.columns
              WHERE table_schema = 'public' AND table_name = %s AND column_name = %s
            ) AS exists
            """,
            [table_name, column_name],
        )
    except Exception:
        return False
    return bool(row and row.get("exists"))


@lru_cache(maxsize=128)
def _wip_table_exists(table_name: str) -> bool:
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", table_name or ""):
        return False
    try:
        row = query_one(
            """
            SELECT EXISTS (
              SELECT 1
              FROM information_schema.tables
              WHERE table_schema = 'public' AND table_name = %s
            ) AS exists
            """,
            [table_name],
        )
    except Exception:
        return False
    return bool(row and row.get("exists"))


def _temp_road_display_select(alias: str = "tr") -> str:
    if _wip_column_exists("temporary_roads", "display_in_dashboard"):
        return f"COALESCE({alias}.display_in_dashboard, true) AS display_in_dashboard"
    return "true AS display_in_dashboard"


def _temp_road_display_where(alias: str = "tr") -> str:
    if _wip_column_exists("temporary_roads", "display_in_dashboard"):
        return f"COALESCE({alias}.display_in_dashboard, true) IS TRUE"
    return "TRUE"


def _temp_road_display_enabled(row: dict) -> bool:
    value = row.get("display_in_dashboard")
    if value is None:
        return True
    return bool(value)


def _temp_road_display_lock_reason(code: Optional[str]) -> Optional[str]:
    return None


def _section_num_from_code(code: Optional[str]) -> Optional[int]:
    match = re.match(r"^UCH_(\d+)$", str(code or "").strip())
    return int(match.group(1)) if match else None


