def _expand_sections(section: Optional[str]) -> Optional[list[str]]:
    """'UCH_1,UCH_2' → ['UCH_1','UCH_2'].

    UCH_31/UCH_32 are historical slices of UCH_3. Keep accepting both forms so
    old imported plans/facts are counted together with the current UCH_3 code.
    """
    if not section or section == "all":
        return None
    codes = [c.strip() for c in section.split(",") if c.strip()]
    expanded: list[str] = []
    for code in codes:
        if code == "UCH_3":
            expanded.extend(["UCH_3", "UCH_31", "UCH_32"])
        else:
            expanded.append(code)
    return list(dict.fromkeys(expanded)) or None


def _merge_section(code: Optional[str]) -> Optional[str]:
    """Collapse historical UCH_31/UCH_32 codes into display section UCH_3."""
    if code in ("UCH_31", "UCH_32"):
        return "UCH_3"
    return code


def _pile_control_report_condition(report_alias: str = "dr") -> str:
    return (
        f"(COALESCE({report_alias}.source_type, '') = 'web_pile_control' "
        f"OR COALESCE({report_alias}.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай'])"
    )


def _non_pile_control_report_condition(report_alias: str = "dr") -> str:
    return f"NOT {_pile_control_report_condition(report_alias)}"


def _approved_report_exists(table_alias: str) -> str:
    return (
        f"EXISTS (SELECT 1 FROM daily_reports dr_scope "
        f"WHERE dr_scope.id = {table_alias}.daily_report_id "
        f"AND COALESCE(dr_scope.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review') "
        f"AND {_non_pile_control_report_condition('dr_scope')})"
    )


def _general_shift_report_condition(table_alias: str) -> str:
    """General-report equipment counts come only from section shift reports.

    The owner-approved rule for the Общий/генеральный отчет is to exclude
    Отчет М snapshots from equipment headcounts and dump-truck norm denominators.
    Those snapshots remain valid for dedicated mechanization views, but they must
    not inflate section shift reporting.
    """
    return (
        f"{_non_pile_control_report_condition(table_alias)} "
        f"AND COALESCE({table_alias}.source_type, '') <> 'mechanization_report_m'"
    )


def _general_shift_report_exists(table_alias: str) -> str:
    return (
        f"EXISTS (SELECT 1 FROM daily_reports dr_scope "
        f"WHERE dr_scope.id = {table_alias}.daily_report_id "
        f"AND COALESCE(dr_scope.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review') "
        f"AND {_general_shift_report_condition('dr_scope')})"
    )


MOVEMENT_TYPE_LABELS = {
    "pit_to_constructive": "карьер-конструктив",
    "pit_to_stockpile": "карьер-накопитель",
    "stockpile_to_constructive": "накопитель-конструктив",
    "stockpile_to_stockpile": "накопитель-накопитель",
    "constructive_to_stockpile": "конструктив-накопитель",
    "constructive_to_constructive": "конструктив-конструктив",
}


def _movement_type_label(code: Optional[str]) -> str:
    return MOVEMENT_TYPE_LABELS.get(code or "", code or "не задано")


def _format_pk(v) -> str:
    try:
        n = float(v)
    except (TypeError, ValueError):
        return "ПК н/д"
    pk = int(n // 100)
    plus = int(round(n - pk * 100))
    return f"ПК{pk}+{plus:02d}"


def _short_object_name(row: dict) -> str:
    """Display concrete object, not only generic constructive/object type."""
    field_code = row.get("pile_field_code")
    if field_code:
        return f"Свайное поле {field_code}"
    object_name = row.get("object_name")
    object_type = row.get("object_type_code")
    pk = row.get("pk_min") if row.get("pk_min") is not None else row.get("object_pk")
    if object_type == "PIPE":
        return f"ПБЖТ {_format_pk(pk)}"
    if object_name:
        if object_type in {"OVERPASS", "BRIDGE"} and pk is not None:
            return f"{object_name} {_format_pk(pk)}"
        return str(object_name)
    if row.get("constructive_name"):
        return str(row["constructive_name"])
    return "—"


def _equipment_bucket_by_section_date(
    d_from: date_cls, d_to: date_cls, codes: Optional[list[str]]
) -> dict[tuple, str]:
    """
    Для каждой пары (section_code_merged, report_date) определяем
    контрактор-букет по самосвалам: own → zhds, АЛМАЗ → almaz, иначе → hire.
    Выбираем букет с наибольшим числом единиц; tie-break: own > остальные.
    """
    where = ["dr.report_date BETWEEN %s AND %s",
             "reu.equipment_type IN ('самосвал','dump_truck')",
             "reu.is_demo = false",
             "COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')",
             _non_pile_control_report_condition("dr")]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code, dr.report_date AS d,
               reu.ownership_type, c.short_name, c.kind,
               COUNT(*)::int AS units
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN contractors c ON c.id = reu.contractor_id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, dr.report_date, reu.ownership_type, c.short_name, c.kind
        """,
        params,
    )
    tally: dict[tuple, dict[str, int]] = {}
    for r in rows:
        sec = _merge_section(r["section_code"])
        if not sec:
            continue
        if r["ownership_type"] == "own" or r["kind"] == "own":
            bucket = "zhds"
        elif (r["short_name"] or "").upper() == "АЛМАЗ":
            bucket = "almaz"
        else:
            bucket = "hire"
        key = (sec, r["d"])
        tally.setdefault(key, {"zhds": 0, "almaz": 0, "hire": 0})
        tally[key][bucket] += int(r["units"] or 0)
    # Pick dominant bucket per (section, date). Tie → prefer zhds.
    priority = {"zhds": 0, "almaz": 1, "hire": 2}
    winner: dict[tuple, str] = {}
    for key, counts in tally.items():
        best = sorted(counts.items(), key=lambda x: (-x[1], priority[x[0]]))
        winner[key] = best[0][0]
    return winner


def _parse_range(
    date_from: Optional[str], date_to: Optional[str]
) -> tuple[date_cls, date_cls]:
    if not date_to:
        date_to = (date_cls.today() - timedelta(days=1)).isoformat()
    if not date_from:
        date_from = date_to
    return date_cls.fromisoformat(date_from), date_cls.fromisoformat(date_to)


