@router.put("/settings/announcement")
def save_settings_announcement(body: DashboardAnnouncementBody, _manager=Depends(require_settings_manager)):
    _ensure_settings_tables()
    updated_by = getattr(_manager, 'username', None) or 'web'
    raw = body.model_dump()
    if raw.get("items") is None:
        raw = {
            "items": [{key: raw.get(key) for key in ("id", "enabled", "title", "message", "tone", "target_paths")}],
        }
    payload = _normalize_dashboard_announcements({**raw, "updated_by": updated_by})
    storage_payload = {"items": payload["items"]}
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO equipment_norms_config (category, key, value, updated_at, updated_by)
                    VALUES ('dashboard_announcement', %s, %s, NOW(), %s)
                    ON CONFLICT (category, key) DO UPDATE
                    SET value = EXCLUDED.value,
                        updated_at = NOW(),
                        updated_by = EXCLUDED.updated_by
                    """,
                    (
                        json.dumps({"id": DASHBOARD_ANNOUNCEMENT_CONFIG_ID}),
                        json.dumps(storage_payload, ensure_ascii=False),
                        updated_by,
                    ),
                )
    finally:
        conn.close()
    return {"ok": True, **_load_dashboard_announcement()}


