def _daily_report_email_env_bool(name: str, default: bool = False) -> bool:
    value = os.getenv(name)
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _daily_report_email_max_attachment_bytes(*env_names: str, default_mb: float = 20.0) -> int:
    for name in env_names:
        raw = str(os.getenv(name) or "").strip()
        if not raw:
            continue
        try:
            return int(float(raw.replace(",", ".")) * 1024 * 1024)
        except ValueError:
            continue
    return int(default_mb * 1024 * 1024)


def _daily_report_email_timeout_seconds(*env_names: str, default_seconds: float = 15.0) -> float:
    for name in env_names:
        raw = str(os.getenv(name) or "").strip()
        if not raw:
            continue
        try:
            return max(3.0, min(60.0, float(raw.replace(",", "."))))
        except ValueError:
            continue
    return default_seconds


def _daily_report_email_from_value(raw: str) -> tuple[str, str, str]:
    from_raw = str(raw or "").strip()
    from_name, from_addr = parseaddr(from_raw)
    if (not from_addr or not EMAIL_ADDRESS_RE.fullmatch(from_addr)) and "@" in from_raw:
        name_part, _, addr_part = from_raw.rpartition(" ")
        if "@" in addr_part:
            from_name = name_part.strip()
            from_addr = addr_part.strip()
    if from_addr and not EMAIL_ADDRESS_RE.fullmatch(from_addr):
        return "", "", ""
    from_email = formataddr((from_name, from_addr)) if from_name and from_addr else from_addr
    return from_email, from_addr, from_name


def _daily_report_email_provider_name() -> str:
    provider = str(os.getenv("MAIL_PROVIDER") or "gmail_smtp").strip().lower().replace("-", "_")
    if provider in {"gmail", "smtp", "gmail_smtp"}:
        return "gmail_smtp"
    if provider in {"gmail_api", "google", "google_gmail", "gmail_http"}:
        return "gmail_api"
    if provider in {"resend", "resend_api"}:
        return "resend"
    raise HTTPException(503, "Почтовый транспорт не настроен: MAIL_PROVIDER должен быть gmail_smtp, gmail_api или resend")


def _daily_report_email_gmail_smtp_config() -> dict:
    host = str(os.getenv("GMAIL_SMTP_HOST") or "smtp.gmail.com").strip()
    port_raw = str(os.getenv("GMAIL_SMTP_PORT") or "587").strip()
    try:
        port = int(port_raw)
    except ValueError:
        raise HTTPException(503, "Gmail SMTP не настроен: GMAIL_SMTP_PORT должен быть числом")
    security = str(os.getenv("GMAIL_SMTP_SECURITY") or ("ssl" if port == 465 else "starttls")).strip().lower()
    if security not in {"starttls", "ssl", "none"}:
        raise HTTPException(503, "Gmail SMTP не настроен: GMAIL_SMTP_SECURITY должен быть starttls, ssl или none")
    username = str(os.getenv("GMAIL_SMTP_USERNAME") or "").strip()
    password = re.sub(r"\s+", "", str(os.getenv("GMAIL_SMTP_APP_PASSWORD") or ""))
    from_email, from_addr, _from_name = _daily_report_email_from_value(str(os.getenv("GMAIL_FROM") or username))
    reply_to = str(os.getenv("GMAIL_REPLY_TO") or "").strip()
    missing = [
        key
        for key, value in {
            "GMAIL_SMTP_HOST": host,
            "GMAIL_SMTP_USERNAME": username,
            "GMAIL_SMTP_APP_PASSWORD": password,
            "GMAIL_FROM": from_addr,
        }.items()
        if not value
    ]
    if missing:
        raise HTTPException(503, f"Gmail SMTP не настроен: заполните {', '.join(missing)}")
    return {
        "provider": "gmail_smtp",
        "provider_label": "Gmail SMTP",
        "host": host,
        "port": port,
        "security": security,
        "username": username,
        "password": password,
        "from_email": from_email,
        "from_addr": from_addr,
        "reply_to": reply_to,
        "dry_run": _daily_report_email_env_bool("GMAIL_DRY_RUN", False),
        "max_attachment_bytes": _daily_report_email_max_attachment_bytes("GMAIL_MAX_ATTACHMENT_MB", default_mb=20.0),
        "timeout_seconds": _daily_report_email_timeout_seconds("GMAIL_SMTP_TIMEOUT_SECONDS", default_seconds=15.0),
    }


def _daily_report_email_resend_config() -> dict:
    api_key = str(os.getenv("RESEND_API_KEY") or "").strip()
    from_raw = str(os.getenv("RESEND_FROM") or "VSM Reports <onboarding@resend.dev>").strip()
    from_email, from_addr, _from_name = _daily_report_email_from_value(from_raw)
    reply_to = str(os.getenv("RESEND_REPLY_TO") or os.getenv("GMAIL_REPLY_TO") or "").strip()
    missing = [
        key
        for key, value in {
            "RESEND_API_KEY": api_key,
            "RESEND_FROM": from_addr,
        }.items()
        if not value
    ]
    if missing:
        raise HTTPException(503, f"Resend API не настроен: заполните {', '.join(missing)}")
    return {
        "provider": "resend",
        "provider_label": "Resend API",
        "api_key": api_key,
        "api_url": str(os.getenv("RESEND_API_URL") or "https://api.resend.com/emails").strip(),
        "from_email": from_email,
        "from_addr": from_addr,
        "reply_to": reply_to,
        "dry_run": _daily_report_email_env_bool("RESEND_DRY_RUN", _daily_report_email_env_bool("GMAIL_DRY_RUN", False)),
        "max_attachment_bytes": _daily_report_email_max_attachment_bytes(
            "RESEND_MAX_ATTACHMENT_MB",
            "GMAIL_MAX_ATTACHMENT_MB",
            default_mb=20.0,
        ),
        "timeout_seconds": _daily_report_email_timeout_seconds(
            "RESEND_API_TIMEOUT_SECONDS",
            "GMAIL_SMTP_TIMEOUT_SECONDS",
            default_seconds=20.0,
        ),
    }


def _daily_report_email_gmail_api_config() -> dict:
    client_id = str(os.getenv("GMAIL_API_CLIENT_ID") or "").strip()
    client_secret = str(os.getenv("GMAIL_API_CLIENT_SECRET") or "").strip()
    refresh_token = re.sub(r"\s+", "", str(os.getenv("GMAIL_API_REFRESH_TOKEN") or ""))
    username = str(os.getenv("GMAIL_SMTP_USERNAME") or "").strip()
    from_email, from_addr, _from_name = _daily_report_email_from_value(str(os.getenv("GMAIL_FROM") or username))
    reply_to = str(os.getenv("GMAIL_REPLY_TO") or "").strip()
    missing = [
        key
        for key, value in {
            "GMAIL_API_CLIENT_ID": client_id,
            "GMAIL_API_CLIENT_SECRET": client_secret,
            "GMAIL_API_REFRESH_TOKEN": refresh_token,
            "GMAIL_FROM": from_addr,
        }.items()
        if not value
    ]
    if missing:
        raise HTTPException(503, f"Gmail API не настроен: заполните {', '.join(missing)}")
    return {
        "provider": "gmail_api",
        "provider_label": "Gmail API",
        "client_id": client_id,
        "client_secret": client_secret,
        "refresh_token": refresh_token,
        "token_url": str(os.getenv("GMAIL_API_TOKEN_URL") or "https://oauth2.googleapis.com/token").strip(),
        "send_url": str(os.getenv("GMAIL_API_SEND_URL") or "https://gmail.googleapis.com/gmail/v1/users/me/messages/send").strip(),
        "from_email": from_email,
        "from_addr": from_addr,
        "reply_to": reply_to,
        "dry_run": _daily_report_email_env_bool("GMAIL_DRY_RUN", False),
        "max_attachment_bytes": _daily_report_email_max_attachment_bytes("GMAIL_MAX_ATTACHMENT_MB", default_mb=20.0),
        "timeout_seconds": _daily_report_email_timeout_seconds(
            "GMAIL_API_TIMEOUT_SECONDS",
            "GMAIL_SMTP_TIMEOUT_SECONDS",
            default_seconds=20.0,
        ),
    }


def _daily_report_email_smtp_config() -> dict:
    provider = _daily_report_email_provider_name()
    if provider == "resend":
        return _daily_report_email_resend_config()
    if provider == "gmail_api":
        return _daily_report_email_gmail_api_config()
    return _daily_report_email_gmail_smtp_config()


def _daily_report_email_open_smtp(config: dict):
    context = ssl.create_default_context()
    try:
        if config["security"] == "ssl":
            smtp = smtplib.SMTP_SSL(config["host"], config["port"], timeout=config["timeout_seconds"], context=context)
        else:
            smtp = smtplib.SMTP(config["host"], config["port"], timeout=config["timeout_seconds"])
            smtp.ehlo()
            if config["security"] == "starttls":
                smtp.starttls(context=context)
                smtp.ehlo()
        smtp.login(config["username"], config["password"])
        return smtp
    except smtplib.SMTPAuthenticationError as exc:
        code = getattr(exc, "smtp_code", None)
        raise HTTPException(
            502,
            f"Не удалось войти в Gmail SMTP: логин или пароль приложения не приняты"
            f"{f' (код SMTP {code})' if code else ''}",
        ) from exc
    except OSError as exc:
        detail = str(exc).strip() or exc.__class__.__name__
        hint = ""
        if isinstance(exc, TimeoutError) or "timed out" in detail.lower():
            hint = " Проверьте, не заблокированы ли исходящие SMTP-порты 465/587 у сервера."
        elif getattr(exc, "errno", None) in {101, 113, 111}:
            hint = " Проверьте сетевой маршрут и исходящие SMTP-порты 465/587 у сервера."
        raise HTTPException(
            502,
            f"Не удалось подключиться к Gmail SMTP ({config['host']}:{config['port']}): {detail}.{hint}",
        ) from exc
    except smtplib.SMTPException as exc:
        detail = str(exc).strip() or exc.__class__.__name__
        raise HTTPException(502, f"Не удалось подключиться к Gmail SMTP: {detail}") from exc


def _daily_report_email_effective_report_period(file_key: str, config: dict, send_date: date_cls) -> tuple[date_cls, date_cls]:
    spec = GENERATOR_PIPELINE_REPORTS.get(file_key) or {}
    is_range_report = spec.get("period_mode") == "range"
    if str(config.get("date_mode") or "") == "custom" and config.get("date"):
        d_to = date_cls.fromisoformat(str(config["date"])[:10])
        if is_range_report and config.get("date_from"):
            d_from = date_cls.fromisoformat(str(config["date_from"])[:10])
        else:
            d_from = d_to
    else:
        d_to = send_date - timedelta(days=1)
        d_from = _daily_report_email_default_range_start(d_to) if is_range_report else d_to
    if d_from > d_to:
        raise HTTPException(400, f"Период файла {file_key}: дата начала должна быть не позже даты окончания")
    return d_from, d_to


def _daily_report_email_system_attachment(file_key: str, send_date: date_cls) -> dict:
    if file_key == DAILY_REPORT_TEMPLATE_ATTACHMENT_KEY:
        content = _generate_daily_report_template_xlsx()
        return {
            "key": file_key,
            "label": "Excel-шаблон для заполнения",
            "filename_ascii": f"daily_report_template_{send_date.isoformat()}.xlsx",
            "filename_utf8": f"Excel-шаблон сменного отчета актуален на {send_date.isoformat()}.xlsx",
            "media_type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "content": content,
            "size_bytes": len(content),
            "report_date": send_date.isoformat(),
        }
    if file_key == DAILY_REPORT_WORD_INSTRUCTION_ATTACHMENT_KEY:
        path = _daily_report_word_instruction_path()
        if not path.exists():
            raise HTTPException(404, f"Word-инструкция не найдена: {path}")
        content = path.read_bytes()
        return {
            "key": file_key,
            "label": "Word-инструкция по проверке отчета",
            "filename_ascii": "daily_report_review_instruction.docx",
            "filename_utf8": DAILY_REPORT_WORD_INSTRUCTION_FILENAME,
            "media_type": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "content": content,
            "size_bytes": len(content),
            "report_date": None,
        }
    raise HTTPException(400, f"Unknown system attachment: {file_key}")


def _daily_report_email_generator_attachment(file_key: str, config: dict, send_date: date_cls) -> dict:
    context = _daily_report_email_generator_context(file_key, config, send_date)
    d_from = context["d_from"]
    d_to = context["d_to"]
    filter_env = context["filter_env"]
    cumulative_mode = bool(context["cumulative_as_of_end_date"])
    cache_hit = False
    cache_mode = None
    cache_created_at = None
    if file_key in BACKGROUND_XLSX_PIPELINE_REPORT_KEYS:
        info = _xlsx_pipeline_job_info(
            file_key,
            d_from,
            d_to,
            filter_env=filter_env,
            section_codes=None,
            general_equipment_plan_counts=None,
            cumulative_as_of_end_date=cumulative_mode,
        )
        artifact = Path(str(info["artifact"]))
        meta_path = Path(str(info["meta_path"]))
        cache_hit = _cached_xlsx_ready(artifact, meta_path, str(info["fingerprint"]))
        if cache_hit:
            cache_mode = "strict"
        elif config.get("use_cache"):
            cached = _latest_cached_xlsx_artifact(
                report_key=file_key,
                d_from=date_cls.fromisoformat(str(info["date_from"])),
                d_to=date_cls.fromisoformat(str(info["date_to"])),
            )
            if cached:
                artifact = Path(str(cached["artifact"]))
                cache_hit = True
                cache_mode = str(cached.get("cache_mode") or "latest")
                cache_created_at = cached.get("cache_created_at")
        if not cache_hit:
            artifact = _ensure_xlsx_export_job_artifact(info)
        content = artifact.read_bytes()
        filename_ascii = str(info.get("filename_ascii") or artifact.name)
        filename_utf8 = str(info.get("filename_utf8") or filename_ascii)
        media_type = str(info.get("media_type") or XLSX_MEDIA_TYPE)
    elif file_key in BACKGROUND_PDF_PIPELINE_REPORT_KEYS:
        info = _pdf_pipeline_job_info(
            file_key,
            d_from,
            d_to,
            filter_env=filter_env,
            section_codes=None,
        )
        artifact = Path(str(info["artifact"]))
        meta_path = Path(str(info["meta_path"]))
        cache_hit = _cached_pdf_ready(artifact, meta_path, str(info["fingerprint"]))
        if cache_hit:
            cache_mode = "strict"
        elif config.get("use_cache"):
            cached = _latest_cached_pdf_artifact(
                report_key=file_key,
                d_from=date_cls.fromisoformat(str(info["date_from"])),
                d_to=date_cls.fromisoformat(str(info["date_to"])),
                section_codes=list(info.get("section_codes") or []),
            )
            if cached:
                artifact = Path(str(cached["artifact"]))
                cache_hit = True
                cache_mode = str(cached.get("cache_mode") or "latest")
                cache_created_at = cached.get("cache_created_at")
        if not cache_hit:
            artifact = _ensure_pdf_export_job_artifact(info)
        content = artifact.read_bytes()
        filename_ascii = str(info.get("filename_ascii") or artifact.name)
        filename_utf8 = str(info.get("filename_utf8") or filename_ascii)
        media_type = str(info.get("media_type") or PDF_MEDIA_TYPE)
    else:
        content, filename_ascii, filename_utf8, media_type = _generate_generator_pipeline_content(
            file_key,
            d_from,
            d_to,
            section_codes=None,
            filter_env=filter_env,
            cumulative_as_of_end_date=cumulative_mode,
            general_equipment_plan_counts=None,
        )
    spec = GENERATOR_PIPELINE_REPORTS.get(file_key) or {}
    return {
        "key": file_key,
        "label": str(spec.get("label") or file_key),
        "filename_ascii": filename_ascii,
        "filename_utf8": filename_utf8,
        "media_type": media_type,
        "content": content,
        "size_bytes": len(content),
        "report_date": d_to.isoformat(),
        "report_date_from": d_from.isoformat(),
        "cumulative_as_of_end_date": cumulative_mode,
        "from_cache": cache_hit,
        "cache_mode": cache_mode,
        "cache_created_at": cache_created_at,
    }


def _daily_report_email_attachment(file_key: str, config: dict, send_date: date_cls) -> dict:
    if file_key in {DAILY_REPORT_TEMPLATE_ATTACHMENT_KEY, DAILY_REPORT_WORD_INSTRUCTION_ATTACHMENT_KEY}:
        return _daily_report_email_system_attachment(file_key, send_date)
    return _daily_report_email_generator_attachment(file_key, config, send_date)


def _daily_report_email_safe_attachment(attachment: dict) -> dict:
    return {
        "key": attachment.get("key"),
        "label": attachment.get("label"),
        "filename": attachment.get("filename_utf8") or attachment.get("filename_ascii"),
        "size_bytes": attachment.get("size_bytes"),
        "report_date": attachment.get("report_date"),
        "report_date_from": attachment.get("report_date_from"),
        "cumulative_as_of_end_date": attachment.get("cumulative_as_of_end_date"),
        "from_cache": bool(attachment.get("from_cache")),
        "cache_mode": attachment.get("cache_mode"),
        "cache_created_at": attachment.get("cache_created_at"),
    }


def _daily_report_email_display_date(value: object) -> str:
    text = str(value or "").strip()[:10]
    if not text:
        return ""
    try:
        return date_cls.fromisoformat(text).strftime("%d.%m.%Y")
    except ValueError:
        return text


def _daily_report_email_attachment_text_suffix(attachment: dict) -> str:
    key = str(attachment.get("key") or "")
    report_date = attachment.get("report_date")
    report_date_from = attachment.get("report_date_from")
    parts: list[str] = []
    if key == DAILY_REPORT_TEMPLATE_ATTACHMENT_KEY and report_date:
        parts.append(f"актуален на {_daily_report_email_display_date(report_date)}")
    elif report_date:
        report_date_text = _daily_report_email_display_date(report_date)
        if report_date_from and report_date_from != report_date:
            parts.append(f"период {_daily_report_email_display_date(report_date_from)} - {report_date_text}")
        else:
            totals_label = "накопительные итоги" if attachment.get("cumulative_as_of_end_date") else "итоги"
            parts.append(f"{totals_label} на {report_date_text}")
        if report_date_from and report_date_from != report_date:
            totals_label = "накопительные итоги" if attachment.get("cumulative_as_of_end_date") else "итоги"
            parts.append(f"{totals_label} на {report_date_text}")
    elif key == DAILY_REPORT_WORD_INSTRUCTION_ATTACHMENT_KEY:
        parts.append("без даты")
    return f" — {', '.join(parts)}" if parts else ""


def _daily_report_email_message(
    *,
    config: dict,
    group: dict,
    attachments: list[dict],
    send_date: date_cls,
) -> tuple[EmailMessage, list[str]]:
    recipients = list(group.get("recipients") or [])
    cc = list(group.get("cc") or [])
    all_recipients = recipients + cc
    subject_prefix = str(group.get("subject_prefix") or DAILY_REPORT_EMAIL_DEFAULT_SUBJECT_PREFIX).strip()
    subject = f"{subject_prefix} · {group.get('name') or 'Группа'} · {send_date.isoformat()}"
    msg = EmailMessage()
    msg["Subject"] = subject
    msg["From"] = config["from_email"]
    msg["To"] = ", ".join(recipients)
    if cc:
        msg["Cc"] = ", ".join(cc)
    if config.get("reply_to"):
        msg["Reply-To"] = config["reply_to"]
    lines = [
        "Добрый день!",
        "",
        "Во вложении файлы ежедневной рассылки служебной отчетности:",
    ]
    if attachments:
        for attachment in attachments:
            lines.append(
                f"- {attachment.get('label') or attachment.get('key')}"
                f"{_daily_report_email_attachment_text_suffix(attachment)}"
            )
    else:
        lines.append("- файлы не выбраны")
    msg.set_content("\n".join(lines))
    for attachment in attachments:
        filename = str(attachment.get("filename_utf8") or attachment.get("filename_ascii") or "report.bin")
        media_type = str(attachment.get("media_type") or mimetypes.guess_type(filename)[0] or "application/octet-stream")
        maintype, subtype = (media_type.split("/", 1) + ["octet-stream"])[:2] if "/" in media_type else ("application", "octet-stream")
        msg.add_attachment(
            attachment["content"],
            maintype=maintype,
            subtype=subtype,
            filename=filename,
        )
    return msg, all_recipients


def _daily_report_email_http_error_message(exc: urllib.error.HTTPError) -> str:
    body = exc.read().decode("utf-8", errors="replace").strip()
    if body:
        try:
            payload = json.loads(body)
            error_value = payload.get("error")
            if isinstance(error_value, dict):
                message = str(error_value.get("message") or error_value.get("status") or body).strip()
            else:
                message = str(payload.get("message") or error_value or body).strip()
        except Exception:
            message = body
    else:
        message = exc.reason or exc.__class__.__name__
    return f"HTTP {exc.code}: {message[:500]}"


def _daily_report_email_send_resend_message(
    *,
    config: dict,
    msg: EmailMessage,
    recipients: list[str],
    cc: list[str],
    attachments: list[dict],
) -> str:
    body_part = msg.get_body(preferencelist=("plain",))
    body_text = body_part.get_content() if body_part is not None else ""
    payload: dict[str, Any] = {
        "from": config["from_email"],
        "to": recipients,
        "subject": str(msg["Subject"] or ""),
        "text": body_text,
    }
    if cc:
        payload["cc"] = cc
    if config.get("reply_to"):
        payload["reply_to"] = [config["reply_to"]]
    if attachments:
        payload["attachments"] = [
            {
                "filename": str(attachment.get("filename_utf8") or attachment.get("filename_ascii") or "report.bin"),
                "content": base64.b64encode(attachment["content"]).decode("ascii"),
            }
            for attachment in attachments
        ]

    request = urllib.request.Request(
        config["api_url"],
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={
            "Authorization": f"Bearer {config['api_key']}",
            "Content-Type": "application/json",
            "User-Agent": "vsm-dashboard/1.0",
            "Idempotency-Key": str(uuid.uuid4()),
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=config["timeout_seconds"]) as response:
            response_payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        raise HTTPException(502, f"Не удалось отправить письмо через Resend API: {_daily_report_email_http_error_message(exc)}") from exc
    except OSError as exc:
        detail = str(exc).strip() or exc.__class__.__name__
        raise HTTPException(502, f"Не удалось подключиться к Resend API: {detail}") from exc
    message_id = str(response_payload.get("id") or "").strip()
    if not message_id:
        raise HTTPException(502, "Resend API не вернул id отправленного письма")
    return message_id


def _daily_report_email_gmail_api_access_token(config: dict) -> str:
    payload = urllib.parse.urlencode(
        {
            "client_id": config["client_id"],
            "client_secret": config["client_secret"],
            "refresh_token": config["refresh_token"],
            "grant_type": "refresh_token",
        }
    ).encode("utf-8")
    request = urllib.request.Request(
        config["token_url"],
        data=payload,
        method="POST",
        headers={
            "Content-Type": "application/x-www-form-urlencoded",
            "User-Agent": "vsm-dashboard/1.0",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=config["timeout_seconds"]) as response:
            response_payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        raise HTTPException(502, f"Не удалось обновить токен Gmail API: {_daily_report_email_http_error_message(exc)}") from exc
    except OSError as exc:
        detail = str(exc).strip() or exc.__class__.__name__
        raise HTTPException(502, f"Не удалось подключиться к OAuth Google: {detail}") from exc
    access_token = str(response_payload.get("access_token") or "").strip()
    if not access_token:
        raise HTTPException(502, "OAuth Google не вернул access_token")
    return access_token


def _daily_report_email_send_gmail_api_message(*, config: dict, msg: EmailMessage) -> str:
    access_token = _daily_report_email_gmail_api_access_token(config)
    payload = {
        "raw": base64.urlsafe_b64encode(msg.as_bytes()).decode("ascii"),
    }
    request = urllib.request.Request(
        config["send_url"],
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        method="POST",
        headers={
            "Authorization": f"Bearer {access_token}",
            "Content-Type": "application/json",
            "User-Agent": "vsm-dashboard/1.0",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=config["timeout_seconds"]) as response:
            response_payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        raise HTTPException(502, f"Не удалось отправить письмо через Gmail API: {_daily_report_email_http_error_message(exc)}") from exc
    except OSError as exc:
        detail = str(exc).strip() or exc.__class__.__name__
        raise HTTPException(502, f"Не удалось подключиться к Gmail API: {detail}") from exc
    message_id = str(response_payload.get("id") or "").strip()
    if not message_id:
        raise HTTPException(502, "Gmail API не вернул id отправленного письма")
    return message_id


def _daily_report_email_deliver_group(
    *,
    smtp,
    config: dict,
    group: dict,
    attachments: list[dict],
    send_date: date_cls,
) -> dict:
    total_bytes = sum(int(attachment.get("size_bytes") or 0) for attachment in attachments)
    if total_bytes > int(config.get("max_attachment_bytes") or 0):
        raise HTTPException(
            413,
            f"Вложения для группы «{group.get('name') or group.get('id')}» больше лимита {config.get('provider_label') or 'почтового сервиса'}",
        )
    msg, all_recipients = _daily_report_email_message(
        config=config,
        group=group,
        attachments=attachments,
        send_date=send_date,
    )
    if not config.get("dry_run"):
        try:
            if config.get("provider") == "resend":
                message_id = _daily_report_email_send_resend_message(
                    config=config,
                    msg=msg,
                    recipients=list(group.get("recipients") or []),
                    cc=list(group.get("cc") or []),
                    attachments=attachments,
                )
            elif config.get("provider") == "gmail_api":
                message_id = _daily_report_email_send_gmail_api_message(config=config, msg=msg)
            else:
                smtp.send_message(msg, from_addr=config["from_addr"], to_addrs=all_recipients)
                message_id = ""
        except (OSError, smtplib.SMTPException) as exc:
            raise HTTPException(502, f"Не удалось отправить письмо через Gmail SMTP: {exc.__class__.__name__}") from exc
        except HTTPException:
            raise
    return {
        "id": group.get("id"),
        "name": group.get("name"),
        "recipient_count": len(group.get("recipients") or []),
        "cc_count": len(group.get("cc") or []),
        "attachment_count": len(attachments),
        "attachment_bytes": total_bytes,
        "sent": not config.get("dry_run"),
        "message_id": message_id if not config.get("dry_run") else "",
    }


def _daily_report_email_file_label(file_key: str) -> str:
    for option in _daily_report_email_file_options():
        if option.get("key") == file_key:
            return str(option.get("label") or file_key)
    return str(GENERATOR_PIPELINE_REPORTS.get(file_key, {}).get("label") or file_key)


def _daily_report_email_generator_context(file_key: str, report_config: dict, send_date: date_cls) -> dict:
    d_from, d_to = _daily_report_email_effective_report_period(file_key, report_config, send_date)
    cumulative_mode = bool(
        file_key in CUMULATIVE_AS_OF_END_DATE_XLSX_REPORT_KEYS
        and report_config.get("cumulative_as_of_end_date") is not False
    )
    filter_env = _report_parameters_env(
        file_key,
        cumulative_as_of_end_date_override=cumulative_mode if file_key in CUMULATIVE_AS_OF_END_DATE_XLSX_REPORT_KEYS else None,
    )
    return {
        "d_from": d_from,
        "d_to": d_to,
        "filter_env": filter_env,
        "cumulative_as_of_end_date": cumulative_mode,
    }


def _daily_report_email_attachment_estimate_seconds(file_key: str, report_config: dict, send_date: date_cls) -> int:
    if file_key in {DAILY_REPORT_TEMPLATE_ATTACHMENT_KEY, DAILY_REPORT_WORD_INSTRUCTION_ATTACHMENT_KEY}:
        return 8
    try:
        context = _daily_report_email_generator_context(file_key, report_config, send_date)
    except Exception:
        return int(PIPELINE_ESTIMATE_FALLBACK_SECONDS.get(file_key, 120))
    d_from = context["d_from"]
    d_to = context["d_to"]
    cumulative_mode = bool(context["cumulative_as_of_end_date"])
    if file_key in BACKGROUND_XLSX_PIPELINE_REPORT_KEYS:
        try:
            info = _xlsx_pipeline_job_info(
                file_key,
                d_from,
                d_to,
                filter_env=context["filter_env"],
                section_codes=None,
                general_equipment_plan_counts=None,
                cumulative_as_of_end_date=cumulative_mode,
            )
            if _cached_xlsx_ready(Path(str(info["artifact"])), Path(str(info["meta_path"])), str(info["fingerprint"])):
                return 2
            if report_config.get("use_cache") and _latest_cached_xlsx_artifact(
                report_key=file_key,
                d_from=date_cls.fromisoformat(str(info["date_from"])),
                d_to=date_cls.fromisoformat(str(info["date_to"])),
            ):
                return 2
        except Exception:
            return int(PIPELINE_ESTIMATE_FALLBACK_SECONDS.get(file_key, 120))
    if file_key in BACKGROUND_PDF_PIPELINE_REPORT_KEYS:
        try:
            info = _pdf_pipeline_job_info(
                file_key,
                d_from,
                d_to,
                filter_env=context["filter_env"],
                section_codes=None,
            )
            if _cached_pdf_ready(Path(str(info["artifact"])), Path(str(info["meta_path"])), str(info["fingerprint"])):
                return 2
            if report_config.get("use_cache") and _latest_cached_pdf_artifact(
                report_key=file_key,
                d_from=date_cls.fromisoformat(str(info["date_from"])),
                d_to=date_cls.fromisoformat(str(info["date_to"])),
                section_codes=list(info.get("section_codes") or []),
            ):
                return 2
        except Exception:
            return int(PIPELINE_ESTIMATE_FALLBACK_SECONDS.get(file_key, 120))
    effective_from, effective_to = _xlsx_effective_period_for_cumulative_as_of(file_key, d_from, d_to, cumulative_mode)
    return _estimate_pipeline_runtime_seconds(file_key, effective_from, effective_to)


def _daily_report_email_status_response(status: Optional[dict] = None) -> dict:
    status = dict(status or DAILY_REPORT_EMAIL_SEND_STATUS or {})
    if not status:
        return {"status": "idle", "running": False}
    progress = _progress_snapshot(
        status=str(status.get("status") or "idle"),
        started_at=status.get("started_at"),
        finished_at=status.get("finished_at"),
        estimated_total_seconds=status.get("total_estimated_seconds"),
        completed_estimated_seconds=float(status.get("completed_estimated_seconds") or 0),
        current_step_started_at=status.get("current_step_started_at"),
        current_step_estimated_seconds=status.get("current_step_estimated_seconds"),
    )
    return {
        **status,
        **progress,
        "running": str(status.get("status") or "") == "running",
    }


def _daily_report_email_update_status(**patch) -> dict:
    now = datetime.now(timezone.utc).isoformat()
    with DAILY_REPORT_EMAIL_SEND_STATUS_LOCK:
        current = dict(DAILY_REPORT_EMAIL_SEND_STATUS)
        current.update(patch)
        current["updated_at"] = now
        DAILY_REPORT_EMAIL_SEND_STATUS.clear()
        DAILY_REPORT_EMAIL_SEND_STATUS.update(current)
        return _daily_report_email_status_response(current)


def _daily_report_email_start_step(
    *,
    stage: str,
    stage_label: str,
    message: str,
    completed_estimated_seconds: float,
    current_step_estimated_seconds: float,
    completed_steps: int,
    total_steps: int,
    current_file_key: Optional[str] = None,
    current_file_label: Optional[str] = None,
    current_group_id: Optional[str] = None,
    current_group_name: Optional[str] = None,
) -> dict:
    return _daily_report_email_update_status(
        status="running",
        stage=stage,
        stage_label=stage_label,
        message=message,
        completed_estimated_seconds=completed_estimated_seconds,
        current_step_estimated_seconds=current_step_estimated_seconds,
        current_step_started_at=datetime.now(timezone.utc).isoformat(),
        completed_steps=completed_steps,
        total_steps=total_steps,
        current_file_key=current_file_key,
        current_file_label=current_file_label,
        current_group_id=current_group_id,
        current_group_name=current_group_name,
    )


@router.get("/settings/daily-report-email/send-status")
def get_settings_daily_report_email_send_status(_manager=Depends(require_settings_manager)):
    with DAILY_REPORT_EMAIL_SEND_STATUS_LOCK:
        status = dict(DAILY_REPORT_EMAIL_SEND_STATUS)
    return _daily_report_email_status_response(status)


def _daily_report_email_attachment_cache_key(file_key: str, report_config: dict, send_date: date_cls) -> str:
    return json.dumps(
        {
            "file_key": file_key,
            "report_config": report_config,
            "send_date": send_date.isoformat(),
        },
        ensure_ascii=False,
        sort_keys=True,
    )


def _daily_report_email_send_plan(active_groups: list[dict], config: dict, send_date: date_cls) -> dict:
    attachment_estimates: dict[str, float] = {}
    unique_attachment_count = 0
    for group in active_groups:
        for file_key in group.get("report_keys") or []:
            report_config = (group.get("report_configs") or {}).get(file_key) or _daily_report_email_default_report_config()
            cache_key = _daily_report_email_attachment_cache_key(file_key, report_config, send_date)
            if cache_key not in attachment_estimates:
                attachment_estimates[cache_key] = float(_daily_report_email_attachment_estimate_seconds(file_key, report_config, send_date))
                unique_attachment_count += 1
    needs_connection_step = bool(config.get("provider") == "gmail_smtp" and not config.get("dry_run"))
    smtp_estimate = 10.0 if needs_connection_step else 0.0
    delivery_estimate = max(1, len(active_groups)) * 8.0
    total_estimated_seconds = max(1.0, sum(attachment_estimates.values()) + smtp_estimate + delivery_estimate)
    total_steps = unique_attachment_count + (1 if needs_connection_step else 0) + len(active_groups)
    return {
        "attachment_estimates": attachment_estimates,
        "smtp_estimate": smtp_estimate,
        "needs_connection_step": needs_connection_step,
        "total_estimated_seconds": total_estimated_seconds,
        "total_steps": max(1, total_steps),
    }


def _daily_report_email_run_locked(
    *,
    send_id: str,
    active_groups: list[dict],
    config: dict,
    send_date: date_cls,
    plan: dict,
) -> None:
    smtp = None
    generated_files: list[dict] = []
    groups_result: list[dict] = []
    attachment_estimates = dict(plan.get("attachment_estimates") or {})
    smtp_estimate = float(plan.get("smtp_estimate") if plan.get("smtp_estimate") is not None else 1.0)
    needs_connection_step = bool(plan.get("needs_connection_step"))
    total_estimated_seconds = float(plan.get("total_estimated_seconds") or 1.0)
    total_steps = int(plan.get("total_steps") or 1)
    completed_estimated_seconds = 0.0
    completed_steps = 0
    try:
        attachment_cache: dict[str, dict] = {}
        group_attachments: dict[str, list[dict]] = {}
        for group in active_groups:
            attachments: list[dict] = []
            for file_key in group.get("report_keys") or []:
                report_config = (group.get("report_configs") or {}).get(file_key) or _daily_report_email_default_report_config()
                cache_key = _daily_report_email_attachment_cache_key(file_key, report_config, send_date)
                if cache_key not in attachment_cache:
                    file_label = _daily_report_email_file_label(file_key)
                    current_estimate = attachment_estimates.get(cache_key, float(_daily_report_email_attachment_estimate_seconds(file_key, report_config, send_date)))
                    _daily_report_email_start_step(
                        stage="generate_attachment",
                        stage_label="Генерация вложения",
                        message=f"Генерируется вложение: {file_label}",
                        completed_estimated_seconds=completed_estimated_seconds,
                        current_step_estimated_seconds=current_estimate,
                        completed_steps=completed_steps,
                        total_steps=total_steps,
                        current_file_key=file_key,
                        current_file_label=file_label,
                    )
                    attachment = _daily_report_email_attachment(file_key, report_config, send_date)
                    attachment_cache[cache_key] = attachment
                    safe_attachment = _daily_report_email_safe_attachment(attachment)
                    generated_files.append(safe_attachment)
                    completed_estimated_seconds += current_estimate
                    completed_steps += 1
                    ready_message = (
                        f"Вложение взято из кеша: {file_label}"
                        if attachment.get("from_cache")
                        else f"Вложение готово: {file_label}"
                    )
                    _daily_report_email_update_status(
                        message=ready_message,
                        generated_files=generated_files,
                        completed_estimated_seconds=completed_estimated_seconds,
                        completed_steps=completed_steps,
                    )
                attachments.append(attachment_cache[cache_key])
            group_attachments[str(group.get("id") or "")] = attachments

        for group in active_groups:
            total_bytes = sum(
                int(attachment.get("size_bytes") or 0)
                for attachment in group_attachments.get(str(group.get("id") or ""), [])
            )
            if total_bytes > int(config.get("max_attachment_bytes") or 0):
                raise HTTPException(
                    413,
                    f"Вложения для группы «{group.get('name') or group.get('id')}» больше лимита {config.get('provider_label') or 'почтового сервиса'}",
                )

        if needs_connection_step:
            _daily_report_email_start_step(
                stage="smtp_connect",
                stage_label="Подключение к SMTP",
                message=f"Подключаюсь к почтовому серверу: {config.get('provider_label') or 'SMTP'}",
                completed_estimated_seconds=completed_estimated_seconds,
                current_step_estimated_seconds=smtp_estimate,
                completed_steps=completed_steps,
                total_steps=total_steps,
            )
            smtp = _daily_report_email_open_smtp(config)
            completed_estimated_seconds += smtp_estimate
            completed_steps += 1
            _daily_report_email_update_status(
                completed_estimated_seconds=completed_estimated_seconds,
                completed_steps=completed_steps,
            )
        groups_result = []
        for group in active_groups:
            group_estimate = 8.0
            _daily_report_email_start_step(
                stage="send_group",
                stage_label="Отправка письма",
                message=f"Отправляется письмо для группы: {group.get('name') or group.get('id')}",
                completed_estimated_seconds=completed_estimated_seconds,
                current_step_estimated_seconds=group_estimate,
                completed_steps=completed_steps,
                total_steps=total_steps,
                current_group_id=str(group.get("id") or ""),
                current_group_name=str(group.get("name") or ""),
            )
            result = _daily_report_email_deliver_group(
                smtp=smtp,
                config=config,
                group=group,
                attachments=group_attachments.get(str(group.get("id") or ""), []),
                send_date=send_date,
            )
            groups_result.append(result)
            completed_estimated_seconds += group_estimate
            completed_steps += 1
            _daily_report_email_update_status(
                groups=groups_result,
                completed_estimated_seconds=completed_estimated_seconds,
                completed_steps=completed_steps,
            )
    except Exception as exc:
        _daily_report_email_update_status(
            status="error",
            stage="error",
            stage_label="Ошибка рассылки",
            message=str(getattr(exc, "detail", None) or exc),
            error=str(getattr(exc, "detail", None) or exc),
            finished_at=datetime.now(timezone.utc).isoformat(),
            generated_files=generated_files,
            groups=groups_result,
        )
        return
    finally:
        try:
            if smtp is not None:
                smtp.quit()
        finally:
            DAILY_REPORT_EMAIL_SEND_LOCK.release()

    _daily_report_email_update_status(
        status="success",
        stage="done",
        stage_label="Рассылка завершена",
        message="Письма отправлены" if not config.get("dry_run") else "Тестовая рассылка завершена без SMTP-отправки",
        completed_estimated_seconds=total_estimated_seconds,
        completed_steps=total_steps,
        current_step_estimated_seconds=0,
        finished_at=datetime.now(timezone.utc).isoformat(),
        generated_files=generated_files,
        groups=groups_result,
    )


@router.post("/settings/daily-report-email/send")
def send_settings_daily_report_email(body: DailyReportEmailSettingsBody, _manager=Depends(require_settings_manager)):
    raw = body.model_dump()
    raw["enabled"] = True
    payload = _normalize_daily_report_email_settings(raw, require_recipients_when_enabled=True)
    active_groups = [group for group in payload["groups"] if group.get("enabled")]
    config = _daily_report_email_smtp_config()
    send_date = datetime.now(timezone.utc).date()
    plan = _daily_report_email_send_plan(active_groups, config, send_date)
    if not DAILY_REPORT_EMAIL_SEND_LOCK.acquire(blocking=False):
        raise HTTPException(409, "Рассылка уже выполняется. Дождитесь завершения текущего запуска.")

    send_id = uuid.uuid4().hex[:12]
    initial_status = _daily_report_email_update_status(
        send_id=send_id,
        status="running",
        stage="queued",
        stage_label="Подготовка рассылки",
        message="Рассылка запущена в фоне, готовлю список вложений",
        started_at=datetime.now(timezone.utc).isoformat(),
        finished_at=None,
        total_steps=plan["total_steps"],
        completed_steps=0,
        total_estimated_seconds=plan["total_estimated_seconds"],
        completed_estimated_seconds=0.0,
        current_step_estimated_seconds=1.0,
        current_step_started_at=datetime.now(timezone.utc).isoformat(),
        generated_files=[],
        groups=[],
        dry_run=bool(config.get("dry_run")),
        error=None,
    )
    try:
        thread = threading.Thread(
            target=_daily_report_email_run_locked,
            kwargs={
                "send_id": send_id,
                "active_groups": active_groups,
                "config": config,
                "send_date": send_date,
                "plan": plan,
            },
            daemon=True,
            name=f"daily-report-email-{send_id}",
        )
        thread.start()
    except Exception as exc:
        DAILY_REPORT_EMAIL_SEND_LOCK.release()
        _daily_report_email_update_status(
            status="error",
            stage="error",
            stage_label="Ошибка запуска рассылки",
            message=str(exc),
            error=str(exc),
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        raise HTTPException(500, f"Не удалось запустить фоновую рассылку: {exc}") from exc

    return {
        "ok": True,
        "queued": True,
        "send_id": send_id,
        "dry_run": bool(config.get("dry_run")),
        "send_date": send_date.isoformat(),
        "status": initial_status,
    }


ISSO_SUPPORT_REPORT_CONFIG_KEY = "generator.isso_support_report.overrides.v1"
ISSO_SUPPORT_REPORT_RD_STATUSES = {"available", "missing", "unknown"}


class IssoSupportReportOverrideRowBody(BaseModel):
    row_key: Optional[str] = None
    plan_id: Optional[str] = None
    object_code: str = ""
    plan_month: Optional[str] = None
    support_range_text: str = ""
    rd_status: str = "unknown"
    remark: str = ""
    section_code: Optional[str] = None
    section_name: Optional[str] = None
    source_name: Optional[str] = None
    object_name: Optional[str] = None
    pk_text: Optional[str] = None


class IssoSupportReportSettingsBody(BaseModel):
    month: Optional[str] = None
    months: Optional[list[str]] = None
    rows: list[IssoSupportReportOverrideRowBody] = []


def _isso_support_report_parse_month(value: Optional[str], *, field_name: str = "month") -> Optional[date_cls]:
    text = str(value or "").strip()
    if not text:
        return None
    if re.fullmatch(r"\d{4}-\d{2}", text):
        text = f"{text}-01"
    try:
        return date_cls.fromisoformat(text[:10]).replace(day=1)
    except ValueError as exc:
        raise HTTPException(400, f"Invalid {field_name}: expected YYYY-MM or YYYY-MM-01") from exc


def _isso_support_report_clean_text(value: object, *, limit: int = 4000, keep_newlines: bool = False) -> str:
    text = str(value or "").replace("\xa0", " ").replace("\r", "").strip()
    if not keep_newlines:
        text = re.sub(r"\s+", " ", text)
    return text[:limit]


def _isso_support_report_normalize_range(value: object) -> str:
    text = _isso_support_report_clean_text(value, limit=400, keep_newlines=False)
    text = text.replace("—", "-").replace("–", "-").replace("−", "-")
    return re.sub(r"\s*-\s*", "-", text)


def _isso_support_report_normalize_status(value: object) -> str:
    text = _isso_support_report_clean_text(value, limit=40, keep_newlines=False).lower()
    if text in {"available", "есть", "rd_available"}:
        return "available"
    if text in {"missing", "нет", "no_rd"}:
        return "missing"
    return "unknown"


def _isso_support_report_row_key(plan_id: Optional[str], object_code: Optional[str], plan_month: str) -> str:
    plan_id_text = _isso_support_report_clean_text(plan_id, limit=120)
    if plan_id_text:
        return f"plan:{plan_id_text}"
    object_code_text = _isso_support_report_clean_text(object_code, limit=160)
    return f"object:{object_code_text}:{plan_month}"


def _normalize_isso_support_report_override_row(raw: object, *, month_hint: Optional[date_cls] = None) -> Optional[dict]:
    if not isinstance(raw, dict):
        return None
    plan_month = _isso_support_report_parse_month(raw.get("plan_month"), field_name="plan_month") or month_hint
    if plan_month is None:
        return None
    plan_month_iso = plan_month.isoformat()
    plan_id = _isso_support_report_clean_text(raw.get("plan_id"), limit=120)
    object_code = _isso_support_report_clean_text(raw.get("object_code"), limit=160)
    if not plan_id and not object_code:
        return None
    row = {
        "row_key": _isso_support_report_row_key(plan_id, object_code, plan_month_iso),
        "plan_id": plan_id,
        "object_code": object_code,
        "plan_month": plan_month_iso,
        "support_range_text": _isso_support_report_normalize_range(raw.get("support_range_text")),
        "rd_status": _isso_support_report_normalize_status(raw.get("rd_status")),
        "remark": _isso_support_report_clean_text(raw.get("remark"), limit=4000, keep_newlines=True),
        "section_code": _isso_support_report_clean_text(raw.get("section_code"), limit=80),
        "section_name": _isso_support_report_clean_text(raw.get("section_name"), limit=200),
        "source_name": _isso_support_report_clean_text(raw.get("source_name"), limit=300),
        "object_name": _isso_support_report_clean_text(raw.get("object_name"), limit=300),
        "pk_text": _isso_support_report_clean_text(raw.get("pk_text"), limit=200),
    }
    if row["rd_status"] not in ISSO_SUPPORT_REPORT_RD_STATUSES:
        row["rd_status"] = "unknown"
    return row


def _normalize_isso_support_report_settings_payload(raw: object) -> dict:
    raw_rows = raw.get("rows") if isinstance(raw, dict) else []
    normalized: list[dict] = []
    seen: set[str] = set()
    for item in raw_rows if isinstance(raw_rows, list) else []:
        row = _normalize_isso_support_report_override_row(item)
        if not row:
            continue
        if row["row_key"] in seen:
            continue
        seen.add(row["row_key"])
        normalized.append(row)
    normalized.sort(key=lambda row: (row["plan_month"], row.get("section_code") or "", row.get("source_name") or "", row["row_key"]))
    return {"rows": normalized}


def _load_isso_support_report_settings_config() -> dict:
    _ensure_dashboard_settings_schema()
    row = query_one(
        """
        SELECT payload, updated_by, updated_at
        FROM dashboard_settings
        WHERE key = %s
        LIMIT 1
        """,
        (ISSO_SUPPORT_REPORT_CONFIG_KEY,),
    )
    payload = _normalize_isso_support_report_settings_payload(_coerce_json_value(row.get("payload")) if row and row.get("payload") is not None else {})
    payload["updated_by"] = row.get("updated_by") if row else None
    payload["updated_at"] = row.get("updated_at").isoformat() if row and row.get("updated_at") else None
    return payload


def _save_isso_support_report_settings_config(rows: list[dict], updated_by: str) -> dict:
    _ensure_dashboard_settings_schema()
    payload = _normalize_isso_support_report_settings_payload({"rows": rows})
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO dashboard_settings (key, payload, updated_by, updated_at)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (key) DO UPDATE
                    SET payload = EXCLUDED.payload,
                        updated_by = EXCLUDED.updated_by,
                        updated_at = NOW()
                    """,
                    (ISSO_SUPPORT_REPORT_CONFIG_KEY, json.dumps(payload, ensure_ascii=False), updated_by),
                )
    finally:
        conn.close()
    return _load_isso_support_report_settings_config()


def _latest_isso_support_snapshot() -> dict:
    row = query_one(
        """
        SELECT id::text AS id,
               snapshot_date::text AS snapshot_date,
               source_filename,
               source_reference,
               title,
               review_status,
               created_at::text AS created_at,
               comment
        FROM isso_front_transfer_snapshots
        ORDER BY snapshot_date DESC, created_at DESC
        LIMIT 1
        """
    )
    if not row:
        raise HTTPException(404, "ISSO snapshot not found")
    return row


def _isso_support_report_snapshot_months(snapshot_id: str) -> list[dict]:
    rows = query(
        """
        SELECT p.plan_month::date AS plan_month,
               COUNT(*)::int AS row_count
        FROM isso_front_transfer_monthly_plan p
        JOIN isso_front_transfer_lines l ON l.id = p.line_id
        WHERE l.snapshot_id = %s::uuid
        GROUP BY p.plan_month
        ORDER BY p.plan_month
        """,
        (snapshot_id,),
    )
    months: list[dict] = []
    for row in rows:
        plan_month = _isso_support_report_parse_month(row.get("plan_month"), field_name="plan_month")
        if not plan_month:
            continue
        months.append({
            "month": plan_month.isoformat(),
            "label": plan_month.strftime("%m.%Y"),
            "row_count": int(row.get("row_count") or 0),
        })
    return months


def _load_isso_support_report_source_rows(snapshot_id: str, target_month: date_cls) -> list[dict]:
    rows = query(
        """
        WITH bounds AS (
            SELECT cs.code, cs.name, csv.pk_start, csv.pk_end
            FROM construction_section_versions csv
            JOIN construction_sections cs ON cs.id = csv.section_id
            WHERE csv.is_current AND csv.boundary_kind = 'main'
        )
        SELECT COALESCE(p.id::text, l.id::text) AS plan_id,
               COALESCE(p.plan_month::text, %s::text) AS plan_month,
               COALESCE(
                   NULLIF(p.support_range_text, ''),
                   NULLIF(l.required_sequence_text, ''),
                   NULLIF(l.raw_payload->>'support_label', ''),
                   NULLIF(l.transferred_supports_text, ''),
                   ''
               ) AS support_range_text,
               o.object_code,
               o.name AS object_name,
               COALESCE(b.code, 'NO_SECTION') AS section_code,
               COALESCE(b.name, 'Без участка') AS section_name,
               os.pk_raw_text,
               a.source_name,
               a.source_pk_m::float AS source_pk_m,
               l.rd_status,
               l.rd_available_text,
               l.remark
        FROM isso_front_transfer_lines l
        LEFT JOIN isso_front_transfer_monthly_plan p ON p.line_id = l.id
                                                   AND p.plan_month = %s::date
        JOIN objects o ON o.id = l.object_id
        LEFT JOIN isso_object_front_attributes a ON a.id = l.object_attribute_id
        LEFT JOIN LATERAL (
            SELECT *
            FROM object_segments os
            WHERE os.object_id = o.id
            ORDER BY os.pk_start NULLS LAST
            LIMIT 1
        ) os ON true
        LEFT JOIN bounds b ON COALESCE(a.source_pk_m, (os.pk_start + os.pk_end) / 2) >= b.pk_start
                          AND COALESCE(a.source_pk_m, (os.pk_start + os.pk_end) / 2) < b.pk_end
        WHERE l.snapshot_id = %s::uuid
        ORDER BY COALESCE(a.source_pk_m, os.pk_start), a.source_name, support_range_text, l.source_row
        """,
        (target_month.isoformat(), target_month.isoformat(), snapshot_id),
    )
    out: list[dict] = []
    for row in rows:
        plan_month_iso = (_isso_support_report_parse_month(row.get("plan_month"), field_name="plan_month") or target_month).isoformat()
        plan_id = _isso_support_report_clean_text(row.get("plan_id"), limit=120)
        object_code = _isso_support_report_clean_text(row.get("object_code"), limit=160)
        out.append(
            {
                "row_key": _isso_support_report_row_key(plan_id, object_code, plan_month_iso),
                "plan_id": plan_id,
                "object_code": object_code,
                "plan_month": plan_month_iso,
                "section_code": _isso_support_report_clean_text(row.get("section_code"), limit=80),
                "section_name": _isso_support_report_clean_text(row.get("section_name"), limit=200),
                "source_name": _isso_support_report_clean_text(row.get("source_name"), limit=300),
                "object_name": _isso_support_report_clean_text(row.get("object_name"), limit=300),
                "pk_text": _isso_support_report_clean_text(row.get("pk_raw_text"), limit=200),
                "source_support_range_text": _isso_support_report_normalize_range(row.get("support_range_text")),
                "source_rd_status": _isso_support_report_normalize_status(row.get("rd_status") or row.get("rd_available_text")),
                "source_remark": _isso_support_report_clean_text(row.get("remark"), limit=4000, keep_newlines=True),
                "source_pk_m": row.get("source_pk_m"),
            }
        )
    return out


def _apply_isso_support_report_overrides(source_rows: list[dict], override_rows: list[dict]) -> list[dict]:
    by_row_key = {str(row.get("row_key") or ""): row for row in override_rows}
    by_object_month = {
        f"{row.get('object_code') or ''}:{row.get('plan_month') or ''}": row
        for row in override_rows
        if row.get("object_code") and row.get("plan_month")
    }
    effective_rows: list[dict] = []
    for row in source_rows:
        override = by_row_key.get(str(row.get("row_key") or ""))
        if not override:
            override = by_object_month.get(f"{row.get('object_code') or ''}:{row.get('plan_month') or ''}")
        effective_rows.append(
            {
                **row,
                "support_range_text": override.get("support_range_text") if override else row.get("source_support_range_text", ""),
                "rd_status": override.get("rd_status") if override else row.get("source_rd_status", "unknown"),
                "remark": override.get("remark") if override else row.get("source_remark", ""),
                "has_override": bool(override),
            }
        )
    return effective_rows


def _build_isso_support_report_settings_response(target_month: date_cls, *, snapshot: Optional[dict] = None, all_months: bool = False) -> dict:
    snapshot_row = snapshot or _latest_isso_support_snapshot()
    snapshot_id = str(snapshot_row.get("id") or "")
    config = _load_isso_support_report_settings_config()
    month_meta = _isso_support_report_snapshot_months(snapshot_id)
    if not month_meta:
        month_meta = [{"month": target_month.isoformat(), "label": target_month.strftime("%m.%Y"), "row_count": 0}]

    response_months = month_meta if all_months else [
        next((item for item in month_meta if item.get("month") == target_month.isoformat()), {"month": target_month.isoformat(), "label": target_month.strftime("%m.%Y"), "row_count": 0})
    ]
    rows: list[dict] = []
    for month_item in response_months:
        month_value = _isso_support_report_parse_month(month_item.get("month"), field_name="month")
        if not month_value:
            continue
        month_iso = month_value.isoformat()
        override_rows = [row for row in config.get("rows", []) if row.get("plan_month") == month_iso]
        source_rows = _load_isso_support_report_source_rows(snapshot_id, month_value)
        effective_rows = _apply_isso_support_report_overrides(source_rows, override_rows)
        month_item["row_count"] = len(effective_rows)
        rows.extend(effective_rows)

    return {
        "snapshot": snapshot_row,
        "target_month": target_month.isoformat(),
        "months": response_months,
        "rows": rows,
        "updated_by": config.get("updated_by"),
        "updated_at": config.get("updated_at"),
    }


@router.get("/settings/isso-support-report")
def get_settings_isso_support_report(
    month: Optional[str] = Query(None),
    all_months: bool = Query(False),
    _manager=Depends(require_settings_manager),
):
    snapshot = _latest_isso_support_snapshot()
    target_month = _isso_support_report_parse_month(month) or date_cls.fromisoformat(str(snapshot.get("snapshot_date") or "")[:10]).replace(day=1)
    return _build_isso_support_report_settings_response(target_month, snapshot=snapshot, all_months=all_months)


@router.put("/settings/isso-support-report")
def save_settings_isso_support_report(body: IssoSupportReportSettingsBody, _manager=Depends(require_settings_manager)):
    snapshot = _latest_isso_support_snapshot()
    default_month = date_cls.fromisoformat(str(snapshot.get("snapshot_date") or "")[:10]).replace(day=1)
    body_month = _isso_support_report_parse_month(body.month) if body.month else None
    target_month = body_month or default_month
    current = _load_isso_support_report_settings_config()
    new_rows = [
        row
        for row in (
            _normalize_isso_support_report_override_row(item.model_dump(), month_hint=target_month)
            for item in body.rows
        )
        if row
    ]

    if body_month:
        months_to_replace = {body_month.isoformat()}
        all_months_response = False
    else:
        months_to_replace = {
            parsed.isoformat()
            for parsed in (
                _isso_support_report_parse_month(month, field_name="months")
                for month in (body.months or [])
            )
            if parsed
        }
        if not months_to_replace:
            months_to_replace = {row.get("plan_month") for row in new_rows if row.get("plan_month")}
        all_months_response = True

    rows_for_other_months = [row for row in current.get("rows", []) if row.get("plan_month") not in months_to_replace]
    _save_isso_support_report_settings_config([*rows_for_other_months, *new_rows], getattr(_manager, "username", None) or "web")
    return _build_isso_support_report_settings_response(target_month, snapshot=snapshot, all_months=all_months_response)



class IssoSupportInputPlanBody(BaseModel):
    plan_id: Optional[str] = None
    plan_month: str
    support_range_text: str = ""
    planned_sites: int = 0


class IssoSupportInputFactMonthBody(BaseModel):
    value: str
    label: str = ""
    sites: int = 0


class IssoSupportInputLineBody(BaseModel):
    line_id: str
    support_label: str = ""
    supports_total: int = 0
    supports_done: int = 0
    fact_supports: int = 0
    sites_total: int = 0
    sites_done: int = 0
    fact_june_sites: int = 0
    fact_july_sites: int = 0
    fact_august_sites: int = 0
    fact_months: list[IssoSupportInputFactMonthBody] = []
    rd_status: str = "unknown"
    remark: str = ""
    deadline: str = "-"
    ms11_started: bool = False
    ms11_scope: bool = False
    plans: list[IssoSupportInputPlanBody] = []


def _isso_support_input_int(value: Any, *, min_value: int = 0, max_value: int = 9999) -> int:
    try:
        number = int(round(float(str(value).replace(",", "."))))
    except Exception:
        number = 0
    return max(min_value, min(max_value, number))


def _isso_support_input_json_obj(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    if value in (None, "", b""):
        return {}
    if isinstance(value, (bytes, bytearray)):
        value = value.decode("utf-8")
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return dict(parsed) if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


def _isso_support_input_pk_text(value: Any) -> str:
    if value is None:
        return ""
    try:
        pk_m = float(value)
    except (TypeError, ValueError):
        return ""
    pk = int(pk_m // 100)
    plus = pk_m - pk * 100
    return f"ПК{pk}+{plus:05.2f}".replace(".", ",")


def _isso_support_input_pk_label(pk_start: Any, pk_end: Any, object_type: str = "", object_code: str = "") -> str:
    start = _isso_support_input_pk_text(pk_start)
    end = _isso_support_input_pk_text(pk_end)
    norm_type = str(object_type or "").lower().replace("ё", "е")
    norm_code = str(object_code or "").upper()
    is_overpass = "путепровод" in norm_type or "overpass" in norm_type or norm_code.startswith("OVERPASS")
    if is_overpass:
        return start or end
    if start and end and start != end:
        return f"{start} - {end}"
    return start or end


ISSO_SUPPORT_INPUT_MONTH_LABELS = {
    1: "январь", 2: "февраль", 3: "март", 4: "апрель", 5: "май", 6: "июнь",
    7: "июль", 8: "август", 9: "сентябрь", 10: "октябрь", 11: "ноябрь", 12: "декабрь",
}
ISSO_SUPPORT_INPUT_MONTH_SHORTS = {
    1: "янв.", 2: "фев.", 3: "мар.", 4: "апр.", 5: "май", 6: "июн.",
    7: "июл.", 8: "авг.", 9: "сен.", 10: "окт.", 11: "нояб.", 12: "дек.",
}
ISSO_SUPPORT_INPUT_LEGACY_FACT_FIELDS = {
    6: "fact_june_sites",
    7: "fact_july_sites",
    8: "fact_august_sites",
}
ISSO_SUPPORT_INPUT_DEFAULT_FACT_MONTHS = tuple(range(6, 13))


def _isso_support_input_month_label(value: date_cls) -> str:
    return f"{ISSO_SUPPORT_INPUT_MONTH_LABELS.get(value.month, value.strftime('%m'))} {value.year}"


def _isso_support_input_month_from_any(value: Any, *, default_year: int) -> Optional[date_cls]:
    if isinstance(value, datetime):
        return value.date().replace(day=1)
    if isinstance(value, date_cls):
        return value.replace(day=1)
    text = str(value or "").strip().lower()
    if not text:
        return None
    match = re.match(r"^(\d{4})-(\d{1,2})", text)
    if match:
        return date_cls(int(match.group(1)), int(match.group(2)), 1)
    for month_num, label in ISSO_SUPPORT_INPUT_MONTH_LABELS.items():
        if text == label or label in text:
            return date_cls(default_year, month_num, 1)
    for month_num, label in ISSO_SUPPORT_INPUT_MONTH_SHORTS.items():
        if text == label or label in text:
            return date_cls(default_year, month_num, 1)
    return None


def _isso_support_input_fact_month_map(raw: dict[str, Any], *, default_year: int) -> dict[str, int]:
    months: dict[str, int] = {}
    fact_months = raw.get("fact_months")
    if isinstance(fact_months, dict):
        for key, value in fact_months.items():
            month_value = _isso_support_input_month_from_any(key, default_year=default_year)
            sites = _isso_support_input_int(value)
            if month_value and sites > 0:
                months[month_value.isoformat()] = sites
    elif isinstance(fact_months, list):
        for item in fact_months:
            if not isinstance(item, dict):
                continue
            month_value = _isso_support_input_month_from_any(
                item.get("value") or item.get("month") or item.get("label"),
                default_year=default_year,
            )
            sites = _isso_support_input_int(item.get("sites") or item.get("value_count"))
            if month_value and sites > 0:
                months[month_value.isoformat()] = sites
    for month_num, field in ISSO_SUPPORT_INPUT_LEGACY_FACT_FIELDS.items():
        sites = _isso_support_input_int(raw.get(field))
        if sites > 0:
            months[date_cls(default_year, month_num, 1).isoformat()] = sites
    return months


def _isso_support_input_fact_month_rows(raw: dict[str, Any], *, default_year: int) -> list[dict[str, Any]]:
    rows = []
    for value, sites in sorted(_isso_support_input_fact_month_map(raw, default_year=default_year).items()):
        try:
            month_value = date_cls.fromisoformat(value)
        except Exception:
            continue
        rows.append({"value": month_value.isoformat(), "label": _isso_support_input_month_label(month_value), "sites": sites})
    return rows


def _isso_support_input_fact_month_map_from_body(body: IssoSupportInputLineBody, *, default_year: int) -> dict[str, int]:
    months: dict[str, int] = {}
    if body.fact_months:
        for item in body.fact_months:
            month_value = _isso_support_input_month_from_any(item.value or item.label, default_year=default_year)
            sites = _isso_support_input_int(item.sites)
            if month_value and sites > 0:
                months[month_value.isoformat()] = sites
        return months
    for month_num, value in (
        (6, body.fact_june_sites),
        (7, body.fact_july_sites),
        (8, body.fact_august_sites),
    ):
        sites = _isso_support_input_int(value)
        if sites > 0:
            months[date_cls(default_year, month_num, 1).isoformat()] = sites
    return months


def _isso_support_input_required_tables_ready() -> bool:
    return all(_dashboard_table_exists(table) for table in (
        "isso_front_transfer_snapshots",
        "isso_front_transfer_lines",
        "isso_front_transfer_monthly_plan",
        "isso_object_front_attributes",
    ))


def _build_isso_support_input_response(target_month: Optional[date_cls] = None) -> dict:
    if not _isso_support_input_required_tables_ready():
        return {"available": False, "detail": "ISSO support tables are not available", "sections": [], "months": [], "snapshot": None}
    snapshot = _latest_isso_support_snapshot()
    snapshot_id = str(snapshot.get("id") or "")
    if target_month is None:
        try:
            target_month = date_cls.fromisoformat(str(snapshot.get("snapshot_date") or "")[:10]).replace(day=1)
        except Exception:
            target_month = date_cls.today().replace(day=1)
    target_year = target_month.year

    line_rows = query(
        """
        WITH bounds AS (
            SELECT cs.code, cs.name, csv.pk_start, csv.pk_end
            FROM construction_section_versions csv
            JOIN construction_sections cs ON cs.id = csv.section_id
            WHERE csv.is_current AND csv.boundary_kind = 'main'
        )
        SELECT l.id::text AS line_id,
               l.source_row,
               l.required_sequence_text,
               l.executor_text,
               l.transferred_supports_text,
               l.rd_status,
               l.rd_available_text,
               l.remark,
               l.raw_payload,
               o.object_code,
               o.name AS object_name_db,
               COALESCE(b.code, 'NO_SECTION') AS section_code,
               COALESCE(b.name, 'Без участка') AS section_name,
               a.source_no,
               a.source_scope,
               a.source_name,
               a.source_pk_m::float AS source_pk_m,
               os.pk_start::float AS pk_start_m,
               os.pk_end::float AS pk_end_m
        FROM isso_front_transfer_lines l
        JOIN objects o ON o.id = l.object_id
        LEFT JOIN isso_object_front_attributes a ON a.id = l.object_attribute_id
        LEFT JOIN LATERAL (
            SELECT *
            FROM object_segments os
            WHERE os.object_id = o.id
            ORDER BY os.pk_start NULLS LAST
            LIMIT 1
        ) os ON true
        LEFT JOIN bounds b ON COALESCE(a.source_pk_m, (os.pk_start + os.pk_end) / 2) >= b.pk_start
                          AND COALESCE(a.source_pk_m, (os.pk_start + os.pk_end) / 2) < b.pk_end
        WHERE l.snapshot_id = %s::uuid
        ORDER BY COALESCE(a.source_pk_m, 1e12), a.source_no, l.source_row
        """,
        (snapshot_id,),
    )
    plan_rows = query(
        """
        SELECT p.id::text AS plan_id,
               p.line_id::text AS line_id,
               p.plan_month::date AS plan_month,
               p.month_label,
               p.support_range_text,
               p.raw_payload
        FROM isso_front_transfer_monthly_plan p
        JOIN isso_front_transfer_lines l ON l.id = p.line_id
        WHERE l.snapshot_id = %s::uuid
        ORDER BY p.plan_month, p.id
        """,
        (snapshot_id,),
    )

    months_by_value: dict[str, date_cls] = {target_month.isoformat(): target_month}
    for month_num in ISSO_SUPPORT_INPUT_DEFAULT_FACT_MONTHS:
        month_value = date_cls(target_year, month_num, 1)
        months_by_value[month_value.isoformat()] = month_value
    plans_by_line: dict[str, list[dict[str, Any]]] = {}
    for plan in plan_rows:
        plan_month_raw = plan.get("plan_month")
        if isinstance(plan_month_raw, date_cls):
            plan_month = plan_month_raw.replace(day=1)
        else:
            try:
                parsed = date_cls.fromisoformat(str(plan_month_raw)[:10])
                plan_month = parsed.replace(day=1)
            except Exception:
                continue
        raw = _isso_support_input_json_obj(plan.get("raw_payload"))
        month_iso = plan_month.isoformat()
        months_by_value[month_iso] = plan_month
        support_range = _isso_support_report_normalize_range(plan.get("support_range_text") or raw.get("support_range_text") or raw.get("support_label"))
        plans_by_line.setdefault(str(plan.get("line_id") or ""), []).append({
            "plan_id": str(plan.get("plan_id") or ""),
            "plan_month": month_iso,
            "month_label": _isso_support_input_month_label(plan_month),
            "support_range_text": support_range,
            "planned_sites": _isso_support_input_int(raw.get("planned_sites")),
        })

    sections: dict[str, dict[str, Any]] = {}
    objects: dict[tuple[str, str, str, str], dict[str, Any]] = {}
    for rec in line_rows:
        raw = _isso_support_input_json_obj(rec.get("raw_payload"))
        line_id = str(rec.get("line_id") or "")
        fact_month_map = _isso_support_input_fact_month_map(raw, default_year=target_year)
        for value in fact_month_map:
            try:
                month_value = date_cls.fromisoformat(value)
            except Exception:
                continue
            months_by_value[month_value.isoformat()] = month_value
        section_code = _merge_section(rec.get("section_code")) or rec.get("section_code") or "NO_SECTION"
        section_name = str(rec.get("section_name") or "Без участка")
        section = sections.setdefault(section_code, {
            "section_code": section_code,
            "section_label": _isso_support_input_section_label(section_code, section_name),
            "objects": [],
            "sites_total": 0,
            "sites_done": 0,
        })
        object_code = str(rec.get("object_code") or "")
        object_name = str(raw.get("object_name") or rec.get("source_name") or rec.get("object_name_db") or "ИССО").strip()
        object_type = str(raw.get("object_type") or rec.get("source_scope") or "ИССО").strip()
        object_no = _isso_support_input_int(raw.get("object_no") or rec.get("source_no"), max_value=999999)
        pk_start_m = rec.get("pk_start_m") if rec.get("pk_start_m") is not None else rec.get("source_pk_m")
        pk_end_m = rec.get("pk_end_m") if rec.get("pk_end_m") is not None else rec.get("source_pk_m")
        object_key = (section_code, object_code, object_name, object_type)
        item = objects.get(object_key)
        if not item:
            item = {
                "object_no": object_no,
                "object_code": object_code,
                "object_name": object_name,
                "object_type": object_type,
                "section_code": section_code,
                "section_label": section["section_label"],
                "pk_label": _isso_support_input_pk_label(pk_start_m, pk_end_m, object_type, object_code),
                "rows": [],
                "sites_total": 0,
                "sites_done": 0,
                "ms11_scope": False,
                "ms11_started": False,
            }
            objects[object_key] = item
            section["objects"].append(item)
        sites_total = _isso_support_input_int(raw.get("sites_total"))
        sites_done = _isso_support_input_int(raw.get("sites_done"))
        if sites_done <= 0:
            sites_done = sum(fact_month_map.values())
        rd_status = _isso_support_report_normalize_status(rec.get("rd_status") or raw.get("rd_status") or rec.get("rd_available_text"))
        ms11_scope = bool(raw.get("ms11_scope")) if "ms11_scope" in raw else _isso_support_input_ms11_text(raw, rec)
        ms11_started = bool(raw.get("ms11_started"))
        row = {
            "line_id": line_id,
            "row_num": _isso_support_input_int(raw.get("row_num") or rec.get("source_row"), max_value=999999),
            "support_label": _isso_support_report_normalize_range(raw.get("support_label") or rec.get("required_sequence_text") or rec.get("transferred_supports_text")),
            "supports_total": _isso_support_input_int(raw.get("supports_total")),
            "supports_done": _isso_support_input_int(raw.get("supports_ready")),
            "fact_supports": _isso_support_input_int(raw.get("fact_supports")),
            "sites_total": sites_total,
            "sites_done": sites_done,
            "fact_june_sites": _isso_support_input_int(raw.get("fact_june_sites")),
            "fact_july_sites": _isso_support_input_int(raw.get("fact_july_sites")),
            "fact_august_sites": _isso_support_input_int(raw.get("fact_august_sites")),
            "fact_months": _isso_support_input_fact_month_rows(raw, default_year=target_year),
            "rd_status": rd_status,
            "remark": _isso_support_report_clean_text(rec.get("remark") or raw.get("remark"), keep_newlines=True),
            "deadline": _isso_support_report_clean_text(raw.get("deadline") or "-", limit=120),
            "ms11_started": ms11_started,
            "ms11_scope": ms11_scope,
            "plans": plans_by_line.get(line_id, []),
        }
        item["rows"].append(row)
        item["sites_total"] += sites_total
        item["sites_done"] += sites_done
        item["ms11_scope"] = bool(item["ms11_scope"] or ms11_scope)
        item["ms11_started"] = bool(item["ms11_started"] or ms11_started)
        section["sites_total"] += sites_total
        section["sites_done"] += sites_done

    section_list = sorted(sections.values(), key=lambda row: _isso_support_input_section_sort_key(row.get("section_code")))
    for section in section_list:
        section["objects"].sort(key=lambda item: (item.get("object_no") or 9999, item.get("pk_label") or "", item.get("object_name") or ""))
    months = [
        {"value": value.isoformat(), "label": _isso_support_input_month_label(value)}
        for value in sorted(months_by_value.values())
    ]
    return {
        "available": True,
        "snapshot": snapshot,
        "target_month": target_month.isoformat(),
        "target_month_label": _isso_support_input_month_label(target_month),
        "months": months,
        "sections": section_list,
    }


def _isso_support_input_ms11_text(raw: dict[str, Any], rec: dict[str, Any]) -> bool:
    text = " ".join(str(raw.get(key) or rec.get(key) or "") for key in ("executor_text", "executor", "contractor_text", "contractor", "remark"))
    normalized = text.lower().replace(" ", "").replace("_", "-").replace("—", "-").replace("–", "-")
    return "мс-11" in normalized or "мс11" in normalized or "силамимс-11" in normalized or "силамимс11" in normalized


def _isso_support_input_section_label(section_code: str, fallback: str = "") -> str:
    match = re.fullmatch(r"UCH_(\d+)", str(section_code or ""))
    if match:
        return f"Участок {match.group(1)}"
    return fallback or section_code or "Без участка"


def _isso_support_input_section_sort_key(section_code: object) -> tuple[int, str]:
    match = re.fullmatch(r"UCH_(\d+)", str(section_code or ""))
    return (int(match.group(1)) if match else 9999, str(section_code or ""))


@router.get("/reports/isso-support-input")
def get_reports_isso_support_input(month: Optional[str] = Query(None), _user=Depends(_require_isso_support_input_user)):
    target_month = _isso_support_report_parse_month(month) if month else None
    return _build_isso_support_input_response(target_month)


@router.put("/reports/isso-support-input/lines/{line_id}")
def put_reports_isso_support_input_line(line_id: str, body: IssoSupportInputLineBody, _user=Depends(_require_isso_support_input_user)):
    if str(body.line_id or "") and str(body.line_id) != str(line_id):
        raise HTTPException(400, "line_id in body does not match URL")
    snapshot = _latest_isso_support_snapshot()
    snapshot_id = str(snapshot.get("id") or "")
    existing = query_one(
        """
        SELECT id::text AS line_id, raw_payload, rd_status, remark
        FROM isso_front_transfer_lines
        WHERE id = %s::uuid AND snapshot_id = %s::uuid
        LIMIT 1
        """,
        (line_id, snapshot_id),
    )
    if not existing:
        raise HTTPException(404, "ISSO line not found in latest snapshot")
    raw = _isso_support_input_json_obj(existing.get("raw_payload"))
    try:
        default_year = date_cls.fromisoformat(str(snapshot.get("snapshot_date") or "")[:10]).year
    except Exception:
        default_year = date_cls.today().year
    fact_month_map = _isso_support_input_fact_month_map_from_body(body, default_year=default_year)
    fact_june_sites = fact_month_map.get(date_cls(default_year, 6, 1).isoformat(), 0)
    fact_july_sites = fact_month_map.get(date_cls(default_year, 7, 1).isoformat(), 0)
    fact_august_sites = fact_month_map.get(date_cls(default_year, 8, 1).isoformat(), 0)
    sites_done = max(_isso_support_input_int(body.sites_done), sum(fact_month_map.values()))
    support_label = _isso_support_report_normalize_range(body.support_label)
    remark = _isso_support_report_clean_text(body.remark, limit=4000, keep_newlines=True)
    rd_status = _isso_support_report_normalize_status(body.rd_status)
    raw.update({
        "support_label": support_label,
        "supports_total": _isso_support_input_int(body.supports_total),
        "supports_ready": _isso_support_input_int(body.supports_done),
        "fact_supports": _isso_support_input_int(body.fact_supports),
        "sites_total": _isso_support_input_int(body.sites_total),
        "sites_done": sites_done,
        "fact_june_sites": fact_june_sites,
        "fact_july_sites": fact_july_sites,
        "fact_august_sites": fact_august_sites,
        "fact_months": fact_month_map,
        "rd_status": rd_status,
        "remark": remark,
        "deadline": _isso_support_report_clean_text(body.deadline or "-", limit=120),
        "ms11_started": bool(body.ms11_started),
        "ms11_scope": bool(body.ms11_scope),
    })
    if body.ms11_scope:
        raw["executor_text"] = "МС-11"
    elif "executor_text" in raw:
        raw["executor_text"] = ""

    plans_existing = query(
        """
        SELECT id::text AS plan_id, raw_payload
        FROM isso_front_transfer_monthly_plan
        WHERE line_id = %s::uuid
        """,
        (line_id,),
    )
    existing_plan_ids = {str(row.get("plan_id") or ""): _isso_support_input_json_obj(row.get("raw_payload")) for row in plans_existing}
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE isso_front_transfer_lines
                    SET rd_status = %s,
                        remark = %s,
                        executor_text = %s,
                        required_sequence_text = %s,
                        raw_payload = %s::jsonb
                    WHERE id = %s::uuid AND snapshot_id = %s::uuid
                    """,
                    (
                        rd_status,
                        remark,
                        "МС-11" if body.ms11_scope else "",
                        support_label,
                        json.dumps(raw, ensure_ascii=False),
                        line_id,
                        snapshot_id,
                    ),
                )
                for plan_body in body.plans:
                    plan_month = _isso_support_report_parse_month(plan_body.plan_month, field_name="plan_month")
                    if not plan_month:
                        continue
                    support_range = _isso_support_report_normalize_range(plan_body.support_range_text)
                    planned_sites = _isso_support_input_int(plan_body.planned_sites)
                    plan_id = _isso_support_report_clean_text(plan_body.plan_id, limit=120)
                    plan_raw = dict(existing_plan_ids.get(plan_id) or {})
                    plan_raw.update({
                        "planned_sites": planned_sites,
                        "support_label": support_range,
                        "support_range_text": support_range,
                    })
                    if plan_id and plan_id in existing_plan_ids:
                        cur.execute(
                            """
                            UPDATE isso_front_transfer_monthly_plan
                            SET plan_month = %s::date,
                                month_label = %s,
                                support_range_text = %s,
                                raw_payload = %s::jsonb
                            WHERE id = %s::uuid AND line_id = %s::uuid
                            """,
                            (
                                plan_month.isoformat(),
                                _isso_support_input_month_label(plan_month),
                                support_range,
                                json.dumps(plan_raw, ensure_ascii=False),
                                plan_id,
                                line_id,
                            ),
                        )
                    elif planned_sites > 0 or support_range:
                        cur.execute(
                            """
                            INSERT INTO isso_front_transfer_monthly_plan (id, line_id, plan_month, month_label, support_range_text, raw_payload)
                            VALUES (%s::uuid, %s::uuid, %s::date, %s, %s, %s::jsonb)
                            """,
                            (
                                str(uuid.uuid4()),
                                line_id,
                                plan_month.isoformat(),
                                _isso_support_input_month_label(plan_month),
                                support_range,
                                json.dumps(plan_raw, ensure_ascii=False),
                            ),
                        )
    finally:
        conn.close()
    target_month = None
    if body.plans:
        target_month = _isso_support_report_parse_month(body.plans[0].plan_month, field_name="plan_month")
    return _build_isso_support_input_response(target_month)


DASHBOARD_PEOPLE_SOURCE_SHEET = "ВСЖМ дашборд"
DASHBOARD_PEOPLE_IMPORT_MAX_BYTES = int(os.getenv("DASHBOARD_PEOPLE_IMPORT_MAX_BYTES", str(15 * 1024 * 1024)))
DASHBOARD_PEOPLE_SCHEMA_READY = False
_DASHBOARD_PEOPLE_SCHEMA_LOCK = threading.Lock()
DASHBOARD_PEOPLE_CATEGORIES = (
    {"key": "hired", "label": "Устроено", "source": "Всего", "db_column": "hired_count"},
    {"key": "at_work", "label": "На работе", "source": "В работе", "db_column": "at_work_count"},
    {"key": "intershift", "label": "Межвахта", "source": "Межвахта", "db_column": "intershift_count"},
    {"key": "vacation", "label": "Отпуск", "source": "Отпуск", "db_column": "vacation_count"},
    {"key": "sick", "label": "Больничный", "source": "Больничный", "db_column": "sick_count"},
    {"key": "day_off", "label": "Выходной", "source": "Выходной", "db_column": "day_off_count"},
    {"key": "absence", "label": "Неявка", "source": "Неявка", "db_column": "absence_count"},
)
DASHBOARD_PEOPLE_CATEGORY_KEYS = tuple(str(item["key"]) for item in DASHBOARD_PEOPLE_CATEGORIES)
DASHBOARD_PEOPLE_CARD_ORDER = (
    "UCH_1",
    "UCH_2",
    "UCH_3",
    "UCH_4",
    "UCH_5",
    "UCH_6",
    "UCH_7",
    "UCH_8",
    "op_moscow",
    "op_novgorod",
    "op_tver",
)
DASHBOARD_PEOPLE_CARD_LABELS = {
    "op_moscow": "ОП Москва",
    "op_novgorod": "ОП Новгород",
    "op_tver": "ОП Тверь",
}
DASHBOARD_PEOPLE_REGION_CARDS = {
    "москва": "op_moscow",
    "новгород": "op_novgorod",
    "великий новгород": "op_novgorod",
    "тверь": "op_tver",
}


def _dashboard_people_empty_counts() -> dict[str, int]:
    return {key: 0 for key in DASHBOARD_PEOPLE_CATEGORY_KEYS}


def _dashboard_people_counts_with_rollups(counts: dict) -> dict:
    payload = {key: int(counts.get(key) or 0) for key in DASHBOARD_PEOPLE_CATEGORY_KEYS}
    payload["vacation_sick"] = payload["vacation"] + payload["sick"]
    return payload


def _dashboard_people_counts_from_db_row(row: Optional[dict]) -> dict[str, int]:
    if not row:
        return _dashboard_people_empty_counts()
    return {
        str(item["key"]): int(row.get(str(item["db_column"])) or 0)
        for item in DASHBOARD_PEOPLE_CATEGORIES
    }


def _dashboard_people_categories_payload() -> list[dict[str, str]]:
    return [
        {
            "key": str(item["key"]),
            "label": str(item["label"]),
            "source": str(item["source"]),
        }
        for item in DASHBOARD_PEOPLE_CATEGORIES
    ]


def _dashboard_people_safe_int(value) -> int:
    if value is None:
        return 0
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, float)):
        if isinstance(value, float) and math.isnan(value):
            return 0
        return int(round(value))
    text_value = str(value).strip()
    if not text_value or text_value.startswith("#"):
        return 0
    text_value = text_value.replace("\xa0", "").replace(" ", "").replace(",", ".")
    match = re.search(r"-?\d+(?:\.\d+)?", text_value)
    if not match:
        return 0
    try:
        return int(round(float(match.group(0))))
    except ValueError:
        return 0


def _dashboard_people_clean_label(value) -> str:
    return re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip()


def _dashboard_people_key(value) -> str:
    return _dashboard_people_clean_label(value).replace("ё", "е").lower()


def _dashboard_people_report_date_from_text(*values) -> Optional[date_cls]:
    for value in values:
        text_value = str(value or "")
        match = re.search(r"(\d{1,2})\.(\d{1,2})\.(\d{2,4})", text_value)
        if not match:
            continue
        day, month, year = (int(part) for part in match.groups())
        if year < 100:
            year += 2000
        try:
            return date_cls(year, month, day)
        except ValueError:
            continue
    return None


def _dashboard_people_counts_from_sheet_row(ws, row_idx: int) -> dict[str, int]:
    return {
        str(item["key"]): _dashboard_people_safe_int(ws.cell(row_idx, col_idx).value)
        for col_idx, item in enumerate(DASHBOARD_PEOPLE_CATEGORIES, start=2)
    }


def _dashboard_people_region_card_code(label: str) -> Optional[str]:
    return DASHBOARD_PEOPLE_REGION_CARDS.get(_dashboard_people_key(label))


def _dashboard_people_section_code(label: str) -> Optional[str]:
    match = re.search(r"пу\s*№?\s*(\d+)", _dashboard_people_key(label))
    if not match:
        return None
    section_num = int(match.group(1))
    if section_num < 1 or section_num > 8:
        return None
    return f"UCH_{section_num}"


def _dashboard_people_card_label(card_code: str) -> str:
    if card_code in DASHBOARD_PEOPLE_CARD_LABELS:
        return DASHBOARD_PEOPLE_CARD_LABELS[card_code]
    match = re.match(r"UCH_(\d+)$", card_code)
    if match:
        return f"Участок №{match.group(1)}"
    return card_code


def _dashboard_people_card_type(card_code: str) -> str:
    return "section" if re.match(r"UCH_\d+$", card_code or "") else "office"


def _dashboard_people_section_num(card_code: str) -> Optional[int]:
    match = re.match(r"UCH_(\d+)$", card_code or "")
    return int(match.group(1)) if match else None


def _dashboard_people_normalize_card_code(value: str) -> str:
    text_value = str(value or "").strip()
    match = re.match(r"uch[_-]?(\d+)$", text_value, flags=re.IGNORECASE)
    if match:
        return f"UCH_{int(match.group(1))}"
    lowered = text_value.lower()
    aliases = {
        "op_moscow": "op_moscow",
        "op_msk": "op_moscow",
        "op_novgorod": "op_novgorod",
        "op_veliky_novgorod": "op_novgorod",
        "op_tver": "op_tver",
    }
    return aliases.get(lowered, text_value)


def _dashboard_people_sphere_from_department_path(value) -> str:
    parts = [part.strip() for part in str(value or "").split(" / ") if part.strip()]
    if len(parts) >= 4:
        return parts[-2]
    if parts:
        return parts[-1]
    return "Без сферы"


def _dashboard_people_add_counts(target: dict[str, int], counts: dict) -> None:
    for key in DASHBOARD_PEOPLE_CATEGORY_KEYS:
        target[key] = int(target.get(key) or 0) + int(counts.get(key) or 0)


def _ensure_dashboard_people_schema() -> None:
    global DASHBOARD_PEOPLE_SCHEMA_READY
    if DASHBOARD_PEOPLE_SCHEMA_READY:
        return
    with _DASHBOARD_PEOPLE_SCHEMA_LOCK:
        if DASHBOARD_PEOPLE_SCHEMA_READY:
            return
        conn = get_conn()
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        CREATE TABLE IF NOT EXISTS dashboard_people_snapshots (
                          id uuid PRIMARY KEY,
                          report_date date NOT NULL,
                          source_filename text,
                          source_path text,
                          sheet_name text NOT NULL,
                          hired_count integer NOT NULL DEFAULT 0,
                          at_work_count integer NOT NULL DEFAULT 0,
                          intershift_count integer NOT NULL DEFAULT 0,
                          vacation_count integer NOT NULL DEFAULT 0,
                          sick_count integer NOT NULL DEFAULT 0,
                          day_off_count integer NOT NULL DEFAULT 0,
                          absence_count integer NOT NULL DEFAULT 0,
                          imported_by text,
                          imported_at timestamptz NOT NULL DEFAULT now(),
                          raw_payload jsonb NOT NULL DEFAULT '{}'::jsonb
                        )
                        """
                    )
                    cur.execute(
                        """
                        CREATE TABLE IF NOT EXISTS dashboard_people_rows (
                          id uuid PRIMARY KEY,
                          snapshot_id uuid NOT NULL REFERENCES dashboard_people_snapshots(id) ON DELETE CASCADE,
                          row_type text NOT NULL,
                          card_code text,
                          card_label text,
                          card_type text,
                          region_code text,
                          region_label text,
                          section_code text,
                          position text,
                          department_path text,
                          source_row integer,
                          depth integer NOT NULL DEFAULT 0,
                          hired_count integer NOT NULL DEFAULT 0,
                          at_work_count integer NOT NULL DEFAULT 0,
                          intershift_count integer NOT NULL DEFAULT 0,
                          vacation_count integer NOT NULL DEFAULT 0,
                          sick_count integer NOT NULL DEFAULT 0,
                          day_off_count integer NOT NULL DEFAULT 0,
                          absence_count integer NOT NULL DEFAULT 0,
                          created_at timestamptz NOT NULL DEFAULT now()
                        )
                        """
                    )
                    cur.execute(
                        """
                        CREATE INDEX IF NOT EXISTS idx_dashboard_people_snapshots_date
                          ON dashboard_people_snapshots (report_date DESC, imported_at DESC)
                        """
                    )
                    cur.execute(
                        """
                        CREATE INDEX IF NOT EXISTS idx_dashboard_people_rows_snapshot_card
                          ON dashboard_people_rows (snapshot_id, card_code, row_type)
                        """
                    )
            DASHBOARD_PEOPLE_SCHEMA_READY = True
        finally:
            conn.close()


def _parse_dashboard_people_workbook(
    file_path: str | Path,
    *,
    source_filename: Optional[str] = None,
    report_date: Optional[date_cls] = None,
) -> dict:
    workbook_path = Path(file_path)
    try:
        workbook = load_workbook(workbook_path, data_only=True)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"Не удалось открыть файл численности: {exc}") from exc

    if DASHBOARD_PEOPLE_SOURCE_SHEET in workbook.sheetnames:
        sheet = workbook[DASHBOARD_PEOPLE_SOURCE_SHEET]
    else:
        sheet = None
        for candidate in workbook.worksheets:
            for row_idx in range(1, min(candidate.max_row, 25) + 1):
                if "должность" in _dashboard_people_key(candidate.cell(row_idx, 1).value):
                    sheet = candidate
                    break
            if sheet is not None:
                break
        if sheet is None:
            raise HTTPException(status_code=400, detail="В файле не найден лист с таблицей численности")

    header_row = None
    expected_headers = [_dashboard_people_key(item["source"]) for item in DASHBOARD_PEOPLE_CATEGORIES]
    for row_idx in range(1, min(sheet.max_row, 30) + 1):
        first_cell = _dashboard_people_key(sheet.cell(row_idx, 1).value)
        headers = [_dashboard_people_key(sheet.cell(row_idx, col_idx).value) for col_idx in range(2, 9)]
        if "должность" in first_cell and headers[:7] == expected_headers:
            header_row = row_idx
            break
    if header_row is None:
        raise HTTPException(status_code=400, detail="В файле численности не найдена ожидаемая шапка статусов")

    parsed_date = report_date or _dashboard_people_report_date_from_text(source_filename, workbook_path.name) or date_cls.today()
    summary_counts: Optional[dict[str, int]] = None
    cards: dict[str, dict] = {}
    positions: list[dict] = []
    path_by_depth: dict[int, str] = {}
    current_region_code: Optional[str] = None
    current_region_label: Optional[str] = None
    current_section_code: Optional[str] = None
    current_section_label: Optional[str] = None

    for row_idx in range(header_row + 1, sheet.max_row + 1):
        label = _dashboard_people_clean_label(sheet.cell(row_idx, 1).value)
        if not label:
            continue
        try:
            depth = int(sheet.cell(row_idx, 1).alignment.indent or 0)
        except Exception:
            depth = 0
        for known_depth in list(path_by_depth):
            if known_depth >= depth:
                path_by_depth.pop(known_depth, None)
        parent_path = [path_by_depth[key] for key in sorted(path_by_depth)]
        path_by_depth[depth] = label
        counts = _dashboard_people_counts_from_sheet_row(sheet, row_idx)
        label_key = _dashboard_people_key(label)

        if "итого по всем" in label_key:
            summary_counts = counts
            current_region_code = None
            current_region_label = None
            current_section_code = None
            current_section_label = None
            continue

        if depth == 0:
            region_code = _dashboard_people_region_card_code(label)
            current_section_code = None
            current_section_label = None
            if region_code:
                current_region_code = region_code
                current_region_label = _dashboard_people_card_label(region_code)
                cards[region_code] = {
                    "card_code": region_code,
                    "card_label": current_region_label,
                    "card_type": _dashboard_people_card_type(region_code),
                    "region_code": region_code,
                    "region_label": current_region_label,
                    "section_code": None,
                    "source_row": row_idx,
                    "depth": depth,
                    "counts": counts,
                }
            else:
                current_region_code = None
                current_region_label = None
            continue

        if depth <= 1:
            section_code = _dashboard_people_section_code(label)
            if section_code:
                current_section_code = section_code
                current_section_label = _dashboard_people_card_label(section_code)
                cards[section_code] = {
                    "card_code": section_code,
                    "card_label": current_section_label,
                    "card_type": _dashboard_people_card_type(section_code),
                    "region_code": current_region_code,
                    "region_label": current_region_label,
                    "section_code": section_code,
                    "source_row": row_idx,
                    "depth": depth,
                    "counts": counts,
                }
            else:
                current_section_code = None
                current_section_label = None

        if depth < 4 or label.startswith("#"):
            continue

        target_cards: list[tuple[str, str, str]] = []
        if current_region_code and current_region_label:
            target_cards.append((current_region_code, current_region_label, "office"))
        if current_section_code and current_section_label:
            target_cards.append((current_section_code, current_section_label, "section"))
        department_path = " / ".join(parent_path)
        for card_code, card_label, card_type in target_cards:
            positions.append(
                {
                    "card_code": card_code,
                    "card_label": card_label,
                    "card_type": card_type,
                    "region_code": current_region_code,
                    "region_label": current_region_label,
                    "section_code": current_section_code if card_type == "section" else None,
                    "position": label,
                    "department_path": department_path,
                    "source_row": row_idx,
                    "depth": depth,
                    "counts": counts,
                }
            )

    if summary_counts is None:
        summary_counts = _dashboard_people_empty_counts()
        for code in ("op_moscow", "op_novgorod", "op_tver"):
            for key, value in (cards.get(code) or {}).get("counts", {}).items():
                summary_counts[key] = summary_counts.get(key, 0) + int(value or 0)

    for card_code in DASHBOARD_PEOPLE_CARD_ORDER:
        cards.setdefault(
            card_code,
            {
                "card_code": card_code,
                "card_label": _dashboard_people_card_label(card_code),
                "card_type": _dashboard_people_card_type(card_code),
                "region_code": card_code if card_code.startswith("op_") else None,
                "region_label": _dashboard_people_card_label(card_code) if card_code.startswith("op_") else None,
                "section_code": card_code if card_code.startswith("UCH_") else None,
                "source_row": None,
                "depth": 0,
                "counts": _dashboard_people_empty_counts(),
            },
        )

    return {
        "report_date": parsed_date,
        "source_filename": source_filename or workbook_path.name,
        "source_path": str(workbook_path),
        "sheet_name": sheet.title,
        "summary": summary_counts,
        "cards": [cards[card_code] for card_code in DASHBOARD_PEOPLE_CARD_ORDER],
        "positions": positions,
    }


def _insert_dashboard_people_row(cur, snapshot_id: str, row_type: str, row: dict) -> None:
    counts = row.get("counts") or {}
    cur.execute(
        """
        INSERT INTO dashboard_people_rows (
          id, snapshot_id, row_type, card_code, card_label, card_type, region_code, region_label,
          section_code, position, department_path, source_row, depth,
          hired_count, at_work_count, intershift_count, vacation_count, sick_count, day_off_count, absence_count
        )
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """,
        [
            str(uuid.uuid4()),
            snapshot_id,
            row_type,
            row.get("card_code"),
            row.get("card_label"),
            row.get("card_type"),
            row.get("region_code"),
            row.get("region_label"),
            row.get("section_code"),
            row.get("position"),
            row.get("department_path"),
            row.get("source_row"),
            int(row.get("depth") or 0),
            int(counts.get("hired") or 0),
            int(counts.get("at_work") or 0),
            int(counts.get("intershift") or 0),
            int(counts.get("vacation") or 0),
            int(counts.get("sick") or 0),
            int(counts.get("day_off") or 0),
            int(counts.get("absence") or 0),
        ],
    )


def _import_dashboard_people_snapshot(
    file_path: str | Path,
    *,
    source_filename: Optional[str] = None,
    source_path: Optional[str] = None,
    report_date: Optional[date_cls] = None,
    imported_by: Optional[str] = None,
) -> dict:
    parsed = _parse_dashboard_people_workbook(file_path, source_filename=source_filename, report_date=report_date)
    _ensure_dashboard_people_schema()
    snapshot_id = str(uuid.uuid4())
    summary = parsed["summary"]
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO dashboard_people_snapshots (
                      id, report_date, source_filename, source_path, sheet_name,
                      hired_count, at_work_count, intershift_count, vacation_count, sick_count, day_off_count, absence_count,
                      imported_by, raw_payload
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb)
                    """,
                    [
                        snapshot_id,
                        parsed["report_date"],
                        parsed["source_filename"],
                        source_path if source_path is not None else parsed["source_path"],
                        parsed["sheet_name"],
                        int(summary.get("hired") or 0),
                        int(summary.get("at_work") or 0),
                        int(summary.get("intershift") or 0),
                        int(summary.get("vacation") or 0),
                        int(summary.get("sick") or 0),
                        int(summary.get("day_off") or 0),
                        int(summary.get("absence") or 0),
                        imported_by,
                        json.dumps(
                            {
                                "parser": "dashboard_people_v1",
                                "card_count": len(parsed["cards"]),
                                "position_row_count": len(parsed["positions"]),
                            },
                            ensure_ascii=False,
                        ),
                    ],
                )
                _insert_dashboard_people_row(
                    cur,
                    snapshot_id,
                    "total",
                    {
                        "card_code": "total",
                        "card_label": "Итого",
                        "card_type": "total",
                        "counts": summary,
                        "depth": 0,
                    },
                )
                for card_row in parsed["cards"]:
                    _insert_dashboard_people_row(cur, snapshot_id, "card", card_row)
                for position_row in parsed["positions"]:
                    _insert_dashboard_people_row(cur, snapshot_id, "position", position_row)
    finally:
        conn.close()

    _invalidate_dashboard_response_cache("dashboard_people_import")
    return {
        "snapshot_id": snapshot_id,
        "report_date": parsed["report_date"].isoformat(),
        "source_filename": parsed["source_filename"],
        "sheet_name": parsed["sheet_name"],
        "cards": len(parsed["cards"]),
        "position_rows": len(parsed["positions"]),
        "summary": _dashboard_people_counts_with_rollups(summary),
    }


def _latest_dashboard_people_snapshot(date_to: Optional[date_cls]) -> Optional[dict]:
    _ensure_dashboard_people_schema()
    if date_to:
        row = query_one(
            """
            SELECT *
            FROM dashboard_people_snapshots
            WHERE report_date <= %s
            ORDER BY report_date DESC, imported_at DESC
            LIMIT 1
            """,
            [date_to],
        )
        return row
    return query_one(
        """
        SELECT *
        FROM dashboard_people_snapshots
        ORDER BY report_date DESC, imported_at DESC
        LIMIT 1
        """
    )


def _dashboard_people_payload(date_to: Optional[date_cls], *, date_from: Optional[date_cls] = None) -> Optional[dict]:
    snapshot = _latest_dashboard_people_snapshot(date_to)
    if not snapshot:
        return None
    snapshot_id = str(snapshot.get("id"))
    card_rows = query(
        """
        SELECT *
        FROM dashboard_people_rows
        WHERE snapshot_id = %s
          AND row_type = 'card'
        """,
        [snapshot_id],
    )
    detail_counts = query(
        """
        SELECT card_code, COUNT(DISTINCT position)::int AS position_count
        FROM dashboard_people_rows
        WHERE snapshot_id = %s
          AND row_type = 'position'
          AND position IS NOT NULL
        GROUP BY card_code
        """,
        [snapshot_id],
    )
    cards_by_code = {str(row.get("card_code")): row for row in card_rows}
    detail_count_by_code = {str(row.get("card_code")): int(row.get("position_count") or 0) for row in detail_counts}
    cards = []
    for card_code in DASHBOARD_PEOPLE_CARD_ORDER:
        row = cards_by_code.get(card_code)
        counts = _dashboard_people_counts_from_db_row(row)
        cards.append(
            {
                "card_code": card_code,
                "card_type": _dashboard_people_card_type(card_code),
                "section_num": _dashboard_people_section_num(card_code),
                "label": _dashboard_people_card_label(card_code),
                "counts": _dashboard_people_counts_with_rollups(counts),
                "total": int(counts.get("hired") or 0),
                "position_count": detail_count_by_code.get(card_code, 0),
            }
        )
    summary = _dashboard_people_counts_from_db_row(snapshot)
    return {
        "source": "dashboard_people",
        "from": date_from.isoformat() if date_from else None,
        "to": date_to.isoformat() if date_to else None,
        "fallback_used": False,
        "note": None,
        "snapshot_id": snapshot_id,
        "report_date": snapshot.get("report_date").isoformat() if snapshot.get("report_date") else None,
        "imported_at": snapshot.get("imported_at").isoformat() if snapshot.get("imported_at") else None,
        "source_filename": snapshot.get("source_filename"),
        "categories": _dashboard_people_categories_payload(),
        "summary": _dashboard_people_counts_with_rollups(summary),
        "total": int(summary.get("hired") or 0),
        "rows": [
            {
                "category": str(item["key"]),
                "label": str(item["label"]),
                "count": int(summary.get(str(item["key"])) or 0),
                "report_count": 0,
            }
            for item in DASHBOARD_PEOPLE_CATEGORIES
        ],
        "cards": cards,
        "sections": cards,
    }


@router.post("/dashboard/people/import")
def import_dashboard_people_file(
    file: UploadFile = File(...),
    report_date: Optional[str] = Query(None),
    _manager=Depends(require_settings_manager),
):
    filename = file.filename or "people.xlsx"
    suffix = Path(filename).suffix or ".xlsx"
    contents = file.file.read(DASHBOARD_PEOPLE_IMPORT_MAX_BYTES + 1)
    if len(contents) > DASHBOARD_PEOPLE_IMPORT_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Файл численности слишком большой")
    parsed_date = _dashboard_people_report_date_from_text(report_date) if report_date else None
    if report_date and not parsed_date:
        raise HTTPException(status_code=400, detail="Неверная дата отчета, используйте ДД.ММ.ГГГГ")
    tmp_name = ""
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as tmp:
            tmp.write(contents)
            tmp_name = tmp.name
        return _import_dashboard_people_snapshot(
            tmp_name,
            source_filename=filename,
            source_path=None,
            report_date=parsed_date,
            imported_by=getattr(_manager, "username", None) or "web",
        )
    finally:
        if tmp_name:
            try:
                os.unlink(tmp_name)
            except FileNotFoundError:
                pass


@router.get("/dashboard/staff-resources/{card_code}/details")
def dashboard_staff_resource_details(
    card_code: str,
    date_to: Optional[str] = Query(None, alias="to"),
):
    _, d_to = _parse_range(None, date_to)
    normalized_card_code = _dashboard_people_normalize_card_code(card_code)
    if normalized_card_code not in DASHBOARD_PEOPLE_CARD_ORDER:
        raise HTTPException(status_code=404, detail="Карточка численности не найдена")
    snapshot = _latest_dashboard_people_snapshot(d_to)
    if not snapshot:
        raise HTTPException(status_code=404, detail="Срез численности еще не загружен")
    snapshot_id = str(snapshot.get("id"))
    card_row = query_one(
        """
        SELECT *
        FROM dashboard_people_rows
        WHERE snapshot_id = %s
          AND row_type = 'card'
          AND card_code = %s
        LIMIT 1
        """,
        [snapshot_id, normalized_card_code],
    )
    rows = query(
        """
        SELECT position, department_path, source_row,
               hired_count, at_work_count, intershift_count, vacation_count, sick_count, day_off_count, absence_count
        FROM dashboard_people_rows
        WHERE snapshot_id = %s
          AND row_type = 'position'
          AND card_code = %s
          AND position IS NOT NULL
        ORDER BY source_row NULLS LAST, id
        """,
        [snapshot_id, normalized_card_code],
    )
    groups: list[dict] = []
    groups_by_sphere: dict[str, dict] = {}
    for row in rows:
        sphere = _dashboard_people_sphere_from_department_path(row.get("department_path"))
        group = groups_by_sphere.get(sphere)
        if not group:
            group = {
                "sphere": sphere,
                "source_row": row.get("source_row"),
                "counts": _dashboard_people_empty_counts(),
                "positions": [],
                "positions_by_key": {},
            }
            groups_by_sphere[sphere] = group
            groups.append(group)
        counts = _dashboard_people_counts_from_db_row(row)
        _dashboard_people_add_counts(group["counts"], counts)
        position = row.get("position") or "Без должности"
        position_slot = group["positions_by_key"].get(position)
        if not position_slot:
            position_slot = {
                "position": position,
                "sphere": sphere,
                "source_row": row.get("source_row"),
                "counts": _dashboard_people_empty_counts(),
            }
            group["positions_by_key"][position] = position_slot
            group["positions"].append(position_slot)
        _dashboard_people_add_counts(position_slot["counts"], counts)

    response_groups = [
        {
            "sphere": group["sphere"],
            "counts": _dashboard_people_counts_with_rollups(group["counts"]),
            "positions": [
                {
                    "position": position["position"],
                    "sphere": position["sphere"],
                    "counts": _dashboard_people_counts_with_rollups(position["counts"]),
                }
                for position in group["positions"]
            ],
        }
        for group in groups
    ]
    flat_positions = [position for group in response_groups for position in group["positions"]]
    return {
        "snapshot_id": snapshot_id,
        "report_date": snapshot.get("report_date").isoformat() if snapshot.get("report_date") else None,
        "source_filename": snapshot.get("source_filename"),
        "card_code": normalized_card_code,
        "card_type": _dashboard_people_card_type(normalized_card_code),
        "section_num": _dashboard_people_section_num(normalized_card_code),
        "label": _dashboard_people_card_label(normalized_card_code),
        "categories": _dashboard_people_categories_payload(),
        "totals": _dashboard_people_counts_with_rollups(_dashboard_people_counts_from_db_row(card_row)),
        "groups": response_groups,
        "positions": flat_positions,
    }


def _dashboard_staff_resources_payload(d_from: date_cls, d_to: date_cls) -> dict:
    people_payload = _dashboard_people_payload(d_to, date_from=d_from)
    if people_payload:
        return people_payload

    rows = query(
        """
        SELECT cs.code AS section_code,
               sc.category,
               SUM(sc.count)::numeric AS count,
               COUNT(DISTINCT dr.id)::int AS report_count
        FROM daily_report_staff_counts sc
        JOIN daily_reports dr ON dr.id = sc.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        WHERE dr.report_date BETWEEN %s AND %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        GROUP BY cs.code, sc.category
        ORDER BY cs.code, sc.category
        """,
        [d_from, d_to],
    )
    fallback_used = False
    note = None
    if not rows:
        fallback_used = True
        note = "За выбранный период данных по людям нет: показано среднее по всем подтвержденным отчетам."
        rows = query(
            """
            SELECT cs.code AS section_code,
                   sc.category,
                   AVG(sc.count)::numeric AS count,
                   COUNT(DISTINCT dr.id)::int AS report_count
            FROM daily_report_staff_counts sc
            JOIN daily_reports dr ON dr.id = sc.daily_report_id
            LEFT JOIN construction_sections cs ON cs.id = dr.section_id
            WHERE COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
            AND NOT (
              COALESCE(dr.source_type, '') = 'web_pile_control'
              OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
            )
            GROUP BY cs.code, sc.category
            ORDER BY cs.code, sc.category
            """,
        )

    manual = _load_dashboard_manual_data()
    category_totals: dict[str, dict] = {}
    section_map: dict[str, dict] = {}
    total = 0.0

    def add_staff_row(sec: str, category: str, value: float, report_count: int = 0, *, label: str | None = None, force: bool = False) -> None:
        nonlocal total
        if not force and abs(value) < 1e-9:
            return
        total += value
        cat_slot = category_totals.setdefault(category, {"category": category, "count": 0.0, "report_count": 0})
        cat_slot["count"] += value
        cat_slot["report_count"] += int(report_count or 0)
        sec_slot = section_map.setdefault(sec, {
            "section_code": sec,
            "section_num": _dashboard_section_num(sec),
            "label": label,
            "total": 0.0,
            "rows_by_category": {},
        })
        if label and not sec_slot.get("label"):
            sec_slot["label"] = label
        sec_slot["total"] += value
        row_slot = sec_slot["rows_by_category"].setdefault(category, {
            "category": category,
            "count": 0.0,
            "report_count": 0,
        })
        row_slot["count"] += value
        row_slot["report_count"] += int(report_count or 0)

    for row in rows:
        value = float(row.get("count") or 0)
        sec = _merge_section(row.get("section_code")) or row.get("section_code") or "—"
        cat = str(row.get("category") or "—").strip() or "—"
        add_staff_row(sec, cat, value, int(row.get("report_count") or 0))

    for row in manual.get("staff_sections") or []:
        sec = row.get("section_code") or "—"
        add_staff_row(sec, "pto", float(row.get("pto") or 0), force=True)
        add_staff_row(sec, "geodesy", float(row.get("geodesy") or 0), force=True)

    for row in manual.get("staff_offices") or []:
        code = row.get("code") or "office"
        label = row.get("label") or code
        add_staff_row(code, "office", float(row.get("office") or 0), label=label, force=True)
        add_staff_row(code, "pto", float(row.get("pto") or 0), label=label, force=True)
        add_staff_row(code, "geodesy", float(row.get("geodesy") or 0), label=label, force=True)

    category_rows = []
    for slot in category_totals.values():
        category_rows.append({
            "category": slot["category"],
            "count": round(slot["count"], 1) if fallback_used else int(round(slot["count"])),
            "report_count": int(slot["report_count"] or 0),
        })
    category_rows.sort(key=lambda row: str(row["category"]))

    sections = []
    for slot in section_map.values():
        row_values = list(slot.pop("rows_by_category").values())
        row_values.sort(key=lambda row: (0 if str(row["category"]).lower() in {"workers", "worker", "staff"} else 1, str(row["category"])))
        sections.append({
            "section_code": slot["section_code"],
            "section_num": slot["section_num"],
            "label": slot.get("label"),
            "total": round(slot["total"], 1) if fallback_used else int(round(slot["total"])),
            "rows": [
                {
                    "category": row["category"],
                    "count": round(row["count"], 1) if fallback_used else int(round(row["count"])),
                    "report_count": int(row["report_count"] or 0),
                }
                for row in row_values
            ],
        })
    sections.sort(key=lambda row: (row.get("section_num") is None, row.get("section_num") or 999, row.get("section_code") or ""))

    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "fallback_used": fallback_used,
        "note": note,
        "total": round(total, 1) if fallback_used else int(round(total)),
        "rows": category_rows,
        "sections": sections,
    }


@router.get("/dashboard/staff-resources")
def dashboard_staff_resources(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
):
    d_from, d_to = _parse_range(date_from, date_to)
    endpoint = "dashboard_staff_resources.v1"
    fingerprint = _dashboard_source_fingerprint(d_from, d_to, include_work=True)
    cache_key = (d_from.isoformat(), d_to.isoformat(), fingerprint)
    allow_stale_cache = _dashboard_response_cache_should_serve_stale()
    if allow_stale_cache:
        cached = _dashboard_short_cache_get(_DASHBOARD_STAFF_RESOURCES_CACHE, cache_key)
        if cached is not None:
            return cached
    persistent_key = _dashboard_response_cache_key({"endpoint": "dashboard_staff_resources", "from": d_from, "to": d_to})
    cached = _dashboard_response_cache_get(endpoint, persistent_key, fingerprint)
    if cached is not None:
        marked = _dashboard_response_cache_mark(cached, status="fresh", fingerprint=fingerprint)
        return _dashboard_short_cache_set(_DASHBOARD_STAFF_RESOURCES_CACHE, cache_key, marked)
    stale = _dashboard_response_cache_stale_payload(
        endpoint,
        persistent_key,
        fingerprint,
        dashboard_staff_resources,
        date_from,
        date_to,
        short_cache=_DASHBOARD_STAFF_RESOURCES_CACHE,
        short_cache_key=cache_key,
    )
    if stale is not None:
        return stale

    return _dashboard_response_cache_build_or_wait(
        endpoint,
        persistent_key,
        fingerprint,
        lambda: _dashboard_staff_resources_payload(d_from, d_to),
        short_cache=_DASHBOARD_STAFF_RESOURCES_CACHE,
        short_cache_key=cache_key,
    )



def _pile_effective_section_join(seg_alias: str = "seg_eff", section_alias: str = "cs_eff", report_section_alias: str = "cs_report_eff") -> str:
    pf_alias = f"{seg_alias}_pf"
    count_alias = f"{seg_alias}_count"
    count_item_alias = f"{seg_alias}_count_item"
    pk_alias = f"{seg_alias}_pk"
    boundary_alias = f"{seg_alias}_section"
    return f"""
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments {count_item_alias}
          WHERE {count_item_alias}.daily_work_item_id = dwi.id
            AND COALESCE({count_item_alias}.is_demo, false) IS FALSE
        ) {count_alias} ON true
        LEFT JOIN daily_work_item_segments {seg_alias}
          ON {seg_alias}.daily_work_item_id = dwi.id
         AND COALESCE({seg_alias}.is_demo, false) IS FALSE
        LEFT JOIN pile_fields {pf_alias} ON {pf_alias}.id = {seg_alias}.pile_field_id
        LEFT JOIN construction_sections {report_section_alias}
          ON {report_section_alias}.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COALESCE(
            (COALESCE({seg_alias}.pk_start, {pf_alias}.pk_start) + COALESCE({seg_alias}.pk_end, {pf_alias}.pk_end)) / 2.0,
            COALESCE({seg_alias}.pk_start, {pf_alias}.pk_start),
            COALESCE({seg_alias}.pk_end, {pf_alias}.pk_end)
          ) AS pk_mid
        ) {pk_alias} ON true
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = 'piles_pipes'
            AND {pk_alias}.pk_mid IS NOT NULL
            AND {pk_alias}.pk_mid >= LEAST(csv.pk_start, csv.pk_end)
            AND {pk_alias}.pk_mid < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) {boundary_alias} ON true
        LEFT JOIN construction_sections {section_alias}
          ON {section_alias}.id = COALESCE({boundary_alias}.section_id, {report_section_alias}.id)
         AND {section_alias}.is_active IS NOT FALSE
    """


def _pile_effective_volume_expr(seg_alias: str = "seg_eff") -> str:
    count_alias = f"{seg_alias}_count"
    return f"""
        CASE
          WHEN {seg_alias}.id IS NULL THEN COALESCE(dwi.volume, 0)
          WHEN {seg_alias}.volume_segment IS NOT NULL THEN COALESCE({seg_alias}.volume_segment, 0)
          WHEN {count_alias}.cnt > 0 THEN COALESCE(dwi.volume, 0) / {count_alias}.cnt
          ELSE COALESCE(dwi.volume, 0)
        END
    """


def _is_pile_rig_text(equipment_type: object, brand_model: object = None) -> bool:
    text = f"{equipment_type or ''} {brand_model or ''}".strip().lower().replace("ё", "е")
    return (
        "сваеб" in text
        or "коп" in text
        or "junttan" in text
        or ("бур" in text and "установ" in text)
    )


def _pile_rig_sql_filter(reu_alias: str = "reu", eu_alias: str = "eu") -> str:
    return f"""
      (
        POSITION('сваеб' IN LOWER(COALESCE({reu_alias}.equipment_type, {eu_alias}.equipment_type, ''))) > 0
        OR POSITION('коп' IN LOWER(COALESCE({reu_alias}.equipment_type, {eu_alias}.equipment_type, ''))) > 0
        OR POSITION('junttan' IN LOWER(COALESCE({reu_alias}.brand_model, {eu_alias}.brand_model, ''))) > 0
        OR (
          POSITION('бур' IN LOWER(COALESCE({reu_alias}.equipment_type, {eu_alias}.equipment_type, ''))) > 0
          AND POSITION('установ' IN LOWER(COALESCE({reu_alias}.equipment_type, {eu_alias}.equipment_type, ''))) > 0
        )
      )
    """


def _clean_pile_rig_name_fragment(value: object) -> str:
    text = str(value or "").replace("ё", "е").strip()
    text = re.sub(r"\bсваебойно[-\s]*буров\w*\b", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"\bсваебойн\w*\b", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"\bустановк\w*\b", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*[·*/|,;:-]+\s*", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def _pile_rig_display_name(row: dict) -> str:
    brand_model = _clean_pile_rig_name_fragment(row.get("brand_model"))
    equipment_type = _clean_pile_rig_name_fragment(row.get("equipment_type"))
    if brand_model:
        return brand_model
    return equipment_type or "Сваебойка"


def _pile_rig_ownership_label(row: dict) -> str:
    contractor = str(row.get("contractor_name") or "").strip()
    normalized = contractor.lower().replace("ё", "е")
    ownership = str(row.get("ownership_type") or "").strip().lower()
    if ownership == "own" or normalized in {"ждс", "ооо ждс", "желдорстрой"}:
        return "ЖДС"
    if "алмаз" in normalized:
        return "АЛМАЗ"
    if contractor:
        return contractor
    if ownership == "hired":
        return "Наемная"
    return "Не указано"


def _pile_rig_has_identifier(row: dict) -> bool:
    return bool(_clean_equipment_identifier_text(row.get("unit_number")) or _clean_equipment_identifier_text(row.get("plate_number")))


def _pile_rig_is_own(row: dict) -> bool:
    ownership = str(row.get("ownership_type") or "").strip().lower()
    contractor = str(row.get("contractor_name") or row.get("contractor") or row.get("ownership_label") or "").strip().lower().replace("ё", "е")
    return ownership == "own" or contractor in {"ждс", "ооо ждс", "желдорстрой"} or "желдорстрой" in contractor


def _pile_rig_sort_key(row: dict) -> tuple:
    unit = _clean_equipment_identifier_text(row.get("unit_number"))
    plate = _clean_equipment_identifier_text(row.get("plate_number"))
    numeric_unit = bool(re.fullmatch(r"\d+", unit))
    unit_num = int(unit) if numeric_unit else 10**9
    has_unit = bool(unit)
    own_bucket = 0 if _pile_rig_is_own(row) else 1
    contractor = str(row.get("contractor_name") or row.get("contractor") or row.get("ownership_label") or "").strip().lower()
    model = str(row.get("name") or row.get("brand_model") or row.get("equipment_type") or row.get("label") or "").strip().lower()
    if numeric_unit and own_bucket == 0:
        group = 0
    elif numeric_unit:
        group = 1
    elif has_unit and own_bucket == 0:
        group = 2
    elif has_unit:
        group = 3
    elif own_bucket == 0:
        group = 4
    else:
        group = 5
    return (
        group,
        unit_num,
        unit,
        contractor if own_bucket else "",
        model,
        plate,
    )


def _pile_rig_identity(row: dict) -> str:
    master_id = str(row.get("equipment_unit_id") or row.get("id") or "").strip()
    if master_id:
        return f"master:{master_id}"
    return _equipment_identity_key(row, row.get("report_equipment_id"))


def _pile_rig_ref_from_row(row: dict, piles_count: float = 0.0) -> Optional[dict[str, Any]]:
    if not _pile_rig_has_identifier(row):
        return None
    key = _pile_rig_identity(row)
    if not key:
        return None
    ref = {
        "key": key,
        "name": _pile_rig_display_name(row),
        "unit_number": _clean_equipment_identifier_text(row.get("unit_number")),
        "plate_number": _clean_equipment_identifier_text(row.get("plate_number")),
        "ownership_label": _pile_rig_ownership_label(row),
        "piles_count": round(float(piles_count or 0), 1),
    }
    notes = _pile_work_notes_from_comments(row.get("work_comments"))
    if notes:
        ref["notes"] = notes
    return ref


PILE_WORK_COMMENT_META_PREFIXES = (
    "field=",
    "field_id=",
    "pile_field=",
    "pile_type=",
    "length=",
    "equipment=",
    "pipe=",
    "pipe_pile_spec=",
    "object=",
    "target=",
    "work_type=",
)


def _pile_work_notes_from_comments(value: Any) -> list[str]:
    values = value if isinstance(value, (list, tuple, set)) else [value]
    notes: list[str] = []
    seen: set[str] = set()
    for raw in values:
        text = str(raw or "").strip()
        if not text:
            continue
        for part in re.split(r"\s*;\s*", text):
            note = part.strip()
            if not note:
                continue
            lower = note.lower()
            if any(lower.startswith(prefix) for prefix in PILE_WORK_COMMENT_META_PREFIXES):
                continue
            if lower in {"pile-control", "контроль свай", "web_pile_control"}:
                continue
            dedupe_key = re.sub(r"\s+", " ", lower)
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            notes.append(note)
    return notes


def _project_pile_kind_from_text(value: Any) -> str:
    text = str(value or "").strip().lower()
    if "test" in text or "trial" in text or "проб" in text:
        return "test"
    return "main"


def _reinforcement_project_pile_data(
    query_section_codes: list[str],
    section_codes: list[str],
) -> tuple[dict[str, dict[str, float]], dict[str, list[dict[str, Any]]]]:
    totals: dict[str, dict[str, float]] = {
        code: {"main": 0.0, "test": 0.0, "dyn": 0.0}
        for code in section_codes
    }
    merged_details: dict[str, dict[str, dict[str, Any]]] = {code: {} for code in section_codes}
    for row in _query_project_piles(query_section_codes):
        code = _merge_section(row.get("section_code")) or str(row.get("section_code") or "")
        if code not in totals:
            continue
        project_qty = float(row.get("pile_count") or 0)
        project_dyn = float(row.get("dynamic_test_count") or 0)
        if project_qty <= 0 and project_dyn <= 0:
            continue
        kind = _project_pile_kind_from_text(row.get("field_type"))
        project_main = 0.0 if kind == "test" else project_qty
        project_test = project_qty if kind == "test" else 0.0
        totals[code]["main"] += project_main
        totals[code]["test"] += project_test
        totals[code]["dyn"] += project_dyn

        field_name = str(row.get("field_code") or "Поле н/д").strip() or "Поле н/д"
        entry = merged_details[code].setdefault(field_name, {
            "section_code": code,
            "field_name": field_name,
            "pk_ranges": [],
            "project_main": 0.0,
            "project_test": 0.0,
            "project_dyn": 0.0,
            "_sort_pk": None,
        })
        entry["project_main"] += project_main
        entry["project_test"] += project_test
        entry["project_dyn"] += project_dyn
        pk_range = row.get("pk_range") or _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"))
        pk_range = pk_range or "ПК н/д"
        if pk_range not in entry["pk_ranges"]:
            entry["pk_ranges"].append(pk_range)
        pk_start = row.get("pk_start")
        if pk_start is not None and (entry["_sort_pk"] is None or pk_start < entry["_sort_pk"]):
            entry["_sort_pk"] = pk_start

    details: dict[str, list[dict[str, Any]]] = {code: [] for code in section_codes}
    for code, by_field in merged_details.items():
        rows = sorted(
            by_field.values(),
            key=lambda item: (
                item.get("_sort_pk") is None,
                float(item.get("_sort_pk") or 0),
                str(item.get("field_name") or ""),
            ),
        )
        for entry in rows:
            details[code].append({
                "section_code": code,
                "field_name": entry.get("field_name") or "Поле н/д",
                "pk_ranges": entry.get("pk_ranges") or ["ПК н/д"],
                "project_main": float(entry.get("project_main") or 0),
                "project_test": float(entry.get("project_test") or 0),
                "project_dyn": float(entry.get("project_dyn") or 0),
            })
    return totals, details


def _reinforcement_pile_rig_usage_rows(date_from: date_cls, date_to: date_cls, query_section_codes: list[str]) -> list[dict]:
    return query(
        f"""
        SELECT reu.id::text AS report_equipment_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               COALESCE(reu.equipment_type, eu.equipment_type) AS equipment_type,
               COALESCE(reu.brand_model, eu.brand_model) AS brand_model,
               COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')) AS unit_number,
               COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')) AS plate_number,
               COALESCE(reu.ownership_type, eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), eu.contractor_name, '') AS contractor_name,
               cs_eff_rig.code AS section_code,
               dwi.report_date AS report_date,
               COALESCE(NULLIF(seg_rig_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д') AS field_name,
                   SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN {_pile_effective_volume_expr('seg_rig')} ELSE 0 END)::numeric AS main_cnt,
                   SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN {_pile_effective_volume_expr('seg_rig')} ELSE 0 END)::numeric AS test_cnt,
                   COUNT(DISTINCT dwi.daily_report_id)::int AS report_count,
                   ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(BTRIM(dwi.comment), '')), NULL) AS work_comments,
                   MIN(dwi.report_date) AS first_date,
                   MAX(dwi.report_date) AS last_date
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        {_pile_effective_section_join('seg_rig', 'cs_eff_rig', 'cs_report_rig')}
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        WHERE dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
          AND cs_eff_rig.code = ANY(%s)
          AND {_pile_rig_sql_filter()}
        GROUP BY reu.id,
                 reu.equipment_unit_id,
                 COALESCE(reu.equipment_type, eu.equipment_type),
                 COALESCE(reu.brand_model, eu.brand_model),
                 COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')),
                 COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')),
                 COALESCE(reu.ownership_type, eu.ownership_type, 'unknown'),
                 COALESCE(NULLIF(reu.contractor_name, ''), eu.contractor_name, ''),
                 cs_eff_rig.code,
                 dwi.report_date,
                 COALESCE(NULLIF(seg_rig_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д')
        """,
        [date_from, date_to, query_section_codes],
    )


def _reinforcement_pile_rig_refs_by_field(
    date_from: date_cls,
    date_to: date_cls,
    query_section_codes: list[str],
    section_codes: list[str],
    *,
    include_day: bool = False,
) -> dict[tuple, list[dict[str, Any]]]:
    grouped: dict[tuple, dict[str, dict[str, Any]]] = {}
    for row in _reinforcement_pile_rig_usage_rows(date_from, date_to, query_section_codes):
        section_code = _merge_section(row.get("section_code")) or row.get("section_code") or ""
        if section_code not in section_codes:
            continue
        field_name = str(row.get("field_name") or "Поле н/д").strip() or "Поле н/д"
        day_value = row.get("report_date")
        day_iso = day_value.isoformat() if hasattr(day_value, "isoformat") else str(day_value or "")
        key = (section_code, day_iso, field_name) if include_day else (section_code, field_name)
        total_cnt = float(row.get("main_cnt") or 0) + float(row.get("test_cnt") or 0)
        if total_cnt <= 0:
            continue
        rig_ref = _pile_rig_ref_from_row(row, total_cnt)
        if not rig_ref:
            continue
        bucket = grouped.setdefault(key, {})
        existing = bucket.setdefault(rig_ref["key"], rig_ref)
        if existing is not rig_ref:
            existing["piles_count"] = round(float(existing.get("piles_count") or 0) + total_cnt, 1)
            existing_notes = existing.setdefault("notes", [])
            for note in rig_ref.get("notes") or []:
                if note not in existing_notes:
                    existing_notes.append(note)
    return {
        key: sorted(values.values(), key=lambda item: (str(item.get("name") or ""), str(item.get("unit_number") or "")))
        for key, values in grouped.items()
    }


def _reinforcement_pile_rigs_payload(
    month_start: date_cls,
    as_of: date_cls,
    query_section_codes: list[str],
    section_codes: list[str],
    day_plan_state: Optional[dict[str, dict[str, float]]] = None,
) -> dict:
    rigs: dict[str, dict[str, Any]] = {}

    def ensure_rig(row: dict) -> Optional[dict]:
        if not _pile_rig_has_identifier(row):
            return None
        key = _pile_rig_identity(row)
        if not key:
            return None
        entry = rigs.setdefault(key, {
            "key": key,
            "name": _pile_rig_display_name(row),
            "unit_number": _clean_equipment_identifier_text(row.get("unit_number")),
            "plate_number": _clean_equipment_identifier_text(row.get("plate_number")),
            "ownership_type": str(row.get("ownership_type") or "unknown").strip() or "unknown",
                "ownership_label": _pile_rig_ownership_label(row),
                "contractor_name": str(row.get("contractor_name") or "").strip(),
                "working_sections": set(),
                "working_days": set(),
                "fact_section_days": set(),
                "piles_count": 0.0,
                "notes": set(),
                "details_by_key": {},
            })
        for field in ("name", "unit_number", "plate_number", "contractor_name"):
            if not entry.get(field):
                if field == "name":
                    entry[field] = _pile_rig_display_name(row)
                elif field in {"unit_number", "plate_number"}:
                    entry[field] = _clean_equipment_identifier_text(row.get(field))
                else:
                    entry[field] = str(row.get(field) or "").strip()
        if entry.get("ownership_label") == "Не указано":
            entry["ownership_type"] = str(row.get("ownership_type") or entry.get("ownership_type") or "unknown").strip()
            entry["ownership_label"] = _pile_rig_ownership_label(row)
        return entry

    master_rows = query(
        """
        SELECT id::text AS equipment_unit_id,
               id::text AS id,
               equipment_type,
               brand_model,
               unit_number,
               plate_number,
               ownership_type,
               contractor_name,
               status
        FROM equipment_units
        WHERE is_active IS NOT FALSE
          AND (
            NULLIF(BTRIM(COALESCE(unit_number, '')), '') IS NOT NULL
            OR NULLIF(BTRIM(COALESCE(plate_number, '')), '') IS NOT NULL
          )
        """
    )
    for row in master_rows:
        if _is_pile_rig_text(row.get("equipment_type"), row.get("brand_model")):
            ensure_rig(row)

    report_rows = query(
        f"""
        SELECT reu.id::text AS report_equipment_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               COALESCE(reu.equipment_type, eu.equipment_type) AS equipment_type,
               COALESCE(reu.brand_model, eu.brand_model) AS brand_model,
               COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')) AS unit_number,
               COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')) AS plate_number,
               COALESCE(reu.ownership_type, eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), eu.contractor_name, '') AS contractor_name,
               COALESCE(reu.status, eu.status, 'unknown') AS status,
               cs.code AS section_code,
               dr.report_date AS report_date
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        WHERE dr.report_date BETWEEN %s AND %s
          AND dr.source_type = 'mechanization_report_m'
          AND reu.is_demo IS NOT TRUE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND {_pile_rig_sql_filter()}
        """,
        [month_start, as_of],
    )
    for row in report_rows:
        ensure_rig(row)

    usage_rows = query(
        f"""
        SELECT reu.id::text AS report_equipment_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               COALESCE(reu.equipment_type, eu.equipment_type) AS equipment_type,
               COALESCE(reu.brand_model, eu.brand_model) AS brand_model,
               COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')) AS unit_number,
               COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')) AS plate_number,
               COALESCE(reu.ownership_type, eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), eu.contractor_name, '') AS contractor_name,
               cs_eff_rig.code AS section_code,
               dwi.report_date AS report_date,
               COALESCE(NULLIF(seg_rig_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д') AS field_name,
                   SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN {_pile_effective_volume_expr('seg_rig')} ELSE 0 END)::numeric AS main_cnt,
                   SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN {_pile_effective_volume_expr('seg_rig')} ELSE 0 END)::numeric AS test_cnt,
                   COUNT(DISTINCT dwi.daily_report_id)::int AS report_count,
                   ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(BTRIM(dwi.comment), '')), NULL) AS work_comments,
                   MIN(dwi.report_date) AS first_date,
                   MAX(dwi.report_date) AS last_date
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        {_pile_effective_section_join('seg_rig', 'cs_eff_rig', 'cs_report_rig')}
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        WHERE dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
          AND cs_eff_rig.code = ANY(%s)
          AND {_pile_rig_sql_filter()}
        GROUP BY reu.id,
                 reu.equipment_unit_id,
                 COALESCE(reu.equipment_type, eu.equipment_type),
                 COALESCE(reu.brand_model, eu.brand_model),
                 COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')),
                 COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')),
                 COALESCE(reu.ownership_type, eu.ownership_type, 'unknown'),
                 COALESCE(NULLIF(reu.contractor_name, ''), eu.contractor_name, ''),
                 cs_eff_rig.code,
                 dwi.report_date,
                 COALESCE(NULLIF(seg_rig_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д')
        """,
        [month_start, as_of, query_section_codes],
    )
    for row in usage_rows:
        entry = ensure_rig(row)
        if not entry:
            continue
        section_code = _merge_section(row.get("section_code")) or row.get("section_code") or "—"
        if section_code not in section_codes:
            continue
        main_cnt = float(row.get("main_cnt") or 0)
        test_cnt = float(row.get("test_cnt") or 0)
        total_cnt = main_cnt + test_cnt
        if total_cnt <= 0:
            continue
        work_notes = _pile_work_notes_from_comments(row.get("work_comments"))
        field_name = str(row.get("field_name") or "Поле н/д").strip() or "Поле н/д"
        report_date = row.get("report_date")
        day_iso = report_date.isoformat() if hasattr(report_date, "isoformat") else str(report_date or "")
        detail_key = f"{section_code}:{field_name}"
        detail = entry["details_by_key"].setdefault(detail_key, {
            "section_code": section_code,
            "section_label": f"Участок №{section_codes.index(section_code) + 1}" if section_code in section_codes else section_code,
            "field_name": field_name,
            "main": 0.0,
            "test": 0.0,
            "total": 0.0,
            "report_count": 0,
            "first_date": None,
            "last_date": None,
            "notes": set(),
        })
        detail["main"] += main_cnt
        detail["test"] += test_cnt
        detail["total"] += total_cnt
        detail["report_count"] += int(row.get("report_count") or 0)
        first_date = row.get("first_date")
        last_date = row.get("last_date")
        if first_date and (detail["first_date"] is None or first_date < detail["first_date"]):
            detail["first_date"] = first_date
        if last_date and (detail["last_date"] is None or last_date > detail["last_date"]):
            detail["last_date"] = last_date
        entry["piles_count"] += total_cnt
        for note in work_notes:
            entry["notes"].add(note)
            detail["notes"].add(note)
        entry["working_sections"].add(section_code)
        if day_iso:
            entry["working_days"].add(day_iso)
            entry["fact_section_days"].add((section_code, day_iso))

    items = []
    by_section: dict[str, list[dict[str, Any]]] = {code: [] for code in section_codes}
    selected_day = as_of.isoformat()
    plan_state = day_plan_state or {}
    for entry in rigs.values():
        details = []
        section_totals: dict[str, float] = {}
        for detail in entry.pop("details_by_key").values():
            detail["first_date"] = detail["first_date"].isoformat() if detail["first_date"] else None
            detail["last_date"] = detail["last_date"].isoformat() if detail["last_date"] else None
            detail["main"] = round(float(detail["main"] or 0), 1)
            detail["test"] = round(float(detail["test"] or 0), 1)
            detail["total"] = round(float(detail["total"] or 0), 1)
            detail["notes"] = sorted(str(note) for note in detail.get("notes", set()) if note)
            details.append(detail)
            section_totals[detail["section_code"]] = section_totals.get(detail["section_code"], 0.0) + float(detail["total"] or 0)
        details.sort(key=lambda row: (
            section_codes.index(row["section_code"]) if row.get("section_code") in section_codes else 999,
            str(row.get("field_name") or ""),
        ))
        working_sections = sorted(entry["working_sections"], key=lambda code: section_codes.index(code) if code in section_codes else 999)
        selected_fact_sections = {
            section_code
            for section_code, day in entry.get("fact_section_days", set())
            if day == selected_day
        }
        performs_plan = any(
            float((plan_state.get(section_code) or {}).get("plan_total") or 0) > 0
            and float((plan_state.get(section_code) or {}).get("fact_total") or 0) >= float((plan_state.get(section_code) or {}).get("plan_total") or 0)
            for section_code in selected_fact_sections
        )
        status = "performing_plan" if performs_plan else "working" if float(entry.get("piles_count") or 0) > 0 else "idle"
        entry_notes = sorted(str(note) for note in entry.get("notes", set()) if note)
        item = {
            **{key: value for key, value in entry.items() if key not in {"working_sections", "working_days", "fact_section_days", "notes"}},
            "working_sections": working_sections,
            "working_days": sorted(day for day in entry["working_days"] if day),
            "piles_count": round(float(entry.get("piles_count") or 0), 1),
            "status": status,
            "notes": entry_notes,
            "details": details,
        }
        items.append(item)
        related_sections = set(working_sections) | set(section_totals)
        for section_code in related_sections:
            if section_code not in by_section:
                continue
            by_section[section_code].append({
                "key": item["key"],
                "name": item["name"],
                "unit_number": item["unit_number"],
                "plate_number": item["plate_number"],
                "ownership_label": item["ownership_label"],
                "status": item["status"],
                "piles_count": round(section_totals.get(section_code, 0.0), 1),
            })
    ranked_items = sorted(items, key=_pile_rig_sort_key)
    for rank, item in enumerate(ranked_items, start=1):
        item["rank"] = rank
    items.sort(key=lambda item: int(item.get("rank") or 9999))
    for rows in by_section.values():
        rows.sort(key=_pile_rig_sort_key)

    return {
        "period": {"from": month_start.isoformat(), "to": as_of.isoformat()},
        "items": items,
        "by_section": by_section,
    }

@router.get("/dashboard/pile-rig-rating")
def dashboard_pile_rig_rating(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
):
    d_from, d_to = _parse_range(date_from, date_to)
    rig_rows = query(
        """
        SELECT cs.code AS section_code,
               COUNT(DISTINCT COALESCE(reu.equipment_unit_id::text, NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number)), ''), NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number)), ''), reu.id::text))::int AS units_count,
               ARRAY_AGG(DISTINCT CASE
                 WHEN NULLIF(BTRIM(COALESCE(reu.brand_model, eu.brand_model, '')), '') IS NOT NULL THEN CONCAT_WS(' · ',
                   NULLIF(BTRIM(COALESCE(reu.brand_model, eu.brand_model, '')), ''),
                   NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number, '')), ''),
                   NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number, '')), '')
                 )
                 ELSE CONCAT_WS(' · ',
                   COALESCE(NULLIF(BTRIM(COALESCE(reu.equipment_type, eu.equipment_type, '')), ''), 'Сваебойная установка'),
                   NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number, '')), ''),
                   NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number, '')), '')
                 )
               END) AS equipment_types
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        WHERE dr.report_date BETWEEN %s AND %s
          AND dr.source_type = 'mechanization_report_m'
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND reu.is_demo IS NOT TRUE
          AND LOWER(COALESCE(reu.status, '')) = 'working'
          AND (
            POSITION('сваеб' IN LOWER(COALESCE(reu.equipment_type, eu.equipment_type, ''))) > 0
            OR (POSITION('бур' IN LOWER(COALESCE(reu.equipment_type, eu.equipment_type, ''))) > 0 AND POSITION('установ' IN LOWER(COALESCE(reu.equipment_type, eu.equipment_type, ''))) > 0)
          )
          AND cs.code IS NOT NULL
        GROUP BY cs.code
        """,
        [d_from, d_to],
    )
    rig_by_sec: dict[str, dict] = {}
    for row in rig_rows:
        sec = _merge_section(row.get("section_code")) or row.get("section_code")
        if not sec:
            continue
        entry = rig_by_sec.setdefault(sec, {"units_count": 0, "equipment_types": set()})
        entry["units_count"] += int(row.get("units_count") or 0)
        raw_types = row.get("equipment_types") or []
        parts = raw_types if isinstance(raw_types, list) else str(raw_types).split(";")
        for part in parts:
            clean = str(part or "").strip()
            if clean:
                entry["equipment_types"].add(clean)

    usage_rig_rows = query(
        f"""
        SELECT cs_eff_usage.code AS section_code,
               COUNT(DISTINCT COALESCE(reu.equipment_unit_id::text, NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number)), ''), NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number)), ''), reu.id::text))::int AS units_count,
               ARRAY_AGG(DISTINCT CONCAT_WS(' · ',
                 COALESCE(NULLIF(BTRIM(COALESCE(reu.equipment_type, eu.equipment_type, '')), ''), 'Сваебойная установка'),
                 NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number, '')), ''),
                 NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number, '')), '')
               )) AS equipment_types
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        {_pile_effective_section_join('seg_usage', 'cs_eff_usage', 'cs_report_usage')}
        WHERE dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
          AND cs_eff_usage.code IS NOT NULL
        GROUP BY cs_eff_usage.code
        """,
        [d_from, d_to],
    )
    for row in usage_rig_rows:
        sec = _merge_section(row.get("section_code")) or row.get("section_code")
        if not sec:
            continue
        entry = rig_by_sec.setdefault(sec, {"units_count": 0, "equipment_types": set()})
        entry["units_count"] += int(row.get("units_count") or 0)
        raw_types = row.get("equipment_types") or []
        parts = raw_types if isinstance(raw_types, list) else str(raw_types).split(";")
        for part in parts:
            clean = str(part or "").strip()
            if clean:
                entry["equipment_types"].add(clean)

    fact_rows = query(
        f"""
        SELECT cs_eff_fact.code AS section_code,
               SUM({_pile_effective_volume_expr('seg_fact')})::numeric AS piles_count
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        {_pile_effective_section_join('seg_fact', 'cs_eff_fact', 'cs_report_fact')}
        WHERE dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
        GROUP BY cs_eff_fact.code
        """,
        [d_from, d_to],
    )
    piles_by_sec: dict[str, float] = {}
    for row in fact_rows:
        sec = _merge_section(row.get("section_code")) or row.get("section_code")
        if sec:
            piles_by_sec[sec] = piles_by_sec.get(sec, 0.0) + float(row.get("piles_count") or 0)

    rows = []
    for n in range(1, 9):
        sec = f"UCH_{n}"
        rig = rig_by_sec.get(sec, {"units_count": 0, "equipment_types": set()})
        units_count = int(rig["units_count"] or 0)
        piles_count = float(piles_by_sec.get(sec, 0.0))
        rows.append({
            "section_code": sec,
            "section_num": n,
            "units_count": units_count,
            "piles_count": round(piles_count, 1),
            "rating": round(piles_count / units_count, 2) if units_count > 0 else None,
            "equipment_types": sorted(rig["equipment_types"]),
        })
    rows.sort(key=lambda row: (-(row["rating"] or 0), row["section_num"]))
    return {"from": d_from.isoformat(), "to": d_to.isoformat(), "rows": rows}


def _dashboard_temp_road_rows_for_pdf(to_date: date_cls) -> tuple[list[dict], dict[str, float]]:
    data = temp_roads_status(to_date.isoformat())
    totals = {"total_m": 0.0, "passable_m": 0.0, "ready_m": 0.0, "done_m": 0.0}
    rows = []
    for road in data.get("roads", []):
        length = abs(float(road.get("length_m") or 0))
        done = 0.0
        ready = 0.0
        covered = 0.0
        for seg in road.get("segments", []):
            seg_len = abs(float(seg.get("ad_pk_end") or seg.get("pk_end") or 0) - float(seg.get("ad_pk_start") or seg.get("pk_start") or 0))
            covered += seg_len
            if seg.get("status_type") == "shpgs_done":
                done += seg_len
            elif seg.get("status_type") == "ready_for_shpgs":
                ready += seg_len
        totals["total_m"] += length
        totals["passable_m"] += min(length, covered)
        totals["ready_m"] += ready
        totals["done_m"] += done
        rows.append({
            "code": road.get("code"),
            "name": road.get("name"),
            "length_m": length,
            "passable_m": min(length, covered),
            "ready_m": ready,
            "done_m": done,
            "effective_date": road.get("effective_date"),
        })
    return rows, totals


def _dashboard_stockpile_rows_for_pdf(as_of: date_cls) -> list[dict]:
    rows = query(
        """
        WITH latest AS (
          SELECT DISTINCT ON (s.stockpile_id)
                 s.stockpile_id, s.snapshot_date, s.balance_volume, s.unit
          FROM stockpile_balance_snapshots s
          WHERE s.snapshot_date <= %s
            AND s.balance_volume IS NOT NULL
          ORDER BY s.stockpile_id, s.snapshot_date DESC
        )
        SELECT sp.name AS stockpile_name,
               COALESCE(m.name, m.code, 'Материал') AS material_name,
               latest.snapshot_date,
               latest.balance_volume::numeric AS balance,
               latest.unit,
               os.pk_start,
               os.pk_end,
               os.pk_raw_text,
               cs.code AS section_code
        FROM latest
        JOIN stockpiles sp ON sp.id = latest.stockpile_id
        LEFT JOIN materials m ON m.id = sp.material_id
        LEFT JOIN object_segments os ON os.object_id = sp.object_id
        LEFT JOIN LATERAL (
          SELECT cs.code
          FROM construction_section_versions csv
          JOIN construction_sections cs ON cs.id = csv.section_id
          WHERE csv.is_current = true
            AND csv.boundary_kind = 'main'
            AND os.pk_start IS NOT NULL
            AND ((os.pk_start + COALESCE(os.pk_end, os.pk_start)) / 2.0) BETWEEN csv.pk_start AND csv.pk_end
          ORDER BY cs.sort_order NULLS LAST, cs.code
          LIMIT 1
        ) cs ON true
        WHERE sp.is_active IS NOT FALSE
        ORDER BY section_code NULLS LAST, sp.name
        """,
        [as_of],
    )
    return [{
        "section": _format_section_label(r.get("section_code")),
        "name": r.get("stockpile_name") or "Накопитель",
        "material": r.get("material_name") or "Материал",
        "pk": _format_pk_range_excel(r.get("pk_start"), r.get("pk_end"), r.get("pk_raw_text")) or "ПК н/д",
        "date": r.get("snapshot_date").isoformat() if r.get("snapshot_date") else "—",
        "balance": round(float(r.get("balance") or 0), 1),
        "unit": r.get("unit") or "м3",
    } for r in rows]


def _dashboard_fmt(n: object, digits: int = 0) -> str:
    try:
        value = float(n or 0)
    except Exception:
        value = 0.0
    if digits <= 0:
        return f"{value:,.0f}".replace(",", " ")
    return f"{value:,.{digits}f}".replace(",", " ").replace(".", ",")


def _dashboard_table(headers: list[str], rows: list[list[object]]) -> str:
    head = "".join(f"<th>{html.escape(str(h))}</th>" for h in headers)
    body = "".join(
        "<tr>" + "".join(f"<td>{html.escape(str(cell))}</td>" for cell in row) + "</tr>"
        for row in rows
    )
    return f"<table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>"



