def _dashboard_render_stockpiles(data: dict) -> str:
    note = f'<div class="warn">{_dashboard_e(data.get("note"))}</div>' if data.get("note") else ""
    by_sec: dict[int, list[dict]] = {}
    totals_by_material: dict[tuple[str, str], float] = {}
    for row in data.get("rows") or []:
        by_sec.setdefault(int(row.get("section_num") or 0), []).append(row)
        key = (str(row.get("material_name") or "Материал"), str(row.get("unit") or "м3"))
        totals_by_material[key] = totals_by_material.get(key, 0.0) + float(row.get("balance") or 0)
    totals_html = "".join(
        f'<span style="display:inline-block;margin:0 6px 6px 0;padding:4px 7px;border:1px solid #e5e7eb;border-radius:6px;background:#f9fafb"><b>{_dashboard_e(material)}</b>: {_dashboard_fmt(value,1)} {_dashboard_e(unit)}</span>'
        for (material, unit), value in sorted(totals_by_material.items(), key=lambda item: -item[1])
    )
    totals_line = f'<div class="muted mono" style="margin-bottom:8px">{totals_html}</div>' if totals_html else ""
    cards = []
    for n in range(1, 9):
        rows = by_sec.get(n) or []
        inner = "".join(f'<div class="row"><div class="name"><b>{_dashboard_e(r.get("material_name"))}</b><br/><span class="muted mono small">{_dashboard_e(r.get("pk_label") or "ПК н/д")}</span></div><div class="val mono">{_dashboard_fmt(r.get("balance"),1)} {_dashboard_e(r.get("unit") or "м3")}</div></div>' for r in rows) or '<span class="muted">нет накопителей</span>'
        cards.append(f'<div class="card"><div class="kpi-label">Участок №{n}</div>{inner}</div>')
    return _dashboard_section("Состояние накопителей по участкам", "▤", note + f'<div class="muted mono" style="margin-bottom:8px">последний срез: {_dashboard_format_date(data.get("effective_date"))}</div>' + totals_line + f'<div class="grid-4">{"".join(cards)}</div>')


def _dashboard_render_pile_rigs(data: dict) -> str:
    rows = data.get("rows") or []
    max_rating = max([1.0] + [float(row.get("rating") or 0) for row in rows if row.get("rating") is not None])
    cards = []
    for row in rows:
        rating = float(row.get("rating") or 0) if row.get("rating") is not None else None
        width = 0.0 if rating is None else max(4.0, min(100.0, rating / max_rating * 100))
        cards.append(
            f'<div class="card"><div class="row" style="padding:0;border-bottom:0"><div class="name"><b>{_dashboard_e(_dashboard_section_label(row.get("section_code"), row.get("section_num")))}</b></div><div class="val mono">{_dashboard_fmt(rating, 2) if rating is not None else "—"}</div></div>'
            f'<div class="bar red"><span style="width:{width:.1f}%"></span></div><div class="muted small" style="margin-top:4px">{_dashboard_fmt(row.get("piles_count"))} свай · {_dashboard_fmt(row.get("units_count"))} уст.</div></div>'
        )
    cards_html = f'<div class="grid-2" style="margin-bottom:12px">{"".join(cards)}</div>' if cards else ''
    table_rows = "".join(
        f'<tr><td>{_dashboard_section_label(row.get("section_code"), row.get("section_num"))}</td><td class="num">{_dashboard_fmt(row.get("piles_count"),1)}</td><td class="num">{_dashboard_fmt(row.get("units_count"))}</td><td class="num"><b>{_dashboard_fmt(row.get("rating"),2) if row.get("rating") is not None else "—"}</b></td><td>{_dashboard_e(", ".join(row.get("equipment_types") or []))}</td></tr>'
        for row in rows
    ) or '<tr><td colspan="5" class="muted">Нет данных.</td></tr>'
    table = f'<table><thead><tr><th>Участок</th><th class="num">Забито свай</th><th class="num">Установок</th><th class="num">Рейтинг</th><th>Типы техники</th></tr></thead><tbody>{table_rows}</tbody></table>'
    subtitle = 'забитые сваи на сваебойную установку в работе'
    return _dashboard_section("Производительность сваебойных установок", "⚙", cards_html + table, subtitle)


DASHBOARD_TEMP_ROAD_TRACKS = [
    {"key": "pioneer_fill", "label": "Пионерка", "fill": "#E8DDF5", "stroke": "#7c3aed"},
    {"key": "subgrade_not_to_grade", "label": "ЗП в работе", "fill": "#FCE5CD", "stroke": "#d97706"},
    {"key": "dso", "label": "ДСО", "fill": "#FFF2CC", "stroke": "#ca8a04"},
    {"key": "ready_for_shpgs", "label": "Под ЩПГС", "fill": "#D9EAF7", "stroke": "#2563eb"},
    {"key": "shpgs_done", "label": "ЩПГС уложен", "fill": "#D9EAD3", "stroke": "#16a34a"},
    {"key": "no_work", "label": "Не в работе", "fill": "#f8fafc", "stroke": "#6b7280"},
]
DASHBOARD_TEMP_ROAD_TRACK_BY_KEY = {row["key"]: row for row in DASHBOARD_TEMP_ROAD_TRACKS}


def _dashboard_format_pk(pk100: float) -> str:
    sign = "-" if pk100 < 0 else ""
    abs_value = abs(float(pk100 or 0))
    pk = math.floor(abs_value / 100)
    plus = abs_value - pk * 100
    return f"{sign}ПК{pk}+{plus:05.2f}"


def _dashboard_merge_ranges(ranges: list[tuple[float, float]]) -> list[tuple[float, float]]:
    if not ranges:
        return []
    cleaned = sorted((min(a, b), max(a, b)) for a, b in ranges)
    out: list[list[float]] = [[cleaned[0][0], cleaned[0][1]]]
    for start, end in cleaned[1:]:
        last = out[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            out.append([start, end])
    return [(row[0], row[1]) for row in out]


def _dashboard_subtract_ranges(universe: tuple[float, float], ranges: list[tuple[float, float]]) -> list[tuple[float, float]]:
    u_start, u_end = min(universe), max(universe)
    merged = _dashboard_merge_ranges(ranges)
    out: list[tuple[float, float]] = []
    cursor = u_start
    for start, end in merged:
        if end <= u_start:
            continue
        if start >= u_end:
            break
        ss = max(start, u_start)
        ee = min(end, u_end)
        if ss > cursor:
            out.append((cursor, ss))
        cursor = max(cursor, ee)
    if cursor < u_end:
        out.append((cursor, u_end))
    return out


def _dashboard_clamp_range(start: float, end: float, min_value: float, max_value: float) -> tuple[float, float] | None:
    lo = min(min_value, max_value)
    hi = max(min_value, max_value)
    a = max(min(start, end), lo)
    b = min(max(start, end), hi)
    if b - a <= 0.01:
        return None
    return a, b


def _dashboard_temp_road_ticks(pk_start: float, pk_end: float) -> list[tuple[int, bool]]:
    start_pk = math.ceil(pk_start / 100)
    end_pk = math.floor(pk_end / 100)
    count = max(0, end_pk - start_pk + 1)
    if count <= 0:
        return []
    step = 1
    for candidate in (1, 2, 5, 10, 20, 50):
        if math.ceil(count / candidate) <= 15:
            step = candidate
            break
    return [(pk, pk % step == 0) for pk in range(start_pk, end_pk + 1)]


def _dashboard_temp_road_title(road: dict) -> str:
    raw = str(road.get("code") or road.get("name") or "").strip()
    match = re.match(r"^АД\s*(\d+(?:\.\d+)?)\s*(№\s*\d+(?:\.\d+)?)?$", raw, flags=re.IGNORECASE)
    if not match:
        return raw or "АД"
    road_num = match.group(1)
    suffix = re.sub(r"\s+", "", match.group(2) or "")
    return f"АД{road_num} {suffix}".strip()


def _dashboard_temp_road_legend_fill(track: dict) -> str:
    if track["key"] == "no_work":
        return "repeating-linear-gradient(45deg, transparent 0 3px, #9ca3af 3px 4px)"
    return track["fill"]


def _dashboard_render_temp_road_card(road: dict) -> str:
    has_rail = road.get("rail_pk_start") is not None and road.get("rail_pk_end") is not None
    axis_start = min(float(road.get("rail_pk_start") or 0), float(road.get("rail_pk_end") or 0)) if has_rail else min(float(road.get("ad_pk_start") or 0), float(road.get("ad_pk_end") or 0))
    axis_end = max(float(road.get("rail_pk_start") or 0), float(road.get("rail_pk_end") or 0)) if has_rail else max(float(road.get("ad_pk_start") or 0), float(road.get("ad_pk_end") or 0))
    span = max(1.0, axis_end - axis_start)
    ad_start = min(float(road.get("ad_pk_start") or 0), float(road.get("ad_pk_end") or 0))
    ad_end = max(float(road.get("ad_pk_start") or 0), float(road.get("ad_pk_end") or 0))
    ad_span = max(1.0, ad_end - ad_start)
    total_length_m = float(road.get("length_m") or abs(ad_end - ad_start) or 0.0)
    length_km = total_length_m / 1000.0

    totals = {track["key"]: 0.0 for track in DASHBOARD_TEMP_ROAD_TRACKS}
    painted: list[dict] = []
    covered_axis: list[tuple[float, float]] = []
    covered_ad: list[tuple[float, float]] = []
    for segment in road.get("segments") or []:
        status_key = str(segment.get("status_type") or "")
        if status_key not in DASHBOARD_TEMP_ROAD_TRACK_BY_KEY or status_key == "no_work":
            continue
        axis_range = _dashboard_clamp_range(float(segment.get("pk_start") or 0), float(segment.get("pk_end") or 0), axis_start, axis_end)
        if not axis_range:
            continue
        raw_ad_start = float(segment.get("ad_pk_start")) if segment.get("ad_pk_start") is not None else axis_range[0]
        raw_ad_end = float(segment.get("ad_pk_end")) if segment.get("ad_pk_end") is not None else axis_range[1]
        ad_range = _dashboard_clamp_range(raw_ad_start, raw_ad_end, ad_start, ad_end)
        if not ad_range:
            continue
        totals[status_key] += ad_range[1] - ad_range[0]
        painted.append({"track": status_key, "start": axis_range[0], "end": axis_range[1], "is_demo": bool(segment.get("is_demo"))})
        covered_axis.append(axis_range)
        covered_ad.append(ad_range)

    for start, end in _dashboard_subtract_ranges((axis_start, axis_end), covered_axis):
        if end - start >= 0.01:
            painted.append({"track": "no_work", "start": start, "end": end, "is_demo": False})
    for start, end in _dashboard_subtract_ranges((ad_start, ad_end), covered_ad):
        if end - start >= 0.01:
            totals["no_work"] += end - start

    ready_len = totals.get("ready_for_shpgs", 0.0) + totals.get("shpgs_done", 0.0)
    ready_pct = ready_len / total_length_m * 100 if total_length_m > 0 else 0.0
    ticks = _dashboard_temp_road_ticks(axis_start, axis_end)

    view_w = 1000.0
    pad_l = 90.0
    pad_r = 10.0
    draw_w = view_w - pad_l - pad_r
    track_h = 28.0
    track_gap = 5.0
    tracks_y0 = 22.0
    tracks_h = len(DASHBOARD_TEMP_ROAD_TRACKS) * track_h + (len(DASHBOARD_TEMP_ROAD_TRACKS) - 1) * track_gap
    axis_y = tracks_y0 + tracks_h + 6.0
    bottom_y = axis_y + 34.0
    view_h = bottom_y + 4.0

    def x_of(pk100: float) -> float:
        return pad_l + ((pk100 - axis_start) / span) * draw_w

    pattern_id = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(road.get("id") or road.get("code") or "road"))
    svg_parts = [
        f'<svg class="road-svg" viewBox="0 0 {view_w:.0f} {view_h:.0f}" xmlns="http://www.w3.org/2000/svg">',
        f'<defs><pattern id="hatch-{pattern_id}" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="6" stroke="#9ca3af" stroke-width="1.2" /></pattern></defs>',
    ]
    left_axis_label = _dashboard_format_pk(axis_start) if has_rail else "ВСЖМ —"
    svg_parts.append(
        f'<text x="{pad_l:.2f}" y="10" font-size="13" font-family="DejaVu Sans Mono, Consolas, monospace" fill="#404040" text-anchor="start">{_dashboard_e(left_axis_label)}</text>'
    )
    if has_rail:
        svg_parts.append(
            f'<text x="{view_w - pad_r:.2f}" y="10" font-size="13" font-family="DejaVu Sans Mono, Consolas, monospace" fill="#404040" text-anchor="end">{_dashboard_e(_dashboard_format_pk(axis_end))}</text>'
        )

    for idx, track in enumerate(DASHBOARD_TEMP_ROAD_TRACKS):
        y = tracks_y0 + idx * (track_h + track_gap)
        fill = f'url(#hatch-{pattern_id})' if track["key"] == "no_work" else track["fill"]
        label = _dashboard_e(track["label"])
        svg_parts.append(
            f'<text x="{pad_l - 6:.2f}" y="{y + track_h / 2 + 3:.2f}" font-size="13" font-family="DejaVu Sans, Arial, sans-serif" fill="#404040" text-anchor="end">{label}</text>'
        )
        svg_parts.append(
            f'<rect x="{pad_l:.2f}" y="{y:.2f}" width="{draw_w:.2f}" height="{track_h:.2f}" fill="white" stroke="#d1d5db" stroke-width="0.6" />'
        )
        for pk, labelled in ticks:
            if not labelled:
                continue
            x = x_of(pk * 100)
            svg_parts.append(
                f'<line x1="{x:.2f}" y1="{y:.2f}" x2="{x:.2f}" y2="{y + track_h:.2f}" stroke="#e5e7eb" stroke-width="0.5" stroke-dasharray="2 2" />'
            )
        for seg in [row for row in painted if row["track"] == track["key"]]:
            x = x_of(seg["start"])
            width = max(0.8, x_of(seg["end"]) - x)
            opacity = "0.75" if seg["is_demo"] else "1"
            stroke = track["stroke"]
            svg_parts.append(
                f'<rect x="{x:.2f}" y="{y:.2f}" width="{width:.2f}" height="{track_h:.2f}" fill="{fill}" stroke="{stroke}" stroke-width="0.8" opacity="{opacity}" />'
            )

    svg_parts.append(
        f'<line x1="{pad_l:.2f}" y1="{axis_y:.2f}" x2="{view_w - pad_r:.2f}" y2="{axis_y:.2f}" stroke="#9ca3af" stroke-width="0.6" />'
    )
    for pk, labelled in ticks:
        x = x_of(pk * 100)
        tick_len = 5 if labelled else 3
        svg_parts.append(
            f'<line x1="{x:.2f}" y1="{axis_y:.2f}" x2="{x:.2f}" y2="{axis_y + tick_len:.2f}" stroke="#9ca3af" stroke-width="0.6" />'
        )
        if labelled:
            svg_parts.append(
                f'<text x="{x:.2f}" y="{axis_y + 15:.2f}" font-size="10" font-family="DejaVu Sans Mono, Consolas, monospace" fill="#6b7280" text-anchor="middle">ПК{pk}</text>'
            )
    svg_parts.append(
        f'<text x="{pad_l:.2f}" y="{bottom_y:.2f}" font-size="13" font-family="DejaVu Sans Mono, Consolas, monospace" fill="#404040" text-anchor="start">АД {_dashboard_e(_dashboard_format_pk(float(road.get("ad_pk_start") or 0)))}</text>'
    )
    svg_parts.append(
        f'<text x="{view_w - pad_r:.2f}" y="{bottom_y:.2f}" font-size="13" font-family="DejaVu Sans Mono, Consolas, monospace" fill="#404040" text-anchor="end">АД {_dashboard_e(_dashboard_format_pk(float(road.get("ad_pk_end") or 0)))}</text>'
    )
    svg_parts.append('</svg>')
    svg = ''.join(svg_parts)

    stats = (
        f'<div class="road-stats"><span><b>L</b><sub>готово</sub> = <span class="mono">{_dashboard_fmt(ready_len, 2)} м</span></span>'
        f'<span><b>%</b><sub>готово</sub> = <span class="mono">{_dashboard_fmt(ready_pct, 1)}%</span></span>'
        f'<span>срез: <span class="mono">{_dashboard_e(_dashboard_format_date(road.get("effective_date")))}</span></span></div>'
    )
    legend_items = []
    for track in DASHBOARD_TEMP_ROAD_TRACKS:
        fill_style = _dashboard_temp_road_legend_fill(track)
        stroke = track["stroke"]
        label = _dashboard_e(track["label"])
        total_label = _dashboard_fmt(totals.get(track["key"], 0.0), 2)
        legend_items.append(
            f'<span class="legend-chip"><span class="swatch" style="border:1px solid {stroke};background:{fill_style}"></span>{label}: <b class="mono">{total_label}</b> м</span>'
        )
    legend = ''.join(legend_items)
    title = f'{_dashboard_temp_road_title(road)} — {length_km:.2f} км'
    return f'<div class="road-card"><div class="road-title">{_dashboard_e(title)}</div>{svg}{stats}<div class="road-legend">{legend}</div></div>'


def _dashboard_render_temp_roads(data: dict) -> str:
    roads = data.get("roads") or []
    note = f'<div class="muted mono" style="margin-bottom:8px">{_dashboard_fmt(len(roads), 0)} АД · по состоянию на {_dashboard_e(_dashboard_format_date(data.get("as_of")))}</div>'
    legend_items = []
    for track in DASHBOARD_TEMP_ROAD_TRACKS:
        fill_style = _dashboard_temp_road_legend_fill(track)
        stroke = track["stroke"]
        label = _dashboard_e(track["label"])
        legend_items.append(
            f'<span class="legend-chip"><span class="swatch" style="border:1px solid {stroke};background:{fill_style}"></span>{label}</span>'
        )
    cards = ''.join(_dashboard_render_temp_road_card(road) for road in roads)
    if not cards:
        cards = '<div class="muted">Нет схем временных автодорог на выбранную дату.</div>'
    body = note + f'<div class="legend-row">{"".join(legend_items)}</div><div class="road-list">{cards}</div>'
    return _dashboard_section(
        "Схемы отсыпки временных автодорог",
        "▧",
        body,
        _dashboard_format_date(data.get("as_of")),
        break_before=True,
        allow_page_breaks=True,
    )


def _generate_dashboard_pdf_report(d_from: date_cls, d_to: date_cls) -> bytes:
    try:
        from weasyprint import HTML
    except Exception as exc:
        raise HTTPException(503, "PDF-экспорт дашборда недоступен: WeasyPrint не установлен") from exc

    try:
        from wip_analytics_routes import analytics_stockpile_balances, daily_summary
    except Exception as exc:
        raise HTTPException(500, f"Не удалось подключить аналитические модули PDF дашборда: {exc}") from exc

    date_from = d_from.isoformat()
    date_to = d_to.isoformat()
    try:
        daily = daily_summary(date_from=date_from, date_to=date_to)
        quarry_material = dashboard_material_flow(date_from=date_from, date_to=date_to)
        transfer_material = material_flow(date_from=date_from, date_to=date_to)
        pile_data = piles(date_from=date_from, date_to=date_to)
        pulse = overview_equipment_pulse(date_from=date_from, date_to=date_to)
        mech = mechanization_aggregates(date_from=date_from, date_to=date_to, bucket="own")
        staff = dashboard_staff_resources(date_from=date_from, date_to=date_to)
        stock = analytics_stockpile_balances(as_of=date_to)
        rig = dashboard_pile_rig_rating(date_from=date_from, date_to=date_to)
        temp_roads = _temp_roads_status_payload(date_to)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(500, f"Не удалось собрать данные PDF дашборда: {exc}") from exc

    generated_at = datetime.now().strftime("%d.%m.%Y %H:%M")
    blocks = [
        _dashboard_render_summary(daily, quarry_material.get("rows") or [], d_from, d_to),
        _dashboard_render_material(quarry_material),
        _dashboard_render_material_flow(
            transfer_material,
            kind="transfer",
            title="Перевозка",
            subtitle="накопитель / конструктив / внутренняя переброска",
        ),
        _dashboard_render_piles(pile_data),
        _dashboard_render_equipment_pulse(pulse),
        _dashboard_render_mechanization(mech),
        _dashboard_render_staff(staff),
        _dashboard_render_stockpiles(stock),
        _dashboard_render_pile_rigs(rig),
        _dashboard_render_temp_roads(temp_roads),
    ]
    html_doc = (
        f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Дашборд {_dashboard_period_label(d_from, d_to)}</title>'
        f'<style>{_dashboard_pdf_css()}</style></head><body><main class="shell"><div class="topbar"><div><h1>Дашборд</h1>'
        f'<div class="muted">Сводка по ключевым показателям за выбранный период</div></div><div class="mono muted">{_dashboard_e(_dashboard_period_label(d_from, d_to))}<br/>'
        f'сгенерировано: {_dashboard_e(generated_at)}</div></div>{"".join(blocks)}</main></body></html>'
    )
    return HTML(string=html_doc, base_url=os.getenv("VSM_FRONTEND_INTERNAL_URL", "/")).write_pdf()


@router.get("/dashboard/pdf")
def dashboard_pdf(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    _user=Depends(current_user),
):
    d_from, d_to = _parse_range(date_from, date_to)
    pdf_bytes = _generate_dashboard_pdf_report(d_from, d_to)
    ascii_name = f"VSM_Dashboard_generated_{d_from.isoformat()}_{d_to.isoformat()}.pdf"
    utf_name = f"Дашборд {d_from.strftime('%d.%m.%Y')}-{d_to.strftime('%d.%m.%Y')}.pdf"
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={"Content-Disposition": f"attachment; filename=\"{ascii_name}\"; filename*=UTF-8''{urllib.parse.quote(utf_name)}"},
    )

# ── piles ──────────────────────────────────────────────────────────────

@router.get("/piles")
def piles(
    section: Optional[str] = None,
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
):
    """
    Свайные работы. Группировка: участок × поле × field_type × pile_type.
    Привязка поля к участку — по PK через construction_section_versions.

    Период (`from`/`to`) сейчас не фильтрует: в схеме нет фактовой таблицы
    с датами забивки свай — pile_fields это статический каталог полей.
    Возвращаем поле `notes` с предупреждением, чтобы фронт мог показать.
    UCH_31 / UCH_32 схлопываем в UCH_3.
    """
    codes = _expand_sections(section)
    where = ["1=1"]
    params: list = []
    if codes:
        where.append(
            """
            EXISTS (
              SELECT 1
              FROM construction_section_versions csv
              JOIN construction_sections cs ON cs.id = csv.section_id
              WHERE csv.is_current = true
                AND csv.boundary_kind = 'piles_pipes'
                AND cs.code = ANY(%s)
                AND pf.pk_start >= csv.pk_start
                AND pf.pk_end   <= csv.pk_end
            )
            """
        )
        params.append(codes)

    rows = query(
        f"""
        SELECT
          pf.id, pf.field_code, pf.field_type, pf.pile_type,
          pf.pk_start, pf.pk_end,
          pf.pile_count, pf.dynamic_test_count,
          pf.is_demo,
          COALESCE(
            (SELECT cs.code
             FROM construction_section_versions csv
             JOIN construction_sections cs ON cs.id = csv.section_id
             WHERE csv.is_current = true
               AND csv.boundary_kind = 'piles_pipes'
               AND pf.pk_start >= csv.pk_start
               AND pf.pk_end   <= csv.pk_end
             ORDER BY csv.pk_start LIMIT 1),
            '—'
          ) AS section_code
        FROM pile_fields pf
        WHERE {' AND '.join(where)}
        ORDER BY pf.pk_start
        """,
        params,
    )

    for r in rows:
        r["pk_start"] = float(r["pk_start"]) if r["pk_start"] is not None else None
        r["pk_end"] = float(r["pk_end"]) if r["pk_end"] is not None else None
        r["section_code"] = _merge_section(r.get("section_code")) or r.get("section_code")

    def _pile_fact_rows(from_date: date_cls, to_date: date_cls) -> tuple[dict[str, dict[str, float]], dict[str, float]]:
        where_dwi = ["dwi.report_date >= %s", "dwi.report_date <= %s", _approved_report_exists("dwi")]
        p_dwi: list = [from_date, to_date]
        if codes:
            where_dwi.append("cs_eff_piles.code = ANY(%s)")
            p_dwi.append(codes)
        fact_rows = query(
            f"""
            SELECT cs_eff_piles.code AS section_code, wt.code AS wt_code,
                   SUM({_pile_effective_volume_expr('seg_piles')})::numeric AS cnt
            FROM daily_work_items dwi
            JOIN daily_reports dr ON dr.id = dwi.daily_report_id
            JOIN work_types wt ON wt.id = dwi.work_type_id
            {_pile_effective_section_join('seg_piles', 'cs_eff_piles', 'cs_report_piles')}
            WHERE {' AND '.join(where_dwi)}
              AND wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
            GROUP BY cs_eff_piles.code, wt.code
            """,
            p_dwi,
        )
        by_sec: dict[str, dict[str, float]] = {}
        for f in fact_rows:
            sec = _merge_section(f["section_code"]) or "—"
            by_sec.setdefault(sec, {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0})
            if f["wt_code"] == "PILE_MAIN":
                by_sec[sec]["main"] += float(f["cnt"] or 0)
            elif f["wt_code"] == "PILE_TRIAL":
                by_sec[sec]["test"] += float(f["cnt"] or 0)
            elif f["wt_code"] == "PILE_DYNTEST":
                by_sec[sec]["dyn"] += float(f["cnt"] or 0)
            elif f["wt_code"] == "PILE_HEADCAP_INSTALLATION":
                by_sec[sec]["headcaps"] += float(f["cnt"] or 0)

        totals = {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0}
        for sec_facts in by_sec.values():
            for k, v in sec_facts.items():
                totals[k] += v
        return by_sec, totals

    # Факт забивки свай за период — из daily_work_items по PILE_* work_types.
    d_from, d_to = _parse_range(date_from, date_to)
    fact_by_sec, fact_totals = _pile_fact_rows(d_from, d_to)
    cumulative_by_sec, cumulative_totals = _pile_fact_rows(PROJECT_START_DATE, d_to)
    plan_where = ["ppp.period_start <= %s", "ppp.period_end >= %s"]
    plan_params: list = [d_to, d_from]
    if codes:
        plan_where.append("cs.code = ANY(%s)")
        plan_params.append(codes)
    plan_rows = query(
        f"""
        SELECT cs.code AS section_code,
               SUM(COALESCE(ppp.planned_main_piles, 0))::numeric AS main_cnt,
               SUM(COALESCE(ppp.planned_test_piles, 0))::numeric AS test_cnt,
               SUM(COALESCE(ppp.planned_dynamic_tests, 0))::numeric AS dyn_cnt,
               SUM(COALESCE(ppp.planned_headcaps, 0))::numeric AS headcap_cnt
        FROM pile_plan_periods ppp
        JOIN construction_sections cs ON cs.id = ppp.section_id
        WHERE {' AND '.join(plan_where)}
        GROUP BY cs.code
        """,
        plan_params,
    )
    plan_by_sec: dict[str, dict[str, float]] = {}
    plan_totals = {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0}
    for row in plan_rows:
        sec = _merge_section(row.get("section_code")) or "—"
        slot = plan_by_sec.setdefault(sec, {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0})
        slot["main"] += float(row.get("main_cnt") or 0)
        slot["test"] += float(row.get("test_cnt") or 0)
        slot["dyn"] += float(row.get("dyn_cnt") or 0)
        slot["headcaps"] += float(row.get("headcap_cnt") or 0)
    for slot in plan_by_sec.values():
        for key in plan_totals:
            plan_totals[key] += slot[key]

    return {
        "rows": rows,
        "fact_by_section": fact_by_sec,
        "fact_totals": fact_totals,
        "plan_by_section": plan_by_sec,
        "plan_totals": plan_totals,
        "cumulative_by_section": cumulative_by_sec,
        "cumulative_totals": cumulative_totals,
        "period": {"from": d_from.isoformat(), "to": d_to.isoformat()},
    }


@router.get("/reinforcement-sections/summary")
def reinforcement_sections_summary(
    date: Optional[str] = None,
    mode: str = "cumulative",
):
    """Участки усиления: факт забивки свай + календарный план из pile_plan_periods."""
    as_of = date_cls.fromisoformat(date) if date else date_cls.today()
    if mode not in ("cumulative", "date"):
        raise HTTPException(400, "mode должен быть cumulative|date")

    month_start = as_of.replace(day=1)
    next_month = (
        month_start.replace(year=month_start.year + 1, month=1)
        if month_start.month == 12
        else month_start.replace(month=month_start.month + 1)
    )
    month_end = next_month - timedelta(days=1)
    section_codes = [f"UCH_{i}" for i in range(1, 9)]
    query_section_codes = ["UCH_1", "UCH_2", "UCH_3", "UCH_31", "UCH_32", "UCH_4", "UCH_5", "UCH_6", "UCH_7", "UCH_8"]

    kpi_where = ["wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')", "cs_eff_kpi.code = ANY(%s)", _approved_report_exists("dwi")]
    kpi_params: list = [query_section_codes]
    if mode == "date":
        kpi_where.append("dwi.report_date = %s")
        kpi_params.append(as_of)
    else:
        kpi_where.append("dwi.report_date <= %s")
        kpi_params.append(as_of)
    kpi_rows = query(
        f"""
        SELECT cs_eff_kpi.code AS section_code, wt.code AS wt_code, SUM({_pile_effective_volume_expr('seg_kpi')})::numeric AS cnt
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        {_pile_effective_section_join('seg_kpi', 'cs_eff_kpi', 'cs_report_kpi')}
        WHERE {' AND '.join(kpi_where)}
        GROUP BY cs_eff_kpi.code, wt.code
        """,
        kpi_params,
    )
    by_section: dict[str, dict[str, float]] = {code: {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0} for code in section_codes}
    for row in kpi_rows:
        code = _merge_section(row.get("section_code")) or ""
        if code not in by_section:
            continue
        if row.get("wt_code") == "PILE_TRIAL":
            key = "test"
        elif row.get("wt_code") == "PILE_DYNTEST":
            key = "dyn"
        elif row.get("wt_code") == "PILE_HEADCAP_INSTALLATION":
            key = "headcaps"
        else:
            key = "main"
        by_section[code][key] += float(row.get("cnt") or 0)

    plan_by_section: dict[str, dict[str, float]] = {code: {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0} for code in section_codes}
    if mode == "date":
        plan_rows = query(
            """
            SELECT cs.code AS section_code,
                   SUM(COALESCE(ppp.planned_main_piles, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS main_cnt,
                   SUM(COALESCE(ppp.planned_test_piles, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS test_cnt,
                   SUM(COALESCE(ppp.planned_dynamic_tests, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS dyn_cnt,
                   SUM(COALESCE(ppp.planned_headcaps, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS headcap_cnt
            FROM pile_plan_periods ppp
            JOIN construction_sections cs ON cs.id = ppp.section_id
            WHERE cs.code = ANY(%s)
              AND ppp.period_start <= %s
              AND ppp.period_end >= %s
            GROUP BY cs.code
            """,
            [query_section_codes, as_of, as_of],
        )
    else:
        plan_rows = query(
            """
            SELECT cs.code AS section_code,
                   SUM(COALESCE(ppp.planned_main_piles, 0)::numeric
                       * GREATEST((LEAST(ppp.period_end, %s::date) - ppp.period_start + 1), 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS main_cnt,
                   SUM(COALESCE(ppp.planned_test_piles, 0)::numeric
                       * GREATEST((LEAST(ppp.period_end, %s::date) - ppp.period_start + 1), 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS test_cnt,
                   SUM(COALESCE(ppp.planned_dynamic_tests, 0)::numeric
                       * GREATEST((LEAST(ppp.period_end, %s::date) - ppp.period_start + 1), 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS dyn_cnt,
                   SUM(COALESCE(ppp.planned_headcaps, 0)::numeric
                       * GREATEST((LEAST(ppp.period_end, %s::date) - ppp.period_start + 1), 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS headcap_cnt
            FROM pile_plan_periods ppp
            JOIN construction_sections cs ON cs.id = ppp.section_id
            WHERE cs.code = ANY(%s)
              AND ppp.period_start <= %s
            GROUP BY cs.code
            """,
            [as_of, as_of, as_of, as_of, query_section_codes, as_of],
        )
    for row in plan_rows:
        code = _merge_section(row.get("section_code")) or ""
        if code not in plan_by_section:
            continue
        plan_by_section[code]["main"] += float(row.get("main_cnt") or 0)
        plan_by_section[code]["test"] += float(row.get("test_cnt") or 0)
        plan_by_section[code]["dyn"] += float(row.get("dyn_cnt") or 0)
        plan_by_section[code]["headcaps"] += float(row.get("headcap_cnt") or 0)
    project_by_section, project_detail_by_section = _reinforcement_project_pile_data(query_section_codes, section_codes)

    days = [(month_start + timedelta(days=i)).isoformat() for i in range((month_end - month_start).days + 1)]
    matrix: dict[str, dict[str, dict[str, Any]]] = {
        code: {
            day: {
                "main": 0.0,
                "test": 0.0,
                "dyn": 0.0,
                "headcaps": 0.0,
                "total": 0.0,
                "plan_main": 0.0,
                "plan_test": 0.0,
                "plan_dyn": 0.0,
                "plan_headcaps": 0.0,
                "plan_total": 0.0,
                "fact_lengths": [],
                "fact_details": [],
                "plan_details": [],
            }
            for day in days
        }
        for code in section_codes
    }
    fact_length_map: dict[str, dict[str, dict[Optional[int], float]]] = {
        code: {day: {} for day in days}
        for code in section_codes
    }

    def _add_fact_length(code: str, day: str, length_m: Optional[int], amount: float) -> None:
        if amount <= 0 or code not in fact_length_map or day not in fact_length_map[code]:
            return
        bucket = fact_length_map[code][day]
        bucket[length_m] = bucket.get(length_m, 0.0) + amount

    def _serialize_fact_lengths(bucket: dict[Optional[int], float]) -> list[dict[str, Any]]:
        items = [
            {"length_m": int(length), "count": float(bucket[length])}
            for length in sorted(length for length in bucket if length is not None)
            if float(bucket.get(length) or 0) > 0
        ]
        unknown_count = float(bucket.get(None) or 0)
        if unknown_count > 0:
            items.append({"length_m": None, "count": unknown_count})
        return items

    def _totals_fact_lengths(day: str) -> list[dict[str, Any]]:
        merged: dict[Optional[int], float] = {}
        for code in section_codes:
            for length_m, amount in fact_length_map[code][day].items():
                merged[length_m] = merged.get(length_m, 0.0) + float(amount or 0)
        return _serialize_fact_lengths(merged)
    calendar_rows = query(
        f"""
        SELECT cs_eff_calendar.code AS section_code, dwi.report_date AS d, wt.code AS wt_code, SUM({_pile_effective_volume_expr('seg_calendar')})::numeric AS cnt
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        {_pile_effective_section_join('seg_calendar', 'cs_eff_calendar', 'cs_report_calendar')}
        WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
          AND cs_eff_calendar.code = ANY(%s)
          AND dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        GROUP BY cs_eff_calendar.code, dwi.report_date, wt.code
        """,
        [query_section_codes, month_start, month_end],
    )
    for row in calendar_rows:
        code = _merge_section(row.get("section_code")) or ""
        day = row.get("d").isoformat()
        if code not in matrix or day not in matrix[code]:
            continue
        if row.get("wt_code") == "PILE_TRIAL":
            key = "test"
        elif row.get("wt_code") == "PILE_DYNTEST":
            key = "dyn"
        elif row.get("wt_code") == "PILE_HEADCAP_INSTALLATION":
            key = "headcaps"
        else:
            key = "main"
        cnt = float(row.get("cnt") or 0)
        matrix[code][day][key] += cnt
        # `total` on the reinforcement dashboard means driven piles only.
        # Dynamic tests and headcaps are separate operational buckets, not piles.
        if key in {"main", "test"}:
            matrix[code][day]["total"] += cnt

    calendar_fact_detail_rows = query(
        f"""
        SELECT cs_eff_day_detail.code AS section_code,
               dwi.report_date AS d,
               COALESCE(NULLIF(seg_day_detail_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д') AS field_name,
               COALESCE(seg_day_detail.pk_start, seg_day_detail_pf.pk_start) AS pk_start,
               COALESCE(seg_day_detail.pk_end, seg_day_detail_pf.pk_end) AS pk_end,
               COALESCE(NULLIF(seg_day_detail.pk_raw_text, ''), NULLIF(seg_day_detail_pf.pk_raw_text, '')) AS pk_raw_text,
               SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN {_pile_effective_volume_expr('seg_day_detail')} ELSE 0 END)::numeric AS main_cnt,
               SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN {_pile_effective_volume_expr('seg_day_detail')} ELSE 0 END)::numeric AS test_cnt,
               SUM(CASE WHEN wt.code = 'PILE_DYNTEST' THEN {_pile_effective_volume_expr('seg_day_detail')} ELSE 0 END)::numeric AS dyn_cnt,
               SUM(CASE WHEN wt.code = 'PILE_HEADCAP_INSTALLATION' THEN {_pile_effective_volume_expr('seg_day_detail')} ELSE 0 END)::numeric AS headcap_cnt,
               COUNT(DISTINCT dwi.daily_report_id)::int AS report_count
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        {_pile_effective_section_join('seg_day_detail', 'cs_eff_day_detail', 'cs_report_day_detail')}
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
          AND cs_eff_day_detail.code = ANY(%s)
          AND dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        GROUP BY cs_eff_day_detail.code,
                 dwi.report_date,
                 COALESCE(NULLIF(seg_day_detail_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д'),
                 COALESCE(seg_day_detail.pk_start, seg_day_detail_pf.pk_start),
                 COALESCE(seg_day_detail.pk_end, seg_day_detail_pf.pk_end),
                 COALESCE(NULLIF(seg_day_detail.pk_raw_text, ''), NULLIF(seg_day_detail_pf.pk_raw_text, ''))
        ORDER BY cs_eff_day_detail.code,
                 dwi.report_date,
                 COALESCE(NULLIF(seg_day_detail_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д'),
                 COALESCE(seg_day_detail.pk_start, seg_day_detail_pf.pk_start) NULLS LAST
        """,
        [query_section_codes, month_start, month_end],
    )
    calendar_pile_rigs_by_field_day = _reinforcement_pile_rig_refs_by_field(
        month_start,
        month_end,
        query_section_codes,
        section_codes,
        include_day=True,
    )

    def _calendar_detail_from_row(row: dict, code: str) -> Optional[dict]:
        main_cnt = float(row.get("main_cnt") or 0)
        test_cnt = float(row.get("test_cnt") or 0)
        dyn_cnt = float(row.get("dyn_cnt") or 0)
        headcap_cnt = float(row.get("headcap_cnt") or 0)
        total_cnt = main_cnt + test_cnt
        if total_cnt <= 0 and dyn_cnt <= 0 and headcap_cnt <= 0:
            return None
        pk_range = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text")) or "ПК н/д"
        day_value = row.get("d")
        day_iso = day_value.isoformat() if hasattr(day_value, "isoformat") else str(day_value or "") or None
        field_name = row.get("field_name") or "Поле н/д"
        return {
            "section_code": code,
            "field_name": field_name,
            "pk_range": pk_range,
            "pk_ranges": [pk_range],
            "main": main_cnt,
            "test": test_cnt,
            "dyn": dyn_cnt,
            "headcaps": headcap_cnt,
            "total": total_cnt,
            "report_count": int(row.get("report_count") or 0),
            "first_date": day_iso,
            "last_date": day_iso,
            "segments": 1,
            "pile_rigs": calendar_pile_rigs_by_field_day.get((code, day_iso or "", field_name), []) if total_cnt > 0 else [],
        }

    for row in calendar_fact_detail_rows:
        code = _merge_section(row.get("section_code")) or ""
        day = row.get("d").isoformat()
        if code not in matrix or day not in matrix[code]:
            continue
        detail = _calendar_detail_from_row(row, code)
        if detail:
            matrix[code][day]["fact_details"].append(detail)

    length_calendar_rows = query(
        f"""
        SELECT cs_eff_length_calendar.code AS section_code,
               dwi.report_date AS d,
               wt.code AS wt_code,
               pf.pile_type,
               SUM(
                 CASE
                   WHEN ds.volume_segment IS NOT NULL THEN COALESCE(ds.volume_segment, 0)
                   WHEN seg_length_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_length_count.cnt
                   ELSE COALESCE(dwi.volume, 0)
                 END
               )::numeric AS cnt
        FROM daily_work_item_segments ds
        JOIN daily_work_items dwi ON dwi.id = ds.daily_work_item_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        LEFT JOIN pile_fields pf ON pf.id = ds.pile_field_id
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_length_count ON true
        LEFT JOIN construction_sections cs_report_length_calendar ON cs_report_length_calendar.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = 'piles_pipes'
            AND COALESCE(
              (COALESCE(ds.pk_start, pf.pk_start) + COALESCE(ds.pk_end, pf.pk_end)) / 2.0,
              COALESCE(ds.pk_start, pf.pk_start),
              COALESCE(ds.pk_end, pf.pk_end)
            ) >= LEAST(csv.pk_start, csv.pk_end)
            AND COALESCE(
              (COALESCE(ds.pk_start, pf.pk_start) + COALESCE(ds.pk_end, pf.pk_end)) / 2.0,
              COALESCE(ds.pk_start, pf.pk_start),
              COALESCE(ds.pk_end, pf.pk_end)
            ) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_length_calendar_section ON true
        LEFT JOIN construction_sections cs_eff_length_calendar
          ON cs_eff_length_calendar.id = COALESCE(effective_length_calendar_section.section_id, cs_report_length_calendar.id)
         AND cs_eff_length_calendar.is_active IS NOT FALSE
        WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
          AND cs_eff_length_calendar.code = ANY(%s)
          AND dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(ds.is_demo, false) IS FALSE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        GROUP BY cs_eff_length_calendar.code, dwi.report_date, wt.code, pf.pile_type
        """,
        [query_section_codes, month_start, month_end],
    )
    for row in length_calendar_rows:
        code = _merge_section(row.get("section_code")) or ""
        day = row.get("d").isoformat()
        if code not in matrix or day not in matrix[code]:
            continue
        amount = float(row.get("cnt") or 0)
        _add_fact_length(code, day, _pile_length_from_type(row.get("pile_type")), amount)

    pipe_length_calendar_rows = query(
        f"""
        WITH specs AS (
            SELECT pps.object_id,
                   pps.work_type_id,
                   pps.pile_length_m,
                   COALESCE(pps.quantity, 0)::numeric AS quantity,
                   SUM(COALESCE(pps.quantity, 0)) OVER (PARTITION BY pps.object_id, pps.work_type_id) AS total_quantity
            FROM pipe_pile_specs pps
            WHERE COALESCE(pps.is_active, true) IS TRUE
        )
        SELECT cs.code AS section_code,
               dwi.report_date AS d,
               wt.code AS wt_code,
               specs.pile_length_m,
               SUM(
                   dwi.volume * CASE
                       WHEN specs.total_quantity > 0 THEN specs.quantity / specs.total_quantity
                       ELSE 1
                   END
               )::numeric AS cnt
        FROM daily_work_items dwi
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN specs ON specs.object_id = dwi.object_id AND specs.work_type_id = dwi.work_type_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr.section_id)
        WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
          AND specs.pile_length_m IS NOT NULL
          AND cs.code = ANY(%s)
          AND dwi.report_date BETWEEN %s AND %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        GROUP BY cs.code, dwi.report_date, wt.code, specs.pile_length_m
        """,
        [query_section_codes, month_start, month_end],
    )
    for row in pipe_length_calendar_rows:
        code = _merge_section(row.get("section_code")) or ""
        day = row.get("d").isoformat()
        if code not in matrix or day not in matrix[code]:
            continue
        amount = float(row.get("cnt") or 0)
        _add_fact_length(code, day, _pile_length_from_type(row.get("pile_length_m")), amount)

    for code in section_codes:
        for day in days:
            matrix[code][day]["fact_lengths"] = _serialize_fact_lengths(fact_length_map[code][day])

    calendar_plan_rows = query(
        """
        SELECT cs.code AS section_code, gs.day::date AS d,
               SUM(COALESCE(ppp.planned_main_piles, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS main_cnt,
               SUM(COALESCE(ppp.planned_test_piles, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS test_cnt,
               SUM(COALESCE(ppp.planned_dynamic_tests, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS dyn_cnt,
               SUM(COALESCE(ppp.planned_headcaps, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS headcap_cnt
        FROM pile_plan_periods ppp
        JOIN construction_sections cs ON cs.id = ppp.section_id
        JOIN LATERAL generate_series(
            GREATEST(ppp.period_start, %s::date),
            LEAST(ppp.period_end, %s::date),
            interval '1 day'
        ) AS gs(day) ON true
        WHERE cs.code = ANY(%s)
          AND ppp.period_start <= %s
          AND ppp.period_end >= %s
        GROUP BY cs.code, gs.day::date
        """,
        [month_start, month_end, query_section_codes, month_end, month_start],
    )
    for row in calendar_plan_rows:
        code = _merge_section(row.get("section_code")) or ""
        day = row.get("d").isoformat()
        if code not in matrix or day not in matrix[code]:
            continue
        main_plan = float(row.get("main_cnt") or 0)
        test_plan = float(row.get("test_cnt") or 0)
        dyn_plan = float(row.get("dyn_cnt") or 0)
        headcap_plan = float(row.get("headcap_cnt") or 0)
        matrix[code][day]["plan_main"] += main_plan
        matrix[code][day]["plan_test"] += test_plan
        matrix[code][day]["plan_dyn"] += dyn_plan
        matrix[code][day]["plan_headcaps"] += headcap_plan
        # Day plan in this tab is the pile-driving plan (main + trial).
        # Dynamic tests are exposed as `plan_dyn` but must not inflate pile totals.
        matrix[code][day]["plan_total"] += main_plan + test_plan

    calendar_plan_detail_rows = query(
        """
        SELECT cs_plan_detail.code AS section_code,
               gs.day::date AS d,
               COALESCE(NULLIF(pf.field_code, ''), 'План участка') AS field_name,
               pf.pk_start AS pk_start,
               pf.pk_end AS pk_end,
               NULLIF(pf.pk_raw_text, '') AS pk_raw_text,
               SUM(COALESCE(ppp.planned_main_piles, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS main_cnt,
               SUM(COALESCE(ppp.planned_test_piles, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS test_cnt,
               SUM(COALESCE(ppp.planned_dynamic_tests, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS dyn_cnt,
               SUM(COALESCE(ppp.planned_headcaps, 0)::numeric
                   / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS headcap_cnt,
               COUNT(DISTINCT ppp.id)::int AS report_count
        FROM pile_plan_periods ppp
        LEFT JOIN pile_fields pf ON pf.id = ppp.pile_field_id
        LEFT JOIN construction_sections cs_direct_plan_detail ON cs_direct_plan_detail.id = ppp.section_id
        LEFT JOIN LATERAL (
          SELECT COALESCE(
            (pf.pk_start + pf.pk_end) / 2.0,
            pf.pk_start,
            pf.pk_end
          ) AS pk_mid
        ) plan_detail_pk ON true
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = 'piles_pipes'
            AND plan_detail_pk.pk_mid IS NOT NULL
            AND plan_detail_pk.pk_mid >= LEAST(csv.pk_start, csv.pk_end)
            AND plan_detail_pk.pk_mid < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) plan_detail_section ON true
        LEFT JOIN construction_sections cs_plan_detail
          ON cs_plan_detail.id = COALESCE(cs_direct_plan_detail.id, plan_detail_section.section_id)
         AND cs_plan_detail.is_active IS NOT FALSE
        JOIN LATERAL generate_series(
            GREATEST(ppp.period_start, %s::date),
            LEAST(ppp.period_end, %s::date),
            interval '1 day'
        ) AS gs(day) ON true
        WHERE cs_plan_detail.code = ANY(%s)
          AND ppp.period_start <= %s
          AND ppp.period_end >= %s
        GROUP BY cs_plan_detail.code,
                 gs.day::date,
                 COALESCE(NULLIF(pf.field_code, ''), 'План участка'),
                 pf.pk_start,
                 pf.pk_end,
                 NULLIF(pf.pk_raw_text, '')
        ORDER BY cs_plan_detail.code,
                 gs.day::date,
                 COALESCE(NULLIF(pf.field_code, ''), 'План участка'),
                 pf.pk_start NULLS LAST
        """,
        [month_start, month_end, query_section_codes, month_end, month_start],
    )
    for row in calendar_plan_detail_rows:
        code = _merge_section(row.get("section_code")) or ""
        day = row.get("d").isoformat()
        if code not in matrix or day not in matrix[code]:
            continue
        detail = _calendar_detail_from_row(row, code)
        if detail:
            matrix[code][day]["plan_details"].append(detail)

    month_plan_by_section = {
        code: {
            "main": sum(matrix[code][day]["plan_main"] for day in days),
            "test": sum(matrix[code][day]["plan_test"] for day in days),
            "dyn": sum(matrix[code][day]["plan_dyn"] for day in days),
            "headcaps": sum(matrix[code][day]["plan_headcaps"] for day in days),
        }
        for code in section_codes
    }

    sections = []
    for idx, code in enumerate(section_codes, start=1):
        main = by_section[code]["main"]
        test = by_section[code]["test"]
        dyn_fact = by_section[code]["dyn"]
        headcaps_fact = by_section[code]["headcaps"]
        plan_main = plan_by_section[code]["main"]
        plan_test = plan_by_section[code]["test"]
        plan_dyn = plan_by_section[code]["dyn"]
        plan_headcaps = plan_by_section[code]["headcaps"]
        month_plan_main = month_plan_by_section[code]["main"]
        month_plan_test = month_plan_by_section[code]["test"]
        month_plan_dyn = month_plan_by_section[code]["dyn"]
        month_plan_headcaps = month_plan_by_section[code]["headcaps"]
        project_main = project_by_section[code]["main"]
        project_test = project_by_section[code]["test"]
        project_dyn = project_by_section[code]["dyn"]
        # Dashboard/report "total" for reinforcement sections is driven piles.
        # Keep dynamic tests in the separate dyn fields, but exclude them from pile totals.
        total = main + test
        plan_total = plan_main + plan_test
        month_plan_total = month_plan_main + month_plan_test
        project_total = project_main + project_test
        sections.append({
            "code": code,
            "label": f"Участок №{idx}",
            "main": main,
            "test": test,
            "dyn": dyn_fact,
            "headcaps": headcaps_fact,
            "total": total,
            "plan_main": plan_main,
            "plan_test": plan_test,
            "plan_dyn": plan_dyn,
            "plan_headcaps": plan_headcaps,
            "plan_total": plan_total,
            "month_plan_main": month_plan_main,
            "month_plan_test": month_plan_test,
            "month_plan_dyn": month_plan_dyn,
            "month_plan_headcaps": month_plan_headcaps,
            "month_plan_total": month_plan_total,
            "project_main": project_main,
            "project_test": project_test,
            "project_dyn": project_dyn,
            "project_total": project_total,
            "delta": total - plan_total,
            "month_delta": total - month_plan_total,
            "project_delta": total - project_total,
        })
    totals_by_day = {
        day: {
            "main": sum(matrix[code][day]["main"] for code in section_codes),
            "test": sum(matrix[code][day]["test"] for code in section_codes),
            "dyn": sum(matrix[code][day]["dyn"] for code in section_codes),
            "headcaps": sum(matrix[code][day]["headcaps"] for code in section_codes),
            "total": sum(matrix[code][day]["total"] for code in section_codes),
            "plan_main": sum(matrix[code][day]["plan_main"] for code in section_codes),
            "plan_test": sum(matrix[code][day]["plan_test"] for code in section_codes),
            "plan_dyn": sum(matrix[code][day]["plan_dyn"] for code in section_codes),
            "plan_headcaps": sum(matrix[code][day]["plan_headcaps"] for code in section_codes),
            "plan_total": sum(matrix[code][day]["plan_total"] for code in section_codes),
            "fact_lengths": _totals_fact_lengths(day),
            "fact_details": [detail for code in section_codes for detail in matrix[code][day].get("fact_details", [])],
            "plan_details": [detail for code in section_codes for detail in matrix[code][day].get("plan_details", [])],
        }
        for day in days
    }

    details: Optional[dict[str, dict[str, list[dict]]]] = None
    if mode == "cumulative":
        def detail_rows(date_from: date_cls, date_to: date_cls, *, include_project: bool = False) -> dict[str, list[dict]]:
            pile_rigs_by_field = _reinforcement_pile_rig_refs_by_field(
                date_from,
                date_to,
                query_section_codes,
                section_codes,
            )
            rows = query(
                f"""
                SELECT cs_eff_detail.code AS section_code,
                       COALESCE(NULLIF(seg_detail_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д') AS field_name,
                       COALESCE(seg_detail.pk_start, seg_detail_pf.pk_start) AS pk_start,
                       COALESCE(seg_detail.pk_end, seg_detail_pf.pk_end) AS pk_end,
                       COALESCE(NULLIF(seg_detail.pk_raw_text, ''), NULLIF(seg_detail_pf.pk_raw_text, '')) AS pk_raw_text,
                       SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN {_pile_effective_volume_expr('seg_detail')} ELSE 0 END)::numeric AS main_cnt,
                       SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN {_pile_effective_volume_expr('seg_detail')} ELSE 0 END)::numeric AS test_cnt,
                       SUM(CASE WHEN wt.code = 'PILE_DYNTEST' THEN {_pile_effective_volume_expr('seg_detail')} ELSE 0 END)::numeric AS dyn_cnt,
                       SUM(CASE WHEN wt.code = 'PILE_HEADCAP_INSTALLATION' THEN {_pile_effective_volume_expr('seg_detail')} ELSE 0 END)::numeric AS headcap_cnt,
                       COUNT(DISTINCT dwi.daily_report_id)::int AS report_count,
                       ARRAY_AGG(DISTINCT dwi.daily_report_id::text) AS report_ids,
                       MIN(dwi.report_date) AS first_date,
                       MAX(dwi.report_date) AS last_date
                FROM daily_work_items dwi
                JOIN daily_reports dr ON dr.id = dwi.daily_report_id
                JOIN work_types wt ON wt.id = dwi.work_type_id
                {_pile_effective_section_join('seg_detail', 'cs_eff_detail', 'cs_report_detail')}
                LEFT JOIN objects obj ON obj.id = dwi.object_id
                WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
                  AND cs_eff_detail.code = ANY(%s)
                  AND dwi.report_date BETWEEN %s AND %s
                  AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
                  AND NOT (
                    COALESCE(dr.source_type, '') = 'web_pile_control'
                    OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
                  )
                GROUP BY cs_eff_detail.code,
                         COALESCE(NULLIF(seg_detail_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д'),
                         COALESCE(seg_detail.pk_start, seg_detail_pf.pk_start),
                         COALESCE(seg_detail.pk_end, seg_detail_pf.pk_end),
                         COALESCE(NULLIF(seg_detail.pk_raw_text, ''), NULLIF(seg_detail_pf.pk_raw_text, ''))
                ORDER BY cs_eff_detail.code,
                         COALESCE(NULLIF(seg_detail_pf.field_code, ''), NULLIF(obj.name, ''), NULLIF(obj.object_code, ''), 'Поле н/д'),
                         COALESCE(seg_detail.pk_start, seg_detail_pf.pk_start) NULLS LAST
                """,
                [query_section_codes, date_from, date_to],
            )
            merged: dict[str, dict[str, dict]] = {code: {} for code in section_codes}

            def ensure_detail_entry(code: str, field_name: str) -> dict:
                return merged[code].setdefault(field_name, {
                    "section_code": code,
                    "field_name": field_name,
                    "pk_ranges": [],
                    "main": 0.0,
                    "test": 0.0,
                    "dyn": 0.0,
                    "headcaps": 0.0,
                    "project_main": 0.0,
                    "project_test": 0.0,
                    "project_dyn": 0.0,
                    "_report_ids": set(),
                    "_report_count_fallback": 0,
                    "_first_date": None,
                    "_last_date": None,
                    "_sort_pk": None,
                })

            if include_project:
                for code, project_rows in project_detail_by_section.items():
                    if code not in merged:
                        continue
                    for project_row in project_rows:
                        field_name = project_row.get("field_name") or "Поле н/д"
                        entry = ensure_detail_entry(code, field_name)
                        entry["project_main"] += float(project_row.get("project_main") or 0)
                        entry["project_test"] += float(project_row.get("project_test") or 0)
                        entry["project_dyn"] += float(project_row.get("project_dyn") or 0)
                        for pk_range in project_row.get("pk_ranges") or []:
                            if pk_range and pk_range not in entry["pk_ranges"]:
                                entry["pk_ranges"].append(pk_range)

            for row in rows:
                code = _merge_section(row.get("section_code")) or ""
                if code not in merged:
                    continue
                field_name = row.get("field_name") or "Поле н/д"
                entry = ensure_detail_entry(code, field_name)
                entry["main"] += float(row.get("main_cnt") or 0)
                entry["test"] += float(row.get("test_cnt") or 0)
                entry["dyn"] += float(row.get("dyn_cnt") or 0)
                entry["headcaps"] += float(row.get("headcap_cnt") or 0)
                entry["_report_count_fallback"] += int(row.get("report_count") or 0)
                for report_id in row.get("report_ids") or []:
                    if report_id:
                        entry["_report_ids"].add(str(report_id))
                pk_range = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text")) or "ПК н/д"
                if pk_range not in entry["pk_ranges"]:
                    entry["pk_ranges"].append(pk_range)
                pk_start = row.get("pk_start")
                if pk_start is not None and (entry["_sort_pk"] is None or pk_start < entry["_sort_pk"]):
                    entry["_sort_pk"] = pk_start
                first_date = row.get("first_date")
                last_date = row.get("last_date")
                if first_date and (entry["_first_date"] is None or first_date < entry["_first_date"]):
                    entry["_first_date"] = first_date
                if last_date and (entry["_last_date"] is None or last_date > entry["_last_date"]):
                    entry["_last_date"] = last_date

            mapped: dict[str, list[dict]] = {code: [] for code in section_codes}
            for code, by_field in merged.items():
                for entry in by_field.values():
                    total_cnt = float(entry["main"] or 0) + float(entry["test"] or 0)
                    dyn_cnt = float(entry["dyn"] or 0)
                    headcap_cnt = float(entry["headcaps"] or 0)
                    project_main = float(entry.get("project_main") or 0)
                    project_test = float(entry.get("project_test") or 0)
                    project_dyn = float(entry.get("project_dyn") or 0)
                    project_total = project_main + project_test
                    if total_cnt <= 0 and dyn_cnt <= 0 and headcap_cnt <= 0 and project_total <= 0 and project_dyn <= 0:
                        continue
                    pk_ranges = entry.get("pk_ranges") or ["ПК н/д"]
                    display_pk = "; ".join(pk_ranges[:3])
                    if len(pk_ranges) > 3:
                        display_pk = f"{display_pk}; +{len(pk_ranges) - 3}"
                    report_ids = entry.get("_report_ids") or set()
                    first_date = entry.get("_first_date")
                    last_date = entry.get("_last_date")
                    field_name = entry.get("field_name") or "Поле н/д"
                    mapped[code].append({
                        "section_code": code,
                        "field_name": field_name,
                        "pk_range": display_pk or "ПК н/д",
                        "pk_ranges": pk_ranges,
                        "main": float(entry["main"] or 0),
                        "test": float(entry["test"] or 0),
                        "dyn": dyn_cnt,
                        "headcaps": headcap_cnt,
                        "total": total_cnt,
                        "project_main": project_main,
                        "project_test": project_test,
                        "project_dyn": project_dyn,
                        "project_total": project_total,
                        "report_count": len(report_ids) if report_ids else int(entry.get("_report_count_fallback") or 0),
                        "first_date": first_date.isoformat() if first_date else None,
                        "last_date": last_date.isoformat() if last_date else None,
                        "segments": len(pk_ranges),
                        "pile_rigs": pile_rigs_by_field.get((code, field_name), []) if total_cnt > 0 else [],
                    })
                mapped[code].sort(key=lambda item: (str(item.get("field_name") or ""), str(item.get("pk_range") or "")))
            return mapped

        details = {
            "month": detail_rows(month_start, as_of),
            "all": detail_rows(PROJECT_START_DATE, as_of, include_project=True),
        }

    selected_day = as_of.isoformat()
    day_plan_state = {
        code: {
            "fact_total": float((matrix.get(code, {}).get(selected_day, {}) or {}).get("total") or 0),
            "plan_total": float((matrix.get(code, {}).get(selected_day, {}) or {}).get("plan_total") or 0),
        }
        for code in section_codes
    }
    pile_rigs = _reinforcement_pile_rigs_payload(month_start, as_of, query_section_codes, section_codes, day_plan_state)

    return {
        "date": as_of.isoformat(),
        "mode": mode,
            "plan_available": any(s["plan_total"] > 0 or s["month_plan_total"] > 0 or s.get("project_total", 0) > 0 for s in sections),
        "sections": sections,
        "calendar": {
            "month": month_start.strftime("%Y-%m"),
            "days": days,
            "rows": [{"code": code, "label": f"Участок №{i}", "days": matrix[code]} for i, code in enumerate(section_codes, start=1)],
            "totals_by_day": totals_by_day,
        },
        "dynamic": [],
        "details": details,
        "pile_rigs": pile_rigs,
    }


def _pile_delivery_month_bounds(as_of: date_cls) -> tuple[date_cls, date_cls, list[str]]:
    month_start = as_of.replace(day=1)
    next_month = (month_start.replace(day=28) + timedelta(days=4)).replace(day=1)
    month_end = next_month - timedelta(days=1)
    days = [(month_start + timedelta(days=i)).isoformat() for i in range((month_end - month_start).days + 1)]
    return month_start, month_end, days


def _pile_delivery_empty_summary(as_of: date_cls, *, available: bool) -> dict:
    month_start, _, days = _pile_delivery_month_bounds(as_of)
    totals_by_day = {day: {"plan": 0.0, "fact": 0.0} for day in days}
    return {
        "available": available,
        "date": as_of.isoformat(),
        "month": month_start.strftime("%Y-%m"),
        "days": days,
        "rows": [],
        "totals_by_day": totals_by_day,
        "totals": {
            "day_plan": 0.0,
            "day_fact": 0.0,
            "month_plan": 0.0,
            "month_fact": 0.0,
            "delta_day": 0.0,
            "delta_month": 0.0,
        },
        "legend": [
            "НС — низовые сваи",
            "ВС — верховые сваи",
        ],
    }


def _pile_delivery_length_m(value: object) -> Optional[int]:
    text = str(value or "")
    match = re.search(r"(\d+(?:[\.,]\d+)?)\s*м\b", text, flags=re.I)
    if not match:
        match = re.search(r"^\s*(\d+(?:[\.,]\d+)?)\s*[НВ]\s*$", text, flags=re.I)
    if not match:
        match = re.search(r"^\s*(\d+(?:[\.,]\d+)?)\s*$", text, flags=re.I)
    if not match:
        return None
    try:
        number = float(match.group(1).replace(",", "."))
    except ValueError:
        return None
    return int(round(number))


def _pile_delivery_placement_side(value: object) -> Optional[str]:
    text = re.sub(r"\s+", " ", str(value or "").upper().replace("Ё", "Е")).strip()
    if re.search(r"(?:^|\s)НС(?:$|\s)", text):
        return "ns"
    if re.search(r"(?:^|\s)ВС(?:$|\s)", text):
        return "vs"
    if re.search(r"^\s*\d+(?:[\.,]\d+)?\s*Н\s*$", text):
        return "ns"
    if re.search(r"^\s*\d+(?:[\.,]\d+)?\s*В\s*$", text):
        return "vs"
    return None


def _pile_delivery_spec_code(value: object) -> Optional[str]:
    length_m = _pile_delivery_length_m(value)
    if length_m is None:
        return None
    side = _pile_delivery_placement_side(value)
    suffix = f"_{side.upper()}" if side else ""
    return f"PILE_{length_m}M{suffix}"


def _pile_delivery_canonical_spec_text(value: object) -> str:
    text = _pile_delivery_normalize_text(value)
    if not text:
        return ""
    length_m = _pile_delivery_length_m(text)
    side = _pile_delivery_placement_side(text)
    if length_m is not None and side == "ns":
        return f"{length_m} м НС"
    if length_m is not None and side == "vs":
        return f"{length_m} м ВС"
    if length_m is not None:
        return f"{length_m} м"
    return text


def _pile_delivery_normalize_text(value: object) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip())


def _pile_delivery_display_code(value: object) -> Optional[str]:
    text = _pile_delivery_normalize_text(value)
    if not text:
        return None
    display = re.sub(r"^PILE_", "", text, flags=re.I)
    return display or None


def _pile_delivery_key_text(value: object) -> str:
    return _pile_delivery_normalize_text(value).upper().replace("Ё", "Е")


def _pile_delivery_specs_catalog() -> list[dict]:
    if not _wip_table_exists("pile_delivery_specs"):
        return []
    rows = query(
        """
        SELECT spec_code,
               display_name,
               length_m,
               placement_side
        FROM pile_delivery_specs
        WHERE COALESCE(is_active, true) IS TRUE
        ORDER BY length_m NULLS LAST, placement_side NULLS LAST, display_name, spec_code
        """
    )
    return [
        {
            "spec_code": row.get("spec_code"),
            "display_name": row.get("display_name"),
            "length_m": int(row.get("length_m")) if row.get("length_m") is not None else None,
            "placement_side": row.get("placement_side"),
        }
        for row in rows
    ]


def _pile_delivery_resolve_spec_code(raw_spec_text: str, specs: list[dict]) -> Optional[str]:
    if not specs:
        return None
    canonical = _pile_delivery_canonical_spec_text(raw_spec_text)
    normalized = _pile_delivery_key_text(canonical)
    derived = _pile_delivery_spec_code(canonical)
    by_code = {str(item.get("spec_code") or "").upper(): item.get("spec_code") for item in specs if item.get("spec_code")}
    by_name = {(_pile_delivery_key_text(item.get("display_name"))): item.get("spec_code") for item in specs if item.get("display_name") and item.get("spec_code")}
    if normalized in by_code:
        return by_code[normalized]
    if normalized in by_name:
        return by_name[normalized]
    if derived and derived.upper() in by_code:
        return by_code[derived.upper()]
    return None


def _pile_delivery_database_rows(delivery_date: date_cls) -> list[dict]:
    specs_ready = _wip_table_exists("pile_delivery_specs")
    if specs_ready:
        rows = query(
            """
            SELECT pdc.id::text AS id,
                   pdc.delivery_date,
                   pdc.supplier_name,
                   pdc.supplier_code,
                   pdc.raw_spec_text,
                   pdc.spec_code,
                   COALESCE(NULLIF(pds.display_name, ''), NULLIF(pdc.raw_spec_text, ''), 'Свая н/д') AS spec_display,
                   pds.length_m AS length_m,
                   pds.placement_side AS placement_side,
                   COALESCE(pdc.exclude_from_totals, false) AS exclude_from_totals,
                   pdc.planned_qty,
                   pdc.actual_qty,
                   pdc.source_reference,
                   pdc.comment,
                   pdc.updated_at
            FROM pile_delivery_calendar pdc
            LEFT JOIN pile_delivery_specs pds ON pds.spec_code = pdc.spec_code
            WHERE pdc.delivery_date = %s
            ORDER BY COALESCE(NULLIF(pdc.supplier_name, ''), 'Поставщик н/д'),
                     pds.length_m NULLS LAST,
                     pds.placement_side NULLS LAST,
                     COALESCE(NULLIF(pds.display_name, ''), NULLIF(pdc.raw_spec_text, ''), 'Свая н/д'),
                     pdc.created_at,
                     pdc.id
            """,
            [delivery_date],
        )
    else:
        rows = query(
            """
            SELECT pdc.id::text AS id,
                   pdc.delivery_date,
                   pdc.supplier_name,
                   pdc.supplier_code,
                   pdc.raw_spec_text,
                   pdc.spec_code,
                   COALESCE(NULLIF(pdc.raw_spec_text, ''), 'Свая н/д') AS spec_display,
                   NULL::integer AS length_m,
                   NULL::text AS placement_side,
                   COALESCE(pdc.exclude_from_totals, false) AS exclude_from_totals,
                   pdc.planned_qty,
                   pdc.actual_qty,
                   pdc.source_reference,
                   pdc.comment,
                   pdc.updated_at
            FROM pile_delivery_calendar pdc
            WHERE pdc.delivery_date = %s
            ORDER BY COALESCE(NULLIF(pdc.supplier_name, ''), 'Поставщик н/д'),
                     COALESCE(NULLIF(pdc.raw_spec_text, ''), 'Свая н/д'),
                     pdc.created_at,
                     pdc.id
            """,
            [delivery_date],
        )
    return [
        {
            "id": row.get("id"),
            "delivery_date": row.get("delivery_date").isoformat() if row.get("delivery_date") else None,
            "supplier_name": _pile_delivery_normalize_text(row.get("supplier_name") or "Поставщик н/д") or "Поставщик н/д",
            "supplier_code": _pile_delivery_normalize_text(row.get("supplier_code")) or None,
            "raw_spec_text": _pile_delivery_normalize_text(row.get("raw_spec_text") or "Свая н/д") or "Свая н/д",
            "spec_code": row.get("spec_code"),
            "spec_code_display": _pile_delivery_display_code(row.get("spec_code")),
            "spec_display": _pile_delivery_normalize_text(row.get("spec_display") or row.get("raw_spec_text") or "Свая н/д") or "Свая н/д",
            "length_m": int(row.get("length_m")) if row.get("length_m") is not None else None,
            "placement_side": row.get("placement_side"),
            "exclude_from_totals": bool(row.get("exclude_from_totals")),
            "planned_qty": float(row.get("planned_qty") or 0),
            "actual_qty": float(row.get("actual_qty") or 0),
            "source_reference": _pile_delivery_normalize_text(row.get("source_reference") or "") or "dashboard",
            "comment": _pile_delivery_normalize_text(row.get("comment") or "") or None,
            "updated_at": row.get("updated_at").isoformat() if row.get("updated_at") else None,
        }
        for row in rows
    ]


@router.get("/pile-deliveries/summary")
def pile_deliveries_summary(date: Optional[str] = None):
    try:
        as_of = date_cls.fromisoformat(date) if date else date_cls.today()
    except ValueError:
        raise HTTPException(400, "Invalid date format, expected YYYY-MM-DD")

    if not _wip_table_exists("pile_delivery_calendar"):
        return _pile_delivery_empty_summary(as_of, available=False)

    month_start, month_end, days = _pile_delivery_month_bounds(as_of)
    summary = _pile_delivery_empty_summary(as_of, available=True)
    specs_ready = _wip_table_exists("pile_delivery_specs")

    if specs_ready:
        rows = query(
            """
            SELECT pdc.delivery_date AS d,
                   COALESCE(NULLIF(pdc.supplier_name, ''), 'Поставщик н/д') AS supplier_name,
                   COALESCE(NULLIF(pds.display_name, ''), NULLIF(pdc.raw_spec_text, ''), 'Свая н/д') AS spec_display,
                   COALESCE(NULLIF(pdc.raw_spec_text, ''), NULLIF(pds.display_name, ''), 'Свая н/д') AS raw_spec_text,
                   COALESCE(NULLIF(pdc.spec_code, ''), NULLIF(pds.spec_code, '')) AS spec_code,
                   pds.length_m AS length_m,
                   pds.placement_side AS placement_side,
                   BOOL_OR(COALESCE(pdc.exclude_from_totals, false)) AS exclude_from_totals,
                   SUM(COALESCE(pdc.planned_qty, 0))::numeric AS planned_qty,
                   SUM(COALESCE(pdc.actual_qty, 0))::numeric AS actual_qty
            FROM pile_delivery_calendar pdc
            LEFT JOIN pile_delivery_specs pds ON pds.spec_code = pdc.spec_code
            WHERE pdc.delivery_date BETWEEN %s AND %s
            GROUP BY 1, 2, 3, 4, 5, 6, 7
            ORDER BY 2, 6 NULLS LAST, 7 NULLS LAST, 3, 1
            """,
            [month_start, month_end],
            )
    else:
        rows = query(
            """
            SELECT pdc.delivery_date AS d,
                   COALESCE(NULLIF(pdc.supplier_name, ''), 'Поставщик н/д') AS supplier_name,
                   COALESCE(NULLIF(pdc.raw_spec_text, ''), 'Свая н/д') AS spec_display,
                   COALESCE(NULLIF(pdc.raw_spec_text, ''), 'Свая н/д') AS raw_spec_text,
                   NULLIF(pdc.spec_code, '') AS spec_code,
                   NULL::integer AS length_m,
                   NULL::text AS placement_side,
                   BOOL_OR(COALESCE(pdc.exclude_from_totals, false)) AS exclude_from_totals,
                   SUM(COALESCE(pdc.planned_qty, 0))::numeric AS planned_qty,
                   SUM(COALESCE(pdc.actual_qty, 0))::numeric AS actual_qty
            FROM pile_delivery_calendar pdc
            WHERE pdc.delivery_date BETWEEN %s AND %s
            GROUP BY 1, 2, 3, 4, 5, 6, 7
            ORDER BY 2, 3, 1
            """,
            [month_start, month_end],
            )

    rows_by_key: dict[tuple[str, str], dict] = {}
    day_order = {day: idx for idx, day in enumerate(days)}
    side_order = {"ns": 0, "vs": 1}
    for row in rows:
        day_value = row.get("d")
        day = day_value.isoformat() if hasattr(day_value, "isoformat") else str(day_value or "")
        if day not in day_order:
            continue
        supplier_name = str(row.get("supplier_name") or "Поставщик н/д").strip() or "Поставщик н/д"
        spec_display = str(row.get("spec_display") or row.get("raw_spec_text") or "Свая н/д").strip() or "Свая н/д"
        raw_spec_text = str(row.get("raw_spec_text") or spec_display).strip() or spec_display
        spec_code = row.get("spec_code") or _pile_delivery_spec_code(raw_spec_text) or spec_display
        spec_code_value = None if spec_code == spec_display else spec_code
        length_m = row.get("length_m")
        length_m = int(length_m) if length_m is not None else _pile_delivery_length_m(raw_spec_text)
        placement_side = row.get("placement_side") or _pile_delivery_placement_side(raw_spec_text)
        exclude_from_totals = bool(row.get("exclude_from_totals"))
        cache_key = (supplier_name, str(spec_code))
        entry = rows_by_key.setdefault(cache_key, {
            "supplier": supplier_name,
            "spec_display": spec_display,
            "spec_code": spec_code_value,
            "spec_code_display": _pile_delivery_display_code(spec_code_value),
            "length_m": length_m,
            "placement_side": placement_side,
            "exclude_from_totals": exclude_from_totals,
            "days": {day_key: {"plan": 0.0, "fact": 0.0} for day_key in days},
            "month_plan": 0.0,
            "month_fact": 0.0,
        })
        planned_qty = float(row.get("planned_qty") or 0)
        actual_qty = float(row.get("actual_qty") or 0)
        entry["days"][day]["plan"] += planned_qty
        entry["days"][day]["fact"] += actual_qty
        entry["month_plan"] += planned_qty
        entry["month_fact"] += actual_qty

    summary_rows = sorted(
        rows_by_key.values(),
        key=lambda item: (
            str(item.get("supplier") or "").lower(),
            item.get("length_m") is None,
            item.get("length_m") or 0,
            side_order.get(item.get("placement_side"), 9),
            str(item.get("spec_display") or "").lower(),
        ),
    )
    totals_by_day = {
        day: {
            "plan": sum(float(item["days"][day]["plan"] or 0) for item in summary_rows if not item.get("exclude_from_totals")),
            "fact": sum(float(item["days"][day]["fact"] or 0) for item in summary_rows if not item.get("exclude_from_totals")),
        }
        for day in days
    }
    day_totals = totals_by_day.get(as_of.isoformat(), {"plan": 0.0, "fact": 0.0})
    month_plan = sum(float(item.get("month_plan") or 0) for item in summary_rows if not item.get("exclude_from_totals"))
    month_fact = sum(float(item.get("month_fact") or 0) for item in summary_rows if not item.get("exclude_from_totals"))
    summary["rows"] = summary_rows
    summary["totals_by_day"] = totals_by_day
    summary["totals"] = {
        "day_plan": float(day_totals.get("plan") or 0),
        "day_fact": float(day_totals.get("fact") or 0),
        "month_plan": month_plan,
        "month_fact": month_fact,
        "delta_day": float(day_totals.get("fact") or 0) - float(day_totals.get("plan") or 0),
        "delta_month": month_fact - month_plan,
    }
    return summary


@router.get("/database/pile-deliveries")
def database_pile_deliveries(
    date: Optional[str] = None,
    _user=Depends(current_user),
):
    try:
        requested_date = date_cls.fromisoformat(date) if date else date_cls.today()
    except ValueError:
        raise HTTPException(400, "Некорректная дата, ожидается YYYY-MM-DD")

    summary = pile_deliveries_summary(date=requested_date.isoformat())
    specs = _pile_delivery_specs_catalog()
    if not _wip_table_exists("pile_delivery_calendar"):
        return {
            "available": False,
            "date": requested_date.isoformat(),
            "specs_ready": bool(specs),
            "specs": specs,
            "rows": [],
            "totals": {"day_plan": 0.0, "day_fact": 0.0, "row_count": 0},
            "summary": summary,
        }

    rows = _pile_delivery_database_rows(requested_date)
    return {
        "available": True,
        "date": requested_date.isoformat(),
        "specs_ready": bool(specs),
        "specs": specs,
        "rows": rows,
        "totals": {
            "day_plan": sum(float(row.get("planned_qty") or 0) for row in rows if not row.get("exclude_from_totals")),
            "day_fact": sum(float(row.get("actual_qty") or 0) for row in rows if not row.get("exclude_from_totals")),
            "row_count": len(rows),
        },
        "summary": summary,
    }


@router.put("/database/pile-deliveries")
def database_replace_pile_deliveries(
    body: PileDeliveryDatabaseReplaceBody,
    _admin=Depends(require_admin),
):
    if not _wip_table_exists("pile_delivery_calendar"):
        raise HTTPException(400, "Миграция pile_delivery_calendar не применена")
    try:
        delivery_date = date_cls.fromisoformat(body.delivery_date)
    except Exception:
        raise HTTPException(400, "Некорректная дата поставки")

    specs = _pile_delivery_specs_catalog()
    normalized_rows: list[dict] = []
    seen_keys: set[tuple[str, str]] = set()
    for idx, row in enumerate(body.rows or [], start=1):
        supplier_name = _pile_delivery_normalize_text(row.supplier_name)
        raw_spec_text = _pile_delivery_canonical_spec_text(row.raw_spec_text)
        planned_qty = float(row.planned_qty or 0)
        actual_qty = float(row.actual_qty or 0)
        exclude_from_totals = bool(row.exclude_from_totals)
        supplier_code = _pile_delivery_normalize_text(row.supplier_code) or None
        source_reference = _pile_delivery_normalize_text(row.source_reference) or "dashboard"
        comment = _pile_delivery_normalize_text(row.comment) or None

        if not supplier_name and not raw_spec_text and planned_qty == 0 and actual_qty == 0:
            continue
        if not supplier_name:
            raise HTTPException(400, f"Строка {idx}: укажите поставщика")
        if not raw_spec_text:
            raise HTTPException(400, f"Строка {idx}: укажите типоразмер сваи")
        if planned_qty < 0 or actual_qty < 0:
            raise HTTPException(400, f"Строка {idx}: план и факт не могут быть отрицательными")

        dedupe_key = (_pile_delivery_key_text(supplier_name), _pile_delivery_key_text(raw_spec_text))
        if dedupe_key in seen_keys:
            raise HTTPException(400, f"Строка {idx}: поставщик и типоразмер повторяется для выбранной даты")
        seen_keys.add(dedupe_key)

        normalized_rows.append({
            "supplier_name": supplier_name,
            "supplier_code": supplier_code,
            "raw_spec_text": raw_spec_text,
            "spec_code": _pile_delivery_resolve_spec_code(raw_spec_text, specs),
            "planned_qty": planned_qty,
            "actual_qty": actual_qty,
            "exclude_from_totals": exclude_from_totals,
            "source_reference": source_reference,
            "comment": comment,
        })

    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM pile_delivery_calendar WHERE delivery_date = %s", (delivery_date,))
            for row in normalized_rows:
                cur.execute(
                    """
                    INSERT INTO pile_delivery_calendar (
                      delivery_date, supplier_name, supplier_code, raw_spec_text, spec_code,
                      planned_qty, actual_qty, exclude_from_totals, source_reference, comment
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """,
                    (
                        delivery_date,
                        row["supplier_name"],
                        row["supplier_code"],
                        row["raw_spec_text"],
                        row["spec_code"],
                        row["planned_qty"],
                        row["actual_qty"],
                        row["exclude_from_totals"],
                        row["source_reference"],
                        row["comment"],
                    ),
                )
        conn.commit()
    return {"ok": True, "date": delivery_date.isoformat(), "saved": len(normalized_rows)}


def _pile_control_section_codes() -> tuple[list[str], list[str]]:
    return [f"UCH_{idx}" for idx in range(1, 9)], ["UCH_1", "UCH_2", "UCH_3", "UCH_31", "UCH_32", "UCH_4", "UCH_5", "UCH_6", "UCH_7", "UCH_8"]


PILE_CONTROL_DAY_START_HOUR = 8


def _pile_control_day_window(day: date_cls) -> tuple[datetime, datetime]:
    start = datetime(day.year, day.month, day.day, PILE_CONTROL_DAY_START_HOUR)
    return start, start + timedelta(days=1)


def _pile_control_interval_buckets(day: date_cls, interval_hours: int) -> list[dict]:
    interval_hours = max(1, min(12, int(interval_hours or 3)))
    buckets = []
    cursor, end_of_day = _pile_control_day_window(day)
    while cursor < end_of_day:
        end = min(cursor + timedelta(hours=interval_hours), end_of_day)
        buckets.append({
            "key": cursor.strftime("%H:%M"),
            "label": f"{cursor:%H:%M}-{end:%H:%M}",
            "start": cursor,
            "end": end,
        })
        cursor = end
    return buckets


def _pile_control_bucket_key(value: datetime, buckets: list[dict]) -> Optional[str]:
    for bucket in buckets:
        if bucket["start"] <= value < bucket["end"]:
            return bucket["key"]
    return None


def _pile_control_priority(value: Optional[str]) -> str:
    priority = (value or "yellow").strip().lower()
    return priority if priority in {"green", "yellow", "red"} else "yellow"


@router.get("/pile-control/summary")
def pile_control_summary(
    date: Optional[str] = None,
    interval_hours: int = Query(3, ge=1, le=12),
    mode: str = Query("day"),
    all_time: bool = Query(False),
    _user=Depends(current_user),
):
    """Оперативный контроль свай: отчеты isso, сгруппированные по отчетному времени."""
    display_mode = (mode or "day").strip().lower()
    if display_mode not in {"day", "cumulative"}:
        raise HTTPException(status_code=400, detail="mode должен быть day или cumulative")
    is_cumulative = display_mode == "cumulative"
    if is_cumulative and all_time:
        last_fact = query_one(
            """
            SELECT MAX(dr.report_date)::date AS report_date
            FROM daily_reports dr
            WHERE COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review', 'review')
              AND (
                COALESCE(dr.source_type, '') = 'web_pile_control'
                OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
              )
            """
        )
        as_of = last_fact.get("report_date") if last_fact and last_fact.get("report_date") else date_cls.today()
    else:
        as_of = date_cls.fromisoformat(date) if date else date_cls.today()
    section_codes, query_section_codes = _pile_control_section_codes()
    day_start, day_end = _pile_control_day_window(as_of)
    day_shift_end = day_start + timedelta(hours=12)
    if is_cumulative:
        period_start, _ = _pile_control_day_window(PROJECT_START_DATE)
        buckets = [{
            "key": "all",
            "label": "Накопительно",
            "start": period_start,
            "end": day_end,
        }]
    else:
        period_start = day_start
        buckets = _pile_control_interval_buckets(as_of, interval_hours)
    report_lookup_start = period_start.date()

    empty_facts = {
        "main": 0.0,
        "test": 0.0,
        "dyn": 0.0,
        "headcaps": 0.0,
        "total": 0.0,
        "plan_main": 0.0,
        "plan_test": 0.0,
        "plan_dyn": 0.0,
        "plan_headcaps": 0.0,
        "plan_total": 0.0,
    }
    matrix = {
        code: {bucket["key"]: dict(empty_facts) for bucket in buckets}
        for code in section_codes
    }

    plan_by_section = {code: {"main": 0.0, "test": 0.0, "dyn": 0.0, "headcaps": 0.0} for code in section_codes}
    if is_cumulative:
        plan_rows = query(
            """
            WITH sliced AS (
              SELECT cs.code AS section_code,
                     ppp.planned_main_piles,
                     ppp.planned_test_piles,
                     ppp.planned_dynamic_tests,
                     ppp.planned_headcaps,
                     GREATEST((ppp.period_end - ppp.period_start + 1), 1) AS period_days,
                     GREATEST((LEAST(ppp.period_end, %s::date) - ppp.period_start + 1), 0) AS active_days
              FROM pile_plan_periods ppp
              JOIN construction_sections cs ON cs.id = ppp.section_id
              WHERE cs.code = ANY(%s)
                AND ppp.period_start <= %s
            )
            SELECT section_code,
                   SUM(COALESCE(planned_main_piles, 0)::numeric * active_days / period_days) AS main_cnt,
                   SUM(COALESCE(planned_test_piles, 0)::numeric * active_days / period_days) AS test_cnt,
                   SUM(COALESCE(planned_dynamic_tests, 0)::numeric * active_days / period_days) AS dyn_cnt,
                   SUM(COALESCE(planned_headcaps, 0)::numeric * active_days / period_days) AS headcap_cnt
            FROM sliced
            GROUP BY section_code
            """,
            [as_of, query_section_codes, as_of],
        )
    else:
        plan_rows = query(
            """
            SELECT cs.code AS section_code,
                   SUM(COALESCE(ppp.planned_main_piles, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS main_cnt,
                   SUM(COALESCE(ppp.planned_test_piles, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS test_cnt,
                   SUM(COALESCE(ppp.planned_dynamic_tests, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS dyn_cnt,
                   SUM(COALESCE(ppp.planned_headcaps, 0)::numeric
                       / GREATEST((ppp.period_end - ppp.period_start + 1), 1)) AS headcap_cnt
            FROM pile_plan_periods ppp
            JOIN construction_sections cs ON cs.id = ppp.section_id
            WHERE cs.code = ANY(%s)
              AND ppp.period_start <= %s
              AND ppp.period_end >= %s
            GROUP BY cs.code
            """,
            [query_section_codes, as_of, as_of],
        )
    for row in plan_rows:
        code = _merge_section(row.get("section_code")) or ""
        if code not in plan_by_section:
            continue
        plan_by_section[code]["main"] += float(row.get("main_cnt") or 0)
        plan_by_section[code]["test"] += float(row.get("test_cnt") or 0)
        plan_by_section[code]["dyn"] += float(row.get("dyn_cnt") or 0)
        plan_by_section[code]["headcaps"] += float(row.get("headcap_cnt") or 0)

    bucket_count = max(len(buckets), 1)
    for code in section_codes:
        for bucket in buckets:
            slot = matrix[code][bucket["key"]]
            slot["plan_main"] = plan_by_section[code]["main"] / bucket_count
            slot["plan_test"] = plan_by_section[code]["test"] / bucket_count
            slot["plan_dyn"] = plan_by_section[code]["dyn"] / bucket_count
            slot["plan_headcaps"] = plan_by_section[code]["headcaps"] / bucket_count
            slot["plan_total"] = slot["plan_main"] + slot["plan_test"] + slot["plan_dyn"]

    if is_cumulative and all_time:
        fact_rows = query(
            f"""
            SELECT dr.report_date::timestamp AS report_ts,
                   COALESCE(cs_eff_control_all.code, '') AS section_code,
                   wt.code AS wt_code,
                   SUM({_pile_effective_volume_expr('seg_control_all')})::numeric AS cnt
            FROM daily_work_items dwi
            JOIN daily_reports dr ON dr.id = dwi.daily_report_id
            JOIN work_types wt ON wt.id = dwi.work_type_id
            {_pile_effective_section_join('seg_control_all', 'cs_eff_control_all', 'cs_report_control_all')}
            WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
              AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review', 'review')
              AND (
                  COALESCE(dr.source_type, '') = 'web_pile_control'
                  OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
                )
              AND dr.report_date >= %s::date
              AND dr.report_date <= %s::date
            GROUP BY dr.report_date, COALESCE(cs_eff_control_all.code, ''), wt.code
            ORDER BY dr.report_date
            """,
            [period_start.date(), as_of],
        )
    else:
        fact_rows = query(
            f"""
            WITH control_reports AS (
              SELECT dr.id AS report_id,
                     COALESCE(cs.code, '') AS report_section_code,
                     COALESCE(
                       NULLIF(dr.review_payload #>> '{{pile_control,reported_at}}', '')::timestamp,
                       dr.report_date::timestamp + CASE
                         WHEN dr.shift = 'night' THEN interval '20 hours'
                         WHEN dr.shift = 'day' THEN interval '8 hours'
                         ELSE interval '12 hours'
                       END
                     ) AS report_ts
              FROM daily_reports dr
              LEFT JOIN construction_sections cs ON cs.id = dr.section_id
              WHERE (
                COALESCE(dr.source_type, '') = 'web_pile_control'
                OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
              )
                AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
                AND dr.report_date >= %s::date - interval '1 day'
                AND dr.report_date <= %s::date + interval '1 day'
            )
            SELECT cr.report_ts,
                   COALESCE(cs_eff_control_day.code, cr.report_section_code) AS section_code,
                   wt.code AS wt_code,
                   SUM({_pile_effective_volume_expr('seg_control_day')})::numeric AS cnt
            FROM daily_work_items dwi
            JOIN daily_reports dr ON dr.id = dwi.daily_report_id
            JOIN control_reports cr ON cr.report_id = dwi.daily_report_id
            JOIN work_types wt ON wt.id = dwi.work_type_id
            {_pile_effective_section_join('seg_control_day', 'cs_eff_control_day', 'cs_report_control_day')}
            WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
              AND cr.report_ts >= %s
              AND cr.report_ts < %s
            GROUP BY cr.report_ts, COALESCE(cs_eff_control_day.code, cr.report_section_code), wt.code
            ORDER BY cr.report_ts
            """,
            [report_lookup_start, as_of, period_start, day_end],
        )
    for row in fact_rows:
        report_ts = row.get("report_ts")
        if not isinstance(report_ts, datetime):
            continue
        bucket_key = _pile_control_bucket_key(report_ts, buckets)
        code = _merge_section(row.get("section_code")) or ""
        if not bucket_key or code not in matrix:
            continue
        wt_code = row.get("wt_code")
        key = "test" if wt_code == "PILE_TRIAL" else "dyn" if wt_code == "PILE_DYNTEST" else "headcaps" if wt_code == "PILE_HEADCAP_INSTALLATION" else "main"
        cnt = float(row.get("cnt") or 0)
        matrix[code][bucket_key][key] += cnt
        if key != "headcaps":
            matrix[code][bucket_key]["total"] += cnt

    bucket_labels = {bucket["key"]: bucket["label"] for bucket in buckets}
    fact_details: list[dict] = []
    if not is_cumulative:
        fact_detail_rows = query(
            f"""
            WITH control_reports AS (
              SELECT dr.id AS report_id,
                     COALESCE(cs.code, '') AS report_section_code,
                     COALESCE(
                       NULLIF(dr.review_payload #>> '{{pile_control,reported_at}}', '')::timestamp,
                       dr.report_date::timestamp + CASE
                         WHEN dr.shift = 'night' THEN interval '20 hours'
                         WHEN dr.shift = 'day' THEN interval '8 hours'
                         ELSE interval '12 hours'
                       END
                     ) AS report_ts
              FROM daily_reports dr
              LEFT JOIN construction_sections cs ON cs.id = dr.section_id
              WHERE (
                COALESCE(dr.source_type, '') = 'web_pile_control'
                OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
              )
                AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
                AND dr.report_date >= %s::date - interval '1 day'
                AND dr.report_date <= %s::date + interval '1 day'
            )
            SELECT cr.report_ts,
                   dr.id::text AS report_id,
                   dwi.id::text AS work_item_id,
                   seg_detail.id::text AS segment_id,
                   COALESCE(cs_eff_detail.code, cr.report_section_code) AS section_code,
                   wt.code AS wt_code,
                   wt.name AS work_name,
                   ({_pile_effective_volume_expr('seg_detail')})::numeric AS cnt,
                   COALESCE(NULLIF(seg_detail_pf.field_code, ''), NULLIF(pf_obj_detail.field_code, ''), NULLIF(obj_detail.name, ''), NULLIF(obj_detail.object_code, ''), 'Поле н/д') AS field_code,
                   COALESCE(NULLIF(seg_detail_pf.field_type, ''), NULLIF(pf_obj_detail.field_type, ''), '') AS field_type,
                   COALESCE(NULLIF(seg_detail_pf.pile_type, ''), NULLIF(pf_obj_detail.pile_type, ''), '') AS pile_type,
                   COALESCE(seg_detail.pk_start, seg_detail_pf.pk_start, pf_obj_detail.pk_start) AS pk_start,
                   COALESCE(seg_detail.pk_end, seg_detail_pf.pk_end, pf_obj_detail.pk_end) AS pk_end,
                   COALESCE(NULLIF(seg_detail.pk_raw_text, ''), NULLIF(seg_detail_pf.pk_raw_text, ''), NULLIF(pf_obj_detail.pk_raw_text, '')) AS pk_raw_text,
                   dr.uploaded_by_username,
                   dr.created_at,
                   dr.review_payload #>> '{{pile_control,sender_name}}' AS sender_name,
                   COALESCE(eq_detail.equipment_label, '') AS equipment_label,
                   COALESCE(eq_detail.equipment_keys, '') AS equipment_keys,
                   COALESCE(eq_detail.unit_numbers, '') AS equipment_unit_numbers,
                   COALESCE(eq_detail.plate_numbers, '') AS equipment_plate_numbers,
                   COALESCE(eq_detail.contractors, '') AS equipment_contractors
            FROM daily_work_items dwi
            JOIN daily_reports dr ON dr.id = dwi.daily_report_id
            JOIN control_reports cr ON cr.report_id = dwi.daily_report_id
            JOIN work_types wt ON wt.id = dwi.work_type_id
            {_pile_effective_section_join('seg_detail', 'cs_eff_detail', 'cs_report_detail')}
            LEFT JOIN objects obj_detail ON obj_detail.id = dwi.object_id
            LEFT JOIN LATERAL (
              SELECT pf_obj.*
              FROM pile_fields pf_obj
              WHERE pf_obj.object_id = dwi.object_id
              ORDER BY pf_obj.pk_start, pf_obj.pk_end, pf_obj.field_code
              LIMIT 1
            ) pf_obj_detail ON seg_detail.id IS NULL
            LEFT JOIN LATERAL (
              SELECT STRING_AGG(DISTINCT CONCAT_WS(' · ',
                       COALESCE(NULLIF(reu.equipment_type, ''), eu.equipment_type, 'Сваебойная техника'),
                       NULLIF(COALESCE(reu.brand_model, eu.brand_model, ''), ''),
                      CASE WHEN COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')) IS NOT NULL THEN 'борт ' || COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), '')) ELSE NULL END,
                      CASE WHEN COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')) IS NOT NULL THEN 'гос. ' || COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), '')) ELSE NULL END,
                       COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '')
                     ), '; ') AS equipment_label,
                     STRING_AGG(DISTINCT COALESCE(reu.equipment_unit_id::text, reu.id::text), ', ') AS equipment_keys,
                     STRING_AGG(DISTINCT NULLIF(COALESCE(reu.unit_number, eu.unit_number, ''), ''), ', ') AS unit_numbers,
                     STRING_AGG(DISTINCT NULLIF(COALESCE(reu.plate_number, eu.plate_number, ''), ''), ', ') AS plate_numbers,
                     STRING_AGG(DISTINCT NULLIF(COALESCE(reu.contractor_name, c.short_name, c.name, eu.contractor_name, ''), ''), ', ') AS contractors
              FROM work_item_equipment_usage wieu
              JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
              LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
              LEFT JOIN contractors c ON c.id = reu.contractor_id
              WHERE wieu.daily_work_item_id = dwi.id
            ) eq_detail ON true
            WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')
              AND cr.report_ts >= %s
              AND cr.report_ts < %s
            ORDER BY cr.report_ts, COALESCE(cs_eff_detail.code, cr.report_section_code), field_code, wt.code, dr.created_at
            """,
            [report_lookup_start, as_of, period_start, day_end],
        )
        for row in fact_detail_rows:
            report_ts = row.get("report_ts")
            if not isinstance(report_ts, datetime):
                continue
            bucket_key = _pile_control_bucket_key(report_ts, buckets)
            code = _merge_section(row.get("section_code")) or ""
            if not bucket_key or code not in matrix:
                continue
            wt_code = row.get("wt_code")
            kind = "test" if wt_code == "PILE_TRIAL" else "dyn" if wt_code == "PILE_DYNTEST" else "headcaps" if wt_code == "PILE_HEADCAP_INSTALLATION" else "main"
            cnt = float(row.get("cnt") or 0)
            if cnt <= 0:
                continue
            pk_label = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text")) or None
            created_at = row.get("created_at")
            fact_details.append({
                "report_id": row.get("report_id"),
                "work_item_id": row.get("work_item_id"),
                "segment_id": row.get("segment_id"),
                "reported_at": report_ts.isoformat(timespec="minutes"),
                "interval_key": bucket_key,
                "interval_label": bucket_labels.get(bucket_key),
                "section_code": code,
                "section_label": f"Участок №{int(''.join(ch for ch in code if ch.isdigit()) or '0')}" if code else "Участок н/д",
                "work_code": wt_code,
                "work_name": row.get("work_name") or "",
                "kind": kind,
                "count": cnt,
                "field_code": row.get("field_code") or "Поле н/д",
                "field_type": row.get("field_type") or "",
                "pile_type": row.get("pile_type") or "",
                "pk_label": pk_label,
                "equipment_label": row.get("equipment_label") or "",
                "equipment_keys": row.get("equipment_keys") or "",
                "equipment_unit_numbers": row.get("equipment_unit_numbers") or "",
                "equipment_plate_numbers": row.get("equipment_plate_numbers") or "",
                "equipment_contractors": row.get("equipment_contractors") or "",
                "sender_name": row.get("sender_name") or "",
                "uploaded_by_username": row.get("uploaded_by_username") or "",
                "created_at": created_at.isoformat(timespec="minutes") if hasattr(created_at, "isoformat") else str(created_at or ""),
            })

    equipment_rating_rows = query(
        """
        WITH control_reports AS (
          SELECT dr.id AS report_id,
                 COALESCE(cs.code, '') AS report_section_code,
                 COALESCE(
                   NULLIF(dr.review_payload #>> '{pile_control,reported_at}', '')::timestamp,
                   dr.report_date::timestamp + CASE
                     WHEN dr.shift = 'night' THEN interval '20 hours'
                     WHEN dr.shift = 'day' THEN interval '8 hours'
                     ELSE interval '12 hours'
                   END
                 ) AS report_ts
          FROM daily_reports dr
          LEFT JOIN construction_sections cs ON cs.id = dr.section_id
          WHERE (
                COALESCE(dr.source_type, '') = 'web_pile_control'
                OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
              )
            AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
            AND dr.report_date >= %s::date - interval '1 day'
            AND dr.report_date <= %s::date + interval '1 day'
        ), rating_base AS (
          SELECT COALESCE(reu.equipment_unit_id::text, reu.id::text) AS equipment_key,
                 COALESCE(NULLIF(reu.equipment_type, ''), eu.equipment_type, 'Сваебойная техника') AS equipment_type,
                 COALESCE(NULLIF(reu.brand_model, ''), eu.brand_model, '') AS brand_model,
                 COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), ''), '') AS unit_number,
                 COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), ''), '') AS plate_number,
                 COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '') AS contractor,
                 wt.code AS wt_code,
                 cr.report_ts,
                 dwi.id AS work_item_id,
                 CASE
                   WHEN seg_rating.id IS NULL THEN COALESCE(wieu.worked_volume, dwi.volume, 0)
                   WHEN seg_rating_count.cnt > 0 THEN COALESCE(wieu.worked_volume, dwi.volume, 0) / seg_rating_count.cnt
                   ELSE COALESCE(wieu.worked_volume, dwi.volume, 0)
                 END::numeric AS cnt,
                 COALESCE(cs_field_rating.code, cs_dwi.code, cr.report_section_code) AS section_code,
                 COALESCE(NULLIF(pf_rating.field_code, ''), NULLIF(pf_obj_rating.field_code, ''), NULLIF(obj_rating.name, ''), NULLIF(obj_rating.object_code, '')) AS field_code,
                 COALESCE(seg_rating.pk_start, pf_rating.pk_start, pf_obj_rating.pk_start) AS pk_start,
                 COALESCE(seg_rating.pk_end, pf_rating.pk_end, pf_obj_rating.pk_end) AS pk_end,
                 COALESCE(NULLIF(seg_rating.pk_raw_text, ''), NULLIF(pf_rating.pk_raw_text, ''), NULLIF(pf_obj_rating.pk_raw_text, '')) AS pk_raw_text
          FROM work_item_equipment_usage wieu
          JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
          JOIN work_types wt ON wt.id = dwi.work_type_id
          JOIN control_reports cr ON cr.report_id = dwi.daily_report_id
          JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
          LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
          LEFT JOIN contractors c ON c.id = reu.contractor_id
          LEFT JOIN construction_sections cs_dwi ON cs_dwi.id = dwi.section_id
          LEFT JOIN objects obj_rating ON obj_rating.id = dwi.object_id
          LEFT JOIN LATERAL (
            SELECT COUNT(*)::numeric AS cnt
            FROM daily_work_item_segments seg_count
            WHERE seg_count.daily_work_item_id = dwi.id
              AND COALESCE(seg_count.is_demo, false) IS FALSE
          ) seg_rating_count ON true
          LEFT JOIN daily_work_item_segments seg_rating
            ON seg_rating.daily_work_item_id = dwi.id
           AND COALESCE(seg_rating.is_demo, false) IS FALSE
          LEFT JOIN pile_fields pf_rating ON pf_rating.id = seg_rating.pile_field_id
          LEFT JOIN LATERAL (
            SELECT pf_obj.*
            FROM pile_fields pf_obj
            WHERE pf_obj.object_id = dwi.object_id
            ORDER BY pf_obj.pk_start, pf_obj.pk_end, pf_obj.field_code
            LIMIT 1
          ) pf_obj_rating ON seg_rating.id IS NULL
          LEFT JOIN LATERAL (
            SELECT COALESCE(
              (COALESCE(seg_rating.pk_start, pf_rating.pk_start, pf_obj_rating.pk_start) + COALESCE(seg_rating.pk_end, pf_rating.pk_end, pf_obj_rating.pk_end)) / 2.0,
              COALESCE(seg_rating.pk_start, pf_rating.pk_start, pf_obj_rating.pk_start),
              COALESCE(seg_rating.pk_end, pf_rating.pk_end, pf_obj_rating.pk_end)
            ) AS pk_mid
          ) pk_rating ON true
          LEFT JOIN LATERAL (
            SELECT csv.section_id
            FROM construction_section_versions csv
            WHERE csv.is_current
              AND csv.boundary_kind = 'piles_pipes'
              AND pk_rating.pk_mid IS NOT NULL
              AND pk_rating.pk_mid >= LEAST(csv.pk_start, csv.pk_end)
              AND pk_rating.pk_mid < GREATEST(csv.pk_start, csv.pk_end)
            ORDER BY csv.pk_start, csv.pk_end
            LIMIT 1
          ) boundary_rating ON true
          LEFT JOIN construction_sections cs_field_rating ON cs_field_rating.id = boundary_rating.section_id
          WHERE wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
            AND cr.report_ts >= %s
            AND cr.report_ts < %s
        )
        SELECT equipment_key,
               equipment_type,
               brand_model,
               unit_number,
               plate_number,
               contractor,
               SUM(CASE WHEN wt_code = 'PILE_MAIN' THEN cnt ELSE 0 END)::numeric AS main_cnt,
               SUM(CASE WHEN wt_code = 'PILE_TRIAL' THEN cnt ELSE 0 END)::numeric AS test_cnt,
               SUM(cnt)::numeric AS total_cnt,
               SUM(CASE WHEN report_ts >= %s AND report_ts < %s THEN cnt ELSE 0 END)::numeric AS day_cnt,
               SUM(CASE WHEN report_ts >= %s AND report_ts < %s THEN cnt ELSE 0 END)::numeric AS night_cnt,
               COUNT(DISTINCT work_item_id) AS work_items,
               ARRAY_REMOVE(ARRAY_AGG(DISTINCT NULLIF(section_code, '')), NULL) AS section_codes,
               COALESCE(
                 JSONB_AGG(DISTINCT JSONB_BUILD_OBJECT(
                   'section_code', NULLIF(section_code, ''),
                   'field_code', NULLIF(field_code, ''),
                   'pk_start', pk_start,
                   'pk_end', pk_end,
                   'pk_raw_text', NULLIF(pk_raw_text, '')
                 )) FILTER (WHERE NULLIF(field_code, '') IS NOT NULL OR pk_start IS NOT NULL OR pk_end IS NOT NULL),
                 '[]'::jsonb
               ) AS field_details
        FROM rating_base
        GROUP BY equipment_key,
                 equipment_type,
                 brand_model,
                 unit_number,
                 plate_number,
                 contractor
        HAVING SUM(cnt) > 0
        ORDER BY total_cnt DESC, equipment_type, unit_number, plate_number
        """,
        [report_lookup_start, as_of, period_start, day_end, day_start, day_shift_end, day_shift_end, day_end],
    )
    equipment_rating = []
    equipment_by_identity_key: dict[str, dict] = {}

    def pile_equipment_identity_key(row: dict) -> str:
        return _equipment_identity_key(row, row.get("equipment_key")) or str(row.get("equipment_key") or row.get("label") or "")

    for row in equipment_rating_rows:
        if not _pile_rig_has_identifier(row):
            continue
        section_values = row.get("section_codes") or []
        merged_sections = sorted({
            _merge_section(code) or str(code)
            for code in section_values
            if code
        }, key=lambda code: int(''.join(ch for ch in code if ch.isdigit()) or '0'))
        raw_field_details = row.get("field_details") or []
        if isinstance(raw_field_details, str):
            try:
                raw_field_details = json.loads(raw_field_details)
            except json.JSONDecodeError:
                raw_field_details = []
        field_details = []
        for detail in raw_field_details:
            if not isinstance(detail, dict):
                continue
            pk_label = _format_pk_range_excel(detail.get("pk_start"), detail.get("pk_end"), detail.get("pk_raw_text")) or None
            field_code = detail.get("field_code")
            section_code = _merge_section(detail.get("section_code")) or detail.get("section_code")
            if not field_code and not pk_label and not section_code:
                continue
            field_details.append({
                "section_code": section_code,
                "field_code": field_code,
                "pk_label": pk_label,
            })
        field_details.sort(key=lambda item: (
            int(''.join(ch for ch in str(item.get("section_code") or "") if ch.isdigit()) or '0'),
            str(item.get("field_code") or ""),
            str(item.get("pk_label") or ""),
        ))
        equipment_type = row.get("equipment_type") or "Сваебойная техника"
        parts = [
            equipment_type,
            row.get("brand_model") or "",
            f"борт {row.get('unit_number')}" if row.get("unit_number") else "",
            f"гос. {row.get('plate_number')}" if row.get("plate_number") else "",
        ]
        item = {
            "rank": 0,
            "equipment_key": row.get("equipment_key"),
            "label": " · ".join(part for part in parts if part),
            "equipment_type": equipment_type,
            "brand_model": row.get("brand_model") or "",
            "unit_number": row.get("unit_number") or "",
            "plate_number": row.get("plate_number") or "",
            "contractor": row.get("contractor") or "",
            "main": float(row.get("main_cnt") or 0),
            "test": float(row.get("test_cnt") or 0),
            "total": float(row.get("total_cnt") or 0),
            "day_total": float(row.get("day_cnt") or 0),
            "night_total": float(row.get("night_cnt") or 0),
            "work_items": int(row.get("work_items") or 0),
            "sections": merged_sections,
            "fields": field_details,
            "status": "working",
            "status_source": "Сводка контроля свай",
            "status_date": as_of.isoformat(),
            "status_comment": "",
        }
        equipment_rating.append(item)
        identity_key = pile_equipment_identity_key(item)
        if identity_key:
            equipment_by_identity_key[identity_key] = item

    pile_equipment_report_m_date = query_one(
        """
        SELECT MAX(dr.report_date)::date AS d
        FROM daily_reports dr
        WHERE dr.source_type = 'mechanization_report_m'
          AND dr.report_date <= %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND EXISTS (
            SELECT 1
            FROM report_equipment_units reu
            WHERE reu.daily_report_id = dr.id
              AND reu.is_demo IS NOT TRUE
              AND LOWER(COALESCE(reu.equipment_type, '')) LIKE 'сваеб%%'
          )
        """,
        [as_of],
    )
    if not pile_equipment_report_m_date or not pile_equipment_report_m_date.get("d"):
        pile_equipment_report_m_date = query_one(
            """
            SELECT MAX(dr.report_date)::date AS d
            FROM daily_reports dr
            WHERE dr.source_type = 'mechanization_report_m'
              AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
              AND EXISTS (
                SELECT 1
                FROM report_equipment_units reu
                WHERE reu.daily_report_id = dr.id
                  AND reu.is_demo IS NOT TRUE
                  AND LOWER(COALESCE(reu.equipment_type, '')) LIKE 'сваеб%%'
              )
            """
        )
    report_m_date = pile_equipment_report_m_date.get("d") if pile_equipment_report_m_date else None
    if report_m_date:
        report_m_rows = query(
            """
            SELECT COALESCE(reu.equipment_unit_id::text, reu.id::text) AS equipment_key,
                   reu.id::text AS report_equipment_id,
                   reu.equipment_unit_id::text AS equipment_unit_id,
                   COALESCE(NULLIF(reu.equipment_type, ''), eu.equipment_type, 'Сваебойная техника') AS equipment_type,
                   COALESCE(NULLIF(reu.brand_model, ''), eu.brand_model, '') AS brand_model,
                   COALESCE(NULLIF(BTRIM(eu.unit_number), ''), NULLIF(BTRIM(reu.unit_number), ''), '') AS unit_number,
                   COALESCE(NULLIF(BTRIM(eu.plate_number), ''), NULLIF(BTRIM(reu.plate_number), ''), '') AS plate_number,
                   COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '') AS contractor,
                   COALESCE(reu.status, 'unknown') AS status,
                   COALESCE(reu.comment, '') AS status_comment,
                   dr.report_date::date AS status_date
            FROM report_equipment_units reu
            JOIN daily_reports dr ON dr.id = reu.daily_report_id
            LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
            LEFT JOIN contractors c ON c.id = reu.contractor_id
            WHERE dr.report_date = %s
              AND dr.source_type = 'mechanization_report_m'
              AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
              AND reu.is_demo IS NOT TRUE
              AND LOWER(COALESCE(reu.equipment_type, '')) LIKE 'сваеб%%'
            """,
            [report_m_date],
        )
        for row in report_m_rows:
            if not _pile_rig_has_identifier(row):
                continue
            identity_key = pile_equipment_identity_key(row)
            if identity_key and identity_key in equipment_by_identity_key:
                # Сводка контроля свай сильнее отчета М: если установка забивала сваи,
                # считаем ее working даже при конфликтующем статусе в отчете М.
                continue
            equipment_type = row.get("equipment_type") or "Сваебойная техника"
            parts = [
                equipment_type,
                row.get("brand_model") or "",
                f"борт {row.get('unit_number')}" if row.get("unit_number") else "",
                f"гос. {row.get('plate_number')}" if row.get("plate_number") else "",
            ]
            item = {
                "rank": 0,
                "equipment_key": row.get("equipment_key"),
                "label": " · ".join(part for part in parts if part),
                "equipment_type": equipment_type,
                "brand_model": row.get("brand_model") or "",
                "unit_number": row.get("unit_number") or "",
                "plate_number": row.get("plate_number") or "",
                "contractor": row.get("contractor") or "",
                "main": 0.0,
                "test": 0.0,
                "total": 0.0,
                "day_total": 0.0,
                "night_total": 0.0,
                "work_items": 0,
                "sections": [],
                "fields": [],
                "status": row.get("status") or "unknown",
                "status_source": "Отчет М",
                "status_date": row.get("status_date").isoformat() if hasattr(row.get("status_date"), "isoformat") else str(row.get("status_date") or ""),
                "status_comment": row.get("status_comment") or "",
            }
            equipment_rating.append(item)
            if identity_key:
                equipment_by_identity_key[identity_key] = item

    equipment_rating.sort(key=_pile_rig_sort_key)
    for idx, item in enumerate(equipment_rating, start=1):
        item["rank"] = idx

    problem_report_rows = query(
        """
        SELECT dr.id::text AS report_id,
               dr.uploaded_by_username,
               dr.source_reference,
               dr.review_payload,
               COALESCE(cs.code, '') AS section_code,
               COALESCE(cs.name, '') AS section_name,
               COALESCE(
                 NULLIF(dr.review_payload #>> '{pile_control,reported_at}', '')::timestamp,
                 dr.report_date::timestamp + CASE
                   WHEN dr.shift = 'night' THEN interval '20 hours'
                   WHEN dr.shift = 'day' THEN interval '8 hours'
                   ELSE interval '12 hours'
                 END
               ) AS report_ts
        FROM daily_reports dr
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        WHERE (
                COALESCE(dr.source_type, '') = 'web_pile_control'
                OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
              )
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND dr.report_date >= %s::date - interval '2 days'
          AND dr.report_date <= %s::date + interval '1 day'
        ORDER BY report_ts DESC
        """,
        [as_of, as_of],
    )
    problems: list[dict] = []
    for row in problem_report_rows:
        report_ts = row.get("report_ts")
        if not isinstance(report_ts, datetime):
            continue
        expires_at = report_ts + timedelta(hours=24)
        if report_ts >= day_end or expires_at < day_start:
            continue
        payload = row.get("review_payload")
        if isinstance(payload, str):
            try:
                payload = json.loads(payload)
            except json.JSONDecodeError:
                payload = None
        issues = ((payload or {}).get("pile_control") or {}).get("issues") if isinstance(payload, dict) else []
        if not isinstance(issues, list):
            issues = []
        for idx, issue in enumerate(issues):
            if not isinstance(issue, dict):
                continue
            if issue.get("resolved") or issue.get("resolved_at"):
                continue
            text = str(issue.get("text") or "").strip()
            if not text:
                continue
            priority = _pile_control_priority(issue.get("priority"))
            problems.append({
                "id": f"{row.get('report_id')}:{idx}",
                "report_id": row.get("report_id"),
                "issue_index": idx,
                "section_code": _merge_section(row.get("section_code")) or row.get("section_code"),
                "section_name": row.get("section_name") or None,
                "priority": priority,
                "text": text,
                "reported_at": report_ts.isoformat(timespec="minutes"),
                "expires_at": expires_at.isoformat(timespec="minutes"),
                "created_by": row.get("uploaded_by_username"),
            })
    priority_order = {"red": 0, "yellow": 1, "green": 2}
    problems.sort(key=lambda item: (priority_order.get(item["priority"], 9), item["reported_at"]), reverse=False)

    sections = []
    for idx, code in enumerate(section_codes, start=1):
        intervals = matrix[code]
        fact_main = sum(slot["main"] for slot in intervals.values())
        fact_test = sum(slot["test"] for slot in intervals.values())
        fact_dyn = sum(slot["dyn"] for slot in intervals.values())
        fact_headcaps = sum(slot["headcaps"] for slot in intervals.values())
        plan_main = sum(slot["plan_main"] for slot in intervals.values())
        plan_test = sum(slot["plan_test"] for slot in intervals.values())
        plan_dyn = sum(slot["plan_dyn"] for slot in intervals.values())
        sections.append({
            "code": code,
            "label": f"Участок №{idx}",
            "main": fact_main,
            "test": fact_test,
            "dyn": fact_dyn,
            "headcaps": fact_headcaps,
            "total": fact_main + fact_test + fact_dyn,
            "plan_main": plan_main,
            "plan_test": plan_test,
            "plan_dyn": plan_dyn,
            "plan_headcaps": plan_by_section[code]["headcaps"],
            "plan_total": plan_main + plan_test + plan_dyn,
            "intervals": intervals,
        })

    totals_by_interval = {}
    for bucket in buckets:
        key = bucket["key"]
        totals_by_interval[key] = {
            field: sum(matrix[code][key][field] for code in section_codes)
            for field in empty_facts.keys()
        }

    return {
        "date": as_of.isoformat(),
        "mode": display_mode,
        "period_label": "Накопительно за все время" if is_cumulative and all_time else (f"Накопительно с {PROJECT_START_DATE.isoformat()} 08:00 по {(as_of + timedelta(days=1)).isoformat()} 08:00" if is_cumulative else f"Сутки {as_of.isoformat()} 08:00-{(as_of + timedelta(days=1)).isoformat()} 08:00"),
        "interval_hours": max(1, min(12, int(interval_hours or 3))),
        "intervals": [
            {"key": bucket["key"], "label": bucket["label"], "start": bucket["start"].isoformat(timespec="minutes"), "end": bucket["end"].isoformat(timespec="minutes")}
            for bucket in buckets
        ],
        "sections": sections,
        "totals_by_interval": totals_by_interval,
        "problems": problems,
        "equipment_rating": equipment_rating,
        "fact_details": fact_details,
    }


@router.post("/pile-control/problems/{report_id}/{issue_index}/resolve")
def resolve_pile_control_problem(report_id: str, issue_index: int, user=Depends(current_user)):
    """Отметить проблемный вопрос контроля свай решенным: может автор отчета или админ."""
    try:
        uuid.UUID(report_id)
    except ValueError:
        raise HTTPException(400, "Невалидный id отчета")
    if issue_index < 0:
        raise HTTPException(400, "Невалидный номер вопроса")

    row = query_one(
        f"""
        SELECT dr.id::text AS id,
               dr.uploaded_by_username,
               dr.review_payload
        FROM daily_reports dr
        WHERE dr.id = %s
          AND {_pile_control_report_condition('dr')}
        LIMIT 1
        """,
        [report_id],
    )
    if not row:
        raise HTTPException(404, "Отчет контроля свай не найден")

    author = str(row.get("uploaded_by_username") or "").strip()
    if getattr(user, "role", "user") != "admin" and author != getattr(user, "username", ""):
        raise HTTPException(403, "Отметить вопрос решенным может автор отчета или админ")

    payload = row.get("review_payload")
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except json.JSONDecodeError:
            payload = {}
    if not isinstance(payload, dict):
        payload = {}
    pile_control = payload.setdefault("pile_control", {})
    if not isinstance(pile_control, dict):
        pile_control = {}
        payload["pile_control"] = pile_control
    issues = pile_control.get("issues")
    if not isinstance(issues, list):
        issues = []
    if issue_index >= len(issues) or not isinstance(issues[issue_index], dict):
        raise HTTPException(404, "Проблемный вопрос уже снят или не найден")

    resolved_issue = issues[issue_index]
    resolved_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    if not resolved_issue.get("resolved") and not resolved_issue.get("resolved_at"):
        resolved_issue["resolved"] = True
        resolved_issue["resolved_by"] = getattr(user, "username", None)
        resolved_issue["resolved_at"] = resolved_at
        resolved_log = pile_control.setdefault("resolved_issues", [])
        if isinstance(resolved_log, list):
            resolved_log.append({
                "issue_index": issue_index,
                "text": resolved_issue.get("text"),
                "priority": resolved_issue.get("priority"),
                "resolved_by": getattr(user, "username", None),
                "resolved_at": resolved_at,
            })
    pile_control["issues"] = issues

    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                UPDATE daily_reports
                SET review_payload = %s::jsonb
                WHERE id = %s
                RETURNING id::text
                """,
                [json.dumps(payload, ensure_ascii=False), report_id],
            )
            updated = cur.fetchone()
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    if not updated:
        raise HTTPException(404, "Отчет контроля свай не найден")

    remaining = sum(1 for item in issues if isinstance(item, dict) and not item.get("resolved") and not item.get("resolved_at"))
    return {"ok": True, "remaining": remaining}


# ── overview table day totals ──────────────────────────────────────────

@router.get("/overview/day-totals")
def overview_day_totals(
    date: Optional[str] = Query(None),
):
    """Итоги за сутки: техника (working / ремонт), материалы, силы, ИТОГО по всем участкам.

    Используется в режиме "Таблица" на Обзоре для нижних summary-строк как в
    "старом отчёте".
    """
    d = date_cls.fromisoformat(date) if date else date_cls.today()

    # 1) Техника per (equipment_type × status). Приоритет: строки отчётов за
    # выбранную дату, затем мастер-свод техники для единиц без строки отчёта.
    report_equipment_rows = query(
        """
        SELECT reu.id::text AS report_equipment_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.equipment_type AS et,
               COALESCE(reu.status, 'unknown') AS st,
               COALESCE(reu.comment, '') AS comment,
               reu.unit_number,
               reu.plate_number
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        WHERE dr.report_date = %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        """,
        (d,),
    )
    effective_equipment: dict[str, dict[str, str]] = {}
    master_seen: set[str] = set()
    for r in report_equipment_rows:
        master_id = r.get("equipment_unit_id")
        if master_id:
            key = f"master:{master_id}"
            master_seen.add(master_id)
        else:
            key = f"report:{r.get('report_equipment_id')}"
        slot = _equipment_status_bucket(r.get("st"), r.get("comment"))
        current = effective_equipment.get(key)
        if current and current.get("slot") == "working":
            continue
        effective_equipment[key] = {
            "equipment_type": (r.get("et") or "unknown").lower(),
            "slot": slot,
        }
    master_rows = query(
        """
        SELECT id::text AS id,
               equipment_type,
               COALESCE(status, 'unknown') AS status,
               COALESCE(comment, '') AS comment
        FROM equipment_units
        WHERE is_active IS NOT FALSE
        """
    )
    for r in master_rows:
        master_id = r.get("id")
        if master_id in master_seen:
            continue
        effective_equipment[f"master:{master_id}"] = {
            "equipment_type": (r.get("equipment_type") or "unknown").lower(),
            "slot": _equipment_status_bucket(r.get("status"), r.get("comment")),
        }
    eq_working: dict[str, int] = {}
    eq_repair: dict[str, int] = {}
    for r in effective_equipment.values():
        et = r["equipment_type"]
        if r["slot"] == "working":
            eq_working[et] = eq_working.get(et, 0) + 1
        else:
            eq_repair[et] = eq_repair.get(et, 0) + 1

    # 2) Материалы (возка) × силы: sum volume per (material, bucket).
    mm_rows = query(
        f"""
        SELECT mat.code AS mat, mm.labor_source_type AS lsrc,
               LOWER(COALESCE(mm.contractor_name, '')) AS contr,
               SUM(mm.volume)::numeric AS v,
               SUM(mm.trip_count)::int AS trips
        FROM material_movements mm
        LEFT JOIN materials mat ON mat.id = mm.material_id
        WHERE mm.report_date = %s
          AND {_approved_report_exists("mm")}
        GROUP BY mat.code, mm.labor_source_type, mm.contractor_name
        """,
        (d,),
    )
    mat_totals: dict[str, dict[str, float]] = {}  # {MAT: {own, almaz, hired, total, trips}}
    grand = {'own': 0.0, 'almaz': 0.0, 'hired': 0.0, 'total': 0.0, 'trips': 0}
    for r in mm_rows:
        mat = (r['mat'] or 'OTHER').upper()
        v = float(r['v'] or 0)
        trips = int(r['trips'] or 0)
        bucket = ('own' if r['lsrc'] == 'own'
                  else 'almaz' if 'алмаз' in (r['contr'] or '')
                  else 'hired')
        slot = mat_totals.setdefault(mat, {'own': 0.0, 'almaz': 0.0, 'hired': 0.0, 'total': 0.0, 'trips': 0})
        slot[bucket] += v
        slot['total'] += v
        slot['trips'] += trips
        grand[bucket] += v
        grand['total'] += v
        grand['trips'] += trips

    return {
        'date': d.isoformat(),
        'equipment_working': eq_working,
        'equipment_repair': eq_repair,
        'equipment_working_total': sum(eq_working.values()),
        'equipment_repair_total': sum(eq_repair.values()),
        'materials': {mat: {k: (round(v, 1) if isinstance(v, float) else v) for k, v in vals.items()}
                      for mat, vals in mat_totals.items()},
        'grand': {k: (round(v, 1) if isinstance(v, float) else v) for k, v in grand.items()},
    }


# ── works by section ────────────────────────────────────────────────────

@router.get("/works-by-section")
def works_by_section(
    section: Optional[str] = None,
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
):
    """
    Выполненные работы за период: плоский список записей (вид работ × конструктив ×
    участок), с объёмом, числом дней и диапазоном ПК (если он есть в segments).
    UCH_31/UCH_32 → UCH_3.
    """
    d_from, d_to = _parse_range(date_from, date_to)
    codes = _expand_sections(section)

    where = ["dwi.report_date BETWEEN %s AND %s", _approved_report_exists("dwi")]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)

    # Агрегация по (wt × concrete object × section). For pile work the concrete
    # object lives on daily_work_item_segments.pile_field_id, while dwi.object_id
    # is intentionally empty; for pipes the DB object name is often generic
    # ("ПБЖТ 1.5х2.0"), so the display name adds PK from the segment.
    rows = query(
        f"""
        SELECT wt.code AS wt_code,
               wt.name AS wt_name,
               COALESCE(MAX(dwi.unit), MAX(wt.default_unit)) AS unit,
               cs.code AS section_code,
               obj.id   AS object_id,
               obj.name AS object_name,
               ot.code  AS object_type_code,
               MAX(os.object_pk) AS object_pk,
               pf.id    AS pile_field_id,
               pf.field_code AS pile_field_code,
               c.name   AS constructive_name,
               SUM(dwi.volume)::numeric AS volume,
               COUNT(DISTINCT dwi.report_date)::int AS days,
               MIN(LEAST(seg.pk_start, seg.pk_end)) AS pk_min,
               MAX(GREATEST(seg.pk_start, seg.pk_end)) AS pk_max
        FROM daily_work_items dwi
        JOIN daily_reports dr_work ON dr_work.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr_work.section_id)
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN (
          SELECT object_id, MIN(LEAST(pk_start, pk_end)) AS object_pk
          FROM object_segments
          GROUP BY object_id
        ) os ON os.object_id = obj.id
        LEFT JOIN constructives c ON c.id = dwi.constructive_id
        LEFT JOIN daily_work_item_segments seg ON seg.daily_work_item_id = dwi.id
        LEFT JOIN pile_fields pf ON pf.id = seg.pile_field_id
        WHERE {' AND '.join(where)}
        GROUP BY wt.code, wt.name, cs.code, obj.id, obj.name, ot.code, pf.id, pf.field_code, c.name
        ORDER BY SUM(dwi.volume) DESC
        """,
        params,
    )

    out = []
    for r in rows:
        sec_raw = r["section_code"]
        sec = _merge_section(sec_raw) or sec_raw or "—"
        object_name = _short_object_name(r)
        object_id = r["object_id"] or r["pile_field_id"] or object_name
        out.append({
            "wt_code": r["wt_code"],
            "wt_name": r["wt_name"],
            "unit": r["unit"],
            "section_code": sec,
            "object_id": str(object_id) if object_id else None,
            "object_name": object_name,
            "constructive_name": r["constructive_name"] or "—",
            "volume": round(float(r["volume"] or 0), 2),
            "days": int(r["days"] or 0),
            "pk_min": float(r["pk_min"]) if r["pk_min"] is not None else None,
            "pk_max": float(r["pk_max"]) if r["pk_max"] is not None else None,
        })

    # Слить UCH_31 / UCH_32 в UCH_3.
    merged: dict[tuple, dict] = {}
    for r in out:
        key = (r["wt_code"], r["object_id"], r["section_code"])
        if key in merged:
            m = merged[key]
            m["volume"] = round(m["volume"] + r["volume"], 2)
            m["days"] = max(m["days"], r["days"])
            if r["pk_min"] is not None:
                m["pk_min"] = r["pk_min"] if m["pk_min"] is None else min(m["pk_min"], r["pk_min"])
            if r["pk_max"] is not None:
                m["pk_max"] = r["pk_max"] if m["pk_max"] is None else max(m["pk_max"], r["pk_max"])
        else:
            merged[key] = r

    def _sort_key(x):
        # Сортируем по номеру участка (UCH_1..UCH_8, «—» в конец), затем по объекту.
        sc = (x.get("section_code") or "—")
        try:
            sec_n = int(sc.replace('UCH_', '')) if sc.startswith('UCH_') else 99
        except Exception:
            sec_n = 99
        return (sec_n, x.get("object_name") or '', x.get("wt_name") or '')

    final_rows = sorted(merged.values(), key=_sort_key)
    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "section": section or "all",
        "rows": final_rows,
    }


