# ── Settings: DB schema, seeding & loader ────────────────────────────────

SETTINGS_REQUIRED_COLUMNS: dict[str, tuple[str, ...]] = {
    "work_types": ("productivity_enabled",),
    "daily_work_items": ("productivity_enabled",),
    "project_work_item_segments": ("pk_raw_text", "volume_segment"),
    "daily_reports": ("review_tag", "review_payload"),
    "report_equipment_units": ("equipment_unit_id",),
    "daily_report_staff_counts": ("daily_report_id", "category", "count"),
    "construction_section_versions": ("boundary_kind",),
}

SETTINGS_REQUIRED_TABLES: tuple[str, ...] = (
    "equipment_norms_config",
    "work_type_aliases",
    "project_work_item_segments",
    "daily_report_staff_counts",
)


def _settings_tables_prepared() -> bool:
    try:
        rows = query(
            """
            SELECT table_name, column_name
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = ANY(%s)
            """,
            (list(SETTINGS_REQUIRED_COLUMNS),),
        )
        have_columns = {(row.get("table_name"), row.get("column_name")) for row in rows}
        for table_name, columns in SETTINGS_REQUIRED_COLUMNS.items():
            for column in columns:
                if (table_name, column) not in have_columns:
                    return False
        rows = query(
            """
            SELECT table_name
            FROM information_schema.tables
            WHERE table_schema = 'public'
              AND table_name = ANY(%s)
            """,
            (list(SETTINGS_REQUIRED_TABLES),),
        )
        have_tables = {row.get("table_name") for row in rows}
        return all(table_name in have_tables for table_name in SETTINGS_REQUIRED_TABLES)
    except Exception:
        return False


def _ensure_settings_tables() -> None:
    """Create equipment_norms_config and related tables if missing."""
    global _SETTINGS_TABLES_READY
    if _SETTINGS_TABLES_READY:
        return
    if _settings_tables_prepared():
        _SETTINGS_TABLES_READY = True
        return
    with _SETTINGS_TABLES_LOCK:
        if _SETTINGS_TABLES_READY:
            return
        if _settings_tables_prepared():
            _SETTINGS_TABLES_READY = True
            return
        conn = get_conn()
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute("SET LOCAL lock_timeout = '2s'")
                    cur.execute("SET LOCAL statement_timeout = '60s'")
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS equipment_norms_config (
                            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                            category TEXT NOT NULL,
                            key JSONB NOT NULL,
                            value JSONB NOT NULL,
                            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                            updated_by TEXT,
                            UNIQUE (category, key)
                        )
                    """)
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS work_type_aliases (
                            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                            canonical_code TEXT NOT NULL,
                            alias_text TEXT NOT NULL UNIQUE,
                            kind TEXT NOT NULL,
                            notes TEXT,
                            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
                        )
                    """)
                    cur.execute("""
                        ALTER TABLE work_types
                        ADD COLUMN IF NOT EXISTS productivity_enabled BOOLEAN NOT NULL DEFAULT true
                    """)
                    cur.execute("""
                        ALTER TABLE daily_work_items
                        ADD COLUMN IF NOT EXISTS productivity_enabled BOOLEAN NOT NULL DEFAULT true
                    """)
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS project_work_item_segments (
                            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                            project_work_item_id UUID NOT NULL REFERENCES project_work_items(id) ON DELETE CASCADE,
                            pk_start NUMERIC NOT NULL,
                            pk_end NUMERIC NOT NULL,
                            pk_raw_text TEXT,
                            volume_segment NUMERIC,
                            comment TEXT,
                            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                            UNIQUE (project_work_item_id, pk_start, pk_end)
                        )
                    """)
                    cur.execute("""
                        ALTER TABLE project_work_item_segments
                        ADD COLUMN IF NOT EXISTS pk_raw_text TEXT
                    """)
                    cur.execute("""
                        ALTER TABLE project_work_item_segments
                        ADD COLUMN IF NOT EXISTS volume_segment NUMERIC
                    """)
                    cur.execute("""
                        DO $$ BEGIN
                            IF EXISTS (
                                SELECT 1
                                FROM information_schema.columns
                                WHERE table_name = 'project_work_item_segments'
                                  AND column_name = 'project_volume_segment'
                            ) THEN
                                UPDATE project_work_item_segments
                                SET volume_segment = project_volume_segment
                                WHERE volume_segment IS NULL;
                            END IF;
                        END $$;
                    """)
                    cur.execute("""
                        ALTER TABLE project_work_item_segments
                        DROP COLUMN IF EXISTS project_volume_segment
                    """)
                    cur.execute("""
                        CREATE INDEX IF NOT EXISTS idx_project_work_item_segments_item
                        ON project_work_item_segments(project_work_item_id)
                    """)
                    cur.execute("""
                        CREATE INDEX IF NOT EXISTS idx_project_work_item_segments_pk
                        ON project_work_item_segments(pk_start, pk_end)
                    """)
                    cur.execute("""
                        DELETE FROM daily_report_parse_candidates
                        WHERE candidate_type = 'personnel'
                    """)
                    cur.execute("""
                        DROP TABLE IF EXISTS daily_report_personnel
                    """)
                    cur.execute("""
                        ALTER TABLE report_equipment_units
                        DROP COLUMN IF EXISTS operator_name
                    """)
                    cur.execute("""
                        UPDATE work_types
                        SET name = 'Уплотнение'
                        WHERE code = 'CONSOLIDATION'
                    """)
                    cur.execute("""
                        ALTER TABLE daily_reports
                        ADD COLUMN IF NOT EXISTS review_tag TEXT
                    """)
                    cur.execute("""
                        ALTER TABLE daily_reports
                        ADD COLUMN IF NOT EXISTS review_payload JSONB
                    """)
                    cur.execute("""
                        CREATE TABLE IF NOT EXISTS daily_report_staff_counts (
                            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                            daily_report_id UUID NOT NULL REFERENCES daily_reports(id) ON DELETE CASCADE,
                            category TEXT NOT NULL,
                            count INTEGER NOT NULL DEFAULT 0,
                            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                            UNIQUE (daily_report_id, category)
                        )
                    """)
                    cur.execute("""
                        CREATE INDEX IF NOT EXISTS idx_daily_report_staff_counts_report
                        ON daily_report_staff_counts(daily_report_id)
                    """)
                    cur.execute("""
                        ALTER TABLE construction_section_versions
                        ADD COLUMN IF NOT EXISTS boundary_kind TEXT NOT NULL DEFAULT 'main'
                    """)
                    cur.execute("""
                        UPDATE construction_section_versions
                        SET boundary_kind = 'main'
                        WHERE boundary_kind IS NULL OR boundary_kind = ''
                    """)
                    cur.execute("""
                        CREATE INDEX IF NOT EXISTS idx_section_versions_kind_current
                        ON construction_section_versions(boundary_kind, section_id, is_current)
                    """)
                    cur.execute("""
                        UPDATE construction_sections
                        SET is_active = true,
                            sort_order = COALESCE(sort_order, 3),
                            name = COALESCE(NULLIF(name, ''), 'Участок 3')
                        WHERE code = 'UCH_3'
                    """)
                    for kind, label in (("temp_roads", "границы для притрассовых дорог"),
                                        ("piles_pipes", "границы для свайных полей и ВПТ")):
                        cur.execute(
                            """
                            INSERT INTO construction_section_versions
                              (section_id, valid_from, valid_to, pk_start, pk_end,
                               pk_raw_text, is_current, comment, boundary_kind)
                            SELECT section_id, CURRENT_DATE, NULL, pk_start, pk_end,
                                   pk_raw_text, true, %s, %s
                            FROM construction_section_versions src
                            WHERE src.boundary_kind = 'main'
                              AND src.is_current = true
                              AND NOT EXISTS (
                                SELECT 1
                                FROM construction_section_versions existing
                                WHERE existing.boundary_kind = %s
                                  AND existing.section_id = src.section_id
                              )
                            """,
                            (f"Скопировано из main: {label}", kind, kind),
                        )
            _SETTINGS_TABLES_READY = True
        finally:
            conn.close()


def _purge_personal_report_text() -> None:
    try:
        from report_text_parser import sanitize_personal_report_text
    except Exception:
        return
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("SELECT id, raw_text FROM daily_reports WHERE raw_text IS NOT NULL")
                rows = cur.fetchall()
                for report_id, raw_text in rows:
                    sanitized = sanitize_personal_report_text(raw_text or "")
                    if sanitized != (raw_text or ""):
                        cur.execute("UPDATE daily_reports SET raw_text = %s WHERE id = %s", (sanitized, report_id))
    finally:
        conn.close()


def _seed_norms_if_empty() -> None:
    """Populate equipment_norms_config from hardcoded defaults if table is empty."""
    row = query_one("SELECT COUNT(*)::int AS cnt FROM equipment_norms_config")
    if row and row["cnt"] > 0:
        return
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                # work_types
                for (et, wt_code), spec in _DEFAULT_WORK_TYPE_NORMS.items():
                    cur.execute(
                        "INSERT INTO equipment_norms_config (category, key, value, updated_by) "
                        "VALUES (%s, %s, %s, 'seed') ON CONFLICT DO NOTHING",
                        ('work_types',
                         json.dumps({'equipment_type': et, 'work_type_code': wt_code}),
                         json.dumps(spec)),
                    )
                # sand_pit
                for sec, (trips, m3) in _DEFAULT_SAND_PIT_DIRECTION_NORMS.items():
                    cur.execute(
                        "INSERT INTO equipment_norms_config (category, key, value, updated_by) "
                        "VALUES (%s, %s, %s, 'seed') ON CONFLICT DO NOTHING",
                        ('sand_pit',
                         json.dumps({'section': sec}),
                         json.dumps({'trips': trips, 'm3_per_trip': m3})),
                    )
                # sand_stockpile
                for sec, (trips, m3) in _DEFAULT_SAND_STOCKPILE_TO_CONSTR_NORMS.items():
                    cur.execute(
                        "INSERT INTO equipment_norms_config (category, key, value, updated_by) "
                        "VALUES (%s, %s, %s, 'seed') ON CONFLICT DO NOTHING",
                        ('sand_stockpile',
                         json.dumps({'section': sec}),
                         json.dumps({'trips': trips, 'm3_per_trip': m3})),
                    )
                # generic
                cur.execute(
                    "INSERT INTO equipment_norms_config (category, key, value, updated_by) "
                    "VALUES (%s, %s, %s, 'seed') ON CONFLICT DO NOTHING",
                    ('generic',
                     json.dumps({'name': 'truck_norm'}),
                     json.dumps({'norm_m3_per_shift': _DEFAULT_GENERIC_TRUCK_NORM})),
                )
    finally:
        conn.close()


def load_norms_from_db() -> dict:
    """Read all norms from DB. On any error, return defaults.

    Returns dict with keys:
      work_types: {(et, wt_code): {norm, unit, code}}
      sand_pit: {section_num: (trips, m3_per_trip)}
      sand_stockpile: {section_num: (trips, m3_per_trip)}
      generic_truck_norm: float
    """
    try:
        rows = query("SELECT category, key, value FROM equipment_norms_config")
    except Exception:
        return {
            'work_types': dict(_DEFAULT_WORK_TYPE_NORMS),
            'sand_pit': dict(_DEFAULT_SAND_PIT_DIRECTION_NORMS),
            'sand_stockpile': dict(_DEFAULT_SAND_STOCKPILE_TO_CONSTR_NORMS),
            'generic_truck_norm': _DEFAULT_GENERIC_TRUCK_NORM,
        }
    out = {'work_types': {}, 'sand_pit': {}, 'sand_stockpile': {},
           'generic_truck_norm': _DEFAULT_GENERIC_TRUCK_NORM}
    for r in rows:
        cat = r['category']
        key = r['key'] if isinstance(r['key'], dict) else json.loads(r['key'])
        val = r['value'] if isinstance(r['value'], dict) else json.loads(r['value'])
        if cat == 'work_types':
            et = key.get('equipment_type')
            wt = key.get('work_type_code')
            if et and wt:
                out['work_types'][(et, wt)] = val
        elif cat == 'sand_pit':
            sec = key.get('section')
            if sec is not None:
                out['sand_pit'][int(sec)] = (val.get('trips'), val.get('m3_per_trip'))
        elif cat == 'sand_stockpile':
            sec = key.get('section')
            if sec is not None:
                out['sand_stockpile'][int(sec)] = (val.get('trips'), val.get('m3_per_trip'))
        elif cat == 'generic':
            if key.get('name') == 'truck_norm':
                out['generic_truck_norm'] = float(val.get('norm_m3_per_shift') or _DEFAULT_GENERIC_TRUCK_NORM)
    # Fallback per-section: если в таблице чего-то нет, не теряем дефолт
    if not out['work_types']:
        out['work_types'] = dict(_DEFAULT_WORK_TYPE_NORMS)
    if not out['sand_pit']:
        out['sand_pit'] = dict(_DEFAULT_SAND_PIT_DIRECTION_NORMS)
    if not out['sand_stockpile']:
        out['sand_stockpile'] = dict(_DEFAULT_SAND_STOCKPILE_TO_CONSTR_NORMS)
    return out


# Мутируемые модуль-level словари, которыми пользуется остальной код.
# Инициализируются дефолтами; обновляются _refresh_norms() (startup / после PATCH).
WORK_TYPE_NORMS: dict[tuple[str, str], dict] = dict(_DEFAULT_WORK_TYPE_NORMS)
SAND_PIT_DIRECTION_NORMS: dict[int, tuple] = dict(_DEFAULT_SAND_PIT_DIRECTION_NORMS)
SAND_STOCKPILE_TO_CONSTR_NORMS: dict[int, tuple] = dict(_DEFAULT_SAND_STOCKPILE_TO_CONSTR_NORMS)
GENERIC_TRUCK_NORM: float = float(_DEFAULT_GENERIC_TRUCK_NORM)


def _refresh_norms() -> None:
    """Обновляет модульные словари из БД (атомарно, на месте)."""
    global GENERIC_TRUCK_NORM
    loaded = load_norms_from_db()
    WORK_TYPE_NORMS.clear()
    WORK_TYPE_NORMS.update(loaded['work_types'])
    SAND_PIT_DIRECTION_NORMS.clear()
    SAND_PIT_DIRECTION_NORMS.update(loaded['sand_pit'])
    SAND_STOCKPILE_TO_CONSTR_NORMS.clear()
    SAND_STOCKPILE_TO_CONSTR_NORMS.update(loaded['sand_stockpile'])
    GENERIC_TRUCK_NORM = float(loaded['generic_truck_norm'])


