def _seed_rd_intake_aliases() -> None:
    """Adds RD intake aliases even when the shared aliases table is already populated."""
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                for canonical, alias, kind in _RD_INTAKE_SYSTEM_ALIASES:
                    if kind == 'work_type':
                        cur.execute("SELECT 1 FROM work_types WHERE code = %s LIMIT 1", (canonical,))
                    elif kind == 'material':
                        cur.execute("SELECT 1 FROM materials WHERE code = %s LIMIT 1", (canonical,))
                    else:
                        cur.execute("SELECT 1")
                    if cur.fetchone() is None:
                        continue
                    cur.execute(
                        "INSERT INTO work_type_aliases (canonical_code, alias_text, kind, notes) "
                        "VALUES (%s, %s, %s, 'rd_intake_system') ON CONFLICT DO NOTHING",
                        (canonical, alias, kind),
                    )
    finally:
        conn.close()


def _init_settings() -> None:
    """Создаёт таблицы, сидит дефолтами, подтягивает в память. Вызывается из startup."""
    for step in (
        _ensure_settings_tables,
        _seed_norms_if_empty,
        _seed_aliases_if_empty,
        _seed_rd_intake_materials,
        _seed_rd_intake_work_types,
        _seed_rd_intake_aliases,
        _purge_personal_report_text,
        _refresh_norms,
    ):
        try:
            step()
        except Exception:
            # Не роняем приложение при отсутствии БД на старте.
            pass

_QUARRY_BY_SEC = {1:'Карьер Васильки',2:'Карьер Васильки',3:'Карьер Васильки',4:'Карьер Васильки',
                  5:'Карьер Васильки',6:'Карьер Южные Маяки',7:'Карьер Великий',8:'Карьер Великий'}


class _DumpTruckNormsProxy:
    """Легаси-словарь: всегда берёт актуальные SAND_PIT_DIRECTION_NORMS.

    Поддерживает .get((sec, mat)) — единственный способ использования в коде.
    """
    def get(self, key, default=None):
        if not (isinstance(key, tuple) and len(key) == 2):
            return default
        n, mat = key
        if mat != 'SAND' or not isinstance(n, int) or n not in _QUARRY_BY_SEC:
            return default
        tpl = SAND_PIT_DIRECTION_NORMS.get(n, (12, 15) if n != 6 else (12, 15))
        trips = tpl[0] if n != 6 else 12
        m3 = tpl[1] if n != 6 else 15
        return {
            'quarry': _QUARRY_BY_SEC[n],
            'trips': trips,
            'm3_per_trip': m3,
            'include_pit_to_stockpile': n != 6,
        }


DUMP_TRUCK_NORMS = _DumpTruckNormsProxy()


def _sec_code_to_num(code: Optional[str]) -> Optional[int]:
    """UCH_1..UCH_8 → 1..8. UCH_31/UCH_32 → 3."""
    if not code:
        return None
    c = _merge_section(code) or code
    if not c.startswith('UCH_'):
        return None
    try:
        return int(c.split('_', 1)[1])
    except Exception:
        return None


EQUIPMENT_CATEGORIES = {
    "dump_truck": {"label": "Самосвалы", "short": "СВ"},
    "excavator": {"label": "Экскаваторы", "short": "ЭК"},
    "bulldozer": {"label": "Бульдозеры", "short": "БД"},
    "other": {"label": "Прочая", "short": "ПР"},
}


def _equipment_category(equipment_type: Optional[str]) -> str:
    et = (equipment_type or "").strip().lower()
    if "самосвал" in et or "dump" in et:
        return "dump_truck"
    if "экскав" in et or "excav" in et:
        return "excavator"
    if "бульд" in et or "dozer" in et:
        return "bulldozer"
    return "other"


def _equipment_status_bucket(status: Optional[str], comment: Optional[str] = None) -> str:
    text = f"{status or ''} {comment or ''}".strip().lower()
    if status and status.lower() == "working":
        return "working"
    if any(token in text for token in ("repair", "ремонт", "неисправ", "полом", "maintenance", "service")):
        return "repair"
    return "idle"


def _section_from_equipment_location(location: Optional[str]) -> Optional[str]:
    text = (location or "").lower()
    m = re.search(r"(?:участ(?:ок|ка)|уч\.)\s*№?\s*(\d+)", text)
    if not m:
        m = re.search(r"\b(\d+)\s*[-–]?\s*(?:й|ый|ой)?\s*участ", text)
    if not m:
        m = re.search(r"\b(\d+)\s*уч", text)
    if not m:
        return None
    return _merge_section(f"UCH_{int(m.group(1))}")


_EQUIPMENT_ID_TRANSLIT = str.maketrans({
    "A": "А",
    "B": "В",
    "C": "С",
    "E": "Е",
    "H": "Н",
    "K": "К",
    "M": "М",
    "O": "О",
    "P": "Р",
    "T": "Т",
    "X": "Х",
    "Y": "У",
})


def _normalize_equipment_identifier(value: Optional[str]) -> str:
    raw = str(value or "").strip().upper().replace("Ё", "Е")
    raw = raw.translate(_EQUIPMENT_ID_TRANSLIT)
    return re.sub(r"[^0-9A-ZА-Я]", "", raw)


_EQUIPMENT_FULL_PLATE_RE = re.compile(
    r"^(?:"
    r"[АВЕКМНОРСТУХ][0-9]{3}[АВЕКМНОРСТУХ]{2}[0-9]{2,3}|"
    r"[АВЕКМНОРСТУХ]?[0-9]{4}[АВЕКМНОРСТУХ]{2}[0-9]{2,3}"
    r")$"
)


def _equipment_identifier_is_full_plate(value: Optional[str]) -> bool:
    return bool(_EQUIPMENT_FULL_PLATE_RE.fullmatch(_normalize_equipment_identifier(value)))


_EMPTY_EQUIPMENT_IDENTIFIER_NORMS = {"", "БН", "НД", "НЕТ", "NONE", "NULL", "UNKNOWN", "БЕЗНОМЕРА"}


def _clean_equipment_identifier_text(value: Optional[str]) -> str:
    text = str(value or "").strip()
    if _normalize_equipment_identifier(text) in _EMPTY_EQUIPMENT_IDENTIFIER_NORMS:
        return ""
    return text


def _equipment_display_identifier_pair(row: dict[str, Any]) -> tuple[str, str]:
    plate = _clean_equipment_identifier_text(row.get("plate_number"))
    unit_number = _clean_equipment_identifier_text(row.get("unit_number"))
    if not plate and unit_number and _equipment_identifier_is_full_plate(unit_number):
        return _normalize_equipment_identifier(unit_number), ""
    return plate, unit_number


def _equipment_identity_key(row: dict, fallback_id: Optional[str] = None) -> str:
    plate = _normalize_equipment_identifier(row.get("plate_number") or row.get("plate"))
    if plate and plate not in _EMPTY_EQUIPMENT_IDENTIFIER_NORMS:
        return f"plate:{plate}"
    unit = _normalize_equipment_identifier(row.get("unit_number"))
    if unit and unit not in _EMPTY_EQUIPMENT_IDENTIFIER_NORMS:
        return f"unit:{unit}"
    master_id = str(row.get("equipment_unit_id") or row.get("id") or fallback_id or "").strip()
    if master_id:
        return f"master:{master_id}"
    report_id = str(row.get("report_equipment_id") or "").strip()
    return f"report:{report_id}" if report_id else ""


def _equipment_operation_metrics_available() -> bool:
    try:
        row = query_one("SELECT to_regclass('public.equipment_operation_metrics')::text AS table_name")
        return bool(row and row.get("table_name"))
    except Exception:
        return False


def _mechanization_bucket_matches(ownership: Optional[str], contractor: Optional[str], bucket: str) -> bool:
    if bucket == "all":
        return True
    owner = (ownership or "").lower()
    contractor_norm = (contractor or "").lower()
    own = owner == "own" or contractor_norm.strip() == "ждс" or "ооо ждс" in contractor_norm
    almaz = "алмаз" in contractor_norm
    if bucket == "own":
        return own
    if bucket == "almaz":
        return almaz
    if bucket == "hired":
        return not own and not almaz
    return True


def _operation_metric_empty_totals() -> dict[str, Any]:
    return {
        "mileage_km_total": 0.0,
        "engine_hours_total": 0.0,
        "fuel_liters_total": 0.0,
        "operation_metric_rows": 0,
        "operation_shift_keys": set(),
        "operation_unit_keys": set(),
    }


def _operation_metric_add(target: dict[str, Any], row: dict[str, Any], *, unit_shift_identity: Optional[str] = None) -> None:
    mileage = float(row.get("mileage_km") or 0)
    engine_hours = float(row.get("engine_hours") or 0)
    fuel = float(row.get("fuel_liters") or 0)
    target["mileage_km_total"] = float(target.get("mileage_km_total") or 0) + mileage
    target["engine_hours_total"] = float(target.get("engine_hours_total") or 0) + engine_hours
    target["fuel_liters_total"] = float(target.get("fuel_liters_total") or 0) + fuel
    target["operation_metric_rows"] = int(target.get("operation_metric_rows") or 0) + 1
    unit_key = unit_shift_identity or str(row.get("equipment_unit_id") or "")
    if unit_key:
        target.setdefault("operation_unit_keys", set()).add(unit_key)
    date_key = str(row.get("metric_date") or "")
    status_text = str(row.get("source_status") or "").lower().replace("ё", "е")
    active_metric = mileage > 0 or engine_hours > 0 or fuel > 0 or "работ" in status_text
    if date_key and active_metric:
        shift_key = (unit_key, date_key, "day")
        target.setdefault("operation_shift_keys", set()).add(shift_key)


def _query_equipment_operation_metrics(
    d_from: date_cls,
    d_to: date_cls,
    *,
    bucket: str = "all",
) -> dict[str, Any]:
    empty = {
        "by_unit": {},
        "by_unit_section": {},
        "by_section_productivity_type": {},
        "by_section_actual_type": {},
        "total": _operation_metric_empty_totals(),
    }
    if not _equipment_operation_metrics_available():
        return empty
    rows = query(
        """
        WITH ranked_metrics AS (
          SELECT m.*,
                 ROW_NUMBER() OVER (
                   PARTITION BY m.equipment_unit_id, m.metric_date
                   ORDER BY
                     CASE WHEN m.source_reference LIKE 'Сачков:%%' THEN 0 ELSE 1 END,
                     ((m.mileage_km IS NOT NULL)::int + (m.engine_hours IS NOT NULL)::int + (m.fuel_liters IS NOT NULL)::int) DESC,
                     m.updated_at DESC NULLS LAST,
                     m.created_at DESC NULLS LAST,
                     m.source_reference DESC,
                     m.source_row_number DESC
                 ) AS metric_rank
          FROM equipment_operation_metrics m
          WHERE m.metric_date BETWEEN %s AND %s
            AND m.equipment_unit_id IS NOT NULL
        )
        SELECT
          m.equipment_unit_id::text AS equipment_unit_id,
          m.metric_date::date AS metric_date,
          m.source_location,
          m.source_status,
          m.source_equipment_type,
          m.mileage_km,
          m.engine_hours,
          m.fuel_liters,
          eu.equipment_type,
          eu.brand_model,
          eu.plate_number,
          eu.unit_number,
          eu.ownership_type,
          eu.contractor_name,
          eu.location AS master_location
        FROM ranked_metrics m
        LEFT JOIN equipment_units eu ON eu.id = m.equipment_unit_id
        WHERE m.metric_rank = 1
        """,
        [d_from, d_to],
    )
    result = empty
    for row in rows:
        if not _mechanization_bucket_matches(row.get("ownership_type"), row.get("contractor_name"), bucket):
            continue
        equipment_unit_id = str(row.get("equipment_unit_id") or "")
        if not equipment_unit_id:
            continue
        raw_type = row.get("equipment_type") or row.get("source_equipment_type") or "Не указано"
        productivity_type = _mechanization_productivity_equipment_type(raw_type)
        section_code = (
            _section_from_equipment_location(row.get("source_location"))
            or _section_from_equipment_location(row.get("master_location"))
        )
        section_code = _merge_section(section_code) or section_code
        by_unit = result["by_unit"].setdefault(equipment_unit_id, _operation_metric_empty_totals())
        _operation_metric_add(by_unit, row, unit_shift_identity=equipment_unit_id)
        _operation_metric_add(result["total"], row, unit_shift_identity=equipment_unit_id)
        if section_code:
            unit_section = result["by_unit_section"].setdefault((equipment_unit_id, section_code), _operation_metric_empty_totals())
            _operation_metric_add(unit_section, row, unit_shift_identity=equipment_unit_id)
            section_productivity = result["by_section_productivity_type"].setdefault((section_code, productivity_type), _operation_metric_empty_totals())
            _operation_metric_add(section_productivity, row, unit_shift_identity=equipment_unit_id)
            section_actual = result["by_section_actual_type"].setdefault((section_code, raw_type), _operation_metric_empty_totals())
            _operation_metric_add(section_actual, row, unit_shift_identity=equipment_unit_id)
    return result


def _operation_totals_payload(totals: Optional[dict[str, Any]]) -> dict[str, Any]:
    data = totals or {}
    return {
        "mileage_km_total": round(float(data.get("mileage_km_total") or 0), 1),
        "engine_hours_total": round(float(data.get("engine_hours_total") or 0), 1),
        "fuel_liters_total": round(float(data.get("fuel_liters_total") or 0), 1),
        "operation_metric_rows": int(data.get("operation_metric_rows") or 0),
        "operation_work_shifts": len(data.get("operation_shift_keys") or []),
        "operation_units_count": len(data.get("operation_unit_keys") or []),
    }


def _nearest_equipment_status_date(requested_date: date_cls) -> tuple[Optional[date_cls], str]:
    """Choose the date for the equipment pulse snapshot.

    Prefer immutable Отчет М daily snapshots. `equipment_units` is a mutable
    master/current-state table: a newer Сачков import updates the same rows and
    removes the previous `source_date`, so it cannot be treated as historical
    truth for dashboard dates.
    """
    exact_snapshot = query_one(
        """
        SELECT dr.report_date::date AS d
        FROM daily_reports dr
        WHERE dr.report_date = %s
          AND dr.source_type = 'mechanization_report_m'
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND EXISTS (
            SELECT 1 FROM report_equipment_units reu
            WHERE reu.daily_report_id = dr.id
              AND reu.is_demo IS NOT TRUE
          )
        LIMIT 1
        """,
        [requested_date],
    )
    if exact_snapshot and exact_snapshot.get("d"):
        return exact_snapshot["d"], "mechanization_report_m"

    order_by_nearest = """
      ORDER BY ABS(d - %s::date),
               CASE WHEN d <= %s::date THEN 0 ELSE 1 END,
               d DESC
      LIMIT 1
    """
    snapshot_row = query_one(
        f"""
        SELECT d
        FROM (
          SELECT DISTINCT dr.report_date::date AS d
          FROM daily_reports dr
          WHERE dr.source_type = 'mechanization_report_m'
            AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
            AND NOT (
              COALESCE(dr.source_type, '') = 'web_pile_control'
              OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
            )
            AND EXISTS (
              SELECT 1 FROM report_equipment_units reu
              WHERE reu.daily_report_id = dr.id
                AND reu.is_demo IS NOT TRUE
            )
        ) available
        {order_by_nearest}
        """,
        [requested_date, requested_date],
    )
    if snapshot_row and snapshot_row.get("d"):
        return snapshot_row["d"], "mechanization_report_m"

    master_row = query_one(
        f"""
        SELECT d
        FROM (
          SELECT DISTINCT source_date::date AS d
          FROM equipment_units
          WHERE is_active IS NOT FALSE
            AND source_date IS NOT NULL
        ) available
        {order_by_nearest}
        """,
        [requested_date, requested_date],
    )
    if master_row and master_row.get("d"):
        return master_row["d"], "equipment_master"

    report_row = query_one(
        f"""
        SELECT d
        FROM (
          SELECT DISTINCT dr.report_date::date AS d
          FROM report_equipment_units reu
          JOIN daily_reports dr ON dr.id = reu.daily_report_id
          WHERE reu.is_demo IS NOT TRUE
            AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
            AND NOT (
              COALESCE(dr.source_type, '') = 'web_pile_control'
              OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
            )
        ) available
        {order_by_nearest}
        """,
        [requested_date, requested_date],
    )
    if report_row and report_row.get("d"):
        return report_row["d"], "report_equipment"
    return None, "none"


