@router.get("/equipment-productivity")
def equipment_productivity(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    section: Optional[str] = None,
):
    """
    Производительность техники по участкам × видам работ с нормативами
    из справочника пользователя (см. WORK_TYPE_NORMS, DUMP_TRUCK_NORMS).

    Для экск./бульд./автогр./катка:
      — для каждой (section, equipment_type, work_type) считаем:
        fact_vol, days_with_work, avg_units_on_those_days, norm → %
      — агрегируем в средний % по технике (по списку применимых видов работ)
      — в детализации показываем per-work-type разбивку.

    Для самосвалов (только материал=SAND):
      — норма per section из DUMP_TRUCK_NORMS
      — знаменатель = та же ЖДС/non-hired логика, что и в Генеральном отчете
      — АЛМАЗ остается во факте, но не добавляет плановый знаменатель
      — уч.6: учитываем только stockpile_to_constructive.
    """
    d_from, d_to = _parse_range(date_from, date_to)
    codes = _expand_sections(section)

    where_dr = ["dr.report_date BETWEEN %s AND %s", "COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')", _non_pile_control_report_condition("dr")]
    params_dr: list = [d_from, d_to]
    if codes:
        where_dr.append("cs.code = ANY(%s)")
        params_dr.append(codes)

    # 1. Ед. техники per (section × date × shift × equipment_type) — шкала «смена».
    # Считаем уникальные машины, а не строки отчета: один борт/госномер не должен
    # превращаться в несколько единиц из-за дневной/ночной строки или дубля в отчете.
    eq_rows = query(
        f"""
        SELECT cs.code AS section_code,
               dr.report_date AS report_date,
               LOWER(COALESCE(dr.shift, 'day')) AS shift,
               reu.equipment_type AS et,
               ARRAY_AGG(DISTINCT COALESCE(
                   NULLIF(reu.equipment_unit_id::text, ''),
                   NULLIF(LOWER(REGEXP_REPLACE(COALESCE(reu.unit_number, eu.unit_number, ''), '\\s+', '', 'g')), ''),
                   NULLIF(LOWER(REGEXP_REPLACE(COALESCE(reu.plate_number, eu.plate_number, ''), '\\s+', '', 'g')), ''),
                   reu.id::text
               )) AS unit_keys
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        WHERE {' AND '.join(where_dr)}
          AND reu.status = 'working'
          AND COALESCE(reu.is_demo, false) IS FALSE
        GROUP BY cs.code, dr.report_date, dr.shift, reu.equipment_type
        """,
        params_dr,
    )
    # units_by_shift[(sec, et)][(date, shift)] = {dedupe equipment keys}
    units_by_shift: dict[tuple, dict] = {}
    for r in eq_rows:
        sec = _merge_section(r["section_code"]) or "—"
        et = (r["et"] or "").lower()
        keys = {str(key) for key in (r.get("unit_keys") or []) if str(key or "").strip()}
        units_by_shift.setdefault((sec, et), {})[(r["report_date"], r["shift"])] = keys

    dump_units_by_shift_general = _query_general_dump_truck_non_hired_unit_keys_by_shift(d_from, d_to, codes)

    # 2. Факт per (section × date × shift × work_type).
    where_dwi = [
        "dwi.report_date BETWEEN %s AND %s",
        "COALESCE(wt.productivity_enabled, true) = true",
        "COALESCE(dwi.productivity_enabled, true) = true",
        _approved_report_exists("dwi"),
    ]
    params_dwi: list = [d_from, d_to]
    if codes:
        where_dwi.append("cs.code = ANY(%s)")
        params_dwi.append(codes)
    dwi_rows = query(
        f"""
        SELECT cs.code AS section_code,
               dwi.report_date AS report_date,
               LOWER(COALESCE(dwi.shift, 'day')) AS shift,
               wt.code AS wt_code,
               wt.name AS wt_name,
               SUM(dwi.volume)::numeric AS volume
        FROM daily_work_items dwi
        JOIN daily_reports dr_work ON dr_work.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr_work.section_id)
        WHERE {' AND '.join(where_dwi)}
        GROUP BY cs.code, dwi.report_date, dwi.shift, wt.code, wt.name
        HAVING SUM(dwi.volume) > 0
        """,
        params_dwi,
    )
    # facts_by_shift[(sec, wt_code)] = {(date, shift): volume}
    facts_by_shift: dict[tuple, dict] = {}
    wt_names: dict[str, str] = {}
    for r in dwi_rows:
        sec = _merge_section(r["section_code"]) or "—"
        wtc = r["wt_code"]
        wt_names[wtc] = r["wt_name"]
        facts_by_shift.setdefault((sec, wtc), {})[(r["report_date"], r["shift"])] = float(r["volume"] or 0)

    work_unit_rows = query(
        f"""
        SELECT cs.code AS section_code,
               dwi.report_date AS report_date,
               LOWER(COALESCE(dwi.shift, 'day')) AS shift,
               LOWER(COALESCE(reu.equipment_type, eu.equipment_type, '')) AS et,
               wt.code AS wt_code,
               ARRAY_AGG(DISTINCT COALESCE(
                   NULLIF(reu.equipment_unit_id::text, ''),
                   NULLIF(LOWER(REGEXP_REPLACE(COALESCE(reu.unit_number, eu.unit_number, ''), '\\s+', '', 'g')), ''),
                   NULLIF(LOWER(REGEXP_REPLACE(COALESCE(reu.plate_number, eu.plate_number, ''), '\\s+', '', 'g')), ''),
                   reu.id::text
               )) AS unit_keys
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr_work ON dr_work.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr_work.section_id)
        WHERE {' AND '.join(where_dwi)}
          AND COALESCE(reu.is_demo, false) IS FALSE
        GROUP BY cs.code, dwi.report_date, dwi.shift, LOWER(COALESCE(reu.equipment_type, eu.equipment_type, '')), wt.code
        """,
        params_dwi,
    )
    work_units_by_shift: dict[tuple, dict] = {}
    for r in work_unit_rows:
        sec = _merge_section(r["section_code"]) or "—"
        et = (r.get("et") or "").lower()
        wtc = r.get("wt_code")
        keys = {str(key) for key in (r.get("unit_keys") or []) if str(key or "").strip()}
        if keys and wtc:
            work_units_by_shift.setdefault((sec, et, wtc), {})[(r["report_date"], r["shift"])] = keys

    # ── Экск./бульд./автогр./каток ─────────────────────────────────────
    # Считаем per-смена: только смены, где был факт по этой работе И техника работала.
    # Expected = sum_over_shifts(units × norm); pct = fact / expected × 100.
    by_section_et: dict[tuple, dict] = {}
    for (et_norm, wt_code), norm_spec in WORK_TYPE_NORMS.items():
        for (sec, wtc), shift_vol in facts_by_shift.items():
            if wtc != wt_code:
                continue
            units_map = units_by_shift.get((sec, et_norm), {})
            work_units_map = work_units_by_shift.get((sec, et_norm, wt_code), {})
            fact_sum = 0.0
            expected = 0.0
            shifts_worked = 0
            units_sum = 0
            dates_with_work = set()
            used_shift_units: dict[tuple, set[str]] = {}
            for (d, sh), v in shift_vol.items():
                if v <= 0:
                    continue
                keys = set(work_units_map.get((d, sh)) or units_map.get((d, sh)) or set())
                u = len(keys)
                if u <= 0:
                    # факт есть, но ни одной единицы техники этого типа в этой смене —
                    # работу делали другой техникой/подрядчиком, в % этой техники не кладём.
                    continue
                fact_sum += v
                expected += u * norm_spec["norm"]
                shifts_worked += 1
                units_sum += u
                dates_with_work.add(d)
                used_shift_units.setdefault((d, sh), set()).update(keys)
            if shifts_worked == 0:
                continue
            pct = (fact_sum / expected * 100) if expected > 0 else None
            avg_units = units_sum / shifts_worked

            entry = by_section_et.setdefault((sec, et_norm), {
                "section_code": sec,
                "equipment_type": et_norm,
                "by_work_type": [],
                "_shift_units": {},
            })
            for shift_key, keys in used_shift_units.items():
                entry["_shift_units"].setdefault(shift_key, set()).update(keys)
            entry["by_work_type"].append({
                "wt_code": wtc,
                "wt_name": wt_names.get(wtc, wtc),
                "norm_code": norm_spec["code"],
                "norm_per_shift": norm_spec["norm"],
                "norm_unit": norm_spec["unit"],
                "fact_volume": round(fact_sum, 2),
                "days": len(dates_with_work),
                "shifts": shifts_worked,
                "avg_units": round(avg_units, 2),
                "expected": round(expected, 1),
                "percent": round(pct, 1) if pct is not None else None,
            })

    # Агрегируем per-техника: средний % по применимым видам работ.
    for (sec, et), entry in by_section_et.items():
        pcts = [w["percent"] for w in entry["by_work_type"] if w["percent"] is not None]
        entry["percent"] = round(sum(pcts) / len(pcts), 1) if pcts else None
        entry["fact_volume_total_m3"] = round(
            sum(w["fact_volume"] for w in entry["by_work_type"] if w["norm_unit"] == "м³"), 1)
        entry["fact_volume_total_m2"] = round(
            sum(w["fact_volume"] for w in entry["by_work_type"] if w["norm_unit"] == "м²"), 1)
        unique_shift_units = entry.pop("_shift_units", {})
        total_shifts = len(unique_shift_units)
        total_unit_shifts = sum(len(keys) for keys in unique_shift_units.values())
        entry["avg_units"] = round(total_unit_shifts / total_shifts, 1) if total_shifts else 0
        entry["work_shifts_total"] = total_shifts
        entry["work_days_total"] = len({d for d, _ in unique_shift_units}) if unique_shift_units else max((w["days"] for w in entry["by_work_type"]), default=0)

    # ── Самосвалы ──────────────────────────────────────────────────────
    # Per-смена: факт грузим из material_movements с разбивкой по (date × shift).
    # Знаменатель = units_samosval(sec, date, shift) × norm_per_shift, только по тем сменам,
    # где был факт в норме (non-АЛМАЗ, для уч.6 — только stockpile_to_constructive).
    mm_rows = query(
        f"""
        SELECT cs.code AS section_code,
               mm.report_date AS report_date,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               mm.movement_type AS mtype,
               mat.code AS material_code,
               mm.contractor_name AS contractor_name,
               SUM(mm.volume)::numeric AS volume,
               SUM(mm.trip_count)::int AS trips
        FROM material_movements mm
        JOIN daily_reports dr_mm ON dr_mm.id = mm.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr_mm.section_id)
        LEFT JOIN materials mat ON mat.id = mm.material_id
        WHERE mm.report_date BETWEEN %s AND %s
          AND COALESCE(mm.is_demo, false) IS FALSE
          AND {_general_shift_report_exists("mm")}
          {" AND cs.code = ANY(%s)" if codes else ""}
        GROUP BY cs.code, mm.report_date, mm.shift, mm.movement_type, mat.code, mm.contractor_name
        """,
        [d_from, d_to] + ([codes] if codes else []),
    )

    # dump_by_sec[sec]["by_material"][mat_key] — накопитель
    # норм-факт/смены/даты отдельно для fact_in_norm и fact_off_norm
    dump_by_sec: dict[str, dict] = {}
    for r in mm_rows:
        sec = _merge_section(r["section_code"]) or "—"
        n = _sec_code_to_num(sec)
        if n is None:
            continue
        mat = (r["material_code"] or "").upper()
        key_mat = 'SAND' if mat == 'SAND' else ('SHPGS' if mat in ('SHPGS', 'SCHEBEN') else None)
        if key_mat is None:
            continue
        spec = DUMP_TRUCK_NORMS.get((n, key_mat)) if key_mat == 'SAND' else None
        mtype = r["mtype"]
        contractor = (r["contractor_name"] or "").lower()
        is_almaz = 'алмаз' in contractor

        count_in_norm = True
        if spec is not None and not spec["include_pit_to_stockpile"] and mtype == 'pit_to_stockpile':
            count_in_norm = False
        if is_almaz:
            count_in_norm = False
        if key_mat == 'SHPGS':
            count_in_norm = False  # нормы ЩПГС ждём

        bucket = dump_by_sec.setdefault(sec, {
            "section_code": sec,
            "equipment_type": "самосвал",
            "by_material": {},
        })["by_material"].setdefault(key_mat, {
            "fact_norm_by_shift": {},   # {(date, shift): volume} — только учитываемые в норме
            "fact_off_norm": 0.0,
            "trips_norm": 0, "trips_off_norm": 0,
        })
        vol = float(r["volume"] or 0)
        trips = int(r["trips"] or 0)
        if count_in_norm:
            key = (r["report_date"], r["shift"])
            bucket["fact_norm_by_shift"][key] = bucket["fact_norm_by_shift"].get(key, 0) + vol
            bucket["trips_norm"] += trips
        else:
            bucket["fact_off_norm"] += vol
            bucket["trips_off_norm"] += trips

    # Собираем строки по самосвалам — per-смена формула.
    dump_rows: list[dict] = []
    for sec, info in dump_by_sec.items():
        n = _sec_code_to_num(sec)
        by_material_out = []
        pct_list = []
        fact_m3_total = 0.0
        all_shift_units: dict[tuple, set[str]] = {}
        # units самосвалов per (date, shift) — те же non-hired unit keys, что и в Генеральном отчете
        units_map_samo = {
            (d, sh): set(keys)
            for (section_code, d, sh), keys in dump_units_by_shift_general.items()
            if section_code == sec
        }

        for mat_key, b in info["by_material"].items():
            spec = DUMP_TRUCK_NORMS.get((n, mat_key))
            norm_per_shift = (spec["trips"] * spec["m3_per_trip"]) if spec else None

            fact_sum = 0.0
            expected = 0.0
            shifts_worked = 0
            units_sum = 0
            dates_with_work = set()
            for (d, sh), v in b["fact_norm_by_shift"].items():
                if v <= 0 or norm_per_shift is None:
                    continue
                keys = set(units_map_samo.get((d, sh)) or set())
                u = len(keys)
                if u <= 0:
                    continue
                fact_sum += v
                expected += u * norm_per_shift
                shifts_worked += 1
                units_sum += u
                dates_with_work.add(d)
                all_shift_units.setdefault((d, sh), set()).update(keys)
            pct = (fact_sum / expected * 100) if expected > 0 else None
            if pct is not None:
                pct_list.append(pct)
            avg_units = (units_sum / shifts_worked) if shifts_worked else 0
            fact_off_norm = b["fact_off_norm"]
            fact_m3_total += fact_sum + fact_off_norm
            by_material_out.append({
                "material": mat_key,
                "quarry": spec["quarry"] if spec else None,
                "norm_per_shift": round(norm_per_shift, 1) if norm_per_shift else None,
                "norm_formula": (f"{spec['trips']} рейс × {spec['m3_per_trip']} м³"
                                  if spec else None),
                "include_pit_to_stockpile": spec["include_pit_to_stockpile"] if spec else None,
                "fact_in_norm": round(fact_sum, 1),
                "fact_off_norm": round(fact_off_norm, 1),
                "trips_in_norm": b["trips_norm"],
                "trips_off_norm": b["trips_off_norm"],
                "days": len(dates_with_work),
                "shifts": shifts_worked,
                "avg_units": round(avg_units, 2),
                "expected": round(expected, 1),
                "percent": round(pct, 1) if pct is not None else None,
            })
        info["by_material"] = by_material_out
        info["percent"] = round(sum(pct_list) / len(pct_list), 1) if pct_list else None
        # На карточке показываем факт В НОРМЕ (сопоставимо с %), off-norm — в тултипе.
        info["fact_volume_total_m3"] = round(sum(m["fact_in_norm"] for m in by_material_out), 1)
        info["fact_volume_total_m2"] = 0.0
        info["fact_off_norm_total_m3"] = round(sum(m["fact_off_norm"] for m in by_material_out), 1)
        total_shifts = len(all_shift_units)
        total_unit_shifts = sum(len(keys) for keys in all_shift_units.values())
        info["avg_units"] = round(total_unit_shifts / total_shifts, 1) if total_shifts else 0
        info["work_shifts_total"] = total_shifts
        info["work_days_total"] = len({d for d, _ in all_shift_units})
        dump_rows.append(info)

    # Объединяем экск/бульд/автогр/каток и самосвалы в один список строк
    out = list(by_section_et.values()) + dump_rows
    out.sort(key=lambda x: (x["section_code"], x["equipment_type"]))
    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "rows": out,
    }


def _overview_equipment_pulse_payload(d_from: date_cls, d_to: date_cls) -> dict:
    requested_date = d_to
    effective_date, date_source = _nearest_equipment_status_date(requested_date)
    if effective_date is None:
        effective_date = requested_date
    date_note = None
    if effective_date != requested_date:
        date_note = (
            f"За {requested_date.isoformat()} нет актуального среза техники; "
            f"показываем ближайший доступный срез на {effective_date.isoformat()}."
        )

    sections_raw = query(
        """
        SELECT code, name, sort_order
        FROM construction_sections
        WHERE is_active IS NOT FALSE
        ORDER BY sort_order NULLS LAST, code
        """
    )
    sections_meta = {
        r["code"]: {
            "section_code": r["code"],
            "label": (r["name"] or r["code"]).replace("Участок ", "Уч. "),
            "working_total": 0,
            "idle_total": 0,
            "repair_total": 0,
            "categories": {
                key: {"working": 0, "idle": 0, "repair": 0}
                for key in EQUIPMENT_CATEGORIES
            },
            "units": [],
        }
        for r in sections_raw
    }

    categories = {
        key: {
            "key": key,
            "label": spec["label"],
            "short": spec["short"],
            "working": 0,
            "idle": 0,
            "repair": 0,
        }
        for key, spec in EQUIPMENT_CATEGORIES.items()
    }

    has_report_m_snapshot = query_one(
        """
        SELECT 1
        FROM daily_reports dr
        WHERE dr.report_date = %s
          AND dr.source_type = 'mechanization_report_m'
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND EXISTS (
            SELECT 1 FROM report_equipment_units reu
            WHERE reu.daily_report_id = dr.id
              AND reu.is_demo IS NOT TRUE
          )
        LIMIT 1
        """,
        [effective_date],
    )
    report_source_filter = "AND dr.source_type = 'mechanization_report_m'" if has_report_m_snapshot else ""
    report_equipment_rows = query(
        f"""
        SELECT cs.code AS section_code,
               eu.location AS master_location,
               reu.id::text AS report_equipment_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.equipment_type,
               COALESCE(reu.brand_model, eu.brand_model, '') AS brand_model,
               COALESCE(reu.unit_number, eu.unit_number) AS unit_number,
               COALESCE(reu.plate_number, eu.plate_number) AS plate_number,
               COALESCE(reu.ownership_type, eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), eu.contractor_name, '') AS contractor_name,
               COALESCE(reu.status, 'unknown') AS status,
               COALESCE(reu.comment, '') AS comment
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        WHERE dr.report_date = %s
          {report_source_filter}
          AND reu.is_demo IS NOT TRUE
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
        """,
        [effective_date],
    )

    effective_by_unit: dict[str, dict] = {}
    master_seen: set[str] = set()
    for row in report_equipment_rows:
        master_id = row.get("equipment_unit_id")
        key = _equipment_identity_key(row, row.get("report_equipment_id"))
        if not key:
            key = f"report:{row.get('report_equipment_id')}"
        if master_id:
            master_seen.add(_equipment_identity_key(row, master_id))
            master_seen.add(f"master:{master_id}")
        section_code = (
            _merge_section(row.get("section_code"))
            or _section_from_equipment_location(row.get("master_location"))
            or "—"
        )
        slot = _equipment_status_bucket(row["status"], row["comment"])
        existing = effective_by_unit.get(key)
        if existing and existing.get("slot") == "working":
            continue
        effective_by_unit[key] = {**row, "section_code_effective": section_code, "slot": slot}

    master_rows = query(
        """
        SELECT id::text AS id,
               equipment_type,
               brand_model,
               unit_number,
               plate_number,
               ownership_type,
               contractor_name,
               COALESCE(status, 'unknown') AS status,
               COALESCE(comment, '') AS comment,
               location,
               source_name,
               source_date
        FROM equipment_units
        WHERE is_active IS NOT FALSE
          AND source_date = %s
        """,
        [effective_date],
    )
    if not master_rows:
        has_dated_master = query_one(
            """
            SELECT 1
            FROM equipment_units
            WHERE is_active IS NOT FALSE
              AND source_date IS NOT NULL
            LIMIT 1
            """
        )
        if not has_dated_master:
            master_rows = query(
                """
                SELECT id::text AS id,
                       equipment_type,
                       brand_model,
                       unit_number,
                       plate_number,
                       ownership_type,
                       contractor_name,
                       COALESCE(status, 'unknown') AS status,
                       COALESCE(comment, '') AS comment,
                       location,
                       source_name,
                       source_date
                FROM equipment_units
                WHERE is_active IS NOT FALSE
                """
            )
    for row in master_rows:
        master_id = row.get("id")
        logical_key = _equipment_identity_key(row, master_id)
        if logical_key in master_seen or (master_id and f"master:{master_id}" in master_seen):
            continue
        effective_by_unit[logical_key or f"master:{master_id}"] = {
            "section_code_effective": _section_from_equipment_location(row.get("location")) or "—",
            "equipment_type": row.get("equipment_type"),
            "unit_number": row.get("unit_number"),
            "plate_number": row.get("plate_number"),
            "brand_model": row.get("brand_model"),
            "ownership_type": row.get("ownership_type"),
            "contractor_name": row.get("contractor_name"),
            "status": row.get("status"),
            "comment": row.get("comment"),
            "location": row.get("location"),
            "source_name": row.get("source_name"),
            "source_date": row.get("source_date"),
            "slot": _equipment_status_bucket(row.get("status"), row.get("comment")),
        }

    for row in effective_by_unit.values():
        section_code = row.get("section_code_effective") or "—"
        if section_code not in sections_meta:
            sections_meta[section_code] = {
                "section_code": section_code,
                "label": section_code.replace("UCH_", "Уч. "),
                "working_total": 0,
                "idle_total": 0,
                "repair_total": 0,
                "categories": {
                    key: {"working": 0, "idle": 0, "repair": 0}
                    for key in EQUIPMENT_CATEGORIES
                },
                "units": [],
            }
        cat = _equipment_category(row["equipment_type"])
        slot = row["slot"]
        categories[cat][slot] += 1
        sections_meta[section_code][f"{slot}_total"] += 1
        sections_meta[section_code]["categories"][cat][slot] += 1
        source_date = row.get("source_date")
        sections_meta[section_code]["units"].append({
            "category": cat,
            "slot": slot,
            "equipment_type": row.get("equipment_type") or "",
            "brand_model": row.get("brand_model") or "",
            "plate_number": row.get("plate_number") or "",
            "unit_number": row.get("unit_number") or "",
            "ownership_type": row.get("ownership_type") or "unknown",
            "contractor_name": row.get("contractor_name") or "",
            "status": row.get("status") or "",
            "comment": row.get("comment") or "",
            "location": row.get("location") or "",
            "source_name": row.get("source_name") or "",
            "source_date": source_date.isoformat() if hasattr(source_date, "isoformat") else source_date,
        })

    totals = {
        "working": sum(c["working"] for c in categories.values()),
        "idle": sum(c["idle"] for c in categories.values()),
        "repair": sum(c["repair"] for c in categories.values()),
    }

    return {
        "from": effective_date.isoformat(),
        "to": effective_date.isoformat(),
        "requested_from": d_from.isoformat(),
        "requested_to": requested_date.isoformat(),
        "effective_date": effective_date.isoformat(),
        "date_source": date_source,
        "date_note": date_note,
        "categories": list(categories.values()),
        "sections": list(sections_meta.values()),
        "totals": totals,
    }


@router.get("/overview/equipment-pulse")
def overview_equipment_pulse(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
):
    """Upper overview infographics: equipment status snapshot by type and section."""
    d_from, d_to = _parse_range(date_from, date_to)
    endpoint = "overview_equipment_pulse.v1"
    fingerprint = _dashboard_source_fingerprint(d_from, d_to, include_equipment=True)
    cache_key = (d_from.isoformat(), d_to.isoformat(), fingerprint)
    allow_stale_cache = _dashboard_response_cache_should_serve_stale()
    if allow_stale_cache:
        cached = _dashboard_short_cache_get(_DASHBOARD_EQUIPMENT_PULSE_CACHE, cache_key)
        if cached is not None:
            return cached
    persistent_key = _dashboard_response_cache_key({"endpoint": "overview_equipment_pulse", "from": d_from, "to": d_to})
    cached = _dashboard_response_cache_get(endpoint, persistent_key, fingerprint)
    if cached is not None:
        marked = _dashboard_response_cache_mark(cached, status="fresh", fingerprint=fingerprint)
        return _dashboard_short_cache_set(_DASHBOARD_EQUIPMENT_PULSE_CACHE, cache_key, marked)
    stale = _dashboard_response_cache_stale_payload(
        endpoint,
        persistent_key,
        fingerprint,
        overview_equipment_pulse,
        date_from,
        date_to,
        short_cache=_DASHBOARD_EQUIPMENT_PULSE_CACHE,
        short_cache_key=cache_key,
    )
    if stale is not None:
        return stale

    return _dashboard_response_cache_build_or_wait(
        endpoint,
        persistent_key,
        fingerprint,
        lambda: _overview_equipment_pulse_payload(d_from, d_to),
        short_cache=_DASHBOARD_EQUIPMENT_PULSE_CACHE,
        short_cache_key=cache_key,
    )


# ── mechanization: per-unit productivity ──────────────────────────────

PRODUCTIVITY_SHIFT_HOURS = 11.0


def _adjust_productivity_norm(reference_norm: float, work_hours: object) -> tuple[float, float]:
    try:
        hours = float(work_hours) if work_hours is not None else PRODUCTIVITY_SHIFT_HOURS
    except (TypeError, ValueError):
        hours = PRODUCTIVITY_SHIFT_HOURS
    if hours <= 0 or hours > PRODUCTIVITY_SHIFT_HOURS:
        hours = PRODUCTIVITY_SHIFT_HOURS
    return reference_norm * hours / PRODUCTIVITY_SHIFT_HOURS, hours

@router.get("/mechanization/units")
def mechanization_units(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    ownership: Optional[str] = Query(None, description="own/subcontractor/supplier, null = все"),
):
    """Список всех единиц техники и их производительность за период (см. _mechanization_units_impl)."""
    d_from, d_to = _parse_range(date_from, date_to)
    return _mechanization_units_impl(d_from, d_to, ownership)


def _mechanization_units_impl(
    d_from,
    d_to,
    ownership: Optional[str] = None,
    include_work_diagnostics: bool = False,
):
    """Внутренняя логика per-unit productivity — переиспользуется агрегатами.

    Методика:
      Экск/бульд/автогр/каток — норма из WORK_TYPE_NORMS × смен.
      Самосвал — факт = volume движений этого юнита из *_equipment_usage; план:
         * SAND pit_to_stockpile|pit_to_constructive — SAND_PIT_DIRECTION_NORMS[sec]
         * SAND stockpile_to_constructive — SAND_STOCKPILE_TO_CONSTR_NORMS[sec]
         * остальное — 166 м³/см.
    """
    try:
        _refresh_norms()
    except Exception:
        REPORT_PIPELINE_LOG.exception("failed to refresh mechanization productivity norms")

    # 1) Снимаем список всех единиц техники, встречавшихся за период.
    where = [
        "dr.report_date BETWEEN %s AND %s",
        "COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')",
        _non_pile_control_report_condition("dr"),
        "reu.is_demo IS NOT TRUE",
    ]
    params: list = [d_from, d_to]
    if ownership:
        where.append("reu.ownership_type = %s")
        params.append(ownership)

    unit_rows = query(
        f"""
        SELECT reu.equipment_type, reu.brand_model, reu.plate_number, reu.unit_number,
               reu.ownership_type, reu.contractor_name,
               cs.code AS section_code,
               dr.report_date,
               LOWER(COALESCE(dr.shift, 'day')) AS shift
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        WHERE {' AND '.join(where)}
        """,
        params,
    )

    # Дедуп ключ: (et_lower, plate, unit_num) — плоский композит.
    def key_of(r):
        return (
            (r['equipment_type'] or '').lower(),
            (r['plate_number'] or '').strip(),
            (r['unit_number'] or '').strip(),
        )

    # Собираем smeнные записи per unit
    units: dict[tuple, dict] = {}
    for r in unit_rows:
        k = key_of(r)
        if k not in units:
            units[k] = {
                'key': k,
                'equipment_type': r['equipment_type'],
                'brand_model': r['brand_model'] or '—',
                'plate_number': r['plate_number'] or '—',
                'unit_number': r['unit_number'] or '—',
                'ownership': r['ownership_type'] or '—',
                'contractor': r['contractor_name'] or '—',
                'shifts': [],   # [(date, shift, section_code)]
            }
        units[k]['shifts'].append((r['report_date'], r['shift'], _merge_section(r['section_code']) or r['section_code']))

    # 2) Per-unit факт из usage-таблиц.
    # work_item_equipment_usage (eq_id → work_item → wt_code, volume/area)
    work_usage_where = [
        "dwi.report_date BETWEEN %s AND %s",
        _approved_report_exists("dwi"),
    ]
    if not include_work_diagnostics:
        work_usage_where.extend([
            "COALESCE(wt.productivity_enabled, true) = true",
            "COALESCE(dwi.productivity_enabled, true) = true",
        ])
    wieu_rows = query(
        f"""
        SELECT wieu.report_equipment_unit_id AS eq_id,
               dwi.id::text AS work_item_id,
               dwi.report_date, LOWER(COALESCE(dwi.shift,'day')) AS shift,
               cs.code AS section_code,
               wt.code AS wt_code,
               wt.name AS wt_name,
               COALESCE(wt.productivity_enabled, true) AS wt_productivity_enabled,
               COALESCE(dwi.productivity_enabled, true) AS dwi_productivity_enabled,
               COALESCE(NULLIF(dwi.unit, ''), wt.default_unit, '') AS source_unit,
               dwi.volume AS source_volume,
               obj.object_code AS object_code,
               obj.name AS object_name,
               ot.code AS object_type_code,
               ot.name AS object_type_name,
               COALESCE(wieu.worked_volume, wieu.worked_area, dwi.volume) AS fact,
               COALESCE(wieu.work_hours, 11)::numeric AS work_hours,
               CASE
                 WHEN wieu.worked_volume IS NOT NULL THEN 'м³'
                 WHEN wieu.worked_area IS NOT NULL THEN 'м²'
                 WHEN LOWER(BTRIM(REPLACE(COALESCE(dwi.unit, ''), '³', '3'))) IN ('м3', 'm3') THEN 'м³'
                 ELSE 'м²'
               END AS unit
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr_work ON dr_work.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr_work.section_id)
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        WHERE {' AND '.join(work_usage_where)}
        """,
        [d_from, d_to],
    )
    work_fact_rows: list[dict[str, Any]] = []
    for r in wieu_rows:
        work_fact_rows.append({
            'eq_id': str(r['eq_id']),
            'date': r['report_date'], 'shift': r['shift'],
            'section': _merge_section(r['section_code']) or r['section_code'],
            'work_item_id': r.get('work_item_id'),
            'wt_code': r['wt_code'], 'wt_name': r['wt_name'],
            'work_type_productivity_enabled': bool(r.get('wt_productivity_enabled', True)),
            'row_productivity_enabled': bool(r.get('dwi_productivity_enabled', True)),
            'source_volume': float(r['source_volume']) if r.get('source_volume') is not None else None,
            'source_unit': r.get('source_unit'),
            'object_code': r.get('object_code'),
            'object_name': r.get('object_name'),
            'object_type_code': r.get('object_type_code'),
            'object_type_name': r.get('object_type_name'),
            'fact': float(r['fact'] or 0), 'unit': r['unit'],
            'work_hours': float(r['work_hours'] or PRODUCTIVITY_SHIFT_HOURS),
        })
    _mechanization_cap_work_usage_facts(work_fact_rows)
    unit_work_facts: dict[str, list] = {}
    for row in work_fact_rows:
        unit_work_facts.setdefault(row.pop('eq_id'), []).append(row)

    # material_movement_equipment_usage
    mmeu_rows = query(
        f"""
        SELECT mmeu.report_equipment_unit_id AS eq_id,
               mm.id::text AS movement_id,
               mm.report_date, LOWER(COALESCE(mm.shift,'day')) AS shift,
               cs.code AS section_code,
               mm.movement_type, mat.code AS mat,
               mat.name AS material_name,
               src.name AS from_object_name,
               dst.name AS to_object_name,
               mm.unit AS source_unit,
               mm.volume AS source_volume,
               mm.trip_count AS source_trips,
               mm.haul_distance_km,
               COALESCE(mmeu.worked_volume, mm.volume) AS fact,
               COALESCE(mmeu.work_hours, 11)::numeric AS work_hours,
               COALESCE(mmeu.trips_count, 0) AS trips
        FROM material_movement_equipment_usage mmeu
        JOIN material_movements mm ON mm.id = mmeu.material_movement_id
        JOIN daily_reports dr_mov ON dr_mov.id = mm.daily_report_id
        LEFT JOIN materials mat ON mat.id = mm.material_id
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN objects dst ON dst.id = mm.to_object_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr_mov.section_id)
        WHERE mm.report_date BETWEEN %s AND %s
          AND {_approved_report_exists("mm")}
        """,
        [d_from, d_to],
    )
    unit_mov_facts: dict[str, list] = {}
    for r in mmeu_rows:
        eid = str(r['eq_id'])
        unit_mov_facts.setdefault(eid, []).append({
            'date': r['report_date'], 'shift': r['shift'],
            'section': _merge_section(r['section_code']) or r['section_code'],
            'mat': r['mat'], 'mtype': r['movement_type'],
            'movement_id': r.get('movement_id'),
            'material_name': r.get('material_name'),
            'from_object_name': r.get('from_object_name'),
            'to_object_name': r.get('to_object_name'),
            'source_volume': float(r['source_volume']) if r.get('source_volume') is not None else None,
            'source_unit': r.get('source_unit'),
            'source_trips': int(r['source_trips'] or 0),
            'haul_distance_km': float(r['haul_distance_km']) if r.get('haul_distance_km') is not None else None,
            'fact': float(r['fact'] or 0), 'trips': int(r['trips'] or 0),
            'work_hours': float(r['work_hours'] or PRODUCTIVITY_SHIFT_HOURS),
        })

    # 3) Сборка: per unit — суммируем факты из usage-таблиц, норма per работу.
    def dump_truck_norm(sec_num: int, mov) -> tuple[float, str]:
        mat = (mov['mat'] or '').upper()
        mt = mov['mtype']
        if mat in ('SAND', 'COARSE_SAND') and mt in ('pit_to_stockpile', 'pit_to_constructive'):
            tpl = SAND_PIT_DIRECTION_NORMS.get(sec_num)
            label = 'карьер-накопитель' if mt == 'pit_to_stockpile' else 'карьер-конструктив'
            if tpl:
                trips, m3 = tpl
                return trips * m3, f'песок {label} ({trips} рейс × {m3} м³)'
            return GENERIC_TRUCK_NORM, f'песок {label} (норматив {GENERIC_TRUCK_NORM:g} м³/смена)'
        if mat in ('SAND', 'COARSE_SAND') and mt == 'stockpile_to_constructive':
            tpl = SAND_STOCKPILE_TO_CONSTR_NORMS.get(sec_num)
            if tpl:
                trips, m3 = tpl
                return trips * m3, f'песок накопитель-конструктив ({trips} рейс × {m3} м³)'
        return GENERIC_TRUCK_NORM, f'{mat or "материал"} · {_movement_type_label(mt)} (норматив {GENERIC_TRUCK_NORM:g} м³/смена)'

    # Нам нужен eq_id для ключа в usage таблицах. Плюс показываем весь мастер-парк
    # из отчета М даже без факта за выбранный период.
    def unit_key(equipment_type, plate_number, unit_number, fallback_id=None):
        plate = _normalize_equipment_identifier(plate_number)
        if plate:
            return ("plate", plate)
        unit = _normalize_equipment_identifier(unit_number)
        if unit:
            return ((equipment_type or "").lower(), "unit", unit)
        return ((equipment_type or "").lower(), "id", str(fallback_id or ""))

    master_rows = query(
        """
        SELECT id AS master_id,
               equipment_type, brand_model, plate_number, unit_number,
               ownership_type, contractor_name, status, source_name, source_date,
               location, comment
        FROM equipment_units
        WHERE COALESCE(is_active, true) = true
        """,
    )

    units_by_key: dict[tuple, dict] = {}
    master_key_by_id: dict[str, tuple] = {}
    master_key_by_plate: dict[str, tuple] = {}
    for r in master_rows:
        display_plate, display_unit = _equipment_display_identifier_pair(r)
        k = unit_key(r["equipment_type"], display_plate, display_unit, r["master_id"])
        master_key_by_id[str(r["master_id"])] = k
        plate_key = _normalize_equipment_identifier(display_plate)
        if plate_key:
            master_key_by_plate[plate_key] = k
        units_by_key[k] = {
            'key': k,
            'master_equipment_id': str(r['master_id']),
            'equipment_type': r['equipment_type'],
            'brand_model': r['brand_model'] or '—',
            'plate_number': display_plate or '—',
            'unit_number': display_unit or '—',
            'ownership': r['ownership_type'] or '—',
            'contractor': r['contractor_name'] or '—',
            'status': r['status'] or '—',
            'location': r['location'] or None,
            'source_name': r['source_name'] or 'Отчет М',
            'source_date': r['source_date'],
            'eq_ids': [],
            'last_date': None,
            'last_section': _section_from_equipment_location(r['location']),
            'shift_keys': set(),
            'operation': _operation_metric_empty_totals(),
        }

    # Перезапрашиваем id юнитов из суточных отчетов: они дают факты/смены и
    # добавляют технику, которой еще нет в master-парке отчета М.
    id_rows = query(
        f"""
        SELECT reu.id AS eq_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.equipment_type, reu.brand_model, reu.plate_number, reu.unit_number,
               reu.ownership_type, reu.contractor_name, reu.status,
               cs.code AS section_code, dr.report_date,
               LOWER(COALESCE(dr.shift, 'day')) AS shift
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        WHERE {' AND '.join(where)}
        """,
        params,
    )

    # Группируем в первую очередь по госномеру; все сменные eq_ids сохраняем для деталей.
    for r in id_rows:
        master_id = str(r.get('equipment_unit_id') or '')
        display_plate, display_unit = _equipment_display_identifier_pair(r)
        normalized_plate = _normalize_equipment_identifier(display_plate)
        normalized_unit = _normalize_equipment_identifier(display_unit)
        if master_id and master_id in master_key_by_id:
            k = master_key_by_id[master_id]
        elif normalized_plate and normalized_plate in master_key_by_plate:
            k = master_key_by_plate[normalized_plate]
        elif normalized_unit and normalized_unit in master_key_by_plate:
            k = master_key_by_plate[normalized_unit]
        else:
            k = unit_key(r['equipment_type'], display_plate, display_unit, r['eq_id'])
        u = units_by_key.setdefault(k, {
            'key': k,
            'master_equipment_id': r.get('equipment_unit_id'),
            'equipment_type': r['equipment_type'],
            'brand_model': r['brand_model'] or '—',
            'plate_number': display_plate or '—',
            'unit_number': display_unit or '—',
            'ownership': r['ownership_type'] or '—',
            'contractor': r['contractor_name'] or '—',
            'status': 'reported',
            'location': None,
            'source_name': 'суточные отчеты',
            'source_date': None,
            'eq_ids': [],
            'last_date': None,
            'last_section': None,
            'shift_keys': set(),
            'operation': _operation_metric_empty_totals(),
        })
        if not u.get('master_equipment_id') and r.get('equipment_unit_id'):
            u['master_equipment_id'] = r.get('equipment_unit_id')
        u['eq_ids'].append(str(r['eq_id']))
        if _equipment_status_bucket(r.get('status')) == 'working':
            u.setdefault('shift_keys', set()).add((str(r['report_date']), r['shift']))
        if u['last_date'] is None or r['report_date'] > u['last_date']:
            u['last_date'] = r['report_date']
            u['last_section'] = _merge_section(r['section_code']) or r['section_code']
        if u.get('source_name') == 'Отчет М' and not u.get('source_date'):
            u['source_name'] = 'суточные отчеты'

    operation_metrics = _query_equipment_operation_metrics(d_from, d_to, bucket="all")
    for master_id, totals in operation_metrics.get("by_unit", {}).items():
        k = master_key_by_id.get(str(master_id))
        if not k or k not in units_by_key:
            continue
        u = units_by_key[k]
        u["operation"] = totals
        for _unit_id, date_key, shift_key in totals.get("operation_shift_keys") or []:
            u.setdefault("shift_keys", set()).add((date_key, shift_key))

    out_units = []
    for k, u in units_by_key.items():
        raw_et = (u['equipment_type'] or '').lower()
        et = _mechanization_productivity_equipment_type(u.get('equipment_type'))
        per_shift_recs = []
        diagnostic_recs = []
        total_fact = 0.0
        total_expected = 0.0
        total_work_hours = 0.0
        fact_unit = None
        for eq_id in u['eq_ids']:
            # Для не-самосвалов — берём work usage
            if et != 'самосвал':
                for w in unit_work_facts.get(eq_id, []):
                    norm_spec = WORK_TYPE_NORMS.get((et, w['wt_code']))
                    reference_norm = float(norm_spec['norm']) if norm_spec else 0.0
                    adjusted_norm, work_hours = _adjust_productivity_norm(reference_norm, w.get('work_hours'))
                    productivity_flags_enabled = bool(w.get('work_type_productivity_enabled', True)) and bool(w.get('row_productivity_enabled', True))
                    participates = bool(productivity_flags_enabled and norm_spec and adjusted_norm > 0 and w['fact'] > 0)
                    exclusion_reasons = []
                    if not w.get('work_type_productivity_enabled', True):
                        exclusion_reasons.append('тип работы отключен в производительности')
                    if not w.get('row_productivity_enabled', True):
                        exclusion_reasons.append('строка отчета отключена в производительности')
                    if not norm_spec:
                        exclusion_reasons.append(f"нет нормы для {et} + {w['wt_code']}")
                    if w['fact'] <= 0:
                        exclusion_reasons.append('нет объема/площади по единице техники')
                    if w.get('fact_adjustment_reason'):
                        if not exclusion_reasons:
                            exclusion_reasons.append('учтено в нормируемом факте')
                        exclusion_reasons.append(w['fact_adjustment_reason'])
                    work_label = w.get('wt_name') or w['wt_code']
                    diagnostic_recs.append({
                        'kind': 'work',
                        'work_item_id': w.get('work_item_id'),
                        'date': w['date'].isoformat(),
                        'shift': w['shift'],
                        'section': w['section'],
                        'object_code': w.get('object_code'),
                        'object_name': w.get('object_name'),
                        'object_type_code': w.get('object_type_code'),
                        'object_type_name': w.get('object_type_name'),
                        'work': work_label,
                        'wt_code': w['wt_code'],
                        'fact': round(w['fact'], 1),
                        'raw_fact': round(w['raw_fact'], 1) if w.get('raw_fact') is not None else None,
                        'unit': w['unit'],
                        'source_volume': round(w['source_volume'], 1) if w.get('source_volume') is not None else None,
                        'source_unit': w.get('source_unit'),
                        'work_hours': round(work_hours, 2),
                        'reference_norm': round(reference_norm, 1) if norm_spec else None,
                        'norm': round(adjusted_norm, 1) if norm_spec else None,
                        'norm_unit': norm_spec.get('unit') if norm_spec else None,
                        'norm_code': norm_spec.get('code') if norm_spec else None,
                        'norm_name': norm_spec.get('norm_name') if norm_spec else None,
                        'percent': round(w['fact'] / adjusted_norm * 100, 1) if norm_spec and adjusted_norm > 0 and w['fact'] > 0 else None,
                        'participates_in_productivity': participates,
                        'exclusion_reason': '; '.join(exclusion_reasons) if exclusion_reasons else None,
                        'productivity_equipment_type': et,
                        'raw_equipment_type': raw_et,
                        'work_type_productivity_enabled': bool(w.get('work_type_productivity_enabled', True)),
                        'row_productivity_enabled': bool(w.get('row_productivity_enabled', True)),
                    })
                    if not participates:
                        continue
                    total_fact += w['fact']
                    total_expected += adjusted_norm
                    total_work_hours += work_hours
                    fact_unit = norm_spec['unit']
                    per_shift_recs.append({
                        'date': w['date'].isoformat(), 'shift': w['shift'], 'section': w['section'],
                        'work': work_label,
                        'unit': norm_spec['unit'],
                        'fact': round(w['fact'], 1),
                        'work_hours': round(work_hours, 2),
                        'reference_norm': reference_norm,
                        'norm': adjusted_norm,
                        'percent': round(w['fact'] / adjusted_norm * 100, 1) if adjusted_norm > 0 else None,
                    })
            else:
                for mov in unit_mov_facts.get(eq_id, []):
                    sec_num = _sec_code_to_num(mov['section'])
                    norm, label = dump_truck_norm(sec_num or 0, mov)
                    reference_norm = float(norm)
                    adjusted_norm, work_hours = _adjust_productivity_norm(reference_norm, mov.get('work_hours'))
                    participates = bool(mov['fact'] > 0 and adjusted_norm > 0)
                    route = " - ".join(part for part in (mov.get('from_object_name'), mov.get('to_object_name')) if part)
                    diagnostic_recs.append({
                        'kind': 'movement',
                        'movement_id': mov.get('movement_id'),
                        'date': mov['date'].isoformat(),
                        'shift': mov['shift'],
                        'section': mov['section'],
                        'object_code': None,
                        'object_name': route or None,
                        'object_type_code': None,
                        'object_type_name': 'Перевозка',
                        'work': label,
                        'wt_code': mov.get('mtype'),
                        'material_code': mov.get('mat'),
                        'material_name': mov.get('material_name'),
                        'movement_type': mov.get('mtype'),
                        'fact': round(mov['fact'], 1),
                        'unit': 'м³',
                        'trips': int(mov.get('trips') or 0),
                        'source_volume': round(mov['source_volume'], 1) if mov.get('source_volume') is not None else None,
                        'source_unit': mov.get('source_unit') or 'м³',
                        'source_trips': int(mov.get('source_trips') or 0),
                        'haul_distance_km': round(mov['haul_distance_km'], 2) if mov.get('haul_distance_km') is not None else None,
                        'work_hours': round(work_hours, 2),
                        'reference_norm': round(reference_norm, 1) if norm else None,
                        'norm': round(adjusted_norm, 1) if norm else None,
                        'norm_unit': 'м³',
                        'norm_code': mov.get('mtype'),
                        'norm_name': label,
                        'percent': round(mov['fact'] / adjusted_norm * 100, 1) if adjusted_norm > 0 and mov['fact'] > 0 else None,
                        'participates_in_productivity': participates,
                        'exclusion_reason': None if participates else 'нет объема перевозки по единице техники',
                        'productivity_equipment_type': et,
                        'raw_equipment_type': raw_et,
                        'work_type_productivity_enabled': True,
                        'row_productivity_enabled': True,
                    })
                    if not participates:
                        continue
                    total_fact += mov['fact']
                    total_expected += adjusted_norm
                    total_work_hours += work_hours
                    fact_unit = 'м³'
                    per_shift_recs.append({
                        'date': mov['date'].isoformat(), 'shift': mov['shift'], 'section': mov['section'],
                        'work': label, 'unit': 'м³', 'fact': round(mov['fact'], 1),
                        'work_hours': round(work_hours, 2),
                        'reference_norm': round(reference_norm, 1),
                        'norm': round(adjusted_norm, 1),
                        'percent': round(mov['fact'] / adjusted_norm * 100, 1) if adjusted_norm > 0 else None,
                    })

        shift_pcts = [float(item['percent']) for item in per_shift_recs if item.get('percent') and item['percent'] > 0]
        shift_count = len(u.get('shift_keys') or [])
        operation_payload = _operation_totals_payload(u.get("operation"))
        if shift_pcts:
            pct = sum(shift_pcts) / len(shift_pcts)
        elif shift_count > 0:
            pct = 0.0
        else:
            pct = None
        out_units.append({
            'merge_key': "|".join(str(part or "") for part in k),
            'master_equipment_id': u.get('master_equipment_id'),
            'report_equipment_ids': u['eq_ids'],
            'equipment_type': u['equipment_type'],
            'productivity_equipment_type': et,
            'brand_model': u['brand_model'],
            'plate_number': u['plate_number'],
            'unit_number': u['unit_number'],
            'ownership': u['ownership'],
            'contractor': u['contractor'],
            'status': u.get('status') or '—',
            'location': u.get('location'),
            'source_name': u.get('source_name'),
            'source_date': u['source_date'].isoformat() if u.get('source_date') else None,
            'last_section': u['last_section'],
            'last_date': u['last_date'].isoformat() if u['last_date'] else None,
            'shifts_worked': shift_count,
            'fact_total': round(total_fact, 1),
            'expected_total': round(total_expected, 1),
            'work_hours_total': round(total_work_hours, 2),
            'fact_unit': fact_unit,
            'percent': round(pct, 1) if pct is not None else None,
            'details': per_shift_recs,
            **operation_payload,
            **({'work_details': diagnostic_recs} if include_work_diagnostics else {}),
        })

    deduped_units: dict[tuple, dict] = {}
    for item in out_units:
        plate_key = _normalize_equipment_identifier(item.get('plate_number'))
        if plate_key:
            dedup_key = ('plate', plate_key)
        elif item.get('master_equipment_id'):
            dedup_key = ('master', str(item.get('master_equipment_id')))
        else:
            dedup_key = ('row', item.get('merge_key') or '')
        existing = deduped_units.get(dedup_key)
        if not existing:
            deduped_units[dedup_key] = item
            continue
        existing_ids = list(existing.get('report_equipment_ids') or [])
        for eq_id in item.get('report_equipment_ids') or []:
            if eq_id not in existing_ids:
                existing_ids.append(eq_id)
        existing['report_equipment_ids'] = existing_ids
        if not existing.get('master_equipment_id') and item.get('master_equipment_id'):
            existing['master_equipment_id'] = item.get('master_equipment_id')
        for field in ('productivity_equipment_type', 'brand_model', 'plate_number', 'unit_number', 'ownership', 'contractor', 'status', 'location', 'source_name', 'source_date', 'last_section', 'last_date'):
            if existing.get(field) in (None, '', '—') and item.get(field) not in (None, '', '—'):
                existing[field] = item.get(field)
        existing['shifts_worked'] = int(existing.get('shifts_worked') or 0) + int(item.get('shifts_worked') or 0)
        existing['fact_total'] = round(float(existing.get('fact_total') or 0) + float(item.get('fact_total') or 0), 1)
        existing['expected_total'] = round(float(existing.get('expected_total') or 0) + float(item.get('expected_total') or 0), 1)
        existing['mileage_km_total'] = round(float(existing.get('mileage_km_total') or 0) + float(item.get('mileage_km_total') or 0), 1)
        existing['engine_hours_total'] = round(float(existing.get('engine_hours_total') or 0) + float(item.get('engine_hours_total') or 0), 1)
        existing['fuel_liters_total'] = round(float(existing.get('fuel_liters_total') or 0) + float(item.get('fuel_liters_total') or 0), 1)
        existing['operation_metric_rows'] = int(existing.get('operation_metric_rows') or 0) + int(item.get('operation_metric_rows') or 0)
        existing['operation_work_shifts'] = int(existing.get('operation_work_shifts') or 0) + int(item.get('operation_work_shifts') or 0)
        if not existing.get('fact_unit') and item.get('fact_unit'):
            existing['fact_unit'] = item.get('fact_unit')
        existing['details'] = [*(existing.get('details') or []), *(item.get('details') or [])]
        if include_work_diagnostics:
            existing['work_details'] = [*(existing.get('work_details') or []), *(item.get('work_details') or [])]
        shift_pcts = [float(detail['percent']) for detail in existing['details'] if detail.get('percent') and detail['percent'] > 0]
        if shift_pcts:
            existing['percent'] = round(sum(shift_pcts) / len(shift_pcts), 1)
        elif existing['shifts_worked'] > 0:
            existing['percent'] = 0.0
        else:
            existing['percent'] = None
    out_units = list(deduped_units.values())

    # Сортировка: по последнему участку (desc по номеру), затем по типу техники.
    def sort_key(x):
        sec_n = _sec_code_to_num(x['last_section']) or 99
        return (sec_n, x['equipment_type'] or '', x['plate_number'] or '')

    out_units.sort(key=sort_key)
    return {
        'from': d_from.isoformat(),
        'to': d_to.isoformat(),
        'count': len(out_units),
        'units': out_units,
    }


def _mechanization_target_identifier_types(value: Optional[str]) -> list[str]:
    if value == "plate":
        return ["plate"]
    if value == "unit":
        return ["unit"]
    return ["plate", "unit"]


def _mechanization_row_matches_identifier(row: dict, normalized: str, identifier_types: list[str]) -> bool:
    if "plate" in identifier_types and _normalize_equipment_identifier(row.get("plate_number")) == normalized:
        return True
    if "unit" in identifier_types and _normalize_equipment_identifier(row.get("unit_number")) == normalized:
        return True
    return False


def _mechanization_equipment_label(row: dict) -> str:
    parts = [
        row.get("equipment_type"),
        row.get("brand_model"),
        f"б/н {row.get('unit_number')}" if row.get("unit_number") else None,
        f"г/н {row.get('plate_number')}" if row.get("plate_number") else None,
    ]
    return " · ".join(str(part) for part in parts if part)


def _mechanization_merge_note(target_label: str) -> str:
    return f"merged into {target_label} via mechanization cleanup"


def _mechanization_validate_report_ids(values: list[str]) -> list[str]:
    ids = list(dict.fromkeys(str(value or "").strip() for value in values))
    ids = [value for value in ids if value]
    if not ids:
        raise HTTPException(400, "Не выбраны строки техники из отчета")
    if any(not re.fullmatch(r"[0-9a-fA-F-]{36}", value) for value in ids):
        raise HTTPException(400, "Некорректный id строки техники")
    return ids


def _mechanization_type_family(value: Optional[str]) -> str:
    text = str(value or "").strip().lower().replace("ё", "е")
    if any(part in text for part in ("самос", "dump", "truck")):
        return "dump_truck"
    if any(part in text for part in ("экскав", "excav")):
        return "excavator"
    if any(part in text for part in ("бульд", "dozer")):
        return "bulldozer"
    if any(part in text for part in ("каток", "roller")):
        return "roller"
    if any(part in text for part in ("грейдер", "grader")):
        return "grader"
    if any(part in text for part in ("кран", "crane")):
        return "crane"
    if any(part in text for part in ("погруз", "loader")):
        return "loader"
    return re.sub(r"\s+", " ", text)


def _mechanization_productivity_equipment_type(value: Optional[str]) -> str:
    """Canonical equipment key used by productivity norms and dashboard cards."""
    text = str(value or "").strip().lower().replace("ё", "е")
    if any(part in text for part in ("самос", "dump", "truck")):
        return "самосвал"
    if "экскав" in text:
        return "экскаватор"
    if "бульд" in text:
        return "бульдозер"
    if "грейдер" in text or "grader" in text:
        return "автогрейдер"
    if "каток" in text or "roller" in text:
        return "каток"
    return re.sub(r"\s+", " ", text)


def _mechanization_work_fact_unit_key(value: Optional[str]) -> str:
    text = str(value or "").strip().lower().replace("³", "3").replace("²", "2")
    text = re.sub(r"\s+", "", text)
    if text in {"м3", "m3"}:
        return "m3"
    if text in {"м2", "m2"}:
        return "m2"
    return text


def _mechanization_cap_work_usage_facts(rows: list[dict[str, Any]]) -> None:
    grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for row in rows:
        work_item_id = str(row.get("work_item_id") or "").strip()
        if not work_item_id:
            continue
        fact_unit = _mechanization_work_fact_unit_key(row.get("unit"))
        source_unit = _mechanization_work_fact_unit_key(row.get("source_unit"))
        if not fact_unit or fact_unit != source_unit:
            continue
        grouped.setdefault((work_item_id, fact_unit), []).append(row)

    for (_work_item_id, _unit), group in grouped.items():
        source_values = [
            float(row.get("source_volume") or 0)
            for row in group
            if row.get("source_volume") is not None
        ]
        source_volume = max(source_values, default=0.0)
        if source_volume <= 0:
            continue
        raw_total = sum(max(0.0, float(row.get("fact") or 0)) for row in group)
        if raw_total <= source_volume + 0.0005:
            continue
        factor = source_volume / raw_total
        for row in group:
            raw_fact = float(row.get("fact") or 0)
            row["raw_fact"] = raw_fact
            row["fact"] = raw_fact * factor
            row["fact_adjustment_reason"] = (
                f"объем техники ограничен фактом строки отчета: "
                f"{source_volume:g} {row.get('source_unit') or row.get('unit') or ''}"
            ).strip()


def _mechanization_identifier_values(row: dict) -> list[tuple[str, str, str]]:
    out: list[tuple[str, str, str]] = []
    for field, label in (("plate_number", "госномер"), ("unit_number", "бортовой")):
        raw = str(row.get(field) or "").strip()
        normalized = _normalize_equipment_identifier(raw)
        if not normalized or normalized in {"НД", "НЕТ", "NONE", "NULL", "UNKNOWN"}:
            continue
        if normalized in {"-", "—"}:
            continue
        out.append((field, label, normalized))
    return out


def _mechanization_report_needs_cleanup(master: dict, report: dict) -> bool:
    master_id = str(master.get("master_equipment_id") or master.get("id") or "")
    report_master_ids = {str(value) for value in (report.get("master_ids") or []) if value}
    if master_id and master_id not in report_master_ids:
        return True

    comparable_fields = ("equipment_type", "brand_model", "plate_number", "unit_number", "ownership", "contractor")
    for field in comparable_fields:
        master_value = _normalize_equipment_identifier(master.get(field)) if field in ("plate_number", "unit_number") else str(master.get(field) or "").strip().lower()
        report_value = _normalize_equipment_identifier(report.get(field)) if field in ("plate_number", "unit_number") else str(report.get(field) or "").strip().lower()
        if master_value != report_value:
            return True
    return False


def _mechanization_duplicate_score(master: dict, report: dict) -> tuple[float, str]:
    if _mechanization_type_family(master.get("equipment_type")) != _mechanization_type_family(report.get("equipment_type")):
        return 0.0, ""

    best_score = 0.0
    best_reason = ""
    for _, master_label, master_value in _mechanization_identifier_values(master):
        for _, report_label, report_value in _mechanization_identifier_values(report):
            if master_value == report_value:
                score = 1.0
                reason = f"{master_label} совпадает: {master_value}"
            elif min(len(master_value), len(report_value)) >= 4 and (
                master_value.startswith(report_value)
                or report_value.startswith(master_value)
                or master_value in report_value
                or report_value in master_value
            ):
                score = 0.92
                reason = f"{master_label}/{report_label} похожи: {master_value} ↔ {report_value}"
            elif (
                master_value.isdigit()
                and report_value.isdigit()
                and min(len(master_value), len(report_value)) >= 3
                and (master_value in report_value or report_value in master_value)
            ):
                score = 0.78
                reason = f"{master_label}/{report_label} похожи по цифрам: {master_value} ↔ {report_value}"
            else:
                continue
            if score > best_score:
                best_score = score
                best_reason = reason

    if best_score <= 0 or not _mechanization_report_needs_cleanup(master, report):
        return 0.0, ""
    return best_score, best_reason


def _mechanization_cleanup_label(row: dict) -> str:
    parts = [
        row.get("equipment_type"),
        row.get("brand_model") if row.get("brand_model") != "—" else None,
        f"г/н {row.get('plate_number')}" if row.get("plate_number") and row.get("plate_number") != "—" else None,
        f"б/н {row.get('unit_number')}" if row.get("unit_number") and row.get("unit_number") != "—" else None,
    ]
    return " · ".join(str(part) for part in parts if part) or "Техника без номера"


def _mechanization_cleanup_row(row: dict, kind: str) -> dict:
    first_date = row.get("first_date")
    last_date = row.get("last_date")
    source_date = row.get("source_date")
    return {
        "kind": kind,
        "master_equipment_id": row.get("master_equipment_id"),
        "report_equipment_ids": row.get("report_equipment_ids") or [],
        "label": _mechanization_cleanup_label(row),
        "equipment_type": row.get("equipment_type") or "—",
        "brand_model": row.get("brand_model") or "—",
        "plate_number": row.get("plate_number") or "—",
        "unit_number": row.get("unit_number") or "—",
        "ownership": row.get("ownership") or "—",
        "contractor": row.get("contractor") or "—",
        "status": row.get("status"),
        "source_name": row.get("source_name"),
        "source_date": source_date.isoformat() if hasattr(source_date, "isoformat") else source_date,
        "location": row.get("location"),
        "first_date": first_date.isoformat() if hasattr(first_date, "isoformat") else first_date,
        "last_date": last_date.isoformat() if hasattr(last_date, "isoformat") else last_date,
        "shifts_count": int(row.get("shifts_count") or 0),
    }


_MECHANIZATION_EMPTY_IDENTIFIERS = {"", "-", "—", "НД", "НЕТ", "NONE", "NULL", "UNKNOWN", "БН", "БЕЗНОМЕРА"}


def _mechanization_normalized_plate(row: dict) -> str:
    value = _normalize_equipment_identifier(row.get("plate_number"))
    if not value or value in _MECHANIZATION_EMPTY_IDENTIFIERS:
        return ""
    return value


def _mechanization_row_quality(row: dict) -> tuple[int, int]:
    filled_fields = (
        "equipment_type",
        "brand_model",
        "plate_number",
        "unit_number",
        "ownership_type",
        "contractor_name",
        "status",
        "location",
    )
    filled = sum(1 for field in filled_fields if str(row.get(field) or "").strip() not in {"", "—"})
    usage = int(row.get("usage_count") or row.get("linked_count") or 0)
    return usage, filled


def _mechanization_pick_duplicate_target(rows: list[dict]) -> dict:
    def score(row: dict) -> tuple[int, int, int, str, str]:
        usage, filled = _mechanization_row_quality(row)
        has_master = 1 if row.get("equipment_unit_id") or row.get("id") else 0
        date_value = row.get("source_date") or row.get("report_date") or row.get("updated_at") or row.get("created_at") or ""
        return (has_master, usage, filled, str(date_value), str(row.get("id") or ""))

    return sorted(rows, key=score, reverse=True)[0]


@router.post("/mechanization/cleanup/merge-duplicates")
def mechanization_cleanup_merge_duplicates(body: MechanizationDuplicateMergeBody, _user=Depends(current_user)):
    d_from, d_to = _parse_range(body.date_from, body.date_to)

    master_rows = query(
        """
        SELECT eu.id::text AS id,
               eu.equipment_type,
               eu.brand_model,
               eu.unit_number,
               eu.plate_number,
               eu.ownership_type,
               eu.contractor_name,
               eu.status,
               eu.source_name,
               eu.source_date,
               eu.location,
               eu.comment,
               eu.created_at,
               eu.updated_at,
               COALESCE(linked.linked_count, 0)::int AS linked_count
        FROM equipment_units eu
        LEFT JOIN (
          SELECT equipment_unit_id, COUNT(*)::int AS linked_count
          FROM report_equipment_units
          WHERE equipment_unit_id IS NOT NULL
          GROUP BY equipment_unit_id
        ) linked ON linked.equipment_unit_id = eu.id
        WHERE eu.is_active IS NOT FALSE
          AND NULLIF(TRIM(eu.plate_number), '') IS NOT NULL
        ORDER BY eu.source_date DESC NULLS LAST, eu.updated_at DESC NULLS LAST, eu.id
        """
    )
    master_groups: dict[str, list[dict]] = {}
    for row in master_rows:
        plate = _mechanization_normalized_plate(row)
        if not plate:
            continue
        master_groups.setdefault(plate, []).append(row)

    canonical_master_by_plate: dict[str, str] = {}
    master_by_id: dict[str, dict] = {str(row["id"]): row for row in master_rows}
    master_merge_groups: list[dict] = []
    for plate, rows in master_groups.items():
        target = _mechanization_pick_duplicate_target(rows)
        target_id = str(target["id"])
        canonical_master_by_plate[plate] = target_id
        source_ids = [str(row["id"]) for row in rows if str(row["id"]) != target_id]
        if not source_ids:
            continue
        master_merge_groups.append({
            "plate": plate,
            "target": target,
            "source_ids": source_ids,
            "source_labels": [_mechanization_equipment_label(row) for row in rows if str(row["id"]) != target_id],
        })

    report_rows = query(
        """
        SELECT reu.id::text AS id,
               reu.daily_report_id::text AS daily_report_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.equipment_type,
               reu.brand_model,
               reu.unit_number,
               reu.plate_number,
               reu.ownership_type,
               reu.contractor_name,
               reu.status,
               reu.comment,
               reu.created_at,
               dr.report_date,
               LOWER(COALESCE(dr.shift, 'day')) AS shift,
               COALESCE(wu.usage_count, 0)::int AS work_usage_count,
               COALESCE(mu.usage_count, 0)::int AS movement_usage_count,
               (COALESCE(wu.usage_count, 0) + COALESCE(mu.usage_count, 0))::int AS usage_count
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN (
          SELECT report_equipment_unit_id, COUNT(*)::int AS usage_count
          FROM work_item_equipment_usage
          GROUP BY report_equipment_unit_id
        ) wu ON wu.report_equipment_unit_id = reu.id
        LEFT JOIN (
          SELECT report_equipment_unit_id, COUNT(*)::int AS usage_count
          FROM material_movement_equipment_usage
          GROUP BY report_equipment_unit_id
        ) mu ON mu.report_equipment_unit_id = reu.id
        WHERE dr.report_date BETWEEN %s AND %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND reu.is_demo IS NOT TRUE
          AND NULLIF(TRIM(reu.plate_number), '') IS NOT NULL
        ORDER BY dr.report_date, LOWER(COALESCE(dr.shift, 'day')), reu.id
        """,
        [d_from, d_to],
    )

    report_groups: dict[tuple[str, str], list[dict]] = {}
    report_link_ids_by_master: dict[str, list[str]] = {}
    for row in report_rows:
        plate = _mechanization_normalized_plate(row)
        if not plate:
            continue
        report_groups.setdefault((str(row["daily_report_id"]), plate), []).append(row)
        target_master_id = canonical_master_by_plate.get(plate)
        if target_master_id and str(row.get("equipment_unit_id") or "") != target_master_id:
            report_link_ids_by_master.setdefault(target_master_id, []).append(str(row["id"]))

    report_merge_groups: list[dict] = []
    for (report_id, plate), rows in report_groups.items():
        if len(rows) < 2:
            continue
        target = _mechanization_pick_duplicate_target(rows)
        target_id = str(target["id"])
        source_rows = [row for row in rows if str(row["id"]) != target_id]
        target_master_id = canonical_master_by_plate.get(plate) or str(target.get("equipment_unit_id") or "") or None
        report_merge_groups.append({
            "report_id": report_id,
            "plate": plate,
            "target": target,
            "target_master_id": target_master_id,
            "source_rows": source_rows,
        })

    dry_run = bool(body.dry_run)
    result = {
        "ok": True,
        "dry_run": dry_run,
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "merged_master_groups": len(master_merge_groups),
        "deactivated_master_units": sum(len(group["source_ids"]) for group in master_merge_groups),
        "relinked_master_references": sum(
            int(master_by_id.get(source_id, {}).get("linked_count") or 0)
            for group in master_merge_groups
            for source_id in group["source_ids"]
        ),
        "merged_report_groups": len(report_merge_groups),
        "hidden_report_units": sum(len(group["source_rows"]) for group in report_merge_groups),
        "linked_report_units": sum(len(ids) for ids in report_link_ids_by_master.values()),
        "moved_work_usage": sum(
            int(row.get("work_usage_count") or 0)
            for group in report_merge_groups
            for row in group["source_rows"]
        ),
        "moved_movement_usage": sum(
            int(row.get("movement_usage_count") or 0)
            for group in report_merge_groups
            for row in group["source_rows"]
        ),
        "groups": [
            {
                "plate": group["plate"],
                "target": _mechanization_equipment_label(group["target"]),
                "sources": group["source_labels"][:5],
            }
            for group in master_merge_groups[:20]
        ],
    }
    if dry_run:
        return result

    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                deactivated_master_units = 0
                relinked_master_references = 0
                for group in master_merge_groups:
                    target = group["target"]
                    target_id = str(target["id"])
                    source_ids = group["source_ids"]
                    target_label = _mechanization_equipment_label(target)
                    cur.execute(
                        """
                        UPDATE report_equipment_units
                        SET equipment_unit_id = %s::uuid,
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                        WHERE equipment_unit_id = ANY(%s::uuid[])
                        """,
                        (target_id, _mechanization_merge_note(target_label), source_ids),
                    )
                    relinked_master_references += cur.rowcount
                    cur.execute(
                        """
                        UPDATE equipment_units
                        SET is_active = false,
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s),
                            updated_at = now()
                        WHERE id = ANY(%s::uuid[])
                          AND is_active IS NOT FALSE
                        """,
                        (f"deactivated as duplicate of {target_label} via mechanization cleanup", source_ids),
                    )
                    deactivated_master_units += cur.rowcount

                linked_report_units = 0
                for target_master_id, report_ids in report_link_ids_by_master.items():
                    master = master_by_id.get(target_master_id)
                    if not master or not report_ids:
                        continue
                    target_label = _mechanization_equipment_label(master)
                    cur.execute(
                        """
                        UPDATE report_equipment_units
                        SET equipment_unit_id = %s::uuid,
                            equipment_type = COALESCE(NULLIF(%s, ''), equipment_type),
                            brand_model = COALESCE(NULLIF(%s, ''), brand_model),
                            unit_number = COALESCE(NULLIF(%s, ''), unit_number),
                            plate_number = COALESCE(NULLIF(%s, ''), plate_number),
                            ownership_type = COALESCE(NULLIF(%s, ''), ownership_type),
                            contractor_name = COALESCE(NULLIF(%s, ''), contractor_name),
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                        WHERE id = ANY(%s::uuid[])
                          AND is_demo IS NOT TRUE
                          AND equipment_unit_id IS DISTINCT FROM %s::uuid
                        """,
                        (
                            target_master_id,
                            master.get("equipment_type"),
                            master.get("brand_model"),
                            master.get("unit_number"),
                            master.get("plate_number"),
                            master.get("ownership_type"),
                            master.get("contractor_name"),
                            _mechanization_merge_note(target_label),
                            report_ids,
                            target_master_id,
                        ),
                    )
                    linked_report_units += cur.rowcount

                hidden_report_units = 0
                moved_work_usage = 0
                moved_movement_usage = 0
                for group in report_merge_groups:
                    target = group["target"]
                    target_id = str(target["id"])
                    source_ids = [str(row["id"]) for row in group["source_rows"]]
                    if not source_ids:
                        continue
                    target_master_id = group.get("target_master_id")
                    master = master_by_id.get(str(target_master_id or ""))
                    target_label = _mechanization_equipment_label(master or target)
                    cur.execute(
                        """
                        UPDATE work_item_equipment_usage
                        SET report_equipment_unit_id = %s::uuid
                        WHERE report_equipment_unit_id = ANY(%s::uuid[])
                        """,
                        (target_id, source_ids),
                    )
                    moved_work_usage += cur.rowcount
                    cur.execute(
                        """
                        UPDATE material_movement_equipment_usage
                        SET report_equipment_unit_id = %s::uuid
                        WHERE report_equipment_unit_id = ANY(%s::uuid[])
                        """,
                        (target_id, source_ids),
                    )
                    moved_movement_usage += cur.rowcount
                    cur.execute(
                        """
                        UPDATE report_equipment_units
                        SET is_demo = true,
                            equipment_unit_id = COALESCE(%s::uuid, equipment_unit_id),
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                        WHERE id = ANY(%s::uuid[])
                          AND is_demo IS NOT TRUE
                        """,
                        (target_master_id, _mechanization_merge_note(target_label), source_ids),
                    )
                    hidden_report_units += cur.rowcount

                result.update({
                    "deactivated_master_units": deactivated_master_units,
                    "relinked_master_references": relinked_master_references,
                    "linked_report_units": linked_report_units,
                    "hidden_report_units": hidden_report_units,
                    "moved_work_usage": moved_work_usage,
                    "moved_movement_usage": moved_movement_usage,
                })
    finally:
        conn.close()

    return result


@router.post("/mechanization/units/merge")
def mechanization_merge_unit(body: MechanizationUnitMergeBody, _user=Depends(current_user)):
    source_ids = list(dict.fromkeys(str(value or "").strip() for value in body.source_report_equipment_ids))
    source_ids = [value for value in source_ids if value]
    if not source_ids:
        raise HTTPException(400, "Не выбрана строка техники из отчета")
    if any(not re.fullmatch(r"[0-9a-fA-F-]{36}", value) for value in source_ids):
        raise HTTPException(400, "Некорректный id строки техники")

    normalized_target = _normalize_equipment_identifier(body.target_identifier)
    if not normalized_target:
        raise HTTPException(400, "Укажи госномер или бортовой номер")
    identifier_types = _mechanization_target_identifier_types(body.target_identifier_type)

    source_rows = query(
        """
        SELECT reu.id::text AS id,
               reu.daily_report_id::text AS daily_report_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.equipment_type,
               reu.brand_model,
               reu.unit_number,
               reu.plate_number,
               reu.ownership_type,
               reu.contractor_name,
               reu.comment
        FROM report_equipment_units reu
        WHERE reu.id = ANY(%s::uuid[])
          AND reu.is_demo IS NOT TRUE
        """,
        [source_ids],
    )
    if not source_rows:
        raise HTTPException(404, "Не нашел выбранную строку техники")
    found_source_ids = {row["id"] for row in source_rows}
    missing = [value for value in source_ids if value not in found_source_ids]
    if missing:
        raise HTTPException(404, f"Часть строк техники уже неактивна или не найдена: {', '.join(missing[:3])}")

    report_ids = list(dict.fromkeys(str(row["daily_report_id"]) for row in source_rows))
    source_set = set(source_ids)

    master_candidates = query(
        """
        SELECT id::text AS id,
               equipment_type,
               brand_model,
               unit_number,
               plate_number,
               ownership_type,
               contractor_name,
               source_date,
               updated_at
        FROM equipment_units
        WHERE is_active IS NOT FALSE
        ORDER BY source_date DESC NULLS LAST, updated_at DESC NULLS LAST
        """
    )
    master_matches = [
        row for row in master_candidates
        if _mechanization_row_matches_identifier(row, normalized_target, identifier_types)
    ]
    master_by_id: dict[str, dict] = {}
    for row in master_matches:
        master_by_id.setdefault(row["id"], row)
    master_matches = list(master_by_id.values())
    if len(master_matches) > 1:
        raise HTTPException(
            409,
            {
                "message": "По этому номеру найдено несколько активных единиц техники. Уточни тип номера или справочник.",
                "candidates": [
                    {"id": row["id"], "label": _mechanization_equipment_label(row)}
                    for row in master_matches[:10]
                ],
            },
        )
    target_master = master_matches[0] if master_matches else None

    report_candidates = query(
        """
        SELECT reu.id::text AS id,
               reu.daily_report_id::text AS daily_report_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.equipment_type,
               reu.brand_model,
               reu.unit_number,
               reu.plate_number,
               reu.ownership_type,
               reu.contractor_name
        FROM report_equipment_units reu
        WHERE reu.daily_report_id = ANY(%s::uuid[])
          AND reu.id <> ALL(%s::uuid[])
          AND reu.is_demo IS NOT TRUE
        """,
        [report_ids, source_ids],
    )
    report_matches = [
        row for row in report_candidates
        if _mechanization_row_matches_identifier(row, normalized_target, identifier_types)
    ]
    report_targets_by_report: dict[str, dict] = {}
    for row in report_matches:
        report_id = row["daily_report_id"]
        if report_id in report_targets_by_report:
            raise HTTPException(
                409,
                {
                    "message": "В одном отчете найдено несколько строк техники с таким номером. Сначала почисти справочник точнее.",
                    "report_id": report_id,
                },
            )
        report_targets_by_report[report_id] = row

    if target_master is None and not report_targets_by_report:
        raise HTTPException(404, "Не нашел активную технику с таким госномером/бортовым")

    target_label = _mechanization_equipment_label(target_master or next(iter(report_targets_by_report.values())))
    updated_sources = 0
    hidden_sources = 0
    moved_work_usage = 0
    moved_movement_usage = 0

    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                for source in source_rows:
                    source_id = source["id"]
                    report_target = report_targets_by_report.get(source["daily_report_id"])
                    if report_target:
                        if target_master is not None:
                            cur.execute(
                                """
                                UPDATE report_equipment_units
                                SET equipment_unit_id = %s,
                                    equipment_type = COALESCE(NULLIF(%s, ''), equipment_type),
                                    brand_model = COALESCE(NULLIF(%s, ''), brand_model),
                                    unit_number = COALESCE(NULLIF(%s, ''), unit_number),
                                    plate_number = COALESCE(NULLIF(%s, ''), plate_number),
                                    ownership_type = COALESCE(NULLIF(%s, ''), ownership_type),
                                    contractor_name = COALESCE(NULLIF(%s, ''), contractor_name)
                                WHERE id = %s
                                """,
                                (
                                    target_master["id"],
                                    target_master.get("equipment_type"),
                                    target_master.get("brand_model"),
                                    target_master.get("unit_number"),
                                    target_master.get("plate_number"),
                                    target_master.get("ownership_type"),
                                    target_master.get("contractor_name"),
                                    report_target["id"],
                                ),
                            )
                        cur.execute(
                            """
                            UPDATE work_item_equipment_usage
                            SET report_equipment_unit_id = %s
                            WHERE report_equipment_unit_id = %s
                            """,
                            (report_target["id"], source_id),
                        )
                        moved_work_usage += cur.rowcount
                        cur.execute(
                            """
                            UPDATE material_movement_equipment_usage
                            SET report_equipment_unit_id = %s
                            WHERE report_equipment_unit_id = %s
                            """,
                            (report_target["id"], source_id),
                        )
                        moved_movement_usage += cur.rowcount
                        cur.execute(
                            """
                            UPDATE report_equipment_units
                            SET is_demo = true,
                                equipment_unit_id = COALESCE(%s::uuid, equipment_unit_id),
                                comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                            WHERE id = %s
                            """,
                            (report_target.get("equipment_unit_id"), _mechanization_merge_note(target_label), source_id),
                        )
                        hidden_sources += cur.rowcount
                        continue

                    target = target_master
                    if target is None:
                        continue
                    cur.execute(
                        """
                        UPDATE report_equipment_units
                        SET equipment_unit_id = %s,
                            equipment_type = COALESCE(NULLIF(%s, ''), equipment_type),
                            brand_model = COALESCE(NULLIF(%s, ''), brand_model),
                            unit_number = COALESCE(NULLIF(%s, ''), unit_number),
                            plate_number = COALESCE(NULLIF(%s, ''), plate_number),
                            ownership_type = COALESCE(NULLIF(%s, ''), ownership_type),
                            contractor_name = COALESCE(NULLIF(%s, ''), contractor_name),
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                        WHERE id = %s
                        """,
                        (
                            target["id"],
                            target.get("equipment_type"),
                            target.get("brand_model"),
                            target.get("unit_number"),
                            target.get("plate_number"),
                            target.get("ownership_type"),
                            target.get("contractor_name"),
                            _mechanization_merge_note(target_label),
                            source_id,
                        ),
                    )
                    updated_sources += cur.rowcount
    finally:
        conn.close()

    return {
        "ok": True,
        "target": target_label,
        "updated_sources": updated_sources,
        "hidden_sources": hidden_sources,
        "moved_work_usage": moved_work_usage,
        "moved_movement_usage": moved_movement_usage,
    }


@router.get("/mechanization/cleanup-candidates")
def mechanization_cleanup_candidates(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    _user=Depends(current_user),
):
    d_from, d_to = _parse_range(date_from, date_to)

    master_rows = query(
        """
        SELECT id::text AS master_equipment_id,
               equipment_type,
               COALESCE(NULLIF(brand_model, ''), '—') AS brand_model,
               COALESCE(NULLIF(unit_number, ''), '—') AS unit_number,
               COALESCE(NULLIF(plate_number, ''), '—') AS plate_number,
               COALESCE(NULLIF(ownership_type, ''), '—') AS ownership,
               COALESCE(NULLIF(contractor_name, ''), '—') AS contractor,
               status,
               source_name,
               source_date,
               location
        FROM equipment_units
        WHERE is_active IS NOT FALSE
        ORDER BY source_date DESC NULLS LAST, updated_at DESC NULLS LAST
        """
    )
    report_rows = query(
        """
        SELECT ARRAY_AGG(reu.id::text ORDER BY dr.report_date, COALESCE(dr.shift, 'day'), reu.id::text) AS report_equipment_ids,
               ARRAY_AGG(DISTINCT reu.equipment_unit_id::text) FILTER (WHERE reu.equipment_unit_id IS NOT NULL) AS master_ids,
               MIN(reu.equipment_type) AS equipment_type,
               COALESCE(NULLIF(reu.brand_model, ''), '—') AS brand_model,
               COALESCE(NULLIF(reu.unit_number, ''), '—') AS unit_number,
               COALESCE(NULLIF(reu.plate_number, ''), '—') AS plate_number,
               COALESCE(NULLIF(reu.ownership_type, ''), '—') AS ownership,
               COALESCE(NULLIF(reu.contractor_name, ''), '—') AS contractor,
               MIN(reu.status) AS status,
               MIN(dr.report_date) AS first_date,
               MAX(dr.report_date) AS last_date,
               COUNT(*)::int AS shifts_count
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        WHERE dr.report_date BETWEEN %s AND %s
          AND COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')
          AND NOT (
            COALESCE(dr.source_type, '') = 'web_pile_control'
            OR COALESCE(dr.review_payload->'review_flags', '[]'::jsonb) ?| ARRAY['isso', 'контроль свай']
          )
          AND reu.is_demo IS NOT TRUE
        GROUP BY LOWER(COALESCE(reu.equipment_type, '')),
                 COALESCE(NULLIF(reu.brand_model, ''), '—'),
                 COALESCE(NULLIF(reu.unit_number, ''), '—'),
                 COALESCE(NULLIF(reu.plate_number, ''), '—'),
                 COALESCE(NULLIF(reu.ownership_type, ''), '—'),
                 COALESCE(NULLIF(reu.contractor_name, ''), '—')
        ORDER BY MAX(dr.report_date) DESC NULLS LAST, MIN(reu.equipment_type), COALESCE(NULLIF(reu.plate_number, ''), '—')
        """,
        [d_from, d_to],
    )

    pairs: list[dict] = []
    paired_report_keys: set[tuple[str, ...]] = set()
    for report in report_rows:
        report_key = tuple(report.get("report_equipment_ids") or [])
        best_master: Optional[dict] = None
        best_score = 0.0
        best_reason = ""
        for master in master_rows:
            score, reason = _mechanization_duplicate_score(master, report)
            if score > best_score:
                best_master = master
                best_score = score
                best_reason = reason
        if best_master and best_score >= 0.74:
            paired_report_keys.add(report_key)
            pairs.append({
                "id": f"{best_master['master_equipment_id']}:{hashlib.sha1('|'.join(report_key).encode('utf-8')).hexdigest()[:10]}",
                "score": round(best_score, 2),
                "reason": best_reason,
                "master": _mechanization_cleanup_row(best_master, "master"),
                "report": _mechanization_cleanup_row(report, "report"),
            })

    pairs.sort(key=lambda item: item["score"], reverse=True)
    others = [
        _mechanization_cleanup_row(report, "report")
        for report in report_rows
        if tuple(report.get("report_equipment_ids") or []) not in paired_report_keys
    ]
    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "pairs": pairs,
        "others": others,
    }


@router.post("/mechanization/cleanup/merge")
def mechanization_cleanup_merge(body: MechanizationCleanupMergeBody, _user=Depends(current_user)):
    report_ids = _mechanization_validate_report_ids(body.report_equipment_ids)
    keep = (body.keep or "master").strip().lower()
    if keep not in {"master", "report"}:
        raise HTTPException(400, "keep должен быть master или report")

    master_id = str(body.master_equipment_id or "").strip()
    if master_id and not re.fullmatch(r"[0-9a-fA-F-]{36}", master_id):
        raise HTTPException(400, "Некорректный id мастер-строки техники")
    if keep == "master" and not master_id:
        raise HTTPException(400, "Не выбрана строка Гермеса для объединения")

    source_rows = query(
        """
        SELECT id::text AS id
        FROM report_equipment_units
        WHERE id = ANY(%s::uuid[])
          AND is_demo IS NOT TRUE
        """,
        [report_ids],
    )
    found_source_ids = {row["id"] for row in source_rows}
    missing = [value for value in report_ids if value not in found_source_ids]
    if missing:
        raise HTTPException(404, f"Часть строк техники уже неактивна или не найдена: {', '.join(missing[:3])}")

    master = None
    if master_id:
        master = query_one(
            """
            SELECT id::text AS id,
                   equipment_type,
                   brand_model,
                   unit_number,
                   plate_number,
                   ownership_type,
                   contractor_name
            FROM equipment_units
            WHERE id = %s::uuid
              AND is_active IS NOT FALSE
            """,
            [master_id],
        )
        if not master:
            raise HTTPException(404, "Не нашел активную строку Гермеса")

    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                if keep == "master":
                    target_label = _mechanization_equipment_label(master)
                    cur.execute(
                        """
                        UPDATE report_equipment_units
                        SET equipment_unit_id = %s::uuid,
                            equipment_type = COALESCE(NULLIF(%s, ''), equipment_type),
                            brand_model = NULLIF(%s, ''),
                            unit_number = NULLIF(%s, ''),
                            plate_number = NULLIF(%s, ''),
                            ownership_type = COALESCE(NULLIF(%s, ''), ownership_type),
                            contractor_name = NULLIF(%s, ''),
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                        WHERE id = ANY(%s::uuid[])
                          AND is_demo IS NOT TRUE
                        """,
                        (
                            master["id"],
                            master.get("equipment_type"),
                            master.get("brand_model"),
                            master.get("unit_number"),
                            master.get("plate_number"),
                            master.get("ownership_type"),
                            master.get("contractor_name"),
                            _mechanization_merge_note(target_label),
                            report_ids,
                        ),
                    )
                    updated_sources = cur.rowcount
                    return {
                        "ok": True,
                        "kept": "master",
                        "target": target_label,
                        "updated_sources": updated_sources,
                        "deactivated_master": 0,
                    }

                target_label = "строка суточного отчета"
                if master:
                    target_label = _mechanization_cleanup_label({
                        "equipment_type": master.get("equipment_type"),
                        "brand_model": master.get("brand_model") or "—",
                        "unit_number": master.get("unit_number") or "—",
                        "plate_number": master.get("plate_number") or "—",
                    })
                    cur.execute(
                        """
                        UPDATE equipment_units
                        SET is_active = false,
                            comment = CONCAT_WS('; ', NULLIF(comment, ''), %s),
                            updated_at = now()
                        WHERE id = %s::uuid
                          AND is_active IS NOT FALSE
                        """,
                        (f"deactivated in favor of report row via mechanization cleanup: {target_label}", master["id"]),
                    )
                    deactivated_master = cur.rowcount
                else:
                    deactivated_master = 0

                cur.execute(
                    """
                    UPDATE report_equipment_units
                    SET equipment_unit_id = CASE
                          WHEN equipment_unit_id = %s::uuid THEN NULL
                          ELSE equipment_unit_id
                        END,
                        comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                    WHERE id = ANY(%s::uuid[])
                      AND is_demo IS NOT TRUE
                    """,
                    (
                        master["id"] if master else None,
                        "kept report row via mechanization cleanup",
                        report_ids,
                    ),
                )
                updated_sources = cur.rowcount
                return {
                    "ok": True,
                    "kept": "report",
                    "target": "строка суточного отчета",
                    "updated_sources": updated_sources,
                    "deactivated_master": deactivated_master,
                }
    finally:
        conn.close()


@router.post("/mechanization/cleanup/delete")
def mechanization_cleanup_delete(body: MechanizationCleanupDeleteBody, _user=Depends(current_user)):
    report_ids = _mechanization_validate_report_ids(body.report_equipment_ids)
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE report_equipment_units
                    SET is_demo = true,
                        comment = CONCAT_WS('; ', NULLIF(comment, ''), %s)
                    WHERE id = ANY(%s::uuid[])
                      AND is_demo IS NOT TRUE
                    """,
                    ("hidden via mechanization cleanup", report_ids),
                )
                hidden = cur.rowcount
    finally:
        conn.close()
    return {"ok": True, "hidden_sources": hidden}


# ── mechanization aggregates for Analytics tab ────────────────────────

def _mechanization_aggregates_payload(d_from: date_cls, d_to: date_cls, bucket: str) -> dict:
    unit_data = _mechanization_units_impl(d_from, d_to)
    operation_data = _query_equipment_operation_metrics(d_from, d_to, bucket=bucket)
    units = unit_data['units']

    def in_bucket(u):
        if bucket == 'all':
            return True
        own = (u.get('ownership') or '').lower() == 'own'
        almaz = 'алмаз' in (u.get('contractor') or '').lower()
        if bucket == 'own':
            return own
        if bucket == 'almaz':
            return almaz
        if bucket == 'hired':
            return not own and not almaz
        return True

    # Группируем per (section, equipment_type) только по нормируемым работам.
    # Важно: количество техники = уникальные машины в сменах с нормируемым фактом,
    # а не все строки парка/ремонта из отчета М.
    agg: dict[tuple, dict] = {}
    for u in units:
        if not in_bucket(u):
            continue
        et = u.get('productivity_equipment_type') or _mechanization_productivity_equipment_type(u.get('equipment_type'))
        unit_identity = str(u.get('master_equipment_id') or u.get('merge_key') or f"{et}:{u.get('plate_number')}:{u.get('unit_number')}")
        for d in u.get('details', []) or []:
            fact = float(d.get('fact') or 0)
            norm = float(d.get('norm') or 0)
            if fact <= 0 or norm <= 0:
                continue
            fu = d.get('unit') or u.get('fact_unit') or 'м³'
            sec = _merge_section(d.get('section')) or d.get('section') or u.get('last_section') or '—'
            key = (sec, et)
            entry = agg.setdefault(key, {
                'section_code': sec, 'equipment_type': et,
                'unit_keys': set(),
                'shift_keys': set(),
                'unit_shift_keys': set(),
                'norm_keys': set(),
                'fact_total_m3': 0.0, 'fact_total_m2': 0.0,
                'fact_for_percent': 0.0,
                'expected_total': 0.0,
                'work_hours_total': 0.0,
                'operation': _operation_metric_empty_totals(),
                'by_work_type': {},
            })
            date_key = str(d.get('date') or '')
            shift_key = str(d.get('shift') or '')
            shift_tuple = (date_key, shift_key)
            unit_shift_tuple = (unit_identity, date_key, shift_key)
            entry['unit_keys'].add(unit_identity)
            entry['shift_keys'].add(shift_tuple)
            entry['unit_shift_keys'].add(unit_shift_tuple)
            if fu == 'м²':
                entry['fact_total_m2'] += fact
            else:
                entry['fact_total_m3'] += fact
            entry['fact_for_percent'] += fact
            entry['work_hours_total'] += float(d.get('work_hours') or PRODUCTIVITY_SHIFT_HOURS)
            wlabel = d.get('work') or ''
            norm_key = (unit_identity, date_key, shift_key, wlabel)
            if norm_key not in entry['norm_keys']:
                entry['norm_keys'].add(norm_key)
                entry['expected_total'] += norm
            w = entry['by_work_type'].setdefault(wlabel, {
                'wt_name': wlabel, 'norm_code': wlabel,
                'norm_per_shift': float(d.get('reference_norm') or norm),
                'norm_unit': 'м²' if fu == 'м²' else 'м³',
                'fact_volume': 0.0, 'expected': 0.0, 'work_hours_total': 0.0,
                'days_set': set(), 'shift_keys': set(), 'unit_shift_keys': set(), 'norm_keys': set(),
            })
            w['fact_volume'] += fact
            w['work_hours_total'] += float(d.get('work_hours') or PRODUCTIVITY_SHIFT_HOURS)
            w['days_set'].add(date_key)
            w['shift_keys'].add(shift_tuple)
            w['unit_shift_keys'].add(unit_shift_tuple)
            if norm_key not in w['norm_keys']:
                w['norm_keys'].add(norm_key)
                w['expected'] += norm

    for key, totals in operation_data.get("by_section_productivity_type", {}).items():
        if key in agg:
            agg[key]["operation"] = totals

    rows_out = []
    for (sec, et), e in agg.items():
        shift_count = len(e['shift_keys'])
        unit_shift_count = len(e['unit_shift_keys'])
        avg_units = (unit_shift_count / shift_count) if shift_count else 0.0
        percent = (e['fact_for_percent'] / e['expected_total'] * 100) if e['expected_total'] > 0 else None
        by_work = []
        for wlabel, w in e['by_work_type'].items():
            work_shift_count = len(w['shift_keys'])
            work_avg_units = (len(w['unit_shift_keys']) / work_shift_count) if work_shift_count else 0.0
            wpct = (w['fact_volume'] / w['expected'] * 100) if w['expected'] > 0 else None
            by_work.append({
                'wt_code': wlabel, 'wt_name': wlabel,
                'norm_code': wlabel, 'norm_per_shift': w['norm_per_shift'],
                'norm_unit': w['norm_unit'],
                'fact_volume': round(w['fact_volume'], 1),
                'days': len(w['days_set']), 'shifts': work_shift_count,
                'avg_units': round(work_avg_units, 2), 'expected': round(w['expected'], 1),
                'work_hours_total': round(w['work_hours_total'], 2),
                'percent': round(wpct, 1) if wpct is not None else None,
            })
        rows_out.append({
            'section_code': sec, 'equipment_type': et,
            'percent': round(percent, 1) if percent is not None else None,
            'avg_units': round(avg_units, 2),
            'work_days_total': len({date for date, _shift in e['shift_keys'] if date}),
            'work_shifts_total': shift_count,
            'work_hours_total': round(e['work_hours_total'], 2),
            'fact_volume_total_m3': round(e['fact_total_m3'], 1),
            'fact_volume_total_m2': round(e['fact_total_m2'], 1),
            **_operation_totals_payload(e.get("operation")),
            'by_work_type': by_work,
        })
    rows_out.sort(key=lambda x: (x['section_code'], x['equipment_type']))
    return {
        'from': unit_data['from'], 'to': unit_data['to'],
        'bucket': bucket, 'rows': rows_out,
    }


@router.get("/mechanization/aggregates")
def mechanization_aggregates(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    bucket: str = Query("own", description="own|almaz|hired|all — фильтр по собственности"),
):
    """Агрегат per (section × equipment_type) из /mechanization/units с фильтром ЖДС.

    Возвращает ровно тот же shape, что и /equipment-productivity (для совместимости
    с EquipmentBlock на Аналитике): rows с полями section_code, equipment_type,
    percent, avg_units, work_days_total, work_shifts_total, by_work_type, by_material.
    """
    d_from, d_to = _parse_range(date_from, date_to)
    endpoint = "mechanization_aggregates.v7"
    fingerprint = _dashboard_source_fingerprint(
        d_from,
        d_to,
        include_work=True,
        include_material=True,
        include_equipment=True,
    )
    cache_key = (d_from.isoformat(), d_to.isoformat(), str(bucket or 'own'), fingerprint)
    cached = _dashboard_short_cache_get(_MECHANIZATION_AGGREGATES_CACHE, cache_key)
    if cached is not None:
        return cached
    persistent_key = _dashboard_response_cache_key({"endpoint": "mechanization_aggregates", "from": d_from, "to": d_to, "bucket": bucket})
    cached = _dashboard_response_cache_get(endpoint, persistent_key, fingerprint)
    if cached is not None:
        marked = _dashboard_response_cache_mark(cached, status="fresh", fingerprint=fingerprint)
        return _dashboard_short_cache_set(_MECHANIZATION_AGGREGATES_CACHE, cache_key, marked)

    return _dashboard_response_cache_build_or_wait(
        endpoint,
        persistent_key,
        fingerprint,
        lambda: _mechanization_aggregates_payload(d_from, d_to, bucket),
        short_cache=_MECHANIZATION_AGGREGATES_CACHE,
        short_cache_key=cache_key,
    )


@router.get("/mechanization/fuel-aggregates")
def mechanization_fuel_aggregates(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    bucket: str = Query("all", description="own|almaz|hired|all — фильтр по собственности"),
):
    d_from, d_to = _parse_range(date_from, date_to)
    operation_data = _query_equipment_operation_metrics(d_from, d_to, bucket=bucket)
    rows_out = []
    for (section_code, equipment_type), totals in operation_data.get("by_section_actual_type", {}).items():
        payload = _operation_totals_payload(totals)
        if not any(payload.get(key, 0) for key in ("mileage_km_total", "engine_hours_total", "fuel_liters_total")):
            continue
        rows_out.append({
            "section_code": section_code,
            "equipment_type": equipment_type,
            **payload,
        })
    rows_out.sort(key=lambda row: (
        -float(row.get("fuel_liters_total") or 0),
        str(row.get("equipment_type") or ""),
        str(row.get("section_code") or ""),
    ))
    total_payload = _operation_totals_payload(operation_data.get("total"))
    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "bucket": bucket,
        "total_fuel_liters": total_payload["fuel_liters_total"],
        "total_mileage_km": total_payload["mileage_km_total"],
        "total_engine_hours": total_payload["engine_hours_total"],
        "rows": rows_out,
    }


@router.get("/mechanization/aggregates/detail")
def mechanization_aggregate_detail(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    bucket: str = Query("own", description="own|almaz|hired|all — фильтр по собственности"),
    section_code: str = Query(...),
    equipment_type: str = Query(...),
):
    """Diagnostic drill-down for one Analytics productivity card."""
    d_from, d_to = _parse_range(date_from, date_to)
    target_section = _merge_section(section_code) or section_code
    target_equipment_type = _mechanization_productivity_equipment_type(equipment_type)
    unit_data = _mechanization_units_impl(d_from, d_to, include_work_diagnostics=True)
    operation_data = _query_equipment_operation_metrics(d_from, d_to, bucket=bucket)

    def in_bucket(u):
        if bucket == 'all':
            return True
        own = (u.get('ownership') or '').lower() == 'own'
        almaz = 'алмаз' in (u.get('contractor') or '').lower()
        if bucket == 'own':
            return own
        if bucket == 'almaz':
            return almaz
        if bucket == 'hired':
            return not own and not almaz
        return True

    rows: list[dict] = []
    total_details = 0
    included_details = 0
    for u in unit_data.get('units', []):
        if not in_bucket(u):
            continue
        unit_equipment_type = u.get('productivity_equipment_type') or _mechanization_productivity_equipment_type(u.get('equipment_type'))
        if unit_equipment_type != target_equipment_type:
            continue
        details = [
            d for d in (u.get('work_details') or [])
            if (_merge_section(d.get('section')) or d.get('section')) == target_section
        ]
        if not details:
            continue
        details.sort(key=lambda d: (
            d.get('date') or '',
            d.get('shift') or '',
            d.get('object_name') or '',
            d.get('work') or '',
        ))
        fact_total = sum(float(d.get('fact') or 0) for d in details if d.get('participates_in_productivity'))
        expected_total = sum(float(d.get('norm') or 0) for d in details if d.get('participates_in_productivity'))
        work_hours_total = sum(float(d.get('work_hours') or PRODUCTIVITY_SHIFT_HOURS) for d in details if d.get('participates_in_productivity'))
        unit_included = sum(1 for d in details if d.get('participates_in_productivity'))
        total_details += len(details)
        included_details += unit_included
        operation_totals = operation_data.get("by_unit_section", {}).get((str(u.get("master_equipment_id") or ""), target_section))
        rows.append({
            'unit_key': u.get('merge_key'),
            'master_equipment_id': u.get('master_equipment_id'),
            'equipment_type': u.get('equipment_type'),
            'productivity_equipment_type': unit_equipment_type,
            'brand_model': u.get('brand_model'),
            'plate_number': u.get('plate_number'),
            'unit_number': u.get('unit_number'),
            'ownership': u.get('ownership'),
            'contractor': u.get('contractor'),
            'section_code': target_section,
            'fact_total': round(fact_total, 1),
            'expected_total': round(expected_total, 1),
            'work_hours_total': round(work_hours_total, 2),
            'percent': round(fact_total / expected_total * 100, 1) if expected_total > 0 else None,
            'shifts_with_details': len({(d.get('date'), d.get('shift')) for d in details if d.get('date')}),
            'included_details': unit_included,
            'excluded_details': len(details) - unit_included,
            **_operation_totals_payload(operation_totals),
            'details': details,
        })

    rows.sort(key=lambda u: (
        str(u.get('equipment_type') or ''),
        str(u.get('unit_number') or ''),
        str(u.get('plate_number') or ''),
    ))
    return {
        'from': unit_data.get('from'),
        'to': unit_data.get('to'),
        'bucket': bucket,
        'section_code': target_section,
        'equipment_type': target_equipment_type,
        'units': rows,
        'totals': {
            'units': len(rows),
            'details': total_details,
            'included_details': included_details,
            'excluded_details': total_details - included_details,
        },
        'calculation_logic': [
            'Берутся строки работ или перевозок из подтвержденных/ожидающих проверки отчетов за выбранный период.',
            'Для работ строка должна быть привязана к конкретной единице техники через work_item_equipment_usage.',
            'Справочная норма уменьшается пропорционально времени работы: норма строки = сменная норма x часы / 11; пустое время считается равным 11 часам.',
            'В расчет процента попадают только строки с включенными флагами производительности, положительным фактом и нормой для пары тип техники + код работы.',
            'Проезды и площадки ИССО не исключаются по типу объекта; если они не участвуют, причина показывается в колонке детализации.',
        ],
    }


# ── TV dashboard ──────────────────────────────────────────────────────────

def _score_0_100(value: float, baseline: float) -> float:
    if baseline <= 0 or value <= 0:
        return 0.0
    return min(value / baseline * 100.0, 150.0)


@router.get("/tv-dashboard/metrics")
def tv_dashboard_metrics(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    _user=Depends(current_user),
):
    _ensure_haul_distance_table()
    _ensure_material_movement_haul_distance_columns()
    d_from, d_to = _parse_range(date_from, date_to)
    sections = _settings_sections()
    section_codes = [s["code"] for s in sections]
    section_names = {s["code"]: s["name"] for s in sections}

    sand_rows_raw = query(
        f"""
        SELECT cs.code AS section_code,
               src.id::text AS quarry_object_id,
               src.name AS quarry_name,
               mm.movement_type,
               SUM(mm.volume)::numeric AS volume,
               SUM(COALESCE(mm.trip_count, 0))::int AS trips,
               CASE
                 WHEN SUM(CASE WHEN COALESCE(mm.haul_distance_km, h.distance_km) IS NOT NULL THEN mm.volume ELSE 0 END) > 0
                 THEN SUM(mm.volume * COALESCE(mm.haul_distance_km, h.distance_km))
                      / SUM(CASE WHEN COALESCE(mm.haul_distance_km, h.distance_km) IS NOT NULL THEN mm.volume ELSE 0 END)
                 ELSE NULL
               END AS distance_km
        FROM material_movements mm
        JOIN materials m ON m.id = mm.material_id
        JOIN objects src ON src.id = mm.from_object_id
        JOIN object_types src_type ON src_type.id = src.object_type_id
        LEFT JOIN construction_sections cs ON cs.id = mm.section_id
        LEFT JOIN section_quarry_haul_distances h
          ON h.section_code = cs.code
         AND h.quarry_object_id = src.id
        WHERE mm.report_date BETWEEN %s AND %s
          AND mm.is_demo = false
          AND m.code = 'SAND'
          AND src_type.code = 'BORROW_PIT'
          AND mm.movement_type IN ('pit_to_constructive', 'pit_to_stockpile')
          AND {_approved_report_exists("mm")}
        GROUP BY cs.code, src.id, src.name, mm.movement_type
        ORDER BY cs.code, src.name, mm.movement_type
        """,
        [d_from, d_to],
    )
    distance_rows = query(
        """
        SELECT section_code, quarry_object_id::text AS quarry_object_id, distance_km
        FROM section_quarry_haul_distances
        """
    )
    distances = {
        (r["section_code"], r["quarry_object_id"]): float(r["distance_km"] or 0)
        for r in distance_rows
        if r.get("distance_km") is not None
    }

    sand_by_section = {
        code: {
            "section_code": code,
            "section_name": section_names.get(code, code),
            "volume": 0.0,
            "placed_volume": 0.0,
            "stockpile_volume": 0.0,
            "trips": 0,
            "ton_km": 0.0,
            "missing_distance_rows": 0,
        }
        for code in section_codes
    }
    sand_by_quarry: list[dict] = []
    for row in sand_rows_raw:
        section_code = _merge_section(row.get("section_code")) or row.get("section_code") or "—"
        volume = float(row.get("volume") or 0)
        trips = int(row.get("trips") or 0)
        distance = float(row.get("distance_km")) if row.get("distance_km") is not None else distances.get((section_code, row.get("quarry_object_id")))
        distance_fallback = distance is None
        effective_distance = distance if distance is not None else 1.0
        ton_km = volume * effective_distance
        if section_code in sand_by_section:
            sand_by_section[section_code]["volume"] += volume
            sand_by_section[section_code]["trips"] += trips
            sand_by_section[section_code]["ton_km"] += ton_km
            if distance_fallback:
                sand_by_section[section_code]["missing_distance_rows"] += 1
            if row.get("movement_type") == "pit_to_stockpile":
                sand_by_section[section_code]["stockpile_volume"] += volume
        sand_by_quarry.append({
            "section_code": section_code,
            "quarry_object_id": row.get("quarry_object_id"),
            "quarry_name": row.get("quarry_name"),
            "volume": round(volume, 1),
            "trips": trips,
            "distance_km": distance,
            "distance_fallback": distance_fallback,
            "movement_type": row.get("movement_type"),
            "ton_km": round(ton_km, 1),
        })
    sand_placed_rows = query(
        f"""
        SELECT cs.code AS section_code,
               SUM(mm.volume)::numeric AS volume
        FROM material_movements mm
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN construction_sections cs ON cs.id = mm.section_id
        WHERE mm.report_date BETWEEN %s AND %s
          AND mm.is_demo = false
          AND m.code = 'SAND'
          AND mm.movement_type IN ('pit_to_constructive', 'stockpile_to_constructive')
          AND {_approved_report_exists("mm")}
        GROUP BY cs.code
        """,
        [d_from, d_to],
    )
    for row in sand_placed_rows:
        section_code = _merge_section(row.get("section_code")) or row.get("section_code") or "—"
        if section_code in sand_by_section:
            sand_by_section[section_code]["placed_volume"] += float(row.get("volume") or 0)
    sand_section_rows = [
        {
            **row,
            "volume": round(float(row["volume"]), 1),
            "placed_volume": round(float(row["placed_volume"]), 1),
            "stockpile_volume": round(float(row["stockpile_volume"]), 1),
            "ton_km": round(float(row["ton_km"]), 1),
        }
        for row in sand_by_section.values()
    ]

    unit_data = _mechanization_units_impl(d_from, d_to)
    equipment_by_section = {
        code: {
            "section_code": code,
            "section_name": section_names.get(code, code),
            "units_count": 0,
            "shifts": 0,
            "avg_percent": None,
            "dump_truck_shifts": 0,
            "pile_drivers": 0,
        }
        for code in section_codes
    }
    percent_values: dict[str, list[float]] = {code: [] for code in section_codes}
    pile_driver_units: list[dict] = []
    for unit in unit_data.get("units", []):
        sec = _merge_section(unit.get("last_section")) or unit.get("last_section")
        et = (unit.get("equipment_type") or "").lower()
        if sec in equipment_by_section:
            equipment_by_section[sec]["units_count"] += 1
            equipment_by_section[sec]["shifts"] += int(unit.get("shifts_worked") or 0)
            if unit.get("percent") is not None:
                percent_values[sec].append(float(unit["percent"]))
            if et in ("самосвал", "dump_truck"):
                equipment_by_section[sec]["dump_truck_shifts"] += int(unit.get("shifts_worked") or 0)
            if "сваеб" in et or "коп" in et:
                equipment_by_section[sec]["pile_drivers"] += 1
        if "сваеб" in et or "коп" in et:
            pile_driver_units.append({
                "equipment_type": unit.get("equipment_type"),
                "brand_model": unit.get("brand_model"),
                "plate_number": unit.get("plate_number"),
                "unit_number": unit.get("unit_number"),
                "status": unit.get("status"),
                "location": unit.get("location"),
                "section_code": sec,
                "source_date": unit.get("source_date") or unit.get("last_date"),
            })
    for code, values in percent_values.items():
        if values:
            equipment_by_section[code]["avg_percent"] = round(sum(values) / len(values), 1)

    pile_data = piles(date_from=d_from.isoformat(), date_to=d_to.isoformat())
    pile_rows = []
    for code in section_codes:
        facts = pile_data.get("fact_by_section", {}).get(code, {"main": 0, "test": 0, "dyn": 0})
        plans = pile_data.get("plan_by_section", {}).get(code, {"main": 0, "test": 0, "dyn": 0})
        fact_total = float(facts.get("main", 0) or 0) + float(facts.get("test", 0) or 0)
        plan_total = float(plans.get("main", 0) or 0) + float(plans.get("test", 0) or 0)
        pile_rows.append({
            "section_code": code,
            "section_name": section_names.get(code, code),
            "fact_main": round(float(facts.get("main", 0) or 0), 1),
            "fact_test": round(float(facts.get("test", 0) or 0), 1),
            "fact_dynamic": round(float(facts.get("dyn", 0) or 0), 1),
            "plan_main": round(float(plans.get("main", 0) or 0), 1),
            "plan_test": round(float(plans.get("test", 0) or 0), 1),
            "plan_dynamic": round(float(plans.get("dyn", 0) or 0), 1),
            "fact_total": round(fact_total, 1),
            "plan_total": round(plan_total, 1),
            "percent": round(fact_total / plan_total * 100, 1) if plan_total > 0 else None,
            "pile_drivers": int(equipment_by_section[code]["pile_drivers"] or 0),
            "piles_per_driver": round(
                fact_total / float(equipment_by_section[code]["pile_drivers"] or 1),
                1,
            ) if equipment_by_section[code]["pile_drivers"] else 0.0,
        })

    other_rows = query(
        f"""
        SELECT cs.code AS section_code,
               COALESCE(NULLIF(dwi.unit, ''), wt.default_unit, '') AS unit,
               SUM(dwi.volume)::numeric AS volume
        FROM daily_work_items dwi
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN construction_sections cs ON cs.id = dwi.section_id
        WHERE dwi.report_date BETWEEN %s AND %s
          AND NOT dwi.is_demo
          AND COALESCE(wt.productivity_enabled, true) = true
          AND COALESCE(dwi.productivity_enabled, true) = true
          AND wt.code NOT IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST')
          AND {_approved_report_exists("dwi")}
        GROUP BY cs.code, COALESCE(NULLIF(dwi.unit, ''), wt.default_unit, '')
        """,
        [d_from, d_to],
    )
    other_by_section: dict[str, dict[str, float]] = {code: {} for code in section_codes}
    max_by_unit: dict[str, float] = {}
    for row in other_rows:
        sec = _merge_section(row.get("section_code")) or row.get("section_code")
        unit = row.get("unit") or "ед."
        volume = float(row.get("volume") or 0)
        if sec not in other_by_section:
            continue
        other_by_section[sec][unit] = other_by_section[sec].get(unit, 0.0) + volume
        max_by_unit[unit] = max(max_by_unit.get(unit, 0.0), other_by_section[sec][unit])

    sand_eff_values = {
        code: float(row["ton_km"]) / max(float(equipment_by_section[code]["dump_truck_shifts"] or 0), 1.0)
        for code, row in sand_by_section.items()
    }
    max_sand_eff = max(sand_eff_values.values(), default=0.0)
    other_eff_values: dict[str, float] = {}
    for code, by_unit in other_by_section.items():
        section_scores = [
            _score_0_100(value, max_by_unit.get(unit, 0.0))
            for unit, value in by_unit.items()
            if max_by_unit.get(unit, 0.0) > 0
        ]
        equipment_units = max(float(equipment_by_section[code]["units_count"] or 0), 1.0)
        other_eff_values[code] = (sum(section_scores) / len(section_scores) if section_scores else 0.0) / equipment_units
    max_other_eff = max(other_eff_values.values(), default=0.0)

    standings = []
    for pile_row in pile_rows:
        code = pile_row["section_code"]
        equipment_score = min(float(equipment_by_section[code]["avg_percent"] or 0), 150.0)
        piles_score = min(float(pile_row["percent"] or 0), 150.0)
        sand_score = _score_0_100(sand_eff_values.get(code, 0.0), max_sand_eff)
        other_score = _score_0_100(other_eff_values.get(code, 0.0), max_other_eff)
        score = (
            equipment_score * 0.30
            + piles_score * 0.25
            + sand_score * 0.25
            + other_score * 0.20
        )
        standings.append({
            "section_code": code,
            "section_name": section_names.get(code, code),
            "score": round(score, 1),
            "rank": 0,
            "components": {
                "equipment": round(equipment_score, 1),
                "piles": round(piles_score, 1),
                "sand_distance": round(sand_score, 1),
                "other_per_equipment": round(other_score, 1),
            },
            "raw": {
                "sand_ton_km_per_dump_shift": round(sand_eff_values.get(code, 0.0), 1),
                "other_work_index": round(other_eff_values.get(code, 0.0), 2),
            },
        })
    standings.sort(key=lambda row: row["score"], reverse=True)
    for idx, row in enumerate(standings, start=1):
        row["rank"] = idx

    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "sections": sections,
        "sand": {
            "by_section": sand_section_rows,
            "by_quarry": sand_by_quarry,
            "total_volume": round(sum(row["volume"] for row in sand_section_rows), 1),
        },
        "equipment": {
            "by_section": list(equipment_by_section.values()),
            "units_total": len(unit_data.get("units", [])),
        },
        "piles": {
            "by_section": pile_rows,
            "drivers": pile_driver_units,
        },
        "standings": {
            "winner": standings[0] if standings else None,
            "rows": standings,
        },
    }


