def _mainline_work_metric_key(wt_code: Optional[str], analytics_tag: Optional[str]) -> Optional[str]:
    code = (wt_code or "").strip().upper()
    text = _general_normalize_text(analytics_tag)
    if code == "TOPSOIL_STRIPPING" or "прс" in text or "растительн" in text:
        return "prs"
    if code == "PEAT_REMOVAL" or "выторф" in text or "торф" in text:
        return "peat_removal"
    if code == "WEAK_SOIL_REPLACEMENT" or ("замен" in text and "грун" in text) or "слаб" in text:
        return "weak_soil_replacement"
    if code in {"EARTH_EXCAVATION", "EXCAVATION_MAIN"} or "выем" in text or "разработ" in text:
        return "excavation"
    if code == "EMBANKMENT_CONSTRUCTION" or "насып" in text:
        return "embankment"
    return None


def _mainline_status_type_for_work_metric(metric_key: Optional[str]) -> Optional[str]:
    return MAINLINE_WORK_METRIC_STATUS_TYPES.get(metric_key or "")


def _empty_mainline_work_totals() -> dict[str, float]:
    return {item["key"]: 0.0 for item in MAINLINE_WORK_METRICS}


def _mainline_work_total_list(values: Optional[dict[str, float]]) -> list[dict]:
    clean = values or {}
    return [
        {
            "key": item["key"],
            "label": item["label"],
            "volume_m3": _clean_report_number(float(clean.get(item["key"]) or 0)),
        }
        for item in MAINLINE_WORK_METRICS
    ]


def _query_mainline_work_metric_rows(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]] = None,
) -> list[dict]:
    where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
    ]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)
    return query(
        f"""
        SELECT cs_eff.code AS section_code,
               dwi.report_date,
               LOWER(COALESCE(dwi.shift, 'day')) AS shift,
               wt.code AS wt_code,
               wt.name AS work_type_name,
               ot.code AS object_type_code,
               obj.object_code AS object_code,
               obj.name AS object_name,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               dwi.labor_source_type,
               dwi.contractor_name,
               MIN(seg.pk_start)::numeric AS pk_start,
               MAX(seg.pk_end)::numeric AS pk_end,
               SUM(
                 CASE
                   WHEN seg.id IS NULL THEN COALESCE(dwi.volume, 0)
                   WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                   WHEN seg_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_count.cnt
                   ELSE COALESCE(dwi.volume, 0)
                 END
               )::numeric AS amount
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND seg.id IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        GROUP BY cs_eff.code, dwi.report_date, dwi.shift, wt.code, wt.name, ot.code, obj.object_code, obj.name, 9, dwi.labor_source_type, dwi.contractor_name
        ORDER BY dwi.report_date DESC, cs_eff.code, wt.name
        """,
        params,
    )


def _mainline_clean_pk_ranges(ranges: Optional[list[tuple[float, float]]]) -> list[tuple[float, float]]:
    clean: list[tuple[float, float]] = []
    for item in ranges or []:
        try:
            start = float(item[0])
            end = float(item[1])
        except (TypeError, ValueError, IndexError):
            continue
        start, end = min(start, end), max(start, end)
        if end - start >= 0.01:
            clean.append((start, end))
    return _fill_merge_ranges(clean)


def _append_mainline_pk_range_filter(
    where: list[str],
    params: list,
    start_expr: str,
    end_expr: str,
    ranges: Optional[list[tuple[float, float]]],
) -> None:
    clean = _mainline_clean_pk_ranges(ranges)
    if not clean:
        return
    clauses = []
    for start, end in clean:
        clauses.append(f"({start_expr} IS NOT NULL AND {end_expr} IS NOT NULL AND {start_expr} < %s AND {end_expr} > %s)")
        params.extend([end, start])
    where.append(f"({' OR '.join(clauses)})")


def _query_mainline_work_segment_rows(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]] = None,
    pk_ranges: Optional[list[tuple[float, float]]] = None,
) -> list[dict]:
    where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        "seg.pk_start IS NOT NULL",
        "seg.pk_end IS NOT NULL",
        """(
          wt.code = ANY(%s)
          OR LOWER(COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw, '')) ~ %s
        )""",
        _approved_report_exists("dwi"),
    ]
    params: list = [d_from, d_to, list(MAINLINE_WORK_METRIC_TYPE_CODES), MAINLINE_WORK_METRIC_TEXT_PATTERN]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)
    _append_mainline_pk_range_filter(where, params, "seg.pk_start", "seg.pk_end", pk_ranges)
    return query(
        f"""
        SELECT cs_eff.code AS section_code,
               dwi.report_date,
               LOWER(COALESCE(dwi.shift, 'day')) AS shift,
               wt.code AS wt_code,
               wt.name AS work_type_name,
               ot.code AS object_type_code,
               obj.object_code AS object_code,
               obj.name AS object_name,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               dwi.labor_source_type,
               dwi.contractor_name,
               seg.pk_start::numeric AS pk_start,
               seg.pk_end::numeric AS pk_end,
               CASE
                 WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                 WHEN seg_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_count.cnt
                 ELSE COALESCE(dwi.volume, 0)
               END::numeric AS amount
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        ORDER BY dwi.report_date DESC, cs_eff.code, seg.pk_start, seg.pk_end
        """,
        params,
    )


def _mainline_work_status_segment_rows(d_to: date_cls, codes: Optional[list[str]] = None) -> list[dict]:
    section_codes = list(dict.fromkeys([_merge_section(code) for code in (codes or GENERAL_ANALYTICS_SECTION_CODES) if _merge_section(code)]))
    rules = _general_report_work_rules()
    out: list[dict] = []
    for row in _query_mainline_work_segment_rows(MAINLINE_FILL_DISPLAY_START_DATE, d_to, section_codes):
        section_code = _merge_section(row.get("section_code"))
        if not section_code or (section_codes and section_code not in section_codes):
            continue
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        category = _general_effective_work_category(
            rules,
            row.get("analytics_tag"),
            row.get("wt_code"),
            row.get("object_type_code"),
            row.get("object_code"),
            source_bucket,
        )
        categories: list[str] = [category] if category else []
        categories.extend(
            _general_additional_split_categories(
                category,
                row.get("object_type_code"),
                row.get("object_code"),
            )
        )
        if not MAINLINE_OH_GENERAL_CATEGORIES.intersection(categories):
            continue
        metric_key = _mainline_work_metric_key(row.get("wt_code"), row.get("analytics_tag"))
        status_type = _mainline_status_type_for_work_metric(metric_key)
        if not status_type:
            continue
        start = float(row.get("pk_start")) if row.get("pk_start") is not None else None
        end = float(row.get("pk_end")) if row.get("pk_end") is not None else None
        if start is None or end is None:
            continue
        report_date = row.get("report_date")
        amount = _clean_report_number(float(row.get("amount") or 0))
        comment_parts = [
            row.get("work_type_name") or row.get("analytics_tag"),
            row.get("object_name") or row.get("object_code"),
            f"{amount:g} м³" if amount else None,
        ]
        comment = " · ".join(str(part) for part in comment_parts if part)
        out.append({
            "section_code": section_code,
            "date": report_date,
            "status_date": report_date,
            "last_date": report_date,
            "source": "work_report",
            "action": None,
            "status_type": status_type,
            "pk_start": start,
            "pk_end": end,
            "comment": comment or None,
        })
    return out


def _mainline_work_rows_payload(
    d_to: date_cls,
    codes: Optional[list[str]] = None,
    include_details: bool = False,
) -> tuple[dict[str, dict[str, float]], dict[str, list[dict]]]:
    section_codes = list(dict.fromkeys([_merge_section(code) for code in (codes or GENERAL_ANALYTICS_SECTION_CODES) if _merge_section(code)]))
    totals_by_section = {code: _empty_mainline_work_totals() for code in section_codes}
    details_by_section: dict[str, list[dict]] = {code: [] for code in section_codes}
    rules = _general_report_work_rules()
    for row in _query_mainline_work_metric_rows(PROJECT_START_DATE, d_to, section_codes):
        section_code = _merge_section(row.get("section_code"))
        if section_code not in totals_by_section:
            continue
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        category = _general_effective_work_category(
            rules,
            row.get("analytics_tag"),
            row.get("wt_code"),
            row.get("object_type_code"),
            row.get("object_code"),
            source_bucket,
        )
        categories: list[str] = [category] if category else []
        categories.extend(
            _general_additional_split_categories(
                category,
                row.get("object_type_code"),
                row.get("object_code"),
            )
        )
        if not MAINLINE_OH_GENERAL_CATEGORIES.intersection(categories):
            continue
        metric_key = _mainline_work_metric_key(row.get("wt_code"), row.get("analytics_tag"))
        if not metric_key:
            continue
        amount = float(row.get("amount") or 0)
        totals_by_section[section_code][metric_key] += amount
        if include_details:
            report_date = row.get("report_date")
            details_by_section[section_code].append({
                "date": report_date.isoformat() if hasattr(report_date, "isoformat") else str(report_date or ""),
                "metric_key": metric_key,
                "label": MAINLINE_WORK_METRIC_LABELS.get(metric_key, metric_key),
                "volume_m3": _clean_report_number(amount),
                "shift": row.get("shift") or "day",
                "work_type_code": row.get("wt_code"),
                "work_type_name": row.get("work_type_name") or row.get("analytics_tag"),
                "object_code": row.get("object_code"),
                "object_name": row.get("object_name"),
                "analytics_tag": row.get("analytics_tag"),
                "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
                "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
            })
    return totals_by_section, details_by_section


def _mainline_section_ranges_from_payload(section: dict) -> list[tuple[float, float]]:
    ranges: list[tuple[float, float]] = []
    for item in section.get("ranges") or []:
        if item.get("pk_start") is None or item.get("pk_end") is None:
            continue
        ranges.append((float(item.get("pk_start")), float(item.get("pk_end"))))
    if not ranges and section.get("pk_start") is not None and section.get("pk_end") is not None:
        ranges.append((float(section.get("pk_start")), float(section.get("pk_end"))))
    return _mainline_clean_pk_ranges(ranges)


def _mainline_volume_parts_for_ranges(
    pk_start: object,
    pk_end: object,
    amount: float,
    ranges: list[tuple[float, float]],
) -> list[tuple[float, float, float]]:
    if pk_start is None or pk_end is None:
        return []
    try:
        raw_start = float(pk_start)
        raw_end = float(pk_end)
    except (TypeError, ValueError):
        return []
    raw_start, raw_end = min(raw_start, raw_end), max(raw_start, raw_end)
    raw_len = raw_end - raw_start
    out: list[tuple[float, float, float]] = []
    for start, end in _fill_clamp_to_ranges(raw_start, raw_end, ranges):
        if raw_len > 0:
            part_amount = amount * max(0.0, end - start) / raw_len
        else:
            part_amount = amount
        out.append((start, end, part_amount))
    return out


def _mainline_metric_row_key(row: dict, rules: list[dict]) -> Optional[str]:
    source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
    category = _general_effective_work_category(
        rules,
        row.get("analytics_tag"),
        row.get("wt_code") or row.get("work_type_code"),
        row.get("object_type_code"),
        row.get("object_code"),
        source_bucket,
    )
    categories: list[str] = [category] if category else []
    categories.extend(
        _general_additional_split_categories(
            category,
            row.get("object_type_code"),
            row.get("object_code"),
        )
    )
    if not MAINLINE_OH_GENERAL_CATEGORIES.intersection(categories):
        return None
    return _mainline_work_metric_key(row.get("wt_code") or row.get("work_type_code"), row.get("analytics_tag"))


def _mainline_work_rows_payload_for_ranges(
    d_to: date_cls,
    ranges: list[tuple[float, float]],
) -> tuple[dict[str, float], list[dict]]:
    totals = _empty_mainline_work_totals()
    details: list[dict] = []
    if not ranges:
        return totals, details
    rules = _general_report_work_rules()
    for row in _query_mainline_work_segment_rows(PROJECT_START_DATE, d_to, None, ranges):
        metric_key = _mainline_metric_row_key(row, rules)
        if not metric_key:
            continue
        for start, end, amount in _mainline_volume_parts_for_ranges(row.get("pk_start"), row.get("pk_end"), float(row.get("amount") or 0), ranges):
            totals[metric_key] += amount
            report_date = row.get("report_date")
            details.append({
                "date": report_date.isoformat() if hasattr(report_date, "isoformat") else str(report_date or ""),
                "metric_key": metric_key,
                "label": MAINLINE_WORK_METRIC_LABELS.get(metric_key, metric_key),
                "volume_m3": _clean_report_number(amount),
                "shift": row.get("shift") or "day",
                "work_type_code": row.get("wt_code"),
                "work_type_name": row.get("work_type_name") or row.get("analytics_tag"),
                "object_code": row.get("object_code"),
                "object_name": row.get("object_name"),
                "analytics_tag": row.get("analytics_tag"),
                "pk_start": start,
                "pk_end": end,
            })
    return totals, details


def _query_mainline_project_metric_rows(ranges: list[tuple[float, float]]) -> list[dict]:
    if not ranges or not _wip_table_exists("project_work_items"):
        return []
    filters = [
        "(pf.id IS NULL OR COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded'))",
    ]
    params: list = []
    _append_mainline_pk_range_filter(
        filters,
        params,
        "COALESCE(ps.pk_start, pf.pk_start, so.pk_start)",
        "COALESCE(ps.pk_end, pf.pk_end, so.pk_end)",
        ranges,
    )
    return query(
        _statement_scope_cte()
        + f"""
        SELECT so.object_code,
               so.object_name,
               so.object_type_code,
               so.object_type_name,
               so.pk_start AS section_pk_start,
               so.pk_end AS section_pk_end,
               so.object_pk_start,
               so.object_pk_end,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), wt.name) AS analytics_tag,
               COALESCE(ps.pk_start, pf.pk_start) AS project_pk_start,
               COALESCE(ps.pk_end, pf.pk_end) AS project_pk_end,
               COALESCE(ps.pk_start, pf.pk_start, so.pk_start) AS pk_start,
               COALESCE(ps.pk_end, pf.pk_end, so.pk_end) AS pk_end,
               CASE WHEN ps.id IS NOT NULL THEN COALESCE(ps.volume_segment, 0) ELSE COALESCE(pwi.project_volume, 0) END::numeric AS amount
        FROM project_work_items pwi
        LEFT JOIN constructives con ON con.id = pwi.constructive_id
        JOIN object_sections so ON so.id = COALESCE(pwi.object_id, con.object_id)
        JOIN work_types wt ON wt.id = pwi.work_type_id
        LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
        LEFT JOIN project_work_item_segments ps ON ps.project_work_item_id = pwi.id
        WHERE {' AND '.join(filters)}
        LIMIT 20000
        """,
        params,
    )


def _mainline_project_totals_for_ranges(ranges: list[tuple[float, float]]) -> dict[str, float]:
    totals = _empty_mainline_work_totals()
    if not ranges:
        return totals
    rules = _general_report_work_rules()
    for row in _query_mainline_project_metric_rows(ranges):
        metric_key = _mainline_metric_row_key(row, rules)
        if not metric_key:
            continue
        clip = _statement_clip_volume_to_section(row, float(row.get("amount") or 0), "project_pk_start", "project_pk_end")
        if clip is None:
            continue
        pk_start, pk_end, project_volume, _keep_pk_raw_text = clip
        for _start, _end, amount in _mainline_volume_parts_for_ranges(pk_start, pk_end, float(project_volume or 0), ranges):
            totals[metric_key] += amount
    return totals


def _attach_mainline_work_totals_to_sections(sections_by_id: dict[str, dict], d_to: date_cls) -> None:
    codes = [section.get("section_code") for section in sections_by_id.values() if section.get("section_code")]
    try:
        totals_by_section, _ = _mainline_work_rows_payload(d_to, codes, include_details=False)
    except Exception:
        logging.exception("Failed to build mainline work totals")
        totals_by_section = {}
    for section in sections_by_id.values():
        section["work_totals"] = _mainline_work_total_list(totals_by_section.get(_merge_section(section.get("section_code"))))


def _mainline_segment_day_rows(section_id: str, d_to: date_cls, section_code: Optional[str] = None) -> list[dict]:
    rows = []
    if _wip_table_exists("mainline_fill_status_segments"):
        rows.extend(query(
            """
            SELECT status_date AS date,
                   'report' AS source,
                   status_type,
                   pk_start,
                   pk_end,
                   NULL::text AS action,
                   NULL::text AS comment
            FROM mainline_fill_status_segments
            WHERE section_id = %s
              AND status_date >= %s
              AND status_date <= %s
              AND COALESCE(is_demo, false) IS FALSE
              AND COALESCE(review_tag, '') = ''
            ORDER BY status_date DESC, pk_start, pk_end
            """,
            [section_id, MAINLINE_FILL_DISPLAY_START_DATE, d_to],
        ))
    if _wip_table_exists("mainline_fill_state_corrections"):
        rows.extend(query(
            """
            SELECT effective_date AS date,
                   'correction' AS source,
                   status_type,
                   pk_start,
                   pk_end,
                   action,
                   comment
            FROM mainline_fill_state_corrections
            WHERE section_id = %s
              AND effective_date >= %s
              AND effective_date <= %s
            ORDER BY effective_date DESC, pk_start, pk_end
            """,
            [section_id, MAINLINE_FILL_DISPLAY_START_DATE, d_to],
        ))
    if not rows and section_code:
        rows.extend(_mainline_work_status_segment_rows(d_to, [section_code]))
    out = []
    for row in rows:
        start = float(row.get("pk_start")) if row.get("pk_start") is not None else None
        end = float(row.get("pk_end")) if row.get("pk_end") is not None else None
        date_value = row.get("date")
        status = row.get("status_type") or "no_work"
        out.append({
            "date": date_value.isoformat() if hasattr(date_value, "isoformat") else str(date_value or ""),
            "source": row.get("source"),
            "action": row.get("action"),
            "status_type": status,
            "status_label": MAINLINE_FILL_STATUS_LABELS.get(status, status),
            "pk_start": start,
            "pk_end": end,
            "length_m": _clean_report_number(abs((end or 0) - (start or 0))) if start is not None and end is not None else 0,
            "comment": row.get("comment"),
        })
    return sorted(out, key=lambda item: (item["date"], item.get("pk_start") or 0), reverse=True)


def _group_mainline_work_days(rows: list[dict]) -> list[dict]:
    grouped: dict[str, dict] = {}
    for row in rows:
        day = grouped.setdefault(row.get("date") or "", {
            "date": row.get("date") or "",
            "totals": _empty_mainline_work_totals(),
            "rows": [],
        })
        metric_key = row.get("metric_key")
        if metric_key in day["totals"]:
            day["totals"][metric_key] += float(row.get("volume_m3") or 0)
        day["rows"].append(row)
    out = []
    for day in grouped.values():
        day["totals"] = _mainline_work_total_list(day["totals"])
        day["rows"] = sorted(day["rows"], key=lambda item: (item.get("metric_key") or "", item.get("work_type_name") or ""))
        out.append(day)
    return sorted(out, key=lambda item: item["date"], reverse=True)


def _mainline_iso_date(value: object) -> Optional[str]:
    if not value:
        return None
    return value.isoformat() if hasattr(value, "isoformat") else str(value)


def _mainline_scheme_object_group(type_code: Optional[str]) -> str:
    return MAINLINE_SCHEME_OBJECT_TYPE_GROUPS.get(str(type_code or "").strip().upper(), "other")


def _mainline_pipe_pk_from_text(value: object) -> Optional[float]:
    text = str(value or "").replace(",", ".")
    pk_match = re.search(r"ПК\s*(\d+)\s*\+\s*(\d+(?:\.\d+)?)", text, flags=re.IGNORECASE)
    if pk_match:
        return float(int(pk_match.group(1)) * 100) + float(pk_match.group(2))
    code_match = re.search(r"\bPIPE_(?:ARRANGEMENT_)?(\d{4,})(?:_(\d+(?:\.\d+)?))?\b", text, flags=re.IGNORECASE)
    if not code_match:
        return None
    base = code_match.group(1)
    decimals = code_match.group(2)
    if decimals:
        return float(f"{base}.{decimals}")
    return float(base)


def _mainline_pipe_pk_from_row(row: dict) -> Optional[float]:
    for value in (row.get("object_name"), row.get("object_code")):
        pk = _mainline_pipe_pk_from_text(value)
        if pk is not None:
            return pk
    return None


def _mainline_clip_context_range_to_allowed(
    start: object,
    end: object,
    allowed_ranges: list[tuple[float, float]],
) -> list[tuple[float, float]]:
    if start is None or end is None:
        return []
    raw_start, raw_end = min(float(start), float(end)), max(float(start), float(end))
    is_point = raw_end - raw_start < 0.01
    out: list[tuple[float, float]] = []
    for allowed_start, allowed_end in allowed_ranges:
        lo, hi = min(float(allowed_start), float(allowed_end)), max(float(allowed_start), float(allowed_end))
        if is_point:
            if lo <= raw_start <= hi:
                out.append((raw_start, raw_start))
            continue
        clipped_start = max(raw_start, lo)
        clipped_end = min(raw_end, hi)
        if clipped_end - clipped_start >= 0.01:
            out.append((clipped_start, clipped_end))
    return out if is_point else _fill_merge_ranges(out)


def _mainline_reference_applies_to_object(row: dict, section: dict, obj: dict) -> bool:
    row_section_id = str(row.get("section_id") or "").strip()
    if row_section_id and row_section_id != str(section.get("section_id") or ""):
        return False
    row_section_code = _merge_section(row.get("section_code"))
    if row_section_code and row_section_code != _merge_section(section.get("section_code")):
        return False
    row_object_id = str(row.get("object_id") or "").strip()
    if row_object_id and row_object_id != str(obj.get("object_id") or ""):
        return False
    row_type = str(row.get("object_type_code") or "").strip().upper()
    if row_type and row_type != str(obj.get("object_type_code") or "").strip().upper():
        return False
    return bool(_mainline_clip_context_range_to_allowed(
        row.get("pk_start"),
        row.get("pk_end"),
        [(float(obj["pk_start"]), float(obj["pk_end"]))],
    ))


def _mainline_reference_applies_to_section(row: dict, section: dict) -> bool:
    row_section_id = str(row.get("section_id") or "").strip()
    if row_section_id and row_section_id != str(section.get("section_id") or ""):
        return False
    row_section_code = _merge_section(row.get("section_code"))
    if row_section_code and row_section_code != _merge_section(section.get("section_code")):
        return False
    allowed = [(item["pk_start"], item["pk_end"]) for item in section.get("ranges") or []]
    return bool(_mainline_clip_context_range_to_allowed(row.get("pk_start"), row.get("pk_end"), allowed))


def _mainline_reference_match_rank(row: dict, obj: dict) -> tuple[int, float, str]:
    if str(row.get("object_id") or "").strip() == str(obj.get("object_id") or "").strip():
        rank = 0
    elif str(row.get("object_type_code") or "").strip():
        rank = 1
    else:
        rank = 2
    return (rank, float(row.get("pk_start") or 0), str(row.get("id") or ""))


def _mainline_matching_reference_rows(rows: list[dict], section: dict, obj: dict) -> list[dict]:
    matches = [row for row in rows if _mainline_reference_applies_to_object(row, section, obj)]
    return sorted(matches, key=lambda row: _mainline_reference_match_rank(row, obj))


def _mainline_compact_rd_document(row: dict) -> dict:
    return {
        "id": row.get("id"),
        "rd_code": row.get("rd_code"),
        "rd_title": row.get("rd_title"),
        "issued_at": _mainline_iso_date(row.get("issued_at")),
        "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
        "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
        "comment": row.get("comment"),
    }


def _mainline_compact_schedule_row(row: dict) -> dict:
    start_date = _mainline_iso_date(row.get("required_start_date"))
    finish_date = _mainline_iso_date(row.get("required_finish_date"))
    work_direction = None
    if start_date and finish_date:
        work_direction = "от меньшего ПК к большему" if start_date <= finish_date else "от большего ПК к меньшему"
    return {
        "id": row.get("id"),
        "schedule_label": row.get("schedule_label"),
        "required_start_date": start_date,
        "required_finish_date": finish_date,
        "work_direction": work_direction,
        "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
        "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
        "comment": row.get("comment"),
    }


def _mainline_rd_status_for_object(obj: dict, docs: list[dict]) -> str:
    if not docs:
        return "missing"
    obj_start = float(obj["pk_start"])
    obj_end = float(obj["pk_end"])
    obj_len = max(0.0, abs(obj_end - obj_start))
    if obj_len < 0.01:
        return "issued"
    covered: list[tuple[float, float]] = []
    for row in docs:
        covered.extend(_mainline_clip_context_range_to_allowed(row.get("pk_start"), row.get("pk_end"), [(obj_start, obj_end)]))
    covered_len = sum(max(0.0, end - start) for start, end in _fill_merge_ranges(covered))
    if covered_len >= obj_len - 0.01:
        return "issued"
    return "partial" if covered_len > 0.01 else "missing"


def _mainline_pile_summary_template(source: Optional[str] = None) -> dict:
    return {
        "planned_main": 0,
        "planned_trial": 0,
        "driven_main": 0,
        "driven_trial": 0,
        "pile_marks": [],
        "pile_mark": None,
        "pk_start": None,
        "pk_end": None,
        "available_from": None,
        "source": source,
    }


def _mainline_pile_summary_finish(summary: dict) -> dict:
    marks = sorted({str(mark).strip() for mark in (summary.get("pile_marks") or []) if str(mark or "").strip()})
    summary["pile_marks"] = marks
    summary["pile_mark"] = "; ".join(marks[:8]) if marks else None
    for key in ("planned_main", "planned_trial", "driven_main", "driven_trial"):
        summary[key] = _clean_report_number(float(summary.get(key) or 0))
    for key in ("pk_start", "pk_end"):
        if summary.get(key) is not None:
            summary[key] = float(summary[key])
    if summary.get("available_from"):
        summary["available_from"] = _mainline_iso_date(summary.get("available_from"))
    return summary


def _mainline_merge_pile_summary(target: dict, source: dict, *, prefer_source: bool = False) -> dict:
    out = dict(target or _mainline_pile_summary_template())
    if prefer_source and source.get("source"):
        out["source"] = source.get("source")
    elif not out.get("source"):
        out["source"] = source.get("source")
    for key in ("planned_main", "planned_trial", "driven_main", "driven_trial"):
        out[key] = float(out.get(key) or 0) + float(source.get(key) or 0)
    out["pile_marks"] = [*(out.get("pile_marks") or []), *(source.get("pile_marks") or [])]
    src_start = source.get("pk_start")
    src_end = source.get("pk_end")
    if src_start is not None:
        out["pk_start"] = min(float(out["pk_start"]), float(src_start)) if out.get("pk_start") is not None else float(src_start)
    if src_end is not None:
        out["pk_end"] = max(float(out["pk_end"]), float(src_end)) if out.get("pk_end") is not None else float(src_end)
    src_available_from = source.get("available_from")
    if src_available_from:
        if not out.get("available_from"):
            out["available_from"] = src_available_from
        else:
            out["available_from"] = min(str(out["available_from"]), str(src_available_from))
    return out


def _query_mainline_pile_field_summaries() -> tuple[dict[str, dict], list[dict]]:
    rows = query(
        """
        SELECT pf.object_id::text AS object_id,
               MIN(LEAST(pf.pk_start, pf.pk_end))::numeric AS pk_start,
               MAX(GREATEST(pf.pk_start, pf.pk_end))::numeric AS pk_end,
               SUM(CASE WHEN LOWER(COALESCE(pf.field_type, 'main')) = 'test' THEN COALESCE(pf.pile_count, 0) ELSE 0 END)::numeric AS planned_trial,
               SUM(CASE WHEN LOWER(COALESCE(pf.field_type, 'main')) = 'test' THEN 0 ELSE COALESCE(pf.pile_count, 0) END)::numeric AS planned_main,
               SUM(CASE WHEN LOWER(COALESCE(pf.field_type, 'main')) = 'test' THEN COALESCE(pf.driven_pile_count, 0) ELSE 0 END)::numeric AS catalog_driven_trial,
               SUM(CASE WHEN LOWER(COALESCE(pf.field_type, 'main')) = 'test' THEN 0 ELSE COALESCE(pf.driven_pile_count, 0) END)::numeric AS catalog_driven_main,
               ARRAY_AGG(DISTINCT NULLIF(BTRIM(pf.pile_type), '')) FILTER (WHERE NULLIF(BTRIM(pf.pile_type), '') IS NOT NULL) AS pile_marks,
               MIN(pf.created_at) AS available_from
        FROM pile_fields pf
        WHERE pf.object_id IS NOT NULL
          AND pf.pk_start IS NOT NULL
          AND pf.pk_end IS NOT NULL
          AND COALESCE(pf.is_demo, false) IS FALSE
          AND COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded')
        GROUP BY pf.object_id
        """,
    )
    by_object: dict[str, dict] = {}
    fallback_rows: list[dict] = []
    for row in rows:
        object_id = str(row.get("object_id") or "")
        summary = _mainline_pile_summary_template("pile_fields")
        summary.update({
            "planned_main": float(row.get("planned_main") or 0),
            "planned_trial": float(row.get("planned_trial") or 0),
            "driven_main": float(row.get("catalog_driven_main") or 0),
            "driven_trial": float(row.get("catalog_driven_trial") or 0),
            "pile_marks": row.get("pile_marks") or [],
            "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
            "available_from": row.get("available_from"),
        })
        by_object[object_id] = _mainline_pile_summary_finish(summary)
        fallback_rows.append({"object_id": object_id, **by_object[object_id]})
    return by_object, fallback_rows


def _query_mainline_pipe_pile_summaries() -> dict[str, dict]:
    if not _wip_table_exists("pipe_pile_specs"):
        return {}
    rows = query(
        """
        WITH seg AS (
          SELECT object_id,
                 MIN(LEAST(pk_start, pk_end)) AS pk_start,
                 MAX(GREATEST(pk_start, pk_end)) AS pk_end
          FROM object_segments
          WHERE pk_start IS NOT NULL
            AND pk_end IS NOT NULL
            AND COALESCE(review_tag, '') = ''
          GROUP BY object_id
        )
        SELECT pps.object_id::text AS object_id,
               MIN(seg.pk_start)::numeric AS pk_start,
               MAX(seg.pk_end)::numeric AS pk_end,
               SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN COALESCE(pps.quantity, 0) ELSE 0 END)::numeric AS planned_main,
               SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN COALESCE(pps.quantity, 0) ELSE 0 END)::numeric AS planned_trial,
               ARRAY_AGG(DISTINCT CONCAT('ПЖБТ ', COALESCE(pps.pile_length_m::text, '?'), ' м'))
                 FILTER (WHERE pps.pile_length_m IS NOT NULL) AS pile_marks
        FROM pipe_pile_specs pps
        JOIN work_types wt ON wt.id = pps.work_type_id
        LEFT JOIN seg ON seg.object_id = pps.object_id
        WHERE COALESCE(pps.is_active, true) IS TRUE
          AND wt.code = ANY(%s)
        GROUP BY pps.object_id
        """,
        [list(MAINLINE_SCHEME_PILE_WORK_TYPE_CODES)],
    )
    by_object: dict[str, dict] = {}
    for row in rows:
        object_id = str(row.get("object_id") or "")
        summary = _mainline_pile_summary_template("pipe_pile_specs")
        summary.update({
            "planned_main": float(row.get("planned_main") or 0),
            "planned_trial": float(row.get("planned_trial") or 0),
            "pile_marks": row.get("pile_marks") or [],
            "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
        })
        by_object[object_id] = _mainline_pile_summary_finish(summary)
    return by_object


def _query_mainline_project_pile_summaries() -> dict[str, dict]:
    if not _wip_table_exists("project_work_items"):
        return {}
    rows = query(
        """
        SELECT pwi.object_id::text AS object_id,
               MIN(pf.pk_start)::numeric AS pk_start,
               MAX(pf.pk_end)::numeric AS pk_end,
               SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN COALESCE(pwi.project_volume, 0) ELSE 0 END)::numeric AS planned_main,
               SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN COALESCE(pwi.project_volume, 0) ELSE 0 END)::numeric AS planned_trial,
               ARRAY_AGG(DISTINCT NULLIF(BTRIM(COALESCE(pf.pile_type, wt.name)), ''))
                 FILTER (WHERE NULLIF(BTRIM(COALESCE(pf.pile_type, wt.name)), '') IS NOT NULL) AS pile_marks
        FROM project_work_items pwi
        JOIN work_types wt ON wt.id = pwi.work_type_id
        LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
        WHERE pwi.object_id IS NOT NULL
          AND wt.code = ANY(%s)
        GROUP BY pwi.object_id
        """,
        [list(MAINLINE_SCHEME_PILE_WORK_TYPE_CODES)],
    )
    by_object: dict[str, dict] = {}
    for row in rows:
        object_id = str(row.get("object_id") or "")
        summary = _mainline_pile_summary_template("project_work_items")
        summary.update({
            "planned_main": float(row.get("planned_main") or 0),
            "planned_trial": float(row.get("planned_trial") or 0),
            "pile_marks": row.get("pile_marks") or [],
            "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
        })
        by_object[object_id] = _mainline_pile_summary_finish(summary)
    return by_object


def _query_mainline_pile_fact_summaries(d_to: date_cls) -> dict[str, dict]:
    rows = query(
        f"""
        SELECT COALESCE(dwi.object_id, seg_scheme_pile_pf.object_id)::text AS object_id,
               SUM(CASE WHEN wt.code = 'PILE_MAIN' THEN ({_pile_effective_volume_expr('seg_scheme_pile')}) ELSE 0 END)::numeric AS driven_main,
               SUM(CASE WHEN wt.code = 'PILE_TRIAL' THEN ({_pile_effective_volume_expr('seg_scheme_pile')}) ELSE 0 END)::numeric AS driven_trial
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments seg_scheme_pile_count_item
          WHERE seg_scheme_pile_count_item.daily_work_item_id = dwi.id
            AND COALESCE(seg_scheme_pile_count_item.is_demo, false) IS FALSE
        ) seg_scheme_pile_count ON true
        LEFT JOIN daily_work_item_segments seg_scheme_pile
          ON seg_scheme_pile.daily_work_item_id = dwi.id
         AND COALESCE(seg_scheme_pile.is_demo, false) IS FALSE
        LEFT JOIN pile_fields seg_scheme_pile_pf ON seg_scheme_pile_pf.id = seg_scheme_pile.pile_field_id
        WHERE dwi.report_date >= %s
          AND dwi.report_date <= %s
          AND COALESCE(dwi.is_demo, false) IS FALSE
          AND COALESCE(dr.is_demo, false) IS FALSE
          AND {_approved_report_exists("dwi")}
          AND wt.code = ANY(%s)
          AND COALESCE(dwi.object_id, seg_scheme_pile_pf.object_id) IS NOT NULL
        GROUP BY COALESCE(dwi.object_id, seg_scheme_pile_pf.object_id)
        """,
        [PROJECT_START_DATE, d_to, list(MAINLINE_SCHEME_PILE_WORK_TYPE_CODES)],
    )
    by_object: dict[str, dict] = {}
    for row in rows:
        object_id = str(row.get("object_id") or "")
        summary = _mainline_pile_summary_template("facts_only")
        summary.update({
            "driven_main": float(row.get("driven_main") or 0),
            "driven_trial": float(row.get("driven_trial") or 0),
        })
        by_object[object_id] = _mainline_pile_summary_finish(summary)
    return by_object


def _mainline_pile_summaries_by_object(d_to: date_cls) -> tuple[dict[str, dict], list[dict]]:
    pile_field_by_object, pile_field_ranges = _query_mainline_pile_field_summaries()
    pipe_by_object = _query_mainline_pipe_pile_summaries()
    project_by_object = _query_mainline_project_pile_summaries()
    fact_by_object = _query_mainline_pile_fact_summaries(d_to)
    object_ids = set(pile_field_by_object) | set(pipe_by_object) | set(project_by_object) | set(fact_by_object)
    out: dict[str, dict] = {}
    for object_id in object_ids:
        summary = _mainline_pile_summary_template()
        has_plan = False
        if object_id in pile_field_by_object:
            summary = _mainline_merge_pile_summary(summary, pile_field_by_object[object_id], prefer_source=True)
            has_plan = True
        if object_id in pipe_by_object:
            summary = _mainline_merge_pile_summary(
                _mainline_pile_summary_template(),
                pipe_by_object[object_id],
                prefer_source=True,
            )
            has_plan = True
        if not has_plan and object_id in project_by_object:
            summary = _mainline_merge_pile_summary(summary, project_by_object[object_id], prefer_source=True)
        if object_id in fact_by_object:
            fact = fact_by_object[object_id]
            summary["driven_main"] = max(float(summary.get("driven_main") or 0), float(fact.get("driven_main") or 0))
            summary["driven_trial"] = max(float(summary.get("driven_trial") or 0), float(fact.get("driven_trial") or 0))
            if not summary.get("source"):
                summary["source"] = fact.get("source")
        out[object_id] = _mainline_pile_summary_finish(summary)
    return out, pile_field_ranges


def _mainline_overlapping_pile_summary(
    obj: dict,
    pile_field_ranges: list[dict],
) -> Optional[dict]:
    obj_start = obj.get("pk_start")
    obj_end = obj.get("pk_end")
    if obj_start is None or obj_end is None:
        return None
    overlaps = [
        row for row in pile_field_ranges
        if row.get("pk_start") is not None
        and row.get("pk_end") is not None
        and min(float(obj_end), float(row["pk_end"])) >= max(float(obj_start), float(row["pk_start"]))
    ]
    if not overlaps:
        return None
    summary = _mainline_pile_summary_template("overlapping_pile_fields")
    for row in overlaps:
        summary = _mainline_merge_pile_summary(summary, row)
    return _mainline_pile_summary_finish(summary)


def _query_mainline_scheme_related_object_rows() -> list[dict]:
    type_codes = list(MAINLINE_SCHEME_OBJECT_TYPE_GROUPS.keys())
    rows = query(
        """
        SELECT o.id::text AS object_id,
               o.object_code,
               o.name AS object_name,
               o.comment AS object_comment,
               ot.code AS object_type_code,
               ot.name AS object_type_name,
               MIN(LEAST(pk.pk_start, pk.pk_end))::numeric AS pk_start,
               MAX(GREATEST(pk.pk_start, pk.pk_end))::numeric AS pk_end
        FROM objects o
        JOIN object_types ot ON ot.id = o.object_type_id
        LEFT JOIN LATERAL (
          SELECT os.pk_start, os.pk_end
          FROM object_segments os
          WHERE os.object_id = o.id
            AND os.pk_start IS NOT NULL
            AND os.pk_end IS NOT NULL
            AND COALESCE(os.review_tag, '') = ''
          UNION ALL
          SELECT pf.pk_start, pf.pk_end
          FROM pile_fields pf
          WHERE pf.object_id = o.id
            AND pf.pk_start IS NOT NULL
            AND pf.pk_end IS NOT NULL
            AND COALESCE(pf.is_demo, false) IS FALSE
            AND COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded')
        ) pk ON true
        WHERE COALESCE(o.is_active, true) IS TRUE
          AND (COALESCE(o.review_tag, '') = '' OR ot.code = 'PIPE')
          AND ot.code = ANY(%s)
        GROUP BY o.id, o.object_code, o.name, o.comment, ot.code, ot.name
        HAVING (MIN(pk.pk_start) IS NOT NULL AND MAX(pk.pk_end) IS NOT NULL) OR ot.code = 'PIPE'
        ORDER BY MIN(LEAST(pk.pk_start, pk.pk_end)), ot.code, o.object_code
        """,
        [type_codes],
    )
    out = []
    for row in rows:
        start_value = row.get("pk_start")
        end_value = row.get("pk_end")
        if start_value is None or end_value is None:
            pipe_pk = _mainline_pipe_pk_from_row(row)
            if pipe_pk is None:
                continue
            start_value = pipe_pk
            end_value = pipe_pk
        group = _mainline_scheme_object_group(row.get("object_type_code"))
        out.append({
            "object_id": row.get("object_id"),
            "object_code": row.get("object_code"),
            "object_name": row.get("object_name"),
            "object_comment": row.get("object_comment"),
            "object_type_code": row.get("object_type_code"),
            "object_type_name": row.get("object_type_name"),
            "object_group": group,
            "object_group_label": MAINLINE_SCHEME_OBJECT_GROUP_LABELS.get(group, "Объект"),
            "communication_type": row.get("object_type_name") if group == "crossing" else None,
            "communications": row.get("object_name") if group == "crossing" else None,
            "pk_start": float(start_value),
            "pk_end": float(end_value),
        })
    return out


def _query_mainline_scheme_rd_rows() -> list[dict]:
    if not _wip_table_exists("mainline_rd_coverage"):
        return []
    return query(
        """
        SELECT rd.id::text AS id,
               rd.section_id::text AS section_id,
               cs.code AS section_code,
               rd.object_id::text AS object_id,
               COALESCE(NULLIF(BTRIM(rd.object_type_code), ''), ot.code) AS object_type_code,
               rd.pk_start,
               rd.pk_end,
               rd.rd_code,
               rd.rd_title,
               rd.issued_at,
               rd.comment
        FROM mainline_rd_coverage rd
        LEFT JOIN construction_sections cs ON cs.id = rd.section_id
        LEFT JOIN objects o ON o.id = rd.object_id
        LEFT JOIN object_types ot ON ot.id = o.object_type_id
        WHERE COALESCE(rd.is_active, true) IS TRUE
        ORDER BY rd.pk_start, rd.pk_end, rd.created_at
        """
    )


def _query_mainline_scheme_schedule_rows() -> list[dict]:
    if not _wip_table_exists("mainline_work_schedule_ranges"):
        return []
    return query(
        """
        SELECT sw.id::text AS id,
               sw.section_id::text AS section_id,
               cs.code AS section_code,
               sw.object_id::text AS object_id,
               COALESCE(NULLIF(BTRIM(sw.object_type_code), ''), ot.code) AS object_type_code,
               sw.pk_start,
               sw.pk_end,
               sw.required_start_date,
               sw.required_finish_date,
               sw.schedule_label,
               sw.comment
        FROM mainline_work_schedule_ranges sw
        LEFT JOIN construction_sections cs ON cs.id = sw.section_id
        LEFT JOIN objects o ON o.id = sw.object_id
        LEFT JOIN object_types ot ON ot.id = o.object_type_id
        WHERE COALESCE(sw.is_active, true) IS TRUE
        ORDER BY sw.pk_start, sw.pk_end, sw.required_start_date NULLS LAST, sw.created_at
        """
    )


def _attach_mainline_scheme_context_to_sections(sections_by_id: dict[str, dict], d_to: Optional[date_cls] = None) -> dict:
    d_to = d_to or date_cls.today()
    rd_schema_ready = _wip_table_exists("mainline_rd_coverage")
    schedule_schema_ready = _wip_table_exists("mainline_work_schedule_ranges")
    try:
        object_rows = _query_mainline_scheme_related_object_rows()
        rd_rows = _query_mainline_scheme_rd_rows()
        schedule_rows = _query_mainline_scheme_schedule_rows()
        pile_summaries, pile_field_ranges = _mainline_pile_summaries_by_object(d_to)
    except Exception:
        logging.exception("Failed to build mainline scheme context")
        object_rows, rd_rows, schedule_rows, pile_summaries, pile_field_ranges = [], [], [], {}, []
    for section in sections_by_id.values():
        allowed = [(item["pk_start"], item["pk_end"]) for item in section.get("ranges") or []]
        related_objects = []
        for obj in object_rows:
            clipped_ranges = _mainline_clip_context_range_to_allowed(obj.get("pk_start"), obj.get("pk_end"), allowed)
            for index, (start, end) in enumerate(clipped_ranges):
                item = {
                    **obj,
                    "section_id": section.get("section_id"),
                    "section_code": section.get("section_code"),
                    "pk_start": start,
                    "pk_end": end,
                    "object_pk_start": obj.get("pk_start"),
                    "object_pk_end": obj.get("pk_end"),
                    "clipped": index > 0 or abs(float(obj.get("pk_start")) - start) > 0.01 or abs(float(obj.get("pk_end")) - end) > 0.01,
                }
                pile_summary = pile_summaries.get(str(obj.get("object_id") or ""))
                if not pile_summary and item.get("object_group") in {"pipe", "crossing"}:
                    pile_summary = _mainline_overlapping_pile_summary(item, pile_field_ranges)
                docs = _mainline_matching_reference_rows(rd_rows, section, item)
                schedules = _mainline_matching_reference_rows(schedule_rows, section, item)
                rd_status = _mainline_rd_status_for_object(item, docs)
                first_schedule = schedules[0] if schedules else {}
                item.update({
                    "rd_status": rd_status,
                    "rd_label": MAINLINE_RD_STATUS_LABELS.get(rd_status, rd_status),
                    "rd_documents": [_mainline_compact_rd_document(row) for row in docs[:6]],
                    "schedule_rows": [_mainline_compact_schedule_row(row) for row in schedules[:6]],
                    "required_start_date": _mainline_iso_date(first_schedule.get("required_start_date")),
                    "required_finish_date": _mainline_iso_date(first_schedule.get("required_finish_date")),
                    "schedule_label": first_schedule.get("schedule_label"),
                    "schedule_comment": first_schedule.get("comment"),
                    "pile_summary": pile_summary,
                })
                related_objects.append(item)
        section_docs = [
            _mainline_compact_rd_document(row)
            for row in rd_rows
            if _mainline_reference_applies_to_section(row, section)
        ]
        section_schedules = [
            _mainline_compact_schedule_row(row)
            for row in schedule_rows
            if _mainline_reference_applies_to_section(row, section)
        ]
        related_objects.sort(key=lambda row: (
            MAINLINE_SCHEME_OBJECT_GROUP_ORDER.get(row.get("object_group"), 90),
            row.get("pk_start") or 0,
            row.get("object_code") or "",
        ))
        rd_summary = {"issued": 0, "partial": 0, "missing": 0}
        for obj in related_objects:
            status = obj.get("rd_status") or "missing"
            if status in rd_summary:
                rd_summary[status] += 1
        section["related_objects"] = related_objects
        section["rd_documents"] = section_docs
        section["schedule_rows"] = section_schedules
        section["rd_summary"] = rd_summary
    return {
        "rd_schema_ready": rd_schema_ready,
        "schedule_schema_ready": schedule_schema_ready,
    }


def _mainline_fill_status_payload(to: Optional[str] = None):
    _, d_to = _parse_range(None, to)
    boundary_rows = query(
        """
        SELECT cs.id::text AS section_id,
               cs.code AS section_code,
               cs.name AS section_name,
               cs.sort_order,
               csv.pk_start,
               csv.pk_end
        FROM construction_section_versions csv
        JOIN construction_sections cs ON cs.id = csv.section_id
        WHERE csv.is_current
          AND csv.boundary_kind = 'main'
          AND cs.is_active IS NOT FALSE
          AND csv.pk_start IS NOT NULL
          AND csv.pk_end IS NOT NULL
        ORDER BY cs.sort_order NULLS LAST, cs.code, LEAST(csv.pk_start, csv.pk_end)
        """
    )
    sections_by_id: dict[str, dict] = {}
    for row in boundary_rows:
        section_id = str(row.get("section_id"))
        start = float(row.get("pk_start"))
        end = float(row.get("pk_end"))
        section = sections_by_id.setdefault(section_id, {
            "section_id": section_id,
            "section_code": row.get("section_code"),
            "section_name": row.get("section_name"),
            "sort_order": row.get("sort_order"),
            "ranges": [],
            "segments": [],
            "effective_date": None,
        })
        section["ranges"].append({"pk_start": min(start, end), "pk_end": max(start, end)})
    for section in sections_by_id.values():
        ranges = [(item["pk_start"], item["pk_end"]) for item in section["ranges"]]
        merged = _fill_merge_ranges(ranges)
        section["ranges"] = [{"pk_start": start, "pk_end": end} for start, end in merged]
        section["pk_start"] = min((start for start, _ in merged), default=None)
        section["pk_end"] = max((end for _, end in merged), default=None)

    schema_ready = _wip_table_exists("mainline_fill_status_segments")
    raw = query(
        """
        SELECT section_id::text AS section_id,
               pk_start,
               pk_end,
               status_type,
               status_date,
               MAX(status_date) OVER (PARTITION BY section_id) AS last_date
        FROM mainline_fill_status_segments
        WHERE status_date >= %s
          AND status_date <= %s
          AND COALESCE(is_demo, false) IS FALSE
          AND COALESCE(review_tag, '') = ''
        ORDER BY status_date, created_at, id
        """,
        [MAINLINE_FILL_DISPLAY_START_DATE, d_to],
    ) if schema_ready else []
    corrections = query(
        """
        SELECT section_id::text AS section_id,
               pk_start,
               pk_end,
               action,
               status_type,
               effective_date,
               MAX(effective_date) OVER (PARTITION BY section_id) AS last_correction_date
        FROM mainline_fill_state_corrections
        WHERE effective_date >= %s
          AND effective_date <= %s
        ORDER BY effective_date, created_at, id
        """,
        [MAINLINE_FILL_DISPLAY_START_DATE, d_to],
    ) if _wip_table_exists("mainline_fill_state_corrections") else []

    grouped_raw: dict[str, list[dict]] = {}
    grouped_corrections: dict[str, list[dict]] = {}
    grouped_work: dict[str, list[dict]] = {}
    work_rows = _mainline_work_status_segment_rows(
        d_to,
        [section.get("section_code") for section in sections_by_id.values() if section.get("section_code")],
    )
    for row in raw:
        grouped_raw.setdefault(str(row.get("section_id")), []).append(row)
    for row in corrections:
        grouped_corrections.setdefault(str(row.get("section_id")), []).append(row)
    for row in work_rows:
        grouped_work.setdefault(_merge_section(row.get("section_code")) or "", []).append(row)

    for section_id, section in sections_by_id.items():
        allowed = [(item["pk_start"], item["pk_end"]) for item in section["ranges"]]
        by_status: dict[str, list[tuple[float, float]]] = {status: [] for status in MAINLINE_FILL_STATUS_PRIORITY}
        last_dates = []
        status_rows = grouped_raw.get(section_id) or grouped_work.get(_merge_section(section.get("section_code")) or "", [])
        for row in status_rows:
            status = row.get("status_type")
            if status not in by_status:
                continue
            by_status[status].extend(_fill_clamp_to_ranges(row.get("pk_start"), row.get("pk_end"), allowed))
            if row.get("last_date"):
                last_dates.append(row.get("last_date"))
        for correction in grouped_corrections.get(section_id, []):
            correction_ranges = _fill_clamp_to_ranges(correction.get("pk_start"), correction.get("pk_end"), allowed)
            if not correction_ranges:
                continue
            for status in MAINLINE_FILL_STATUS_PRIORITY:
                by_status[status] = _fill_subtract_ranges(by_status[status], correction_ranges)
            if correction.get("action") != "clear_status" and correction.get("status_type") in by_status:
                by_status[correction["status_type"]].extend(correction_ranges)
            if correction.get("last_correction_date"):
                last_dates.append(correction.get("last_correction_date"))
        for status in MAINLINE_FILL_STATUS_PRIORITY:
            by_status[status] = _fill_merge_ranges(by_status[status])
        exclusive: dict[str, list[tuple[float, float]]] = {}
        higher: list[tuple[float, float]] = []
        for status in MAINLINE_FILL_STATUS_PRIORITY:
            exclusive[status] = _fill_subtract_ranges(by_status[status], higher)
            higher = _fill_merge_ranges(higher + exclusive[status])
        segments = []
        for status, ranges in exclusive.items():
            for start, end in ranges:
                if end - start >= 0.5:
                    segments.append({"pk_start": start, "pk_end": end, "status_type": status, "is_demo": False})
        section["segments"] = sorted(segments, key=lambda item: item["pk_start"])
        if last_dates:
            section["effective_date"] = max(last_dates).isoformat()
    _attach_mainline_work_totals_to_sections(sections_by_id, d_to)
    context_schema = _attach_mainline_scheme_context_to_sections(sections_by_id, d_to)
    return {
        "as_of": d_to.isoformat(),
        "display_start_date": MAINLINE_FILL_DISPLAY_START_DATE.isoformat(),
        "sections": list(sections_by_id.values()),
        "schema_ready": schema_ready,
        **context_schema,
    }


@router.get("/mainline-fill/status")
def mainline_fill_status(to: Optional[str] = None, _user=Depends(current_user)):
    _, d_to = _parse_range(None, to)
    endpoint = "mainline_fill_status.v2"
    fingerprint = _dashboard_source_fingerprint(MAINLINE_FILL_DISPLAY_START_DATE, d_to, include_mainline_fill=True)
    persistent_key = _dashboard_response_cache_key({"endpoint": "mainline_fill_status", "to": d_to})
    cached = _dashboard_response_cache_get(endpoint, persistent_key, fingerprint)
    if cached is not None:
        return _dashboard_response_cache_mark(cached, status="fresh", fingerprint=fingerprint)
    stale = _dashboard_response_cache_stale_payload(
        endpoint,
        persistent_key,
        fingerprint,
        mainline_fill_status,
        to,
    )
    if stale is not None:
        return stale
    return _dashboard_response_cache_build_or_wait(
        endpoint,
        persistent_key,
        fingerprint,
        lambda: _mainline_fill_status_payload(to),
    )


@router.get("/mainline-fill/sections/{section_code}/details")
def mainline_fill_section_details(
    section_code: str,
    to: Optional[str] = None,
    _user=Depends(current_user),
):
    _, d_to = _parse_range(None, to)
    status_data = mainline_fill_status(to, _user)
    requested_code = _merge_section(section_code)
    section = next(
        (item for item in status_data.get("sections", []) if _merge_section(item.get("section_code")) == requested_code),
        None,
    )
    if not section:
        raise HTTPException(404, "Участок ОХ не найден")
    detail_ranges = _mainline_section_ranges_from_payload(section)
    work_totals, work_rows = _mainline_work_rows_payload_for_ranges(d_to, detail_ranges)
    project_totals = _mainline_project_totals_for_ranges(detail_ranges)
    return {
        "as_of": d_to.isoformat(),
        "section_id": section.get("section_id"),
        "section_code": section.get("section_code"),
        "section_name": section.get("section_name"),
        "ranges": section.get("ranges") or [],
        "work_totals": _mainline_work_total_list(work_totals),
        "project_totals": _mainline_work_total_list(project_totals),
        "work_days": _group_mainline_work_days(work_rows),
        "segment_days": _mainline_segment_day_rows(section.get("section_id"), d_to, section.get("section_code")),
        "related_objects": section.get("related_objects") or [],
        "rd_documents": section.get("rd_documents") or [],
        "schedule_rows": section.get("schedule_rows") or [],
        "rd_summary": section.get("rd_summary") or {"issued": 0, "partial": 0, "missing": 0},
        "rd_schema_ready": status_data.get("rd_schema_ready", False),
        "schedule_schema_ready": status_data.get("schedule_schema_ready", False),
    }


@router.get("/database/mainline-fill-corrections")
def database_mainline_fill_corrections(
    to: Optional[str] = None,
    _user=Depends(current_user),
):
    status_data = _mainline_fill_status_payload(to)
    corrections = []
    if status_data.get("schema_ready") and _wip_table_exists("mainline_fill_state_corrections"):
        corrections = query(
            """
            SELECT c.id::text AS id,
                   c.section_id::text AS section_id,
                   cs.code AS section_code,
                   cs.name AS section_name,
                   c.effective_date,
                   c.action,
                   c.status_type,
                   c.pk_start,
                   c.pk_end,
                   c.comment,
                   c.created_by,
                   c.created_at
            FROM mainline_fill_state_corrections c
            JOIN construction_sections cs ON cs.id = c.section_id
            ORDER BY c.effective_date DESC, c.created_at DESC
            LIMIT 120
            """
        )
    return {
        "as_of": status_data.get("as_of"),
        "schema_ready": status_data.get("schema_ready", False),
        "sections": status_data.get("sections", []),
        "corrections": [
            {
                "id": row.get("id"),
                "section_id": row.get("section_id"),
                "section_code": row.get("section_code"),
                "section_name": row.get("section_name"),
                "effective_date": row.get("effective_date").isoformat() if row.get("effective_date") else None,
                "action": row.get("action"),
                "status_type": row.get("status_type"),
                "pk_start": float(row.get("pk_start")) if row.get("pk_start") is not None else None,
                "pk_end": float(row.get("pk_end")) if row.get("pk_end") is not None else None,
                "comment": row.get("comment") or "",
                "created_by": row.get("created_by"),
                "created_at": row.get("created_at").isoformat() if row.get("created_at") else None,
            }
            for row in corrections
        ],
    }


@router.post("/database/mainline-fill-corrections")
def database_create_mainline_fill_correction(
    body: MainlineFillCorrectionBody,
    _admin=Depends(require_admin),
):
    if not _wip_table_exists("mainline_fill_state_corrections"):
        raise HTTPException(400, "Миграция mainline_fill_state_corrections не применена")
    try:
        effective_date = date_cls.fromisoformat(body.effective_date)
    except Exception:
        raise HTTPException(400, "Некорректная дата корректировки")
    status_type = (body.status_type or "").strip()
    if status_type not in MAINLINE_FILL_STATUS_TYPES:
        raise HTTPException(400, "Некорректный статус отсыпки ОХ")
    action = "clear_status" if status_type == "no_work" or body.action == "clear_status" else "set_status"
    if action == "clear_status":
        status_type = "no_work"
    if body.pk_start is None or body.pk_end is None:
        raise HTTPException(400, "Укажите ПК начала и конца")
    pk_start = min(float(body.pk_start), float(body.pk_end))
    pk_end = max(float(body.pk_start), float(body.pk_end))
    section = query_one(
        "SELECT id::text AS id, code FROM construction_sections WHERE code = %s AND is_active IS NOT FALSE LIMIT 1",
        [body.section_code],
    )
    if not section:
        raise HTTPException(404, "Участок не найден")
    correction_id = str(uuid.uuid4())
    created_by = getattr(_admin, "username", None)
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO mainline_fill_state_corrections (
                  id, section_id, effective_date, action, status_type,
                  pk_start, pk_end, comment, created_by
                ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    correction_id,
                    section["id"],
                    effective_date,
                    action,
                    status_type,
                    pk_start,
                    pk_end,
                    body.comment,
                    created_by,
                ),
            )
        conn.commit()
    _invalidate_dashboard_response_cache("mainline_fill_correction_create")
    return {"ok": True, "id": correction_id}


@router.delete("/database/mainline-fill-corrections/{correction_id}")
def database_delete_mainline_fill_correction(
    correction_id: str,
    _admin=Depends(require_admin),
):
    if not _wip_table_exists("mainline_fill_state_corrections"):
        raise HTTPException(400, "Миграция mainline_fill_state_corrections не применена")
    try:
        uuid.UUID(correction_id)
    except ValueError:
        raise HTTPException(400, "Некорректный id корректировки")
    with get_conn() as conn:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM mainline_fill_state_corrections WHERE id = %s RETURNING id", (correction_id,))
            deleted = cur.fetchone()
        conn.commit()
    if not deleted:
        raise HTTPException(404, "Корректировка не найдена")
    _invalidate_dashboard_response_cache("mainline_fill_correction_delete")
    return {"ok": True, "id": correction_id}


# ── Settings: norms & aliases ─────────────────────────────────────────────

_NORM_CODE_PREFIX_FALLBACK: dict[str, str] = {
    'RzrGrn': 'Разработка грунта',
    'SntPRS': 'Снятие ПРС',
    'UkrOtk': 'Устройство кюветов/укрепление откосов',
    'PlnOtk': 'Планировка откосов',
    'PlnZmp': 'Планировка земполотна под отметку',
    'PlnSch': 'Профилировка щебёночного слоя',
    'UsOsTN': 'Устройство насыпи',
    'UNSOSh': 'Устройство насыпи из ЩПС/ЩПГС',
    'RspGrn': 'Профилирование (ПРС поверхности)',
    'UplPds': 'Уплотнение насыпи',
}


def _work_type_productivity_flags(codes: list[str]) -> dict[str, bool]:
    if not codes:
        return {}
    try:
        rows = query(
            """
            SELECT code, COALESCE(productivity_enabled, true) AS productivity_enabled
            FROM work_types
            WHERE code = ANY(%s)
            """,
            [codes],
        )
    except Exception:
        return {}
    return {str(r["code"]): bool(r.get("productivity_enabled", True)) for r in rows}


def _resolve_work_name(wt_code: str, norm_code: Optional[str]) -> str:
    """Вернёт человекочитаемое название: work_types.name либо fallback по префиксу norm_code."""
    try:
        row = query_one("SELECT name FROM work_types WHERE code = %s", (wt_code,))
        if row and row.get("name"):
            return str(row["name"])
    except Exception:
        pass
    if norm_code:
        for prefix, label in _NORM_CODE_PREFIX_FALLBACK.items():
            if norm_code.startswith(prefix):
                return label
    return wt_code


def _resolve_norm_name(equipment_type: Optional[str], wt_code: str, spec: dict) -> str:
    existing = str((spec or {}).get("norm_name") or "").strip()
    if existing:
        return existing
    equipment = str(equipment_type or "").strip().lower()
    norm_code = str((spec or {}).get("code") or "").strip()
    for prefix, label in _NORM_CODE_PREFIX_FALLBACK.items():
        if norm_code.startswith(prefix):
            return f"{label} · {equipment}" if equipment else label
    work_name = _resolve_work_name(wt_code, norm_code)
    return f"{work_name} · {equipment}" if equipment and equipment not in work_name.lower() else work_name


def _backfill_work_type_norm_names() -> None:
    try:
        rows = query("SELECT key, value FROM equipment_norms_config WHERE category = 'work_types'")
    except Exception:
        return
    updates: list[tuple[str, str]] = []
    for row in rows:
        key = row.get("key") if isinstance(row, dict) else row[0]
        value = row.get("value") if isinstance(row, dict) else row[1]
        if isinstance(key, str):
            try:
                key = json.loads(key)
            except Exception:
                key = {}
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except Exception:
                value = {}
        if not isinstance(key, dict) or not isinstance(value, dict):
            continue
        if str(value.get("norm_name") or "").strip():
            continue
        wt_code = str(key.get("work_type_code") or "").strip()
        if not wt_code:
            continue
        patched = dict(value)
        patched["norm_name"] = _resolve_norm_name(key.get("equipment_type"), wt_code, value)
        updates.append((json.dumps(patched, ensure_ascii=False), json.dumps(key, ensure_ascii=False)))
    if not updates:
        return
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                for value_json, key_json in updates:
                    cur.execute(
                        """
                        UPDATE equipment_norms_config
                        SET value = %s::jsonb, updated_at = NOW(), updated_by = COALESCE(updated_by, 'norm_name_backfill')
                        WHERE category = 'work_types' AND key = %s::jsonb
                        """,
                        (value_json, key_json),
                    )
    finally:
        conn.close()


@router.get("/settings/norms")
def get_settings_norms():
    """Возвращает все нормы, сгруппированные по 4 категориям."""
    try:
        _ensure_settings_tables()
        _seed_norms_if_empty()
        _backfill_work_type_norm_names()
    except Exception:
        pass
    data = load_norms_from_db()
    productivity_flags = _work_type_productivity_flags([wt for (_, wt) in data["work_types"].keys()])
    work_types = [
        {
            "equipment_type": et,
            "work_type_code": wt,
            "name": _resolve_work_name(wt, spec.get("code")),
            "norm_name": _resolve_norm_name(et, wt, spec),
            "norm": float(spec.get("norm") or 0),
            "unit": spec.get("unit"),
            "code": spec.get("code"),
            "productivity_enabled": productivity_flags.get(wt, True),
        }
        for (et, wt), spec in sorted(data["work_types"].items())
    ]
    sand_pit = [
        {"section": sec, "trips": tpl[0], "m3_per_trip": tpl[1]}
        for sec, tpl in sorted(data["sand_pit"].items())
    ]
    sand_stockpile = [
        {"section": sec, "trips": tpl[0], "m3_per_trip": tpl[1]}
        for sec, tpl in sorted(data["sand_stockpile"].items())
    ]
    generic = {"norm_m3_per_shift": float(data["generic_truck_norm"])}
    work_options = query(
        """
        SELECT id::text AS id,
               code,
               name,
               default_unit,
               analytics_tag,
               COALESCE(productivity_enabled, true) AS productivity_enabled
        FROM work_types
        WHERE COALESCE(is_active, true) IS TRUE
        ORDER BY lower(name), code
        """
    )
    equipment_types = sorted({str(key[0] or '').strip() for key in data["work_types"].keys() if str(key[0] or '').strip()})
    for fallback in ("экскаватор", "бульдозер", "автогрейдер", "каток", "самосвал"):
        if fallback not in equipment_types:
            equipment_types.append(fallback)
    return {
        "work_types": work_types,
        "work_options": work_options,
        "equipment_types": equipment_types,
        "sand_pit": sand_pit,
        "sand_stockpile": sand_stockpile,
        "generic": generic,
    }


