@router.patch("/settings/norms")
def patch_settings_norms(body: NormsPatchBody, _manager=Depends(require_settings_manager)):
    """Частичное обновление норм. Принимает любой набор из 4 секций."""
    try:
        _ensure_settings_tables()
    except Exception:
        pass
    updated_by = body.updated_by or "web"
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                if body.work_types is not None:
                    submitted_keys: list[dict] = []
                    normalized_work_rows: list[tuple[dict, dict, dict]] = []
                    for row in body.work_types:
                        et = (row.get("equipment_type") or "").strip().lower()
                        raw_codes = row.get("work_type_codes")
                        if isinstance(raw_codes, list):
                            work_codes = [str(code or "").strip() for code in raw_codes]
                        else:
                            work_codes = [str(row.get("work_type_code") or "").strip()]
                        work_codes = [code for code in dict.fromkeys(work_codes) if code]
                        if not et or not work_codes:
                            continue
                        for wt in work_codes:
                            key = {"equipment_type": et, "work_type_code": wt}
                            value = {
                                "norm_name": str(row.get("norm_name") or "").strip() or _resolve_norm_name(et, wt, row),
                                "norm": float(row.get("norm") or 0),
                                "unit": row.get("unit") or "м³",
                                "code": row.get("code") or "",
                            }
                            submitted_keys.append(key)
                            normalized_work_rows.append((row, key, value))
                    cur.execute("SELECT key FROM equipment_norms_config WHERE category = 'work_types'")
                    for existing_key_row in cur.fetchall():
                        existing_key = existing_key_row[0]
                        if isinstance(existing_key, str):
                            try:
                                existing_key = json.loads(existing_key)
                            except Exception:
                                existing_key = {}
                        if existing_key not in submitted_keys:
                            cur.execute(
                                "DELETE FROM equipment_norms_config WHERE category = 'work_types' AND key = %s::jsonb",
                                (json.dumps(existing_key, ensure_ascii=False),),
                            )
                    for row, key, value in normalized_work_rows:
                        cur.execute(
                            """
                            INSERT INTO equipment_norms_config (category, key, value, updated_at, updated_by)
                            VALUES ('work_types', %s, %s, NOW(), %s)
                            ON CONFLICT (category, key) DO UPDATE
                              SET value = EXCLUDED.value,
                                  updated_at = NOW(),
                                  updated_by = EXCLUDED.updated_by
                            """,
                            (json.dumps(key, ensure_ascii=False), json.dumps(value, ensure_ascii=False), updated_by),
                        )
                        if "productivity_enabled" in row:
                            cur.execute(
                                """
                                UPDATE work_types
                                SET productivity_enabled = %s
                                WHERE code = %s
                                """,
                                (bool(row.get("productivity_enabled")), key["work_type_code"]),
                            )
                for cat, rows in (("sand_pit", body.sand_pit), ("sand_stockpile", body.sand_stockpile)):
                    if rows is None:
                        continue
                    for row in rows:
                        sec = row.get("section")
                        if sec is None:
                            continue
                        try:
                            sec = int(sec)
                        except (TypeError, ValueError):
                            continue
                        key = {"section": sec}
                        value = {
                            "trips": int(row.get("trips") or 0),
                            "m3_per_trip": float(row.get("m3_per_trip") or 0),
                        }
                        cur.execute(
                            """
                            INSERT INTO equipment_norms_config (category, key, value, updated_at, updated_by)
                            VALUES (%s, %s, %s, NOW(), %s)
                            ON CONFLICT (category, key) DO UPDATE
                              SET value = EXCLUDED.value,
                                  updated_at = NOW(),
                                  updated_by = EXCLUDED.updated_by
                            """,
                            (cat, json.dumps(key), json.dumps(value), updated_by),
                        )
                if body.generic is not None:
                    key = {"name": "truck_norm"}
                    value = {"norm_m3_per_shift": float(body.generic.get("norm_m3_per_shift") or 0)}
                    cur.execute(
                        """
                        INSERT INTO equipment_norms_config (category, key, value, updated_at, updated_by)
                        VALUES ('generic', %s, %s, NOW(), %s)
                        ON CONFLICT (category, key) DO UPDATE
                          SET value = EXCLUDED.value,
                              updated_at = NOW(),
                              updated_by = EXCLUDED.updated_by
                        """,
                        (json.dumps(key), json.dumps(value), updated_by),
                    )
    finally:
        conn.close()
    # Обновляем in-memory кэш, чтобы следующий запрос /equipment-productivity уже видел изменения.
    _refresh_norms()
    _invalidate_dashboard_response_cache("settings_norms")
    return {"ok": True}


@router.get("/settings/compaction-coefficients")
def get_settings_compaction_coefficients(_user=Depends(current_user)):
    """Owner-facing Купл rules (material/work) for DiM/MStroy/General reports."""
    rows = _load_compaction_coefficient_rules()
    objects = query(
        """
        SELECT o.object_code AS code, o.name, ot.code AS object_type_code, ot.name AS object_type_name
        FROM objects o
        JOIN object_types ot ON ot.id = o.object_type_id
        WHERE o.is_active IS NOT FALSE AND ot.is_active IS NOT FALSE
        ORDER BY ot.sort_order NULLS LAST, ot.name, o.name, o.object_code
        """
    )
    works = query(
        """
        SELECT code, name, analytics_tag
        FROM work_types
        WHERE is_active IS NOT FALSE
        ORDER BY COALESCE(analytics_tag, ''), name, code
        """
    )
    object_types = query(
        """
        SELECT code, name
        FROM object_types
        WHERE is_active IS NOT FALSE
        ORDER BY sort_order NULLS LAST, name
        """
    )
    tags = query(
        """
        SELECT name
        FROM work_analytics_tags
        WHERE is_active IS TRUE
        ORDER BY name
        """
    )
    return {
        "rows": rows,
        "objects": objects,
        "object_types": object_types,
        "works": works,
        "tags": tags,
    }


@router.put("/settings/compaction-coefficients")
def save_settings_compaction_coefficients(body: CompactionCoefficientsPatchBody, _manager=Depends(require_settings_manager)):
    _ensure_settings_tables()
    updated_by = body.updated_by or getattr(_manager, 'username', None) or 'web'
    normalized = []
    for idx, row in enumerate(body.rows[:200]):
        rule = _normalize_compaction_rule(row.model_dump())
        if float(rule.get('coefficient') or 0) < 1:
            raise HTTPException(status_code=400, detail='Купл должен быть не меньше 1: вводится как материал / работа')
        rule['sort_order'] = idx
        normalized.append(rule)
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("DELETE FROM equipment_norms_config WHERE category = 'compaction_coefficients'")
                for rule in normalized:
                    cur.execute(
                        """
                        INSERT INTO equipment_norms_config (category, key, value, updated_at, updated_by)
                        VALUES ('compaction_coefficients', %s, %s, NOW(), %s)
                        """,
                        (json.dumps({'id': rule['id']}), json.dumps(rule, ensure_ascii=False), updated_by),
                    )
    finally:
        conn.close()
    _invalidate_dashboard_response_cache("compaction_coefficients")
    return {"ok": True, "rows": normalized}


# ── Settings: haul distances ──────────────────────────────────────────────

def _ensure_haul_distance_table() -> None:
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS section_quarry_haul_distances (
                        section_code TEXT NOT NULL REFERENCES construction_sections(code) ON DELETE CASCADE,
                        quarry_object_id UUID NOT NULL REFERENCES objects(id) ON DELETE CASCADE,
                        distance_km NUMERIC,
                        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        updated_by TEXT,
                        PRIMARY KEY (section_code, quarry_object_id)
                    )
                    """
                )
                cur.execute(
                    """
                    CREATE INDEX IF NOT EXISTS idx_section_quarry_haul_distances_quarry
                    ON section_quarry_haul_distances(quarry_object_id)
                    """
                )
    finally:
        conn.close()


def _ensure_material_movement_haul_distance_columns() -> None:
    global _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_READY
    required_columns = ("haul_distance_km", "haul_distance_source")
    if _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_READY:
        return
    if all(_wip_column_exists("material_movements", column) for column in required_columns):
        _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_READY = True
        return
    with _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_LOCK:
        if _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_READY:
            return
        _wip_column_exists.cache_clear()
        missing_columns = [
            column
            for column in required_columns
            if not _wip_column_exists("material_movements", column)
        ]
        if not missing_columns:
            _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_READY = True
            return
        conn = get_conn()
        try:
            with conn:
                with conn.cursor() as cur:
                    cur.execute("SET LOCAL lock_timeout = '2s'")
                    cur.execute("SET LOCAL statement_timeout = '30s'")
                    if "haul_distance_km" in missing_columns:
                        cur.execute("""
                            ALTER TABLE material_movements
                            ADD COLUMN IF NOT EXISTS haul_distance_km NUMERIC
                        """)
                    if "haul_distance_source" in missing_columns:
                        cur.execute("""
                            ALTER TABLE material_movements
                            ADD COLUMN IF NOT EXISTS haul_distance_source TEXT
                        """)
        finally:
            conn.close()
    _wip_column_exists.cache_clear()
    _MATERIAL_MOVEMENT_HAUL_DISTANCE_COLUMNS_READY = True


def _ensure_object_map_points_table() -> None:
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS object_map_points (
                        object_id UUID PRIMARY KEY REFERENCES objects(id) ON DELETE CASCADE,
                        latitude DOUBLE PRECISION,
                        longitude DOUBLE PRECISION,
                        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        updated_by TEXT,
                        CONSTRAINT object_map_points_lat_check
                          CHECK (latitude IS NULL OR (latitude >= -90 AND latitude <= 90)),
                        CONSTRAINT object_map_points_lng_check
                          CHECK (longitude IS NULL OR (longitude >= -180 AND longitude <= 180)),
                        CONSTRAINT object_map_points_pair_check
                          CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude IS NOT NULL AND longitude IS NOT NULL))
                    )
                    """
                )
    finally:
        conn.close()


def _settings_sections() -> list[dict]:
    rows = query(
        """
        SELECT code, name, sort_order
        FROM construction_sections
        WHERE is_active = true
        ORDER BY sort_order NULLS LAST, code
        """
    )
    return [
        {"code": r["code"], "name": r["name"], "sort_order": r["sort_order"]}
        for r in rows
    ]


def _borrow_pits() -> list[dict]:
    _ensure_object_map_points_table()
    rows = query(
        """
        SELECT o.id::text AS id,
               o.object_code AS code,
               o.name,
               omp.latitude,
               omp.longitude
        FROM objects o
        JOIN object_types ot ON ot.id = o.object_type_id
        LEFT JOIN object_map_points omp ON omp.object_id = o.id
        WHERE o.is_active = true
          AND ot.code = 'BORROW_PIT'
        ORDER BY o.name, o.object_code
        """
    )
    return [
        {
            "id": r["id"],
            "code": r["code"],
            "name": r["name"],
            "latitude": float(r["latitude"]) if r.get("latitude") is not None else None,
            "longitude": float(r["longitude"]) if r.get("longitude") is not None else None,
        }
        for r in rows
    ]


def _daily_report_template_path() -> Path:
    here = Path(__file__).resolve()
    candidates = [
        REPORT_TEMPLATE_DIR / REPORT_TEMPLATE_FILENAME,
        here.parent / "public_templates" / REPORT_TEMPLATE_FILENAME,
        here.parent.parent / "frontend" / "public" / "templates" / REPORT_TEMPLATE_FILENAME,
        Path("/opt/vsm/vsm-dashboard/frontend/public/templates") / REPORT_TEMPLATE_FILENAME,
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return candidates[0]


def _daily_report_word_instruction_path() -> Path:
    candidates: list[Path] = []
    env_path = os.getenv("VSM_DAILY_REPORT_WORD_INSTRUCTION")
    if env_path:
        candidates.append(Path(env_path).expanduser())
    candidates.extend([
        DAILY_REPORT_WORD_INSTRUCTION_CONTAINER_PATH,
        Path(__file__).resolve().parent.parent / "frontend" / "public" / "templates" / "daily_report_shift_review_instructions.docx",
        Path("/opt/vsm/vsm-dashboard/frontend/public/templates/daily_report_shift_review_instructions.docx"),
    ])
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return candidates[0]


def _validate_daily_report_word_instruction_upload(filename: str, contents: bytes) -> None:
    name = (filename or "").strip()
    if not name.lower().endswith(".docx"):
        raise HTTPException(status_code=400, detail="Загрузите файл инструкции в формате .docx")
    if not contents:
        raise HTTPException(status_code=400, detail="Файл инструкции пустой")
    if len(contents) > DAILY_REPORT_WORD_INSTRUCTION_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Файл инструкции слишком большой")
    if not contents.startswith(b"PK\x03\x04"):
        raise HTTPException(status_code=400, detail="Файл не похож на DOCX")
    try:
        with ZipFile(BytesIO(contents)) as archive:
            names = set(archive.namelist())
            if "[Content_Types].xml" not in names or "word/document.xml" not in names:
                raise HTTPException(status_code=400, detail="В DOCX не найдена структура Word-документа")
            bad_member = archive.testzip()
            if bad_member:
                raise HTTPException(status_code=400, detail=f"DOCX поврежден: {bad_member}")
    except BadZipFile as exc:
        raise HTTPException(status_code=400, detail="Файл не является валидным DOCX") from exc


def _apply_file_owner_mode(path: Path, *, uid: int, gid: int, mode: int) -> None:
    try:
        os.chown(path, uid, gid)
    except OSError:
        pass
    try:
        os.chmod(path, mode)
    except OSError:
        pass


def _replace_daily_report_word_instruction(contents: bytes, *, uploaded_by: str) -> tuple[Path, Optional[Path], datetime]:
    path = _daily_report_word_instruction_path()
    if path.exists() and path.is_dir():
        raise HTTPException(status_code=500, detail=f"Путь инструкции указывает на папку: {path}")
    updated_at = datetime.now(timezone.utc)
    timestamp = updated_at.strftime("%Y%m%dT%H%M%SZ")
    tmp_path = path.parent / f".{path.name}.tmp-{uuid.uuid4().hex}"
    backup_path: Optional[Path] = None
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        parent_stat = path.parent.stat()
        current_stat = path.stat() if path.exists() else None
        target_uid = parent_stat.st_uid if not current_stat or current_stat.st_uid == 0 else current_stat.st_uid
        target_gid = parent_stat.st_gid if not current_stat or current_stat.st_gid == 0 else current_stat.st_gid
        target_mode = (current_stat.st_mode & 0o777) if current_stat else 0o664
        with open(tmp_path, "wb") as handle:
            handle.write(contents)
            handle.flush()
            os.fsync(handle.fileno())
        if path.exists():
            DAILY_REPORT_WORD_INSTRUCTION_BACKUP_DIR.mkdir(parents=True, exist_ok=True)
            _apply_file_owner_mode(DAILY_REPORT_WORD_INSTRUCTION_BACKUP_DIR, uid=target_uid, gid=target_gid, mode=0o775)
            clean_user = re.sub(r"[^A-Za-z0-9_.-]+", "_", uploaded_by or "web").strip("._") or "web"
            backup_path = DAILY_REPORT_WORD_INSTRUCTION_BACKUP_DIR / f"{path.stem}-{timestamp}-{clean_user}{path.suffix}"
            shutil.copy2(path, backup_path)
            _apply_file_owner_mode(backup_path, uid=target_uid, gid=target_gid, mode=0o664)
        os.replace(tmp_path, path)
        _apply_file_owner_mode(path, uid=target_uid, gid=target_gid, mode=target_mode)
    except PermissionError as exc:
        raise HTTPException(
            status_code=500,
            detail="Каталог инструкции недоступен для записи. Проверьте bind-mount /app/public_templates.",
        ) from exc
    except OSError as exc:
        raise HTTPException(status_code=500, detail=f"Не удалось сохранить инструкцию: {exc}") from exc
    finally:
        try:
            if tmp_path.exists():
                tmp_path.unlink()
        except OSError:
            pass
    return path, backup_path, updated_at


def _format_pk_excel(value) -> str:
    try:
        n = round(float(value), 2)
    except (TypeError, ValueError):
        return ""
    pk = int(n // 100)
    plus = round(n - pk * 100, 2)
    if plus >= 99.995:
        pk += 1
        plus = 0.0
    if abs(plus - round(plus)) < 0.005:
        plus_text = f"{int(round(plus)):02d}"
    else:
        plus_text = f"{plus:05.2f}".replace(".", ",").rstrip("0").rstrip(",")
    return f"ПК{pk}+{plus_text}"


def _format_pk_range_excel(pk_start, pk_end, raw_text: Optional[str] = None) -> str:
    raw = str(raw_text or "").strip()
    if raw:
        return raw
    start = _format_pk_excel(pk_start)
    end = _format_pk_excel(pk_end)
    if start and end and start != end:
        return f"{start} - {end}"
    return start or end


def _float_or_none(value):
    try:
        return float(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def _reference_comment_join(parts: list[str]) -> str:
    return "; ".join(part for part in parts if part)


def _reference_pile_key(value: Optional[str]) -> str:
    text = str(value or "").strip().upper().replace(" ", "")
    text = text.replace("Н", "N").replace("Т", "T")
    match = re.search(r"(\d+(?:_\d+)?[NT])", text)
    return match.group(1) if match else text


def _reference_pile_display(value: Optional[str]) -> str:
    raw = str(value or "").strip().replace("N", "Н").replace("T", "Т")
    return re.sub(r"\s+", "", raw).strip()


def _reference_pile_key_from_object(code: Optional[str], label: Optional[str]) -> str:
    code_text = str(code or "").upper().replace("Н", "N").replace("Т", "T")
    code_match = re.search(r"^PF[PT]_([0-9_]+[NT])$", code_text)
    if code_match:
        return _reference_pile_key(code_match.group(1))
    label_text = str(label or "").upper().replace("Н", "N").replace("Т", "T")
    label_match = re.search(r"(\d+(?:_\d+)?\s*[NT])", label_text)
    return _reference_pile_key(label_match.group(1)) if label_match else ""


def _reference_object_group_order(type_code: Optional[str]) -> int:
    return {
        "TEMP_ROAD": 10,
        "MAIN_TRACK": 20,
        "PILE_FIELD": 30,
        "PILE_COMPLEX": 30,
        "PILE_DRIVING_PAD": 30,
        "PIPE": 40,
        "ISSO_ACCESS": 50,
        "TECH_ROAD": 60,
        "SERVICE_ROAD": 70,
        "STATION_TRACK": 80,
    }.get(type_code or "", 90)


def _reference_comment_number(row: dict, key: str) -> Optional[float]:
    """Extract a numeric `key=value` marker from pile_fields.comment."""
    comment = str(row.get("comment") or "")
    match = re.search(rf"(?:^|[;\s]){re.escape(key)}\s*=\s*(-?\d+(?:[\.,]\d+)?)", comment, flags=re.IGNORECASE)
    if not match:
        return None
    try:
        return float(match.group(1).replace(",", "."))
    except (TypeError, ValueError):
        return None


def _reference_pile_catalog_status(row: dict) -> str:
    """Return normalized catalogue status for dashboard/reference suggestions."""
    explicit = str(row.get("catalog_status") or "").strip().lower()
    if explicit in {"excluded", "superseded", "исключен", "исключено", "заменен", "заменено"} or explicit.startswith("исключ"):
        return "excluded"
    comment = str(row.get("comment") or "").lower()
    if re.search(r"status\s*=\s*исключ", comment) or "статус=исключ" in comment:
        return "excluded"
    return "active"


def _reference_pile_driven_count(row: dict) -> float:
    """Driven count used for suggestion filtering without mutating production facts."""
    candidates = [_float_or_none(row.get("fact_count")) or 0.0]
    # The 29.05.2026 catalogue carries actual driven trial-pile counts in comments.
    # Use them for hiding completed suggestions, but do not insert/change facts from them.
    driven_structured = _float_or_none(row.get("driven_pile_count"))
    if row.get("field_type") == "test" and driven_structured is not None:
        candidates.append(driven_structured)
    driven_trial = _reference_comment_number(row, "driven_trial")
    if row.get("field_type") == "test" and driven_trial is not None:
        candidates.append(driven_trial)
    return max(candidates)


def _reference_pile_remaining_count(row: dict) -> float:
    planned = _float_or_none(row.get("pile_count")) or 0.0
    remaining = planned - _reference_pile_driven_count(row)
    return max(0.0, remaining)


def _reference_pile_is_offerable(row: dict) -> bool:
    if _reference_pile_catalog_status(row) == "excluded":
        return False
    return _reference_pile_remaining_count(row) > 0


def _reference_pile_comment(row: dict) -> str:
    kind = "Пробные сваи" if row.get("field_type") == "test" else "Основные сваи"
    details = [kind]
    if row.get("pile_type"):
        details.append(f"марка свай: {row.get('pile_type')}")
    if row.get("pile_count") is not None:
        details.append(f"проектное количество: {row.get('pile_count')}")
    driven = _reference_pile_driven_count(row)
    if driven:
        details.append(f"погружено: {driven:g}")
    if row.get("pile_count") is not None:
        details.append(f"остаток: {_reference_pile_remaining_count(row):g}")
    if row.get("dynamic_test_count") is not None:
        details.append(f"динамические испытания: {row.get('dynamic_test_count')}")
    return _reference_comment_join(details)


def _reference_work_group_label(row: dict) -> str:
    code = str(row.get("code") or "")
    group = str(row.get("work_group") or "").lower()
    tag = str(row.get("analytics_tag") or "").lower()
    name = str(row.get("name") or "").lower()
    source = " ".join([tag, name])
    if code.startswith("PIPE_ARRANGEMENT_"):
        return "Трубы на временных притрассовых дорогах"
    if group == "piles" or "сва" in source or "наголов" in source:
        return "Свайные работы"
    if group == "pipe_temp_road":
        return "ИССО и сопутствующие работы"
    if "геотекст" in source or "ростверк" in source:
        return "Геосинтетика"
    if "пес" in source or "насып" in source or "замена" in source or "обочин" in source:
        return "Песок и земляное полотно"
    if "щпс" in source or "щпгс" in source or "щеб" in source or "пгс" in source or "зс" in source:
        return "Щебень, ЩПС и ПГС"
    if "выем" in source or "выторф" in source or "прс" in source or "раститель" in source or "грунт" in source:
        return "Земляные работы"
    if "кювет" in source or "канава" in source:
        return "Водоотвод"
    if "планиров" in source:
        return "Планировка"
    if "асфальт" in source or "покрыт" in source:
        return "Дорожная одежда"
    if "перемещ" in source or "погруз" in source:
        return "Перемещение материалов"
    return "Прочие работы"


def _reference_work_group_order(group_label: str) -> int:
    return {
        "Земляные работы": 10,
        "Песок и земляное полотно": 20,
        "Щебень, ЩПС и ПГС": 30,
        "Геосинтетика": 40,
        "Водоотвод": 50,
        "Планировка": 60,
        "Дорожная одежда": 70,
        "Свайные работы": 80,
        "Трубы на временных притрассовых дорогах": 90,
        "ИССО и сопутствующие работы": 100,
        "Перемещение материалов": 110,
        "Прочие работы": 900,
    }.get(group_label, 900)




def _reference_object_group_title(type_code: Optional[str]) -> str:
    return {
        "TEMP_ROAD": "1. Временные притрассовые дороги",
        "MAIN_TRACK": "2. Земляное полотно ОХ",
        "PILE_COMPLEX": "3. Свайные поля, стартовые площадки и проезды",
        "PILE_FIELD": "3. Свайные поля, стартовые площадки и проезды",
        "PILE_DRIVING_PAD": "3. Свайные поля, стартовые площадки и проезды",
        "PIPE": "4. ПЖБТ",
        "ISSO_ACCESS": "5. Проезды и площадки ИССО",
        "TECH_ROAD": "6. Технологические проезды",
        "SERVICE_ROAD": "7. Содержание",
        "STATION_TRACK": "8. Станционные пути",
    }.get(type_code or "", "11. Прочие объекты без набора работ")


def _reference_object_type_label(type_code: Optional[str], fallback: Optional[str]) -> str:
    return {
        "TEMP_ROAD": "Временная притрассовая дорога",
        "MAIN_TRACK": "Сегмент основного хода",
        "PILE_FIELD": "Участок усиления",
        "PILE_DRIVING_PAD": "Стартовая площадка погружения свай",
        "TECH_ROAD": "Технологический проезд",
        "PIPE": "Водопропускная труба ПЖБТ",
        "ISSO_ACCESS": "Площадка и проезд к ИССО",
        "BRIDGE": "Мост",
        "OVERPASS": "Путепровод",
        "SERVICE_ROAD": "Содержание",
        "STATION_TRACK": "Станционные пути",
        "BORROW_PIT": "Карьер",
        "STOCKPILE": "Накопитель",
    }.get(type_code or "", fallback or type_code or "Объект")

def _reference_pipe_pk_from_code(code: Optional[str]) -> Optional[float]:
    match = re.search(r"PIPE_ARRANGEMENT_(\d+)", str(code or ""))
    return float(match.group(1)) if match else None


def _reference_section_temp_road_ranges(section_code: str) -> list[tuple[float, float]]:
    ranges = []
    for row in query(
        """
        SELECT LEAST(pk_start, pk_end) AS pk_start,
               GREATEST(pk_start, pk_end) AS pk_end
        FROM construction_section_versions csv
        JOIN construction_sections cs ON cs.id = csv.section_id
        WHERE csv.is_current = true
          AND csv.boundary_kind = 'temp_roads'
          AND cs.code = %s
          AND csv.pk_start IS NOT NULL
          AND csv.pk_end IS NOT NULL
        ORDER BY csv.pk_start
        """,
        (section_code,),
    ):
        start = _float_or_none(row.get("pk_start"))
        end = _float_or_none(row.get("pk_end"))
        if start is not None and end is not None:
            ranges.append((min(start, end), max(start, end)))
    return ranges


def _reference_pipe_allowed_for_section(code: Optional[str], ranges: list[tuple[float, float]]) -> bool:
    pk = _reference_pipe_pk_from_code(code)
    if pk is None:
        return True
    return any(start <= pk <= end for start, end in ranges)


def _section_reference_payload(section_code: str) -> dict:
    object_rows = query(
        """
        WITH seg AS (
            SELECT object_id,
                   MIN(LEAST(pk_start, pk_end)) AS pk_start,
                   MAX(GREATEST(pk_start, pk_end)) AS pk_end,
                   STRING_AGG(DISTINCT NULLIF(pk_raw_text, ''), '; ' ORDER BY NULLIF(pk_raw_text, '')) AS pk_raw_text
            FROM object_segments
            WHERE pk_start IS NOT NULL
              AND pk_end IS NOT NULL
            GROUP BY object_id
        ),
        main_bounds AS (
            SELECT cs.code AS section_code,
                   csv.pk_start,
                   csv.pk_end,
                   csv.pk_raw_text,
                   ROW_NUMBER() OVER (PARTITION BY cs.code ORDER BY csv.pk_start, csv.pk_end) AS section_part
            FROM construction_section_versions csv
            JOIN construction_sections cs ON cs.id = csv.section_id
            WHERE csv.is_current = true
              AND csv.boundary_kind = 'main'
        ),
        object_base AS (
            SELECT o.id,
                   o.object_code AS code,
                   o.name AS label,
                   ot.code AS type_code,
                   ot.name AS type_name,
                   seg.pk_start,
                   seg.pk_end,
                   seg.pk_raw_text,
                   CASE
                     WHEN o.object_code ~ '^MAIN_00([1-8])$' THEN 'UCH_' || substring(o.object_code FROM '^MAIN_00([1-8])$')
                     WHEN o.object_code = 'MAIN_031' THEN 'UCH_3'
                     WHEN o.object_code = 'MAIN_032' THEN 'UCH_3'
                     ELSE NULL
                   END AS main_section_code,
                   CASE
                     WHEN o.object_code IN ('ASP_2840','BRIDGE_282952') THEN 'UCH_3'
                     ELSE NULL
                   END AS section_override_code,
                   CASE
                     WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE') THEN 'temp_roads'
                     WHEN ot.code IN ('PILE_FIELD','ISSO_ACCESS','BRIDGE','OVERPASS','PIPE','PILE_DRIVING_PAD') THEN 'piles_pipes'
                     ELSE 'main'
                   END AS boundary_kind,
                   CASE
                     WHEN seg.pk_start IS NOT NULL AND seg.pk_end IS NOT NULL THEN (seg.pk_start + seg.pk_end) / 2.0
                     ELSE NULL
                   END AS midpoint
            FROM objects o
            JOIN object_types ot ON ot.id = o.object_type_id
            LEFT JOIN seg ON seg.object_id = o.id
            WHERE o.is_active = true
              AND ot.code NOT IN ('STOCKPILE','BORROW_PIT','PILE_FIELD','BRIDGE','OVERPASS')
        )
        SELECT ob.code,
               ob.label,
               ob.type_code,
               ob.type_name,
               COALESCE(CASE WHEN ob.type_code = 'MAIN_TRACK' THEN mb.pk_start ELSE ob.pk_start END, ob.pk_start) AS pk_start,
               COALESCE(CASE WHEN ob.type_code = 'MAIN_TRACK' THEN mb.pk_end ELSE ob.pk_end END, ob.pk_end) AS pk_end,
               COALESCE(CASE WHEN ob.type_code = 'MAIN_TRACK' THEN mb.pk_raw_text ELSE ob.pk_raw_text END, ob.pk_raw_text) AS pk_raw_text,
               CASE WHEN ob.type_code = 'MAIN_TRACK' THEN ob.main_section_code ELSE COALESCE(ob.section_override_code, sec.section_code) END AS section_code,
               isso.label AS related_isso_name,
               isso.pk_start AS related_isso_pk_start,
               isso.pk_end AS related_isso_pk_end,
               isso.pk_raw_text AS related_isso_pk_raw_text
        FROM object_base ob
        LEFT JOIN main_bounds mb
          ON ob.type_code = 'MAIN_TRACK'
         AND mb.section_code = ob.main_section_code
         AND (
             (ob.code = 'MAIN_031' AND mb.section_part = 1)
          OR (ob.code = 'MAIN_032' AND mb.section_part = 2)
          OR (ob.code NOT IN ('MAIN_031','MAIN_032'))
         )
        LEFT JOIN LATERAL (
            SELECT cs.code AS section_code
            FROM construction_section_versions csv
            JOIN construction_sections cs ON cs.id = csv.section_id
            WHERE csv.is_current = true
              AND csv.boundary_kind = ob.boundary_kind
              AND ob.midpoint IS NOT NULL
              AND ob.midpoint BETWEEN LEAST(csv.pk_start, csv.pk_end) AND GREATEST(csv.pk_start, csv.pk_end)
            ORDER BY cs.sort_order NULLS LAST, cs.code, csv.pk_start
            LIMIT 1
        ) sec ON TRUE
        LEFT JOIN LATERAL (
            SELECT io.name AS label,
                   iseg.pk_start,
                   iseg.pk_end,
                   iseg.pk_raw_text
            FROM objects io
            JOIN object_types iot ON iot.id = io.object_type_id
            JOIN seg iseg ON iseg.object_id = io.id
            WHERE io.is_active = true
              AND iot.code IN ('BRIDGE','OVERPASS','PIPE')
              AND ob.midpoint IS NOT NULL
            ORDER BY ABS(((iseg.pk_start + iseg.pk_end) / 2.0) - ob.midpoint), io.name
            LIMIT 1
        ) isso ON ob.type_code = 'ISSO_ACCESS'
        WHERE (CASE WHEN ob.type_code = 'MAIN_TRACK' THEN ob.main_section_code ELSE COALESCE(ob.section_override_code, sec.section_code) END) = %s
        ORDER BY CASE ob.type_code
                   WHEN 'TEMP_ROAD' THEN 10
                   WHEN 'MAIN_TRACK' THEN 20
                   WHEN 'PILE_DRIVING_PAD' THEN 30
                   WHEN 'TECH_ROAD' THEN 60
                   WHEN 'PIPE' THEN 40
                   WHEN 'ISSO_ACCESS' THEN 50
                   WHEN 'SERVICE_ROAD' THEN 70
                   WHEN 'STATION_TRACK' THEN 80
                   ELSE 90
                 END,
                 COALESCE(CASE WHEN ob.type_code = 'MAIN_TRACK' THEN mb.pk_start ELSE ob.pk_start END, ob.pk_start) NULLS LAST,
                 ob.label
        """,
        (section_code,),
    )
    pile_rows = query(
        f"""
        SELECT pf.field_code AS code,
               'Свайное поле ' || pf.field_code AS label,
               'PILE_FIELD' AS type_code,
               'Свайное поле' AS type_name,
               pf.pk_start,
               pf.pk_end,
               pf.pk_raw_text,
               pf.field_type,
               pf.pile_type,
               pf.pile_count,
               pf.dynamic_test_count,
               pf.comment,
               pf.catalog_status,
               pf.driven_pile_count,
               COALESCE(fact.fact_count, 0)::numeric AS fact_count,
               sec.section_code
        FROM pile_fields pf
        LEFT JOIN LATERAL (
            SELECT cs.code AS section_code
            FROM construction_section_versions csv
            JOIN construction_sections cs ON cs.id = csv.section_id
            WHERE csv.is_current = true
              AND csv.boundary_kind = 'piles_pipes'
              AND pf.pk_start IS NOT NULL
              AND pf.pk_end IS NOT NULL
              AND ((pf.pk_start + pf.pk_end) / 2.0) BETWEEN LEAST(csv.pk_start, csv.pk_end) AND GREATEST(csv.pk_start, csv.pk_end)
            ORDER BY cs.sort_order NULLS LAST, cs.code, csv.pk_start
            LIMIT 1
        ) sec ON TRUE
        LEFT JOIN LATERAL (
            SELECT SUM(COALESCE(seg.volume_segment, dwi.volume, 0)) AS fact_count
            FROM daily_work_item_segments seg
            JOIN daily_work_items dwi ON dwi.id = seg.daily_work_item_id
            JOIN work_types wt ON wt.id = dwi.work_type_id
            WHERE seg.pile_field_id = pf.id
              AND COALESCE(seg.is_demo, false) = false
              AND COALESCE(dwi.is_demo, false) = false
              AND {_approved_report_exists("dwi")}
              AND (
                (pf.field_type = 'main' AND wt.code = 'PILE_MAIN')
                OR (pf.field_type = 'test' AND wt.code = 'PILE_TRIAL')
              )
        ) fact ON TRUE
        WHERE COALESCE(pf.is_demo, false) = false
          AND pf.field_type IN ('main', 'test')
          AND sec.section_code = %s
        ORDER BY pf.pk_start NULLS LAST, pf.field_code, CASE pf.field_type WHEN 'main' THEN 0 ELSE 1 END
        """,
        (section_code,),
    )

    objects: list[dict] = []
    pile_object_rows: dict[str, list[dict]] = {}
    for r in object_rows:
        pk_start = _float_or_none(r.get("pk_start"))
        pk_end = _float_or_none(r.get("pk_end"))
        related_start = _float_or_none(r.get("related_isso_pk_start"))
        related_end = _float_or_none(r.get("related_isso_pk_end"))
        type_code = r.get("type_code")
        field_key = ""
        if type_code == "PILE_DRIVING_PAD":
            field_key = _reference_pile_key_from_object(r.get("code"), r.get("label"))
        row = {
            "type_code": type_code,
            "type_label": _reference_object_type_label(type_code, r.get("type_name")),
            "code": r.get("code") or "",
            "label": r.get("label"),
            "pk_start": _format_pk_excel(pk_start),
            "pk_end": _format_pk_excel(pk_end),
            "pk_range": _format_pk_range_excel(pk_start, pk_end, r.get("pk_raw_text")),
            "related_isso_name": r.get("related_isso_name") or "",
            "related_isso_pk_range": _format_pk_range_excel(related_start, related_end, r.get("related_isso_pk_raw_text")),
            "comment": "",
            "group_title": _reference_object_group_title(type_code),
            "sort_group": _reference_object_group_order(type_code),
            "sort_sub": 2 if type_code == "PILE_DRIVING_PAD" else 3 if type_code == "TECH_ROAD" else 0,
            "sort_pk": pk_start if pk_start is not None else 10**12,
            "group_sort_pk": pk_start if pk_start is not None else 10**12,
        }
        if field_key:
            pile_object_rows.setdefault(field_key, []).append(row)
        else:
            objects.append(row)

    pile_groups: dict[str, dict] = {}
    for r in pile_rows:
        if not _reference_pile_is_offerable(r):
            continue
        pk_start = _float_or_none(r.get("pk_start"))
        pk_end = _float_or_none(r.get("pk_end"))
        field_key = _reference_pile_key(r.get("code"))
        display = _reference_pile_display(r.get("code"))
        group = pile_groups.setdefault(field_key, {"display": display, "sort_pk": pk_start if pk_start is not None else 10**12, "rows": []})
        if pk_start is not None:
            group["sort_pk"] = min(group.get("sort_pk", 10**12), pk_start)
        is_test = r.get("field_type") == "test"
        label = f"Пробные сваи {display}" if is_test else f"Участок усиления {display}"
        group["rows"].append({
            "type_code": "PILE_FIELD",
            "type_label": "Участок усиления",
            "code": f"PF_{field_key}" if field_key else (r.get("code") or ""),
            "label": label,
            "pk_start": _format_pk_excel(pk_start),
            "pk_end": _format_pk_excel(pk_end),
            "pk_range": _format_pk_range_excel(pk_start, pk_end, r.get("pk_raw_text")),
            "related_isso_name": "",
            "related_isso_pk_range": "",
            "comment": _reference_pile_comment(r),
            "group_title": _reference_object_group_title("PILE_FIELD"),
            "sort_group": _reference_object_group_order("PILE_FIELD"),
            "sort_sub": 1,
            "sort_pk": pk_start if pk_start is not None else 10**12,
            "group_sort_pk": group.get("sort_pk", 10**12),
        })

    for field_key, related_rows in pile_object_rows.items():
        group = pile_groups.setdefault(field_key, {
            "display": _reference_pile_display(field_key),
            "sort_pk": min((row.get("sort_pk", 10**12) for row in related_rows), default=10**12),
            "rows": [],
        })
        for row in related_rows:
            row["group_sort_pk"] = group.get("sort_pk", row.get("sort_pk", 10**12))
            group["rows"].append(row)

    for group in pile_groups.values():
        rows = group.get("rows", [])
        if rows:
            group_sort_pk = group.get("sort_pk", 10**12)
            pk_range = next((row.get("pk_range") for row in rows if row.get("pk_range")), "")
            display = group.get("display") or next((row.get("label") for row in rows if row.get("label")), "")
            objects.append({
                "type_code": "PILE_COMPLEX",
                "type_label": "",
                "code": "",
                "label": f"Комплекс участка усиления {display}".strip(),
                "pk_start": "",
                "pk_end": "",
                "pk_range": pk_range,
                "related_isso_name": "",
                "related_isso_pk_range": "",
                "comment": "",
                "group_title": _reference_object_group_title("PILE_COMPLEX"),
                "row_role": "complex",
                "sort_group": _reference_object_group_order("PILE_COMPLEX"),
                "sort_sub": 0,
                "sort_pk": group_sort_pk,
                "group_sort_pk": group_sort_pk,
            })
        for row in rows:
            row["group_sort_pk"] = group.get("sort_pk", row.get("sort_pk", 10**12))
            objects.append(row)

    objects.sort(key=lambda row: (
        row.get("sort_group", 99),
        row.get("group_sort_pk", row.get("sort_pk", 10**12)),
        row.get("sort_sub", 0),
        row.get("sort_pk", 10**12),
        str(row.get("label") or ""),
    ))

    storage_rows = query(
        """
        WITH seg AS (
            SELECT object_id,
                   MIN(LEAST(pk_start, pk_end)) AS pk_start,
                   MAX(GREATEST(pk_start, pk_end)) AS pk_end,
                   STRING_AGG(DISTINCT NULLIF(pk_raw_text, ''), '; ' ORDER BY NULLIF(pk_raw_text, '')) AS pk_raw_text
            FROM object_segments
            WHERE pk_start IS NOT NULL
              AND pk_end IS NOT NULL
            GROUP BY object_id
        ),
        storage_base AS (
            SELECT o.id AS object_id,
                   o.object_code AS code,
                   o.name AS label,
                   ot.code AS type_code,
                   ot.name AS type_name,
                   seg.pk_start,
                   seg.pk_end,
                   seg.pk_raw_text,
                   COALESCE(
                     m.name,
                     CASE
                       WHEN position('щпгс' IN lower(o.name)) > 0 THEN 'ЩПГС'
                       WHEN position('пес' IN lower(o.name)) > 0 THEN 'Песок'
                       WHEN position('торф' IN lower(o.name)) > 0 THEN 'Торф'
                       WHEN position('щеб' IN lower(o.name)) > 0 THEN 'Щебень'
                       ELSE NULL
                     END
                   ) AS material_name,
                   CASE
                     WHEN o.object_code ~ 'UCH_([1-8])' THEN 'UCH_' || substring(o.object_code FROM 'UCH_([1-8])')
                     ELSE NULL
                   END AS code_section_code,
                   CASE
                     WHEN seg.pk_start IS NOT NULL AND seg.pk_end IS NOT NULL THEN (seg.pk_start + seg.pk_end) / 2.0
                     ELSE NULL
                   END AS midpoint
            FROM objects o
            JOIN object_types ot ON ot.id = o.object_type_id
            LEFT JOIN seg ON seg.object_id = o.id
            LEFT JOIN stockpiles st ON st.object_id = o.id
            LEFT JOIN materials m ON m.id = st.material_id
            WHERE o.is_active = true
              AND ot.code IN ('STOCKPILE','BORROW_PIT')
        )
        SELECT sb.*,
               COALESCE(sec.section_code, sb.code_section_code) AS section_code,
               h.distance_km
        FROM storage_base sb
        LEFT JOIN LATERAL (
            SELECT cs.code AS section_code
            FROM construction_section_versions csv
            JOIN construction_sections cs ON cs.id = csv.section_id
            WHERE csv.is_current = true
              AND csv.boundary_kind = 'temp_roads'
              AND sb.midpoint IS NOT NULL
              AND sb.midpoint BETWEEN LEAST(csv.pk_start, csv.pk_end) AND GREATEST(csv.pk_start, csv.pk_end)
            ORDER BY cs.sort_order NULLS LAST, cs.code, csv.pk_start
            LIMIT 1
        ) sec ON TRUE
        LEFT JOIN section_quarry_haul_distances h
          ON h.section_code = %s
         AND h.quarry_object_id = sb.object_id
        WHERE sb.type_code = 'BORROW_PIT'
           OR COALESCE(sec.section_code, sb.code_section_code) = %s
        ORDER BY CASE sb.type_code WHEN 'STOCKPILE' THEN 10 ELSE 20 END,
                 sb.pk_start NULLS LAST,
                 sb.label
        """,
        (section_code, section_code),
    )
    storage = []
    for r in storage_rows:
        pk_start = _float_or_none(r.get("pk_start"))
        pk_end = _float_or_none(r.get("pk_end"))
        type_code = r.get("type_code")
        type_label = _reference_object_type_label(type_code, "Накопитель" if type_code == "STOCKPILE" else "Карьер")
        pk_range = _format_pk_range_excel(pk_start, pk_end, r.get("pk_raw_text"))
        label = r.get("label") or type_label
        if type_code == "STOCKPILE" and r.get("material_name"):
            label = f"Накопитель {r.get('material_name')} {pk_range}".strip()
        comment_parts = [type_label]
        if type_code == "BORROW_PIT" and r.get("distance_km") is not None:
            comment_parts.append(f"плечо до участка: {_clean_report_number(float(r.get('distance_km') or 0))} км")
        storage.append({
            "type_code": type_code,
            "type_label": type_label,
            "code": r.get("code") or "",
            "label": label,
            "material": r.get("material_name") or "",
            "pk_start": _format_pk_excel(pk_start),
            "pk_end": _format_pk_excel(pk_end),
            "pk_range": pk_range,
            "comment": "; ".join(comment_parts),
            "group_title": "9. Накопители участка" if type_code == "STOCKPILE" else "10. Карьеры",
        })

    temp_road_ranges = _reference_section_temp_road_ranges(section_code)
    work_rows = query(
        """
        SELECT code, name, default_unit, work_group, analytics_tag,
               COALESCE(productivity_enabled, true) AS productivity_enabled,
               COALESCE(show_in_timeline, false) AS show_in_timeline
        FROM work_types
        WHERE is_active = true
        ORDER BY show_in_timeline DESC, analytics_tag NULLS LAST, name
        """
    )
    work_types = []
    for r in work_rows:
        if str(r.get("code") or "").startswith("PIPE_ARRANGEMENT_") and not _reference_pipe_allowed_for_section(r.get("code"), temp_road_ranges):
            continue
        group_label = _reference_work_group_label(r)
        work_types.append({
            "group": group_label,
            "code": r.get("code") or "",
            "label": r.get("name"),
            "unit": r.get("default_unit") or "",
            "analytics_tag": r.get("analytics_tag") or "",
            "comment": "Учитывается в производительности" if r.get("productivity_enabled") else "Справочная работа",
            "sort_group": _reference_work_group_order(group_label),
        })
    work_types.sort(key=lambda row: (row.get("sort_group", 900), str(row.get("analytics_tag") or ""), str(row.get("label") or "")))

    materials = [
        {
            "code": r.get("code") or "",
            "label": r.get("name"),
            "unit": r.get("default_unit") or "",
        }
        for r in query(
            """
            SELECT code, name, default_unit
            FROM materials
            ORDER BY CASE code WHEN 'SAND' THEN 0 WHEN 'COARSE_SAND' THEN 1 ELSE 2 END, name
            """
        )
    ]
    return {
        "objects": objects,
        "storage": storage,
        "work_types": work_types,
        "materials": materials,
    }

