def _clear_daily_template_sheet(ws) -> None:
    for merged in list(ws.merged_cells.ranges):
        ws.unmerge_cells(str(merged))
    if ws.max_row:
        ws.delete_rows(1, ws.max_row)


def _section_sheet_name(section: dict) -> str:
    section_code = str(section.get("code") or "").strip()
    match = re.search(r"(\d+)", section_code)
    suffix = match.group(1) if match else section_code.replace("_", "")
    return f"Участок {suffix}"[:31]


def _style_section_catalog_row(ws, row_idx: int, role: Optional[str] = None, *, header: bool = False, group: bool = False) -> None:
    role = "header" if header else "block" if group else role
    thin = Side(style="thin", color="D9D9D9")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    fills = {
        "header": "1F4E78",
        "block": "D9EAF7",
        "object": "EDF3F8",
        "complex": "E2F0D9",
        "material": "FFF2CC",
    }
    center_cols = {3, 5, 7}
    for cell in ws[row_idx]:
        cell.border = border
        centered = role in {"header", "block"} or cell.column in center_cols
        cell.alignment = Alignment(
            horizontal="center" if centered else None,
            vertical="center" if centered else "top",
            wrap_text=True,
        )
        fill = fills.get(role or "")
        if fill:
            cell.fill = PatternFill("solid", fgColor=fill)
        if role == "header":
            cell.font = Font(bold=True, color="FFFFFF")
        elif role in {"block", "object", "complex"}:
            cell.font = Font(bold=True, color="111827")
        elif role == "material":
            cell.font = Font(italic=True, color="111827")


def _write_section_catalog_header(ws, row_idx: int) -> int:
    for col_idx, label in enumerate(DAILY_TEMPLATE_SECTION_HEADERS, start=1):
        ws.cell(row=row_idx, column=col_idx, value=label)
    _style_section_catalog_row(ws, row_idx, header=True)
    return row_idx + 1


def _write_section_catalog_group(ws, row_idx: int, title: str) -> int:
    ws.cell(row=row_idx, column=1, value=title)
    ws.merge_cells(start_row=row_idx, start_column=1, end_row=row_idx, end_column=len(DAILY_TEMPLATE_SECTION_HEADERS))
    _style_section_catalog_row(ws, row_idx, group=True)
    return row_idx + 1


def _write_section_catalog_row(ws, row_idx: int, values: list[object], role: Optional[str] = None, outline_level: int = 1) -> int:
    for col_idx, value in enumerate(values, start=1):
        ws.cell(row=row_idx, column=col_idx, value="" if value is None else value)
    ws.row_dimensions[row_idx].outlineLevel = outline_level
    _style_section_catalog_row(ws, row_idx, role=role)
    return row_idx + 1


def _daily_template_dim_module():
    try:
        dim_path = str(DIM_PIPELINE_DIR)
        if dim_path not in sys.path:
            sys.path.insert(0, dim_path)
        import generate_dim_report as dim  # type: ignore
        return dim
    except Exception:
        return None


def _daily_template_work_reference_rows(payload: dict) -> list[dict]:
    work_by_code = {str(item.get("code") or ""): item for item in payload.get("work_types") or []}

    def visible_work_row(item: dict, *, fallback_label: str = "", fallback_unit: str = "", comment: str = "") -> dict:
        return {
            "label": item.get("label") or fallback_label,
            "unit": item.get("unit") or fallback_unit,
            "comment": comment or item.get("comment") or "",
            "code": str(item.get("code") or ""),
        }

    dim = _daily_template_dim_module()
    if dim is None:
        rows: list[dict] = []
        current_group = None
        for item in payload.get("work_types") or []:
            group = item.get("group") or "Прочие работы"
            if group != current_group:
                rows.append({"row_role": "complex", "type_label": group})
                current_group = group
            rows.append(visible_work_row(item))
        return rows

    type_sets = [
        ("TEMP_ROAD", "Временная притрассовая дорога", getattr(dim, "TEMP_ROAD_BASE_RULES", []), ""),
        ("MAIN_TRACK", "Сегмент основного хода / земляное полотно ОХ", getattr(dim, "MAIN_EARTHWORK_RULES", []), ""),
        ("PILE_FIELD_MAIN", "Участок усиления / свайное поле", getattr(dim, "PILE_FIELD_RULES", []), ""),
        ("PILE_DRIVING_PAD", "Стартовая площадка погружения свай", getattr(dim, "PILE_ACCESS_RULES", []), ""),
        ("PIPE", "ПЖБТ", getattr(dim, "PIPE_RULES", []), ""),
        ("ISSO_ACCESS", "Проезд и площадка к ИССО", getattr(dim, "ISSO_ACCESS_RULES", []), ""),
        ("TECH_ROAD", "Технологический проезд", getattr(dim, "STANDALONE_TECH_RULES", []), ""),
        ("SERVICE_ROAD", "Содержание дорог", getattr(dim, "SERVICE_ROAD_RULES", []), ""),
        ("STATION_TRACK", "Станционные пути", getattr(dim, "STATION_TRACK_RULES", []), ""),
        ("STOCKPILE", "Накопитель", [], "работы не раскрываются; показан как справочный объект/материальный пункт"),
        ("BORROW_PIT", "Карьер", [], "работы не раскрываются; показан как справочный источник материала/плечо доставки"),
    ]
    rows = []
    used_codes: set[str] = set()
    for type_code, type_name, rules, note in type_sets:
        rows.append({"row_role": "complex", "type_label": type_name, "comment": note})
        for code, display, unit in rules:
            if code:
                used_codes.add(str(code))
            db_row = work_by_code.get(str(code or ""), {})
            display_value = db_row.get("label") or display
            unit_value = db_row.get("unit") or unit
            raw_tag = db_row.get("analytics_tag") or "0"
            try:
                tag = dim.normalized_tag(raw_tag)
            except Exception:
                tag = raw_tag or "0"
            try:
                comment = dim.tag_explanation(code, display_value, tag) or "0"
            except Exception:
                comment = db_row.get("comment") or "0"
            rows.append(visible_work_row({"code": code or "", **db_row}, fallback_label=display_value, fallback_unit=unit_value, comment=comment))
    remaining = [item for item in payload.get("work_types") or [] if str(item.get("code") or "") not in used_codes]
    if remaining:
        rows.append({
            "row_role": "complex",
            "type_label": "Все остальные активные работы из БД",
            "comment": "Справочный общий список работ, которые не входят в типовые наборы выше.",
        })
        current_group = None
        for item in sorted(remaining, key=lambda row: (row.get("sort_group", 900), str(row.get("group") or ""), str(row.get("label") or ""))):
            group = item.get("group") or "Прочие работы"
            if group != current_group:
                rows.append({"row_role": "complex", "type_label": group})
                current_group = group
            rows.append(visible_work_row(item))
    return rows


def _populate_section_catalog_sheet(wb, section: dict) -> None:
    title = _section_sheet_name(section)
    if title in wb.sheetnames:
        ws = wb[title]
    else:
        ws = wb.create_sheet(title=title)
    _clear_daily_template_sheet(ws)
    ws.sheet_view.showGridLines = False
    ws.freeze_panes = "A2"
    ws.sheet_properties.tabColor = DAILY_TEMPLATE_SECTION_TAB_COLOR

    row = _write_section_catalog_header(ws, 1)
    payload = _section_reference_payload(str(section.get("code") or ""))

    objects_by_group: dict[str, list[dict]] = {title: [] for title in DAILY_TEMPLATE_SECTION_BLOCKS}
    for item in payload["objects"]:
        group = item.get("group_title") or _reference_object_group_title(item.get("type_code"))
        objects_by_group.setdefault(group, []).append(item)
    storage_by_group: dict[str, list[dict]] = {"9. Накопители участка": [], "10. Карьеры": []}
    for item in payload["storage"]:
        storage_by_group.setdefault(item.get("group_title") or "", []).append(item)

    for group_title in DAILY_TEMPLATE_SECTION_BLOCKS:
        row = _write_section_catalog_group(ws, row, group_title)
        if group_title in storage_by_group:
            for item in storage_by_group.get(group_title, []):
                row = _write_section_catalog_row(ws, row, [
                    item.get("type_label") or "",
                    item.get("label") or "",
                    item.get("pk_range") or "",
                    "",
                    "",
                    "",
                    "",
                    _reference_comment_join([item.get("material") or "", item.get("comment") or ""]),
                ], role="object")
            continue
        for item in objects_by_group.get(group_title, []):
            comment = _reference_comment_join([
                item.get("comment") or "",
                f"Связанное ИССО: {item.get('related_isso_name')}" if item.get("related_isso_name") else "",
                f"ПК ИССО: {item.get('related_isso_pk_range')}" if item.get("related_isso_pk_range") else "",
            ])
            row = _write_section_catalog_row(ws, row, [
                item.get("type_label") or "",
                item.get("label") or "",
                item.get("pk_range") or "",
                item.get("related_isso_name") or "",
                item.get("related_isso_pk_range") or "",
                "",
                "",
                comment,
            ], role=item.get("row_role") or "object")

    row = _write_section_catalog_group(ws, row, "12. Справочно: работы, присужденные типам объектов")
    row = _write_section_catalog_header(ws, row)
    for item in _daily_template_work_reference_rows(payload):
        if item.get("row_role") == "complex":
            row = _write_section_catalog_row(ws, row, [
                item.get("type_label") or "",
                "",
                "",
                "",
                "",
                "",
                "",
                item.get("comment") or "",
            ], role="complex")
            continue
        row = _write_section_catalog_row(ws, row, [
            "",
            "",
            "",
            "",
            "",
            item.get("label") or "",
            item.get("unit") or "",
            item.get("comment") or "",
        ])

    widths = [30, 72, 24, 42, 24, 54, 12, 80]
    for idx, width in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(idx)].width = width
    ws.auto_filter.ref = f"A1:{get_column_letter(len(DAILY_TEMPLATE_SECTION_HEADERS))}{ws.max_row}"


def _daily_template_boundary_kind_label(kind: object) -> str:
    key = str(kind or "main").strip() or "main"
    return DAILY_TEMPLATE_BOUNDARY_KIND_LABELS.get(key) or BOUNDARY_KINDS.get(key) or key


def _daily_template_boundary_rows() -> list[list[object]]:
    rows = query(
        """
        SELECT csv.boundary_kind,
               cs.name AS section_name,
               csv.pk_start,
               csv.pk_end,
               csv.pk_raw_text,
               csv.valid_from,
               csv.valid_to,
               csv.comment
        FROM construction_section_versions csv
        JOIN construction_sections cs ON cs.id = csv.section_id
        WHERE csv.is_current = true
          AND cs.is_active IS NOT FALSE
        ORDER BY CASE csv.boundary_kind
                   WHEN 'main' THEN 1
                   WHEN 'piles_pipes' THEN 2
                   WHEN 'temp_roads' THEN 3
                   ELSE 99
                 END,
                 cs.sort_order NULLS LAST,
                 cs.code,
                 csv.pk_start,
                 csv.pk_end
        """
    )
    return [
        [
            _daily_template_boundary_kind_label(row.get("boundary_kind")),
            row.get("section_name") or "",
            row.get("pk_start") if row.get("pk_start") is not None else "",
            row.get("pk_end") if row.get("pk_end") is not None else "",
            _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text")),
            row.get("valid_from") or "",
            row.get("valid_to") or "",
            row.get("comment") or "",
        ]
        for row in rows
    ]


def _update_daily_template_boundaries_sheet(wb) -> None:
    if "Границы" in wb.sheetnames:
        ws = wb["Границы"]
    else:
        ws = wb.create_sheet("Границы", min(3, len(wb.sheetnames)))
    _clear_daily_template_sheet(ws)
    ws.sheet_properties.tabColor = "8064A2"
    ws.sheet_view.showGridLines = False
    ws.freeze_panes = "A4"

    headers = DAILY_TEMPLATE_BOUNDARY_HEADERS
    rows = _daily_template_boundary_rows()
    body_rows = rows or [["Границы не загружены", "", "", "", "", "", "", "В БД нет активных границ"]]

    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(headers))
    title = ws.cell(1, 1, "Актуальные границы участков из БД")
    title.font = Font(bold=True, color="FFFFFF")
    title.fill = PatternFill("solid", fgColor="1F4E78")
    title.alignment = Alignment(horizontal="center", vertical="center")

    header_fill = PatternFill("solid", fgColor="D9EAF7")
    thin = Side(style="thin", color="D9D9D9")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    for col_idx, header in enumerate(headers, start=1):
        cell = ws.cell(3, col_idx, header)
        cell.font = Font(bold=True)
        cell.fill = header_fill
        cell.border = border
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    for row_idx, values in enumerate(body_rows, start=4):
        for col_idx, value in enumerate(values, start=1):
            cell = ws.cell(row_idx, col_idx, value)
            cell.border = border
            cell.alignment = Alignment(vertical="top", wrap_text=True)

    widths = {1: 34, 2: 32, 3: 14, 4: 14, 5: 32, 6: 14, 7: 14, 8: 44}
    for col_idx, width in widths.items():
        ws.column_dimensions[get_column_letter(col_idx)].width = width
    ws.auto_filter.ref = f"A3:{get_column_letter(len(headers))}{3 + len(body_rows)}"



def _write_help_row(ws, row_idx: int, name: object, description: object, *, header: bool = False, section: bool = False) -> int:
    ws.cell(row=row_idx, column=1, value=name)
    ws.cell(row=row_idx, column=2, value=description)
    thin = Side(style="thin", color="D7DDE8")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    for cell in ws[row_idx]:
        cell.border = border
        cell.alignment = Alignment(wrap_text=True, vertical="top")
    if header or section:
        fill = "DCE7F5" if section else "F3F4F6"
        for cell in ws[row_idx]:
            cell.fill = PatternFill("solid", fgColor=fill)
            cell.font = Font(bold=True, color="111827")
    return row_idx + 1


