@router.get("/settings/haul-distances")
def get_haul_distances(_user=Depends(current_user)):
    _ensure_haul_distance_table()
    _ensure_object_map_points_table()
    rows = query(
        """
        SELECT h.section_code,
               h.quarry_object_id::text AS quarry_object_id,
               h.distance_km,
               h.updated_at,
               h.updated_by,
               o.object_code AS quarry_code,
               o.name AS quarry_name
        FROM section_quarry_haul_distances h
        JOIN objects o ON o.id = h.quarry_object_id
        ORDER BY h.section_code, o.name, o.object_code
        """
    )
    return {
        "sections": _settings_sections(),
        "quarries": _borrow_pits(),
        "rows": [
            {
                "section_code": r["section_code"],
                "quarry_object_id": r["quarry_object_id"],
                "quarry_code": r["quarry_code"],
                "quarry_name": r["quarry_name"],
                "distance_km": float(r["distance_km"]) if r.get("distance_km") is not None else None,
                "updated_at": r["updated_at"].isoformat() if r.get("updated_at") else None,
                "updated_by": r["updated_by"],
            }
            for r in rows
        ],
    }


@router.put("/settings/quarries")
def put_quarry_coordinates(body: QuarryCoordinatesPatchBody, _manager=Depends(require_settings_manager)):
    _ensure_object_map_points_table()
    quarries = {r["id"] for r in _borrow_pits()}
    updated_by = body.updated_by or getattr(_manager, "username", None) or "web"

    normalized: list[tuple[str, float | None, float | None]] = []
    for row in body.rows:
        object_id = (row.id or "").strip()
        if object_id not in quarries:
            raise HTTPException(400, f"Unknown quarry id: {object_id}")
        lat = row.latitude
        lng = row.longitude
        if lat is None and lng is None:
            normalized.append((object_id, None, None))
            continue
        if lat is None or lng is None:
            raise HTTPException(400, "Для карьера нужно указать и широту, и долготу")
        lat_f = float(lat)
        lng_f = float(lng)
        if not (-90 <= lat_f <= 90):
            raise HTTPException(400, f"Некорректная широта для {object_id}")
        if not (-180 <= lng_f <= 180):
            raise HTTPException(400, f"Некорректная долгота для {object_id}")
        normalized.append((object_id, lat_f, lng_f))

    conn = get_conn()
    written = 0
    try:
        with conn:
            with conn.cursor() as cur:
                for object_id, lat, lng in normalized:
                    if lat is None and lng is None:
                        cur.execute("DELETE FROM object_map_points WHERE object_id = %s::uuid", (object_id,))
                        continue
                    cur.execute(
                        """
                        INSERT INTO object_map_points (object_id, latitude, longitude, updated_at, updated_by)
                        VALUES (%s::uuid, %s, %s, NOW(), %s)
                        ON CONFLICT (object_id) DO UPDATE
                          SET latitude = EXCLUDED.latitude,
                              longitude = EXCLUDED.longitude,
                              updated_at = NOW(),
                              updated_by = EXCLUDED.updated_by
                        """,
                        (object_id, lat, lng, updated_by),
                    )
                    written += 1
    finally:
        conn.close()
    return {"ok": True, "written": written}


@router.put("/settings/haul-distances")
def put_haul_distances(body: HaulDistancePatchBody, _manager=Depends(require_settings_manager)):
    _ensure_haul_distance_table()
    sections = {r["code"] for r in _settings_sections()}
    quarries = {r["id"] for r in _borrow_pits()}
    updated_by = body.updated_by or getattr(_manager, "username", None) or "web"

    conn = get_conn()
    written = 0
    normalized: list[tuple[str, str, float]] = []
    for row in body.rows:
        section_code = (row.section_code or "").strip()
        quarry_object_id = (row.quarry_object_id or "").strip()
        if section_code not in sections:
            raise HTTPException(400, f"Unknown section_code: {section_code}")
        if quarry_object_id not in quarries:
            raise HTTPException(400, f"Unknown quarry_object_id: {quarry_object_id}")
        distance = row.distance_km
        if distance is None or float(distance) <= 0:
            continue
        normalized.append((section_code, quarry_object_id, float(distance)))
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("DELETE FROM section_quarry_haul_distances")
                for section_code, quarry_object_id, distance in normalized:
                    cur.execute(
                        """
                        INSERT INTO section_quarry_haul_distances
                          (section_code, quarry_object_id, distance_km, updated_at, updated_by)
                        VALUES (%s, %s::uuid, %s, NOW(), %s)
                        ON CONFLICT (section_code, quarry_object_id) DO UPDATE
                          SET distance_km = EXCLUDED.distance_km,
                              updated_at = NOW(),
                              updated_by = EXCLUDED.updated_by
                        """,
                        (section_code, quarry_object_id, float(distance), updated_by),
                    )
                    written += 1
    finally:
        conn.close()
    _invalidate_dashboard_response_cache("haul_distances")
    return {"ok": True, "written": written}


# ── Settings: section boundaries ──────────────────────────────────────────

class SectionBoundaryRow(BaseModel):
    section_code: str
    pk_start: float
    pk_end: float
    pk_raw_text: Optional[str] = None
    comment: Optional[str] = None


class SectionBoundariesPatchBody(BaseModel):
    boundary_kind: str
    rows: list[SectionBoundaryRow]


@router.get("/settings/section-boundaries")
def get_section_boundaries():
    try:
        _ensure_settings_tables()
    except Exception:
        pass
    sections = query(
        """
        SELECT code, name, sort_order
        FROM construction_sections
        WHERE is_active = true OR code = 'UCH_3'
        ORDER BY sort_order NULLS LAST, code
        """
    )
    rows = query(
        """
        SELECT csv.id::text AS id,
               csv.boundary_kind,
               cs.code AS section_code,
               cs.name AS section_name,
               csv.pk_start,
               csv.pk_end,
               csv.pk_raw_text,
               csv.comment,
               csv.valid_from,
               csv.valid_to,
               csv.is_current
        FROM construction_section_versions csv
        JOIN construction_sections cs ON cs.id = csv.section_id
        WHERE csv.is_current = true
        ORDER BY csv.boundary_kind, cs.sort_order NULLS LAST, cs.code, csv.pk_start
        """
    )
    return {
        "boundary_kinds": [
            {"key": key, "label": label}
            for key, label in BOUNDARY_KINDS.items()
        ],
        "sections": [
            {"code": r["code"], "name": r["name"], "sort_order": r["sort_order"]}
            for r in sections
        ],
        "rows": [
            {
                "id": r["id"],
                "boundary_kind": r["boundary_kind"],
                "section_code": r["section_code"],
                "section_name": r["section_name"],
                "pk_start": float(r["pk_start"]),
                "pk_end": float(r["pk_end"]),
                "pk_raw_text": r["pk_raw_text"],
                "comment": r["comment"],
                "valid_from": r["valid_from"].isoformat() if r["valid_from"] else None,
                "valid_to": r["valid_to"].isoformat() if r["valid_to"] else None,
                "is_current": bool(r["is_current"]),
            }
            for r in rows
        ],
    }


@router.patch("/settings/section-boundaries")
def patch_section_boundaries(body: SectionBoundariesPatchBody, _manager=Depends(require_settings_manager)):
    try:
        _ensure_settings_tables()
    except Exception:
        pass
    kind = (body.boundary_kind or "").strip()
    if kind not in BOUNDARY_KINDS:
        raise HTTPException(400, f"boundary_kind must be one of {sorted(BOUNDARY_KINDS)}")
    if not body.rows:
        raise HTTPException(400, "rows must not be empty")

    section_rows = query("SELECT id, code FROM construction_sections WHERE is_active = true OR code = 'UCH_3'")
    section_by_code = {r["code"]: r["id"] for r in section_rows}

    normalized: list[dict] = []
    for row in body.rows:
        section_id = section_by_code.get(row.section_code)
        if not section_id:
            raise HTTPException(400, f"Unknown section_code: {row.section_code}")
        if row.pk_end < row.pk_start:
            raise HTTPException(400, f"pk_end must be >= pk_start for {row.section_code}")
        normalized.append({
            "section_id": section_id,
            "section_code": row.section_code,
            "pk_start": float(row.pk_start),
            "pk_end": float(row.pk_end),
            "pk_raw_text": row.pk_raw_text,
            "comment": row.comment,
        })

    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE construction_section_versions
                    SET is_current = false, valid_to = CURRENT_DATE
                    WHERE boundary_kind = %s AND is_current = true
                    """,
                    (kind,),
                )
                for row in normalized:
                    cur.execute(
                        """
                        INSERT INTO construction_section_versions
                          (section_id, valid_from, valid_to, pk_start, pk_end,
                           pk_raw_text, is_current, comment, boundary_kind)
                        VALUES (%s, CURRENT_DATE, NULL, %s, %s, %s, true, %s, %s)
                        """,
                        (
                            row["section_id"],
                            row["pk_start"],
                            row["pk_end"],
                            row["pk_raw_text"],
                            row["comment"],
                            kind,
                        ),
                    )
    finally:
        conn.close()
    _invalidate_dashboard_response_cache("section_boundaries")
    return {"ok": True, "boundary_kind": kind, "rows": len(normalized)}


