def _section_codes_from_body(section_codes: Optional[list[str]]) -> Optional[list[str]]:
    if not section_codes or "all" in section_codes:
        return None
    return _expand_sections(",".join(section_codes))


def _attachment_headers(filename_ascii: str, filename_utf8: str) -> dict[str, str]:
    quoted = urllib.parse.quote(filename_utf8)
    return {
        "Content-Disposition": (
            f"attachment; filename=\"{filename_ascii}\"; "
            f"filename*=UTF-8''{quoted}"
        )
    }


def _report_pipeline_env() -> dict[str, str]:
    env = os.environ.copy()
    if not env.get("TEMP_ROADS_DB_DSN"):
        user = env.get("DB_USER", "works_user")
        password = env.get("DB_PASSWORD", "")
        host = env.get("DB_HOST", "127.0.0.1")
        port = env.get("DB_PORT", "5433")
        db_name = env.get("DB_NAME", "works_db_v2")
        env["TEMP_ROADS_DB_DSN"] = f"postgresql://{user}:{password}@{host}:{port}/{db_name}"
    env.setdefault("DIM_REPORT_MEMORY_GUARD", "1")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_SOFT_RATIO", "0.76")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_HARD_RATIO", "0.84")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_ABORT_RATIO", "0.94")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_CHECK_INTERVAL_SECONDS", "0.5")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_SLEEP_SECONDS", "0.75")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_MAX_WAIT_SECONDS", "45")
    env.setdefault("DIM_REPORT_MEMORY_GUARD_ROW_INTERVAL", "75")
    return env


def _process_memory_kb(pid: int) -> int:
    try:
        status = Path(f"/proc/{pid}/status").read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return 0
    total = 0
    for line in status.splitlines():
        if line.startswith(("VmRSS:", "VmSwap:")):
            parts = line.split()
            if len(parts) >= 2:
                try:
                    total += int(parts[1])
                except ValueError:
                    pass
    return total


def _process_children(pid: int) -> list[int]:
    try:
        raw = Path(f"/proc/{pid}/task/{pid}/children").read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return []
    children: list[int] = []
    for part in raw.split():
        try:
            children.append(int(part))
        except ValueError:
            pass
    return children


def _process_tree_memory_kb(root_pid: int) -> int:
    total = 0
    seen: set[int] = set()
    stack = [root_pid]
    while stack:
        pid = stack.pop()
        if pid in seen:
            continue
        seen.add(pid)
        total += _process_memory_kb(pid)
        stack.extend(_process_children(pid))
    return total


def _read_report_pipeline_int_file(path: Path) -> Optional[int]:
    try:
        raw = path.read_text(encoding="utf-8", errors="ignore").strip()
    except OSError:
        return None
    if not raw or raw == "max":
        return None
    try:
        return int(raw)
    except ValueError:
        return None


def _report_pipeline_cgroup_memory_bytes() -> tuple[int, int]:
    candidates = (
        (Path("/sys/fs/cgroup/memory.current"), Path("/sys/fs/cgroup/memory.max")),
        (Path("/sys/fs/cgroup/memory/memory.usage_in_bytes"), Path("/sys/fs/cgroup/memory/memory.limit_in_bytes")),
    )
    for current_path, limit_path in candidates:
        current = _read_report_pipeline_int_file(current_path)
        limit = _read_report_pipeline_int_file(limit_path)
        if not current:
            continue
        if not limit or limit <= 0 or limit >= 1 << 60:
            return current, 0
        return current, limit
    return 0, 0


def _report_pipeline_cgroup_action(current_bytes: int, limit_bytes: int, *, paused: bool, paused_seconds: float) -> str:
    if not REPORT_PIPELINE_CGROUP_BACKPRESSURE_ENABLED or not current_bytes or not limit_bytes:
        return "none"
    ratio = current_bytes / limit_bytes
    if ratio >= REPORT_PIPELINE_CGROUP_KILL_RATIO:
        return "kill"
    if paused:
        if ratio <= REPORT_PIPELINE_CGROUP_RESUME_RATIO:
            return "resume"
        if paused_seconds >= REPORT_PIPELINE_CGROUP_MAX_PAUSE_SECONDS:
            return "kill"
        return "wait"
    if ratio >= REPORT_PIPELINE_CGROUP_PAUSE_RATIO:
        return "pause"
    return "none"


def _signal_report_pipeline_group(proc: subprocess.Popen[str], sig: int) -> bool:
    if os.name != "posix":
        return False
    try:
        os.killpg(proc.pid, sig)
        return True
    except ProcessLookupError:
        return False


def _kill_report_pipeline(proc: subprocess.Popen[str]) -> None:
    try:
        if os.name == "posix":
            os.killpg(proc.pid, signal.SIGKILL)
        else:
            proc.kill()
    except ProcessLookupError:
        pass


def _run_report_pipeline(
    cmd: list[str],
    cwd: Path,
    *,
    timeout: Optional[int] = None,
    extra_env: Optional[dict[str, str]] = None,
    low_priority: bool = False,
) -> str:
    with XLSX_GENERATOR_RUN_LOCK:
        return _run_report_pipeline_locked(
            cmd,
            cwd,
            timeout=timeout,
            extra_env=extra_env,
            low_priority=low_priority,
        )


def _run_report_pipeline_locked(
    cmd: list[str],
    cwd: Path,
    *,
    timeout: Optional[int] = None,
    extra_env: Optional[dict[str, str]] = None,
    low_priority: bool = False,
) -> str:
    effective_timeout = timeout if timeout is not None else REPORT_PIPELINE_TIMEOUT
    env = _report_pipeline_env()
    effective_cmd = list(cmd)
    if low_priority:
        thread_limit = str(REPORT_PIPELINE_XLSX_THREADS)
        for var_name in REPORT_PIPELINE_XLSX_THREAD_ENV_VARS:
            env[var_name] = thread_limit
        nice_bin = shutil.which("nice") if os.name == "posix" else None
        if nice_bin and REPORT_PIPELINE_XLSX_NICE > 0:
            effective_cmd = [nice_bin, "-n", str(REPORT_PIPELINE_XLSX_NICE), *effective_cmd]
    if extra_env:
        env.update(extra_env)

    run_id = uuid.uuid4().hex[:12]
    memory_limit_kb = REPORT_PIPELINE_MEMORY_LIMIT_MB * 1024
    started_at = time.monotonic()
    peak_memory_kb = 0
    peak_cgroup_memory_bytes = 0
    cgroup_limit_bytes = 0
    paused_for_cgroup = False
    cgroup_pause_started_at: Optional[float] = None
    cgroup_pause_total_seconds = 0.0
    try:
        proc = subprocess.Popen(
            effective_cmd,
            cwd=str(cwd),
            env=env,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            start_new_session=(os.name == "posix"),
        )
        REPORT_PIPELINE_LOG.warning(
            "report_pipeline_start run_id=%s pid=%s timeout_s=%s mem_limit_mb=%s cwd=%s cmd=%r",
            run_id,
            proc.pid,
            effective_timeout,
            REPORT_PIPELINE_MEMORY_LIMIT_MB,
            str(cwd),
            effective_cmd,
        )
        while True:
            elapsed = time.monotonic() - started_at
            remaining = effective_timeout - elapsed
            if remaining <= 0:
                _kill_report_pipeline(proc)
                stdout, _ = proc.communicate()
                REPORT_PIPELINE_LOG.error(
                    "report_pipeline_timeout run_id=%s pid=%s timeout_s=%s peak_memory_mb=%.1f",
                    run_id,
                    proc.pid,
                    effective_timeout,
                    peak_memory_kb / 1024,
                )
                raise HTTPException(504, f"Report pipeline timed out after {effective_timeout} seconds")
            try:
                stdout, _ = proc.communicate(
                    timeout=min(REPORT_PIPELINE_MEMORY_CHECK_INTERVAL_SECONDS, remaining)
                )
                break
            except subprocess.TimeoutExpired:
                current_memory_kb = _process_tree_memory_kb(proc.pid)
                peak_memory_kb = max(peak_memory_kb, current_memory_kb)
                cgroup_current_bytes, cgroup_limit_bytes_current = _report_pipeline_cgroup_memory_bytes()
                if cgroup_current_bytes and cgroup_limit_bytes_current:
                    peak_cgroup_memory_bytes = max(peak_cgroup_memory_bytes, cgroup_current_bytes)
                    cgroup_limit_bytes = cgroup_limit_bytes_current
                    paused_seconds = (
                        time.monotonic() - cgroup_pause_started_at
                        if paused_for_cgroup and cgroup_pause_started_at is not None
                        else 0.0
                    )
                    action = _report_pipeline_cgroup_action(
                        cgroup_current_bytes,
                        cgroup_limit_bytes_current,
                        paused=paused_for_cgroup,
                        paused_seconds=paused_seconds,
                    )
                    sigstop = getattr(signal, "SIGSTOP", None)
                    sigcont = getattr(signal, "SIGCONT", None)
                    if action == "pause" and sigstop is not None and _signal_report_pipeline_group(proc, sigstop):
                        paused_for_cgroup = True
                        cgroup_pause_started_at = time.monotonic()
                        REPORT_PIPELINE_LOG.warning(
                            "report_pipeline_cgroup_pause run_id=%s pid=%s cgroup_memory_mb=%.1f limit_mb=%.1f ratio=%.3f",
                            run_id,
                            proc.pid,
                            cgroup_current_bytes / 1024 / 1024,
                            cgroup_limit_bytes_current / 1024 / 1024,
                            cgroup_current_bytes / cgroup_limit_bytes_current,
                        )
                    elif action == "resume" and sigcont is not None and _signal_report_pipeline_group(proc, sigcont):
                        if cgroup_pause_started_at is not None:
                            cgroup_pause_total_seconds += time.monotonic() - cgroup_pause_started_at
                        paused_for_cgroup = False
                        cgroup_pause_started_at = None
                        REPORT_PIPELINE_LOG.warning(
                            "report_pipeline_cgroup_resume run_id=%s pid=%s cgroup_memory_mb=%.1f limit_mb=%.1f ratio=%.3f pause_total_s=%.1f",
                            run_id,
                            proc.pid,
                            cgroup_current_bytes / 1024 / 1024,
                            cgroup_limit_bytes_current / 1024 / 1024,
                            cgroup_current_bytes / cgroup_limit_bytes_current,
                            cgroup_pause_total_seconds,
                        )
                    elif action == "kill":
                        if paused_for_cgroup and sigcont is not None:
                            _signal_report_pipeline_group(proc, sigcont)
                        _kill_report_pipeline(proc)
                        stdout, _ = proc.communicate()
                        detail = (stdout or "").strip()[-800:]
                        REPORT_PIPELINE_LOG.error(
                            "report_pipeline_cgroup_memory_kill run_id=%s pid=%s cgroup_memory_mb=%.1f limit_mb=%.1f ratio=%.3f paused_s=%.1f cmd=%r",
                            run_id,
                            proc.pid,
                            cgroup_current_bytes / 1024 / 1024,
                            cgroup_limit_bytes_current / 1024 / 1024,
                            cgroup_current_bytes / cgroup_limit_bytes_current,
                            paused_seconds,
                            effective_cmd,
                        )
                        message = (
                            "Report pipeline stopped before container OOM "
                            f"({int(cgroup_current_bytes / 1024 / 1024)} MB / "
                            f"{int(cgroup_limit_bytes_current / 1024 / 1024)} MB)"
                        )
                        if detail:
                            message = f"{message}: {detail}"
                        raise HTTPException(507, message)
                if memory_limit_kb and current_memory_kb > memory_limit_kb:
                    _kill_report_pipeline(proc)
                    stdout, _ = proc.communicate()
                    detail = (stdout or "").strip()[-800:]
                    REPORT_PIPELINE_LOG.error(
                        "report_pipeline_memory_kill run_id=%s pid=%s memory_mb=%.1f limit_mb=%s peak_memory_mb=%.1f cmd=%r",
                        run_id,
                        proc.pid,
                        current_memory_kb / 1024,
                        REPORT_PIPELINE_MEMORY_LIMIT_MB,
                        peak_memory_kb / 1024,
                        effective_cmd,
                    )
                    message = (
                        f"Report pipeline exceeded memory limit "
                        f"({current_memory_kb // 1024} MB > {REPORT_PIPELINE_MEMORY_LIMIT_MB} MB)"
                    )
                    if detail:
                        message = f"{message}: {detail}"
                    raise HTTPException(507, message)
    except OSError as exc:
        REPORT_PIPELINE_LOG.exception("report_pipeline_start_failed run_id=%s cmd=%r", run_id, effective_cmd)
        raise HTTPException(500, f"Report pipeline failed to start: {exc}") from exc

    if paused_for_cgroup and cgroup_pause_started_at is not None:
        cgroup_pause_total_seconds += time.monotonic() - cgroup_pause_started_at
    peak_memory_kb = max(peak_memory_kb, _process_tree_memory_kb(proc.pid))
    elapsed = time.monotonic() - started_at
    if proc.returncode != 0:
        detail = (stdout or "").strip()[-1600:] or "Report pipeline failed"
        REPORT_PIPELINE_LOG.error(
            "report_pipeline_failed run_id=%s pid=%s returncode=%s elapsed_s=%.1f peak_memory_mb=%.1f detail=%r",
            run_id,
            proc.pid,
            proc.returncode,
            elapsed,
            peak_memory_kb / 1024,
            detail[-500:],
        )
        raise HTTPException(500, detail)
    REPORT_PIPELINE_LOG.warning(
        "report_pipeline_done run_id=%s pid=%s elapsed_s=%.1f peak_memory_mb=%.1f peak_cgroup_memory_mb=%.1f cgroup_limit_mb=%.1f cgroup_pause_s=%.1f returncode=%s",
        run_id,
        proc.pid,
        elapsed,
        peak_memory_kb / 1024,
        peak_cgroup_memory_bytes / 1024 / 1024,
        cgroup_limit_bytes / 1024 / 1024,
        cgroup_pause_total_seconds,
        proc.returncode,
    )
    return stdout or ""


def _read_output_file(path: Path) -> bytes:
    if not path.exists():
        raise HTTPException(500, f"Report pipeline did not create output file: {path}")
    return path.read_bytes()


def _parse_report_pipeline_json(stdout: str, *, detail: str) -> dict:
    for line in reversed((stdout or "").splitlines()):
        candidate = line.strip()
        if not candidate:
            continue
        try:
            parsed = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            return parsed
    raise HTTPException(500, detail)


def _parse_temp_roads_tsm_filename_date(name: str) -> date_cls | None:
    match = TEMP_ROADS_TSM_FILENAME_RE.match(name or "")
    if not match:
        return None
    try:
        return date_cls.fromisoformat(match.group("report_date"))
    except ValueError:
        return None


def _find_temp_roads_tsm_source_file(report_date: date_cls) -> Path:
    candidates: list[tuple[date_cls, Path]] = []
    if TEMP_ROADS_TSM_WORKSPACE.exists():
        for path in TEMP_ROADS_TSM_WORKSPACE.glob("ТСМ отчет по ВрАД *.xlsx"):
            parsed_date = _parse_temp_roads_tsm_filename_date(path.name)
            if parsed_date is not None and path.is_file():
                candidates.append((parsed_date, path))
    if not candidates:
        raise HTTPException(404, "Не найден исходный TSM workbook в /opt/vsm/.openclaw/workspace")

    past_candidates = sorted((item for item in candidates if item[0] <= report_date), key=lambda item: item[0])
    if past_candidates:
        return past_candidates[-1][1]
    return sorted(candidates, key=lambda item: item[0])[0][1]


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


DATE_SCOPED_XLSX_REPORT_KEYS = frozenset({"dim", "general", "mstroy_graph", "financial_plan_fact"})

XLSX_REPORT_GLOBAL_FINGERPRINT_TABLES = (
    "construction_sections",
    "construction_section_versions",
    "dashboard_settings",
    "equipment_norms_config",
    "materials",
    "object_segments",
    "object_types",
    "objects",
    "pile_fields",
    "pile_plan_periods",
    "pipe_pile_specs",
    "planned_work_items",
    "project_work_item_segments",
    "project_work_items",
    "statement_customer_closed_work_items",
    "temporary_roads",
    "work_types",
)

XLSX_REPORT_DAILY_SCOPED_FINGERPRINT_QUERIES = (
    (
        "daily_reports",
        "daily_reports dr",
        "dr.xmin",
        """
        WHERE dr.report_date <= %s
           OR EXISTS (
                SELECT 1
                FROM daily_work_items dwi
                WHERE dwi.daily_report_id = dr.id
                  AND dwi.report_date <= %s
           )
           OR EXISTS (
                SELECT 1
                FROM material_movements mm
                WHERE mm.daily_report_id = dr.id
                  AND mm.report_date <= %s
           )
        """,
        3,
    ),
    ("daily_work_items", "daily_work_items dwi", "dwi.xmin", "WHERE dwi.report_date <= %s", 1),
    (
        "daily_work_item_segments",
        "daily_work_item_segments seg JOIN daily_work_items dwi ON dwi.id = seg.daily_work_item_id",
        "seg.xmin",
        "WHERE dwi.report_date <= %s",
        1,
    ),
    ("material_movements", "material_movements mm", "mm.xmin", "WHERE mm.report_date <= %s", 1),
)

XLSX_REPORT_FULL_FACT_FINGERPRINT_TABLES = (
    "daily_reports",
    "daily_work_items",
    "daily_work_item_segments",
    "material_movements",
)


def _xlsx_db_table_exists(cur, table: str) -> bool:
    cur.execute("SELECT to_regclass(%s)", (f"public.{table}",))
    row = cur.fetchone()
    return bool(row and row[0])


def _xlsx_db_table_fingerprint(cur, table: str) -> dict[str, str]:
    if not _xlsx_db_table_exists(cur, table):
        return {"rows": "0", "max_xmin": "0", "missing": "1"}
    cur.execute(f"SELECT COUNT(*)::text, COALESCE(MAX(xmin::text::bigint), 0)::text FROM {table}")
    row_count, max_xmin = cur.fetchone()
    return {"rows": str(row_count or "0"), "max_xmin": str(max_xmin or "0")}


def _xlsx_db_scoped_fingerprint(
    cur,
    *,
    table: str,
    source_sql: str,
    xmin_expr: str,
    where_sql: str,
    params: tuple[Any, ...],
) -> dict[str, str]:
    if not _xlsx_db_table_exists(cur, table):
        return {"rows": "0", "max_xmin": "0", "missing": "1"}
    cur.execute(
        f"""
        SELECT COUNT(*)::text, COALESCE(MAX(({xmin_expr})::text::bigint), 0)::text
        FROM {source_sql}
        {where_sql}
        """,
        params,
    )
    row_count, max_xmin = cur.fetchone()
    return {"rows": str(row_count or "0"), "max_xmin": str(max_xmin or "0")}


def _xlsx_report_db_fingerprint(
    report_key: Optional[str] = None,
    d_from: Optional[date_cls] = None,
    d_to: Optional[date_cls] = None,
    *,
    filter_env: Optional[dict[str, str]] = None,
) -> dict[str, Any]:
    """Cheap read-only invalidation signal for XLSX report inputs.

    The DiM/Mстрой/Общий generators depend on catalog tables, project volumes,
    daily facts, material movements, and section boundaries.  Catalog tables are
    still global, while the heavy date-based reports fingerprint operational
    facts only through the requested report date.  A future-day edit therefore
    no longer invalidates already generated earlier-day reports.
    """
    date_scoped = report_key in DATE_SCOPED_XLSX_REPORT_KEYS and d_to is not None
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            global_result = {
                table: _xlsx_db_table_fingerprint(cur, table)
                for table in XLSX_REPORT_GLOBAL_FINGERPRINT_TABLES
            }
            if not date_scoped:
                for table in XLSX_REPORT_FULL_FACT_FINGERPRINT_TABLES:
                    global_result[table] = _xlsx_db_table_fingerprint(cur, table)
                return global_result

            daily_result: dict[str, dict[str, str]] = {}
            for table, source_sql, xmin_expr, where_sql, date_param_count in XLSX_REPORT_DAILY_SCOPED_FINGERPRINT_QUERIES:
                daily_result[table] = _xlsx_db_scoped_fingerprint(
                    cur,
                    table=table,
                    source_sql=source_sql,
                    xmin_expr=xmin_expr,
                    where_sql=where_sql,
                    params=(d_to,) * date_param_count,
                )

            return {
                "scope": {
                    "mode": "facts_through_report_date",
                    "report_key": report_key,
                    "request_date_from": d_from.isoformat() if d_from else None,
                    "date_to": d_to.isoformat(),
                    "report_filters": filter_env or {},
                },
                "global": global_result,
                "daily": daily_result,
            }
    finally:
        conn.close()


def _xlsx_report_cache_fingerprint(
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    script: Path,
    template: Path,
    filter_env: Optional[dict[str, str]] = None,
) -> str:
    script_hashes = {
        path.name: _sha256_file(path)
        for path in sorted(DIM_PIPELINE_DIR.glob("generate_*_report.py"))
        if path.is_file()
    }
    extra_inputs: dict[str, Any] = {}
    if report_key == "mstroy_graph":
        overlay_path = DIM_PIPELINE_DIR / "overlays" / "mstroy_project_overlay_latest.json"
        extra_inputs["project_overlay"] = {
            "path": str(overlay_path),
            "sha256": _sha256_file(overlay_path) if overlay_path.exists() else None,
        }
    if report_key == "dim":
        extra_inputs["mstroy_summary_template"] = {
            "path": str(MSTROY_GRAPH_TEMPLATE),
            "sha256": _sha256_file(MSTROY_GRAPH_TEMPLATE) if MSTROY_GRAPH_TEMPLATE.exists() else None,
        }
    payload = {
        "cache_version": 3 if report_key in DATE_SCOPED_XLSX_REPORT_KEYS else 2,
        "report_key": report_key,
        "date_from": d_from.isoformat(),
        "date_to": d_to.isoformat(),
        "script": str(script),
        "script_sha256": _sha256_file(script),
        "template": str(template),
        "template_sha256": _sha256_file(template),
        "scripts_sha256": script_hashes,
        "extra_inputs": extra_inputs,
        "excluded_tags_env": os.getenv("DIM_REPORT_EXCLUDED_ANALYTICS_TAGS", ""),
        "report_filters": filter_env or {},
        "db": _xlsx_report_db_fingerprint(report_key, d_from, d_to, filter_env=filter_env),
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _xlsx_cache_paths(report_key: str, d_from: date_cls, d_to: date_cls, fingerprint: str) -> tuple[Path, Path, Path]:
    cache_dir = REPORT_XLSX_CACHE_DIR / report_key
    safe_range = f"{d_from.isoformat()}_{d_to.isoformat()}"
    base = f"{report_key}_{safe_range}_{fingerprint[:20]}"
    return cache_dir / f"{base}.xlsx", cache_dir / f"{base}.metadata.json", cache_dir / f"{report_key}_{safe_range}.lock"


PIPELINE_ESTIMATE_FALLBACK_SECONDS = {
    "dim": 2400,
    "mstroy": 720,
    "mstroy_graph": 600,
    "general": 900,
    "simple_section_report": 360,
    "transport_section_report": 360,
    "financial_plan_fact": 300,
    "equipment": 360,
    "pile_daily_breakdown": 120,
    "admin_dumptruck": 360,
    "general_analytics_main_table": 360,
    "general_exact_xlsx": 360,
    "statements_general_workbook": 300,
    "temp_roads_tsm_xlsx": 180,
    "mainline_structural_scheme": 180,
}


def _parse_utc_datetime(value: object) -> Optional[datetime]:
    if isinstance(value, datetime):
        parsed = value
    else:
        text = str(value or "").strip()
        if not text:
            return None
        try:
            parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except ValueError:
            return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _elapsed_seconds_since(value: object) -> Optional[int]:
    parsed = _parse_utc_datetime(value)
    if parsed is None:
        return None
    return max(0, int((datetime.now(timezone.utc) - parsed).total_seconds()))


def _elapsed_seconds_between(started_at: object, finished_at: object) -> Optional[int]:
    started = _parse_utc_datetime(started_at)
    finished = _parse_utc_datetime(finished_at)
    if started is None or finished is None:
        return None
    return max(0, int((finished - started).total_seconds()))


def _clamp_progress_percent(value: float) -> int:
    return max(0, min(100, int(round(value))))


def _date_range_days(d_from: date_cls, d_to: date_cls) -> int:
    return max(1, (d_to - d_from).days + 1)


def _estimate_xlsx_runtime_seconds(report_key: str, d_from: date_cls, d_to: date_cls) -> int:
    fallback = int(PIPELINE_ESTIMATE_FALLBACK_SECONDS.get(report_key, 420))
    cache_dir = REPORT_XLSX_CACHE_DIR / report_key
    if not cache_dir.exists():
        return fallback
    prefix = f"{report_key}_"
    target_days = _date_range_days(d_from, d_to)
    weighted: list[tuple[float, float]] = []
    locks = sorted(cache_dir.glob(f"{prefix}*.lock"), key=lambda path: path.stat().st_mtime, reverse=True)[:80]
    for lock_path in locks:
        stem = lock_path.name[:-5]
        if not stem.startswith(prefix):
            continue
        range_part = stem[len(prefix):]
        parts = range_part.split("_", 1)
        if len(parts) != 2:
            continue
        try:
            old_from = date_cls.fromisoformat(parts[0])
            old_to = date_cls.fromisoformat(parts[1])
        except ValueError:
            continue
        matches = sorted(cache_dir.glob(f"{stem}_*.xlsx"), key=lambda path: path.stat().st_mtime, reverse=True)
        if not matches:
            continue
        duration = matches[0].stat().st_mtime - lock_path.stat().st_mtime
        if duration < 30 or duration > REPORT_PIPELINE_XLSX_TIMEOUT:
            continue
        old_days = _date_range_days(old_from, old_to)
        weight = 1.0
        if old_days == target_days:
            weight = 3.0
        elif abs(old_days - target_days) <= 1:
            weight = 2.0
        weighted.append((duration, weight))
        if len(weighted) >= 20:
            break
    if not weighted:
        return fallback
    weighted.sort(key=lambda item: item[0])
    total_weight = sum(weight for _duration, weight in weighted)
    threshold = total_weight / 2
    acc = 0.0
    for duration, weight in weighted:
        acc += weight
        if acc >= threshold:
            return int(max(60, min(REPORT_PIPELINE_XLSX_TIMEOUT, duration)))
    return int(max(60, min(REPORT_PIPELINE_XLSX_TIMEOUT, weighted[-1][0])))


def _estimate_pipeline_runtime_seconds(report_key: str, d_from: date_cls, d_to: date_cls) -> int:
    if report_key in PIPELINE_ESTIMATE_FALLBACK_SECONDS and (REPORT_XLSX_CACHE_DIR / report_key).exists():
        return _estimate_xlsx_runtime_seconds(report_key, d_from, d_to)
    return int(PIPELINE_ESTIMATE_FALLBACK_SECONDS.get(report_key, 420))


def _progress_snapshot(
    *,
    status: str,
    started_at: object,
    estimated_total_seconds: object,
    finished_at: object = None,
    completed_estimated_seconds: float = 0.0,
    current_step_started_at: object = None,
    current_step_estimated_seconds: object = None,
) -> dict[str, Optional[int]]:
    is_finished = status in {"ready", "success", "error"}
    elapsed = (
        _elapsed_seconds_between(started_at, finished_at)
        if is_finished and finished_at
        else _elapsed_seconds_since(started_at)
    )
    try:
        total_estimate = max(1.0, float(estimated_total_seconds or 0))
    except (TypeError, ValueError):
        total_estimate = 0.0
    if status == "ready" or status == "success":
        return {
            "elapsed_seconds": elapsed,
            "eta_seconds": 0,
            "estimated_total_seconds": int(total_estimate) if total_estimate else None,
            "progress_percent": 100,
        }
    if status == "error":
        return {
            "elapsed_seconds": elapsed,
            "eta_seconds": None,
            "estimated_total_seconds": int(total_estimate) if total_estimate else None,
            "progress_percent": None,
        }
    if total_estimate <= 0:
        return {
            "elapsed_seconds": elapsed,
            "eta_seconds": None,
            "estimated_total_seconds": None,
            "progress_percent": None,
        }
    current_elapsed = _elapsed_seconds_since(current_step_started_at) if current_step_started_at else elapsed
    try:
        step_estimate = max(1.0, float(current_step_estimated_seconds or total_estimate))
    except (TypeError, ValueError):
        step_estimate = total_estimate
    effective_done = float(completed_estimated_seconds or 0) + min(float(current_elapsed or 0), step_estimate * 0.95)
    percent = _clamp_progress_percent((effective_done / total_estimate) * 100)
    if percent >= 100:
        percent = 99
    eta = max(0, int(round(total_estimate - effective_done)))
    return {
        "elapsed_seconds": elapsed,
        "eta_seconds": eta,
        "estimated_total_seconds": int(round(total_estimate)),
        "progress_percent": percent,
    }


def _read_cached_xlsx(path: Path, meta_path: Path, fingerprint: str) -> bytes | None:
    if not path.exists() or not meta_path.exists():
        return None
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if meta.get("fingerprint") != fingerprint:
        return None
    if int(meta.get("size_bytes") or -1) != path.stat().st_size:
        return None
    return path.read_bytes()


def _cached_xlsx_ready(path: Path, meta_path: Path, fingerprint: str) -> bool:
    if not path.exists() or not meta_path.exists():
        return False
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, ValueError):
        return False
    if meta.get("fingerprint") != fingerprint:
        return False
    try:
        return int(meta.get("size_bytes") or -1) == path.stat().st_size
    except OSError:
        return False


def _cached_xlsx_meta_artifact_path(meta_path: Path, meta: Optional[dict] = None) -> Path:
    meta = meta if isinstance(meta, dict) else {}
    raw = str(meta.get("artifact") or "").strip()
    if raw:
        artifact = Path(raw)
        return artifact if artifact.is_absolute() else meta_path.parent / artifact
    if meta_path.name.endswith(".metadata.json"):
        return meta_path.with_name(f"{meta_path.name[:-len('.metadata.json')]}.xlsx")
    return meta_path.with_suffix(".xlsx")


def _cached_xlsx_metadata_path_for_artifact(artifact_path: Path) -> Path:
    return artifact_path.with_suffix(".metadata.json")


def _is_valid_xlsx_artifact(path: Path) -> bool:
    try:
        if path.stat().st_size <= 0:
            return False
        with ZipFile(path) as archive:
            names = set(archive.namelist())
        return "[Content_Types].xml" in names and any(name.startswith("xl/") for name in names)
    except (OSError, BadZipFile, ValueError):
        return False


def _latest_cached_xlsx_artifact(
    *,
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
) -> Optional[dict[str, Any]]:
    if not REPORT_XLSX_CACHE_ENABLED:
        return None
    cache_dir = REPORT_XLSX_CACHE_DIR / report_key
    if not cache_dir.exists() or not cache_dir.is_dir():
        return None

    safe_range = f"{d_from.isoformat()}_{d_to.isoformat()}"
    prefix = f"{report_key}_{safe_range}_"
    candidates: dict[Path, dict[str, Any]] = {}

    for meta_path in cache_dir.glob(f"{prefix}*.metadata.json"):
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError, ValueError):
            continue
        if meta.get("report_key") != report_key:
            continue
        if meta.get("date_from") != d_from.isoformat() or meta.get("date_to") != d_to.isoformat():
            continue
        artifact = _cached_xlsx_meta_artifact_path(meta_path, meta)
        try:
            expected_size = int(meta.get("size_bytes") or -1)
            actual_size = artifact.stat().st_size
        except (OSError, TypeError, ValueError):
            continue
        if expected_size != actual_size or not _is_valid_xlsx_artifact(artifact):
            continue
        candidates[artifact] = {
            "artifact": artifact,
            "meta_path": meta_path,
            "fingerprint": str(meta.get("fingerprint") or ""),
            "cache_created_at": str(
                meta.get("created_at")
                or datetime.fromtimestamp(artifact.stat().st_mtime, timezone.utc).isoformat()
            ),
            "cache_mode": "latest_metadata" if meta.get("fingerprint") else "latest",
            "mtime": artifact.stat().st_mtime,
        }

    for artifact in cache_dir.glob(f"{prefix}*.xlsx"):
        if artifact in candidates or not _is_valid_xlsx_artifact(artifact):
            continue
        candidates[artifact] = {
            "artifact": artifact,
            "meta_path": _cached_xlsx_metadata_path_for_artifact(artifact),
            "fingerprint": "",
            "cache_created_at": datetime.fromtimestamp(artifact.stat().st_mtime, timezone.utc).isoformat(),
            "cache_mode": "latest_file",
            "mtime": artifact.stat().st_mtime,
        }

    if not candidates:
        return None
    return max(candidates.values(), key=lambda item: float(item.get("mtime") or 0))


def _pdf_cache_section_suffix(section_codes: Optional[list[str]] = None) -> str:
    section_codes_clean = _mainline_structural_scheme_section_codes(section_codes)
    return "_".join(section_codes_clean) if section_codes_clean else "all"


def _pdf_cache_paths(
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    fingerprint: str,
    *,
    section_codes: Optional[list[str]] = None,
) -> tuple[Path, Path, Path]:
    cache_dir = REPORT_PDF_CACHE_DIR / report_key
    safe_range = f"{d_from.isoformat()}_{d_to.isoformat()}"
    section_suffix = _pdf_cache_section_suffix(section_codes)
    base = f"{report_key}_{safe_range}_{section_suffix}_{fingerprint[:20]}"
    return cache_dir / f"{base}.pdf", cache_dir / f"{base}.metadata.json", cache_dir / f"{report_key}_{safe_range}_{section_suffix}.lock"


def _is_valid_pdf_artifact(path: Path) -> bool:
    try:
        if path.stat().st_size <= 8:
            return False
        with path.open("rb") as fh:
            return fh.read(5) == b"%PDF-"
    except OSError:
        return False


def _cached_pdf_meta_artifact_path(meta_path: Path, meta: Optional[dict] = None) -> Path:
    meta = meta if isinstance(meta, dict) else {}
    raw = str(meta.get("artifact") or "").strip()
    if raw:
        artifact = Path(raw)
        return artifact if artifact.is_absolute() else meta_path.parent / artifact
    if meta_path.name.endswith(".metadata.json"):
        return meta_path.with_name(f"{meta_path.name[:-len('.metadata.json')]}.pdf")
    return meta_path.with_suffix(".pdf")


def _cached_pdf_ready(path: Path, meta_path: Path, fingerprint: str) -> bool:
    if not path.exists() or not meta_path.exists():
        return False
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, ValueError):
        return False
    if meta.get("fingerprint") != fingerprint:
        return False
    try:
        return int(meta.get("size_bytes") or -1) == path.stat().st_size and _is_valid_pdf_artifact(path)
    except OSError:
        return False


def _latest_cached_pdf_artifact(
    *,
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    section_codes: Optional[list[str]] = None,
) -> Optional[dict[str, Any]]:
    if not REPORT_PDF_CACHE_ENABLED:
        return None
    cache_dir = REPORT_PDF_CACHE_DIR / report_key
    if not cache_dir.exists() or not cache_dir.is_dir():
        return None

    section_codes_clean = _mainline_structural_scheme_section_codes(section_codes)
    section_suffix = _pdf_cache_section_suffix(section_codes_clean)
    safe_range = f"{d_from.isoformat()}_{d_to.isoformat()}"
    prefix = f"{report_key}_{safe_range}_{section_suffix}_"
    candidates: dict[Path, dict[str, Any]] = {}

    for meta_path in cache_dir.glob(f"{prefix}*.metadata.json"):
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError, ValueError):
            continue
        if meta.get("report_key") != report_key:
            continue
        if meta.get("date_from") != d_from.isoformat() or meta.get("date_to") != d_to.isoformat():
            continue
        if list(meta.get("section_codes") or []) != section_codes_clean:
            continue
        artifact = _cached_pdf_meta_artifact_path(meta_path, meta)
        try:
            expected_size = int(meta.get("size_bytes") or -1)
            actual_size = artifact.stat().st_size
        except (OSError, TypeError, ValueError):
            continue
        if expected_size != actual_size or not _is_valid_pdf_artifact(artifact):
            continue
        candidates[artifact] = {
            "artifact": artifact,
            "meta_path": meta_path,
            "fingerprint": str(meta.get("fingerprint") or ""),
            "cache_created_at": str(
                meta.get("created_at")
                or datetime.fromtimestamp(artifact.stat().st_mtime, timezone.utc).isoformat()
            ),
            "cache_mode": "latest_metadata" if meta.get("fingerprint") else "latest",
            "mtime": artifact.stat().st_mtime,
        }

    for artifact in cache_dir.glob(f"{prefix}*.pdf"):
        if artifact in candidates or not _is_valid_pdf_artifact(artifact):
            continue
        candidates[artifact] = {
            "artifact": artifact,
            "meta_path": artifact.with_suffix(".metadata.json"),
            "fingerprint": "",
            "cache_created_at": datetime.fromtimestamp(artifact.stat().st_mtime, timezone.utc).isoformat(),
            "cache_mode": "latest_file",
            "mtime": artifact.stat().st_mtime,
        }

    if not candidates:
        return None
    return max(candidates.values(), key=lambda item: float(item.get("mtime") or 0))


def _ensure_cached_xlsx_artifact(
    *,
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    script: Path,
    template: Path,
    output_name: str,
    filter_env: Optional[dict[str, str]] = None,
    fingerprint: Optional[str] = None,
    artifact: Optional[Path] = None,
    meta_path: Optional[Path] = None,
    lock_path: Optional[Path] = None,
    cumulative_end_date: Optional[date_cls] = None,
) -> Path:
    if not REPORT_XLSX_CACHE_ENABLED:
        raise HTTPException(503, "XLSX cache is disabled; background export requires cache")
    fingerprint = fingerprint or _xlsx_report_cache_fingerprint(report_key, d_from, d_to, script, template, filter_env=filter_env)
    if artifact is None or meta_path is None or lock_path is None:
        artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, d_from, d_to, fingerprint)
    if _cached_xlsx_ready(artifact, meta_path, fingerprint):
        return artifact

    artifact.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+") as lock_fh:
        fcntl.flock(lock_fh, fcntl.LOCK_EX)
        try:
            if _cached_xlsx_ready(artifact, meta_path, fingerprint):
                return artifact
            with tempfile.TemporaryDirectory(prefix=f"vsm-{report_key}-report-") as tmp_dir:
                tmp_output = Path(tmp_dir) / output_name
                stdout = _run_xlsx_generator(
                    script,
                    template,
                    tmp_output,
                    d_from,
                    d_to,
                    filter_env=filter_env,
                    cumulative_end_date=cumulative_end_date,
                )
                _read_output_file(tmp_output)
                tmp_cache = artifact.with_suffix(artifact.suffix + ".tmp")
                shutil.copyfile(tmp_output, tmp_cache)
                tmp_cache.replace(artifact)
                _write_cached_xlsx_metadata(
                    meta_path,
                    report_key=report_key,
                    d_from=d_from,
                    d_to=d_to,
                    fingerprint=fingerprint,
                    artifact_path=artifact,
                    stdout=stdout,
                )
                return artifact
        finally:
            fcntl.flock(lock_fh, fcntl.LOCK_UN)


