def _clear_xlsx_report_cache() -> dict[str, int | str | bool]:
    """Remove generated XLSX cache artifacts, keeping the cache root itself.

    This is intentionally scoped to REPORT_XLSX_CACHE_DIR only; it does not
    touch pipeline templates, DB files, or PDF artifacts.
    """
    root = REPORT_XLSX_CACHE_DIR
    if not root.exists():
        root.mkdir(parents=True, exist_ok=True)
        return {"ok": True, "cache_dir": str(root), "removed_files": 0, "removed_dirs": 0, "removed_bytes": 0}
    if not root.is_dir():
        raise HTTPException(500, f"XLSX cache path is not a directory: {root}")

    removed_files = 0
    removed_dirs = 0
    removed_bytes = 0
    for child in list(root.iterdir()):
        try:
            if child.is_file() or child.is_symlink():
                try:
                    removed_bytes += child.stat().st_size
                except OSError:
                    pass
                child.unlink()
                removed_files += 1
            elif child.is_dir():
                for nested in child.rglob("*"):
                    if nested.is_file() or nested.is_symlink():
                        try:
                            removed_bytes += nested.stat().st_size
                        except OSError:
                            pass
                        removed_files += 1
                    elif nested.is_dir():
                        removed_dirs += 1
                shutil.rmtree(child)
                removed_dirs += 1
        except OSError as exc:
            raise HTTPException(500, f"Failed to clear XLSX cache item {child}: {exc}") from exc
    root.mkdir(parents=True, exist_ok=True)
    return {
        "ok": True,
        "cache_dir": str(root),
        "removed_files": removed_files,
        "removed_dirs": removed_dirs,
        "removed_bytes": removed_bytes,
    }


def _write_cached_xlsx_metadata(
    meta_path: Path,
    *,
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    fingerprint: str,
    artifact_path: Path,
    stdout: str,
) -> None:
    meta = {
        "report_key": report_key,
        "date_from": d_from.isoformat(),
        "date_to": d_to.isoformat(),
        "fingerprint": fingerprint,
        "artifact": str(artifact_path),
        "size_bytes": artifact_path.stat().st_size,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "pipeline_stdout_tail": (stdout or "")[-2000:],
    }
    tmp_meta = meta_path.with_suffix(meta_path.suffix + ".tmp")
    tmp_meta.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp_meta.replace(meta_path)


