def _pdf_report_cache_fingerprint(
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    *,
    section_codes: Optional[list[str]] = None,
    filter_env: Optional[dict[str, str]] = None,
) -> str:
    if report_key != "mainline_structural_scheme":
        raise HTTPException(400, f"PDF cache is not supported for {report_key}")
    payload = {
        "cache_version": 2,
        "report_key": report_key,
        "date_from": d_from.isoformat(),
        "date_to": d_to.isoformat(),
        "section_codes": _mainline_structural_scheme_section_codes(section_codes),
        "script": str(MAINLINE_STRUCTURAL_SCHEME_SCRIPT),
        "script_sha256": _sha256_file(MAINLINE_STRUCTURAL_SCHEME_SCRIPT) if MAINLINE_STRUCTURAL_SCHEME_SCRIPT.exists() else None,
        "report_filters": filter_env or {},
        "db": _dashboard_source_fingerprint(MAINLINE_FILL_DISPLAY_START_DATE, d_to, include_mainline_fill=True),
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _pdf_pipeline_job_info(
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    filter_env: Optional[dict[str, str]] = None,
    *,
    section_codes: Optional[list[str]] = None,
) -> dict:
    if report_key != "mainline_structural_scheme":
        raise HTTPException(400, f"PDF background export is not supported for {report_key}")
    if not MAINLINE_STRUCTURAL_SCHEME_SCRIPT.exists():
        raise HTTPException(503, "Mainline structural scheme pipeline is not available on this server")
    d_from = d_to
    section_codes_clean = _mainline_structural_scheme_section_codes(section_codes)
    fingerprint = _pdf_report_cache_fingerprint(
        report_key,
        d_from,
        d_to,
        section_codes=section_codes_clean,
        filter_env=filter_env,
    )
    artifact, meta_path, lock_path = _pdf_cache_paths(report_key, d_from, d_to, fingerprint, section_codes=section_codes_clean)
    date_label = d_to.strftime("%d.%m.%Y")
    suffix = "_".join(section_codes_clean) if section_codes_clean else "all"
    filename_ascii = f"VSM_Mainline_Structural_Scheme_{d_to.isoformat()}_{suffix}.pdf"
    filename_utf8 = f"Структурная схема ОХ {date_label}{' ' + suffix if section_codes_clean else ''}.pdf"
    job_payload = {
        "report_key": report_key,
        "date_from": d_from.isoformat(),
        "date_to": d_to.isoformat(),
        "filter_env": filter_env or {},
        "fingerprint": fingerprint,
        "artifact": str(artifact),
        "meta_path": str(meta_path),
        "lock_path": str(lock_path),
        "media_type": PDF_MEDIA_TYPE,
        "section_codes": section_codes_clean,
        "filename_ascii": filename_ascii,
        "filename_utf8": filename_utf8,
        "estimated_total_seconds": _estimate_pipeline_runtime_seconds(report_key, d_from, d_to),
        "stage_label": "Генерация PDF",
    }
    job_id_raw = json.dumps(job_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    job_payload["job_id"] = hashlib.sha256(job_id_raw.encode("utf-8")).hexdigest()[:32]
    return job_payload


def _ensure_pdf_export_job_artifact(job: dict) -> Path:
    report_key = str(job.get("report_key") or "")
    if report_key != "mainline_structural_scheme":
        raise HTTPException(400, f"PDF background export is not supported for {report_key}")
    if not REPORT_PDF_CACHE_ENABLED:
        raise HTTPException(503, "PDF cache is disabled; background export requires cache")
    artifact = Path(str(job["artifact"]))
    meta_path = Path(str(job["meta_path"]))
    fingerprint = str(job["fingerprint"])
    if _cached_pdf_ready(artifact, meta_path, fingerprint):
        return artifact

    d_to = date_cls.fromisoformat(str(job["date_to"]))
    section_codes = _mainline_structural_scheme_section_codes(list(job.get("section_codes") or []))
    lock_path = Path(str(job["lock_path"]))
    artifact.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+") as lock_fh:
        fcntl.flock(lock_fh, fcntl.LOCK_EX)
        try:
            if _cached_pdf_ready(artifact, meta_path, fingerprint):
                return artifact
            with tempfile.TemporaryDirectory(prefix=f"vsm-{report_key}-report-") as tmp_dir:
                tmp_path = Path(tmp_dir)
                tmp_output = tmp_path / "mainline_structural_scheme.pdf"
                stdout = _run_mainline_structural_scheme_pipeline(d_to, section_codes, tmp_output, tmp_path / "mpl")
                _read_output_file(tmp_output)
                tmp_cache = artifact.with_suffix(artifact.suffix + ".tmp")
                shutil.copyfile(tmp_output, tmp_cache)
                tmp_cache.replace(artifact)
                _write_cached_pdf_metadata(
                    meta_path,
                    report_key=report_key,
                    d_from=date_cls.fromisoformat(str(job["date_from"])),
                    d_to=d_to,
                    fingerprint=fingerprint,
                    artifact_path=artifact,
                    stdout=stdout,
                    section_codes=section_codes,
                )
                return artifact
        finally:
            fcntl.flock(lock_fh, fcntl.LOCK_UN)


def _generate_cached_xlsx_report(
    *,
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    script: Path,
    template: Path,
    output_name: str,
    filter_env: Optional[dict[str, str]] = None,
    cumulative_end_date: Optional[date_cls] = None,
) -> bytes:
    if not REPORT_XLSX_CACHE_ENABLED:
        with tempfile.TemporaryDirectory(prefix=f"vsm-{report_key}-report-") as tmp_dir:
            output = Path(tmp_dir) / output_name
            _run_xlsx_generator(
                script,
                template,
                output,
                d_from,
                d_to,
                filter_env=filter_env,
                cumulative_end_date=cumulative_end_date,
            )
            return _read_output_file(output)

    fingerprint = _xlsx_report_cache_fingerprint(report_key, d_from, d_to, script, template, filter_env=filter_env)
    artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, d_from, d_to, fingerprint)
    cached = _read_cached_xlsx(artifact, meta_path, fingerprint)
    if cached is not None:
        return cached

    artifact.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+") as lock_fh:
        fcntl.flock(lock_fh, fcntl.LOCK_EX)
        try:
            cached = _read_cached_xlsx(artifact, meta_path, fingerprint)
            if cached is not None:
                return cached
            with tempfile.TemporaryDirectory(prefix=f"vsm-{report_key}-report-") as tmp_dir:
                tmp_output = Path(tmp_dir) / output_name
                stdout = _run_xlsx_generator(
                    script,
                    template,
                    tmp_output,
                    d_from,
                    d_to,
                    filter_env=filter_env,
                    cumulative_end_date=cumulative_end_date,
                )
                _read_output_file(tmp_output)
                tmp_cache = artifact.with_suffix(artifact.suffix + ".tmp")
                shutil.copyfile(tmp_output, tmp_cache)
                tmp_cache.replace(artifact)
                _write_cached_xlsx_metadata(
                    meta_path,
                    report_key=report_key,
                    d_from=d_from,
                    d_to=d_to,
                    fingerprint=fingerprint,
                    artifact_path=artifact,
                    stdout=stdout,
                )
                return artifact.read_bytes()
        finally:
            fcntl.flock(lock_fh, fcntl.LOCK_UN)


XLSX_GENERATORS_WITHOUT_CUMULATIVE_END_ARG = frozenset({
    "generate_mstroi_graph_report.py",
})


def _run_xlsx_generator(
    script: Path,
    template: Path,
    output: Path,
    d_from: date_cls,
    d_to: date_cls,
    *,
    filter_env: Optional[dict[str, str]] = None,
    cumulative_end_date: Optional[date_cls] = None,
) -> str:
    cmd = [
        sys.executable,
        str(script),
        "--template",
        str(template),
        "--output",
        str(output),
        "--start-date",
        d_from.isoformat(),
        "--end-date",
        d_to.isoformat(),
    ]
    if cumulative_end_date is not None and script.name not in XLSX_GENERATORS_WITHOUT_CUMULATIVE_END_ARG:
        cmd.extend(["--cumulative-end-date", cumulative_end_date.isoformat()])
    return _run_report_pipeline(
        cmd,
        DIM_PIPELINE_DIR,
        timeout=REPORT_PIPELINE_XLSX_TIMEOUT,
        extra_env=filter_env,
        low_priority=True,
    )


def _generate_temp_roads_pipeline_pdf(report_date: date_cls) -> tuple[bytes, str, str]:
    if not TEMP_ROADS_WEASY_MODULE.exists():
        raise HTTPException(503, "Temp roads report pipeline is not available on this server")
    date_label = report_date.strftime("%d.%m.%Y")
    with tempfile.TemporaryDirectory(prefix="vsm-temp-roads-report-") as tmp_dir:
        output = Path(tmp_dir) / "temp_roads_report.pdf"
        code = (
            "from datetime import date\n"
            "from pathlib import Path\n"
            "from weasyprint import HTML\n"
            "import generate_temp_roads_daily_pdf_weasy as mod\n"
            f"mod.REPORT_DATE = date.fromisoformat({report_date.isoformat()!r})\n"
            "mod.TARGET_DATE = date(2026, 5, 1)\n"
            f"mod.OUTPUT_PATH = Path({str(output)!r})\n"
            "model = mod.build_model()\n"
            "html = mod.render_html(model)\n"
            "HTML(string=html, base_url='/').write_pdf(str(mod.OUTPUT_PATH))\n"
            "print(mod.OUTPUT_PATH)\n"
        )
        _run_report_pipeline([sys.executable, "-c", code], TEMP_ROADS_PIPELINE_DIR)
        data = _read_output_file(output)
    return data, f"VSM_Temp_Roads_{report_date.isoformat()}.pdf", f"Отчет по отсыпке {date_label}.pdf"


def _generate_temp_roads_tsm_pipeline_xlsx(report_date: date_cls) -> tuple[bytes, str, str]:
    if not TEMP_ROADS_RUNNER.exists():
        raise HTTPException(503, "Temp roads TSM pipeline is not available on this server")
    source_file = _find_temp_roads_tsm_source_file(report_date)
    raw = _run_report_pipeline(
        [
            sys.executable,
            str(TEMP_ROADS_RUNNER),
            "--date",
            report_date.isoformat(),
            "--generate-tsm-xlsx",
            "--source-file",
            str(source_file),
        ],
        TEMP_ROADS_RUNNER.parent,
        timeout=REPORT_PIPELINE_XLSX_TIMEOUT,
        low_priority=True,
    )
    result = _parse_report_pipeline_json(raw, detail="TSM pipeline did not return JSON result")
    if result.get("status") != "ok":
        raise HTTPException(500, str(result.get("detail") or "TSM pipeline failed"))
    output_path = Path(str(result.get("output_path") or ""))
    data = _read_output_file(output_path)
    date_label = report_date.strftime("%d.%m.%Y")
    return (
        data,
        f"VSM_Temp_Roads_TSM_{report_date.isoformat()}.xlsx",
        f"ТСМ отчет по ВрАД {date_label}.xlsx",
    )


