def _mainline_structural_scheme_section_codes(section_codes: Optional[list[str]] = None) -> list[str]:
    cleaned: list[str] = []
    for raw_code in section_codes or []:
        code = _merge_section(raw_code)
        if not code or str(code).strip().lower() == "all":
            continue
        cleaned.append(code)
    return list(dict.fromkeys(cleaned))


def _run_mainline_structural_scheme_pipeline(
    report_date: date_cls,
    section_codes: Optional[list[str]],
    output: Path,
    mpl_config_dir: Path,
) -> str:
    if not MAINLINE_STRUCTURAL_SCHEME_SCRIPT.exists():
        raise HTTPException(503, "Mainline structural scheme pipeline is not available on this server")
    section_codes_clean = _mainline_structural_scheme_section_codes(section_codes)
    cmd = [
        sys.executable,
        str(MAINLINE_STRUCTURAL_SCHEME_SCRIPT),
        "--to",
        report_date.isoformat(),
        "--output",
        str(output),
    ]
    if section_codes_clean:
        cmd.extend(["--sections", ",".join(section_codes_clean)])
    return _run_report_pipeline(
        cmd,
        MAINLINE_STRUCTURAL_SCHEME_SCRIPT.parent.parent,
        extra_env={
            "MPLBACKEND": "Agg",
            "MPLCONFIGDIR": str(mpl_config_dir),
        },
        low_priority=True,
    )


