def _simple_section_report_filename_section_label(section_codes: Optional[list[str]]) -> str:
    if not section_codes:
        return "все участки"
    labels: list[str] = []
    seen: set[str] = set()
    for code in section_codes:
        normalized = str(code or "").strip().upper()
        if normalized in {"UCH_31", "UCH_32"}:
            normalized = "UCH_3"
        if not normalized.startswith("UCH_"):
            continue
        label = normalized.replace("UCH_", "")
        if label not in seen:
            seen.add(label)
            labels.append(label)
    if not labels:
        return "выбранные участки"
    return ", ".join(labels)


def _active_generator_section_codes() -> list[str]:
    rows = query(
        """
        SELECT code
        FROM construction_sections
        WHERE is_active = true
        ORDER BY sort_order NULLS LAST, code
        """
    )
    return [str(row["code"]) for row in rows if row.get("code")]


