def _generate_dim_like_pipeline_xlsx(
    *,
    report_key: str,
    script_name: str,
    template: Path,
    output_name: str,
    filename_prefix: str,
    filename_label: str,
    d_from: date_cls,
    d_to: date_cls,
    filter_env: Optional[dict[str, str]] = None,
    cumulative_as_of_end_date: bool = False,
) -> tuple[bytes, str, str]:
    script = DIM_PIPELINE_DIR / script_name
    if not script.exists():
        raise HTTPException(503, f"{filename_label} pipeline is not available on this server")
    if not template.exists():
        raise HTTPException(503, f"{filename_label} template is not available on this server")
    effective_from, effective_to = _xlsx_effective_period_for_cumulative_as_of(
        report_key,
        d_from,
        d_to,
        cumulative_as_of_end_date,
    )
    effective_filter_env = dict(filter_env or {})
    if cumulative_as_of_end_date:
        effective_filter_env.update(_report_option_env(cumulative_as_of_end_date=True))
    data = _generate_cached_xlsx_report(
        report_key=report_key,
        d_from=effective_from,
        d_to=effective_to,
        script=script,
        template=template,
        output_name=output_name,
        filter_env=effective_filter_env or None,
        cumulative_end_date=d_to if cumulative_as_of_end_date else None,
    )
    filename_ascii, filename_utf8 = _dim_like_pipeline_filenames(
        filename_prefix=filename_prefix,
        filename_label=filename_label,
        d_from=d_from,
        d_to=d_to,
        cumulative_as_of_end_date=cumulative_as_of_end_date,
    )
    return data, filename_ascii, filename_utf8


