def _admin_dumptruck_template_sort_key(path: Path) -> tuple[date_cls, float, str]:
    parsed_date = date_cls.min
    match = ADMIN_DUMPTRUCK_TEMPLATE_FILENAME_RE.match(path.name)
    if match:
        try:
            parsed_date = datetime.strptime(match.group("report_date"), "%d.%m.%Y").date()
        except ValueError:
            parsed_date = date_cls.min
    return parsed_date, path.stat().st_mtime, path.name


def _admin_dumptruck_template_candidates() -> list[Path]:
    candidates: list[Path] = []
    if ADMIN_DUMPTRUCK_TEMPLATE_ENV:
        candidates.append(Path(ADMIN_DUMPTRUCK_TEMPLATE_ENV).expanduser())
    candidates.append(ADMIN_DUMPTRUCK_DEFAULT_TEMPLATE)
    if ADMIN_DUMPTRUCK_TEMPLATE_DIR.exists():
        preferred_templates = sorted(
            ADMIN_DUMPTRUCK_TEMPLATE_DIR.glob("Административный отчет *.xlsx"),
            key=_admin_dumptruck_template_sort_key,
            reverse=True,
        )
        for candidate in preferred_templates:
            if candidate not in candidates:
                candidates.append(candidate)
        for candidate in sorted(
            ADMIN_DUMPTRUCK_TEMPLATE_DIR.glob("*.xlsx"),
            key=lambda path: (path.stat().st_mtime, path.name),
            reverse=True,
        ):
            if candidate not in candidates:
                candidates.append(candidate)
    if ADMIN_DUMPTRUCK_REPORT_DIR.exists():
        preferred = sorted(
            ADMIN_DUMPTRUCK_REPORT_DIR.glob("Административный отчет *.xlsx"),
            key=_admin_dumptruck_template_sort_key,
            reverse=True,
        )
        candidates.extend(preferred)
        for candidate in sorted(
            ADMIN_DUMPTRUCK_REPORT_DIR.glob("*.xlsx"),
            key=lambda path: (path.stat().st_mtime, path.name),
            reverse=True,
        ):
            if candidate not in candidates:
                candidates.append(candidate)
    return candidates


def _resolve_admin_dumptruck_template() -> Path:
    for candidate in _admin_dumptruck_template_candidates():
        if candidate.exists():
            return candidate.resolve()
    if ADMIN_DUMPTRUCK_TEMPLATE_ENV:
        return Path(ADMIN_DUMPTRUCK_TEMPLATE_ENV).expanduser().resolve()
    return ADMIN_DUMPTRUCK_DEFAULT_TEMPLATE.resolve()


def _generate_admin_dumptruck_pipeline_xlsx(report_date: date_cls) -> tuple[bytes, str, str]:
    template = _resolve_admin_dumptruck_template()
    with tempfile.TemporaryDirectory(prefix="vsm-admin-dumptruck-") as tmp_dir:
        output = Path(tmp_dir) / "admin_dumptruck_report.xlsx"
        _run_admin_dumptruck_pipeline(report_date, template, output)
        data = _read_output_file(output)
    return (
        data,
        f"VSM_Admin_Dumptruck_{report_date.isoformat()}.xlsx",
        f"Административный отчет {report_date.isoformat()}.xlsx",
    )


def _resolve_admin_dumptruck_runner() -> tuple[str, Path]:
    if ADMIN_DUMPTRUCK_WRAPPER.exists():
        return "wrapper", ADMIN_DUMPTRUCK_WRAPPER
    if ADMIN_DUMPTRUCK_GENERATOR.exists():
        return "generator", ADMIN_DUMPTRUCK_GENERATOR
    raise HTTPException(503, "Admin dumptruck pipeline is not available on this server")


def _run_admin_dumptruck_pipeline(report_date: date_cls, template: Path, output: Path) -> str:
    runner_kind, runner = _resolve_admin_dumptruck_runner()
    if not template.exists():
        raise HTTPException(503, "Admin dumptruck template is not available on this server")
    json_summary = output.with_suffix(".summary.json")
    command = [
        "bash" if runner_kind == "wrapper" else sys.executable,
        str(runner),
        "--date",
        report_date.isoformat(),
        "--template",
        str(template),
        "--output",
        str(output),
        "--json-summary",
        str(json_summary),
    ]
    pythonpath_parts = [part for part in ["/app", os.environ.get("PYTHONPATH", "")] if part]
    return _run_report_pipeline(
        command,
        runner.parent,
        timeout=REPORT_PIPELINE_XLSX_TIMEOUT,
        extra_env={"PYTHONPATH": os.pathsep.join(pythonpath_parts)},
        low_priority=True,
    )


def _ensure_cached_admin_dumptruck_xlsx_artifact(
    *,
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    template: Path,
    fingerprint: str,
    artifact: Path,
    meta_path: Path,
    lock_path: Path,
) -> Path:
    if not REPORT_XLSX_CACHE_ENABLED:
        raise HTTPException(503, "XLSX cache is disabled; background export requires cache")
    if _cached_xlsx_ready(artifact, meta_path, fingerprint):
        return artifact

    artifact.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+") as lock_fh:
        fcntl.flock(lock_fh, fcntl.LOCK_EX)
        try:
            if _cached_xlsx_ready(artifact, meta_path, fingerprint):
                return artifact
            with tempfile.TemporaryDirectory(prefix=f"vsm-{report_key}-report-") as tmp_dir:
                tmp_output = Path(tmp_dir) / "admin_dumptruck_report.xlsx"
                stdout = _run_admin_dumptruck_pipeline(d_to, template, tmp_output)
                _read_output_file(tmp_output)
                tmp_cache = artifact.with_suffix(artifact.suffix + ".tmp")
                shutil.copyfile(tmp_output, tmp_cache)
                tmp_cache.replace(artifact)
                _write_cached_xlsx_metadata(
                    meta_path,
                    report_key=report_key,
                    d_from=d_from,
                    d_to=d_to,
                    fingerprint=fingerprint,
                    artifact_path=artifact,
                    stdout=stdout,
                )
                return artifact
        finally:
            fcntl.flock(lock_fh, fcntl.LOCK_UN)


