def _xlsx_pipeline_job_info(
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    filter_env: Optional[dict[str, str]] = None,
    *,
    section_codes: Optional[list[str]] = None,
    general_equipment_plan_counts: Optional[dict[str, dict[str, dict[str, float]]]] = None,
    cumulative_as_of_end_date: bool = False,
) -> dict:
    if report_key == "admin_dumptruck":
        d_from = d_to
        template = _resolve_admin_dumptruck_template()
        filename_label = "Административный отчет"
        script = None
        try:
            _, script = _resolve_admin_dumptruck_runner()
        except HTTPException as exc:
            raise HTTPException(exc.status_code, str(exc.detail))
        if not template.exists():
            raise HTTPException(503, f"{filename_label} template is not available on this server")
        fingerprint_env = dict(filter_env or {})
        if ADMIN_DUMPTRUCK_GENERATOR.exists():
            fingerprint_env["VSM_ADMIN_DUMPTRUCK_GENERATOR_SHA256"] = _sha256_file(ADMIN_DUMPTRUCK_GENERATOR)
        fingerprint = _xlsx_report_cache_fingerprint(report_key, d_from, d_to, script, template, filter_env=fingerprint_env)
        artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, d_from, d_to, fingerprint)
        job_payload = {
            "report_key": report_key,
            "date_from": d_from.isoformat(),
            "date_to": d_to.isoformat(),
            "script": str(script),
            "template": str(template),
            "output_name": "admin_dumptruck_report.xlsx",
            "filename_ascii": f"VSM_Admin_Dumptruck_{d_to.isoformat()}.xlsx",
            "filename_utf8": f"{filename_label} {d_to.isoformat()}.xlsx",
            "filter_env": filter_env or {},
            "fingerprint": fingerprint,
            "artifact": str(artifact),
            "meta_path": str(meta_path),
            "lock_path": str(lock_path),
            "media_type": XLSX_MEDIA_TYPE,
            "estimated_total_seconds": _estimate_pipeline_runtime_seconds(report_key, d_from, d_to),
            "stage_label": "Генерация XLSX",
        }
        job_id_raw = json.dumps(job_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        job_payload["job_id"] = hashlib.sha256(job_id_raw.encode("utf-8")).hexdigest()[:32]
        return job_payload

    if report_key == "general_exact_xlsx":
        template = _resolve_general_analytics_template()
        filename_label = "Генеральный отчет xlsx"
        if not template.exists():
            raise HTTPException(503, f"{filename_label} template is not available on this server")
        script = Path(__file__).resolve()
        fingerprint_env = dict(filter_env or {})
        fingerprint_env["VSM_GENERAL_EXACT_SECTION_CODES_JSON"] = json.dumps(section_codes or [], ensure_ascii=False)
        fingerprint_env["VSM_GENERAL_EXACT_MANUAL_PLAN_JSON"] = json.dumps(general_equipment_plan_counts or {}, ensure_ascii=False, sort_keys=True)
        fingerprint = _xlsx_report_cache_fingerprint(report_key, d_from, d_to, script, template, filter_env=fingerprint_env)
        artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, d_from, d_to, fingerprint)
        job_payload = {
            "report_key": report_key,
            "date_from": d_from.isoformat(),
            "date_to": d_to.isoformat(),
            "script": str(script),
            "template": str(template),
            "output_name": "general_exact_report.xlsx",
            "filename_ascii": f"VSM_General_Analytics_{d_to.isoformat()}.xlsx",
            "filename_utf8": f"{filename_label} {d_to.isoformat()}.xlsx",
            "filter_env": filter_env or {},
            "fingerprint": fingerprint,
            "artifact": str(artifact),
            "meta_path": str(meta_path),
            "lock_path": str(lock_path),
            "media_type": XLSX_MEDIA_TYPE,
            "section_codes": list(section_codes or []),
            "general_equipment_plan_counts": general_equipment_plan_counts or {},
            "estimated_total_seconds": _estimate_pipeline_runtime_seconds(report_key, d_from, d_to),
            "stage_label": "Генерация XLSX",
        }
        job_id_raw = json.dumps(job_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        job_payload["job_id"] = hashlib.sha256(job_id_raw.encode("utf-8")).hexdigest()[:32]
        return job_payload

    if report_key == "financial_plan_fact":
        script = FINANCIAL_PLAN_FACT_REPORT_SCRIPT
        if not script.exists():
            raise HTTPException(503, "Financial plan-fact report pipeline is not available on this server")
        fingerprint_env = dict(filter_env or {})
        fingerprint_env["VSM_FINANCIAL_PLAN_FACT_SECTION_CODES_JSON"] = json.dumps(section_codes or [], ensure_ascii=False)
        fingerprint = _xlsx_report_cache_fingerprint(report_key, d_from, d_to, script, script, filter_env=fingerprint_env)
        artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, d_from, d_to, fingerprint)
        section_label = _simple_section_report_filename_section_label(section_codes)
        job_payload = {
            "report_key": report_key,
            "date_from": d_from.isoformat(),
            "date_to": d_to.isoformat(),
            "script": str(script),
            "template": str(script),
            "output_name": "financial_plan_fact.xlsx",
            "filename_ascii": f"VSM_Financial_Plan_Fact_{d_from.isoformat()}_{d_to.isoformat()}.xlsx",
            "filename_utf8": f"Финансовый план-факт {section_label} {d_from.isoformat()} - {d_to.isoformat()}.xlsx",
            "filter_env": filter_env or {},
            "fingerprint": fingerprint,
            "artifact": str(artifact),
            "meta_path": str(meta_path),
            "lock_path": str(lock_path),
            "media_type": XLSX_MEDIA_TYPE,
            "section_codes": list(section_codes or []),
            "estimated_total_seconds": _estimate_pipeline_runtime_seconds(report_key, d_from, d_to),
            "stage_label": "Генерация XLSX",
        }
        job_id_raw = json.dumps(job_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        job_payload["job_id"] = hashlib.sha256(job_id_raw.encode("utf-8")).hexdigest()[:32]
        return job_payload

    spec = XLSX_PIPELINE_REPORT_SPECS.get(report_key)
    if not spec:
        raise HTTPException(400, f"XLSX background export is not supported for {report_key}")
    script = DIM_PIPELINE_DIR / str(spec["script_name"])
    template = Path(spec["template"])
    filename_label = str(spec["filename_label"])
    if not script.exists():
        raise HTTPException(503, f"{filename_label} pipeline is not available on this server")
    if not template.exists():
        raise HTTPException(503, f"{filename_label} template is not available on this server")
    cumulative_mode = bool(cumulative_as_of_end_date and report_key in CUMULATIVE_AS_OF_END_DATE_XLSX_REPORT_KEYS)
    effective_from, effective_to = _xlsx_effective_period_for_cumulative_as_of(
        report_key,
        d_from,
        d_to,
        cumulative_mode,
    )
    effective_filter_env = dict(filter_env or {})
    if cumulative_mode:
        effective_filter_env.update(_report_option_env(cumulative_as_of_end_date=True))
    fingerprint = _xlsx_report_cache_fingerprint(
        report_key,
        effective_from,
        effective_to,
        script,
        template,
        filter_env=effective_filter_env or None,
    )
    artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, effective_from, effective_to, fingerprint)
    filename_ascii, filename_utf8 = _dim_like_pipeline_filenames(
        filename_prefix=str(spec["filename_prefix"]),
        filename_label=filename_label,
        d_from=d_from,
        d_to=d_to,
        cumulative_as_of_end_date=cumulative_mode,
    )
    job_payload = {
        "report_key": report_key,
        "date_from": effective_from.isoformat(),
        "date_to": effective_to.isoformat(),
        "request_date_from": d_from.isoformat(),
        "request_date_to": d_to.isoformat(),
        "script": str(script),
        "template": str(template),
        "output_name": str(spec["output_name"]),
        "filename_ascii": filename_ascii,
        "filename_utf8": filename_utf8,
        "filter_env": effective_filter_env,
        "fingerprint": fingerprint,
        "artifact": str(artifact),
        "meta_path": str(meta_path),
        "lock_path": str(lock_path),
        "media_type": XLSX_MEDIA_TYPE,
        "cumulative_as_of_end_date": cumulative_mode,
        "cumulative_end_date": d_to.isoformat() if cumulative_mode else None,
        "estimated_total_seconds": _estimate_pipeline_runtime_seconds(report_key, effective_from, effective_to),
        "stage_label": "Генерация XLSX",
    }
    job_id_raw = json.dumps(job_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    job_payload["job_id"] = hashlib.sha256(job_id_raw.encode("utf-8")).hexdigest()[:32]
    return job_payload


def _xlsx_export_job_response(job: dict) -> dict:
    status = str(job.get("status") or "queued")
    job_id = str(job.get("job_id") or "")
    artifact = Path(str(job.get("artifact") or ""))
    size = artifact.stat().st_size if status == "ready" and artifact.exists() else None
    progress = _progress_snapshot(
        status=status,
        started_at=job.get("started_at") or job.get("created_at"),
        finished_at=job.get("finished_at"),
        estimated_total_seconds=job.get("estimated_total_seconds"),
        current_step_started_at=job.get("started_at") or job.get("created_at"),
        current_step_estimated_seconds=job.get("estimated_total_seconds"),
    )
    return {
        "job_id": job_id,
        "status": status,
        "ready": status == "ready",
        "report_key": job.get("report_key"),
        "date_from": job.get("date_from"),
        "date_to": job.get("date_to"),
        "filename": job.get("filename_utf8"),
        "size_bytes": size,
        "message": job.get("message"),
        "error": job.get("error"),
        "stage_label": job.get("stage_label"),
        "created_at": job.get("created_at"),
        "started_at": job.get("started_at"),
        "finished_at": job.get("finished_at"),
        **progress,
        "download_url": f"/api/wip/generator/pipeline-export-jobs/{job_id}/download" if status == "ready" else None,
    }


def _xlsx_export_job_update(job_id: str, **patch) -> None:
    with XLSX_EXPORT_JOBS_LOCK:
        job = XLSX_EXPORT_JOBS.get(job_id)
        if not job:
            return
        job.update(patch)


def _ensure_xlsx_export_job_artifact(job: dict) -> Path:
    report_key = str(job.get("report_key") or "")
    if report_key == "statements_general_workbook":
        return _ensure_cached_statement_general_workbook_artifact(
            report_key=report_key,
            month=str(job.get("month") or job.get("date_from") or ""),
            section=str(job.get("section") or "") or None,
            object_type=str(job.get("object_type") or "") or None,
            object_id=str(job.get("object_id") or "") or None,
            q=str(job.get("q") or "") or None,
            group_mode=str(job.get("group_mode") or "section"),
            hide_zero_works=bool(job.get("hide_zero_works")),
            hide_zero_objects=bool(job.get("hide_zero_objects")),
            only_with_plan=bool(job.get("only_with_plan")),
            only_missing_rate=bool(job.get("only_missing_rate")),
            actual_section_binding=bool(job.get("actual_section_binding")),
            d_from=date_cls.fromisoformat(str(job["date_from"])),
            d_to=date_cls.fromisoformat(str(job["date_to"])),
            fingerprint=str(job["fingerprint"]),
            artifact=Path(str(job["artifact"])),
            meta_path=Path(str(job["meta_path"])),
            lock_path=Path(str(job["lock_path"])),
        )
    if report_key == "general_exact_xlsx":
        return _ensure_cached_general_exact_xlsx_artifact(
            report_key=report_key,
            d_from=date_cls.fromisoformat(str(job["date_from"])),
            d_to=date_cls.fromisoformat(str(job["date_to"])),
            template=Path(str(job["template"])),
            fingerprint=str(job["fingerprint"]),
            artifact=Path(str(job["artifact"])),
            meta_path=Path(str(job["meta_path"])),
            lock_path=Path(str(job["lock_path"])),
            section_codes=list(job.get("section_codes") or []),
            general_equipment_plan_counts=dict(job.get("general_equipment_plan_counts") or {}),
        )
    if report_key == "admin_dumptruck":
        return _ensure_cached_admin_dumptruck_xlsx_artifact(
            report_key=report_key,
            d_from=date_cls.fromisoformat(str(job["date_from"])),
            d_to=date_cls.fromisoformat(str(job["date_to"])),
            template=Path(str(job["template"])),
            fingerprint=str(job["fingerprint"]),
            artifact=Path(str(job["artifact"])),
            meta_path=Path(str(job["meta_path"])),
            lock_path=Path(str(job["lock_path"])),
        )
    if report_key == "financial_plan_fact":
        return _ensure_cached_financial_plan_fact_xlsx_artifact(
            report_key=report_key,
            d_from=date_cls.fromisoformat(str(job["date_from"])),
            d_to=date_cls.fromisoformat(str(job["date_to"])),
            fingerprint=str(job["fingerprint"]),
            artifact=Path(str(job["artifact"])),
            meta_path=Path(str(job["meta_path"])),
            lock_path=Path(str(job["lock_path"])),
            section_codes=list(job.get("section_codes") or []),
        )

    cumulative_end_raw = job.get("cumulative_end_date")
    cumulative_end_date = date_cls.fromisoformat(str(cumulative_end_raw)) if cumulative_end_raw else None
    return _ensure_cached_xlsx_artifact(
        report_key=report_key,
        d_from=date_cls.fromisoformat(str(job["date_from"])),
        d_to=date_cls.fromisoformat(str(job["date_to"])),
        script=Path(str(job["script"])),
        template=Path(str(job["template"])),
        output_name=str(job["output_name"]),
        filter_env=dict(job.get("filter_env") or {}),
        fingerprint=str(job["fingerprint"]),
        artifact=Path(str(job["artifact"])),
        meta_path=Path(str(job["meta_path"])),
        lock_path=Path(str(job["lock_path"])),
        cumulative_end_date=cumulative_end_date,
    )


def _run_xlsx_export_job(job_id: str) -> None:
    with XLSX_EXPORT_JOBS_LOCK:
        job = dict(XLSX_EXPORT_JOBS.get(job_id) or {})
        if not job:
            return
        XLSX_EXPORT_JOBS[job_id].update({
            "status": "running",
            "message": "Файл ожидает свободный слот генерации или генерируется на сервере",
            "stage_label": "Генерация файла",
            "started_at": datetime.now(timezone.utc).isoformat(),
        })
    try:
        artifact = _ensure_xlsx_export_job_artifact(job)
        _xlsx_export_job_update(
            job_id,
            status="ready",
            artifact=str(artifact),
            message="Файл готов к скачиванию",
            error=None,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
    except HTTPException as exc:
        REPORT_PIPELINE_LOG.warning(
            "xlsx_export_job_http_error job_id=%s report_key=%s detail=%r",
            job_id,
            job.get("report_key"),
            exc.detail,
        )
        _xlsx_export_job_update(
            job_id,
            status="error",
            message="Не удалось сгенерировать файл",
            error=str(exc.detail),
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
    except Exception as exc:
        REPORT_PIPELINE_LOG.exception(
            "xlsx_export_job_failed job_id=%s report_key=%s",
            job_id,
            job.get("report_key"),
        )
        _xlsx_export_job_update(
            job_id,
            status="error",
            message="Не удалось сгенерировать файл",
            error=str(exc),
            finished_at=datetime.now(timezone.utc).isoformat(),
        )


