def _general_analytics_template_candidates(filename: str) -> list[Path]:
    here = Path(__file__).resolve()
    return [
        REPORT_TEMPLATE_DIR / filename,
        here.parent / "public_templates" / filename,
        here.parent.parent / "frontend" / "public" / "templates" / filename,
        here.parent.parent / "frontend" / "dist" / "templates" / filename,
        Path("/opt/vsm/vsm-dashboard/frontend/public/templates") / filename,
        Path("/opt/vsm/vsm-dashboard/frontend/dist/templates") / filename,
    ]


def _resolve_general_analytics_template() -> Path:
    if GENERAL_ANALYTICS_TEMPLATE_ENV:
        return Path(GENERAL_ANALYTICS_TEMPLATE_ENV)
    ready_candidates = _general_analytics_template_candidates(GENERAL_ANALYTICS_TEMPLATE_FILENAME)
    for candidate in ready_candidates:
        if candidate.exists():
            return candidate
    legacy_candidates = _general_analytics_template_candidates(GENERAL_ANALYTICS_LEGACY_TEMPLATE_FILENAME)
    for candidate in legacy_candidates:
        if candidate.exists():
            return candidate
    return ready_candidates[0]


def _is_ready_general_analytics_template(ws) -> bool:
    if str(ws.cell(row=3, column=2).value or "").strip().upper() != "ДЕНЬ":
        return False
    period_rows = [
        row_idx
        for row_idx in range(1, ws.max_row + 1)
        if str(ws.cell(row=row_idx, column=2).value or "").strip() == "Текущий день"
    ]
    return len(period_rows) >= 2


def _section_ui_label(code: str) -> str:
    match = re.search(r"(\d+)", code or "")
    return f"Участок №{match.group(1)}" if match else (code or "Без участка")


def _general_target_row(source_row: int) -> Optional[int]:
    removed = 0
    for start, end in GENERAL_ANALYTICS_DELETED_SOURCE_RANGES:
        if start <= source_row <= end:
            return None
        if source_row > end:
            removed += end - start + 1
    return source_row - removed


def _first_general_top_body_row(ws) -> Optional[int]:
    for row_idx in range(1, ws.max_row + 1):
        if _general_period_key(ws.cell(row=row_idx, column=2).value) and _normalize_general_label(ws.cell(row=row_idx, column=3).value) == "№ участка":
            return row_idx
    return None


def _find_general_top_quarry_label_rows(ws) -> list[int]:
    """Find top quarry/day-night row anchors from the template geometry.

    The owner template is the source of truth. The 09.06 template moved the
    first report body block down and added a final visible top-table row; using
    the old hard-coded source rows silently wrote the last rows into the wrong
    labels. Scan visible labels before the first body period row and fall back
    to legacy source rows only for minimal synthetic tests/templates.
    """
    body_row = _first_general_top_body_row(ws)
    max_row = (body_row - 1) if body_row else min(ws.max_row, _general_target_row(42) or 42)
    rows: list[int] = []
    for row_idx in range(7, max_row + 1):
        if _normalize_general_label(ws.cell(row=row_idx, column=4).value):
            rows.append(row_idx)
    if rows:
        return rows[:GENERAL_REPORT_TOP_QUARRY_ROW_LIMIT]
    return [source_row for source_row in range(7, 42, 2) if _general_target_row(source_row) is not None]


def _find_general_metadata_row(ws, label: str) -> Optional[int]:
    needle = _normalize_general_label(label)
    if not needle:
        return None
    body_row = _first_general_top_body_row(ws)
    max_row = min(ws.max_row, (body_row + 12) if body_row else 90)
    for row_idx in range(1, max_row + 1):
        if _normalize_general_label(ws.cell(row=row_idx, column=GENERAL_ANALYTICS_VALUE_START_COL).value) == needle:
            return row_idx
    return None


def _general_output_max_row() -> int:
    return _general_target_row(GENERAL_ANALYTICS_SOURCE_LAST_ROW) or GENERAL_ANALYTICS_SOURCE_LAST_ROW


def _general_date_label(value: date_cls) -> str:
    return value.strftime("%d.%m.%Y")


def _general_periods(report_date: date_cls) -> dict[str, tuple[date_cls, date_cls]]:
    week_start = report_date - timedelta(days=report_date.weekday())
    month_start = report_date.replace(day=1)
    return {
        "day": (report_date, report_date),
        "week": (week_start, report_date),
        "month": (month_start, report_date),
        "total": (PROJECT_START_DATE, report_date),
    }


def _section_values() -> dict[str, float]:
    return {code: 0.0 for code in GENERAL_ANALYTICS_SECTION_CODES}


def _add_section_value(values: dict[str, float], section_code: Optional[str], amount: float) -> None:
    section = _merge_section(section_code)
    if section in values:
        values[section] += float(amount or 0)


def _sum_section_values(*items: dict[str, float]) -> dict[str, float]:
    out = _section_values()
    for item in items:
        for code in GENERAL_ANALYTICS_SECTION_CODES:
            out[code] += float((item or {}).get(code) or 0)
    return out


def _section_values_has_data(values: dict[str, float]) -> bool:
    return any(abs(float((values or {}).get(code) or 0)) >= 0.0005 for code in GENERAL_ANALYTICS_SECTION_CODES)


def _subtract_section_values(left: dict[str, float], right: dict[str, float]) -> dict[str, float]:
    out = _section_values()
    for code in GENERAL_ANALYTICS_SECTION_CODES:
        out[code] = float((left or {}).get(code) or 0) - float((right or {}).get(code) or 0)
    return out


def _floor_section_values(values: dict[str, float], floor: float = 0.0) -> dict[str, float]:
    out = _section_values()
    limit = float(floor)
    for code in GENERAL_ANALYTICS_SECTION_CODES:
        out[code] = max(limit, float((values or {}).get(code) or 0))
    return out


def _clean_report_number(value: float):
    if abs(value) < 0.0005:
        return 0
    rounded = round(float(value), 3)
    if abs(rounded - round(rounded)) < 0.0005:
        return int(round(rounded))
    return rounded


def _set_general_cell_value(ws, row: int, column: int, value) -> None:
    cell = ws.cell(row=row, column=column)
    if cell.__class__.__name__ == "MergedCell":
        return
    cell.value = value




def _copy_general_row_style(ws, from_row: int, to_row: int) -> None:
    if from_row < 1 or to_row < 1 or from_row > ws.max_row:
        return
    ws.row_dimensions[to_row].height = ws.row_dimensions[from_row].height
    for col_idx in range(1, 14):
        src = ws.cell(row=from_row, column=col_idx)
        dst = ws.cell(row=to_row, column=col_idx)
        if src.has_style:
            dst._style = copy(src._style)
        if src.number_format:
            dst.number_format = src.number_format
        if src.alignment:
            dst.alignment = copy(src.alignment)
        if src.font:
            dst.font = copy(src.font)
        if src.fill:
            dst.fill = copy(src.fill)
        if src.border:
            dst.border = copy(src.border)


def _restore_general_analysis_rows(ws) -> None:
    """Restore rows that are absent from the compact template but exist in the reference report."""
    if str(ws.cell(row=3, column=2).value or "").strip().upper() == "ДЕНЬ":
        return
    if str(ws.cell(row=2, column=2).value or "").strip() != "Текущий день":
        return

    ws.insert_rows(2, 43)
    for row_idx in range(2, 45):
        _copy_general_row_style(ws, 45, row_idx)

    ws.insert_rows(46, 7)
    for row_idx in range(46, 53):
        _copy_general_row_style(ws, 53, row_idx)

    for merged in list(ws.merged_cells.ranges):
        if merged.min_row >= 2 and merged.max_row <= 44:
            ws.unmerge_cells(str(merged))

    _set_general_cell_value(ws, 3, 2, "ДЕНЬ")
    _set_general_cell_value(ws, 3, 3, "НОЧЬ")
    _set_general_cell_value(ws, 3, 4, "Итого")
    _set_general_cell_value(ws, 3, 5, "Всего за день")
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=6):
        _set_general_cell_value(ws, 3, idx, section_code.replace("UCH_", ""))
    _set_general_cell_value(ws, 4, 4, "ИТОГО")


def _write_section_values_at_row(
    ws,
    row: int,
    values: dict[str, float],
    total_override: Optional[float] = None,
) -> None:
    clean_values = {code: float((values or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES}
    total_value = float(total_override) if total_override is not None else sum(clean_values.values())
    _set_general_cell_value(ws, row, GENERAL_ANALYTICS_VALUE_START_COL, _clean_report_number(total_value))
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, _clean_report_number(clean_values.get(section_code, 0)))


def _write_optional_section_values_at_row(ws, row: int, values: Optional[dict[str, float]]) -> None:
    provided: dict[str, float] = {}
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        raw = (values or {}).get(section_code)
        if raw is None:
            continue
        provided[section_code] = float(raw)
    _write_section_values_at_row(ws, row, provided)


def _normalize_general_equipment_plan_counts(
    raw: Optional[dict[str, dict[str, dict[str, float]]]],
) -> dict[str, dict[str, dict[str, float]]]:
    cleaned: dict[str, dict[str, dict[str, float]]] = {}
    if not raw:
        return cleaned
    for equipment_key in GENERAL_REPORT_MANUAL_PLAN_EQUIPMENT:
        equipment_payload = raw.get(equipment_key)
        if not isinstance(equipment_payload, dict):
            continue
        cleaned_equipment: dict[str, dict[str, float]] = {}
        for shift_key in GENERAL_REPORT_MANUAL_PLAN_SHIFTS:
            shift_payload = equipment_payload.get(shift_key)
            if not isinstance(shift_payload, dict):
                continue
            cleaned_shift: dict[str, float] = {}
            for section_code in GENERAL_ANALYTICS_SECTION_CODES:
                if section_code not in shift_payload:
                    continue
                raw_value = shift_payload.get(section_code)
                if raw_value is None:
                    continue
                try:
                    value = float(str(raw_value).strip().replace(",", "."))
                except (TypeError, ValueError):
                    continue
                if value < 0:
                    continue
                cleaned_shift[section_code] = value
            if cleaned_shift:
                cleaned_equipment[shift_key] = cleaned_shift
        if cleaned_equipment:
            cleaned[equipment_key] = cleaned_equipment
    return cleaned


def _write_section_text_values_at_row(ws, row: int, values: dict[str, object]) -> None:
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, values.get(section_code))


def _read_section_values_at_row(ws, row: int) -> dict[str, float]:
    values = _section_values()
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        raw = ws.cell(row=row, column=idx).value
        try:
            values[section_code] = float(raw or 0)
        except (TypeError, ValueError):
            values[section_code] = 0.0
    return values


def _write_general_percent_values_at_row(ws, row: int, values: dict[str, float]) -> None:
    clean_values = {code: float((values or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES}
    present = [value for value in clean_values.values() if abs(value) > 0.0005]
    avg = sum(present) / len(present) if present else 0
    _set_general_cell_value(ws, row, GENERAL_ANALYTICS_VALUE_START_COL, _clean_report_number(avg))
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, _clean_report_number(clean_values.get(section_code, 0)))


def _general_ratio_values(numerator: dict[str, float], denominator: dict[str, float]) -> dict[str, float]:
    values = _section_values()
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        denom = float((denominator or {}).get(section_code) or 0)
        values[section_code] = float((numerator or {}).get(section_code) or 0) / denom if denom > 0 else 0
    return values


def _write_general_ratio_values_at_row(
    ws,
    row: int,
    numerator: dict[str, float],
    denominator: dict[str, float],
) -> None:
    values = _general_ratio_values(numerator, denominator)
    total_denominator = sum(float((denominator or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES)
    total_numerator = sum(float((numerator or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES)
    _set_general_cell_value(
        ws,
        row,
        GENERAL_ANALYTICS_VALUE_START_COL,
        _clean_report_number(total_numerator / total_denominator if total_denominator > 0 else 0),
    )
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, _clean_report_number(values.get(section_code, 0)))


def _write_plan_from_counts_at_rows(
    ws,
    day_counts: dict[str, float],
    night_counts: dict[str, float],
    norm_by_section: dict[str, float],
    total_row: int,
    day_row: int,
    night_row: int,
    total_counts: Optional[dict[str, float]] = None,
) -> dict[str, float]:
    total_values, day_values, night_values = _plan_from_counts(day_counts, night_counts, norm_by_section, total_counts)
    _write_section_values_at_row(ws, total_row, total_values)
    _write_section_values_at_row(ws, day_row, day_values)
    _write_section_values_at_row(ws, night_row, night_values)
    return total_values


def _write_plan_day_night_from_counts_at_rows(
    ws,
    day_counts: dict[str, float],
    night_counts: dict[str, float],
    norm_by_section: dict[str, float],
    day_row: int,
    night_row: int,
    total_counts: Optional[dict[str, float]] = None,
) -> dict[str, float]:
    total_values, day_values, night_values = _plan_from_counts(day_counts, night_counts, norm_by_section, total_counts)
    _write_section_values_at_row(ws, day_row, day_values)
    _write_section_values_at_row(ws, night_row, night_values)
    return total_values


def _write_section_text_values(ws, source_row: int, values: dict[str, object]) -> None:
    row = _general_target_row(source_row)
    if row is None:
        return
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, values.get(section_code))


def _read_general_section_values(ws, source_row: int) -> dict[str, float]:
    row = _general_target_row(source_row)
    values = _section_values()
    if row is None:
        return values
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        raw = ws.cell(row=row, column=idx).value
        try:
            values[section_code] = float(raw or 0)
        except (TypeError, ValueError):
            values[section_code] = 0.0
    return values


def _write_general_percent_values(ws, source_row: int, values: dict[str, float]) -> None:
    row = _general_target_row(source_row)
    if row is None:
        return
    clean_values = {code: float((values or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES}
    present = [value for value in clean_values.values() if abs(value) > 0.0005]
    avg = sum(present) / len(present) if present else 0
    _set_general_cell_value(ws, row, GENERAL_ANALYTICS_VALUE_START_COL, _clean_report_number(avg))
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, _clean_report_number(clean_values.get(section_code, 0)))


def _general_section_num(section_code: str) -> Optional[int]:
    match = re.search(r"(\d+)", section_code or "")
    return int(match.group(1)) if match else None

def _write_section_values(ws, source_row: int, values: dict[str, float]) -> None:
    row = _general_target_row(source_row)
    if row is None:
        return
    clean_values = {code: float((values or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES}
    _set_general_cell_value(ws, row, GENERAL_ANALYTICS_VALUE_START_COL, _clean_report_number(sum(clean_values.values())))
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        _set_general_cell_value(ws, row, idx, _clean_report_number(clean_values.get(section_code, 0)))


def _blank_general_value_cells(ws) -> None:
    metadata_labels = {_normalize_general_label(label) for label in GENERAL_DUMP_TRUCK_METADATA_SOURCE_ROWS.values()}
    for row_idx in range(1, ws.max_row + 1):
        marker_c = str(ws.cell(row=row_idx, column=3).value or "").strip()
        marker_b = str(ws.cell(row=row_idx, column=2).value or "").strip()
        marker_e = _normalize_general_label(ws.cell(row=row_idx, column=GENERAL_ANALYTICS_VALUE_START_COL).value)
        if marker_c == "№ Участка" or marker_c.startswith("Плановое количество") or marker_b == "ДЕНЬ":
            continue
        start_col = GENERAL_ANALYTICS_VALUE_START_COL + 1 if marker_e in metadata_labels else GENERAL_ANALYTICS_VALUE_START_COL
        for col_idx in range(start_col, 14):
            _set_general_cell_value(ws, row_idx, col_idx, None)


def _rewrite_general_report_dates(ws, report_date: date_cls) -> None:
    date_label = _general_date_label(report_date)
    week_start = report_date - timedelta(days=report_date.weekday())
    week_label = f"с {week_start.strftime('%d.%m')} по {report_date.strftime('%d.%m')}"
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=13):
        for cell in row:
            value = cell.value
            if not isinstance(value, str) or value.startswith("="):
                continue
            updated = value.replace("ДД.ММ.ГГГГ", date_label).replace("22.05.2026", date_label)
            updated = re.sub(r"с \d{2}\.\d{2} по \d{2}\.\d{2}", week_label, updated)
            cell.value = updated
    ws["E1"] = date_label


def _trim_general_analysis_sheet(ws) -> None:
    output_max_row = _general_output_max_row()
    for merged in list(ws.merged_cells.ranges):
        if merged.max_col > 13 or merged.max_row > output_max_row:
            ws.unmerge_cells(str(merged))
    if ws.max_column > 13:
        ws.delete_cols(14, ws.max_column - 13)
    if ws.max_row > output_max_row:
        ws.delete_rows(output_max_row + 1, ws.max_row - output_max_row)
    for row_idx in list(ws.row_dimensions):
        if row_idx > output_max_row:
            del ws.row_dimensions[row_idx]
    for cell_key in list(ws._cells):
        row_idx, col_idx = cell_key
        if row_idx > output_max_row or col_idx > 13:
            del ws._cells[cell_key]
    ws.print_area = f"A1:M{output_max_row}"
    ws.page_setup.orientation = ws.ORIENTATION_PORTRAIT
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0


