def _ensure_dashboard_settings_schema() -> None:
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS dashboard_settings (
                      key text PRIMARY KEY,
                      payload jsonb NOT NULL,
                      updated_by text,
                      updated_at timestamptz NOT NULL DEFAULT now()
                    )
                    """
                )
    finally:
        conn.close()


def _general_clean_string_list(values: object, limit: int = 80) -> list[str]:
    if not isinstance(values, list):
        return []
    out: list[str] = []
    seen: set[str] = set()
    for value in values[:limit]:
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        out.append(text)
        seen.add(text)
    return out


def _general_clean_bool(value: object, default: bool = True) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return default
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "y", "on", "да"}:
        return True
    if text in {"0", "false", "no", "n", "off", "нет"}:
        return False
    return default


def _general_clean_id(value: object, fallback: str) -> str:
    text = re.sub(r"[^a-zA-Z0-9_\-]+", "_", str(value or "").strip())[:80].strip("_")
    return text or fallback


def _general_row_filters(raw: object) -> dict:
    return raw if isinstance(raw, dict) else {}


