def _normalize_general_report_work_rows(rows: object) -> list[dict]:
    raw_by_code = {}
    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, dict):
                continue
            code = str(row.get("code") or "").strip()
            if not code and str(row.get("id") or "").startswith("work_"):
                code = str(row.get("id") or "")[5:]
            if code:
                raw_by_code[code] = row
    normalized: list[dict] = []
    for default in _default_general_report_work_rows():
        raw = raw_by_code.get(default["code"], {})
        filters = _general_row_filters(raw.get("filters"))
        normalized.append({
            "code": default["code"],
            "label": str(raw.get("label") or default["label"]).strip()[:160],
            "enabled": _general_clean_bool(raw.get("enabled"), default["enabled"]),
            "include_in_totals": _general_clean_bool(raw.get("include_in_totals"), default["include_in_totals"]),
            "tags": _general_clean_string_list(raw["tags"]) if "tags" in raw else (_general_clean_string_list(filters.get("tags")) if "tags" in filters else default["tags"]),
            "object_type_codes": _general_clean_string_list(raw["object_type_codes"]) if "object_type_codes" in raw else (_general_clean_string_list(filters.get("object_type_codes")) if "object_type_codes" in filters else default["object_type_codes"]),
            "object_codes": _general_clean_string_list(raw["object_codes"]) if "object_codes" in raw else (_general_clean_string_list(filters.get("object_codes")) if "object_codes" in filters else default["object_codes"]),
            "source_buckets": _general_clean_string_list(raw["source_buckets"]) if "source_buckets" in raw else _general_clean_string_list(filters.get("source_buckets")),
        })
    return normalized


def _normalize_general_report_top_quarry_rows(rows: object) -> list[dict]:
    raw_rows = rows if isinstance(rows, list) else _default_general_report_quarry_rows()
    if isinstance(rows, list):
        default_rows = _default_general_report_quarry_rows()
        raw_by_label: dict[str, dict] = {}
        used_raw_ids: set[int] = set()
        for raw in rows:
            if not isinstance(raw, dict):
                continue
            filters = _general_row_filters(raw.get("filters"))
            quarry_labels = _general_clean_string_list(filters.get("quarry_labels") if "quarry_labels" in filters else raw.get("quarry_labels"), limit=24)
            label = str(raw.get("label") or (quarry_labels[0] if quarry_labels else "")).strip()
            key = _general_quarry_label_key(label)
            if key and key not in raw_by_label:
                raw_by_label[key] = raw
        ordered_rows: list[dict] = []
        for default in default_rows:
            key = _general_quarry_label_key(default.get("label"))
            raw = raw_by_label.get(key, default)
            ordered_rows.append(raw)
            used_raw_ids.add(id(raw))
        for raw in rows:
            if isinstance(raw, dict) and id(raw) not in used_raw_ids and len(ordered_rows) < GENERAL_REPORT_TOP_QUARRY_ROW_LIMIT:
                ordered_rows.append(raw)
        raw_rows = ordered_rows
    normalized: list[dict] = []
    seen_ids: set[str] = set()
    for idx, raw in enumerate(raw_rows[:GENERAL_REPORT_TOP_QUARRY_ROW_LIMIT] if isinstance(raw_rows, list) else [], start=1):
        if not isinstance(raw, dict):
            continue
        label = str(raw.get("label") or "").strip()[:160]
        filters = _general_row_filters(raw.get("filters"))
        quarry_labels = _general_clean_string_list(filters.get("quarry_labels") if "quarry_labels" in filters else raw.get("quarry_labels"), limit=24)
        if not label and quarry_labels:
            label = quarry_labels[0]
        if not label:
            label = f"Карьер {idx}"
        row_id = _general_clean_id(raw.get("id"), f"quarry_{idx}")
        while row_id in seen_ids:
            row_id = f"{row_id}_{idx}"
        seen_ids.add(row_id)
        has_explicit_filters = any([
            _general_clean_string_list(filters.get("materials"), limit=16),
            _general_clean_string_list(filters.get("movement_types"), limit=16),
            _general_clean_string_list(filters.get("source_buckets"), limit=8),
            _general_clean_string_list(filters.get("from_object_type_codes"), limit=80),
            _general_clean_string_list(filters.get("from_object_codes"), limit=160),
            _general_clean_string_list(filters.get("to_object_type_codes"), limit=80),
            _general_clean_string_list(filters.get("to_object_codes"), limit=160),
        ])
        if not quarry_labels and not has_explicit_filters:
            quarry_labels = [label]
        normalized.append({
            "id": row_id,
            "label": label,
            "source": "top_quarry",
            "enabled": _general_clean_bool(raw.get("enabled"), True),
            "include_in_totals": _general_clean_bool(raw.get("include_in_totals"), True),
            "filters": {
                "quarry_labels": quarry_labels,
                "materials": _general_clean_string_list(filters.get("materials"), limit=16),
                "movement_types": _general_clean_string_list(filters.get("movement_types"), limit=16),
                "tags": [],
                "object_type_codes": [],
                "object_codes": [],
                "from_object_type_codes": _general_clean_string_list(filters.get("from_object_type_codes"), limit=80),
                "from_object_codes": _general_clean_string_list(filters.get("from_object_codes"), limit=160),
                "to_object_type_codes": _general_clean_string_list(filters.get("to_object_type_codes"), limit=80),
                "to_object_codes": _general_clean_string_list(filters.get("to_object_codes"), limit=160),
                "source_buckets": _general_clean_string_list(filters.get("source_buckets"), limit=8),
                "equipment_classes": [],
            },
        })
    return normalized


def _normalize_general_report_equipment_rows(rows: object) -> list[dict]:
    raw_by_code: dict[str, dict] = {}
    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, dict):
                continue
            filters = _general_row_filters(row.get("filters"))
            code = str(row.get("code") or "").strip()
            classes = _general_clean_string_list(filters.get("equipment_classes"), limit=8)
            if not code and classes:
                code = classes[0]
            if code:
                raw_by_code[code] = row
    normalized: list[dict] = []
    for default in _default_general_report_equipment_rows():
        raw = raw_by_code.get(default["code"], {})
        filters = _general_row_filters(raw.get("filters"))
        classes = _general_clean_string_list(filters.get("equipment_classes"), limit=8) or [default["code"]]
        classes = [value for value in classes if value in GENERAL_REPORT_EQUIPMENT_CLASS_CODES] or [default["code"]]
        normalized.append({
            "id": _general_clean_id(raw.get("id"), default["id"]),
            "code": default["code"],
            "label": str(raw.get("label") or default["label"]).strip()[:160],
            "source": "equipment_count",
            "enabled": _general_clean_bool(raw.get("enabled"), True),
            "include_in_totals": _general_clean_bool(raw.get("include_in_totals"), True),
            "filters": {
                "tags": _general_clean_string_list(filters.get("tags")),
                "object_type_codes": _general_clean_string_list(filters.get("object_type_codes")),
                "object_codes": _general_clean_string_list(filters.get("object_codes")),
                "from_object_type_codes": [],
                "from_object_codes": [],
                "to_object_type_codes": [],
                "to_object_codes": [],
                "quarry_labels": [],
                "materials": [],
                "movement_types": [],
                "source_buckets": _general_clean_string_list(filters.get("source_buckets"), limit=8),
                "equipment_classes": classes,
            },
        })
    return normalized


def _normalize_general_report_custom_blocks(blocks: object) -> list[dict]:
    out: list[dict] = []
    if not isinstance(blocks, list):
        return out
    for idx, raw in enumerate(blocks[:GENERAL_REPORT_BLOCK_LIMIT], start=1):
        if not isinstance(raw, dict):
            continue
        kind = str(raw.get("kind") or "").strip() or str(raw.get("id") or "").strip()
        if kind in {"top_quarries", "work_summary", "equipment_day"}:
            continue
        block_id = _general_clean_id(raw.get("id"), f"custom_{idx}")
        rows: list[dict] = []
        raw_rows = raw.get("rows") if isinstance(raw.get("rows"), list) else []
        for row_idx, row in enumerate(raw_rows[:GENERAL_REPORT_CUSTOM_ROW_LIMIT], start=1):
            if not isinstance(row, dict):
                continue
            filters = _general_row_filters(row.get("filters"))
            row_id = _general_clean_id(row.get("id"), f"{block_id}_row_{row_idx}")
            rows.append({
                "id": row_id,
                "code": str(row.get("code") or row_id).strip()[:80],
                "label": str(row.get("label") or f"Строка {row_idx}").strip()[:160],
                "source": str(row.get("source") or "work_category").strip()[:80],
                "enabled": _general_clean_bool(row.get("enabled"), True),
                "include_in_totals": _general_clean_bool(row.get("include_in_totals"), True),
                "filters": {
                    "tags": _general_clean_string_list(filters.get("tags")),
                    "object_type_codes": _general_clean_string_list(filters.get("object_type_codes")),
                    "object_codes": _general_clean_string_list(filters.get("object_codes")),
                    "from_object_type_codes": _general_clean_string_list(filters.get("from_object_type_codes"), limit=80),
                    "from_object_codes": _general_clean_string_list(filters.get("from_object_codes"), limit=160),
                    "to_object_type_codes": _general_clean_string_list(filters.get("to_object_type_codes"), limit=80),
                    "to_object_codes": _general_clean_string_list(filters.get("to_object_codes"), limit=160),
                    "quarry_labels": _general_clean_string_list(filters.get("quarry_labels")),
                    "materials": _general_clean_string_list(filters.get("materials")),
                    "movement_types": _general_clean_string_list(filters.get("movement_types")),
                    "source_buckets": _general_clean_string_list(filters.get("source_buckets"), limit=8),
                    "equipment_classes": _general_clean_string_list(filters.get("equipment_classes"), limit=8),
                },
            })
        out.append({
            "id": block_id,
            "title": str(raw.get("title") or f"Дополнительный блок {idx}").strip()[:160],
            "kind": "custom",
            "enabled": _general_clean_bool(raw.get("enabled"), True),
            "rows": rows,
        })
    return out


def _normalize_general_report_config(payload: object) -> dict:
    raw = payload if isinstance(payload, dict) else {}
    raw_blocks = raw.get("blocks") if isinstance(raw.get("blocks"), list) else []
    raw_work_block = next((block for block in raw_blocks if isinstance(block, dict) and block.get("id") == "work_summary"), None)
    work_source = raw_work_block.get("rows") if isinstance(raw_work_block, dict) and isinstance(raw_work_block.get("rows"), list) else raw.get("rows")
    work_rows = _normalize_general_report_work_rows(work_source)
    raw_top_block = next((block for block in raw_blocks if isinstance(block, dict) and block.get("id") == "top_quarries"), None)
    top_rows = _normalize_general_report_top_quarry_rows(raw_top_block.get("rows") if isinstance(raw_top_block, dict) else None)
    raw_equipment_block = next((block for block in raw_blocks if isinstance(block, dict) and block.get("id") == "equipment_day"), None)
    equipment_rows = _normalize_general_report_equipment_rows(raw_equipment_block.get("rows") if isinstance(raw_equipment_block, dict) else None)
    top_title = str((raw_top_block or {}).get("title") or "Возка / верхняя таблица")[:160] if isinstance(raw_top_block, dict) else "Возка / верхняя таблица"
    if top_title == "Карьеры / верхняя таблица":
        top_title = "Возка / верхняя таблица"
    builtin_blocks = {
        "top_quarries": {
            "id": "top_quarries",
            "title": top_title,
            "kind": "top_quarries",
            "enabled": _general_clean_bool((raw_top_block or {}).get("enabled") if isinstance(raw_top_block, dict) else None, True),
            "rows": top_rows,
        },
        "work_summary": {
            "id": "work_summary",
            "title": str((raw_work_block or {}).get("title") or "Основные работы")[:160] if isinstance(raw_work_block, dict) else "Основные работы",
            "kind": "work_summary",
            "enabled": _general_clean_bool((raw_work_block or {}).get("enabled") if isinstance(raw_work_block, dict) else None, True),
            "rows": _work_block_rows_from_work_rows(work_rows),
        },
        "equipment_day": {
            "id": "equipment_day",
            "title": str((raw_equipment_block or {}).get("title") or "Текущий день - техника")[:160] if isinstance(raw_equipment_block, dict) else "Текущий день - техника",
            "kind": "equipment_day",
            "enabled": _general_clean_bool((raw_equipment_block or {}).get("enabled") if isinstance(raw_equipment_block, dict) else None, True),
            "rows": equipment_rows,
        },
    }
    custom_blocks = {
        block["id"]: block
        for block in _normalize_general_report_custom_blocks(raw_blocks)
        if isinstance(block, dict) and block.get("id")
    }
    ordered_ids: list[str] = []
    for raw_block in raw_blocks:
        if not isinstance(raw_block, dict):
            continue
        raw_id = str(raw_block.get("id") or raw_block.get("kind") or "").strip()
        if not raw_id:
            continue
        normalized_id = raw_id if raw_id in builtin_blocks else _general_clean_id(raw_id, raw_id)
        if normalized_id in builtin_blocks or normalized_id in custom_blocks:
            if normalized_id not in ordered_ids:
                ordered_ids.append(normalized_id)
    for block_id in ("top_quarries", "work_summary", "equipment_day"):
        if block_id not in ordered_ids:
            ordered_ids.append(block_id)
    for block_id in custom_blocks:
        if block_id not in ordered_ids:
            ordered_ids.append(block_id)
    blocks: list[dict] = []
    for block_id in ordered_ids:
        if block_id in builtin_blocks:
            blocks.append(builtin_blocks[block_id])
        elif block_id in custom_blocks:
            blocks.append(custom_blocks[block_id])
    return {"version": 2, "rows": work_rows, "blocks": blocks}


def _load_general_report_config_record() -> tuple[dict, Optional[str], object]:
    try:
        _ensure_dashboard_settings_schema()
        row = query_one(
            """
            SELECT payload, updated_by, updated_at
            FROM dashboard_settings
            WHERE key = %s
            """,
            (GENERAL_REPORT_CONFIG_KEY,),
        )
        if row and isinstance(row.get("payload"), dict):
            return row.get("payload") or {}, row.get("updated_by"), row.get("updated_at")
        legacy = query_one(
            """
            SELECT payload, updated_by, updated_at
            FROM dashboard_settings
            WHERE key = %s
            """,
            (GENERAL_REPORT_WORK_CONFIG_KEY,),
        )
        if legacy and isinstance(legacy.get("payload"), dict):
            return legacy.get("payload") or {}, legacy.get("updated_by"), legacy.get("updated_at")
    except Exception:
        pass
    return {}, None, None


@lru_cache(maxsize=1)
def _general_report_config() -> dict:
    payload, _, _ = _load_general_report_config_record()
    return _normalize_general_report_config(payload)


def _general_report_work_rules() -> list[dict]:
    return _general_report_config()["rows"]


def _general_report_top_quarry_rules() -> list[dict]:
    for block in _general_report_config().get("blocks") or []:
        if block.get("id") == "top_quarries" and block.get("enabled", True):
            return [row for row in (block.get("rows") or []) if row.get("enabled", True)]
    return []


def _general_report_equipment_day_rules() -> list[dict]:
    for block in _general_report_config().get("blocks") or []:
        if block.get("id") == "equipment_day" and block.get("enabled", True):
            return [row for row in (block.get("rows") or []) if row.get("enabled", True)]
    return []


def _general_equipment_rule_for_class(equipment_class: str) -> Optional[dict]:
    for block in _general_report_config().get("blocks") or []:
        if block.get("id") != "equipment_day" or not block.get("enabled", True):
            continue
        for rule in block.get("rows") or []:
            filters = _general_row_filters(rule.get("filters"))
            classes = _general_clean_string_list(filters.get("equipment_classes"), limit=8)
            code = str(rule.get("code") or "").strip()
            if equipment_class in classes or equipment_class == code:
                return rule
    return None


def _general_report_quarry_options() -> list[dict]:
    labels_by_key: dict[str, str] = {}

    def add_label(label: object) -> None:
        text = str(label or "").strip()
        if not text:
            return
        key = _general_quarry_label_key(text)
        if key and key not in labels_by_key:
            labels_by_key[key] = text

    for row in _default_general_report_quarry_rows():
        add_label(row.get("label"))
    try:
        rows = query(
            f"""
            SELECT DISTINCT COALESCE(NULLIF(src.name, ''), src.object_code, 'Карьер') AS quarry_name,
                            m.code AS material_code,
                            COALESCE(NULLIF(m.name, ''), m.code) AS material_name
            FROM material_movements mm
            JOIN daily_reports dr ON dr.id = mm.daily_report_id
            JOIN materials m ON m.id = mm.material_id
            LEFT JOIN objects src ON src.id = mm.from_object_id
            LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
            WHERE src_ot.code = 'BORROW_PIT'
              AND {_non_pile_control_report_condition('dr')}
            ORDER BY 1, 3
            """
        )
        for row in rows:
            material = _general_material_bucket(row.get("material_code"), row.get("material_name"))
            quarry_name = _quarry_display_name(row.get("quarry_name") or "Карьер")
            label = quarry_name
            if material != "SAND":
                label = f"{quarry_name} ({row.get('material_name') or row.get('material_code') or 'материал'})"
            add_label(label)
    except Exception:
        pass
    return [
        {"value": label, "label": label}
        for label in sorted(labels_by_key.values(), key=lambda item: _general_quarry_label_key(item))
    ]


def _general_report_object_options() -> list[dict]:
    options: list[dict] = []
    try:
        type_rows = query(
            f"""
            SELECT ot.code, COALESCE(NULLIF(ot.name, ''), ot.code) AS name, COUNT(o.id)::int AS cnt
            FROM object_types ot
            LEFT JOIN objects o ON o.object_type_id = ot.id AND COALESCE(o.is_active, true) IS TRUE
            WHERE NULLIF(BTRIM(COALESCE(ot.code, '')), '') IS NOT NULL
            GROUP BY ot.code, ot.name
            ORDER BY name, ot.code
            """
        )
    except Exception:
        type_rows = []
    for row in type_rows:
        code = str(row.get("code") or "").strip()
        if not code:
            continue
        options.append({
            "value": f"type:{code}",
            "label": f"Тип: {row.get('name') or code}",
            "hint": f"{row.get('cnt') or 0} объектов",
        })
    try:
        object_rows = query(
            """
            SELECT o.object_code, COALESCE(NULLIF(o.name, ''), o.object_code) AS name,
                   ot.code AS object_type_code, COALESCE(NULLIF(ot.name, ''), ot.code) AS object_type_name
            FROM objects o
            LEFT JOIN object_types ot ON ot.id = o.object_type_id
            WHERE COALESCE(o.is_active, true) IS TRUE
              AND NULLIF(BTRIM(COALESCE(o.object_code, '')), '') IS NOT NULL
            ORDER BY object_type_name NULLS LAST, name, o.object_code
            LIMIT 2000
            """
        )
    except Exception:
        object_rows = []
    for row in object_rows:
        code = str(row.get("object_code") or "").strip()
        if not code:
            continue
        hint_parts = [row.get("object_type_name"), row.get("object_code")]
        hint = " · ".join(str(part) for part in hint_parts if part)
        options.append({
            "value": f"object:{code}",
            "label": row.get("name") or code,
            "hint": hint or code,
        })
    return options


def _general_report_source_options() -> list[dict]:
    variants: dict[str, set[str]] = {key: set() for key in GENERAL_REPORT_SOURCE_BUCKET_LABELS}
    try:
        rows = query(
            f"""
            SELECT dwi.labor_source_type::text AS source_type, dwi.contractor_name::text AS contractor_name
            FROM daily_work_items dwi
            JOIN daily_reports dr ON dr.id = dwi.daily_report_id
            WHERE (dwi.labor_source_type IS NOT NULL OR NULLIF(BTRIM(dwi.contractor_name), '') IS NOT NULL)
              AND {_non_pile_control_report_condition('dr')}
            UNION
            SELECT mm.labor_source_type::text AS source_type, mm.contractor_name::text AS contractor_name
            FROM material_movements mm
            JOIN daily_reports dr ON dr.id = mm.daily_report_id
            WHERE (mm.labor_source_type IS NOT NULL OR NULLIF(BTRIM(mm.contractor_name), '') IS NOT NULL)
              AND {_non_pile_control_report_condition('dr')}
            UNION
            SELECT ownership_type::text AS source_type, contractor_name::text AS contractor_name
            FROM report_equipment_units
            WHERE ownership_type IS NOT NULL OR NULLIF(BTRIM(contractor_name), '') IS NOT NULL
            """
        )
        for row in rows:
            source_type = str(row.get("source_type") or "").strip()
            contractor = str(row.get("contractor_name") or "").strip()
            bucket = _general_source_bucket(source_type, contractor)
            if bucket not in variants:
                variants[bucket] = set()
            label = " / ".join(part for part in (source_type, contractor) if part)
            if label:
                variants[bucket].add(label[:80])
    except Exception:
        pass
    options: list[dict] = []
    for value, label in GENERAL_REPORT_SOURCE_BUCKET_LABELS.items():
        hint_items = sorted(variants.get(value) or [])[:6]
        options.append({
            "value": value,
            "label": label,
            "hint": ", ".join(hint_items) if hint_items else "Нет отдельных значений в БД",
        })
    return options


def _general_report_equipment_options() -> list[dict]:
    variants: dict[str, set[str]] = {code: set() for code in GENERAL_REPORT_EQUIPMENT_CLASS_LABELS}
    try:
        rows = query(
            """
            SELECT COALESCE(NULLIF(reu.equipment_type, ''), NULLIF(eu.equipment_type, '')) AS equipment_type,
                   COUNT(*)::int AS cnt
            FROM report_equipment_units reu
            LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
            WHERE COALESCE(reu.is_demo, false) IS FALSE
              AND NULLIF(BTRIM(COALESCE(reu.equipment_type, eu.equipment_type, '')), '') IS NOT NULL
            GROUP BY COALESCE(NULLIF(reu.equipment_type, ''), NULLIF(eu.equipment_type, ''))
            ORDER BY 1
            """
        )
        for row in rows:
            raw_type = str(row.get("equipment_type") or "").strip()
            class_code = _general_equipment_class(raw_type)
            if class_code in variants:
                variants[class_code].add(f"{raw_type} ({row.get('cnt') or 0})")
    except Exception:
        pass
    return [
        {
            "value": code,
            "label": label,
            "hint": ", ".join(sorted(variants.get(code) or [])[:8]) or "Справочник техники",
        }
        for code, label in GENERAL_REPORT_EQUIPMENT_CLASS_LABELS.items()
    ]


def _general_material_filter_value(material_code: Optional[str], material_name: Optional[str]) -> str:
    return (material_code or material_name or "material").strip().upper().replace(" ", "_")


def _general_material_filter_aliases(material_code: Optional[str], material_name: Optional[str]) -> list[str]:
    values: list[str] = []
    actual = _general_material_filter_value(material_code, material_name)
    if actual:
        values.append(actual)
    bucket = _general_material_bucket(material_code, material_name)
    # Для ЩПС/ЩПГС/ПГС не добавляем общий SHPS-alias: в справочнике это разные материалы.
    if bucket and bucket != "SHPS" and bucket not in values:
        values.append(bucket)
    return values


def _general_material_filter_label(value: str) -> str:
    return {
        "SAND": "Песок",
        "SOIL": "Грунт",
        "SHPGS": "ЩПГС",
        "SHPS": "ЩПС",
        "PGS": "ПГС",
        "SCHEBEN": "Щебень",
        "CRUSHED_STONE": "Щебень",
    }.get(value, value)


def _general_report_material_options() -> list[dict]:
    values: dict[str, dict[str, str]] = {}
    try:
        rows = query(
            """
            SELECT DISTINCT code AS material_code, COALESCE(NULLIF(name, ''), code) AS material_name
            FROM materials
            WHERE NULLIF(BTRIM(COALESCE(code, name, '')), '') IS NOT NULL
            ORDER BY 2, 1
            """
        )
        for row in rows:
            value = _general_material_filter_value(row.get("material_code"), row.get("material_name"))
            if not value:
                continue
            label = str(row.get("material_name") or row.get("material_code") or value).strip()
            code = str(row.get("material_code") or value).strip()
            values[value] = {"label": label or _general_material_filter_label(value), "hint": code}
    except Exception:
        pass
    if not values:
        values = {
            "SAND": {"label": "Песок", "hint": "SAND"},
            "SHPGS": {"label": "ЩПГС", "hint": "SHPGS"},
            "SHPS": {"label": "ЩПС", "hint": "SHPS"},
            "PGS": {"label": "ПГС", "hint": "PGS"},
            "SOIL": {"label": "Грунт", "hint": "SOIL"},
            "SCHEBEN": {"label": "Щебень", "hint": "SCHEBEN"},
        }
    return [
        {"value": value, "label": item["label"], "hint": item.get("hint")}
        for value, item in sorted(values.items(), key=lambda pair: pair[1]["label"].lower())
        if value
    ]


def _general_report_movement_options() -> list[dict]:
    values: set[str] = set()
    try:
        rows = query(
            f"""
            SELECT DISTINCT mm.movement_type
            FROM material_movements mm
            JOIN daily_reports dr ON dr.id = mm.daily_report_id
            WHERE NULLIF(BTRIM(COALESCE(mm.movement_type, '')), '') IS NOT NULL
              AND COALESCE(mm.is_demo, false) IS FALSE
              AND {_non_pile_control_report_condition('dr')}
            ORDER BY mm.movement_type
            """
        )
        values.update(str(row.get("movement_type") or "").strip() for row in rows)
    except Exception:
        pass
    if not values:
        values.update(MOVEMENT_TYPE_LABELS.keys())
    return [
        {"value": value, "label": _movement_type_label(value)}
        for value in sorted(v for v in values if v)
    ]


def _dashboard_debug_clean_key(value: object) -> str:
    key = re.sub(r"[^a-zA-Z0-9_.:-]+", "_", str(value or "").strip())[:120].strip("_.:-")
    if not key:
        raise HTTPException(400, "Не указан ключ debug-настройки")
    return key


def _dashboard_debug_setting_key(key: str) -> str:
    return f"{DASHBOARD_DEBUG_CONFIG_PREFIX}{_dashboard_debug_clean_key(key)}"


def _normalize_dashboard_debug_filters(raw: object) -> dict[str, list[str]]:
    source = raw if isinstance(raw, dict) else {}
    out: dict[str, list[str]] = {}
    for key in DASHBOARD_DEBUG_FILTER_KEYS:
        values = _general_clean_string_list(source.get(key), limit=240)
        out[key] = values
    return out


def _debug_option(value: object, label: object, hint: object = None) -> dict:
    text_value = str(value or "").strip()
    text_label = str(label or text_value or "—").strip()
    item = {"value": text_value, "label": text_label}
    if hint:
        item["hint"] = str(hint)[:180]
    return item


def _dashboard_debug_tag_options() -> list[dict]:
    try:
        rows = query(
            f"""
            SELECT tag_name, SUM(cnt)::int AS cnt, STRING_AGG(DISTINCT unit, ', ' ORDER BY unit) AS units
            FROM (
              SELECT COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), 'Без тега') AS tag_name,
                     COALESCE(dwi.unit, wt.default_unit, '') AS unit,
                     COUNT(*)::int AS cnt
              FROM daily_work_items dwi
              JOIN daily_reports dr ON dr.id = dwi.daily_report_id
              JOIN work_types wt ON wt.id = dwi.work_type_id
              WHERE COALESCE(dwi.is_demo, false) IS FALSE
                AND {_non_pile_control_report_condition('dr')}
              GROUP BY COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), 'Без тега'), COALESCE(dwi.unit, wt.default_unit, '')
              UNION ALL
              SELECT wat.name AS tag_name, '' AS unit, 0 AS cnt
              FROM work_analytics_tags wat
            ) src
            WHERE NULLIF(BTRIM(tag_name), '') IS NOT NULL
            GROUP BY tag_name
            ORDER BY tag_name
            """
        )
    except Exception:
        rows = []
    return [_debug_option(row.get("tag_name"), row.get("tag_name"), f"{row.get('cnt') or 0} строк{(' · ' + row.get('units')) if row.get('units') else ''}") for row in rows]


def _dashboard_debug_object_type_options() -> list[dict]:
    try:
        rows = query(
            f"""
            SELECT ot.code, COALESCE(NULLIF(ot.name, ''), ot.code) AS name, COUNT(o.id)::int AS cnt
            FROM object_types ot
            LEFT JOIN objects o ON o.object_type_id = ot.id AND COALESCE(o.is_active, true) IS TRUE
            GROUP BY ot.code, ot.name
            ORDER BY name, ot.code
            """
        )
    except Exception:
        rows = []
    return [_debug_option(row.get("code"), row.get("name"), f"{row.get('cnt') or 0} объектов") for row in rows if row.get("code")]


def _dashboard_debug_object_options(limit: int = 1200) -> list[dict]:
    try:
        rows = query(
            """
            SELECT o.id::text AS id, o.object_code, COALESCE(NULLIF(o.name, ''), o.object_code) AS name,
                   ot.code AS object_type_code, COALESCE(NULLIF(ot.name, ''), ot.code) AS object_type_name
            FROM objects o
            LEFT JOIN object_types ot ON ot.id = o.object_type_id
            WHERE COALESCE(o.is_active, true) IS TRUE
            ORDER BY object_type_name NULLS LAST, name, o.object_code
            LIMIT %s
            """,
            [limit],
        )
    except Exception:
        rows = []
    out = []
    for row in rows:
        code = row.get("object_code") or row.get("id")
        label = row.get("name") or code
        hint = " / ".join(part for part in [row.get("object_type_name"), row.get("object_code")] if part and part != label)
        out.append(_debug_option(code, label, hint))
    return out


def _dashboard_debug_source_object_options(limit: int = 800) -> list[dict]:
    try:
        rows = query(
            f"""
            SELECT src.id::text AS id, src.object_code, COALESCE(NULLIF(src.name, ''), src.object_code) AS name,
                   ot.code AS object_type_code, COALESCE(NULLIF(ot.name, ''), ot.code) AS object_type_name,
                   COUNT(mm.id)::int AS cnt
            FROM material_movements mm
            JOIN daily_reports dr ON dr.id = mm.daily_report_id
            JOIN objects src ON src.id = mm.from_object_id
            LEFT JOIN object_types ot ON ot.id = src.object_type_id
            WHERE COALESCE(mm.is_demo, false) IS FALSE
              AND {_non_pile_control_report_condition('dr')}
            GROUP BY src.id, src.object_code, src.name, ot.code, ot.name
            ORDER BY object_type_name NULLS LAST, name
            LIMIT %s
            """,
            [limit],
        )
    except Exception:
        rows = []
    out = []
    for row in rows:
        label = row.get("name") or row.get("object_code") or row.get("id")
        hint = f"{row.get('object_type_name') or 'Тип не указан'} · {row.get('cnt') or 0} перевозок"
        out.append(_debug_option(row.get("id"), label, hint))
    return out


def _dashboard_debug_source_object_type_options() -> list[dict]:
    try:
        rows = query(
            f"""
            SELECT ot.code, COALESCE(NULLIF(ot.name, ''), ot.code) AS name, COUNT(mm.id)::int AS cnt
            FROM material_movements mm
            JOIN daily_reports dr ON dr.id = mm.daily_report_id
            JOIN objects src ON src.id = mm.from_object_id
            LEFT JOIN object_types ot ON ot.id = src.object_type_id
            WHERE COALESCE(mm.is_demo, false) IS FALSE
              AND {_non_pile_control_report_condition('dr')}
              AND ot.code IS NOT NULL
            GROUP BY ot.code, ot.name
            ORDER BY name, ot.code
            """
        )
    except Exception:
        rows = []
    return [_debug_option(row.get("code"), row.get("name"), f"{row.get('cnt') or 0} перевозок") for row in rows if row.get("code")]


