@router.get("/dashboard-debug/config")
def get_dashboard_debug_config(key: str, _user=Depends(current_user)):
    setting_key = _dashboard_debug_setting_key(key)
    _ensure_dashboard_settings_schema()
    row = query_one(
        """
        SELECT payload, updated_by, updated_at
        FROM dashboard_settings
        WHERE key = %s
        """,
        (setting_key,),
    )
    payload = row.get("payload") if row and isinstance(row.get("payload"), dict) else {}
    return {
        "key": _dashboard_debug_clean_key(key),
        "filters": _normalize_dashboard_debug_filters(payload.get("filters") if isinstance(payload, dict) else payload),
        "updated_by": row.get("updated_by") if row else None,
        "updated_at": row.get("updated_at").isoformat() if row and hasattr(row.get("updated_at"), "isoformat") else (row.get("updated_at") if row else None),
    }


@router.put("/dashboard-debug/config")
def save_dashboard_debug_config(body: DashboardDebugConfigBody, _admin=Depends(require_admin)):
    key = _dashboard_debug_clean_key(body.key)
    filters = _normalize_dashboard_debug_filters(body.filters)
    payload = {"filters": filters}
    _ensure_dashboard_settings_schema()
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO dashboard_settings (key, payload, updated_by, updated_at)
                    VALUES (%s, %s::jsonb, %s, now())
                    ON CONFLICT (key) DO UPDATE
                    SET payload = EXCLUDED.payload,
                        updated_by = EXCLUDED.updated_by,
                        updated_at = now()
                    RETURNING updated_at
                    """,
                    (_dashboard_debug_setting_key(key), json.dumps(payload, ensure_ascii=False), _admin.username),
                )
                updated_at = cur.fetchone()[0]
        return {
            "key": key,
            "filters": filters,
            "updated_by": _admin.username,
            "updated_at": updated_at.isoformat() if hasattr(updated_at, "isoformat") else updated_at,
        }
    finally:
        conn.close()


def _general_matching_work_rule(
    rules: list[dict],
    tag: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
    source_bucket: Optional[str] = None,
) -> Optional[dict]:
    tag_norm = _general_normalize_text(tag)
    obj_type = str(object_type_code or "").strip()
    obj = str(object_code or "").strip()
    for rule in rules:
        if not rule.get("enabled", True):
            continue
        filters = _general_row_filters(rule.get("filters"))
        tags_source = rule.get("tags") if "tags" in rule else filters.get("tags")
        tags = {_general_normalize_text(value) for value in (tags_source or []) if _general_normalize_text(value)}
        if tags and tag_norm not in tags:
            continue
        type_source = rule.get("object_type_codes") if "object_type_codes" in rule else filters.get("object_type_codes")
        object_source = rule.get("object_codes") if "object_codes" in rule else filters.get("object_codes")
        rule_code = str(rule.get("code") or "").strip().upper()
        type_codes = {str(value or "").strip() for value in (type_source or []) if str(value or "").strip()}
        object_codes = {str(value or "").strip() for value in (object_source or []) if str(value or "").strip()}
        type_match = obj_type in type_codes
        object_match = obj in object_codes
        if rule_code in {"SAND_VAD", "VYEMKA"} and obj_type == "TECH_ROAD" and not _general_is_vad_object_type(obj_type, obj):
            type_match = False
        if rule_code in {"SAND_OH", "VYEMKA_OH"} and _general_is_oh_object_type(obj_type, obj) and "MAIN_TRACK" in type_codes:
            type_match = True
        if (type_codes or object_codes) and not (type_match or object_match):
            continue
        source_source = rule.get("source_buckets") if "source_buckets" in rule else filters.get("source_buckets")
        source_buckets = set(_general_clean_string_list(source_source, limit=8))
        if source_bucket is not None and source_buckets and source_bucket not in source_buckets:
            continue
        code = str(rule.get("code") or "").strip()
        if code in GENERAL_REPORT_WORK_ROW_CODES:
            return rule
    return None


def _general_configured_work_category(
    rules: list[dict],
    tag: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
    source_bucket: Optional[str] = None,
) -> Optional[str]:
    rule = _general_matching_work_rule(rules, tag, object_type_code, object_code, source_bucket)
    if not rule:
        return None
    code = str(rule.get("code") or "").strip()
    if _general_is_pile_field_object_type(object_type_code, object_code):
        code_upper = code.upper()
        if code_upper in {"SAND", "SAND_OH", "SAND_PILE"}:
            return "SAND_PILE"
        if code_upper in {"VYEMKA", "VYEMKA_OH", "VYEMKA_OTHER", "VYEMKA_PILE"}:
            return "VYEMKA_PILE"
    return code or None


def _general_normalize_text(value: object) -> str:
    text = str(value or "").strip().lower().replace("ё", "е")
    text = re.sub(r"[()\[\]{}\"'«»“”„.,;:/\\]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def _general_is_local_soil_tag(tag: object) -> bool:
    """Owner row 185: local soil = placement tags containing "грунт"."""
    text = _general_normalize_text(tag)
    if "грунт" not in text:
        return False
    return not any(marker in text for marker in ("раститель", "прс", "выем", "выторф"))


def _general_is_pile_access_tech_road(object_type_code: Optional[str], object_code: Optional[str] = None) -> bool:
    obj_type = (object_type_code or "").upper()
    obj_code = (object_code or "").upper()
    return obj_type == "TECH_ROAD" and any(obj_code.startswith(prefix) for prefix in GENERAL_REPORT_PILE_ACCESS_TECH_ROAD_PREFIXES)


def _general_is_pile_field_object_type(object_type_code: Optional[str], object_code: Optional[str] = None) -> bool:
    obj_type = (object_type_code or "").upper()
    return obj_type in GENERAL_REPORT_PILE_OBJECT_TYPE_CODES or _general_is_pile_access_tech_road(obj_type, object_code)


def _general_is_oh_object_type(object_type_code: Optional[str], object_code: Optional[str] = None) -> bool:
    obj_type = (object_type_code or "").upper()
    return obj_type in GENERAL_REPORT_OH_OBJECT_TYPE_CODES


def _general_is_vad_object_type(object_type_code: Optional[str], object_code: Optional[str] = None) -> bool:
    obj_type = (object_type_code or "").upper()
    if obj_type == "TECH_ROAD":
        return not _general_is_pile_access_tech_road(obj_type, object_code)
    return obj_type in GENERAL_REPORT_VAD_OBJECT_TYPE_CODES


def _general_tp_bucket(object_code: Optional[str]) -> Optional[str]:
    obj_code = (object_code or "").upper()
    if obj_code in GENERAL_REPORT_TP_VALDAI_OBJECT_CODES:
        return "VALDAI"
    if obj_code in GENERAL_REPORT_TP_VYPOLZOVO_OBJECT_CODES:
        return "VYPOLZOVO"
    if obj_code in GENERAL_REPORT_TP_OBJECT_CODES:
        return "TP"
    return None


def _general_local_soil_extra_categories(object_code: Optional[str]) -> list[str]:
    """Owner-approved TP sand extras for local-soil tags.

    Some traction-substation sand-placement facts arrive as analytics tags like
    ``Грунт(*)`` with a non-sand work type, so the standard classifier only
    retains them in ``SOIL_LOCAL``.  The owner wants those facts visible in the
    Генеральный report rows ``Укладка песка → ТП / Валдай / Выползово`` as well.
    """
    tp_bucket = _general_tp_bucket(object_code)
    if tp_bucket == "VALDAI":
        return ["SAND", "SAND_VALDAI"]
    if tp_bucket == "VYPOLZOVO":
        return ["SAND", "SAND_VYPOLZOVO"]
    return []


def _general_additional_split_categories(
    category: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
) -> list[str]:
    if not category:
        return []
    obj_type = (object_type_code or "").upper()
    obj_code = (object_code or "").upper()
    tp_bucket = _general_tp_bucket(obj_code)
    extras: list[str] = []
    if category == "PRS":
        if _general_is_pile_field_object_type(obj_type, obj_code):
            extras.append("PRS_PILE")
        elif _general_is_vad_object_type(obj_type, obj_code):
            extras.append("PRS_VAD")
        elif _general_is_oh_object_type(obj_type, obj_code):
            extras.append("PRS_OH")
        elif tp_bucket == "VALDAI":
            extras.append("PRS_VALDAI")
        elif tp_bucket == "VYPOLZOVO":
            extras.append("PRS_VYPOLZOVO")
    elif category == "SAND":
        if tp_bucket == "VALDAI":
            extras.append("SAND_VALDAI")
        elif tp_bucket == "VYPOLZOVO":
            extras.append("SAND_VYPOLZOVO")
    elif category == "VYEMKA_OTHER":
        if tp_bucket == "VALDAI":
            extras.append("VYEMKA_VALDAI")
        elif tp_bucket == "VYPOLZOVO":
            extras.append("VYEMKA_VYPOLZOVO")
    return extras


def _general_work_category(
    tag: Optional[str],
    wt_code: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str] = None,
) -> Optional[str]:
    code = (wt_code or "").upper()
    obj_type = (object_type_code or "").upper()
    obj_code = (object_code or "").upper()
    text = _general_normalize_text(tag)
    if code in {"PILE_MAIN", "PILE_TRIAL", "PILE_DYNTEST", "PILE_HEADCAP_INSTALLATION"}:
        return None
    mapped = _GENERAL_TAG_CATEGORY_BY_TEXT.get(text)
    if mapped:
        if mapped == "VYEMKA":
            if _general_is_pile_field_object_type(obj_type, obj_code):
                return "VYEMKA_PILE"
            if _general_is_oh_object_type(obj_type, obj_code):
                return "VYEMKA_OH"
            return "VYEMKA" if _general_is_vad_object_type(obj_type, obj_code) else "VYEMKA_OTHER"
        if mapped == "SAND":
            if _general_is_pile_field_object_type(obj_type, obj_code):
                return "SAND_PILE"
            if _general_is_oh_object_type(obj_type, obj_code):
                return "SAND_OH"
        return mapped
    if code == "TOPSOIL_STRIPPING" or "прс" in text or "растительн" in text:
        return "PRS"
    if code == "EXCAVATION_MAIN":
        return "VYEMKA_PILE" if _general_is_pile_field_object_type(obj_type, obj_code) else "VYEMKA_OH"
    if code in {"EARTH_EXCAVATION", "PEAT_REMOVAL"} or "выем" in text or "выторф" in text:
        if _general_is_pile_field_object_type(obj_type, obj_code):
            return "VYEMKA_PILE"
        if _general_is_oh_object_type(obj_type, obj_code):
            return "VYEMKA_OH"
        return "VYEMKA" if _general_is_vad_object_type(obj_type, obj_code) else "VYEMKA_OTHER"
    if code in {"EMBANKMENT_CONSTRUCTION", "WEAK_SOIL_REPLACEMENT", "PAVEMENT_SANDING", "SHOULDER_BACKFILL"} or "песок" in text:
        if _general_is_pile_field_object_type(obj_type, obj_code):
            return "SAND_PILE"
        return "SAND_OH" if _general_is_oh_object_type(obj_type, obj_code) else "SAND"
    if code == "SLOPE_FORMATION_CC" or ("щеб" in text and "щп" not in text):
        return "SCHEBEN"
    if code in {"CRUSHED_STONE_PLACEMENT", "FIRST_PROTECTIVE_LAYER", "SECOND_PROTECTIVE_LAYER", "ZS1", "ZS2"}:
        return "SHPS"
    if "щпс" in text or "щпгс" in text or "пгс" in text:
        return "SHPS"
    if code == "DITCH_CONSTRUCTION" or "кювет" in text or "канав" in text:
        return "DITCH"
    if code == "AREA_GRADING" or "планиров" in text:
        return "GRADING"
    if "перемещ" in text:
        return "MOVE"
    if "сопутств" in text:
        return "RELATED"
    if obj_type == "PILE_DRIVING_PAD":
        return "PILE_PAD"
    return None


def _general_effective_work_category(
    rules: list[dict],
    tag: Optional[str],
    wt_code: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
    source_bucket: Optional[str] = None,
) -> Optional[str]:
    """Resolve a General-report work category without treating config as exclusion.

    Configured rows support owner-defined splits, but ordinary recognized work
    tags must still flow into the ready template even when the compact default
    config does not list them explicitly (for example Планировка/Канава rows).
    """
    configured = _general_configured_work_category(
        rules,
        tag,
        object_type_code,
        object_code,
        source_bucket,
    )
    if configured:
        return configured
    return _general_work_category(tag, wt_code, object_type_code, object_code)


def _general_plan_work_category(
    rules: list[dict],
    tag: Optional[str],
    wt_code: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
    source_bucket: Optional[str] = None,
) -> Optional[str]:
    """Resolve plan categories with business rules that must not affect facts."""
    if (wt_code or "").upper() in GENERAL_REPORT_PLAN_SAND_WORK_TYPE_CODES:
        if _general_is_pile_field_object_type(object_type_code, object_code):
            return "SAND_PILE"
        if _general_is_oh_object_type(object_type_code, object_code):
            return "SAND_OH"
        if _general_is_vad_object_type(object_type_code, object_code):
            return "SAND_VAD"
        return "SAND"
    return _general_effective_work_category(
        rules,
        tag,
        wt_code,
        object_type_code,
        object_code,
        source_bucket,
    )


def _general_boundary_kind_case_sql(object_type_expr: str) -> str:
    return f"""CASE
              WHEN {object_type_expr} = 'TEMP_ROAD' THEN 'temp_roads'
              WHEN {object_type_expr} = 'SERVICE_ROAD' THEN 'temp_roads'
              WHEN {object_type_expr} = 'TEMP_ROAD_PIPE' THEN 'temp_roads'
              WHEN {object_type_expr} IN ('PILE_FIELD', 'PILE_DRIVING_PAD', 'ISSO_ACCESS', 'PIPE', 'BRIDGE', 'OVERPASS', 'TECH_ROAD') THEN 'piles_pipes'
              ELSE 'main'
            END"""


def _general_equipment_work_category(
    rules: list[dict],
    tag: Optional[str],
    wt_code: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
    source_bucket: Optional[str] = None,
) -> Optional[str]:
    """Resolve category for equipment productivity rows.

    The volume-summary rows deliberately split earthwork by a compact set of
    business buckets (ВАД / ОХ). The equipment tables are broader: the
    excavator/bulldozer "Выемка" rows should count the machinery and volume for
    excavation/peat-removal performed on access pads and ISSO approach areas as
    well, otherwise техвыработка disappears even though the DB fact is valid.
    """
    code = (wt_code or "").upper()
    obj_type = (object_type_code or "").upper()
    text = _general_normalize_text(tag)
    if code == "DITCH_CONSTRUCTION" or "кювет" in text or "канав" in text:
        return "DITCH"
    if (
        code in {"EARTH_EXCAVATION", "PEAT_REMOVAL"}
        or "выем" in text
        or "выторф" in text
    ) and (
        obj_type in {"PILE_FIELD", "PILE_DRIVING_PAD", "ISSO_ACCESS", "BRIDGE", "OVERPASS"}
        or _general_is_pile_access_tech_road(obj_type, object_code)
    ):
        return "VYEMKA"
    category = _general_effective_work_category(
        rules,
        tag,
        wt_code,
        object_type_code,
        object_code,
        source_bucket,
    )
    if category in {"VYEMKA_OTHER", "VYEMKA_PILE"}:
        return "VYEMKA"
    if category:
        return category
    return None


def _general_material_movement_equipment_category(
    material: Optional[str],
    movement_type: Optional[str],
    from_object_type_code: Optional[str] = None,
    to_object_type_code: Optional[str] = None,
) -> Optional[str]:
    route = str(movement_type or "").strip()
    if route in {"stockpile_to_stockpile", "constructive_to_stockpile", "constructive_to_constructive"}:
        return "MOVE"
    if route == "stockpile_to_constructive" and material in {"SOIL", "PEAT"}:
        return "MOVE"
    if material in {"SOIL", "PEAT"} and _general_is_constructive_object_type(from_object_type_code) and _general_is_constructive_object_type(to_object_type_code):
        return "MOVE"
    if material == "SAND":
        return "SAND"
    if material == "SHPS":
        return "SHPS"
    if material == "SCHEBEN":
        return "SCHEBEN"
    return None


def _general_source_bucket(labor_source: Optional[str], contractor_name: Optional[str]) -> str:
    contractor = (contractor_name or "").strip().lower().replace("ё", "е")
    contractor = re.sub(r"[\"'«»“”„]+", "", contractor)
    contractor = re.sub(r"\s+", " ", contractor).strip()
    source = (labor_source or "").strip().lower()
    if "алмаз" in contractor:
        return "almaz"
    if source == "own" or "собствен" in contractor or bool(re.search(r"(?:^|\b)(?:ооо\s+)?ждс(?:\b|$)", contractor)):
        return "non_hired"
    if source == "hired":
        return "hired"
    return "non_hired"


def _new_work_fact_slot() -> dict[str, dict[str, float]]:
    return {
        "total": _section_values(),
        "day": _section_values(),
        "night": _section_values(),
        "non_hired": _section_values(),
        "almaz": _section_values(),
        "hired": _section_values(),
    }


def _query_general_work_facts(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, float]]]:
    where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
    ]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs_eff.code AS section_code,
               dwi.shift,
               wt.code AS wt_code,
               ot.code AS object_type_code,
               obj.object_code AS object_code,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               dwi.labor_source_type,
               dwi.contractor_name,
               SUM(
                 CASE
                   WHEN seg.id IS NULL THEN COALESCE(dwi.volume, 0)
                   WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                   WHEN seg_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_count.cnt
                   ELSE COALESCE(dwi.volume, 0)
                 END
               )::numeric AS amount
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND seg.id IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        GROUP BY cs_eff.code, dwi.shift, wt.code, ot.code, obj.object_code, 6, dwi.labor_source_type, dwi.contractor_name
        """,
        params,
    )
    rules = _general_report_work_rules()
    facts: dict[str, dict[str, dict[str, float]]] = {}
    for row in rows:
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        category = _general_effective_work_category(
            rules,
            row.get("analytics_tag"),
            row.get("wt_code"),
            row.get("object_type_code"),
            row.get("object_code"),
            source_bucket,
        )
        categories: list[str] = [category] if category else []
        categories.extend(
            _general_additional_split_categories(
                category,
                row.get("object_type_code"),
                row.get("object_code"),
            )
        )
        if _general_is_local_soil_tag(row.get("analytics_tag")):
            categories.append("SOIL_LOCAL")
            categories.extend(_general_local_soil_extra_categories(row.get("object_code")))
        if not categories:
            continue
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        shift = (row.get("shift") or "").lower()
        for key in dict.fromkeys(categories):
            slot = facts.setdefault(key, _new_work_fact_slot())
            _add_section_value(slot["total"], section, amount)
            _add_section_value(slot["night" if shift == "night" else "day"], section, amount)
            _add_section_value(slot[source_bucket], section, amount)
    return facts


def _general_material_bucket(material_code: Optional[str], material_name: Optional[str]) -> Optional[str]:
    code = (material_code or "").strip().upper().replace(" ", "_")
    name = (material_name or "").strip().lower().replace("ё", "е")
    if code == "SAND" or "пес" in name:
        return "SAND"
    if code == "SOIL" or "грунт" in name:
        return "SOIL"
    if code == "PEAT" or "торф" in name:
        return "PEAT"
    if code in {"SHPGS", "SHPS", "ЩПС", "ЩПГС", "PGS"} or "щп" in name or "пгс" in name:
        return "SHPS"
    if code in {"CRUSHED_STONE", "SCHЕBEN", "SCHEBEN"} or "щеб" in name:
        return "SCHEBEN"
    return None


GENERAL_CONSTRUCTIVE_OBJECT_TYPE_CODES = {
    "MAIN_TRACK",
    "TEMP_ROAD",
    "TEMP_ROAD_PIPE",
    "SERVICE_ROAD",
    "ISSO_ACCESS",
    "TECH_ROAD",
    "PILE_DRIVING_PAD",
    "PIPE",
    "PILE_FIELD",
    "STATION_TRACK",
    "INTERSECTION_PROP",
}


def _general_is_constructive_object_type(type_code: Optional[str]) -> bool:
    return (type_code or "").strip().upper() in GENERAL_CONSTRUCTIVE_OBJECT_TYPE_CODES


def _general_is_soil_cut_to_embankment_movement(row: dict) -> bool:
    """Owner definition for quarry-table row "Объем из выемки в насыпь".

    Count SOIL movements from any source into another object, except when the
    destination is a stockpile. Основной ход, temporary roads, pipes/pile pads,
    quarries and other catalogued entities are all objects; the row is about the
    soil ending up in a non-stockpile object, not about the specific source kind.
    """
    if _general_material_bucket(row.get("material_code"), row.get("material_name")) != "SOIL":
        return False
    destination_type = (row.get("to_object_type_code") or "").strip().upper()
    return bool(destination_type) and destination_type != "STOCKPILE"


def _query_general_movement_facts(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, float]]]:
    where = [
        "mm.report_date >= %s",
        "mm.report_date <= %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("mm"),
    ]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               m.code AS material_code,
               m.name AS material_name,
               mm.movement_type,
               src_ot.code AS from_object_type_code,
               dst_ot.code AS to_object_type_code,
               mm.labor_source_type,
               mm.contractor_name,
               SUM(mm.volume)::numeric AS amount
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        LEFT JOIN objects src_obj ON src_obj.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src_obj.object_type_id
        LEFT JOIN objects dst_obj ON dst_obj.id = mm.to_object_id
        LEFT JOIN object_types dst_ot ON dst_ot.id = dst_obj.object_type_id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, mm.shift, m.code, m.name, mm.movement_type, src_ot.code, dst_ot.code, mm.labor_source_type, mm.contractor_name
        """,
        params,
    )
    facts: dict[str, dict[str, dict[str, float]]] = {}
    for row in rows:
        material = _general_material_bucket(row.get("material_code"), row.get("material_name"))
        movement_type = (row.get("movement_type") or "").strip()
        keys: list[str] = []
        if material == "SAND" and movement_type == "pit_to_stockpile":
            keys.append("SAND_PIT_TO_STOCKPILE")
            keys.append("SAND_SITE_DELIVERED")
        elif material == "SAND" and movement_type == "pit_to_constructive":
            keys.append("SAND_PIT_TO_CONSTRUCTIVE")
            keys.append("SAND_SITE_DELIVERED")
        elif material == "SAND" and movement_type == "stockpile_to_constructive":
            keys.append("SAND_STOCKPILE_TO_CONSTRUCTIVE")
        elif material == "SHPS" and movement_type == "pit_to_stockpile":
            keys.append("SHPS_PIT_TO_STOCKPILE")
        elif material == "SCHEBEN" and movement_type == "pit_to_stockpile":
            keys.append("SCHEBEN_PIT_TO_STOCKPILE")
        elif material == "SHPS" and movement_type == "pit_to_constructive":
            keys.append("SHPS_PIT_TO_CONSTRUCTIVE")
        elif _general_is_soil_cut_to_embankment_movement(row):
            keys.append("SOIL_STOCKPILE_TO_CONSTRUCTIVE")
        if not keys:
            continue
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        for key in keys:
            slot = facts.setdefault(key, _new_work_fact_slot())
            _add_section_value(slot["total"], section, amount)
            _add_section_value(slot[shift], section, amount)
            _add_section_value(slot[source_bucket], section, amount)
    return facts


def _query_general_dashboard_material_delivery_facts(
    material_code: str,
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, float]]:
    """Material delivery totals aligned with dashboard material-flow source policy.

    The dashboard has owner-approved historical material-haul totals up to a
    reference date and then appends available `material_movements` facts after
    actual DB data starts. The cumulative General report rows must use the
    same policy so owner-visible "за все время" totals match the dashboard
    instead of only the raw DB tail.
    """
    slot = _new_work_fact_slot()
    if d_from > d_to:
        return slot
    wanted_code = str(material_code or "").upper()
    allowed_sections = {_merge_section(code) or code for code in (codes or [])}
    data = dashboard_material_flow(d_from.isoformat(), d_to.isoformat())
    for row in data.get("rows") or []:
        if str(row.get("material") or "").upper() != wanted_code:
            continue
        if row.get("movement_type") not in {"pit_to_stockpile", "pit_to_constructive"}:
            continue
        section = _merge_section(row.get("section_code")) or row.get("section_code")
        if allowed_sections and section not in allowed_sections:
            continue
        try:
            amount = float(row.get("volume") or 0)
        except (TypeError, ValueError):
            amount = 0.0
        if abs(amount) < 0.0005:
            continue
        source_bucket = str(row.get("contractor_bucket") or "").strip().lower()
        if source_bucket == "almaz":
            bucket = "almaz"
        elif source_bucket in {"hire", "hired"}:
            bucket = "hired"
        else:
            bucket = "non_hired"
        _add_section_value(slot["total"], section, amount)
        _add_section_value(slot[bucket], section, amount)
    return slot


def _query_general_dashboard_sand_haul_facts(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, float]]:
    return _query_general_dashboard_material_delivery_facts("SAND", d_from, d_to, codes)


def _query_general_dashboard_shpgs_delivery_facts(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, float]]:
    return _query_general_dashboard_material_delivery_facts("SHPGS", d_from, d_to, codes)


def _query_general_work_plans(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
    *,
    plan_scope: str = "all",
) -> dict[str, dict[str, dict[str, float]]]:
    try:
        row = query_one(
            """
            SELECT EXISTS (
              SELECT 1 FROM information_schema.tables
              WHERE table_schema = 'public' AND table_name = 'planned_work_items'
            ) AS exists
            """
        )
        if not row or not row.get("exists"):
            return {}
    except Exception:
        return {}
    where = ["COALESCE(pwi.is_active, true) IS TRUE"]
    params: list = [d_from, PROJECT_START_DATE, d_to, d_from]
    section_expr = "COALESCE(cs_override.code, sec_plan.section_code, sec_object.section_code, cs_mt.code)"
    if codes:
        where.append(f"{section_expr} = ANY(%s)")
        params.append(codes)
    if plan_scope == "dated_only":
        where.append("pwi.period_start IS NOT NULL")
        where.append("pwi.period_end IS NOT NULL")
    elif plan_scope == "total_only":
        where.append("pwi.period_start IS NULL")
        where.append("pwi.period_end IS NULL")
    elif plan_scope != "all":
        raise ValueError(f"Unsupported general plan scope: {plan_scope}")
    params.extend([d_from, PROJECT_START_DATE, d_to, d_from])
    try:
        rows = query(
            f"""
            WITH main_track_section_map(object_code, section_code) AS (
              VALUES
                ('MAIN_001', 'UCH_1'),
                ('MAIN_002', 'UCH_2'),
                ('MAIN_003', 'UCH_3'),
                ('MAIN_031', 'UCH_3'),
                ('MAIN_032', 'UCH_3'),
                ('MAIN_OH_STAGE3', 'UCH_3'),
                ('MAIN_004', 'UCH_4'),
                ('MAIN_005', 'UCH_5'),
                ('MAIN_006', 'UCH_6'),
                ('MAIN_007', 'UCH_7'),
                ('MAIN_008', 'UCH_8')
            )
            SELECT {section_expr} AS section_code,
                   wt.code AS wt_code,
                   ot.code AS object_type_code,
                   obj.object_code AS object_code,
                   COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), wt.name) AS analytics_tag,
                   SUM(
                     CASE
                       WHEN pwi.period_start IS NULL AND pwi.period_end IS NULL THEN
                         CASE WHEN %s::date = %s::date THEN COALESCE(pwi.planned_volume, 0) ELSE 0 END
                       ELSE COALESCE(pwi.planned_volume, 0)
                         * GREATEST(0, (LEAST(pwi.period_end, %s::date) - GREATEST(pwi.period_start, %s::date) + 1))::numeric
                         / GREATEST(1, (pwi.period_end - pwi.period_start + 1))::numeric
                     END
                   )::numeric AS amount
            FROM planned_work_items pwi
            JOIN work_types wt ON wt.id = pwi.work_type_id
            LEFT JOIN objects obj ON obj.id = pwi.object_id
            LEFT JOIN object_types ot ON ot.id = obj.object_type_id
            LEFT JOIN LATERAL (
              SELECT cs.code AS section_code
              FROM construction_section_versions csv
              JOIN construction_sections cs ON cs.id = csv.section_id
              WHERE pwi.pk_start IS NOT NULL
                AND pwi.pk_end IS NOT NULL
                AND csv.is_current = true
                AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
                AND (
                  (
                    pwi.pk_start = pwi.pk_end
                    AND pwi.pk_start >= LEAST(csv.pk_start, csv.pk_end)
                    AND pwi.pk_start < GREATEST(csv.pk_start, csv.pk_end)
                  )
                  OR (
                    pwi.pk_start <> pwi.pk_end
                    AND LEAST(GREATEST(pwi.pk_start, pwi.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                        > GREATEST(LEAST(pwi.pk_start, pwi.pk_end), LEAST(csv.pk_start, csv.pk_end))
                  )
                )
              ORDER BY CASE
                         WHEN pwi.pk_start = pwi.pk_end
                          AND pwi.pk_start >= LEAST(csv.pk_start, csv.pk_end)
                          AND pwi.pk_start < GREATEST(csv.pk_start, csv.pk_end)
                         THEN 1
                         ELSE GREATEST(
                           0,
                           LEAST(GREATEST(pwi.pk_start, pwi.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                           - GREATEST(LEAST(pwi.pk_start, pwi.pk_end), LEAST(csv.pk_start, csv.pk_end))
                         )
                       END DESC,
                       cs.sort_order NULLS LAST,
                       cs.code
              LIMIT 1
            ) sec_plan ON true
            LEFT JOIN LATERAL (
              SELECT cs.code AS section_code
              FROM object_segments os
              JOIN construction_section_versions csv
                ON csv.is_current = true
               AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
               AND (
                 (
                   os.pk_start = os.pk_end
                   AND os.pk_start >= LEAST(csv.pk_start, csv.pk_end)
                   AND os.pk_start < GREATEST(csv.pk_start, csv.pk_end)
                 )
                 OR (
                   os.pk_start <> os.pk_end
                   AND LEAST(GREATEST(os.pk_start, os.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                       > GREATEST(LEAST(os.pk_start, os.pk_end), LEAST(csv.pk_start, csv.pk_end))
                 )
               )
              JOIN construction_sections cs ON cs.id = csv.section_id
              WHERE os.object_id = pwi.object_id
              ORDER BY CASE
                         WHEN os.pk_start = os.pk_end
                          AND os.pk_start >= LEAST(csv.pk_start, csv.pk_end)
                          AND os.pk_start < GREATEST(csv.pk_start, csv.pk_end)
                         THEN 1
                         ELSE GREATEST(
                           0,
                           LEAST(GREATEST(os.pk_start, os.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                           - GREATEST(LEAST(os.pk_start, os.pk_end), LEAST(csv.pk_start, csv.pk_end))
                         )
                       END DESC,
                       cs.sort_order NULLS LAST,
                       cs.code
              LIMIT 1
            ) sec_object ON true
            LEFT JOIN construction_sections cs_override
              ON cs_override.code = CASE
                WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
                ELSE NULL
              END
             AND cs_override.is_active IS NOT FALSE
            LEFT JOIN main_track_section_map mt_map
              ON mt_map.object_code = obj.object_code
             AND ot.code = 'MAIN_TRACK'
            LEFT JOIN construction_sections cs_mt
              ON cs_mt.code = mt_map.section_code
             AND cs_mt.is_active IS NOT FALSE
            WHERE {' AND '.join(where)}
              AND (
                (pwi.period_start IS NULL AND pwi.period_end IS NULL AND %s::date = %s::date)
                OR (pwi.period_start IS NOT NULL AND pwi.period_end IS NOT NULL AND pwi.period_start <= %s::date AND pwi.period_end >= %s::date)
              )
            GROUP BY 1, 2, 3, 4, 5
            """,
            params,
        )
    except Exception:
        return {}
    rules = _general_report_work_rules()
    plans: dict[str, dict[str, dict[str, float]]] = {}
    for row in rows:
        category = _general_plan_work_category(
            rules,
            row.get("analytics_tag"),
            row.get("wt_code"),
            row.get("object_type_code"),
            row.get("object_code"),
        )
        if not category:
            continue
        categories = [category, *_general_additional_split_categories(category, row.get("object_type_code"), row.get("object_code"))]
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        for key in dict.fromkeys(categories):
            slot = plans.setdefault(key, _new_work_fact_slot())
            _add_section_value(slot["total"], section, amount)
    return plans



def _scale_general_plan_values(values: Optional[dict[str, float]], factor: float) -> dict[str, float]:
    scaled = _section_values()
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        scaled[section_code] = float((values or {}).get(section_code) or 0) * factor
    return scaled



def _scale_general_plan_slots(
    plans: dict[str, dict[str, dict[str, float]]],
    factor: float,
) -> dict[str, dict[str, dict[str, float]]]:
    scaled: dict[str, dict[str, dict[str, float]]] = {}
    for category, slot in (plans or {}).items():
        target = _new_work_fact_slot()
        for bucket, values in (slot or {}).items():
            if bucket in target:
                target[bucket] = _scale_general_plan_values(values, factor)
        scaled[category] = target
    return scaled



def _overlay_general_plan_slots(
    base: dict[str, dict[str, dict[str, float]]],
    override: dict[str, dict[str, dict[str, float]]],
) -> dict[str, dict[str, dict[str, float]]]:
    merged: dict[str, dict[str, dict[str, float]]] = {}
    for category, slot in (base or {}).items():
        target = _new_work_fact_slot()
        for bucket, values in (slot or {}).items():
            if bucket in target:
                target[bucket] = {section: float(value or 0) for section, value in (values or {}).items()}
        merged[category] = target
    for category, slot in (override or {}).items():
        target = merged.setdefault(category, _new_work_fact_slot())
        for bucket, values in (slot or {}).items():
            if bucket not in target:
                continue
            for section, value in (values or {}).items():
                target[bucket][section] = float(value or 0)
    return merged



def _query_general_volume_plan_periods(
    report_date: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, dict[str, float]]]]:
    month_start = report_date.replace(day=1)
    if month_start.month == 12:
        next_month_start = month_start.replace(year=month_start.year + 1, month=1)
    else:
        next_month_start = month_start.replace(month=month_start.month + 1)
    month_end = next_month_start - timedelta(days=1)
    month_plans = _query_general_work_plans(month_start, month_end, codes, plan_scope="dated_only")
    total_regular_plans = _query_general_work_plans(PROJECT_START_DATE, report_date, codes, plan_scope="dated_only")
    total_only_plans = _query_general_work_plans(PROJECT_START_DATE, report_date, codes, plan_scope="total_only")
    total_plans = _overlay_general_plan_slots(total_regular_plans, total_only_plans)
    days_in_month = max(1, (month_end - month_start).days + 1)
    return {
        "day": _scale_general_plan_slots(month_plans, 1.0 / days_in_month),
        "week": _scale_general_plan_slots(month_plans, 0.25),
        "month": month_plans,
        "total": total_plans,
    }


def _query_general_top_quarry_rows(report_date: date_cls, codes: Optional[list[str]]) -> tuple[list[dict], dict[str, dict[str, float]], dict[str, dict[str, float]]]:
    where = [
        "mm.report_date = %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        "src_ot.code = 'BORROW_PIT'",
        "mm.movement_type IN ('pit_to_stockpile', 'pit_to_constructive')",
        _approved_report_exists("mm"),
    ]
    params: list = [report_date]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               COALESCE(NULLIF(src.name, ''), src.object_code, 'Карьер') AS quarry_name,
               m.code AS material_code,
               COALESCE(NULLIF(m.name, ''), m.code) AS material_name,
               mm.labor_source_type,
               mm.contractor_name,
               SUM(mm.volume)::numeric AS amount
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, mm.shift, src.name, src.object_code, m.code, m.name, mm.labor_source_type, mm.contractor_name
        """,
        params,
    )
    grouped: dict[str, dict] = {}
    almaz = _new_work_fact_slot()
    hired = _new_work_fact_slot()
    for row in rows:
        material = _general_material_bucket(row.get("material_code"), row.get("material_name"))
        quarry_name = _quarry_display_name(row.get("quarry_name") or "Карьер")
        label = quarry_name
        if material != "SAND":
            label = f"{quarry_name} ({row.get('material_name') or row.get('material_code') or 'материал'})"
        item = grouped.setdefault(label, {"label": label, "total": _section_values(), "day": _section_values(), "night": _section_values()})
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        _add_section_value(item["total"], section, amount)
        _add_section_value(item[shift], section, amount)
        if material == "SAND":
            bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
            if bucket == "almaz":
                _add_section_value(almaz["total"], section, amount)
                _add_section_value(almaz[shift], section, amount)
            elif bucket == "hired":
                _add_section_value(hired["total"], section, amount)
                _add_section_value(hired[shift], section, amount)
    detail_rows = [item for item in grouped.values() if sum(item["total"].values()) > 0]
    detail_rows.sort(key=lambda item: (-sum(item["total"].values()), item["label"]))
    return detail_rows, almaz, hired


def _general_quarry_label_key(label: object) -> str:
    text = str(label or "").lower().replace("ё", "е")
    text = re.sub(r"[\"'«»“”„]+", "", text)
    text = re.sub(r"\bкарьер\b", "", text)
    text = re.sub(r"\b(?:миголо[шщ]и|милогоши)\b", "миголощи", text)
    text = re.sub(r"\s*\(\s*(щпгс|щпс|пгс|песок|sand|shpgs|shps)\s*\)\s*", r" \1 ", text)
    text = re.sub(r"[^0-9a-zа-я]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    parts = text.split()
    if len(parts) > 1 and parts[-1] in QUARRY_MATERIAL_SUFFIX_KEYS:
        return f"{' '.join(parts[:-1])} ({parts[-1]})"
    return text


def _general_quarry_source_fact_key(label_key: str, source_bucket: str) -> str:
    return f"{label_key}||source:{source_bucket}"


def _general_quarry_filtered_fact_key(
    label_key: str,
    source_bucket: Optional[str] = None,
    material: Optional[str] = None,
    movement_type: Optional[str] = None,
    from_scope: Optional[str] = None,
    to_scope: Optional[str] = None,
) -> str:
    parts = [label_key]
    if source_bucket:
        parts.append(f"source:{source_bucket}")
    if material:
        parts.append(f"material:{material}")
    if movement_type:
        parts.append(f"movement:{movement_type}")
    if from_scope:
        parts.append(f"from:{from_scope}")
    if to_scope:
        parts.append(f"to:{to_scope}")
    return "||".join(parts)


def _general_quarry_source_key(label: object, source_bucket: str) -> str:
    return _general_quarry_filtered_fact_key(_general_quarry_label_key(label), source_bucket)


def _general_quarry_label_keys(label: object) -> set[str]:
    key = _general_quarry_label_key(label)
    keys = {key}

    def add_variant(value: str) -> None:
        value = re.sub(r"\s+", " ", value).strip()
        if value:
            keys.add(value)

    if " алмаз" in key:
        add_variant(key.replace(" алмаз", ""))
    without_material = re.sub(r"\s*\((?:щпгс|щпс|пгс|песок|sand|shpgs|shps)\)\s*", " ", key).strip()
    add_variant(without_material)
    for item in list(keys):
        if "щпгс" in item:
            add_variant(item.replace("щпгс", "щпс"))
        if "щпс" in item:
            add_variant(item.replace("щпс", "щпгс"))
    return {item for item in keys if item}


def _new_general_quarry_slot() -> dict[str, dict[str, float]]:
    return {"total": _section_values(), "day": _section_values(), "night": _section_values()}


def _sum_general_sections(values: dict[str, float]) -> float:
    return sum(float((values or {}).get(code) or 0) for code in GENERAL_ANALYTICS_SECTION_CODES)


def _copy_general_quarry_slot(slot: dict[str, dict[str, float]]) -> dict[str, dict[str, float]]:
    copied = _new_general_quarry_slot()
    for bucket in ("total", "day", "night"):
        for code in GENERAL_ANALYTICS_SECTION_CODES:
            copied[bucket][code] = float(((slot or {}).get(bucket) or {}).get(code) or 0)
    return copied


def _put_general_quarry_slot(
    facts: dict[str, dict[str, dict[str, float]]],
    label: str,
    slot: dict[str, dict[str, float]],
) -> None:
    target = facts.setdefault(_general_quarry_label_key(label), _new_general_quarry_slot())
    for bucket in ("total", "day", "night"):
        for code in GENERAL_ANALYTICS_SECTION_CODES:
            target[bucket][code] += float(((slot or {}).get(bucket) or {}).get(code) or 0)


def _general_quarry_slot_for_label(
    facts: dict[str, dict[str, dict[str, float]]],
    label: object,
    source_bucket: Optional[str] = None,
    material: Optional[str] = None,
    movement_type: Optional[str] = None,
    from_scope: Optional[str] = None,
    to_scope: Optional[str] = None,
) -> dict[str, dict[str, float]]:
    for key in _general_quarry_label_keys(label):
        fact_key = _general_quarry_filtered_fact_key(key, source_bucket, material, movement_type, from_scope, to_scope)
        if fact_key in facts:
            return _copy_general_quarry_slot(facts[fact_key])
    return _new_general_quarry_slot()


def _general_scope_filter_values(filters: dict, prefix: str) -> list[str]:
    values: list[str] = []
    for code in _general_clean_string_list(filters.get(f"{prefix}_object_type_codes"), limit=80):
        values.append(f"type:{code}")
    for code in _general_clean_string_list(filters.get(f"{prefix}_object_codes"), limit=160):
        values.append(f"object:{code}")
    return list(dict.fromkeys(values))


def _general_scope_fact_values(type_code: object, object_code: object) -> list[str]:
    values: list[str] = []
    type_text = str(type_code or "").strip()
    object_text = str(object_code or "").strip()
    if type_text:
        values.append(f"type:{type_text}")
    if object_text:
        values.append(f"object:{object_text}")
    return values


def _add_general_quarry_slot(target: dict[str, dict[str, float]], source: dict[str, dict[str, float]]) -> None:
    for bucket in ("total", "day", "night"):
        for code in GENERAL_ANALYTICS_SECTION_CODES:
            target[bucket][code] += float(((source or {}).get(bucket) or {}).get(code) or 0)


def _general_quarry_slot_for_rule(
    facts: dict[str, dict[str, dict[str, float]]],
    rule: dict,
) -> dict[str, dict[str, float]]:
    filters = _general_row_filters(rule.get("filters"))
    labels = _general_clean_string_list(filters.get("quarry_labels"), limit=24)
    source_buckets = _general_clean_string_list(filters.get("source_buckets"), limit=8)
    materials = _general_clean_string_list(filters.get("materials"), limit=16)
    movement_types = _general_clean_string_list(filters.get("movement_types"), limit=16)
    from_scopes = _general_scope_filter_values(filters, "from")
    to_scopes = _general_scope_filter_values(filters, "to")
    if not labels:
        labels = [GENERAL_QUARRY_ALL_LABEL]
    combined = _new_general_quarry_slot()
    for label in labels:
        for source_bucket in (source_buckets or [None]):
            for material in (materials or [None]):
                for movement_type in (movement_types or [None]):
                    for from_scope in (from_scopes or [None]):
                        for to_scope in (to_scopes or [None]):
                            _add_general_quarry_slot(
                                combined,
                                _general_quarry_slot_for_label(facts, label, source_bucket, material, movement_type, from_scope, to_scope),
                            )
    return combined


_GENERAL_TOP_QUARRY_FORCE_TOTAL_LABELS = {
    "завоз силами алмаз",
    "завоз песка наемниками",
    "завоз наемниками",
}
_GENERAL_TOP_QUARRY_EXCLUDE_TOTAL_LABELS = {
    "коровкино (щпгс)",
    "коровкино щпгс",
    "коровкино",
}


def _general_top_quarry_rule_counts_in_total(rule: dict) -> bool:
    labels = [_general_normalize_text(rule.get("label"))]
    filters = _general_row_filters(rule.get("filters"))
    labels.extend(_general_normalize_text(item) for item in _general_clean_string_list(filters.get("quarry_labels"), limit=24))
    label_keys = {_general_quarry_label_key(label) for label in labels if label}
    if label_keys & _GENERAL_TOP_QUARRY_EXCLUDE_TOTAL_LABELS:
        return False
    if rule.get("include_in_totals", True):
        return True
    return any(label in _GENERAL_TOP_QUARRY_FORCE_TOTAL_LABELS for label in labels if label)


def _query_general_quarry_period_facts(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, float]]]:
    where = [
        "mm.report_date >= %s",
        "mm.report_date <= %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        "mm.movement_type IN ('pit_to_stockpile', 'pit_to_constructive')",
        _approved_report_exists("mm"),
    ]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               COALESCE(NULLIF(src.name, ''), src.object_code, 'Источник') AS source_name,
               src.object_code AS source_object_code,
               src_ot.code AS source_object_type_code,
               src_ot.name AS source_object_type_name,
               COALESCE(NULLIF(dst.name, ''), dst.object_code, '') AS destination_name,
               dst.object_code AS destination_object_code,
               dst_ot.code AS destination_object_type_code,
               dst_ot.name AS destination_object_type_name,
               m.code AS material_code,
               COALESCE(NULLIF(m.name, ''), m.code) AS material_name,
               mm.movement_type,
               mm.labor_source_type,
               mm.contractor_name,
               SUM(mm.volume)::numeric AS amount
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
        LEFT JOIN objects dst ON dst.id = mm.to_object_id
        LEFT JOIN object_types dst_ot ON dst_ot.id = dst.object_type_id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, mm.shift,
                 src.name, src.object_code, src_ot.code, src_ot.name,
                 dst.name, dst.object_code, dst_ot.code, dst_ot.name,
                 m.code, m.name, mm.movement_type, mm.labor_source_type, mm.contractor_name
        """,
        params,
    )
    facts: dict[str, dict[str, dict[str, float]]] = {}

    def add_fact(
        label: str,
        section: Optional[str],
        shift: str,
        amount: float,
        source_bucket: Optional[str],
        material_values: list[str],
        movement_type: Optional[str],
        from_scopes: list[str],
        to_scopes: list[str],
    ) -> None:
        label_keys = list(dict.fromkeys([
            _general_quarry_label_key(label),
            _general_quarry_label_key(GENERAL_QUARRY_ALL_LABEL),
        ]))
        source_filters = list(dict.fromkeys([None, source_bucket]))
        material_filters = list(dict.fromkeys([None, *material_values]))
        movement_filters = list(dict.fromkeys([None, movement_type]))
        from_filters = list(dict.fromkeys([None, *from_scopes]))
        to_filters = list(dict.fromkeys([None, *to_scopes]))
        for label_key in label_keys:
            for source_filter in source_filters:
                for material_filter in material_filters:
                    for movement_filter in movement_filters:
                        for from_filter in from_filters:
                            for to_filter in to_filters:
                                fact_key = _general_quarry_filtered_fact_key(
                                    label_key,
                                    source_filter,
                                    material_filter,
                                    movement_filter,
                                    from_filter,
                                    to_filter,
                                )
                                slot = facts.setdefault(fact_key, _new_general_quarry_slot())
                                _add_section_value(slot["total"], section, amount)
                                _add_section_value(slot[shift], section, amount)

    for row in rows:
        material_values = _general_material_filter_aliases(row.get("material_code"), row.get("material_name"))
        material_bucket = _general_material_bucket(row.get("material_code"), row.get("material_name"))
        movement_type = (row.get("movement_type") or "").strip()
        source_name = row.get("source_name") or "Источник"
        if (row.get("source_object_type_code") or "").strip() == "BORROW_PIT" or movement_type in {"pit_to_stockpile", "pit_to_constructive"}:
            source_name = _quarry_display_name(source_name)
        label = source_name
        if material_bucket != "SAND":
            label = f"{source_name} ({row.get('material_name') or row.get('material_code') or 'материал'})"
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        from_scopes = _general_scope_fact_values(row.get("source_object_type_code"), row.get("source_object_code"))
        to_scopes = _general_scope_fact_values(row.get("destination_object_type_code"), row.get("destination_object_code"))
        add_fact(label, section, shift, amount, source_bucket, material_values, movement_type, from_scopes, to_scopes)
        if material_bucket == "SAND":
            if source_bucket == "almaz":
                add_fact("Завоз силами АЛМАЗ", section, shift, amount, source_bucket, material_values, movement_type, from_scopes, to_scopes)
            elif source_bucket == "hired":
                add_fact("Завоз песка наемниками", section, shift, amount, source_bucket, material_values, movement_type, from_scopes, to_scopes)
    return facts

def _write_general_top_quarry_table(
    ws,
    report_date: date_cls,
    codes: Optional[list[str]],
    work_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    movement_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
) -> None:
    label_rows = _find_general_top_quarry_label_rows(ws)
    configured_rows = _general_report_top_quarry_rules()

    body_row = _first_general_top_body_row(ws)
    clear_max_row = (body_row - 1) if body_row else (_general_target_row(42) or 42)
    for row in range(4, min(clear_max_row, ws.max_row) + 1):
        for col_idx in range(2, 14):
            _set_general_cell_value(ws, row, col_idx, None)

    _set_general_cell_value(ws, 3, 2, "ДЕНЬ")
    _set_general_cell_value(ws, 3, 3, "НОЧЬ")
    _set_general_cell_value(ws, 3, 4, "Итого")
    _set_general_cell_value(ws, 3, 5, "Всего за день")
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=6):
        _set_general_cell_value(ws, 3, idx, section_code.replace("UCH_", ""))

    periods = _general_periods(report_date)
    quarry_periods: dict[str, dict[str, dict[str, dict[str, float]]]] = {}
    for period_key in ("day", "week", "month"):
        period_from, period_to = periods[period_key]
        facts = _query_general_quarry_period_facts(period_from, period_to, codes)
        _put_general_quarry_slot(
            facts,
            "Объем из выемки в насыпь",
            (movement_periods.get(period_key, {}).get("SOIL_STOCKPILE_TO_CONSTRUCTIVE") or _new_work_fact_slot()),
        )
        _put_general_quarry_slot(
            facts,
            "Объем выемки осн. хода",
            (work_periods.get(period_key, {}).get("VYEMKA_OH") or _new_work_fact_slot()),
        )
        quarry_periods[period_key] = facts

    total = _section_values()
    day_total = _section_values()
    night_total = _section_values()
    week_total = 0.0
    month_total = 0.0
    for row, rule in zip(label_rows, configured_rows):
        night_row = row + 1
        label = str(rule.get("label") or "").strip() or "Строка"
        day_slot = _general_quarry_slot_for_rule(quarry_periods.get("day", {}), rule)
        week_slot = _general_quarry_slot_for_rule(quarry_periods.get("week", {}), rule)
        month_slot = _general_quarry_slot_for_rule(quarry_periods.get("month", {}), rule)
        week_value = _sum_general_sections(week_slot["total"])
        month_value = _sum_general_sections(month_slot["total"])
        counts_in_total = _general_top_quarry_rule_counts_in_total(rule)
        if counts_in_total:
            week_total += week_value
            month_total += month_value
        _set_general_cell_value(ws, row, 2, _clean_report_number(week_value))
        _set_general_cell_value(ws, row, 3, _clean_report_number(month_value))
        _set_general_cell_value(ws, row, 4, label)
        _set_general_cell_value(ws, night_row, 4, None)
        _write_section_values_at_row(ws, row, day_slot["day"])
        _write_section_values_at_row(ws, night_row, day_slot["night"])
        if counts_in_total:
            for code in GENERAL_ANALYTICS_SECTION_CODES:
                day_total[code] += float(day_slot["day"].get(code) or 0)
                night_total[code] += float(day_slot["night"].get(code) or 0)
                total[code] += float(day_slot["total"].get(code) or 0)

    _set_general_cell_value(ws, 4, 4, "ИТОГО")
    _set_general_cell_value(ws, 5, 2, "Факт неделя")
    _set_general_cell_value(ws, 5, 3, "Факт месяц")
    _set_general_cell_value(ws, 5, 4, "Итого день")
    _set_general_cell_value(ws, 6, 2, _clean_report_number(week_total))
    _set_general_cell_value(ws, 6, 3, _clean_report_number(month_total))
    _set_general_cell_value(ws, 6, 4, "Итого ночь")
    _write_section_values_at_row(ws, 4, total)
    _write_section_values_at_row(ws, 5, day_total)
    _write_section_values_at_row(ws, 6, night_total)


def _query_general_sand_quarry_meta(report_date: date_cls, codes: Optional[list[str]]) -> dict[str, list[dict]]:
    try:
        _ensure_haul_distance_table()
        _ensure_material_movement_haul_distance_columns()
    except Exception:
        pass
    where = [
        "mm.report_date = %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        "src_ot.code = 'BORROW_PIT'",
        "mm.movement_type IN ('pit_to_stockpile', 'pit_to_constructive')",
        "(m.code = 'SAND' OR LOWER(COALESCE(m.name, '')) LIKE '%%пес%%')",
        _approved_report_exists("mm"),
    ]
    params: list = [report_date]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               src.id::text AS quarry_id,
               COALESCE(NULLIF(src.name, ''), src.object_code, 'Карьер') AS quarry_name,
               CASE
                 WHEN SUM(CASE WHEN COALESCE(mm.haul_distance_km, h.distance_km) IS NOT NULL THEN mm.volume ELSE 0 END) > 0
                 THEN SUM(mm.volume * COALESCE(mm.haul_distance_km, h.distance_km))
                      / SUM(CASE WHEN COALESCE(mm.haul_distance_km, h.distance_km) IS NOT NULL THEN mm.volume ELSE 0 END)
                 ELSE NULL
               END AS distance_km,
               SUM(mm.volume)::numeric AS amount
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
        LEFT JOIN section_quarry_haul_distances h
          ON h.section_code = cs.code
         AND h.quarry_object_id = src.id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, src.id, src.name, src.object_code
        HAVING SUM(mm.volume) <> 0
        ORDER BY cs.code, SUM(mm.volume) DESC, quarry_name
        """,
        params,
    )
    result: dict[str, list[dict]] = {code: [] for code in GENERAL_ANALYTICS_SECTION_CODES}
    for row in rows:
        section = _merge_section(row.get("section_code"))
        if section in result:
            item = dict(row)
            item["quarry_name"] = _quarry_display_name(item.get("quarry_name") or item.get("quarry_id") or "Карьер")
            result[section].append(item)
    return result


def _format_general_list(values: list[object]) -> str:
    out: list[str] = []
    for value in values:
        if value is None or value == "":
            continue
        text = str(value)
        try:
            num = float(value)
            text = str(_clean_report_number(num)).replace(".", ",")
        except (TypeError, ValueError):
            pass
        if text not in out:
            out.append(text)
    return " / ".join(out)


def _read_general_dump_truck_defaults(ws) -> dict[str, dict[str, object]]:
    defaults = {"quarry": {}, "distance": {}}
    row_by_key = {
        "quarry": _find_general_metadata_row(ws, "Карьер") or (_general_target_row(46) or 46),
        "distance": _find_general_metadata_row(ws, "Плечо возки,км") or (_general_target_row(47) or 47),
    }
    for idx, section_code in enumerate(GENERAL_ANALYTICS_SECTION_CODES, start=GENERAL_ANALYTICS_VALUE_START_COL + 1):
        defaults["quarry"][section_code] = ws.cell(row=row_by_key["quarry"], column=idx).value
        defaults["distance"][section_code] = ws.cell(row=row_by_key["distance"], column=idx).value
    return defaults


def _fill_general_dump_truck_metadata(
    ws,
    report_date: date_cls,
    codes: Optional[list[str]],
    defaults: Optional[dict[str, dict[str, object]]] = None,
) -> None:
    row_by_source = {
        source_row: (_find_general_metadata_row(ws, label) or _general_target_row(source_row))
        for source_row, label in GENERAL_DUMP_TRUCK_METADATA_SOURCE_ROWS.items()
    }
    for source_row, label in GENERAL_DUMP_TRUCK_METADATA_SOURCE_ROWS.items():
        row = row_by_source.get(source_row)
        if row is not None:
            _set_general_cell_value(ws, row, GENERAL_ANALYTICS_VALUE_START_COL, label)
    meta = _query_general_sand_quarry_meta(report_date, codes)
    quarry_values: dict[str, str] = {}
    distance_values: dict[str, str] = {}
    trips_total: dict[str, float] = _section_values()
    trips_day: dict[str, float] = _section_values()
    trips_night: dict[str, float] = _section_values()
    stockpile_day: dict[str, float] = _section_values()
    stockpile_night: dict[str, float] = _section_values()
    default_quarries = (defaults or {}).get("quarry") or {}
    default_distances = (defaults or {}).get("distance") or {}
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        rows = meta.get(section_code) or []
        quarry_values[section_code] = _format_general_list([r.get("quarry_name") for r in rows])
        distance_values[section_code] = _format_general_list([r.get("distance_km") for r in rows if r.get("distance_km") is not None])
        if not rows and section_code == "UCH_5":
            quarry_values[section_code] = "Васильки"
            distance_values[section_code] = "16"
        if not quarry_values[section_code]:
            quarry_values[section_code] = default_quarries.get(section_code) or ""
        if not distance_values[section_code]:
            distance_values[section_code] = default_distances.get(section_code) or ""
        section_num = _general_section_num(section_code)
        sand_norm = SAND_PIT_DIRECTION_NORMS.get(section_num or 0)
        stockpile_norm = SAND_STOCKPILE_TO_CONSTR_NORMS.get(section_num or 0)
        if sand_norm:
            trips_day[section_code] = float(sand_norm[0] or 0)
            trips_night[section_code] = float(sand_norm[0] or 0)
            trips_total[section_code] = trips_day[section_code] + trips_night[section_code]
        if stockpile_norm:
            stockpile_day[section_code] = float(stockpile_norm[0] or 0)
            stockpile_night[section_code] = float(stockpile_norm[0] or 0)
    metadata_values = {
        46: quarry_values,
        47: distance_values,
        48: trips_total,
        49: trips_day,
        50: trips_night,
        51: stockpile_day,
        52: stockpile_night,
    }
    for source_row, values in metadata_values.items():
        row = row_by_source.get(source_row)
        if row is not None:
            _write_section_text_values_at_row(ws, row, values)

def _general_equipment_class(equipment_type: Optional[str]) -> Optional[str]:
    text = (equipment_type or "").lower().replace("ё", "е")
    if "самосвал" in text or "тонар" in text or "dump" in text:
        return "dump_truck"
    if "экскават" in text or "excavat" in text:
        return "excavator"
    if "бульдоз" in text or "bulldoz" in text:
        return "bulldozer"
    return None


def _general_equipment_class_from_row(row: object) -> Optional[str]:
    """Classify equipment using type first, then fallback descriptor fields.

    Some imports store descriptors like ``242/340м3/экскаватор/ЖДС`` in
    ``unit_number`` while ``equipment_type`` is the generic word ``номер``.
    The general report should not drop such historical rows; if the explicit
    type is unrecognized, scan the report/master descriptor fields as fallback.
    """
    if not isinstance(row, dict):
        return _general_equipment_class(str(row or ""))
    explicit = _general_equipment_class(row.get("equipment_type"))
    if explicit:
        return explicit
    for key in ("unit_number", "plate_number", "brand_model", "equipment_name", "label"):
        eq = _general_equipment_class(row.get(key))
        if eq:
            return eq
    descriptor = " / ".join(
        str(row.get(key) or "")
        for key in ("equipment_type", "unit_number", "plate_number", "brand_model", "equipment_name", "label")
    )
    return _general_equipment_class(descriptor)


def _new_equipment_fact_slot() -> dict[str, dict[str, float]]:
    return {
        "total": _section_values(),
        "day": _section_values(),
        "night": _section_values(),
        "hired": _section_values(),
        "non_hired": _section_values(),
        "almaz": _section_values(),
        "day_non_hired": _section_values(),
        "day_almaz": _section_values(),
        "day_hired": _section_values(),
        "night_non_hired": _section_values(),
        "night_almaz": _section_values(),
        "night_hired": _section_values(),
    }


def _equipment_is_jds(ownership_type: Optional[str], contractor_name: Optional[str]) -> bool:
    ownership = (ownership_type or "").strip().lower()
    contractor = (contractor_name or "").strip().lower().replace("ё", "е")
    contractor = re.sub(r"[\"'«»“”„]+", "", contractor)
    contractor = re.sub(r"\s+", " ", contractor).strip()
    return (
        ownership == "own"
        or "собствен" in contractor
        or bool(re.search(r"(?:^|\b)(?:ооо\s+)?ждс(?:\b|$)", contractor))
    )


def _equipment_is_hired(ownership_type: Optional[str], contractor_name: Optional[str]) -> bool:
    if _equipment_is_jds(ownership_type, contractor_name):
        return False
    return (ownership_type or "").strip().lower() == "hired" or bool((contractor_name or "").strip())


def _equipment_source_bucket(ownership_type: Optional[str], contractor_name: Optional[str]) -> str:
    contractor = (contractor_name or "").strip().lower().replace("ё", "е")
    if "алмаз" in contractor:
        return "almaz"
    if _equipment_is_hired(ownership_type, contractor_name):
        return "hired"
    return "non_hired"


def _general_rule_source_buckets(rule: Optional[dict]) -> list[str]:
    filters = _general_row_filters((rule or {}).get("filters"))
    return [value for value in _general_clean_string_list(filters.get("source_buckets"), limit=8) if value in GENERAL_REPORT_SOURCE_BUCKET_LABELS]


def _general_rule_matches_work_filters(
    rule: Optional[dict],
    tag: Optional[str],
    object_type_code: Optional[str],
    object_code: Optional[str],
) -> bool:
    if rule is not None and not rule.get("enabled", True):
        return False
    filters = _general_row_filters((rule or {}).get("filters"))
    tags = {_general_normalize_text(value) for value in _general_clean_string_list(filters.get("tags"))}
    if tags and _general_normalize_text(tag) not in tags:
        return False
    type_codes = {str(value or "").strip() for value in _general_clean_string_list(filters.get("object_type_codes"))}
    object_codes = {str(value or "").strip() for value in _general_clean_string_list(filters.get("object_codes"))}
    obj_type = str(object_type_code or "").strip()
    obj_code = str(object_code or "").strip()
    if (type_codes or object_codes) and obj_type not in type_codes and obj_code not in object_codes:
        return False
    return True


def _general_equipment_slot_values(slot: dict[str, dict[str, float]], bucket: str, rule: Optional[dict]) -> dict[str, float]:
    if rule is not None and not rule.get("enabled", True):
        return _section_values()
    source_buckets = _general_rule_source_buckets(rule)
    if not source_buckets:
        return (slot or {}).get(bucket) or _section_values()
    values = _section_values()
    for source_bucket in source_buckets:
        source_key = source_bucket if bucket in {"total", "hired"} else f"{bucket}_{source_bucket}"
        values = _sum_section_values(values, (slot or {}).get(source_key) or _section_values())
    return values


def _general_equipment_work_unit_key(row: dict) -> str:
    for key in ("unit_key", "equipment_unit_id", "plate_number", "unit_number", "report_equipment_unit_id", "reu_id", "id"):
        value = row.get(key)
        text = re.sub(r"\s+", "", str(value or "").strip().lower())
        if text:
            return f"{key}:{text}"
    return f"row:{id(row)}"


def _general_equipment_work_count_slots_from_rows(rows: list[dict], rules: Optional[list[dict]] = None) -> dict[str, dict[str, dict[str, dict[str, float]]]]:
    rules = rules if rules is not None else _general_report_work_rules()
    result: dict[str, dict[str, dict[str, dict[str, float]]]] = {}
    seen: dict[tuple[str, str, str, Optional[str]], set[str]] = {}

    def add_once(slot: dict[str, dict[str, float]], bucket: str, section: Optional[str], unit_key: str) -> None:
        dedup_key = (bucket, unit_key, section, None)
        bucket_seen = seen.setdefault(dedup_key, set())
        # Keep per-result bucket membership separate by object identity so the
        # same unit can count once in each equipment/category bucket, while
        # duplicate report rows or day+night total rows do not inflate counts.
        marker = str(id(slot))
        if marker in bucket_seen:
            return
        bucket_seen.add(marker)
        _add_section_value(slot[bucket], section, 1.0)

    for row in rows:
        eq = _general_equipment_class_from_row(row)
        if not eq:
            continue
        source_bucket = _equipment_source_bucket(row.get("ownership_type"), row.get("contractor_name"))
        material = _general_material_bucket(row.get("material_code"), row.get("material_name"))
        category = str(row.get("category") or "").strip()
        if not category:
            category = _general_material_movement_equipment_category(
                material,
                row.get("movement_type"),
                row.get("from_object_type_code"),
                row.get("to_object_type_code"),
            ) or ""
        if not category:
            category = _general_equipment_work_category(
                rules,
                row.get("analytics_tag"),
                row.get("wt_code"),
                row.get("object_type_code"),
                row.get("object_code"),
                source_bucket,
            ) or ""
        if not category:
            continue
        slot = result.setdefault(eq, {}).setdefault(category, _new_equipment_fact_slot())
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        unit_key = _general_equipment_work_unit_key(row)
        add_once(slot, shift, section, unit_key)
        add_once(slot, f"{shift}_{source_bucket}", section, unit_key)
        add_once(slot, "total", section, unit_key)
        add_once(slot, source_bucket, section, unit_key)
        if source_bucket == "hired":
            add_once(slot, "hired", section, unit_key)
    return result


def _general_equipment_plan_counts_for_category(
    equipment_work_counts: dict[str, dict[str, dict[str, dict[str, float]]]],
    equipment_code: str,
    category: str,
    bucket: str,
    rule: Optional[dict],
) -> dict[str, float]:
    slot = _equipment_category_slot(equipment_work_counts.get(equipment_code) or {}, category)
    return _general_equipment_slot_values(slot, bucket, rule)


def _general_external_equipment_slot_values(slot: dict[str, dict[str, float]], bucket: str = "total") -> dict[str, float]:
    """Values for non-ЖДС equipment/material rows: АЛМАЗ + наём.

    This intentionally ignores the equipment-day rule source filter. In the
    ready Генеральный отчет template the regular dump-truck rows are configured
    as ЖДС/non_hired, while the explicit "НАЕМ+АЛМАЗ" row must always show the
    external part of the same material-transport fact.
    """
    values = _section_values()
    for source_bucket in ("almaz", "hired"):
        source_key = source_bucket if bucket == "total" else f"{bucket}_{source_bucket}"
        values = _sum_section_values(values, (slot or {}).get(source_key) or _section_values())
    return values


def _query_general_dump_truck_non_hired_unit_keys_by_shift(
    date_from: date_cls,
    date_to: date_cls,
    codes: Optional[list[str]],
) -> dict[tuple[str, date_cls, str], set[str]]:
    """Working dump-truck unit keys with the same source semantics as Генеральный.

    Returns unique unit keys per (section, report_date, shift), keeping only
    non-hired / ЖДС dump trucks from section shift reports and excluding
    mechanization snapshots.
    """
    eq_where = [
        "dr.report_date BETWEEN %s AND %s",
        "COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')",
        _general_shift_report_condition("dr"),
        "COALESCE(reu.is_demo, false) IS FALSE",
        "reu.status = 'working'",
        "(LOWER(CONCAT_WS(' ', reu.equipment_type, eu.equipment_type, reu.unit_number, eu.unit_number, reu.plate_number, eu.plate_number, reu.brand_model, eu.brand_model)) LIKE ANY(ARRAY['%%самосвал%%', '%%тонар%%', '%%dump%%']))",
    ]
    eq_params: list = [date_from, date_to]
    if codes:
        eq_where.append("cs.code = ANY(%s)")
        eq_params.append(codes)
    eq_rows = query(
        f"""
        SELECT cs.code AS section_code,
               dr.report_date AS report_date,
               LOWER(COALESCE(dr.shift, 'day')) AS shift,
               COALESCE(reu.equipment_type, eu.equipment_type) AS equipment_type,
               eu.equipment_type AS equipment_name,
               COALESCE(reu.brand_model, eu.brand_model, '') AS brand_model,
               COALESCE(reu.plate_number, eu.plate_number, '') AS plate_number,
               COALESCE(reu.unit_number, eu.unit_number, '') AS unit_number,
               COALESCE(NULLIF(reu.ownership_type, ''), eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '') AS contractor_name,
               COALESCE(
                   reu.equipment_unit_id::text,
                   NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number)), ''),
                   NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number)), ''),
                   reu.id::text
               ) AS unit_key
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        LEFT JOIN contractors c ON c.id = reu.contractor_id
        WHERE {' AND '.join(eq_where)}
        """,
        eq_params,
    )
    units_by_shift: dict[tuple[str, date_cls, str], set[str]] = {}
    for row in eq_rows:
        if _general_equipment_class_from_row(row) != "dump_truck":
            continue
        if _equipment_source_bucket(row.get("ownership_type"), row.get("contractor_name")) != "non_hired":
            continue
        section = _merge_section(row.get("section_code")) or "—"
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        unit_key = _general_equipment_work_unit_key(row)
        units_by_shift.setdefault((section, row.get("report_date"), shift), set()).add(unit_key)
    return units_by_shift


def _general_unique_unit_total_from_shift_map(units_by_shift: Optional[dict[tuple[str, date_cls, str], set[str]]]) -> float:
    unique_keys: set[str] = set()
    for keys in (units_by_shift or {}).values():
        unique_keys.update(str(key) for key in (keys or set()) if str(key or "").strip())
    return float(len(unique_keys))


def _query_general_dump_truck_non_hired_unique_daily_total(
    report_date: date_cls,
    codes: Optional[list[str]],
) -> float:
    return _general_unique_unit_total_from_shift_map(
        _query_general_dump_truck_non_hired_unit_keys_by_shift(report_date, report_date, codes)
    )


def _query_general_dump_truck_sand_productivity_plan_counts(
    report_date: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, float]]:
    """Dump-truck SAND plan counts using transport-report semantics.

    The transport report counts machines linked to material movement rows and
    deduplicates the same machine once per section/date for the total plan.  The
    General report must use the same denominator so machine counts and planned
    output do not diverge between the two XLSX pipelines.
    """
    slot = _new_equipment_fact_slot()
    movement_where = [
        "mm.report_date = %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _general_shift_report_exists("mm"),
        "m.code = 'SAND'",
        "COALESCE(mm.labor_source_type, 'own') = 'own'",
        "mm.movement_type IN ('pit_to_constructive', 'pit_to_stockpile', 'stockpile_to_constructive', 'stockpile_to_stockpile')",
    ]
    movement_params: list = [report_date]
    if codes:
        movement_where.append("cs.code = ANY(%s)")
        movement_params.append(codes)
    movement_rows = query(
        f"""
        SELECT cs.code AS section_code,
               mm.report_date AS report_date,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               mm.movement_type AS movement_type,
               COALESCE(reu.equipment_type, mm.equipment_type, 'самосвал') AS equipment_type,
               reu.equipment_unit_id::text AS equipment_unit_id,
               reu.id::text AS report_equipment_unit_id,
               reu.id::text AS reu_id,
               COALESCE(reu.brand_model, '') AS brand_model,
               COALESCE(reu.plate_number, '') AS plate_number,
               COALESCE(reu.unit_number, '') AS unit_number,
               COALESCE(mm.labor_source_type, reu.ownership_type, 'own') AS ownership_type,
               COALESCE(mm.contractor_name, reu.contractor_name, '') AS contractor_name,
               COALESCE(
                   reu.equipment_unit_id::text,
                   NULLIF(BTRIM(reu.plate_number), ''),
                   NULLIF(BTRIM(reu.unit_number), ''),
                   reu.id::text
               ) AS unit_key
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        JOIN material_movement_equipment_usage mmeu ON mmeu.material_movement_id = mm.id
        JOIN report_equipment_units reu ON reu.id = mmeu.report_equipment_unit_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        WHERE {' AND '.join(movement_where)}
        """,
        movement_params,
    )
    seen: dict[tuple[str, str], set[str]] = {}

    def add_once(bucket: str, section: Optional[str], unit_key: str) -> None:
        merged_section = _merge_section(section) or "—"
        if merged_section not in GENERAL_ANALYTICS_SECTION_CODES:
            return
        marker = (bucket, merged_section)
        bucket_seen = seen.setdefault(marker, set())
        if unit_key in bucket_seen:
            return
        bucket_seen.add(unit_key)
        _add_section_value(slot[bucket], merged_section, 1.0)

    for row in movement_rows:
        section = _merge_section(row.get("section_code")) or "—"
        section_num = _sec_code_to_num(section)
        if section_num is None:
            continue
        spec = DUMP_TRUCK_NORMS.get((section_num, "SAND"))
        if not spec:
            continue
        movement_type = str(row.get("movement_type") or "").strip()
        if movement_type == "pit_to_stockpile" and not bool(spec.get("include_pit_to_stockpile", True)):
            continue
        unit_key = _general_equipment_work_unit_key(row)
        if not unit_key:
            continue
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        add_once(shift, section, unit_key)
        add_once(f"{shift}_non_hired", section, unit_key)
        add_once("total", section, unit_key)
        add_once("non_hired", section, unit_key)
    return slot


def _query_general_equipment_counts(
    report_date: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, float]]]:
    where = [
        "dr.report_date = %s",
        "COALESCE(reu.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        "reu.status = 'working'",
        _general_shift_report_exists("reu"),
    ]
    params: list = [report_date]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               dr.shift,
               COALESCE(reu.equipment_type, eu.equipment_type) AS equipment_type,
               eu.equipment_type AS equipment_name,
               COALESCE(reu.brand_model, eu.brand_model, '') AS brand_model,
               COALESCE(reu.plate_number, eu.plate_number, '') AS plate_number,
               COALESCE(reu.unit_number, eu.unit_number, '') AS unit_number,
               COALESCE(NULLIF(reu.ownership_type, ''), eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '') AS contractor_name,
               COALESCE(
                   reu.equipment_unit_id::text,
                   NULLIF(BTRIM(COALESCE(reu.plate_number, eu.plate_number)), ''),
                   NULLIF(BTRIM(COALESCE(reu.unit_number, eu.unit_number)), ''),
                   reu.id::text
               ) AS unit_key
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        LEFT JOIN contractors c ON c.id = reu.contractor_id
        WHERE {' AND '.join(where)}
        """,
        params,
    )
    result: dict[str, dict[str, dict[str, float]]] = {}
    seen: dict[tuple[int, str, str], set[str]] = {}

    def add_once(slot: dict[str, dict[str, float]], bucket: str, section: Optional[str], unit_key: str) -> None:
        marker = (id(slot), bucket, section or "—")
        bucket_seen = seen.setdefault(marker, set())
        if unit_key in bucket_seen:
            return
        bucket_seen.add(unit_key)
        _add_section_value(slot[bucket], section, 1.0)

    for row in rows:
        eq = _general_equipment_class_from_row(row)
        if not eq:
            continue
        slot = result.setdefault(eq, _new_equipment_fact_slot())
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        source_bucket = _equipment_source_bucket(row.get("ownership_type"), row.get("contractor_name"))
        unit_key = _general_equipment_work_unit_key(row)
        add_once(slot, source_bucket, section, unit_key)
        add_once(slot, f"{shift}_{source_bucket}", section, unit_key)
        if source_bucket == "non_hired":
            add_once(slot, "total", section, unit_key)
            add_once(slot, shift, section, unit_key)
    return result



def _query_general_equipment_work_facts(
    report_date: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, dict[str, float]]]]:
    where = [
        "dwi.report_date = %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(reu.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
    ]
    params: list = [report_date]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs_eff.code AS section_code,
               dwi.shift,
               reu.equipment_type,
               reu.brand_model,
               reu.plate_number,
               reu.unit_number,
               reu.ownership_type,
               reu.contractor_name,
               wt.code AS wt_code,
               ot.code AS object_type_code,
               obj.object_code AS object_code,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               SUM(
                 CASE
                   WHEN seg.id IS NULL THEN COALESCE(wieu.worked_volume, dwi.volume, 0)
                   WHEN wieu.worked_volume IS NOT NULL AND COALESCE(dwi.volume, 0) <> 0 AND seg.volume_segment IS NOT NULL THEN wieu.worked_volume * seg.volume_segment / dwi.volume
                   WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                   WHEN seg_count.cnt > 0 THEN COALESCE(wieu.worked_volume, dwi.volume, 0) / seg_count.cnt
                   ELSE COALESCE(wieu.worked_volume, dwi.volume, 0)
                 END
               )::numeric AS amount
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND seg.id IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        GROUP BY cs_eff.code, dwi.shift, reu.equipment_type, reu.brand_model, reu.plate_number, reu.unit_number, reu.ownership_type, reu.contractor_name, wt.code, ot.code, obj.object_code, 12
        """,
        params,
    )
    rules = _general_report_work_rules()
    result: dict[str, dict[str, dict[str, dict[str, float]]]] = {}
    equipment_rules = {code: _general_equipment_rule_for_class(code) for code in GENERAL_REPORT_EQUIPMENT_CLASS_CODES}
    for row in rows:
        eq = _general_equipment_class_from_row(row)
        if not eq:
            continue
        equipment_rule = equipment_rules.get(eq)
        if eq in {"excavator", "bulldozer"} and not _general_rule_matches_work_filters(
            equipment_rule,
            row.get("analytics_tag"),
            row.get("object_type_code"),
            row.get("object_code"),
        ):
            continue
        source_bucket = _equipment_source_bucket(row.get("ownership_type"), row.get("contractor_name"))
        category = _general_equipment_work_category(
            rules,
            row.get("analytics_tag"),
            row.get("wt_code"),
            row.get("object_type_code"),
            row.get("object_code"),
            source_bucket,
        )
        if not category:
            continue
        slot = result.setdefault(eq, {}).setdefault(category, _new_equipment_fact_slot())
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        _add_section_value(slot["total"], section, amount)
        _add_section_value(slot[shift], section, amount)
        _add_section_value(slot[source_bucket], section, amount)
        _add_section_value(slot[f"{shift}_{source_bucket}"], section, amount)
        if source_bucket == "hired":
            _add_section_value(slot["hired"], section, amount)

    movement_where = [
        "mm.report_date = %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("mm"),
        "mm.movement_type IN ('pit_to_constructive', 'stockpile_to_constructive', 'pit_to_stockpile', 'stockpile_to_stockpile', 'constructive_to_stockpile', 'constructive_to_constructive')",
    ]
    movement_params: list = [report_date]
    if codes:
        movement_where.append("cs.code = ANY(%s)")
        movement_params.append(codes)
    movement_rows = query(
        f"""
        SELECT cs.code AS section_code,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               COALESCE(reu.equipment_type, mm.equipment_type, 'самосвал') AS equipment_type,
               reu.brand_model,
               reu.plate_number,
               reu.unit_number,
               COALESCE(mm.labor_source_type, reu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(mm.contractor_name, reu.contractor_name, '') AS contractor_name,
               m.code AS material_code,
               m.name AS material_name,
               mm.movement_type,
               src_ot.code AS from_object_type_code,
               dst_ot.code AS to_object_type_code,
               SUM(COALESCE(mmeu.worked_volume, mm.volume))::numeric AS amount
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN material_movement_equipment_usage mmeu ON mmeu.material_movement_id = mm.id
        LEFT JOIN report_equipment_units reu ON reu.id = mmeu.report_equipment_unit_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        LEFT JOIN objects src_obj ON src_obj.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src_obj.object_type_id
        LEFT JOIN objects dst_obj ON dst_obj.id = mm.to_object_id
        LEFT JOIN object_types dst_ot ON dst_ot.id = dst_obj.object_type_id
        WHERE {' AND '.join(movement_where)}
        GROUP BY cs.code, mm.shift, 3, 4, 5, 6, 7, 8, m.code, m.name, mm.movement_type, src_ot.code, dst_ot.code
        """,
        movement_params,
    )
    for row in movement_rows:
        eq = _general_equipment_class_from_row(row)
        material = _general_material_bucket(row.get("material_code"), row.get("material_name"))
        category = _general_material_movement_equipment_category(
            material,
            row.get("movement_type"),
            row.get("from_object_type_code"),
            row.get("to_object_type_code"),
        )
        if not eq or not category:
            continue
        slot = result.setdefault(eq, {}).setdefault(category, _new_equipment_fact_slot())
        amount = float(row.get("amount") or 0)
        section = row.get("section_code")
        shift = "night" if (row.get("shift") or "").lower() == "night" else "day"
        source_bucket = _equipment_source_bucket(row.get("ownership_type"), row.get("contractor_name"))
        _add_section_value(slot["total"], section, amount)
        _add_section_value(slot[shift], section, amount)
        _add_section_value(slot[source_bucket], section, amount)
        _add_section_value(slot[f"{shift}_{source_bucket}"], section, amount)
        if source_bucket == "hired":
            _add_section_value(slot["hired"], section, amount)
    return result


def _query_general_equipment_work_counts(
    report_date: date_cls,
    codes: Optional[list[str]],
) -> dict[str, dict[str, dict[str, dict[str, float]]]]:
    where = [
        "dwi.report_date = %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(reu.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
    ]
    params: list = [report_date]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)
    work_rows = query(
        f"""
        SELECT cs_eff.code AS section_code,
               dwi.shift,
               reu.equipment_type,
               reu.brand_model,
               reu.plate_number,
               reu.unit_number,
               reu.ownership_type,
               reu.contractor_name,
               wt.code AS wt_code,
               ot.code AS object_type_code,
               obj.object_code AS object_code,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               COALESCE(
                   reu.equipment_unit_id::text,
                   NULLIF(BTRIM(reu.plate_number), ''),
                   NULLIF(BTRIM(reu.unit_number), ''),
                   reu.id::text
               ) AS unit_key
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN report_equipment_units reu ON reu.id = wieu.report_equipment_unit_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND seg.id IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        """,
        params,
    )

    movement_where = [
        "mm.report_date = %s",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("mm"),
        "mm.movement_type IN ('pit_to_constructive', 'stockpile_to_constructive', 'pit_to_stockpile', 'stockpile_to_stockpile', 'constructive_to_stockpile', 'constructive_to_constructive')",
    ]
    movement_params: list = [report_date]
    if codes:
        movement_where.append("cs.code = ANY(%s)")
        movement_params.append(codes)
    movement_rows = query(
        f"""
        SELECT cs.code AS section_code,
               LOWER(COALESCE(mm.shift, 'day')) AS shift,
               COALESCE(reu.equipment_type, mm.equipment_type, 'самосвал') AS equipment_type,
               reu.brand_model,
               reu.plate_number,
               reu.unit_number,
               COALESCE(mm.labor_source_type, reu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(mm.contractor_name, reu.contractor_name, '') AS contractor_name,
               m.code AS material_code,
               m.name AS material_name,
               mm.movement_type,
               src_ot.code AS from_object_type_code,
               dst_ot.code AS to_object_type_code,
               COALESCE(
                   reu.equipment_unit_id::text,
                   NULLIF(BTRIM(reu.plate_number), ''),
                   NULLIF(BTRIM(reu.unit_number), ''),
                   reu.id::text
               ) AS unit_key
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        JOIN material_movement_equipment_usage mmeu ON mmeu.material_movement_id = mm.id
        JOIN report_equipment_units reu ON reu.id = mmeu.report_equipment_unit_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
        LEFT JOIN objects src_obj ON src_obj.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src_obj.object_type_id
        LEFT JOIN objects dst_obj ON dst_obj.id = mm.to_object_id
        LEFT JOIN object_types dst_ot ON dst_ot.id = dst_obj.object_type_id
        WHERE {' AND '.join(movement_where)}
        """,
        movement_params,
    )
    return _general_equipment_work_count_slots_from_rows([*work_rows, *movement_rows], _general_report_work_rules())


def _pile_length_from_type(pile_type: Optional[str]) -> Optional[int]:
    text = str(pile_type or "").upper().replace("C", "С")
    if ";" in text:
        return None
    direct = re.fullmatch(r"\s*(\d{1,2})\s*", text)
    if direct:
        return int(direct.group(1))
    matches = [int(m) for m in re.findall(r"С(\d{2,3})", text)]
    if not matches:
        return None
    return int(round(sum(matches) / 10))


def _statement_pile_length_from_sources(pile_type: Optional[str], pipe_pile_length_m=None) -> Optional[int]:
    field_length = _pile_length_from_type(pile_type)
    if field_length is not None:
        return field_length
    return _pile_length_from_type(pipe_pile_length_m)


def _new_pile_slot() -> dict[str, dict[str, float]]:
    return {
        "main": _section_values(),
        "test": _section_values(),
        "dyn": _section_values(),
        "headcaps": _section_values(),
    }


def _query_general_project_pile_plans(codes: Optional[list[str]]) -> dict[str, dict]:
    plans = _new_pile_slot()
    length_plans: dict[str, dict[int, dict[str, float]]] = {"main": {}, "test": {}}
    length_unknown_plans: dict[str, dict[str, float]] = {"main": _section_values(), "test": _section_values()}
    where = ["COALESCE(pf.is_demo, false) IS FALSE"]
    params: list = []
    if codes:
        where.append("sec.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT sec.code AS section_code,
               pf.field_type,
               pf.pile_type,
               SUM(COALESCE(pf.pile_count, 0))::numeric AS pile_cnt,
               SUM(COALESCE(pf.dynamic_test_count, 0))::numeric AS dyn_cnt
        FROM pile_fields pf
        LEFT JOIN LATERAL (
          SELECT cs.code
          FROM construction_section_versions csv
          JOIN construction_sections cs ON cs.id = csv.section_id
          WHERE csv.is_current = true
            AND csv.boundary_kind = 'piles_pipes'
            AND pf.pk_start < csv.pk_end
            AND pf.pk_end > csv.pk_start
          ORDER BY GREATEST(0, LEAST(pf.pk_end, csv.pk_end) - GREATEST(pf.pk_start, csv.pk_start)) DESC,
                   csv.pk_start
          LIMIT 1
        ) sec ON true
        WHERE {' AND '.join(where)}
        GROUP BY sec.code, pf.field_type, pf.pile_type
        """,
        params,
    )
    for row in rows:
        section = row.get("section_code")
        kind = "test" if row.get("field_type") == "test" else "main"
        amount = float(row.get("pile_cnt") or 0)
        _add_section_value(plans[kind], section, amount)
        _add_section_value(plans["dyn"], section, float(row.get("dyn_cnt") or 0))
        length = _pile_length_from_type(row.get("pile_type"))
        if length:
            slot = length_plans[kind].setdefault(length, _section_values())
            _add_section_value(slot, section, amount)
        elif amount > 0:
            _add_section_value(length_unknown_plans[kind], section, amount)
    return {"plans": plans, "length_plans": length_plans, "length_unknown_plans": length_unknown_plans}


def _query_general_pile_data(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
    plan_from: Optional[date_cls] = None,
    plan_to: Optional[date_cls] = None,
) -> dict:
    facts = _new_pile_slot()
    plans = _new_pile_slot()
    plan_d_from = plan_from or d_from
    plan_d_to = plan_to or d_to
    length_facts: dict[str, dict[int, dict[str, float]]] = {"main": {}, "test": {}}
    length_plans: dict[str, dict[int, dict[str, float]]] = {"main": {}, "test": {}}
    length_unknown_facts: dict[str, dict[str, float]] = {"main": _section_values(), "test": _section_values()}
    length_unknown_plans: dict[str, dict[str, float]] = {"main": _section_values(), "test": _section_values()}

    fact_where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
        "wt.code IN ('PILE_MAIN', 'PILE_TRIAL', 'PILE_DYNTEST', 'PILE_HEADCAP_INSTALLATION')",
    ]
    fact_params: list = [d_from, d_to]
    if codes:
        fact_where.append("cs_eff_general_pile.code = ANY(%s)")
        fact_params.append(codes)
    fact_rows = query(
        f"""
        SELECT cs_eff_general_pile.code AS section_code, wt.code AS wt_code, SUM({_pile_effective_volume_expr('seg_general_pile')})::numeric AS cnt
        FROM daily_work_items dwi
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        {_pile_effective_section_join('seg_general_pile', 'cs_eff_general_pile', 'cs_report_general_pile')}
        WHERE {' AND '.join(fact_where)}
        GROUP BY cs_eff_general_pile.code, wt.code
        """,
        fact_params,
    )
    wt_to_key = {
        "PILE_MAIN": "main",
        "PILE_TRIAL": "test",
        "PILE_DYNTEST": "dyn",
        "PILE_HEADCAP_INSTALLATION": "headcaps",
    }
    for row in fact_rows:
        key = wt_to_key.get(row.get("wt_code"))
        if key:
            _add_section_value(facts[key], row.get("section_code"), float(row.get("cnt") or 0))

    use_project_plan = plan_d_from <= PROJECT_START_DATE
    if use_project_plan:
        project_plan = _query_general_project_pile_plans(codes)
        plans = project_plan["plans"]
        length_plans = project_plan["length_plans"]
        length_unknown_plans = project_plan["length_unknown_plans"]
    else:
        plan_where = ["ppp.period_start <= %s", "ppp.period_end >= %s"]
        plan_params: list = [plan_d_to, plan_d_from]
        if codes:
            plan_where.append("cs.code = ANY(%s)")
            plan_params.append(codes)
        plan_rows = query(
            f"""
            SELECT cs.code AS section_code,
                   SUM(COALESCE(ppp.planned_main_piles, 0))::numeric AS main_cnt,
                   SUM(COALESCE(ppp.planned_test_piles, 0))::numeric AS test_cnt,
                   SUM(COALESCE(ppp.planned_dynamic_tests, 0))::numeric AS dyn_cnt,
                   SUM(COALESCE(ppp.planned_headcaps, 0))::numeric AS headcap_cnt
            FROM pile_plan_periods ppp
            JOIN construction_sections cs ON cs.id = ppp.section_id
            WHERE {' AND '.join(plan_where)}
            GROUP BY cs.code
            """,
            plan_params,
        )
        for row in plan_rows:
            _add_section_value(plans["main"], row.get("section_code"), float(row.get("main_cnt") or 0))
            _add_section_value(plans["test"], row.get("section_code"), float(row.get("test_cnt") or 0))
            _add_section_value(plans["dyn"], row.get("section_code"), float(row.get("dyn_cnt") or 0))
            _add_section_value(plans["headcaps"], row.get("section_code"), float(row.get("headcap_cnt") or 0))

    length_where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(ds.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
        "wt.code IN ('PILE_MAIN', 'PILE_TRIAL')",
    ]
    length_params: list = [d_from, d_to]
    if codes:
        length_where.append("cs_eff_length.code = ANY(%s)")
        length_params.append(codes)
    length_rows = query(
        f"""
        SELECT cs_eff_length.code AS section_code,
               wt.code AS wt_code,
               pf.pile_type,
               SUM(
                 CASE
                   WHEN ds.volume_segment IS NOT NULL THEN COALESCE(ds.volume_segment, 0)
                   WHEN seg_length_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_length_count.cnt
                   ELSE COALESCE(dwi.volume, 0)
                 END
               )::numeric AS cnt
        FROM daily_work_item_segments ds
        JOIN daily_work_items dwi ON dwi.id = ds.daily_work_item_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        LEFT JOIN pile_fields pf ON pf.id = ds.pile_field_id
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_length_count ON true
        LEFT JOIN construction_sections cs_report_length ON cs_report_length.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = 'piles_pipes'
            AND COALESCE(
              (COALESCE(ds.pk_start, pf.pk_start) + COALESCE(ds.pk_end, pf.pk_end)) / 2.0,
              COALESCE(ds.pk_start, pf.pk_start),
              COALESCE(ds.pk_end, pf.pk_end)
            ) >= LEAST(csv.pk_start, csv.pk_end)
            AND COALESCE(
              (COALESCE(ds.pk_start, pf.pk_start) + COALESCE(ds.pk_end, pf.pk_end)) / 2.0,
              COALESCE(ds.pk_start, pf.pk_start),
              COALESCE(ds.pk_end, pf.pk_end)
            ) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_length_section ON true
        LEFT JOIN construction_sections cs_eff_length
          ON cs_eff_length.id = COALESCE(effective_length_section.section_id, cs_report_length.id)
         AND cs_eff_length.is_active IS NOT FALSE
        WHERE {' AND '.join(length_where)}
        GROUP BY cs_eff_length.code, wt.code, pf.pile_type
        """,
        length_params,
    )
    for row in length_rows:
        kind = "main" if row.get("wt_code") == "PILE_MAIN" else "test"
        length = _pile_length_from_type(row.get("pile_type"))
        amount = float(row.get("cnt") or 0)
        if not length:
            if amount > 0:
                _add_section_value(length_unknown_facts[kind], row.get("section_code"), amount)
            continue
        slot = length_facts[kind].setdefault(length, _section_values())
        _add_section_value(slot, row.get("section_code"), amount)

    # Pipe/PBЖT pile facts are object-linked (daily_work_items.object_id) and
    # their approved length nomenclature lives in pipe_pile_specs, not in
    # daily_work_item_segments.pile_field_id -> pile_fields.pile_type.  Without
    # this second pass the headline pile totals include pipes, but the rows
    # "факт N м" miss them (e.g. ПК2656/ПК2685).
    pipe_length_where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
        "wt.code IN ('PILE_MAIN', 'PILE_TRIAL')",
        "specs.pile_length_m IS NOT NULL",
    ]
    pipe_length_params: list = [d_from, d_to]
    if codes:
        pipe_length_where.append("cs.code = ANY(%s)")
        pipe_length_params.append(codes)
    pipe_length_rows = query(
        f"""
        WITH specs AS (
            SELECT pps.object_id,
                   pps.work_type_id,
                   pps.pile_length_m,
                   COALESCE(pps.quantity, 0)::numeric AS quantity,
                   SUM(COALESCE(pps.quantity, 0)) OVER (PARTITION BY pps.object_id, pps.work_type_id) AS total_quantity
            FROM pipe_pile_specs pps
            WHERE COALESCE(pps.is_active, true) IS TRUE
        )
        SELECT cs.code AS section_code,
               wt.code AS wt_code,
               specs.pile_length_m,
               SUM(
                   dwi.volume * CASE
                       WHEN specs.total_quantity > 0 THEN specs.quantity / specs.total_quantity
                       ELSE 1
                   END
               )::numeric AS cnt
        FROM daily_work_items dwi
        JOIN work_types wt ON wt.id = dwi.work_type_id
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN specs ON specs.object_id = dwi.object_id AND specs.work_type_id = dwi.work_type_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr.section_id)
        WHERE {' AND '.join(pipe_length_where)}
        GROUP BY cs.code, wt.code, specs.pile_length_m
        """,
        pipe_length_params,
    )
    for row in pipe_length_rows:
        kind = "main" if row.get("wt_code") == "PILE_MAIN" else "test"
        length = _pile_length_from_type(row.get("pile_length_m"))
        amount = float(row.get("cnt") or 0)
        if not length:
            if amount > 0:
                _add_section_value(length_unknown_facts[kind], row.get("section_code"), amount)
            continue
        slot = length_facts[kind].setdefault(length, _section_values())
        _add_section_value(slot, row.get("section_code"), amount)

    if not use_project_plan:
        length_plan_rows = query(
            f"""
            SELECT cs.code AS section_code,
                   pf.field_type,
                   pf.pile_type,
                   SUM(CASE WHEN pf.field_type = 'test' THEN COALESCE(ppp.planned_test_piles, 0) ELSE COALESCE(ppp.planned_main_piles, 0) END)::numeric AS cnt
            FROM pile_plan_periods ppp
            JOIN construction_sections cs ON cs.id = ppp.section_id
            JOIN pile_fields pf ON pf.id = ppp.pile_field_id
            WHERE {' AND '.join(plan_where)}
            GROUP BY cs.code, pf.field_type, pf.pile_type
            """,
            plan_params,
        )
        for row in length_plan_rows:
            kind = "test" if row.get("field_type") == "test" else "main"
            length = _pile_length_from_type(row.get("pile_type"))
            amount = float(row.get("cnt") or 0)
            if not length:
                if amount > 0:
                    _add_section_value(length_unknown_plans[kind], row.get("section_code"), amount)
                continue
            slot = length_plans[kind].setdefault(length, _section_values())
            _add_section_value(slot, row.get("section_code"), amount)

    return {
        "facts": facts,
        "plans": plans,
        "length_facts": length_facts,
        "length_plans": length_plans,
        "length_unknown_facts": length_unknown_facts,
        "length_unknown_plans": length_unknown_plans,
    }


def _category_bucket(
    facts: dict[str, dict[str, dict[str, float]]],
    category: str,
    bucket: str = "total",
) -> dict[str, float]:
    return ((facts.get(category) or {}).get(bucket) or _section_values())


def _sum_category_buckets(
    facts: dict[str, dict[str, dict[str, float]]],
    categories: tuple[str, ...] | list[str],
    bucket: str = "total",
) -> dict[str, float]:
    values = _section_values()
    for category in categories:
        values = _sum_section_values(values, _category_bucket(facts, category, bucket))
    return values


def _external_category_bucket(
    facts: dict[str, dict[str, dict[str, float]]],
    category: str,
) -> dict[str, float]:
    return _sum_section_values(_category_bucket(facts, category, "almaz"), _category_bucket(facts, category, "hired"))


def _sum_equipment_fact_slots(
    eq_facts: dict[str, dict[str, dict[str, float]]],
    categories: tuple[str, ...] | list[str],
) -> dict[str, dict[str, float]]:
    slot = _new_equipment_fact_slot()
    for category in categories:
        source = eq_facts.get(category) or {}
        for bucket in slot:
            slot[bucket] = _sum_section_values(slot[bucket], source.get(bucket) or _section_values())
    return slot


def _equipment_category_slot(eq_facts: dict[str, dict[str, dict[str, float]]], category: str) -> dict[str, dict[str, float]]:
    if category == "SAND":
        return _sum_equipment_fact_slots(eq_facts, ("SAND", "SAND_VAD", "SAND_OH"))
    if category == "VYEMKA":
        return _sum_equipment_fact_slots(eq_facts, ("VYEMKA", "VYEMKA_OH"))
    return eq_facts.get(category) or _new_equipment_fact_slot()


READY_GENERAL_EQUIPMENT_LABELS = {
    "самосвал": "dump_truck",
    "экскаватор": "excavator",
    "бульдозер": "bulldozer",
}

READY_GENERAL_EQUIPMENT_CATEGORY_LABELS = {
    "песок": "SAND",
    "щебень": "SCHEBEN",
    "щпс": "SHPS",
    "щпгс": "SHPS",
    "перевозка": "MOVE",
    "перемещение": "MOVE",
    "выемка": "VYEMKA",
    "канавы": "DITCH",
    "планировка": "GRADING",
    "прс": "PRS",
    "сопутствующие работы": "RELATED",
    "сопутствующее": "RELATED",
}


def _ready_general_equipment_category_from_label(label: object) -> Optional[str]:
    text = _normalize_general_label(label)
    if not text:
        return None
    for needle, category in READY_GENERAL_EQUIPMENT_CATEGORY_LABELS.items():
        if needle in text:
            return category
    return None


def _find_ready_general_equipment_rows(ws) -> dict[str, dict]:
    """Find ready-template equipment rows from visible Russian labels."""
    rows: dict[str, dict] = {}
    current_eq: Optional[str] = None
    current_category: Optional[str] = None
    for row_idx in range(1, ws.max_row + 1):
        b_text = _normalize_general_label(ws.cell(row=row_idx, column=2).value)
        c_text = _normalize_general_label(ws.cell(row=row_idx, column=3).value)
        d_text = _normalize_general_label(ws.cell(row=row_idx, column=4).value)

        if _general_period_key(ws.cell(row=row_idx, column=2).value) and current_eq:
            current_eq = None
            current_category = None
            continue

        eq = READY_GENERAL_EQUIPMENT_LABELS.get(b_text)
        if eq:
            current_eq = eq
            current_category = None
            rows.setdefault(eq, {"counts": {}, "categories": {}})

        if not current_eq:
            continue

        counts = rows.setdefault(current_eq, {"counts": {}, "categories": {}})["counts"]
        if "плановое количество" in c_text and "день" in c_text:
            counts["plan_day"] = row_idx
            continue
        if "плановое количество" in c_text and "ночь" in c_text:
            counts["plan_night"] = row_idx
            continue
        if "фактическое количество" in c_text and ("сутки" in c_text or "за сутки" in c_text):
            counts["fact_total"] = row_idx
            continue
        if "фактическое количество" in c_text and "день" in c_text:
            counts["fact_day"] = row_idx
            continue
        if "фактическое количество" in c_text and "ночь" in c_text:
            counts["fact_night"] = row_idx
            continue
        if "% от норматива" in c_text:
            counts["percent"] = row_idx
            continue

        category = _ready_general_equipment_category_from_label(ws.cell(row=row_idx, column=3).value)
        if category:
            current_category = category
            rows[current_eq]["categories"].setdefault(category, {})
        if not current_category or not d_text:
            continue
        cat_rows = rows[current_eq]["categories"].setdefault(current_category, {})
        if d_text.startswith("план за сутки по пп"):
            cat_rows["db_plan"] = row_idx
        elif d_text.startswith("плановая выработка"):
            cat_rows["plan_total"] = row_idx
        elif d_text.startswith("план за день"):
            cat_rows["plan_day"] = row_idx
        elif d_text.startswith("план за ночь"):
            cat_rows["plan_night"] = row_idx
        elif d_text.startswith("факт завоз"):
            cat_rows["stockpile_in"] = row_idx
        elif d_text.startswith("факт вывоз"):
            cat_rows["stockpile_out"] = row_idx
        elif d_text.startswith("факт за сутки"):
            if current_eq == "dump_truck" and current_category == "SAND" and ("алмаз" in d_text or "наем" in d_text or "наём" in d_text):
                cat_rows["external_total"] = row_idx
            elif current_eq == "dump_truck" and current_category == "SAND" and "ждс" in d_text:
                cat_rows["non_hired_total"] = row_idx
            elif "fact_total" not in cat_rows:
                # Keep the first plain "Факт за сутки" row as the canonical
                # day+night total.  Some ready templates also include explicit
                # source rows below (e.g. "Факт за сутки ЖДС"); those must not
                # steal the canonical row and leave it blank.
                cat_rows["fact_total"] = row_idx
        elif d_text.startswith("факт за день"):
            cat_rows["fact_day"] = row_idx
        elif d_text.startswith("факт за ночь"):
            cat_rows["fact_night"] = row_idx
    return rows


