def _ready_general_volume_category_from_label(label: object) -> Optional[str]:
    text = _normalize_general_label(label)
    if not text:
        return None
    for needle, category in READY_GENERAL_VOLUME_CATEGORY_LABELS:
        if needle in text:
            return category
    return None


def _ready_general_volume_plan_category(
    label: object,
    sublabel: object,
    d_label: object = None,
    note: object = None,
    current_group: Optional[str] = None,
) -> Optional[str]:
    label_text = _normalize_general_label(label)
    sub_text = _normalize_general_label(sublabel)
    d_text = _normalize_general_label(d_label)
    note_text = _normalize_general_label(note)
    combined = " ".join(part for part in (label_text, sub_text) if part).strip()
    category = _ready_general_volume_category_from_label(combined or label_text or sub_text)
    if category:
        return category
    if label_text == "прс":
        current_group = "prs"
    if label_text == "завоз песка":
        return "SAND_HAUL"
    if label_text == "укладка песка":
        current_group = "sand"
    elif label_text == "выемка":
        current_group = "vyemka"
    combined_details = " ".join(part for part in (sub_text, d_text, note_text) if part).strip()
    if "валдай" in combined_details and "выползово" not in combined_details:
        tp_bucket = "VALDAI"
    elif "выползово" in combined_details and "валдай" not in combined_details:
        tp_bucket = "VYPOLZOVO"
    elif sub_text == "тп" or "факт тп" in d_text or ("валдай" in combined_details and "выползово" in combined_details):
        tp_bucket = "TP"
    else:
        tp_bucket = None
    if current_group == "prs":
        if sub_text == "вад":
            return "PRS_VAD"
        if sub_text == "ох":
            return "PRS_OH"
        if sub_text == "свайные поля":
            return "PRS_PILE"
        if tp_bucket == "TP":
            return "PRS_TP"
        if tp_bucket == "VALDAI":
            return "PRS_VALDAI"
        if tp_bucket == "VYPOLZOVO":
            return "PRS_VYPOLZOVO"
        if sub_text == "прочее":
            return "PRS_OTHER"
        if label_text == "прс" and sub_text in {"", "всего"}:
            return "PRS"
    if current_group == "sand":
        if sub_text == "вад":
            return "SAND_VAD"
        if sub_text == "ох":
            return "SAND_OH"
        if sub_text == "свайные поля":
            return "SAND_PILE"
        if tp_bucket == "TP":
            return "SAND_TP"
        if tp_bucket == "VALDAI":
            return "SAND_VALDAI"
        if tp_bucket == "VYPOLZOVO":
            return "SAND_VYPOLZOVO"
        if sub_text == "прочее":
            return "SAND"
        if label_text == "укладка песка" and sub_text in {"", "всего"}:
            return "SAND_TOTAL"
    if current_group == "vyemka":
        if sub_text == "вад":
            return "VYEMKA"
        if sub_text == "ох":
            return "VYEMKA_OH"
        if sub_text == "свайные поля":
            return "VYEMKA_PILE"
        if tp_bucket == "TP":
            return "VYEMKA_TP"
        if tp_bucket == "VALDAI":
            return "VYEMKA_VALDAI"
        if tp_bucket == "VYPOLZOVO":
            return "VYEMKA_VYPOLZOVO"
        if sub_text == "прочее":
            return "VYEMKA_OTHER"
        if label_text == "выемка" and sub_text in {"", "всего"}:
            return "VYEMKA_TOTAL"
    if label_text == "прс":
        return "PRS"
    return None


def _ready_general_volume_categories_for_totals(category_rows: dict[str, dict]) -> list[str]:
    """Choose visible categories for the summary percent without double-counting."""
    visible = set(category_rows or {})
    categories: list[str] = []
    if "PRS" in visible:
        categories.append("PRS")
    else:
        for category in ("PRS_VAD", "PRS_OH", "PRS_PILE", "PRS_OTHER"):
            if category in visible:
                categories.append(category)
    if "SAND_TOTAL" in visible:
        categories.append("SAND_TOTAL")
    else:
        for category in ("SAND_VAD", "SAND_OH", "SAND_PILE", "SAND"):
            if category in visible:
                categories.append(category)
    if "VYEMKA_TOTAL" in visible:
        categories.append("VYEMKA_TOTAL")
    else:
        for category in ("VYEMKA", "VYEMKA_OH", "VYEMKA_PILE", "VYEMKA_OTHER"):
            if category in visible:
                categories.append(category)
    for category in ("SCHEBEN", "SHPS"):
        if category in visible:
            categories.append(category)
    return categories


def _looks_like_ready_general_volume_period(ws, row_idx: int) -> bool:
    if not _general_period_key(ws.cell(row=row_idx, column=2).value):
        return False
    for scan_row in range(row_idx + 1, min(ws.max_row, row_idx + 8) + 1):
        if "% выполнения объема" in _normalize_general_label(ws.cell(row=scan_row, column=3).value):
            return True
    return False


def _find_ready_general_volume_rows(ws) -> dict[str, dict]:
    rows: dict[str, dict] = {}
    period_starts = [
        row_idx
        for row_idx in range(1, ws.max_row + 1)
        if _looks_like_ready_general_volume_period(ws, row_idx)
    ]
    for idx, start_row in enumerate(period_starts):
        period = _general_period_key(ws.cell(row=start_row, column=2).value)
        if not period:
            continue
        if period in rows:
            # The final owner template repeats the same period labels again in
            # the pile section. Those pile blocks also contain "% выполнения"
            # and volume-like plan/fact rows, so the first occurrence of each
            # period is the canonical volume-summary block.
            continue
        boundary = period_starts[idx + 1] if idx + 1 < len(period_starts) else _general_find_next_pile_boundary(ws, start_row)
        block: dict = {"categories": {}, "_row_range": (start_row + 1, boundary - 1)}
        header_rows: list[tuple[int, str]] = []
        fallback_header_rows: list[int] = []
        sand_haul_rows: dict[str, int] = {}
        current_group: Optional[str] = None
        in_sand_haul_block = False
        for row_idx in range(start_row + 1, boundary):
            b_text = _normalize_general_label(ws.cell(row=row_idx, column=2).value)
            c_text = _normalize_general_label(ws.cell(row=row_idx, column=3).value)
            d_text = _normalize_general_label(ws.cell(row=row_idx, column=4).value)
            note_value = ws.cell(row=row_idx, column=15).value
            if b_text == "завоз песка":
                in_sand_haul_block = True
                current_group = None
            elif b_text:
                in_sand_haul_block = False
            if in_sand_haul_block:
                if d_text.startswith("план"):
                    sand_haul_rows["plan"] = row_idx
                elif "факт всего" in d_text:
                    sand_haul_rows["total"] = row_idx
                elif "факт ждс" in d_text:
                    sand_haul_rows["non_hired"] = row_idx
                elif "факт наем" in d_text or "факт наём" in d_text:
                    sand_haul_rows["hired"] = row_idx
                elif "факт алмаз" in d_text:
                    sand_haul_rows["almaz"] = row_idx
                elif "местный грунт" in d_text:
                    sand_haul_rows["local_soil"] = row_idx
            if "% выполнения объема" in c_text:
                block["percent"] = row_idx
            if d_text.startswith("план"):
                if b_text == "прс":
                    current_group = "prs"
                elif b_text == "укладка песка":
                    current_group = "sand"
                elif b_text == "выемка":
                    current_group = "vyemka"
                elif b_text and b_text != "завоз песка":
                    current_group = None
                category = _ready_general_volume_plan_category(
                    ws.cell(row=row_idx, column=2).value,
                    ws.cell(row=row_idx, column=3).value,
                    ws.cell(row=row_idx, column=4).value,
                    note_value,
                    current_group,
                )
                if category:
                    header_rows.append((row_idx, category))
                elif c_text == "объем":
                    fallback_header_rows.append(row_idx)
        if fallback_header_rows:
            assigned_categories = {category for _, category in header_rows if category != "SAND_HAUL"}
            remaining_categories = [
                category
                for category in READY_GENERAL_VOLUME_CATEGORY_SEQUENCE
                if category not in assigned_categories
            ]
            for row_idx, category in zip(fallback_header_rows, remaining_categories):
                if category not in assigned_categories:
                    header_rows.append((row_idx, category))
                    assigned_categories.add(category)
        header_rows.sort(key=lambda item: item[0])
        for idx, (row_idx, category) in enumerate(header_rows):
            next_header = header_rows[idx + 1][0] if idx + 1 < len(header_rows) else boundary
            if category == "SAND_HAUL":
                continue
            cat_rows = block["categories"].setdefault(category, {})
            cat_rows["plan"] = row_idx
            for fact_row in range(row_idx + 1, next_header):
                d_text = _normalize_general_label(ws.cell(row=fact_row, column=4).value)
                if d_text.startswith("факт завоз"):
                    stockpile_category = "SCHEBEN_STOCKPILE" if category == "SCHEBEN" else ("SHPS_STOCKPILE" if category == "SHPS" else None)
                    if stockpile_category:
                        block["categories"].setdefault(stockpile_category, {})["total"] = fact_row
                elif "факт ждс" in d_text:
                    cat_rows["non_hired"] = fact_row
                elif "факт наем" in d_text or "факт наём" in d_text:
                    cat_rows["external"] = fact_row
                elif "факт алмаз" in d_text:
                    cat_rows["almaz"] = fact_row
                elif d_text.startswith("факт"):
                    cat_rows["total"] = fact_row
        if sand_haul_rows:
            block["sand_haul"] = sand_haul_rows
        rows[period] = block
    return rows


def _apply_general_work_row_labels(ws, plan_rows_by_period: dict[str, dict[str, int]], direct_rows: bool) -> None:
    rules = {str(rule.get("code") or ""): rule for rule in _general_report_work_rules()}
    for rows in plan_rows_by_period.values():
        for category, row_idx in rows.items():
            rule = rules.get(category)
            if not rule:
                continue
            target_row = row_idx if direct_rows else _general_target_row(row_idx)
            if target_row is None:
                continue
            _set_general_cell_value(ws, target_row, 2, str(rule.get("label") or "").strip() if rule.get("enabled", True) else None)



def _write_general_metadata_cell(ws, row_idx: Optional[int], column_idx: int, value: Optional[str]) -> None:
    if not row_idx:
        return
    cell = ws.cell(row=row_idx, column=column_idx)
    cell.value = value
    cell.alignment = Alignment(vertical="top", wrap_text=False)



def _ready_general_volume_family(category: Optional[str]) -> str:
    code = str(category or "")
    if code.startswith("PRS"):
        return "PRS"
    if code.startswith("SAND"):
        return "SAND"
    if code.startswith("VYEMKA"):
        return "VYEMKA"
    if code.startswith("SCHEBEN"):
        return "SCHEBEN"
    if code.startswith("SHPS"):
        return "SHPS"
    return code



def _ready_general_volume_scope_text(category: Optional[str], row_kind: str) -> Optional[str]:
    if row_kind == "percent":
        return "Свод по видимым строкам блока периода"
    if row_kind.startswith("sand_haul_"):
        if row_kind == "sand_haul_plan":
            return "Те же объекты, что и «Укладка песка ВСЕГО»"
        return "material_movements: карьер/накопитель → накопитель/конструктив"
    if category == "SCHEBEN_STOCKPILE":
        return "material_movements: карьер → накопитель"
    if category == "SHPS_STOCKPILE":
        return "material_movements: карьер → накопитель"
    if category in {"PRS_VAD", "SAND_VAD", "VYEMKA"}:
        return "TEMP_ROAD, SERVICE_ROAD, TECH_ROAD (кроме pile-access PFT_*)"
    if category in {"PRS_OH", "SAND_OH", "VYEMKA_OH"}:
        return "MAIN_TRACK, STATION_TRACK"
    if category in {"PRS_PILE", "SAND_PILE", "VYEMKA_PILE"}:
        return "PILE_FIELD, PILE_DRIVING_PAD, TECH_ROAD PFT_*"
    if category in {"PRS_TP", "SAND_TP", "VYEMKA_TP"}:
        return "; ".join(GENERAL_REPORT_TP_SCOPE_TEXT[bucket] for bucket in ("VALDAI", "VYPOLZOVO"))
    if category in {"PRS_VALDAI", "SAND_VALDAI", "VYEMKA_VALDAI"}:
        return GENERAL_REPORT_TP_SCOPE_TEXT["VALDAI"]
    if category in {"PRS_VYPOLZOVO", "SAND_VYPOLZOVO", "VYEMKA_VYPOLZOVO"}:
        return GENERAL_REPORT_TP_SCOPE_TEXT["VYPOLZOVO"]
    if category == "PRS_OTHER":
        return "Все объекты ПРС, кроме VAD/ОХ/свайных полей/ТП"
    if category == "SAND":
        return "Прочие объекты песчаных работ вне отдельных строк ОХ/свайных полей/ТП"
    if category == "VYEMKA_OTHER":
        return "Прочие объекты выемки вне отдельных строк ОХ/свайных полей/ТП"
    if category == "SAND_TOTAL":
        return "Все объекты песчаных работ"
    if category == "VYEMKA_TOTAL":
        return "Все объекты выемки / выторфовки"
    if category in {"PRS", "SCHEBEN", "SHPS"}:
        return "Все объекты категории"
    return None



def _ready_general_volume_tag_text(category: Optional[str], row_kind: str) -> Optional[str]:
    if row_kind.startswith("sand_haul_"):
        if row_kind == "sand_haul_local_soil":
            return "facts.SOIL_LOCAL: analytics_tag содержит «грунт», кроме раститель/ПРС/выем/выторф"
        return "material=SAND; movement_type in pit_to_stockpile|pit_to_constructive|stockpile_to_constructive"
    family = _ready_general_volume_family(category)
    if family == "PRS":
        return "analytics_tag: ПРС / растительный; wt_code: TOPSOIL_STRIPPING"
    if family == "SAND":
        work_codes = "EMBANKMENT_CONSTRUCTION, WEAK_SOIL_REPLACEMENT, PAVEMENT_SANDING, SHOULDER_BACKFILL"
        if row_kind == "plan":
            work_codes += ", SECOND_PROTECTIVE_LAYER, ZS2"
        return f"analytics_tag содержит «песок»; wt_code: {work_codes}"
    if family == "VYEMKA":
        return "analytics_tag: Выемка / Выторфовка / Канавы / Кюветы; wt_code: EARTH_EXCAVATION, PEAT_REMOVAL, EXCAVATION_MAIN"
    if family == "SCHEBEN":
        return "analytics_tag: щебень; wt_code: SLOPE_FORMATION_CC"
    if family == "SHPS":
        work_codes = "CRUSHED_STONE_PLACEMENT, FIRST_PROTECTIVE_LAYER, ZS1"
        if row_kind != "plan":
            work_codes += ", SECOND_PROTECTIVE_LAYER, ZS2"
        return f"analytics_tag: ЩПС / ЩПГС / ПГС / ЗС; wt_code: {work_codes}"
    return None



def _ready_general_volume_logic_text(category: Optional[str], row_kind: str) -> Optional[str]:
    if row_kind == "percent":
        return "Процент = отношение суммы факта к сумме плана по видимым строкам периода; использует subtotal-строки, чтобы не было двойного счета."
    if row_kind == "sand_haul_plan":
        return "План берется из planned_work_items песчаных работ (тот же плановый объем, что у «Укладка песка ВСЕГО»), а не из material_movements. День = month/days_in_month, неделя = 0.25*month."
    if row_kind == "sand_haul_total":
        return "Факт = material_movements по доставке песка на площадку. Для накопительного итога используется SAND_DASHBOARD_SITE_DELIVERED, для day/week/month — SAND_SITE_DELIVERED."
    if row_kind == "sand_haul_non_hired":
        return "Только source_bucket=non_hired (ЖДС / собственные)."
    if row_kind == "sand_haul_hired":
        return "Только source_bucket=hired (наемные)."
    if row_kind == "sand_haul_almaz":
        return "Только source_bucket=almaz."
    if row_kind == "sand_haul_local_soil":
        return "day/week/month: факт из SOIL_LOCAL. Накопительно: SAND_TOTAL fact − sand haul delivered; отрицательные значения по участкам обрезаются до 0, total ячейка хранит сырой diff."
    if category == "SCHEBEN_STOCKPILE":
        return "Факт завоза = material_movements с material=SCHEBEN и route pit_to_stockpile."
    if category == "SHPS_STOCKPILE":
        return "Факт завоза = material_movements с material=SHPS и route pit_to_stockpile; накопительно при наличии берется SHPGS_DASHBOARD_SITE_DELIVERED, иначе fallback = SHPS_PIT_TO_STOCKPILE + SHPS факт."
    source = (
        "План = planned_work_items; день считается как month/days_in_month, неделя = 0.25*month, накопительно = PROJECT_START..report_date."
        if row_kind == "plan"
        else "Факт = daily_work_items + daily_work_item_segments; берутся только утвержденные/подтвержденные записи."
    )
    if category in {"PRS_TP", "SAND_TP", "VYEMKA_TP"}:
        return f"{source} ТП = Валдай + Выползово."
    if category in {"PRS_PILE", "SAND_PILE", "VYEMKA_PILE"}:
        return f"{source} Только свайные поля, стартовые площадки и pile-access дороги PFT_*."
    if category in {"PRS_VALDAI", "SAND_VALDAI", "VYEMKA_VALDAI"}:
        return f"{source} Только тяговая подстанция Валдай."
    if category in {"PRS_VYPOLZOVO", "SAND_VYPOLZOVO", "VYEMKA_VYPOLZOVO"}:
        return f"{source} Только тяговая подстанция Выползово."
    if category == "PRS_OTHER":
        return f"{source} Прочее = PRS − PRS_VAD − PRS_OH − PRS_PILE − PRS_VALDAI − PRS_VYPOLZOVO; по участкам floor до 0."
    if category == "SAND":
        return f"{source} Прочее = базовый SAND − SAND_VALDAI − SAND_VYPOLZOVO, когда TP-строки присутствуют в шаблоне."
    if category == "VYEMKA_OTHER":
        return f"{source} Прочее = VYEMKA_OTHER − VYEMKA_VALDAI − VYEMKA_VYPOLZOVO, когда TP-строки присутствуют в шаблоне."
    if category == "SAND_TOTAL":
        return f"{source} ВСЕГО = SAND + SAND_VAD + SAND_OH + SAND_PILE."
    if category == "VYEMKA_TOTAL":
        return f"{source} ВСЕГО = VYEMKA + VYEMKA_OH + VYEMKA_PILE + VYEMKA_OTHER."
    return source



def _annotate_ready_general_volume_rows(ws, volume_rows: dict[str, dict]) -> None:
    ws.cell(row=1, column=GENERAL_ANALYTICS_META_OBJECT_COL, value="Объекты / source")
    ws.cell(row=1, column=GENERAL_ANALYTICS_META_TAG_COL, value="Теги / work types")
    ws.cell(row=1, column=GENERAL_ANALYTICS_META_LOGIC_COL, value="Логика / исключения")
    ws.column_dimensions[get_column_letter(GENERAL_ANALYTICS_META_OBJECT_COL)].width = 46
    ws.column_dimensions[get_column_letter(GENERAL_ANALYTICS_META_TAG_COL)].width = 44
    ws.column_dimensions[get_column_letter(GENERAL_ANALYTICS_META_LOGIC_COL)].width = 74
    for col_idx in (
        GENERAL_ANALYTICS_META_OBJECT_COL,
        GENERAL_ANALYTICS_META_TAG_COL,
        GENERAL_ANALYTICS_META_LOGIC_COL,
    ):
        ws.cell(row=1, column=col_idx).alignment = Alignment(vertical="top", wrap_text=False)

    for block in volume_rows.values():
        row_range = block.get("_row_range")
        if isinstance(row_range, tuple) and len(row_range) == 2:
            start_row, end_row = row_range
            for row_idx in range(int(start_row), int(end_row) + 1):
                for col_idx in (
                    GENERAL_ANALYTICS_META_OBJECT_COL,
                    GENERAL_ANALYTICS_META_TAG_COL,
                    GENERAL_ANALYTICS_META_LOGIC_COL,
                ):
                    ws.cell(row=row_idx, column=col_idx, value=None)

        percent_row = block.get("percent")
        if percent_row:
            _write_general_metadata_cell(ws, percent_row, GENERAL_ANALYTICS_META_OBJECT_COL, _ready_general_volume_scope_text(None, "percent"))
            _write_general_metadata_cell(ws, percent_row, GENERAL_ANALYTICS_META_TAG_COL, "Сумма план/факт по строкам блока")
            _write_general_metadata_cell(ws, percent_row, GENERAL_ANALYTICS_META_LOGIC_COL, _ready_general_volume_logic_text(None, "percent"))

        for category, rows in (block.get("categories") or {}).items():
            for row_kind, row_idx in (rows or {}).items():
                _write_general_metadata_cell(ws, row_idx, GENERAL_ANALYTICS_META_OBJECT_COL, _ready_general_volume_scope_text(category, row_kind))
                _write_general_metadata_cell(ws, row_idx, GENERAL_ANALYTICS_META_TAG_COL, _ready_general_volume_tag_text(category, row_kind))
                _write_general_metadata_cell(ws, row_idx, GENERAL_ANALYTICS_META_LOGIC_COL, _ready_general_volume_logic_text(category, row_kind))

        for row_kind, row_idx in (block.get("sand_haul") or {}).items():
            bucket_key = f"sand_haul_{row_kind}"
            _write_general_metadata_cell(ws, row_idx, GENERAL_ANALYTICS_META_OBJECT_COL, _ready_general_volume_scope_text(None, bucket_key))
            _write_general_metadata_cell(ws, row_idx, GENERAL_ANALYTICS_META_TAG_COL, _ready_general_volume_tag_text(None, bucket_key))
            _write_general_metadata_cell(ws, row_idx, GENERAL_ANALYTICS_META_LOGIC_COL, _ready_general_volume_logic_text(None, bucket_key))



def _fill_ready_general_volume_summary(
    ws,
    work_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    plan_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    movement_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    current_day_sand_output: dict[str, float],
) -> None:
    volume_rows = _find_ready_general_volume_rows(ws)
    _annotate_ready_general_volume_rows(ws, volume_rows)

    for period_key, block in volume_rows.items():
        plans = plan_periods.get(period_key, {})
        facts = work_periods.get(period_key, {})
        movements = movement_periods.get(period_key, {})
        category_rows = block.get("categories") or {}
        visible_categories = set(category_rows)

        def _ready_split_other_bucket(
            source: dict[str, dict[str, dict[str, float]]],
            base_category: str,
            split_categories: tuple[str, ...],
            bucket: str,
            subtract_when_visible: set[str],
        ) -> dict[str, float]:
            values = _category_bucket(source, base_category, bucket)
            if not (visible_categories & subtract_when_visible):
                return values
            for split_category in split_categories:
                values = _subtract_section_values(values, _category_bucket(source, split_category, bucket))
            return _floor_section_values(values)

        def _ready_volume_category_bucket(
            source: dict[str, dict[str, dict[str, float]]],
            category: str,
            bucket: str = "total",
        ) -> dict[str, float]:
            if category == "SAND_TOTAL":
                return _sum_category_buckets(source, ("SAND", "SAND_VAD", "SAND_OH", "SAND_PILE"), bucket)
            if category == "SAND_TP":
                return _sum_category_buckets(source, ("SAND_VALDAI", "SAND_VYPOLZOVO"), bucket)
            if category == "SAND":
                return _ready_split_other_bucket(
                    source,
                    "SAND",
                    ("SAND_VALDAI", "SAND_VYPOLZOVO"),
                    bucket,
                    {"SAND_TP", "SAND_VALDAI", "SAND_VYPOLZOVO"},
                )
            if category == "VYEMKA_TOTAL":
                return _sum_category_buckets(source, ("VYEMKA", "VYEMKA_OH", "VYEMKA_PILE", "VYEMKA_OTHER"), bucket)
            if category == "VYEMKA_TP":
                return _sum_category_buckets(source, ("VYEMKA_VALDAI", "VYEMKA_VYPOLZOVO"), bucket)
            if category == "VYEMKA_OTHER":
                return _ready_split_other_bucket(
                    source,
                    "VYEMKA_OTHER",
                    ("VYEMKA_VALDAI", "VYEMKA_VYPOLZOVO"),
                    bucket,
                    {"VYEMKA_TP", "VYEMKA_VALDAI", "VYEMKA_VYPOLZOVO"},
                )
            if category == "PRS_TP":
                return _sum_category_buckets(source, ("PRS_VALDAI", "PRS_VYPOLZOVO"), bucket)
            if category == "PRS_OTHER":
                values = _category_bucket(source, "PRS", bucket)
                if not (visible_categories & {"PRS_VAD", "PRS_OH", "PRS_PILE", "PRS_TP", "PRS_VALDAI", "PRS_VYPOLZOVO"}):
                    return values
                for split_category in ("PRS_VAD", "PRS_OH", "PRS_PILE", "PRS_VALDAI", "PRS_VYPOLZOVO"):
                    values = _subtract_section_values(values, _category_bucket(source, split_category, bucket))
                return _floor_section_values(values)
            return _category_bucket(source, category, bucket)

        def _ready_external_category_bucket(source: dict[str, dict[str, dict[str, float]]], category: str) -> dict[str, float]:
            return _sum_section_values(
                _ready_volume_category_bucket(source, category, "almaz"),
                _ready_volume_category_bucket(source, category, "hired"),
            )

        categories_for_totals = _ready_general_volume_categories_for_totals(category_rows)
        sand_haul_rows = block.get("sand_haul") or {}
        sand_haul = movements.get(
            "SAND_DASHBOARD_SITE_DELIVERED" if period_key == "total" else "SAND_SITE_DELIVERED"
        ) or _new_work_fact_slot()
        local_soil = facts.get("SOIL_LOCAL") or _new_work_fact_slot()
        sand_material_plan = _ready_volume_category_bucket(plans, "SAND_TOTAL")
        sand_total_fact = _ready_volume_category_bucket(facts, "SAND_TOTAL")
        local_soil_total_override = None
        if period_key == "total":
            local_soil_raw = _subtract_section_values(sand_total_fact, sand_haul.get("total") or _section_values())
            local_soil_display = _floor_section_values(local_soil_raw)
            local_soil_total_override = sum(local_soil_raw.values())
        else:
            local_soil_display = _floor_section_values(local_soil.get("total") or _section_values())
        sand_haul_plan_row = sand_haul_rows.get("plan")
        if sand_haul_plan_row:
            _write_section_values_at_row(ws, sand_haul_plan_row, sand_material_plan)
        for bucket, row in sand_haul_rows.items():
            if bucket == "plan":
                continue
            if bucket == "local_soil":
                _write_section_values_at_row(ws, row, local_soil_display, total_override=local_soil_total_override)
            else:
                _write_section_values_at_row(ws, row, sand_haul.get(bucket) or _section_values())
        for category, rows in category_rows.items():
            if category == "SHPS_STOCKPILE":
                row = rows.get("total")
                if row:
                    shps_dashboard_delivery_values = _category_bucket(movements, "SHPGS_DASHBOARD_SITE_DELIVERED")
                    if period_key == "total" and _section_values_has_data(shps_dashboard_delivery_values):
                        shps_stockpile_values = shps_dashboard_delivery_values
                    else:
                        shps_stockpile_values = _category_bucket(movements, "SHPS_PIT_TO_STOCKPILE")
                    if period_key == "total" and not _section_values_has_data(shps_dashboard_delivery_values):
                        shps_stockpile_values = _sum_section_values(
                            shps_stockpile_values,
                            _ready_volume_category_bucket(facts, "SHPS"),
                        )
                    _write_section_values_at_row(ws, row, shps_stockpile_values)
                continue
            if category == "SCHEBEN_STOCKPILE":
                row = rows.get("total")
                if row:
                    _write_section_values_at_row(ws, row, _category_bucket(movements, "SCHEBEN_PIT_TO_STOCKPILE"))
                continue
            plan_row = rows.get("plan")
            if plan_row:
                _write_section_values_at_row(ws, plan_row, _ready_volume_category_bucket(plans, category))
            total_row = rows.get("total")
            if total_row:
                _write_section_values_at_row(ws, total_row, _ready_volume_category_bucket(facts, category))
            non_hired_row = rows.get("non_hired")
            if non_hired_row:
                _write_section_values_at_row(ws, non_hired_row, _ready_volume_category_bucket(facts, category, "non_hired"))
            external_row = rows.get("external")
            if external_row:
                _write_section_values_at_row(ws, external_row, _ready_external_category_bucket(facts, category))

        planned = _section_values()
        actual = _section_values()
        for category in categories_for_totals:
            planned = _sum_section_values(planned, _ready_volume_category_bucket(plans, category))
            actual = _sum_section_values(actual, _ready_volume_category_bucket(facts, category))
        percent_row = block.get("percent")
        if percent_row:
            _write_general_ratio_values_at_row(ws, percent_row, actual, planned)


def _fill_general_volume_summary(
    ws,
    work_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    plan_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    movement_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
    current_day_sand_output: dict[str, float],
) -> None:
    if _is_ready_general_analytics_template(ws):
        _fill_ready_general_volume_summary(ws, work_periods, plan_periods, movement_periods, current_day_sand_output)
        return
    plan_rows_by_period = {
        "day": {"PRS": 238, "SAND": 240, "VYEMKA": 245, "VYEMKA_OH": 247, "SCHEBEN": 249, "SHPS": 251},
        "week": {"PRS": 262, "SAND": 264, "VYEMKA": 268, "VYEMKA_OH": 270, "SCHEBEN": 272, "SHPS": 274},
        "month": {"PRS": 285, "SAND": 287, "VYEMKA": 293, "VYEMKA_OH": 295, "SCHEBEN": 297, "SHPS": 299},
        "total": {"PRS": 310, "SAND": 312, "VYEMKA": 314, "VYEMKA_OH": 316, "SCHEBEN": 318, "SHPS": 320},
        "week_duplicate": {"PRS": 330, "SAND": 332, "VYEMKA": 336, "VYEMKA_OH": 338, "SCHEBEN": 340, "SHPS": 342},
        "month_duplicate": {"PRS": 352, "SAND": 354, "VYEMKA": 357, "VYEMKA_OH": 359, "SCHEBEN": 361, "SHPS": 363},
    }
    rows_by_period = {
        "day": {"PRS": 239, "SAND_OUTPUT": 241, "SAND_NON": 242, "SAND_ALMAZ": 243, "SAND_HIRED": 244, "VYEMKA": 246, "VYEMKA_OH": 248, "SCHEBEN": 250, "SHPS": 252, "SHPS_STOCKPILE": 253},
        "week": {"PRS": 263, "SAND_NON": 265, "SAND_ALMAZ": 266, "SAND_HIRED": 267, "VYEMKA": 269, "VYEMKA_OH": 271, "SCHEBEN": 273, "SHPS": 275, "SHPS_STOCKPILE": 276},
        "month": {"PRS": 286, "SAND_TOTAL": 288, "SAND_SITE_DELIVERED": 289, "SAND_NON": 290, "SAND_ALMAZ": 291, "SAND_HIRED": 292, "VYEMKA": 294, "VYEMKA_OH": 296, "SCHEBEN": 298, "SHPS": 300, "SHPS_STOCKPILE": 301},
        "total": {"PRS": 311, "SAND_TOTAL": 313, "VYEMKA": 315, "VYEMKA_OH": 317, "SCHEBEN": 319, "SHPS": 321, "SHPS_STOCKPILE": 322},
        "week_duplicate": {"PRS": 331, "SAND_NON": 333, "SAND_ALMAZ": 334, "SAND_HIRED": 335, "VYEMKA": 337, "VYEMKA_OH": 339, "SCHEBEN": 341, "SHPS": 343},
        "month_duplicate": {"PRS": 353, "SAND_TOTAL": 355, "SAND_SITE_DELIVERED": 356, "VYEMKA": 358, "VYEMKA_OH": 360, "SCHEBEN": 362, "SHPS": 364},
    }
    _apply_general_work_row_labels(ws, plan_rows_by_period, False)
    alias = {"week_duplicate": "week", "month_duplicate": "month"}
    for period_key, rows in plan_rows_by_period.items():
        plans = plan_periods.get(alias.get(period_key, period_key), {})
        for category, source_row in rows.items():
            _write_section_values(ws, source_row, _category_bucket(plans, category))
    _write_section_values(ws, 241, current_day_sand_output)

    for period_key, rows in rows_by_period.items():
        actual_period = alias.get(period_key, period_key)
        facts = work_periods.get(actual_period, {})
        movements = movement_periods.get(actual_period, {})
        if "PRS" in rows:
            _write_section_values(ws, rows["PRS"], _category_bucket(facts, "PRS"))
        if "SAND_TOTAL" in rows:
            _write_section_values(ws, rows["SAND_TOTAL"], _category_bucket(facts, "SAND"))
        if "SAND_SITE_DELIVERED" in rows:
            _write_section_values(ws, rows["SAND_SITE_DELIVERED"], _category_bucket(movements, "SAND_SITE_DELIVERED"))
        if "SAND_NON" in rows:
            target_row = _general_target_row(rows["SAND_NON"])
            if target_row is not None:
                _set_general_cell_value(ws, target_row, 4, "Факт всего")
            _write_section_values(ws, rows["SAND_NON"], _category_bucket(facts, "SAND"))
        if "SAND_ALMAZ" in rows:
            _write_section_values(ws, rows["SAND_ALMAZ"], _category_bucket(facts, "SAND", "almaz"))
        if "SAND_HIRED" in rows:
            _write_section_values(ws, rows["SAND_HIRED"], _category_bucket(facts, "SAND", "hired"))
        if "SHPS_STOCKPILE" in rows:
            shps_dashboard_delivery_values = _category_bucket(movements, "SHPGS_DASHBOARD_SITE_DELIVERED")
            if actual_period == "total" and _section_values_has_data(shps_dashboard_delivery_values):
                shps_stockpile_values = shps_dashboard_delivery_values
            else:
                shps_stockpile_values = _category_bucket(movements, "SHPS_PIT_TO_STOCKPILE")
            if actual_period == "total" and not _section_values_has_data(shps_dashboard_delivery_values):
                shps_stockpile_values = _sum_section_values(
                    shps_stockpile_values,
                    _category_bucket(facts, "SHPS"),
                )
            _write_section_values(
                ws,
                rows["SHPS_STOCKPILE"],
                shps_stockpile_values,
            )
        for category in ("VYEMKA", "VYEMKA_OH", "SCHEBEN", "SHPS"):
            if category in rows:
                _write_section_values(ws, rows[category], _category_bucket(facts, category))



def _norm_from_settings(equipment_type: str, work_type_codes: tuple[str, ...], fallback: float) -> float:
    for work_type_code in work_type_codes:
        spec = WORK_TYPE_NORMS.get((equipment_type, work_type_code))
        if spec and spec.get("norm") is not None:
            try:
                return float(spec.get("norm") or fallback)
            except (TypeError, ValueError):
                return fallback
    return fallback


def _plan_from_counts(
    day_counts: dict[str, float],
    night_counts: dict[str, float],
    norm_by_section: dict[str, float],
    total_counts: Optional[dict[str, float]] = None,
) -> tuple[dict[str, float], dict[str, float], dict[str, float]]:
    day_values = _section_values()
    night_values = _section_values()
    total_values = _section_values()
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        norm = float(norm_by_section.get(section_code) or 0)
        day_values[section_code] = float(day_counts.get(section_code) or 0) * norm
        night_values[section_code] = float(night_counts.get(section_code) or 0) * norm
        if total_counts is None:
            total_values[section_code] = day_values[section_code] + night_values[section_code]
        else:
            total_values[section_code] = float(total_counts.get(section_code) or 0) * norm
    return total_values, day_values, night_values


def _write_plan_from_counts(
    ws,
    day_counts: dict[str, float],
    night_counts: dict[str, float],
    norm_by_section: dict[str, float],
    total_row: int,
    day_row: int,
    night_row: int,
    total_counts: Optional[dict[str, float]] = None,
) -> dict[str, float]:
    total_values, day_values, night_values = _plan_from_counts(day_counts, night_counts, norm_by_section, total_counts)
    _write_section_values(ws, total_row, total_values)
    _write_section_values(ws, day_row, day_values)
    _write_section_values(ws, night_row, night_values)
    return total_values


def _constant_norms(value: float) -> dict[str, float]:
    return {section_code: float(value) for section_code in GENERAL_ANALYTICS_SECTION_CODES}


def _sand_pit_norms() -> dict[str, float]:
    values = _constant_norms(0)
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        section_num = _general_section_num(section_code)
        spec = DUMP_TRUCK_NORMS.get((section_num or 0, "SAND"))
        if spec:
            values[section_code] = float(spec.get("trips") or 0) * float(spec.get("m3_per_trip") or 0)
    return values


def _general_plan_category(plans: dict[str, dict[str, dict[str, float]]], category: str) -> dict[str, float]:
    return ((plans.get(category) or {}).get("total") or _section_values())

def _fill_general_equipment_plan_rows(ws, plan_day: dict[str, dict[str, dict[str, float]]]) -> None:
    if _is_ready_general_analytics_template(ws):
        equipment_rows = _find_ready_general_equipment_rows(ws)
        for eq_rows in equipment_rows.values():
            for category, rows in (eq_rows.get("categories") or {}).items():
                row = rows.get("db_plan")
                if not row:
                    continue
                values = _sum_category_buckets(plan_day, ("SAND", "SAND_VAD", "SAND_OH")) if category == "SAND" else (
                    _sum_category_buckets(plan_day, ("VYEMKA", "VYEMKA_OH")) if category == "VYEMKA" else _general_plan_category(plan_day, category)
                )
                _write_section_values_at_row(ws, row, values)
        return

    for category, rows in {
        "SAND": (66, 111, 185),
        "SCHEBEN": (84,),
        "SHPS": (91, 125, 178),
        "VYEMKA": (118, 192),
        "PRS": (171,),
        "DITCH": (140,),
        "MOVE": (133,),
        "GRADING": (199,),
    }.items():
        values = _general_plan_category(plan_day, category)
        for row in rows:
            _write_section_values(ws, row, values)


def _write_ready_general_equipment_count_by_label(ws, label_fragment: str, values: dict[str, float], first_only: bool = True) -> None:
    needle = _normalize_general_label(label_fragment)
    for row_idx in range(1, ws.max_row + 1):
        text = _normalize_general_label(ws.cell(row=row_idx, column=3).value)
        if needle and needle in text:
            _write_section_values_at_row(ws, row_idx, values)
            if first_only:
                return


def _ready_row(rows: dict, key: str) -> Optional[int]:
    row = rows.get(key)
    return int(row) if row else None


def _write_ready_general_manual_equipment_count_rows(
    ws,
    plan_counts: Optional[dict[str, dict[str, dict[str, float]]]],
) -> None:
    plan_counts = plan_counts or {}
    equipment_rows = _find_ready_general_equipment_rows(ws)
    for equipment_key in GENERAL_REPORT_MANUAL_PLAN_EQUIPMENT:
        count_rows = (equipment_rows.get(equipment_key) or {}).get("counts") or {}
        equipment_values = plan_counts.get(equipment_key) or {}
        for shift_key, row_key in (("day", "plan_day"), ("night", "plan_night")):
            row = _ready_row(count_rows, row_key)
            if not row:
                continue
            _write_optional_section_values_at_row(ws, row, equipment_values.get(shift_key))


def _write_ready_plan_from_counts(
    ws,
    category_rows: dict,
    day_counts: dict[str, float],
    night_counts: dict[str, float],
    norm_by_section: dict[str, float],
    total_counts: Optional[dict[str, float]] = None,
) -> dict[str, float]:
    total_values, day_values, night_values = _plan_from_counts(day_counts, night_counts, norm_by_section, total_counts)
    total_row = _ready_row(category_rows, "plan_total")
    day_row = _ready_row(category_rows, "plan_day")
    night_row = _ready_row(category_rows, "plan_night")
    if total_row:
        _write_section_values_at_row(ws, total_row, total_values)
    if day_row:
        _write_section_values_at_row(ws, day_row, day_values)
    if night_row:
        _write_section_values_at_row(ws, night_row, night_values)
    return total_values


def _fill_ready_general_equipment(
    ws,
    report_date: date_cls,
    codes: Optional[list[str]],
    movement_day: dict[str, dict[str, dict[str, float]]],
    plan_day: dict[str, dict[str, dict[str, float]]],
) -> dict[str, float]:
    counts = _query_general_equipment_counts(report_date, codes)
    equipment_facts = _query_general_equipment_work_facts(report_date, codes)
    equipment_work_counts = _query_general_equipment_work_counts(report_date, codes)
    equipment_rules = {code: _general_equipment_rule_for_class(code) for code in GENERAL_REPORT_EQUIPMENT_CLASS_CODES}
    equipment_rows = _find_ready_general_equipment_rows(ws)
    _fill_general_equipment_plan_rows(ws, plan_day)

    for eq, eq_rows in equipment_rows.items():
        slot = counts.get(eq) or _new_equipment_fact_slot()
        rule = equipment_rules.get(eq)
        count_rows = eq_rows.get("counts") or {}
        total_row = _ready_row(count_rows, "fact_total")
        day_row = _ready_row(count_rows, "fact_day")
        night_row = _ready_row(count_rows, "fact_night")
        if total_row:
            total_override = None
            if eq == "dump_truck":
                total_override = _query_general_dump_truck_non_hired_unique_daily_total(report_date, codes)
            _write_section_values_at_row(
                ws,
                total_row,
                _general_equipment_slot_values(slot, "total", rule),
                total_override=total_override,
            )
        if day_row:
            _write_section_values_at_row(ws, day_row, _general_equipment_slot_values(slot, "day", rule))
        if night_row:
            _write_section_values_at_row(ws, night_row, _general_equipment_slot_values(slot, "night", rule))

    dump_rows = equipment_rows.get("dump_truck", {})
    dump_categories = dump_rows.get("categories") or {}
    dump_rule = equipment_rules.get("dump_truck")
    dump_sand_productivity_counts = _query_general_dump_truck_sand_productivity_plan_counts(report_date, codes)
    sand_output = _write_ready_plan_from_counts(
        ws,
        dump_categories.get("SAND") or {},
        dump_sand_productivity_counts.get("day") or _section_values(),
        dump_sand_productivity_counts.get("night") or _section_values(),
        _sand_pit_norms(),
        total_counts=dump_sand_productivity_counts.get("total") or _section_values(),
    )
    generic_norms = _constant_norms(float(GENERIC_TRUCK_NORM))
    for category in ("SCHEBEN", "SHPS", "MOVE"):
        _write_ready_plan_from_counts(
            ws,
            dump_categories.get(category) or {},
            _general_equipment_plan_counts_for_category(equipment_work_counts, "dump_truck", category, "day", dump_rule),
            _general_equipment_plan_counts_for_category(equipment_work_counts, "dump_truck", category, "night", dump_rule),
            generic_norms,
        )

    excavator_rows = equipment_rows.get("excavator", {})
    excavator_categories = excavator_rows.get("categories") or {}
    excavator_rule = equipment_rules.get("excavator")
    excavator_norms = {
        "SAND": _constant_norms(_norm_from_settings("экскаватор", ("EMBANKMENT_CONSTRUCTION",), 718.0)),
        "PRS": _constant_norms(_norm_from_settings("экскаватор", ("TOPSOIL_STRIPPING",), 700.0)),
        "VYEMKA": _constant_norms(_norm_from_settings("экскаватор", ("EARTH_EXCAVATION", "PEAT_REMOVAL"), 718.0)),
        "DITCH": _constant_norms(_norm_from_settings("экскаватор", ("DITCH_CONSTRUCTION",), 400.0)),
        "GRADING": _constant_norms(_norm_from_settings("экскаватор", ("AREA_GRADING",), 1018.0)),
    }
    for category, norms in excavator_norms.items():
        _write_ready_plan_from_counts(
            ws,
            excavator_categories.get(category) or {},
            _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", category, "day", excavator_rule),
            _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", category, "night", excavator_rule),
            norms,
        )

    bulldozer_rows = equipment_rows.get("bulldozer", {})
    bulldozer_categories = bulldozer_rows.get("categories") or {}
    bulldozer_rule = equipment_rules.get("bulldozer")
    bulldozer_norms = {
        "PRS": _constant_norms(_norm_from_settings("бульдозер", ("TOPSOIL_STRIPPING",), 800.0)),
        "SHPS": _constant_norms(_norm_from_settings("бульдозер", ("CRUSHED_STONE_PLACEMENT", "FIRST_PROTECTIVE_LAYER"), 1400.0)),
        "SAND": _constant_norms(_norm_from_settings("бульдозер", ("PAVEMENT_SANDING", "EMBANKMENT_CONSTRUCTION"), 1400.0)),
        "VYEMKA": _constant_norms(_norm_from_settings("бульдозер", ("EARTH_EXCAVATION",), 500.0)),
        "GRADING": _constant_norms(_norm_from_settings("бульдозер", ("AREA_GRADING",), 2037.0)),
    }
    for category, norms in bulldozer_norms.items():
        _write_ready_plan_from_counts(
            ws,
            bulldozer_categories.get(category) or {},
            _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", category, "day", bulldozer_rule),
            _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", category, "night", bulldozer_rule),
            norms,
        )

    for eq, eq_rows in equipment_rows.items():
        eq_facts = equipment_facts.get(eq) or {}
        rule = equipment_rules.get(eq)
        for category, row_map in (eq_rows.get("categories") or {}).items():
            slot = _equipment_category_slot(eq_facts, category)
            fact_total = _ready_row(row_map, "fact_total")
            fact_day = _ready_row(row_map, "fact_day")
            fact_night = _ready_row(row_map, "fact_night")
            if fact_total:
                _write_section_values_at_row(ws, fact_total, _general_equipment_slot_values(slot, "total", rule))
            if fact_day:
                _write_section_values_at_row(ws, fact_day, _general_equipment_slot_values(slot, "day", rule))
            if fact_night:
                _write_section_values_at_row(ws, fact_night, _general_equipment_slot_values(slot, "night", rule))
            external_total = _ready_row(row_map, "external_total")
            non_hired_total = _ready_row(row_map, "non_hired_total")
            source_slot = slot
            if eq == "dump_truck" and category == "SAND" and (external_total or non_hired_total):
                # The explicit SAND source rows in the ready General report are
                # material-haul source splits, not the broader dump-truck SAND
                # production fact.  Use only карьер→конструктив and
                # карьер→накопитель (SAND_SITE_DELIVERED); otherwise ЖДС rows
                # also pick up накопитель→конструктив and become inflated.
                source_slot = movement_day.get("SAND_SITE_DELIVERED") or slot
            if external_total:
                _write_section_values_at_row(ws, external_total, _general_external_equipment_slot_values(source_slot, "total"))
            if non_hired_total:
                _write_section_values_at_row(ws, non_hired_total, (source_slot or _new_work_fact_slot()).get("non_hired") or _section_values())

    for category, movement_key, bucket_key in (
        ("SAND", "SAND_PIT_TO_STOCKPILE", "stockpile_in"),
        ("SAND", "SAND_STOCKPILE_TO_CONSTRUCTIVE", "stockpile_out"),
        ("SHPS", "SHPS_PIT_TO_STOCKPILE", "stockpile_in"),
    ):
        row = _ready_row(dump_categories.get(category) or {}, bucket_key)
        if row:
            _write_section_values_at_row(ws, row, (movement_day.get(movement_key) or _new_work_fact_slot())["total"])

    def _sum_rows(section_code: str, row_maps: list[dict], key: str) -> float:
        total = 0.0
        for row_map in row_maps:
            row = _ready_row(row_map, key)
            if row:
                total += float(_read_section_values_at_row(ws, row).get(section_code) or 0)
        return total

    for eq, categories_for_percent in (
        ("dump_truck", ("SAND", "SCHEBEN", "SHPS", "MOVE")),
        ("excavator", ("SAND", "PRS", "VYEMKA", "DITCH", "GRADING")),
        ("bulldozer", ("PRS", "SHPS", "SAND", "VYEMKA", "GRADING")),
    ):
        eq_rows = equipment_rows.get(eq, {})
        category_maps = [(eq_rows.get("categories") or {}).get(category) or {} for category in categories_for_percent]
        count_rows = eq_rows.get("counts") or {}
        percent_values = _section_values()
        for section_code in GENERAL_ANALYTICS_SECTION_CODES:
            plan_value = _sum_rows(section_code, category_maps, "plan_total")
            fact_value = _sum_rows(section_code, category_maps, "fact_total")
            actual = 0.0
            for key in ("fact_day", "fact_night"):
                row = _ready_row(count_rows, key)
                if row:
                    actual += float(_read_section_values_at_row(ws, row).get(section_code) or 0)
            percent_values[section_code] = fact_value / plan_value if plan_value > 0 and actual > 0 else 0
        percent_row = _ready_row(count_rows, "percent")
        if percent_row:
            _write_general_percent_values_at_row(ws, percent_row, percent_values)
    return sand_output


def _fill_general_equipment(
    ws,
    report_date: date_cls,
    codes: Optional[list[str]],
    movement_day: dict[str, dict[str, dict[str, float]]],
    plan_day: dict[str, dict[str, dict[str, float]]],
) -> dict[str, float]:
    if _is_ready_general_analytics_template(ws):
        return _fill_ready_general_equipment(ws, report_date, codes, movement_day, plan_day)

    counts = _query_general_equipment_counts(report_date, codes)
    equipment_facts = _query_general_equipment_work_facts(report_date, codes)
    equipment_work_counts = _query_general_equipment_work_counts(report_date, codes)
    equipment_rules = {code: _general_equipment_rule_for_class(code) for code in GENERAL_REPORT_EQUIPMENT_CLASS_CODES}
    _fill_general_equipment_plan_rows(ws, plan_day)

    for eq, day_row, night_row in (
        ("dump_truck", 55, 56),
        ("excavator", 101, 102),
        ("bulldozer", 161, 162),
    ):
        slot = counts.get(eq) or _new_equipment_fact_slot()
        rule = equipment_rules.get(eq)
        _write_section_values(ws, day_row, _general_equipment_slot_values(slot, "day", rule))
        _write_section_values(ws, night_row, _general_equipment_slot_values(slot, "night", rule))
    dump_rule = equipment_rules.get("dump_truck")
    _write_section_values(ws, 82, _general_equipment_slot_values(counts.get("dump_truck") or _new_equipment_fact_slot(), "hired", dump_rule))
    _write_section_values(ws, 83, _general_equipment_slot_values(((equipment_facts.get("dump_truck") or {}).get("SAND") or _new_equipment_fact_slot()), "hired", dump_rule))

    dump_sand_productivity_counts = _query_general_dump_truck_sand_productivity_plan_counts(report_date, codes)
    sand_output = _write_plan_from_counts(
        ws,
        dump_sand_productivity_counts.get("day") or _section_values(),
        dump_sand_productivity_counts.get("night") or _section_values(),
        _sand_pit_norms(),
        67,
        68,
        69,
        total_counts=dump_sand_productivity_counts.get("total") or _section_values(),
    )
    generic_norms = _constant_norms(float(GENERIC_TRUCK_NORM))
    _write_plan_from_counts(
        ws,
        _general_equipment_plan_counts_for_category(equipment_work_counts, "dump_truck", "SCHEBEN", "day", dump_rule),
        _general_equipment_plan_counts_for_category(equipment_work_counts, "dump_truck", "SCHEBEN", "night", dump_rule),
        generic_norms,
        85,
        86,
        87,
    )
    _write_plan_from_counts(
        ws,
        _general_equipment_plan_counts_for_category(equipment_work_counts, "dump_truck", "SHPS", "day", dump_rule),
        _general_equipment_plan_counts_for_category(equipment_work_counts, "dump_truck", "SHPS", "night", dump_rule),
        generic_norms,
        92,
        93,
        94,
    )

    excavator_rule = equipment_rules.get("excavator")
    excavator_norms = {
        "SAND": _constant_norms(_norm_from_settings("экскаватор", ("EMBANKMENT_CONSTRUCTION",), 718.0)),
        "PRS": _constant_norms(_norm_from_settings("экскаватор", ("TOPSOIL_STRIPPING",), 700.0)),
        "VYEMKA": _constant_norms(_norm_from_settings("экскаватор", ("EARTH_EXCAVATION", "PEAT_REMOVAL"), 718.0)),
        "DITCH": _constant_norms(_norm_from_settings("экскаватор", ("DITCH_CONSTRUCTION",), 400.0)),
        "GRADING": _constant_norms(_norm_from_settings("экскаватор", ("AREA_GRADING",), 1018.0)),
    }
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "SAND", "day", excavator_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "SAND", "night", excavator_rule), excavator_norms["SAND"], 112, 113, 114)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "VYEMKA", "day", excavator_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "VYEMKA", "night", excavator_rule), excavator_norms["VYEMKA"], 119, 120, 121)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "DITCH", "day", excavator_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "DITCH", "night", excavator_rule), excavator_norms["DITCH"], 141, 142, 143)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "GRADING", "day", excavator_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "excavator", "GRADING", "night", excavator_rule), excavator_norms["GRADING"], 147, 148, 149)

    bulldozer_rule = equipment_rules.get("bulldozer")
    bulldozer_norms = {
        "PRS": _constant_norms(_norm_from_settings("бульдозер", ("TOPSOIL_STRIPPING",), 800.0)),
        "SHPS": _constant_norms(_norm_from_settings("бульдозер", ("CRUSHED_STONE_PLACEMENT", "FIRST_PROTECTIVE_LAYER"), 1400.0)),
        "SAND": _constant_norms(_norm_from_settings("бульдозер", ("PAVEMENT_SANDING", "EMBANKMENT_CONSTRUCTION"), 1400.0)),
        "VYEMKA": _constant_norms(_norm_from_settings("бульдозер", ("EARTH_EXCAVATION",), 500.0)),
        "GRADING": _constant_norms(_norm_from_settings("бульдозер", ("AREA_GRADING",), 2037.0)),
    }
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "PRS", "day", bulldozer_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "PRS", "night", bulldozer_rule), bulldozer_norms["PRS"], 172, 173, 174)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "SHPS", "day", bulldozer_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "SHPS", "night", bulldozer_rule), bulldozer_norms["SHPS"], 179, 180, 181)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "SAND", "day", bulldozer_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "SAND", "night", bulldozer_rule), bulldozer_norms["SAND"], 186, 187, 188)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "VYEMKA", "day", bulldozer_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "VYEMKA", "night", bulldozer_rule), bulldozer_norms["VYEMKA"], 193, 194, 195)
    _write_plan_from_counts(ws, _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "GRADING", "day", bulldozer_rule), _general_equipment_plan_counts_for_category(equipment_work_counts, "bulldozer", "GRADING", "night", bulldozer_rule), bulldozer_norms["GRADING"], 200, 201, 202)

    equipment_rows = {
        "dump_truck": {"SAND": (70, 71, 72), "SCHEBEN": (88, 89, 90), "SHPS": (95, 96, 97)},
        "excavator": {"SAND": (115, 116, 117), "VYEMKA": (122, 123, 124), "SHPS": (129, 130, 131), "MOVE": (137, 138, 139), "DITCH": (144, 145, 146), "GRADING": (150, 151, 152), "RELATED": (156, 157, 158)},
        "bulldozer": {"PRS": (175, 176, 177), "SHPS": (182, 183, 184), "SAND": (189, 190, 191), "VYEMKA": (196, 197, 198), "GRADING": (203, 204, 205), "RELATED": (209, 210, 211)},
    }
    for eq, categories in equipment_rows.items():
        eq_facts = equipment_facts.get(eq) or {}
        for category, (total_row, day_row, night_row) in categories.items():
            slot = eq_facts.get(category) or _new_equipment_fact_slot()
            rule = equipment_rules.get(eq)
            _write_section_values(ws, total_row, _general_equipment_slot_values(slot, "total", rule))
            _write_section_values(ws, day_row, _general_equipment_slot_values(slot, "day", rule))
            _write_section_values(ws, night_row, _general_equipment_slot_values(slot, "night", rule))

    _write_section_values(ws, 73, (movement_day.get("SAND_PIT_TO_STOCKPILE") or _new_work_fact_slot())["total"])
    _write_section_values(ws, 74, (movement_day.get("SAND_STOCKPILE_TO_CONSTRUCTIVE") or _new_work_fact_slot())["total"])
    _write_section_values(ws, 98, (movement_day.get("SHPS_PIT_TO_STOCKPILE") or _new_work_fact_slot())["hired"])

    dump_percent = _section_values()
    excavator_percent = _section_values()
    bulldozer_percent = _section_values()
    for section_code in GENERAL_ANALYTICS_SECTION_CODES:
        dump_plan = sum((_read_general_section_values(ws, row).get(section_code) or 0) for row in (67, 85, 92))
        dump_fact = sum((_read_general_section_values(ws, row).get(section_code) or 0) for row in (70, 88, 95))
        dump_actual = (_read_general_section_values(ws, 55).get(section_code) or 0) + (_read_general_section_values(ws, 56).get(section_code) or 0)
        dump_percent[section_code] = dump_fact / dump_plan if dump_plan > 0 and dump_actual > 0 else 0

        excavator_plan = sum((_read_general_section_values(ws, row).get(section_code) or 0) for row in (112, 119, 141, 147))
        excavator_fact = sum((_read_general_section_values(ws, row).get(section_code) or 0) for row in (115, 122, 144, 150))
        excavator_actual = (_read_general_section_values(ws, 101).get(section_code) or 0) + (_read_general_section_values(ws, 102).get(section_code) or 0)
        excavator_percent[section_code] = excavator_fact / excavator_plan if excavator_plan > 0 and excavator_actual > 0 else 0

        bulldozer_plan = sum((_read_general_section_values(ws, row).get(section_code) or 0) for row in (172, 179, 186, 193, 200))
        bulldozer_fact = sum((_read_general_section_values(ws, row).get(section_code) or 0) for row in (175, 182, 189, 196, 203))
        bulldozer_actual = (_read_general_section_values(ws, 161).get(section_code) or 0) + (_read_general_section_values(ws, 162).get(section_code) or 0)
        bulldozer_percent[section_code] = bulldozer_fact / bulldozer_plan if bulldozer_plan > 0 and bulldozer_actual > 0 else 0
    _write_general_percent_values(ws, 58, dump_percent)
    _write_general_percent_values(ws, 103, excavator_percent)
    _write_general_percent_values(ws, 163, bulldozer_percent)
    return sand_output

def _length_bucket(data: dict[str, dict[int, dict[str, float]]], kind: str, length: int) -> dict[str, float]:
    return ((data.get(kind) or {}).get(length) or _section_values())


def _find_ready_general_pile_rows(ws) -> dict[str, dict]:
    out: dict[str, dict] = {}
    current_period: Optional[str] = None
    for row_idx in range(1, ws.max_row + 1):
        period = _general_period_key(ws.cell(row=row_idx, column=2).value)
        if period:
            current_period = period
            out.setdefault(period, {"lengths": {"test": {}, "main": {}, "combined": {}}})
            continue
        if not current_period:
            continue
        block = out.setdefault(current_period, {"lengths": {"test": {}, "main": {}, "combined": {}}})
        col2 = ws.cell(row=row_idx, column=2).value
        col3 = ws.cell(row=row_idx, column=3).value
        if "% выполнения" in _normalize_general_label(col3):
            block["percent"] = row_idx
            continue
        if "динамические испытания" in _normalize_general_label(col2):
            block["dyn_plan"] = row_idx
            fact_row = _general_find_fact_row(ws, row_idx, _general_find_next_pile_boundary(ws, row_idx))
            if fact_row:
                block["dyn_fact"] = fact_row
            continue
        kind = _general_pile_block_kind(col2)
        if not kind:
            continue
        boundary = _general_find_next_pile_boundary(ws, row_idx)
        fact_row = _general_find_fact_row(ws, row_idx, boundary)
        block[f"{kind}_plan"] = row_idx
        if fact_row:
            block[f"{kind}_fact"] = fact_row
            for scan_row in range(fact_row + 1, boundary):
                length = _general_length_from_label(ws.cell(row=scan_row, column=4).value)
                if length is not None and length not in block["lengths"][kind]:
                    block["lengths"][kind][length] = scan_row
    return out


def _fill_ready_general_pile_rows(
    ws,
    pile_periods: dict[str, dict],
) -> None:
    pile_rows = _find_ready_general_pile_rows(ws)
    for period_key, rows in pile_rows.items():
        data = pile_periods.get(period_key) or {}
        facts = data.get("facts") or _new_pile_slot()
        plans = data.get("plans") or _new_pile_slot()
        length_facts = data.get("length_facts") or {"main": {}, "test": {}}

        combined_plan = _sum_section_values(plans["main"], plans["test"])
        combined_fact = _sum_section_values(facts["main"], facts["test"])
        for key, values in (
            ("test_plan", plans["test"]),
            ("test_fact", facts["test"]),
            ("dyn_plan", plans["dyn"]),
            ("dyn_fact", facts["dyn"]),
            ("main_plan", plans["main"]),
            ("main_fact", facts["main"]),
            ("combined_plan", combined_plan),
            ("combined_fact", combined_fact),
        ):
            row = rows.get(key)
            if row:
                _write_section_values_at_row(ws, row, values)

        percent_row = rows.get("percent")
        if percent_row:
            percent = _section_values()
            for section_code in GENERAL_ANALYTICS_SECTION_CODES:
                plan_value = float(combined_plan.get(section_code) or 0)
                percent[section_code] = float(combined_fact.get(section_code) or 0) / plan_value if plan_value > 0 else 0
            _write_general_percent_values_at_row(ws, percent_row, percent)

        for kind in ("test", "main", "combined"):
            for length, row in (rows.get("lengths") or {}).get(kind, {}).items():
                _write_section_values_at_row(
                    ws,
                    row,
                    _length_values_for_general_pile_block(length_facts, kind, length),
                )


def _fill_general_pile_rows(
    ws,
    pile_periods: dict[str, dict],
    work_periods: dict[str, dict[str, dict[str, dict[str, float]]]],
) -> None:
    if _is_ready_general_analytics_template(ws):
        _fill_ready_general_pile_rows(ws, pile_periods)
        return
    pile_rows = {
        "day": {"pad_fact": 375, "test_plan": 376, "test_fact": 377, "test_lengths": {9: 378, 10: 379, 12: 380, 16: 381, 21: 382, 24: 383}, "dyn_plan": 386, "dyn_fact": 387, "main_plan": 388, "main_fact": 389, "main_lengths": {10: 390, 11: 391, 12: 392, 16: 393, 20: 394, 21: 395}, "combined_plan": 396, "combined_fact": 397, "combined_lengths": {9: 398, 10: 399, 11: 400, 12: 401, 16: 402, 20: 403, 21: 404, 24: 405}},
        "week": {"pad_fact": 412, "test_plan": 413, "test_fact": 414, "test_lengths": {9: 415, 10: 416, 12: 417, 16: 418, 21: 419, 24: 420}, "dyn_plan": 423, "dyn_fact": 424, "main_plan": 425, "main_fact": 428, "main_lengths": {10: 429, 11: 430, 12: 431, 16: 432, 20: 433, 21: 434}, "combined_plan": 435, "combined_fact": 438, "combined_lengths": {9: 439, 10: 440, 11: 441, 12: 442, 16: 443, 20: 444, 21: 445, 24: 446}},
        "month": {"pad_fact": 453, "test_plan": 454, "test_fact": 455, "test_lengths": {9: 456, 10: 457, 12: 458, 16: 459, 21: 460, 24: 461}, "dyn_plan": 464, "dyn_fact": 465, "main_plan": 466, "main_fact": 469, "main_lengths": {10: 470, 11: 471, 12: 472, 16: 473, 20: 474, 21: 475}, "combined_plan": 476, "combined_fact": 479, "combined_lengths": {9: 480, 10: 481, 11: 482, 12: 483, 16: 484, 20: 485, 21: 486, 24: 487}},
        "total": {"pad_fact": 494, "test_plan": 495, "test_fact": 496, "test_lengths": {9: 497, 10: 498, 12: 499, 16: 500, 20: 501, 21: 502, 24: 503}, "dyn_plan": 506, "dyn_fact": 507, "main_plan": 508, "main_fact": 509, "main_lengths": {10: 510, 11: 511, 12: 512, 16: 513, 20: 514, 21: 515}, "combined_plan": 516, "combined_fact": 517, "combined_lengths": {9: 518, 10: 519, 11: 520, 12: 521, 16: 522, 20: 523, 21: 524, 24: 525}},
    }
    for period_key, rows in pile_rows.items():
        data = pile_periods[period_key]
        facts = data["facts"]
        plans = data["plans"]
        length_facts = data["length_facts"]
        length_plans = data["length_plans"]
        _write_section_values(ws, rows["pad_fact"], _category_bucket(work_periods.get(period_key, {}), "PILE_PAD"))
        _write_section_values(ws, rows["test_plan"], plans["test"])
        _write_section_values(ws, rows["test_fact"], facts["test"])
        _write_section_values(ws, rows["dyn_plan"], plans["dyn"])
        _write_section_values(ws, rows["dyn_fact"], facts["dyn"])
        _write_section_values(ws, rows["main_plan"], plans["main"])
        _write_section_values(ws, rows["main_fact"], facts["main"])
        _write_section_values(ws, rows["combined_plan"], _sum_section_values(plans["main"], plans["test"]))
        _write_section_values(ws, rows["combined_fact"], _sum_section_values(facts["main"], facts["test"]))
        for length, source_row in rows["test_lengths"].items():
            _write_section_values(ws, source_row, _length_bucket(length_facts, "test", length))
        for length, source_row in rows["main_lengths"].items():
            _write_section_values(ws, source_row, _length_bucket(length_facts, "main", length))
        for length, source_row in rows["combined_lengths"].items():
            _write_section_values(
                ws,
                source_row,
                _sum_section_values(
                    _length_bucket(length_facts, "main", length),
                    _length_bucket(length_facts, "test", length),
                ),
            )




GENERAL_EXCLUDED_PILE_ROW_NEEDLES = (
    "устройство стартовых площадок",
    "работы по стыковке и сварке свай",
    "фактическое количество кран",
    "фактическое количество сваебойная установка",
)


def _is_general_excluded_pile_row(ws, row_idx: int) -> bool:
    text = " ".join(str(ws.cell(row=row_idx, column=col).value or "") for col in (2, 3, 4)).lower().replace("ё", "е")
    return any(needle in text for needle in GENERAL_EXCLUDED_PILE_ROW_NEEDLES)


def _delete_general_excluded_pile_rows(ws) -> list[int]:
    """Hide rows that are excluded from the server pile report.

    Keep the XLSX template geometry intact: deleting crane / pile-driving-rig
    rows shifts conditional-formatting ranges and makes the percent row look as
    if sparklines/data bars appeared on pile fact rows.  The owner wants a full
    template repeat, so excluded rows are hidden, not physically deleted.
    """
    hidden_rows: list[int] = []
    for row_idx in range(1, ws.max_row + 1):
        if _is_general_excluded_pile_row(ws, row_idx):
            ws.row_dimensions[row_idx].hidden = True
            hidden_rows.append(row_idx)
    return sorted(set(hidden_rows))


def _clear_general_pile_row_hidden_flags(ws) -> None:
    """Clear stale template hidden flags, but keep intentionally excluded rows hidden."""
    first_pile_period_row = _first_general_pile_period_row(ws)
    if first_pile_period_row is None:
        return
    for row_idx in range(first_pile_period_row, ws.max_row + 1):
        if not _is_general_excluded_pile_row(ws, row_idx):
            ws.row_dimensions[row_idx].hidden = False


GENERAL_PILE_LENGTH_NOMENCLATURE = tuple(range(7, 29))


def _normalize_general_label(value: object) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip().lower().replace("ё", "е"))


def _general_pile_block_kind(label: object) -> Optional[str]:
    text = _normalize_general_label(label)
    if not text:
        return None
    if "погружено пробных свай" in text:
        return "test"
    if "погружено свай" in text and "пробные" in text and "основные" in text:
        return "combined"
    if "погружено свай" in text:
        return "main"
    return None


def _general_period_key(label: object) -> Optional[str]:
    text = _normalize_general_label(label)
    if text == "текущий день":
        return "day"
    if text == "текущая неделя":
        return "week"
    if text == "текущий месяц":
        return "month"
    if text == "накопительным итогом":
        return "total"
    return None


def _general_length_from_label(label: object) -> Optional[int]:
    match = re.search(r"факт\s+(\d{1,2})\s*м", _normalize_general_label(label))
    return int(match.group(1)) if match else None


def _general_find_next_pile_boundary(ws, start_row: int) -> int:
    for row_idx in range(start_row + 1, ws.max_row + 1):
        if _general_period_key(ws.cell(row=row_idx, column=2).value):
            return row_idx
        if _general_pile_block_kind(ws.cell(row=row_idx, column=2).value):
            return row_idx
    return ws.max_row + 1


def _general_find_fact_row(ws, block_row: int, boundary_row: int) -> Optional[int]:
    for row_idx in range(block_row + 1, boundary_row):
        if _normalize_general_label(ws.cell(row=row_idx, column=4).value).startswith("факт"):
            return row_idx
    return None


def _general_find_period_for_row(ws, row_idx: int) -> Optional[str]:
    for scan_row in range(row_idx, 0, -1):
        period = _general_period_key(ws.cell(row=scan_row, column=2).value)
        if period:
            return period
    return None


def _length_values_for_general_pile_block(length_facts: dict[str, dict[int, dict[str, float]]], kind: str, length: int) -> dict[str, float]:
    if kind == "test":
        return _length_bucket(length_facts, "test", length)
    if kind == "main":
        return _length_bucket(length_facts, "main", length)
    return _sum_section_values(
        _length_bucket(length_facts, "main", length),
        _length_bucket(length_facts, "test", length),
    )


def _style_general_pseudo_merged_range(ws, min_row: int, min_col: int, max_row: int, max_col: int) -> None:
    if min_row < 1 or min_col < 1 or min_row > ws.max_row:
        return
    max_row = min(max_row, ws.max_row)
    if max_row < min_row or max_col < min_col:
        return
    source = ws.cell(row=min_row, column=min_col)
    value = source.value
    font = copy(source.font)
    fill = copy(source.fill)
    number_format = source.number_format
    protection = copy(source.protection)
    base_border = copy(source.border)
    empty_side = Side(style=None)
    alignment = Alignment(
        horizontal=source.alignment.horizontal or "center",
        vertical="center",
        text_rotation=source.alignment.textRotation or 0,
        wrap_text=True,
    )
    for row_idx in range(min_row, max_row + 1):
        for col_idx in range(min_col, max_col + 1):
            cell = ws.cell(row=row_idx, column=col_idx)
            cell.value = value if row_idx == min_row and col_idx == min_col else None
            cell.font = copy(font)
            cell.fill = copy(fill)
            cell.number_format = number_format
            cell.protection = copy(protection)
            cell.alignment = copy(alignment)
            cell.border = Border(
                left=copy(base_border.left) if col_idx == min_col else copy(empty_side),
                right=copy(base_border.right) if col_idx == max_col else copy(empty_side),
                top=copy(base_border.top) if row_idx == min_row else copy(empty_side),
                bottom=copy(base_border.bottom) if row_idx == max_row else copy(empty_side),
            )


def _style_general_pseudo_merged_ranges(ws, ranges: list[tuple[int, int, int, int]]) -> None:
    for min_row, min_col, max_row, max_col in ranges:
        _style_general_pseudo_merged_range(ws, min_row, min_col, max_row, max_col)


def _adjust_general_ranges_after_deleted_rows(
    ranges: list[tuple[int, int, int, int]],
    deleted_rows: list[int],
) -> list[tuple[int, int, int, int]]:
    deleted = sorted(set(deleted_rows))
    if not deleted:
        return ranges
    adjusted: list[tuple[int, int, int, int]] = []
    for min_row, min_col, max_row, max_col in ranges:
        new_min = min_row - sum(1 for row_idx in deleted if row_idx < min_row)
        new_max = max_row - sum(1 for row_idx in deleted if row_idx <= max_row)
        if new_max >= new_min:
            adjusted.append((new_min, min_col, new_max, max_col))
    return adjusted


def _first_general_pile_period_row(ws) -> Optional[int]:
    """Find the first period label that belongs to the pile section.

    The template repeats period labels in earlier earthwork/equipment blocks too.
    Only the pile period area may be temporarily unmerged before deleting
    crane/rig rows and zero pile-length rows.
    """
    excluded_needles = (
        "фактическое количество кран",
        "фактическое количество сваебойная установка",
    )
    row_idx = 1
    while row_idx <= ws.max_row:
        if not _general_period_key(ws.cell(row=row_idx, column=2).value):
            row_idx += 1
            continue
        next_period = ws.max_row + 1
        for scan_row in range(row_idx + 1, ws.max_row + 1):
            if _general_period_key(ws.cell(row=scan_row, column=2).value):
                next_period = scan_row
                break
        for scan_row in range(row_idx + 1, next_period):
            label = ws.cell(row=scan_row, column=2).value
            normalized = _normalize_general_label(label)
            if _general_pile_block_kind(label) or any(needle in normalized for needle in excluded_needles):
                return row_idx
        row_idx = next_period
    return None


def _unmerge_general_pile_block_label_cells(ws) -> list[tuple[int, int, int, int]]:
    first_pile_period_row = _first_general_pile_period_row(ws)
    if first_pile_period_row is None:
        return []
    unmerged_ranges: list[tuple[int, int, int, int]] = []
    for merged in list(ws.merged_cells.ranges):
        if merged.max_row >= first_pile_period_row and merged.min_col >= 2 and merged.max_col <= 4:
            coords = (merged.min_row, merged.min_col, merged.max_row, merged.max_col)
            ws.unmerge_cells(str(merged))
            unmerged_ranges.append(coords)
    return unmerged_ranges


def _restore_general_pile_block_label_cells(ws, ranges: list[tuple[int, int, int, int]]) -> None:
    for min_row, min_col, max_row, max_col in ranges:
        if min_row < 1 or min_col < 1 or max_row < min_row or max_col < min_col:
            continue
        if min_row == max_row and min_col == max_col:
            continue
        max_row = min(max_row, ws.max_row)
        try:
            ws.merge_cells(start_row=min_row, start_column=min_col, end_row=max_row, end_column=max_col)
        except ValueError:
            continue


def _copy_general_cell_visuals(src, dst) -> None:
    if src.has_style:
        dst._style = copy(src._style)
    dst.font = copy(src.font)
    dst.fill = copy(src.fill)
    dst.border = copy(src.border)
    dst.alignment = copy(src.alignment)
    dst.number_format = src.number_format
    dst.protection = copy(src.protection)


def _visible_row_runs(min_row: int, max_row: int, hidden_rows: set[int]) -> list[tuple[int, int]]:
    runs: list[tuple[int, int]] = []
    current_start: Optional[int] = None
    previous_visible: Optional[int] = None
    for row_idx in range(min_row, max_row + 1):
        if row_idx in hidden_rows:
            if current_start is not None and previous_visible is not None:
                runs.append((current_start, previous_visible))
                current_start = None
            previous_visible = None
            continue
        if current_start is None:
            current_start = row_idx
        previous_visible = row_idx
    if current_start is not None and previous_visible is not None:
        runs.append((current_start, previous_visible))
    return runs


def _split_general_pile_label_merges_around_hidden_rows(ws, hidden_rows: list[int]) -> None:
    """Do not let real B/C pile merges cross hidden zero-length rows.

    Excel/LibreOffice can render a vertical merged cell oddly when most of its
    member rows are hidden.  Keep the zero pile rows hidden (not deleted), but
    split only the left B/C pile labels into visible contiguous runs.  This is
    the safe compromise for the left side of the table: no real merge spans a
    hidden row, while the block label and the `Объем` label remain readable.
    """
    first_pile_period_row = _first_general_pile_period_row(ws)
    if first_pile_period_row is None or not hidden_rows:
        return
    hidden = set(hidden_rows)
    for merged in list(ws.merged_cells.ranges):
        if merged.min_row < first_pile_period_row:
            continue
        if merged.min_col != merged.max_col or merged.min_col not in (2, 3):
            continue
        if not any(merged.min_row <= row_idx <= merged.max_row for row_idx in hidden):
            continue
        min_row, max_row, col_idx = merged.min_row, min(merged.max_row, ws.max_row), merged.min_col
        source = ws.cell(row=min_row, column=col_idx)
        label = source.value
        source_visual = ws.cell(row=min_row, column=col_idx)
        try:
            ws.unmerge_cells(str(merged))
        except ValueError:
            continue
        for row_idx in range(min_row, max_row + 1):
            cell = ws.cell(row=row_idx, column=col_idx)
            _copy_general_cell_visuals(source_visual, cell)
            cell.value = None
        for run_start, run_end in _visible_row_runs(min_row, max_row, hidden):
            top = ws.cell(row=run_start, column=col_idx)
            _copy_general_cell_visuals(source_visual, top)
            top.value = label
            if run_end > run_start:
                try:
                    ws.merge_cells(start_row=run_start, start_column=col_idx, end_row=run_end, end_column=col_idx)
                except ValueError:
                    pass


def _insert_general_rows_preserving_block_merges(ws, row_idx: int, amount: int = 1) -> None:
    """Insert rows inside a general-report block and expand its B/C vertical merges.

    openpyxl shifts merged ranges after insertion but does not reliably expand a
    merge when rows are inserted inside it.  The pile blocks use B and C vertical
    merges for the block label and "Объем" column, so expand those ranges
    explicitly before adding missing length nomenclature rows.
    """
    affected: list[tuple[int, int, int]] = []
    for merged in list(ws.merged_cells.ranges):
        if merged.min_col != merged.max_col or merged.min_col not in (2, 3):
            continue
        if merged.min_row <= row_idx <= merged.max_row + 1:
            affected.append((merged.min_col, merged.min_row, merged.max_row))
            ws.unmerge_cells(str(merged))
    ws.insert_rows(row_idx, amount)
    for col_idx, min_row, max_row in affected:
        ws.merge_cells(start_row=min_row, start_column=col_idx, end_row=max_row + amount, end_column=col_idx)


def _ensure_general_pile_length_nomenclature(ws, pile_periods: dict[str, dict]) -> None:
    """Keep all pile length rows inside every pile fact block.

    Older code appended missing/unknown pile lengths at the bottom of the sheet,
    which visually put new rows under the cumulative-total area.  The owner wants
    each repeated block (day/week/month/total × test/main/combined) to carry the
    same complete nomenclature in-place.
    """
    row_idx = 1
    while row_idx <= ws.max_row:
        kind = _general_pile_block_kind(ws.cell(row=row_idx, column=2).value)
        if not kind:
            row_idx += 1
            continue
        period_key = _general_find_period_for_row(ws, row_idx)
        boundary = _general_find_next_pile_boundary(ws, row_idx)
        fact_row = _general_find_fact_row(ws, row_idx, boundary)
        if not period_key or not fact_row:
            row_idx += 1
            continue

        existing: dict[int, int] = {}
        style_source = fact_row
        for scan_row in range(fact_row + 1, boundary):
            length = _general_length_from_label(ws.cell(row=scan_row, column=4).value)
            if length is None:
                continue
            existing.setdefault(length, scan_row)
            style_source = scan_row

        insert_at = fact_row + 1
        for length in GENERAL_PILE_LENGTH_NOMENCLATURE:
            current_row = existing.get(length)
            if current_row is None:
                _insert_general_rows_preserving_block_merges(ws, insert_at, 1)
                _copy_general_row_style(ws, style_source, insert_at)
                _set_general_cell_value(ws, insert_at, 2, None)
                _set_general_cell_value(ws, insert_at, 3, None)
                _set_general_cell_value(ws, insert_at, 4, f"факт {length} м")
                for known_length, known_row in list(existing.items()):
                    if known_row >= insert_at:
                        existing[known_length] = known_row + 1
                existing[length] = insert_at
                boundary += 1
                style_source = insert_at
                current_row = insert_at
            values = _length_values_for_general_pile_block(
                (pile_periods.get(period_key) or {}).get("length_facts") or {},
                kind,
                length,
            )
            _write_section_values_at_row(ws, current_row, values)
            insert_at = current_row + 1
        row_idx = boundary


def _hide_zero_or_duplicate_general_pile_length_rows(ws) -> list[int]:
    """Hide pile-length fact rows whose generated fact is zero.

    Ready XLSX templates are owner-controlled visual layouts.  Do not delete
    rows, do not hide duplicate non-zero lengths, and do not split/rebuild
    merges here: the only allowed structural visibility change in length rows is
    hiding rows where all fact cells E:M are zero/empty after the data fill.

    The final owner template contains repeated pile blocks without a stable
    merged label in column B on every block start, so detection is intentionally
    row-local: any row labeled like ``факт 7 м`` in column D is a pile-length fact
    row and is hidden only when E:M are all zero.
    """
    rows_to_hide: list[int] = []
    for row_idx in range(1, ws.max_row + 1):
        length = _general_length_from_label(ws.cell(row=row_idx, column=4).value)
        if length is None:
            continue
        values = []
        for col_idx in range(GENERAL_ANALYTICS_VALUE_START_COL, 14):
            raw = ws.cell(row=row_idx, column=col_idx).value
            try:
                values.append(float(raw or 0))
            except (TypeError, ValueError):
                values.append(0.0)
        if all(abs(value) < 0.0005 for value in values):
            rows_to_hide.append(row_idx)
    hidden_rows = sorted(set(rows_to_hide))
    for row_idx in hidden_rows:
        ws.row_dimensions[row_idx].hidden = True
    return hidden_rows


def _delete_zero_or_duplicate_general_pile_length_rows(ws) -> list[int]:
    """Compatibility wrapper: empty pile-length rows are hidden, not deleted."""
    return _hide_zero_or_duplicate_general_pile_length_rows(ws)


def _general_print_area_max_row(ws) -> Optional[int]:
    area = str(ws.print_area or "")
    match = re.search(r":\$?[A-Z]+\$?(\d+)", area)
    if not match:
        return None
    try:
        return int(match.group(1))
    except (TypeError, ValueError):
        return None


GENERAL_ANALYTICS_PDF_ROW_BREAKS: tuple[int, ...] = ()


def _clear_general_page_breaks(ws) -> None:
    for breaks in (ws.row_breaks, ws.col_breaks):
        try:
            breaks.brk = []
        except AttributeError:
            pass


def _configure_general_pdf_layout(ws, max_row: int, max_col: str) -> None:
    _clear_general_page_breaks(ws)
    for row_idx in GENERAL_ANALYTICS_PDF_ROW_BREAKS:
        if 1 < row_idx < max_row:
            ws.row_breaks.append(Break(id=row_idx))
    ws.print_area = f"A1:{max_col}{max_row}"
    ws.page_setup.orientation = ws.ORIENTATION_PORTRAIT
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.page_margins.left = 0.1
    ws.page_margins.right = 0.1
    ws.page_margins.top = 0.18
    ws.page_margins.bottom = 0.18
    try:
        ws.sheet_properties.pageSetUpPr.fitToPage = True
        ws.print_options.horizontalCentered = True
    except AttributeError:
        pass


def _general_pile_plan_period(period_key: str, period_from: date_cls, period_to: date_cls) -> tuple[date_cls, date_cls]:
    """Return the planning horizon for ready-template pile blocks.

    Facts remain period-to-date, but the owner-facing pile rows should show the
    full ISO week / calendar-month plan, not just Monday- or month-start to the
    report date. Otherwise a Monday report makes the week plan equal the day
    plan, and a mid-month report truncates the monthly pile plan even though the
    DB already contains the remaining scheduled rows.
    """
    if period_key == "week":
        return period_from, period_from + timedelta(days=6)
    if period_key == "month":
        next_month = (period_from.replace(day=28) + timedelta(days=4)).replace(day=1)
        return period_from, next_month - timedelta(days=1)
    return period_from, period_to


def _build_general_analytics_workbook(
    report_date: date_cls,
    codes: Optional[list[str]],
    manual_equipment_plan_counts: Optional[dict[str, dict[str, dict[str, float]]]] = None,
) -> bytes:
    template_path = _resolve_general_analytics_template()
    if not template_path.exists():
        raise HTTPException(503, f"Шаблон Генерального отчета не найден: {template_path}")
    try:
        wb = load_workbook(template_path)
    except Exception as exc:
        raise HTTPException(500, f"Не удалось открыть шаблон Генерального отчета: {exc}") from exc
    if "Аналитика" not in wb.sheetnames:
        raise HTTPException(500, "В шаблоне Генерального отчета нет листа Аналитика")
    ws = wb["Аналитика"]
    ready_template = _is_ready_general_analytics_template(ws)
    template_print_max_row = _general_print_area_max_row(ws)
    _restore_general_analysis_rows(ws)
    if not ready_template:
        _trim_general_analysis_sheet(ws)
    dump_truck_defaults = _read_general_dump_truck_defaults(ws)
    _blank_general_value_cells(ws)
    _rewrite_general_report_dates(ws, report_date)

    periods = _general_periods(report_date)
    work_periods = {
        key: _query_general_work_facts(period_from, period_to, codes)
        for key, (period_from, period_to) in periods.items()
    }
    movement_periods = {
        key: _query_general_movement_facts(period_from, period_to, codes)
        for key, (period_from, period_to) in periods.items()
    }
    movement_periods.setdefault("total", {})["SAND_DASHBOARD_SITE_DELIVERED"] = _query_general_dashboard_sand_haul_facts(
        PROJECT_START_DATE,
        report_date,
        codes,
    )
    movement_periods.setdefault("total", {})["SHPGS_DASHBOARD_SITE_DELIVERED"] = _query_general_dashboard_shpgs_delivery_facts(
        PROJECT_START_DATE,
        report_date,
        codes,
    )
    plan_periods = _query_general_volume_plan_periods(report_date, codes)
    pile_periods = {}
    for key, (period_from, period_to) in periods.items():
        plan_from, plan_to = _general_pile_plan_period(key, period_from, period_to)
        pile_periods[key] = _query_general_pile_data(
            period_from,
            period_to,
            codes,
            plan_from=plan_from,
            plan_to=plan_to,
        )

    _write_general_top_quarry_table(ws, report_date, codes, work_periods, movement_periods)
    _fill_general_dump_truck_metadata(ws, report_date, codes, dump_truck_defaults)
    current_day_sand_output = _fill_general_equipment(
        ws,
        report_date,
        codes,
        movement_periods.get("day", {}),
        plan_periods.get("day", {}),
    )
    if ready_template:
        _write_ready_general_manual_equipment_count_rows(ws, manual_equipment_plan_counts)
    _fill_general_volume_summary(
        ws,
        work_periods,
        plan_periods,
        movement_periods,
        current_day_sand_output,
    )
    _fill_general_pile_rows(ws, pile_periods, work_periods)
    _delete_general_excluded_pile_rows(ws)
    _clear_general_pile_row_hidden_flags(ws)
    _hide_zero_or_duplicate_general_pile_length_rows(ws)

    # PDF must cover the whole generated report.  Keep notes/metadata columns O:R visible
    # in XLSX, but exclude them from PDF by printing only A:M across all rows.
    _configure_general_pdf_layout(ws, ws.max_row, "M")
    try:
        wb.calculation.fullCalcOnLoad = True
        wb.calculation.forceFullCalc = True
    except AttributeError:
        pass

    bio = BytesIO()
    wb.save(bio)
    return bio.getvalue()


def _export_xlsx_bytes_to_pdf(xlsx_bytes: bytes, stem: str) -> bytes:
    with tempfile.TemporaryDirectory(prefix="vsm-general-analytics-") as tmp_dir:
        tmp_path = Path(tmp_dir)
        xlsx_path = tmp_path / f"{stem}.xlsx"
        out_dir = tmp_path / "pdf"
        profile_dir = tmp_path / "lo-profile"
        out_dir.mkdir()
        profile_dir.mkdir()
        xlsx_path.write_bytes(xlsx_bytes)
        cmd = [
            REPORT_LIBREOFFICE_BIN,
            "--headless",
            "--nologo",
            "--nofirststartwizard",
            f"-env:UserInstallation=file://{profile_dir}",
            "--convert-to",
            "pdf:calc_pdf_Export",
            "--outdir",
            str(out_dir),
            str(xlsx_path),
        ]
        try:
            proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=180, check=False)
        except FileNotFoundError as exc:
            raise HTTPException(503, f"PDF-экспорт недоступен: LibreOffice не найден ({REPORT_LIBREOFFICE_BIN})") from exc
        except subprocess.TimeoutExpired as exc:
            raise HTTPException(504, "PDF-экспорт Генерального отчета превысил лимит времени") from exc
        if proc.returncode != 0:
            detail = (proc.stderr or proc.stdout or "LibreOffice вернул ошибку").strip()[-1000:]
            raise HTTPException(500, f"Не удалось собрать PDF Генерального отчета: {detail}")
        pdf_path = out_dir / f"{stem}.pdf"
        if not pdf_path.exists():
            matches = list(out_dir.glob("*.pdf"))
            if not matches:
                raise HTTPException(500, "LibreOffice не создал PDF Генерального отчета")
            pdf_path = matches[0]
        return pdf_path.read_bytes()


def _generate_general_analytics_main_table_report(
    report_date: date_cls,
    codes: Optional[list[str]],
    report_format: str,
    manual_equipment_plan_counts: Optional[dict[str, dict[str, dict[str, float]]]] = None,
) -> tuple[bytes, str, str]:
    xlsx_bytes = _build_general_analytics_workbook(
        report_date,
        codes,
        manual_equipment_plan_counts=manual_equipment_plan_counts,
    )
    date_ascii = report_date.isoformat()
    date_label = _general_date_label(report_date)
    if report_format == "xlsx":
        return (
            xlsx_bytes,
            f"VSM_General_Analytics_{date_ascii}.xlsx",
            f"Генеральный отчет - Аналитика {date_label}.xlsx",
        )
    if report_format != "pdf":
        raise HTTPException(400, f"Unsupported General report format: {report_format}")
    pdf_bytes = _export_xlsx_bytes_to_pdf(xlsx_bytes, f"general_analytics_{date_ascii}")
    return (
        pdf_bytes,
        f"VSM_General_Analytics_{date_ascii}.pdf",
        f"Генеральный отчет - Аналитика {date_label}.pdf",
    )

def _equipment_status_label(status: Optional[str]) -> str:
    labels = {
        "working": "в работе",
        "repair": "ремонт",
        "standby": "простой",
        "out": "вне работы",
        "unknown": "не указан",
    }
    code = (status or "").strip().lower()
    return labels.get(code, status or "не указан")


def _equipment_bucket_label(bucket: Optional[str]) -> str:
    labels = {
        "working": "работа",
        "repair": "ремонт",
        "idle": "простой",
    }
    return labels.get(bucket or "", bucket or "не указан")


def _join_distinct(*values: object) -> str:
    seen: set[str] = set()
    out: list[str] = []
    for value in values:
        if value is None:
            continue
        parts = str(value).split(";")
        for part in parts:
            clean = part.strip()
            if not clean or clean in seen:
                continue
            seen.add(clean)
            out.append(clean)
    return "; ".join(out)


def _format_section_label(code: Optional[str]) -> str:
    merged = _merge_section(code) or code
    if not merged:
        return "—"
    if merged.startswith("UCH_"):
        return f"№{merged.replace('UCH_', '')}"
    return merged


def _equipment_report_clean_contractor(value: Optional[str]) -> str:
    text = str(value or "").strip()
    text = re.sub(r"\s*/\s*плечо\b.*$", "", text, flags=re.I).strip()
    text = re.sub(r"\s*/\s*(?:\d+(?:[.,]\d+)?\s*)?(?:м\s*)?км\s*$", "", text, flags=re.I).strip()
    text = re.sub(r"\s+", " ", text)
    aliases = {
        "алмаз": "Алмаз",
        "ждс": "ЖДС",
    }
    return aliases.get(text.lower(), text)


def _equipment_report_is_hired(row: dict) -> bool:
    ownership = str(row.get("ownership_type") or "").strip().lower()
    contractor = _equipment_report_clean_contractor(row.get("contractor_name") or row.get("contractor"))
    return ownership == "hired" or (contractor and contractor.lower() not in {"ждс", "желдорстрой", "ооо ждс", "ооо \"ждс\""})


def _split_evenly_numeric(value: object, parts: int, index: int, *, decimals: int = 2) -> float:
    if parts <= 1:
        return round(float(value or 0), decimals)
    scale = 10 ** decimals
    total_units = int(round(float(value or 0) * scale))
    base, remainder = divmod(total_units, parts)
    current = base + (remainder if index == 0 else 0)
    return round(current / scale, decimals)


def _split_evenly_int(value: object, parts: int, index: int) -> int:
    if parts <= 1:
        return int(value or 0)
    total = int(round(float(value or 0)))
    base, remainder = divmod(total, parts)
    return base + (remainder if index == 0 else 0)


def _equipment_report_detail_signature(row: dict, fields: tuple[str, ...]) -> tuple:
    return tuple(str(row.get(field) or "") for field in fields)


def _equipment_report_group_key(row: dict) -> tuple:
    return (
        row.get("report_date"),
        row.get("shift"),
        _merge_section(row.get("section_code")) or row.get("section_code") or "—",
        str(row.get("equipment_type") or "").strip().lower(),
        _equipment_report_clean_contractor(row.get("contractor_name")),
        str(row.get("status") or "").strip().lower(),
    )


def _equipment_report_summary_unit_key(row: dict) -> str:
    master_id = str(row.get("equipment_unit_id") or "").strip()
    if master_id:
        return f"master:{master_id}"
    plate = _normalize_equipment_identifier(row.get("plate_number"))
    if plate:
        return f"plate:{plate}"
    unit = _normalize_equipment_identifier(row.get("unit_number"))
    if unit:
        return f"unit:{unit}"
    report_id = str(row.get("report_equipment_unit_id") or "").strip()
    if report_id:
        return f"report:{report_id}"
    return "|".join([
        str(row.get("equipment_type") or ""),
        str(row.get("brand_model") or ""),
        str(row.get("contractor") or row.get("contractor_name") or ""),
    ])


EQUIPMENT_REPORT_MECHANIZATION_ONLY_OBJECTS = "По данным механизации единица техники работает на участке"


def _equipment_report_unit_identity(row: dict) -> str:
    master_id = str(row.get("equipment_unit_id") or "").strip()
    if master_id:
        return f"master:{master_id}"
    plate = _normalize_equipment_identifier(row.get("plate_number"))
    if plate:
        return f"plate:{plate}"
    unit = _normalize_equipment_identifier(row.get("unit_number"))
    if unit:
        return f"unit:{unit}"
    return ""


def _equipment_report_same_shift_unit_key(row: dict) -> tuple | None:
    unit_key = _equipment_report_unit_identity(row)
    if not unit_key:
        return None
    return (
        row.get("report_date"),
        str(row.get("shift") or ""),
        _merge_section(row.get("section_code")) or row.get("section_code") or "—",
        unit_key,
    )


def _equipment_report_is_mechanization_snapshot(row: dict) -> bool:
    return str(row.get("source_type") or "").strip() == "mechanization_report_m"


def _enrich_equipment_report_master_fields(base_rows: list[dict]) -> None:
    normalized_values = sorted({
        value
        for row in base_rows
        for value in (
            _normalize_equipment_identifier(row.get("plate_number")),
            _normalize_equipment_identifier(row.get("unit_number")),
        )
        if value
    })
    if not normalized_values:
        return
    try:
        master_rows = query(
            """
            SELECT eui.normalized_value,
                   eu.id::text AS equipment_unit_id,
                   eu.equipment_type,
                   eu.brand_model,
                   eu.unit_number,
                   eu.plate_number,
                   eu.ownership_type,
                   eu.contractor_name
            FROM equipment_unit_identifiers eui
            JOIN equipment_units eu ON eu.id = eui.equipment_unit_id
            WHERE eui.normalized_value = ANY(%s)
              AND COALESCE(eu.is_active, true) IS TRUE
            ORDER BY eu.updated_at DESC NULLS LAST, eu.created_at DESC NULLS LAST
            """,
            [normalized_values],
        )
    except Exception:
        return
    grouped: dict[str, list[dict]] = {}
    for row in master_rows:
        grouped.setdefault(str(row.get("normalized_value") or ""), []).append(row)
    unique_by_norm = {
        norm: rows[0]
        for norm, rows in grouped.items()
        if len({str(row.get("equipment_unit_id") or "") for row in rows if row.get("equipment_unit_id")}) == 1
    }
    for row in base_rows:
        master = None
        for value in (
            _normalize_equipment_identifier(row.get("plate_number")),
            _normalize_equipment_identifier(row.get("unit_number")),
        ):
            master = unique_by_norm.get(value)
            if master:
                break
        if not master:
            continue
        row["equipment_unit_id"] = row.get("equipment_unit_id") or master.get("equipment_unit_id")
        for key in ("equipment_type", "brand_model", "unit_number", "plate_number", "ownership_type", "contractor_name"):
            if not str(row.get(key) or "").strip() and master.get(key):
                row[key] = master.get(key)


def _query_equipment_report_rows(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> list[dict]:
    base_where = [
        "dr.report_date BETWEEN %s AND %s",
        "reu.is_demo IS NOT TRUE",
        "COALESCE(dr.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review')",
        _non_pile_control_report_condition("dr"),
    ]
    base_params: list = [d_from, d_to]
    if codes:
        base_where.append("cs.code = ANY(%s)")
        base_params.append(codes)

    base_rows = query(
        f"""
        SELECT reu.id::text AS report_equipment_unit_id,
               reu.equipment_unit_id::text AS equipment_unit_id,
               dr.report_date,
               LOWER(COALESCE(dr.shift, 'day')) AS shift,
               COALESCE(dr.source_type, '') AS source_type,
               cs.code AS section_code,
               COALESCE(reu.equipment_type, eu.equipment_type, 'техника') AS equipment_type,
               COALESCE(NULLIF(reu.brand_model, ''), eu.brand_model, '') AS brand_model,
               COALESCE(NULLIF(reu.unit_number, ''), eu.unit_number, '') AS unit_number,
               COALESCE(NULLIF(reu.plate_number, ''), eu.plate_number, '') AS plate_number,
               COALESCE(NULLIF(reu.ownership_type, ''), eu.ownership_type, 'unknown') AS ownership_type,
               COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '') AS contractor_name,
               COALESCE(NULLIF(reu.status, ''), eu.status, 'unknown') AS status,
               COALESCE(NULLIF(reu.comment, ''), eu.comment, '') AS comment
        FROM report_equipment_units reu
        JOIN daily_reports dr ON dr.id = reu.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = dr.section_id
        LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
        LEFT JOIN contractors c ON c.id = reu.contractor_id
        WHERE {' AND '.join(base_where)}
        ORDER BY dr.report_date, cs.sort_order NULLS LAST, cs.code, reu.equipment_type, reu.unit_number, reu.plate_number
        """,
        base_params,
    )

    usage_where = [
        "dwi.report_date BETWEEN %s AND %s",
        "dwi.is_demo IS NOT TRUE",
        _approved_report_exists("dwi"),
    ]
    usage_params: list = [d_from, d_to]
    if codes:
        usage_where.append("cs.code = ANY(%s)")
        usage_params.append(codes)
    work_rows = query(
        f"""
        SELECT wieu.report_equipment_unit_id::text AS eq_id,
               COALESCE(obj.name, 'Без объекта') AS work_objects,
               COALESCE(wt.name, dwi.work_name_raw, 'Работа') AS work_names,
               SUM(COALESCE(wieu.worked_volume, dwi.volume, 0))::numeric AS work_volume,
               SUM(COALESCE(wieu.trips_count, 0))::int AS work_trips
        FROM work_item_equipment_usage wieu
        JOIN daily_work_items dwi ON dwi.id = wieu.daily_work_item_id
        JOIN daily_reports dr_work ON dr_work.id = dwi.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(dwi.section_id, dr_work.section_id)
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN work_types wt ON wt.id = dwi.work_type_id
        WHERE {' AND '.join(usage_where)}
        GROUP BY wieu.report_equipment_unit_id, 2, 3
        ORDER BY wieu.report_equipment_unit_id::text, 2, 3
        """,
        usage_params,
    )
    work_by_eq: dict[str, list[dict]] = {}
    for r in work_rows:
        work_by_eq.setdefault(str(r["eq_id"]), []).append(r)

    movement_where = [
        "mm.report_date BETWEEN %s AND %s",
        "mm.is_demo IS NOT TRUE",
        "mmeu.is_demo IS NOT TRUE",
        _approved_report_exists("mm"),
    ]
    movement_params: list = [d_from, d_to]
    if codes:
        movement_where.append("cs.code = ANY(%s)")
        movement_params.append(codes)
    movement_rows = query(
        f"""
        SELECT mmeu.report_equipment_unit_id::text AS eq_id,
               CONCAT_WS(' → ', NULLIF(src.name, ''), NULLIF(dst.name, '')) AS movement_routes,
               COALESCE(NULLIF(mat.name, ''), mat.code, 'материал') AS material_names,
               COALESCE(mm.movement_type, '') AS movement_types,
               SUM(COALESCE(mmeu.worked_volume, mm.volume, 0))::numeric AS movement_volume,
               SUM(COALESCE(mmeu.trips_count, mm.trip_count, 0))::int AS movement_trips,
               CASE
                 WHEN SUM(CASE WHEN COALESCE(mm.haul_distance_km, h.distance_km) IS NOT NULL THEN COALESCE(mmeu.worked_volume, mm.volume, 0) ELSE 0 END) > 0
                 THEN SUM(COALESCE(mmeu.worked_volume, mm.volume, 0) * COALESCE(mm.haul_distance_km, h.distance_km))
                      / SUM(CASE WHEN COALESCE(mm.haul_distance_km, h.distance_km) IS NOT NULL THEN COALESCE(mmeu.worked_volume, mm.volume, 0) ELSE 0 END)
                 ELSE NULL
               END AS haul_distance_km
        FROM material_movement_equipment_usage mmeu
        JOIN material_movements mm ON mm.id = mmeu.material_movement_id
        JOIN daily_reports dr_mm ON dr_mm.id = mm.daily_report_id
        LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr_mm.section_id)
        LEFT JOIN materials mat ON mat.id = mm.material_id
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN objects dst ON dst.id = mm.to_object_id
        LEFT JOIN section_quarry_haul_distances h
          ON h.section_code = cs.code
         AND h.quarry_object_id = src.id
        WHERE {' AND '.join(movement_where)}
        GROUP BY mmeu.report_equipment_unit_id, 2, 3, 4
        ORDER BY mmeu.report_equipment_unit_id::text, 2, 3, 4
        """,
        movement_params,
    )
    movement_by_eq: dict[str, list[dict]] = {}
    for r in movement_rows:
        movement_by_eq.setdefault(str(r["eq_id"]), []).append(r)

    _enrich_equipment_report_master_fields(base_rows)
    hired_groups: dict[tuple, list[dict]] = {}
    for row in base_rows:
        if _equipment_report_is_hired(row):
            hired_groups.setdefault(_equipment_report_group_key(row), []).append(row)
    group_by_eq = {
        str(row.get("report_equipment_unit_id")): (key, idx, len(rows))
        for key, rows in hired_groups.items()
        for idx, row in enumerate(rows)
    }

    def shared_work_items(eq_id: str) -> list[dict]:
        group_info = group_by_eq.get(eq_id)
        if not group_info:
            return work_by_eq.get(eq_id) or []
        group_key, row_index, group_size = group_info
        group_rows = hired_groups.get(group_key) or []
        order: list[tuple] = []
        aggregated: dict[tuple, dict] = {}
        for group_row in group_rows:
            for work in work_by_eq.get(str(group_row.get("report_equipment_unit_id")), []) or []:
                signature = _equipment_report_detail_signature(work, ("work_objects", "work_names"))
                if signature not in aggregated:
                    order.append(signature)
                    aggregated[signature] = dict(work)
                else:
                    aggregated[signature]["work_volume"] = float(aggregated[signature].get("work_volume") or 0) + float(work.get("work_volume") or 0)
                    aggregated[signature]["work_trips"] = int(aggregated[signature].get("work_trips") or 0) + int(work.get("work_trips") or 0)
        items: list[dict] = []
        for signature in order:
            item = dict(aggregated[signature])
            item["work_volume"] = _split_evenly_numeric(item.get("work_volume"), group_size, row_index)
            item["work_trips"] = _split_evenly_int(item.get("work_trips"), group_size, row_index)
            items.append(item)
        return items

    def shared_movement_items(eq_id: str) -> list[dict]:
        group_info = group_by_eq.get(eq_id)
        if not group_info:
            return movement_by_eq.get(eq_id) or []
        group_key, row_index, group_size = group_info
        group_rows = hired_groups.get(group_key) or []
        order: list[tuple] = []
        aggregated: dict[tuple, dict] = {}
        for group_row in group_rows:
            for movement in movement_by_eq.get(str(group_row.get("report_equipment_unit_id")), []) or []:
                signature = _equipment_report_detail_signature(movement, ("movement_routes", "material_names", "movement_types"))
                if signature not in aggregated:
                    order.append(signature)
                    aggregated[signature] = dict(movement)
                else:
                    aggregated[signature]["movement_volume"] = float(aggregated[signature].get("movement_volume") or 0) + float(movement.get("movement_volume") or 0)
                    aggregated[signature]["movement_trips"] = int(aggregated[signature].get("movement_trips") or 0) + int(movement.get("movement_trips") or 0)
                    current_distance = aggregated[signature].get("haul_distance_km")
                    next_distance = movement.get("haul_distance_km")
                    if current_distance is None and next_distance is not None:
                        aggregated[signature]["haul_distance_km"] = next_distance
        items: list[dict] = []
        for signature in order:
            item = dict(aggregated[signature])
            item["movement_volume"] = _split_evenly_numeric(item.get("movement_volume"), group_size, row_index)
            item["movement_trips"] = _split_evenly_int(item.get("movement_trips"), group_size, row_index)
            items.append(item)
        return items

    def base_result_row(row: dict) -> dict:
        status = row.get("status")
        bucket = _equipment_status_bucket(status, row.get("comment"))
        contractor = _equipment_report_clean_contractor(row.get("contractor_name"))
        return {
            "report_equipment_unit_id": row.get("report_equipment_unit_id") or "",
            "equipment_unit_id": row.get("equipment_unit_id") or "",
            "date": row.get("report_date"),
            "shift": "День" if row.get("shift") == "day" else "Ночь",
            "section_code": _merge_section(row.get("section_code")) or row.get("section_code") or "—",
            "section": _format_section_label(row.get("section_code")),
            "status_group": _equipment_bucket_label(bucket),
            "status": _equipment_status_label(status),
            "equipment_type": row.get("equipment_type") or "техника",
            "brand_model": row.get("brand_model") or "",
            "unit_number": row.get("unit_number") or "",
            "plate_number": row.get("plate_number") or "",
            "ownership_type": row.get("ownership_type") or "",
            "contractor": contractor,
            "work_objects": "",
            "work_names": "",
            "movement_routes": "",
            "materials": "",
            "movement_types": "",
            "haul_distance_km": "",
            "objects": "",
            "work_volume": 0,
            "movement_volume": 0,
            "trips": 0,
            "comment": row.get("comment") or "",
        }

    def row_has_details(row: dict) -> bool:
        eq_id = str(row.get("report_equipment_unit_id"))
        return bool(shared_work_items(eq_id) or shared_movement_items(eq_id))

    non_m_detail_unit_keys = {
        key
        for row in base_rows
        if not _equipment_report_is_mechanization_snapshot(row) and row_has_details(row)
        for key in (_equipment_report_same_shift_unit_key(row),)
        if key is not None
    }

    result: list[dict] = []
    for row in base_rows:
        same_shift_unit_key = _equipment_report_same_shift_unit_key(row)
        if _equipment_report_is_mechanization_snapshot(row) and same_shift_unit_key in non_m_detail_unit_keys:
            continue
        eq_id = str(row.get("report_equipment_unit_id"))
        work_items = shared_work_items(eq_id)
        movement_items = shared_movement_items(eq_id)
        has_details = False
        for work in work_items:
            item = base_result_row(row)
            item.update({
                "work_objects": work.get("work_objects") or "",
                "work_names": work.get("work_names") or "",
                "objects": work.get("work_objects") or "",
                "work_volume": round(float(work.get("work_volume") or 0), 2),
                "trips": int(work.get("work_trips") or 0),
            })
            result.append(item)
            has_details = True
        for movement in movement_items:
            raw_movement_types = [
                item.strip()
                for item in str(movement.get("movement_types") or "").split(",")
                if item.strip()
            ]
            item = base_result_row(row)
            item.update({
                "movement_routes": movement.get("movement_routes") or "",
                "materials": movement.get("material_names") or "",
                "movement_types": ", ".join(_movement_type_label(code) for code in raw_movement_types),
                "haul_distance_km": round(float(movement.get("haul_distance_km")), 2) if movement.get("haul_distance_km") is not None else "",
                "objects": movement.get("movement_routes") or "",
                "movement_volume": round(float(movement.get("movement_volume") or 0), 2),
                "trips": int(movement.get("movement_trips") or 0),
            })
            result.append(item)
            has_details = True
        if not has_details:
            item = base_result_row(row)
            if _equipment_report_is_mechanization_snapshot(row):
                item["objects"] = EQUIPMENT_REPORT_MECHANIZATION_ONLY_OBJECTS
            result.append(item)
    return result


def _generate_equipment_pipeline_xlsx(
    d_from: date_cls,
    d_to: date_cls,
    codes: Optional[list[str]],
) -> tuple[bytes, str, str]:
    rows = _query_equipment_report_rows(d_from, d_to, codes)
    wb = Workbook()
    ws = wb.active
    ws.title = "Техника"
    header_fill = PatternFill("solid", fgColor="1F2937")
    header_font = Font(color="FFFFFF", bold=True)
    columns = [
        ("date", "Дата"),
        ("shift", "Смена"),
        ("section", "Участок"),
        ("objects", "Объекты / маршруты"),
        ("status_group", "Группа статуса"),
        ("status", "Статус"),
        ("equipment_type", "Тип техники"),
        ("brand_model", "Марка / модель"),
        ("unit_number", "Бортовой / инв."),
        ("plate_number", "Госномер"),
        ("contractor", "Подрядчик"),
        ("work_names", "Работы"),
        ("materials", "Материалы"),
        ("movement_types", "Направления перевозки"),
        ("haul_distance_km", "Плечо, км"),
        ("work_volume", "Объем работ"),
        ("movement_volume", "Объем перевозки"),
        ("trips", "Рейсы"),
        ("comment", "Комментарий / простой / ремонт"),
    ]
    ws.append([label for _, label in columns])
    for cell in ws[1]:
        cell.fill = header_fill
        cell.font = header_font
    for row in rows:
        ws.append([row.get(key, "") for key, _ in columns])
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = ws.dimensions

    for idx, (_, label) in enumerate(columns, start=1):
        width = max(len(label) + 2, 14)
        for value_cell in ws.iter_cols(min_col=idx, max_col=idx, min_row=2):
            for cell in value_cell:
                width = min(max(width, len(str(cell.value or "")) + 2), 48)
        ws.column_dimensions[ws.cell(row=1, column=idx).column_letter].width = width

    summary_ws = wb.create_sheet(title="Сводка")
    summary_ws.append(["Участок", "Принадлежность", "Группа статуса", "Тип техники", "Единиц"])
    for cell in summary_ws[1]:
        cell.fill = header_fill
        cell.font = header_font
    summary: dict[tuple, set[str]] = {}
    for row in rows:
        hired = _equipment_report_is_hired(row)
        key = (
            row.get("section_code") or "—",
            row.get("section") or "—",
            "Наемная" if hired else "ЖДС",
            row.get("status_group") or "не указан",
            row.get("equipment_type") or "техника",
            1 if hired else 0,
        )
        unit_key = _equipment_report_summary_unit_key(row)
        summary.setdefault(key, set()).add(unit_key)
    for (_section_code, section, ownership, status_group, equipment_type, _ownership_sort), units in sorted(
        summary.items(),
        key=lambda item: (
            _section_num_from_code(_merge_section(item[0][0]) or item[0][0]) or 999,
            item[0][5],
            str(item[0][3]),
            str(item[0][4]),
        ),
    ):
        summary_ws.append([section, ownership, status_group, equipment_type, len(units)])
    summary_ws.freeze_panes = "A2"
    summary_ws.auto_filter.ref = summary_ws.dimensions
    for idx in range(1, 6):
        width = 16
        for value_cell in summary_ws.iter_cols(min_col=idx, max_col=idx, min_row=1):
            for cell in value_cell:
                width = min(max(width, len(str(cell.value or "")) + 2), 42)
        summary_ws.column_dimensions[summary_ws.cell(row=1, column=idx).column_letter].width = width

    bio = BytesIO()
    wb.save(bio)
    if d_from == d_to:
        period_ascii = d_to.isoformat()
        period_label = d_to.strftime("%d.%m.%Y")
    else:
        period_ascii = f"{d_from.isoformat()}_{d_to.isoformat()}"
        period_label = f"{d_from.strftime('%d.%m.%Y')} - {d_to.strftime('%d.%m.%Y')}"
    return (
        bio.getvalue(),
        f"VSM_Equipment_{period_ascii}.xlsx",
        f"Отчет по технике {period_label}.xlsx",
    )


def _report_filter_values(values: Optional[list[str]]) -> list[str]:
    if values is None:
        return []
    out: list[str] = []
    seen: set[str] = set()
    has_all = False
    for value in values or []:
        v = str(value or "").strip()
        if v == "all":
            has_all = True
            continue
        if not v or v in seen:
            continue
        out.append(v)
        seen.add(v)
    if not out and not has_all:
        return ["__VSM_EMPTY_SELECTION__"]
    return out


def _report_filter_env(
    *,
    work_tags: Optional[list[str]] = None,
    object_type_codes: Optional[list[str]] = None,
    object_codes: Optional[list[str]] = None,
) -> dict[str, str]:
    payload = {
        "DIM_REPORT_FILTER_WORK_TAGS": _report_filter_values(work_tags),
        "DIM_REPORT_FILTER_OBJECT_TYPES": _report_filter_values(object_type_codes),
        "DIM_REPORT_FILTER_OBJECTS": _report_filter_values(object_codes),
    }
    return {
        key: json.dumps(values, ensure_ascii=False)
        for key, values in payload.items()
        if values
    }


def _report_option_env(*, cumulative_as_of_end_date: Optional[bool] = None) -> dict[str, str]:
    if cumulative_as_of_end_date is None:
        return {}
    return {
        "DIM_REPORT_CUMULATIVE_AS_OF_END_DATE": "1" if cumulative_as_of_end_date else "0",
        "DIM_REPORT_SHOW_DAILY_PK_DETAILS": "0",
    }


def _cumulative_as_of_end_date_from_body(body: object) -> bool:
    explicit = getattr(body, "cumulative_as_of_end_date", None)
    if explicit is not None:
        return bool(explicit)
    legacy = getattr(body, "show_daily_pk_details", None)
    if legacy is not None:
        return bool(legacy)
    return False


def _normalize_generator_report_parameters(payload: object) -> dict:
    raw = payload if isinstance(payload, dict) else {}
    raw_reports = raw.get("reports") if isinstance(raw.get("reports"), dict) else {}
    reports: dict[str, dict] = {}
    default_section_ids = {section["id"] for section in GENERATOR_PARAMETER_SECTION_DEFAULTS}
    for report_key in GENERATOR_PARAMETER_REPORT_KEYS:
        raw_report = raw_reports.get(report_key) if isinstance(raw_reports.get(report_key), dict) else {}
        raw_sections = raw_report.get("sections") if isinstance(raw_report.get("sections"), list) else []
        raw_sections_by_id: dict[str, dict] = {}
        extra_sections: list[dict] = []
        for raw_section in raw_sections:
            if not isinstance(raw_section, dict):
                continue
            section_id = _general_clean_id(raw_section.get("id"), "")
            if not section_id:
                continue
            if section_id in default_section_ids:
                raw_sections_by_id[section_id] = raw_section
            else:
                extra_sections.append(raw_section)

        sections: list[dict] = []
        seen_sections: set[str] = set()
        for default in GENERATOR_PARAMETER_SECTION_DEFAULTS:
            section_id = default["id"]
            raw_section = raw_sections_by_id.get(section_id, {})
            title = str(raw_section.get("title") or default["title"]).strip()[:160] or default["title"]
            sections.append({
                "id": section_id,
                "title": title,
                "enabled": _general_clean_bool(raw_section.get("enabled"), True),
            })
            seen_sections.add(section_id)

        for idx, raw_section in enumerate(extra_sections[:24], start=1):
            section_id = _general_clean_id(raw_section.get("id"), f"custom_{idx}")
            if section_id in seen_sections:
                continue
            title = str(raw_section.get("title") or f"Дополнительный раздел {idx}").strip()[:160]
            sections.append({
                "id": section_id,
                "title": title or f"Дополнительный раздел {idx}",
                "enabled": _general_clean_bool(raw_section.get("enabled"), True),
            })
            seen_sections.add(section_id)

        grouping = str(raw_report.get("grouping") or "objects").strip()
        if grouping not in {"sections", "objects"}:
            grouping = "objects"
        cumulative_as_of_end_date = _general_clean_bool(
            raw_report.get("cumulative_as_of_end_date", raw_report.get("show_daily_pk_details")),
            False,
        )
        reports[report_key] = {
            "cumulative_as_of_end_date": cumulative_as_of_end_date,
            "show_daily_pk_details": cumulative_as_of_end_date,
            "include_quarry_totals": _general_clean_bool(raw_report.get("include_quarry_totals"), True),
            "grouping": grouping,
            "work_tags": _general_clean_string_list(raw_report.get("work_tags"), limit=160),
            "object_type_codes": _general_clean_string_list(raw_report.get("object_type_codes"), limit=160),
            "object_codes": _general_clean_string_list(raw_report.get("object_codes"), limit=240),
            "sections": sections,
        }
    return {"version": 1, "reports": reports}


def _load_generator_report_parameters_record() -> tuple[dict, Optional[str], object]:
    try:
        _ensure_dashboard_settings_schema()
        row = query_one(
            """
            SELECT payload, updated_by, updated_at
            FROM dashboard_settings
            WHERE key = %s
            """,
            (GENERATOR_REPORT_PARAMETERS_CONFIG_KEY,),
        )
        if row and isinstance(row.get("payload"), dict):
            return row.get("payload") or {}, row.get("updated_by"), row.get("updated_at")
    except Exception:
        pass
    return {}, None, None


def _generator_report_parameters() -> dict:
    payload, _, _ = _load_generator_report_parameters_record()
    return _normalize_generator_report_parameters(payload)


def _report_parameters_for_key(report_key: str, parameters: Optional[dict] = None) -> dict:
    normalized = parameters or _generator_report_parameters()
    reports = normalized.get("reports") if isinstance(normalized, dict) else {}
    report = reports.get(report_key) if isinstance(reports, dict) else None
    if isinstance(report, dict):
        return report
    return _normalize_generator_report_parameters({})["reports"].get(report_key, {})


def _report_parameters_env(
    report_key: str,
    *,
    parameters: Optional[dict] = None,
    cumulative_as_of_end_date_override: Optional[bool] = None,
    show_daily_pk_details_override: Optional[bool] = None,
) -> dict[str, str]:
    cumulative_override = (
        cumulative_as_of_end_date_override
        if cumulative_as_of_end_date_override is not None
        else show_daily_pk_details_override
    )
    if report_key not in GENERATOR_PARAMETER_REPORT_KEYS:
        return _report_option_env(cumulative_as_of_end_date=cumulative_override)
    report = _report_parameters_for_key(report_key, parameters)
    cumulative_as_of_end_date = (
        cumulative_override
        if cumulative_override is not None
        else bool(report.get("cumulative_as_of_end_date", report.get("show_daily_pk_details")))
    )
    env = _report_option_env(cumulative_as_of_end_date=cumulative_as_of_end_date)
    if report_key in GENERATOR_PARAMETER_QUARRY_TOTAL_REPORT_KEYS:
        env["DIM_REPORT_INCLUDE_QUARRY_TOTALS"] = "1" if report.get("include_quarry_totals", True) is not False else "0"
    if report_key in GENERATOR_PARAMETER_GROUPING_REPORT_KEYS:
        env["DIM_REPORT_GROUPING_MODE"] = str(report.get("grouping") or "objects")
    if report_key in GENERATOR_PARAMETER_SECTION_REPORT_KEYS:
        sections = report.get("sections") if isinstance(report.get("sections"), list) else []
        enabled_sections = [
            str(section.get("id"))
            for section in sections
            if isinstance(section, dict) and section.get("enabled", True) is not False and section.get("id")
        ]
        titles = {
            str(section.get("id")): str(section.get("title") or "")
            for section in sections
            if isinstance(section, dict) and section.get("id") and str(section.get("title") or "").strip()
        }
        env["DIM_REPORT_ENABLED_SECTIONS"] = ",".join(enabled_sections) if enabled_sections else "__none__"
        env["DIM_REPORT_SECTION_TITLES_JSON"] = json.dumps(titles, ensure_ascii=False)
    env.update(_report_filter_env(
        work_tags=report.get("work_tags") or None,
        object_type_codes=report.get("object_type_codes") or None,
        object_codes=report.get("object_codes") or None,
    ))
    return env


def _pipeline_filter_env_from_body(
    body: GeneratorPipelineExportBody,
    *,
    cumulative_as_of_end_date: bool,
) -> dict[str, str]:
    cumulative_override = (
        cumulative_as_of_end_date
        if body.report_key in CUMULATIVE_AS_OF_END_DATE_XLSX_REPORT_KEYS
        else None
    )
    filter_env = _report_parameters_env(
        body.report_key,
        cumulative_as_of_end_date_override=cumulative_override,
    )
    filter_env.update(_report_filter_env(
        work_tags=body.work_tags,
        object_type_codes=body.object_type_codes,
        object_codes=body.object_codes,
    ))
    return filter_env


def _allowed_columns(report_type: str, selected: Optional[dict[str, list[str]]]) -> list[dict]:
    all_columns = GENERATOR_REPORT_TYPES[report_type]["columns"]
    selected_keys = selected.get(report_type) if selected else None
    if not selected_keys:
        return all_columns
    allowed = {c["key"] for c in all_columns}
    keys = [k for k in selected_keys if k in allowed]
    return [c for c in all_columns if c["key"] in keys] or all_columns


def _query_sand_by_constructive(d_from: date_cls, d_to: date_cls, codes: Optional[list[str]]) -> list[dict]:
    where = [
        "mm.report_date BETWEEN %s AND %s",
        "mm.is_demo = false",
        "m.code = 'SAND'",
        "mm.movement_type IN ('pit_to_constructive', 'stockpile_to_constructive')",
        _approved_report_exists("mm"),
    ]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               dst.name AS object_name,
               mm.movement_type,
               SUM(mm.volume)::numeric AS volume,
               COALESCE(MAX(mm.unit), 'м³') AS unit,
               SUM(COALESCE(mm.trip_count, 0))::int AS trips
        FROM material_movements mm
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN construction_sections cs ON cs.id = mm.section_id
        LEFT JOIN objects dst ON dst.id = mm.to_object_id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, dst.name, mm.movement_type
        ORDER BY cs.code, dst.name, mm.movement_type
        """,
        params,
    )
    for r in rows:
        r["section_code"] = _merge_section(r.get("section_code")) or r.get("section_code") or "—"
        r["movement_type"] = _movement_type_label(r.get("movement_type"))
        r["volume"] = round(float(r.get("volume") or 0), 2)
    return rows


def _query_sand_by_quarry(d_from: date_cls, d_to: date_cls, codes: Optional[list[str]]) -> list[dict]:
    where = [
        "mm.report_date BETWEEN %s AND %s",
        "mm.is_demo = false",
        "m.code = 'SAND'",
        "src_type.code = 'BORROW_PIT'",
        "mm.movement_type IN ('pit_to_constructive', 'pit_to_stockpile')",
        _approved_report_exists("mm"),
    ]
    params: list = [d_from, d_to]
    if codes:
        where.append("cs.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               src.name AS quarry_name,
               dst.name AS to_object_name,
               mm.movement_type,
               SUM(mm.volume)::numeric AS volume,
               COALESCE(MAX(mm.unit), 'м³') AS unit,
               SUM(COALESCE(mm.trip_count, 0))::int AS trips
        FROM material_movements mm
        JOIN materials m ON m.id = mm.material_id
        JOIN objects src ON src.id = mm.from_object_id
        JOIN object_types src_type ON src_type.id = src.object_type_id
        LEFT JOIN objects dst ON dst.id = mm.to_object_id
        LEFT JOIN construction_sections cs ON cs.id = mm.section_id
        WHERE {' AND '.join(where)}
        GROUP BY cs.code, src.name, dst.name, mm.movement_type
        ORDER BY cs.code, src.name, dst.name, mm.movement_type
        """,
        params,
    )
    for r in rows:
        r["section_code"] = _merge_section(r.get("section_code")) or r.get("section_code") or "—"
        r["movement_type"] = _movement_type_label(r.get("movement_type"))
        r["volume"] = round(float(r.get("volume") or 0), 2)
    return rows


def _query_project_piles(codes: Optional[list[str]]) -> list[dict]:
    where = [
        "pf.is_demo = false",
        "COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded')",
    ]
    params: list = []
    if codes:
        where.append("sec.code = ANY(%s)")
        params.append(codes)
    rows = query(
        f"""
        SELECT COALESCE(sec.code, '—') AS section_code,
               pf.field_code,
               CASE pf.field_type WHEN 'test' THEN 'пробное' ELSE 'основное' END AS field_type,
               pf.pile_type,
               pf.pk_start,
               pf.pk_end,
               pf.pile_count,
               COALESCE(pf.dynamic_test_count, 0) AS dynamic_test_count
        FROM pile_fields pf
        LEFT JOIN LATERAL (
          SELECT cs.code
          FROM construction_section_versions csv
          JOIN construction_sections cs ON cs.id = csv.section_id
          WHERE csv.is_current = true
            AND csv.boundary_kind = 'piles_pipes'
            AND pf.pk_start >= csv.pk_start
            AND pf.pk_end <= csv.pk_end
          ORDER BY csv.pk_start
          LIMIT 1
        ) sec ON true
        WHERE {' AND '.join(where)}
        ORDER BY sec.code, pf.pk_start, pf.field_code
        """,
        params,
    )
    for r in rows:
        r["section_code"] = _merge_section(r.get("section_code")) or r.get("section_code") or "—"
        r["pk_range"] = f"{_format_pk(r.get('pk_start'))} - {_format_pk(r.get('pk_end'))}"
        r["pile_count"] = int(r.get("pile_count") or 0)
        r["dynamic_test_count"] = int(r.get("dynamic_test_count") or 0)

    pipe_where = ["COALESCE(o.is_active, true) IS TRUE", "ot.code = 'PIPE'"]
    pipe_params: list = []
    if codes:
        pipe_where.append("pipe_sec.code = ANY(%s)")
        pipe_params.append(codes)
    pipe_rows = query(
        f"""
        WITH seg AS (
            SELECT object_id,
                   MIN(LEAST(pk_start, pk_end)) AS pk_start,
                   MAX(GREATEST(pk_start, pk_end)) AS pk_end
            FROM object_segments
            WHERE pk_start IS NOT NULL AND pk_end IS NOT NULL
            GROUP BY object_id
        ), spec AS (
            SELECT pps.object_id,
                   pps.work_type_id,
                   STRING_AGG(DISTINCT CONCAT(COALESCE(pps.pile_length_m::text, '?'), ' м'), '; ' ORDER BY CONCAT(COALESCE(pps.pile_length_m::text, '?'), ' м')) AS length_text,
                   SUM(COALESCE(pps.quantity, 0))::numeric AS spec_project_qty
            FROM pipe_pile_specs pps
            WHERE COALESCE(pps.is_active, true) IS TRUE
            GROUP BY pps.object_id, pps.work_type_id
        ), pwi AS (
            SELECT project_work_items.object_id,
                   project_work_items.work_type_id,
                   SUM(COALESCE(project_work_items.project_volume, 0))::numeric AS project_qty
            FROM project_work_items
            GROUP BY project_work_items.object_id, project_work_items.work_type_id
        ), pipe_work AS (
            SELECT object_id, work_type_id FROM spec
            UNION
            SELECT object_id, work_type_id FROM pwi
        )
        SELECT COALESCE(pipe_sec.code, '—') AS section_code,
               o.object_code AS field_code,
               CASE wt.code WHEN 'PILE_TRIAL' THEN 'ПЖБТ, пробные' ELSE 'ПЖБТ, основные' END AS field_type,
               COALESCE(spec.length_text, wt.name, '') AS pile_type,
               seg.pk_start,
               seg.pk_end,
               COALESCE(NULLIF(pwi.project_qty, 0), spec.spec_project_qty, 0)::numeric AS pile_count,
               0::numeric AS dynamic_test_count
        FROM pipe_work
        JOIN objects o ON o.id = pipe_work.object_id
        JOIN object_types ot ON ot.id = o.object_type_id
        JOIN work_types wt ON wt.id = pipe_work.work_type_id
        LEFT JOIN seg ON seg.object_id = o.id
        LEFT JOIN spec ON spec.object_id = pipe_work.object_id AND spec.work_type_id = pipe_work.work_type_id
        LEFT JOIN pwi ON pwi.object_id = pipe_work.object_id AND pwi.work_type_id = pipe_work.work_type_id
        LEFT JOIN LATERAL (
          SELECT cs.code
          FROM construction_section_versions csv
          JOIN construction_sections cs ON cs.id = csv.section_id
          WHERE csv.is_current = true
            AND csv.boundary_kind = 'piles_pipes'
            AND seg.pk_start IS NOT NULL
            AND seg.pk_end IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) BETWEEN LEAST(csv.pk_start, csv.pk_end) AND GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY cs.sort_order NULLS LAST, cs.code, csv.pk_start
          LIMIT 1
        ) pipe_sec ON true
        WHERE {' AND '.join(pipe_where)}
          AND wt.code IN ('PILE_MAIN', 'PILE_TRIAL')
          AND COALESCE(NULLIF(pwi.project_qty, 0), spec.spec_project_qty, 0) > 0
        ORDER BY pipe_sec.code, seg.pk_start, o.object_code, wt.code
        """,
        pipe_params,
    )
    for r in pipe_rows:
        r["section_code"] = _merge_section(r.get("section_code")) or r.get("section_code") or "—"
        r["pk_range"] = f"{_format_pk(r.get('pk_start'))} - {_format_pk(r.get('pk_end'))}"
        r["pile_count"] = int(round(float(r.get("pile_count") or 0)))
        r["dynamic_test_count"] = int(r.get("dynamic_test_count") or 0)
    rows.extend(pipe_rows)
    rows.sort(key=lambda r: (
        _section_num_from_code(r.get("section_code")) or 999,
        r.get("pk_start") is None,
        float(r.get("pk_start") or 0),
        str(r.get("field_code") or ""),
        str(r.get("field_type") or ""),
    ))
    return rows


def _rows_for_generator(report_type: str, d_from: date_cls, d_to: date_cls, codes: Optional[list[str]]) -> list[dict]:
    if report_type == "sand_by_constructive":
        return _query_sand_by_constructive(d_from, d_to, codes)
    if report_type == "sand_by_quarry":
        return _query_sand_by_quarry(d_from, d_to, codes)
    if report_type == "project_piles":
        return _query_project_piles(codes)
    raise HTTPException(400, f"Unknown report type: {report_type}")


def _general_debug_query_values(values: Optional[list[str]], limit: int = 80) -> list[str]:
    return _general_clean_string_list(values or [], limit=limit)


def _general_report_debug_kind_from_row(block: Optional[dict], row: Optional[dict], fallback: str = "work_summary") -> str:
    raw = str((row or {}).get("source") or (block or {}).get("kind") or fallback or "work_summary").strip()
    if raw in {"top_quarry", "top_quarries"}:
        return "top_quarries"
    if raw in {"equipment_count", "equipment_day"}:
        return "equipment_day"
    return "work_summary"


def _general_report_find_block_and_row(
    row_id: str,
    block_id: Optional[str] = None,
    config: Optional[dict] = None,
) -> tuple[Optional[dict], dict]:
    wanted_row_id = str(row_id or "").strip()
    wanted_block_id = str(block_id or "").strip() or None
    if not wanted_row_id:
        raise HTTPException(400, "row_id is required")
    config = config or _general_report_config()
    for block in config.get("blocks") or []:
        if wanted_block_id and str(block.get("id") or "").strip() != wanted_block_id:
            continue
        for row in block.get("rows") or []:
            if str(row.get("id") or "").strip() == wanted_row_id:
                return block, row
    raise HTTPException(404, f"Строка конструктора не найдена: {wanted_row_id}")


@router.get("/generator/general-report-row-debug")
def get_generator_general_report_row_debug(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    section: Optional[str] = None,
    kind: str = "work_summary",
    block_id: Optional[str] = None,
    row_id: Optional[str] = None,
    tags: Optional[list[str]] = Query(None),
    object_type_codes: Optional[list[str]] = Query(None),
    object_codes: Optional[list[str]] = Query(None),
    from_object_type_codes: Optional[list[str]] = Query(None),
    from_object_codes: Optional[list[str]] = Query(None),
    to_object_type_codes: Optional[list[str]] = Query(None),
    to_object_codes: Optional[list[str]] = Query(None),
    quarry_labels: Optional[list[str]] = Query(None),
    materials: Optional[list[str]] = Query(None),
    movement_types: Optional[list[str]] = Query(None),
    source_buckets: Optional[list[str]] = Query(None),
    equipment_classes: Optional[list[str]] = Query(None),
    limit: int = 200,
    _user=Depends(current_user),
):
    """Read-only row debugger for General Report constructor."""
    d_from, d_to = _parse_range(date_from, date_to)
    codes = _expand_sections(section)
    limit = max(10, min(int(limit or 200), 500))

    saved_block = None
    saved_row = None
    if row_id:
        saved_block, saved_row = _general_report_find_block_and_row(row_id=row_id, block_id=block_id)
        saved_filters = _general_row_filters(saved_row.get("filters"))
        kind = _general_report_debug_kind_from_row(saved_block, saved_row, kind)
        tag_values = _general_debug_query_values(saved_filters.get("tags"))
        object_type_values = _general_debug_query_values(saved_filters.get("object_type_codes"))
        object_values = _general_debug_query_values(saved_filters.get("object_codes"))
        from_object_type_values = _general_debug_query_values(saved_filters.get("from_object_type_codes"))
        from_object_values = _general_debug_query_values(saved_filters.get("from_object_codes"))
        to_object_type_values = _general_debug_query_values(saved_filters.get("to_object_type_codes"))
        to_object_values = _general_debug_query_values(saved_filters.get("to_object_codes"))
        quarry_values = _general_debug_query_values(saved_filters.get("quarry_labels"))
        material_values = _general_debug_query_values(saved_filters.get("materials"))
        movement_values = _general_debug_query_values(saved_filters.get("movement_types"))
        source_values = _general_debug_query_values(saved_filters.get("source_buckets"), limit=12)
        equipment_values = _general_debug_query_values(saved_filters.get("equipment_classes"), limit=12)
    else:
        tag_values = _general_debug_query_values(tags)
        object_type_values = _general_debug_query_values(object_type_codes)
        object_values = _general_debug_query_values(object_codes)
        from_object_type_values = _general_debug_query_values(from_object_type_codes)
        from_object_values = _general_debug_query_values(from_object_codes)
        to_object_type_values = _general_debug_query_values(to_object_type_codes)
        to_object_values = _general_debug_query_values(to_object_codes)
        quarry_values = _general_debug_query_values(quarry_labels)
        material_values = _general_debug_query_values(materials)
        movement_values = _general_debug_query_values(movement_types)
        source_values = _general_debug_query_values(source_buckets, limit=12)
        equipment_values = _general_debug_query_values(equipment_classes, limit=12)

    if kind == "top_quarries":
        where = [
            "mm.report_date BETWEEN %s AND %s",
            "COALESCE(mm.is_demo, false) IS FALSE",
            "COALESCE(dr.is_demo, false) IS FALSE",
            _approved_report_exists("mm"),
        ]
        params: list = [d_from, d_to]
        if codes:
            where.append("cs.code = ANY(%s)")
            params.append(codes)
        if movement_values:
            where.append("mm.movement_type = ANY(%s)")
            params.append(movement_values)
        if from_object_type_values:
            where.append("src_ot.code = ANY(%s)")
            params.append(from_object_type_values)
        if from_object_values:
            where.append("src.object_code = ANY(%s)")
            params.append(from_object_values)
        if to_object_type_values:
            where.append("dst_ot.code = ANY(%s)")
            params.append(to_object_type_values)
        if to_object_values:
            where.append("dst.object_code = ANY(%s)")
            params.append(to_object_values)
        rows = query(
            f"""
            SELECT mm.id::text AS id,
                   mm.report_date,
                   cs.code AS section_code,
                   LOWER(COALESCE(mm.shift, 'day')) AS shift,
                   COALESCE(NULLIF(src.name, ''), src.object_code, 'Источник') AS source_name,
                   src.object_code AS source_object_code,
                   src_ot.code AS source_object_type_code,
                   src_ot.name AS source_object_type_name,
                   COALESCE(NULLIF(dst.name, ''), dst.object_code, '') AS destination_name,
                   dst.object_code AS destination_object_code,
                   dst_ot.code AS destination_object_type_code,
                   dst_ot.name AS destination_object_type_name,
                   m.code AS material_code,
                   COALESCE(NULLIF(m.name, ''), m.code) AS material_name,
                   mm.movement_type,
                   mm.labor_source_type,
                   COALESCE(mm.contractor_name, c.short_name, c.name, '') AS contractor_name,
                   COALESCE(mm.volume, 0)::numeric AS amount
            FROM material_movements mm
            JOIN daily_reports dr ON dr.id = mm.daily_report_id
            JOIN materials m ON m.id = mm.material_id
            LEFT JOIN construction_sections cs ON cs.id = COALESCE(mm.section_id, dr.section_id)
            LEFT JOIN objects src ON src.id = mm.from_object_id
            LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
            LEFT JOIN objects dst ON dst.id = mm.to_object_id
            LEFT JOIN object_types dst_ot ON dst_ot.id = dst.object_type_id
            LEFT JOIN contractors c ON c.id = mm.contractor_id
            WHERE {' AND '.join(where)}
            ORDER BY mm.report_date DESC, cs.code, source_name
            LIMIT %s
            """,
            [*params, limit * 5],
        )
        out = []
        total = 0.0
        selected_quarry_keys = {_general_quarry_label_key(value) for value in quarry_values}
        selected_sources = set(source_values)
        selected_materials = set(material_values)
        for row in rows:
            source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
            material_value = _general_material_filter_value(row.get("material_code"), row.get("material_name"))
            material_aliases = _general_material_filter_aliases(row.get("material_code"), row.get("material_name"))
            material_bucket = _general_material_bucket(row.get("material_code"), row.get("material_name"))
            label = row.get("source_name") or "Источник"
            if material_bucket and material_bucket != "SAND":
                label = f"{label} ({row.get('material_name') or row.get('material_code') or 'материал'})"
            if selected_quarry_keys and not (_general_quarry_label_keys(label) & selected_quarry_keys):
                continue
            if selected_sources and source_bucket not in selected_sources:
                continue
            if selected_materials and not (set(material_aliases) & selected_materials):
                continue
            amount = float(row.get("amount") or 0)
            total += amount
            out.append({
                "id": row.get("id"),
                "date": row["report_date"].isoformat() if row.get("report_date") else None,
                "section_code": _merge_section(row.get("section_code")) or row.get("section_code") or "—",
                "kind": "movement",
                "label": label,
                "source_name": row.get("source_name"),
                "source_object_type_name": row.get("source_object_type_name"),
                "destination_name": row.get("destination_name") or None,
                "destination_object_type_name": row.get("destination_object_type_name") or None,
                "material": row.get("material_name") or row.get("material_code") or "—",
                "movement_type": row.get("movement_type"),
                "movement_label": _movement_type_label(row.get("movement_type")),
                "source_bucket": source_bucket,
                "contractor_name": row.get("contractor_name") or "—",
                "shift": row.get("shift"),
                "unit": "м3",
                "volume": round(amount, 2),
            })
            if len(out) >= limit:
                break
        return {
            "from": d_from.isoformat(),
            "to": d_to.isoformat(),
            "kind": kind,
            "block_id": saved_block.get("id") if isinstance(saved_block, dict) else None,
            "row_id": saved_row.get("id") if isinstance(saved_row, dict) else None,
            "row_label": saved_row.get("label") if isinstance(saved_row, dict) else None,
            "total": round(total, 2),
            "rows": out,
        }

    if kind == "equipment_day":
        where = [
            "dr.report_date BETWEEN %s AND %s",
            "COALESCE(reu.is_demo, false) IS FALSE",
            "COALESCE(dr.is_demo, false) IS FALSE",
            "reu.status = 'working'",
            _approved_report_exists("reu"),
        ]
        params = [d_from, d_to]
        if codes:
            where.append("cs.code = ANY(%s)")
            params.append(codes)
        rows = query(
            f"""
            SELECT reu.id::text AS id,
                   dr.report_date,
                   dr.shift,
                   cs.code AS section_code,
                   COALESCE(reu.equipment_type, eu.equipment_type) AS equipment_type,
                   COALESCE(NULLIF(reu.plate_number, ''), eu.plate_number, '') AS plate_number,
                   COALESCE(NULLIF(reu.unit_number, ''), eu.unit_number, '') AS unit_number,
                   COALESCE(NULLIF(reu.ownership_type, ''), eu.ownership_type, 'unknown') AS ownership_type,
                   COALESCE(NULLIF(reu.contractor_name, ''), c.short_name, c.name, eu.contractor_name, '') AS contractor_name
            FROM report_equipment_units reu
            JOIN daily_reports dr ON dr.id = reu.daily_report_id
            LEFT JOIN construction_sections cs ON cs.id = dr.section_id
            LEFT JOIN equipment_units eu ON eu.id = reu.equipment_unit_id
            LEFT JOIN contractors c ON c.id = reu.contractor_id
            WHERE {' AND '.join(where)}
            ORDER BY dr.report_date DESC, cs.code, equipment_type
            LIMIT %s
            """,
            [*params, limit * 5],
        )
        out = []
        selected_sources = set(source_values)
        selected_classes = set(equipment_values)
        for row in rows:
            eq_class = _general_equipment_class(row.get("equipment_type"))
            if selected_classes and eq_class not in selected_classes:
                continue
            source_bucket = _equipment_source_bucket(row.get("ownership_type"), row.get("contractor_name"))
            if selected_sources and source_bucket not in selected_sources:
                continue
            out.append({
                "id": row.get("id"),
                "date": row["report_date"].isoformat() if row.get("report_date") else None,
                "section_code": _merge_section(row.get("section_code")) or row.get("section_code") or "—",
                "kind": "equipment",
                "label": row.get("equipment_type") or GENERAL_REPORT_EQUIPMENT_CLASS_LABELS.get(eq_class or "", "Техника"),
                "equipment_class": eq_class,
                "plate_number": row.get("plate_number") or "—",
                "unit_number": row.get("unit_number") or "—",
                "source_bucket": source_bucket,
                "contractor_name": row.get("contractor_name") or "—",
                "shift": row.get("shift"),
                "unit": "ед.",
                "volume": 1,
            })
            if len(out) >= limit:
                break
        return {
            "from": d_from.isoformat(),
            "to": d_to.isoformat(),
            "kind": kind,
            "block_id": saved_block.get("id") if isinstance(saved_block, dict) else None,
            "row_id": saved_row.get("id") if isinstance(saved_row, dict) else None,
            "row_label": saved_row.get("label") if isinstance(saved_row, dict) else None,
            "total": len(out),
            "rows": out,
        }

    where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
    ]
    params = [d_from, d_to]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)
    if tag_values:
        where.append("COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) = ANY(%s)")
        params.append(tag_values)
    if object_type_values:
        where.append("ot.code = ANY(%s)")
        params.append(object_type_values)
    if object_values:
        where.append("obj.object_code = ANY(%s)")
        params.append(object_values)
    rows = query(
        f"""
        SELECT COALESCE(seg.id::text, dwi.id::text) AS id,
               dwi.report_date,
               dwi.shift,
               cs_eff.code AS section_code,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               ot.code AS object_type_code,
               ot.name AS object_type_name,
               obj.object_code,
               obj.name AS object_name,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               dwi.labor_source_type,
               dwi.contractor_name,
               COALESCE(NULLIF(dwi.unit, ''), wt.default_unit, '') AS unit,
               CASE
                 WHEN seg.id IS NULL THEN COALESCE(dwi.volume, 0)
                 WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                 WHEN seg_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_count.cnt
                 ELSE COALESCE(dwi.volume, 0)
               END::numeric AS amount
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND seg.id IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        ORDER BY dwi.report_date DESC, wt.name, obj.name NULLS LAST
        LIMIT %s
        """,
        [*params, limit * 5],
    )
    out = []
    total = 0.0
    selected_sources = set(source_values)
    for row in rows:
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        if selected_sources and source_bucket not in selected_sources:
            continue
        amount = float(row.get("amount") or 0)
        total += amount
        out.append({
            "id": row.get("id"),
            "date": row["report_date"].isoformat() if row.get("report_date") else None,
            "section_code": _merge_section(row.get("section_code")) or row.get("section_code") or "—",
            "kind": "work",
            "label": row.get("analytics_tag") or row.get("work_type_name") or "Работа",
            "work_type_name": row.get("work_type_name"),
            "object_name": row.get("object_name") or row.get("object_type_name") or "—",
            "object_type_name": row.get("object_type_name") or "—",
            "source_bucket": source_bucket,
            "contractor_name": row.get("contractor_name") or "—",
            "shift": row.get("shift"),
            "unit": row.get("unit") or "—",
            "volume": round(amount, 2),
        })
        if len(out) >= limit:
            break
    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "kind": kind,
        "block_id": saved_block.get("id") if isinstance(saved_block, dict) else None,
        "row_id": saved_row.get("id") if isinstance(saved_row, dict) else None,
        "row_label": saved_row.get("label") if isinstance(saved_row, dict) else None,
        "total": round(total, 2),
        "rows": out,
    }


@router.get("/generator/general-report-unresolved")
def get_generator_general_report_unresolved(
    date_from: Optional[str] = Query(None, alias="from"),
    date_to: Optional[str] = Query(None, alias="to"),
    section: Optional[str] = None,
    status: Optional[list[str]] = Query(None),
    limit: int = 250,
    _user=Depends(current_user),
):
    d_from, d_to = _parse_range(date_from, date_to)
    codes = _expand_sections(section)
    limit = max(25, min(int(limit or 250), 1000))
    valid_statuses = ("matched", "implicit", "unresolved")
    selected_statuses = {
        str(value or "").strip().lower()
        for value in (status or [])
        if str(value or "").strip().lower() in valid_statuses
    }
    if not selected_statuses:
        selected_statuses = {"implicit", "unresolved"}

    where = [
        "dwi.report_date >= %s",
        "dwi.report_date <= %s",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _approved_report_exists("dwi"),
    ]
    params = [d_from, d_to]
    if codes:
        where.append("cs_eff.code = ANY(%s)")
        params.append(codes)

    raw_scan_limit = max(limit * 8, 1200)
    raw_scan_limit = min(raw_scan_limit, 5000)
    rows = query(
        f"""
        SELECT COALESCE(seg.id::text, dwi.id::text) AS id,
               dwi.report_date,
               dwi.shift,
               cs_eff.code AS section_code,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               ot.code AS object_type_code,
               ot.name AS object_type_name,
               obj.object_code,
               obj.name AS object_name,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               dwi.labor_source_type,
               dwi.contractor_name,
               COALESCE(NULLIF(dwi.unit, ''), wt.default_unit, '') AS unit,
               CASE
                 WHEN seg.id IS NULL THEN COALESCE(dwi.volume, 0)
                 WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                 WHEN seg_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_count.cnt
                 ELSE COALESCE(dwi.volume, 0)
               END::numeric AS amount
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND seg.id IS NOT NULL
            AND ((seg.pk_start + seg.pk_end) / 2.0) >= LEAST(csv.pk_start, csv.pk_end)
            AND ((seg.pk_start + seg.pk_end) / 2.0) < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
          END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE(cs_report.id, cs_override.id, effective_section.section_id)
         AND cs_eff.is_active IS NOT FALSE
        WHERE {' AND '.join(where)}
        ORDER BY dwi.report_date DESC, wt.name, obj.name NULLS LAST
        LIMIT %s
        """,
        [*params, raw_scan_limit],
    )

    rules = _general_report_work_rules()
    row_labels = {
        str(row.get("code") or "").strip(): str(row.get("label") or row.get("code") or "").strip()
        for row in _general_report_work_rules()
        if str(row.get("code") or "").strip()
    }
    for row in _default_general_report_work_rows():
        code = str(row.get("code") or "").strip()
        if code and code not in row_labels:
            row_labels[code] = str(row.get("label") or code).strip()

    summary = {
        key: {"status": key, "label": {"matched": "Явно настроено", "implicit": "Поймано типовой логикой", "unresolved": "Неразобрано"}[key], "row_count": 0, "total_volume": 0.0}
        for key in valid_statuses
    }
    out: list[dict] = []
    truncated = False

    for row in rows:
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        matched_rule = _general_matching_work_rule(
            rules,
            row.get("analytics_tag"),
            row.get("object_type_code"),
            row.get("object_code"),
            source_bucket,
        )
        implicit_code = _general_work_category(
            row.get("analytics_tag"),
            row.get("work_type_code"),
            row.get("object_type_code"),
            row.get("object_code"),
        )
        if matched_rule:
            status_key = "matched"
            resolved_code = str(matched_rule.get("code") or "").strip() or None
            resolved_label = str(matched_rule.get("label") or row_labels.get(resolved_code or "") or resolved_code or "").strip() or None
        elif implicit_code:
            status_key = "implicit"
            resolved_code = implicit_code
            resolved_label = row_labels.get(implicit_code) or implicit_code
        else:
            status_key = "unresolved"
            resolved_code = None
            resolved_label = None

        amount = float(row.get("amount") or 0)
        summary[status_key]["row_count"] += 1
        summary[status_key]["total_volume"] += amount

        if status_key not in selected_statuses:
            continue
        if len(out) >= limit:
            truncated = True
            continue

        out.append({
            "id": row.get("id"),
            "date": row["report_date"].isoformat() if row.get("report_date") else None,
            "section_code": _merge_section(row.get("section_code")) or row.get("section_code") or "—",
            "status": status_key,
            "status_label": summary[status_key]["label"],
            "label": row.get("analytics_tag") or row.get("work_type_name") or "Работа",
            "work_type_name": row.get("work_type_name") or "—",
            "work_type_code": row.get("work_type_code") or None,
            "object_name": row.get("object_name") or row.get("object_type_name") or "—",
            "object_code": row.get("object_code") or None,
            "object_type_code": row.get("object_type_code") or None,
            "object_type_name": row.get("object_type_name") or "—",
            "resolved_code": resolved_code,
            "resolved_label": resolved_label,
            "source_bucket": source_bucket,
            "contractor_name": row.get("contractor_name") or "—",
            "shift": row.get("shift"),
            "unit": row.get("unit") or "—",
            "volume": round(amount, 2),
        })

    return {
        "from": d_from.isoformat(),
        "to": d_to.isoformat(),
        "limit": limit,
        "statuses": [value for value in valid_statuses if value in selected_statuses],
        "truncated": truncated,
        "summary": [
            {
                **summary[key],
                "total_volume": round(float(summary[key]["total_volume"] or 0), 2),
            }
            for key in valid_statuses
        ],
        "rows": out,
    }


