@router.put("/generator/general-report-config")
def save_generator_general_report_config(
    body: GeneralReportWorkRulesBody,
    manager=Depends(require_settings_manager),
):
    _ensure_dashboard_settings_schema()
    raw_rows = [row.model_dump() for row in body.rows]
    raw_blocks = [block.model_dump() for block in body.blocks]
    config = _normalize_general_report_config({"rows": raw_rows, "blocks": raw_blocks})
    payload = {"version": 2, "rows": config["rows"], "blocks": config["blocks"]}
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO dashboard_settings (key, payload, updated_by, updated_at)
                    VALUES (%s, %s::jsonb, %s, now())
                    ON CONFLICT (key) DO UPDATE
                    SET payload = EXCLUDED.payload,
                        updated_by = EXCLUDED.updated_by,
                        updated_at = now()
                    RETURNING updated_at
                    """,
                    (GENERAL_REPORT_CONFIG_KEY, json.dumps(payload, ensure_ascii=False), manager.username),
                )
                updated_at = cur.fetchone()[0]
        _general_report_config.cache_clear()
        return {
            **config,
            "quarry_options": _general_report_quarry_options(),
            "source_options": _general_report_source_options(),
            "material_options": _general_report_material_options(),
            "movement_options": _general_report_movement_options(),
            "equipment_options": _general_report_equipment_options(),
            "object_options": _general_report_object_options(),
            "updated_by": manager.username,
            "updated_at": updated_at.isoformat() if hasattr(updated_at, "isoformat") else updated_at,
        }
    finally:
        conn.close()


