@router.post("/generator/pipeline-export-jobs")
def generator_pipeline_export_job(body: GeneratorPipelineExportBody, _user=Depends(current_user)):
    if body.report_key not in BACKGROUND_XLSX_PIPELINE_REPORT_KEYS:
        raise HTTPException(400, f"Background XLSX export is not supported for {body.report_key}")
    d_from, d_to = _parse_range(body.date_from, body.date_to)
    if d_from > d_to:
        raise HTTPException(400, "Период указан наоборот: дата начала должна быть не позже даты окончания. Накопительный итог в XLSX считается отдельно, от первого факта до последнего факта.")
    cumulative_as_of_end_date = (
        body.report_key in CUMULATIVE_AS_OF_END_DATE_XLSX_REPORT_KEYS
        and _cumulative_as_of_end_date_from_body(body)
    )
    filter_env = _pipeline_filter_env_from_body(
        body,
        cumulative_as_of_end_date=cumulative_as_of_end_date,
    )
    general_equipment_plan_counts = _normalize_general_equipment_plan_counts(body.general_equipment_plan_counts)
    info = _xlsx_pipeline_job_info(
        body.report_key,
        d_from,
        d_to,
        filter_env=filter_env,
        section_codes=_section_codes_from_body(body.section_codes),
        general_equipment_plan_counts=general_equipment_plan_counts,
        cumulative_as_of_end_date=cumulative_as_of_end_date,
    )
    job_id = str(info["job_id"])
    artifact = Path(str(info["artifact"]))
    meta_path = Path(str(info["meta_path"]))
    if _cached_xlsx_ready(artifact, meta_path, str(info["fingerprint"])):
        job = {
            **info,
            "status": "ready",
            "message": "Файл найден в кеше",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "finished_at": datetime.now(timezone.utc).isoformat(),
        }
        with XLSX_EXPORT_JOBS_LOCK:
            XLSX_EXPORT_JOBS[job_id] = job
        return _xlsx_export_job_response(job)

    should_start = False
    with XLSX_EXPORT_JOBS_LOCK:
        existing = XLSX_EXPORT_JOBS.get(job_id)
        if existing and existing.get("status") in {"queued", "running"}:
            return _xlsx_export_job_response(existing)
        if existing and existing.get("status") == "ready" and _cached_xlsx_ready(artifact, meta_path, str(info["fingerprint"])):
            return _xlsx_export_job_response(existing)
        job = {
            **info,
            "status": "queued",
            "message": "Файл поставлен в очередь генерации",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "error": None,
        }
        XLSX_EXPORT_JOBS[job_id] = job
        should_start = True
    if should_start:
        thread = threading.Thread(target=_run_xlsx_export_job, args=(job_id,), daemon=True)
        thread.start()
    return _xlsx_export_job_response(job)


@router.get("/generator/pipeline-export-jobs/{job_id}")
def generator_pipeline_export_job_status(job_id: str, _user=Depends(current_user)):
    with XLSX_EXPORT_JOBS_LOCK:
        job = XLSX_EXPORT_JOBS.get(job_id)
        if not job:
            raise HTTPException(404, "Export job not found")
        return _xlsx_export_job_response(job)


@router.get("/generator/pipeline-export-jobs/{job_id}/download")
def generator_pipeline_export_job_download(job_id: str, _user=Depends(current_user)):
    with XLSX_EXPORT_JOBS_LOCK:
        job = dict(XLSX_EXPORT_JOBS.get(job_id) or {})
    if not job:
        raise HTTPException(404, "Export job not found")
    if job.get("status") != "ready":
        raise HTTPException(409, "Export file is not ready yet")
    artifact = Path(str(job.get("artifact") or ""))
    meta_path = Path(str(job.get("meta_path") or ""))
    if not _cached_xlsx_ready(artifact, meta_path, str(job.get("fingerprint") or "")):
        raise HTTPException(404, "Cached export file is missing or stale")
    return FileResponse(
        str(artifact),
        media_type=str(job.get("media_type") or XLSX_MEDIA_TYPE),
        headers=_attachment_headers(str(job.get("filename_ascii") or "report.xlsx"), str(job.get("filename_utf8") or "report.xlsx")),
    )


def _generate_generator_pipeline_content(
    report_key: str,
    d_from: date_cls,
    d_to: date_cls,
    *,
    section_codes: Optional[list[str]] = None,
    filter_env: Optional[dict[str, str]] = None,
    cumulative_as_of_end_date: bool = False,
    general_equipment_plan_counts: Optional[dict[str, dict[str, dict[str, float]]]] = None,
) -> tuple[bytes, str, str, str]:
    if report_key not in GENERATOR_PIPELINE_REPORTS:
        raise HTTPException(400, f"Unknown report pipeline: {report_key}")
    codes = section_codes
    if report_key == "temp_roads":
        content, filename_ascii, filename_utf8 = _generate_temp_roads_pipeline_pdf(d_to)
        media_type = "application/pdf"
    elif report_key == "temp_roads_tsm_xlsx":
        content, filename_ascii, filename_utf8 = _generate_temp_roads_tsm_pipeline_xlsx(d_to)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "reinforcement_sections":
        content, filename_ascii, filename_utf8 = _generate_reinforcement_pipeline_pdf(d_to)
        media_type = "application/pdf"
    elif report_key == "isso_support":
        content, filename_ascii, filename_utf8 = _generate_isso_support_pipeline_pdf(d_to)
        media_type = "application/pdf"
    elif report_key == "mainline_structural_scheme":
        content, filename_ascii, filename_utf8 = _generate_mainline_structural_scheme_pipeline_pdf(d_to, codes)
        media_type = "application/pdf"
    elif report_key == "dim":
        content, filename_ascii, filename_utf8 = _generate_dim_pipeline_xlsx(
            d_from,
            d_to,
            filter_env=filter_env,
            cumulative_as_of_end_date=cumulative_as_of_end_date,
        )
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "mstroy":
        content, filename_ascii, filename_utf8 = _generate_mstroy_pipeline_xlsx(
            d_from,
            d_to,
            filter_env=filter_env,
            cumulative_as_of_end_date=cumulative_as_of_end_date,
        )
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "mstroy_graph":
        content, filename_ascii, filename_utf8 = _generate_mstroy_graph_pipeline_xlsx(
            d_from,
            d_to,
            filter_env=filter_env,
            cumulative_as_of_end_date=cumulative_as_of_end_date,
        )
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "general":
        content, filename_ascii, filename_utf8 = _generate_general_pipeline_xlsx(
            d_from,
            d_to,
            filter_env=filter_env,
            cumulative_as_of_end_date=cumulative_as_of_end_date,
        )
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "simple_section_report":
        content, filename_ascii, filename_utf8 = _generate_simple_section_pipeline_xlsx(d_from, d_to, codes)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "transport_section_report":
        content, filename_ascii, filename_utf8 = _generate_transport_section_pipeline_xlsx(d_from, d_to, codes)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "financial_plan_fact":
        content, filename_ascii, filename_utf8 = _generate_financial_plan_fact_pipeline_xlsx(d_from, d_to, codes)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "equipment":
        content, filename_ascii, filename_utf8 = _generate_equipment_pipeline_xlsx(d_to, d_to, codes)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "pile_daily_breakdown":
        content, filename_ascii, filename_utf8 = _generate_pile_daily_breakdown_pipeline_xlsx(d_from, d_to)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "general_exact_pdf":
        content, filename_ascii, filename_utf8 = _generate_general_analytics_main_table_report(
            d_to,
            codes,
            "pdf",
            manual_equipment_plan_counts=general_equipment_plan_counts,
        )
        media_type = "application/pdf"
    elif report_key == "general_exact_xlsx":
        content, filename_ascii, filename_utf8 = _generate_general_analytics_main_table_report(
            d_to,
            codes,
            "xlsx",
            manual_equipment_plan_counts=general_equipment_plan_counts,
        )
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    elif report_key == "admin_dumptruck":
        content, filename_ascii, filename_utf8 = _generate_admin_dumptruck_pipeline_xlsx(d_to)
        media_type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    else:
        raise HTTPException(400, f"Unknown report pipeline: {report_key}")
    return content, filename_ascii, filename_utf8, media_type


@router.post("/generator/pipeline-export")
def generator_pipeline_export(body: GeneratorPipelineExportBody, _user=Depends(current_user)):
    if body.report_key not in GENERATOR_PIPELINE_REPORTS:
        raise HTTPException(400, f"Unknown report pipeline: {body.report_key}")
    d_from, d_to = _parse_range(body.date_from, body.date_to)
    if d_from > d_to:
        raise HTTPException(400, "Период указан наоборот: дата начала должна быть не позже даты окончания. Накопительный итог в XLSX считается отдельно, от первого факта до последнего факта.")
    codes = _section_codes_from_body(body.section_codes)

    cumulative_as_of_end_date = (
        body.report_key in CUMULATIVE_AS_OF_END_DATE_XLSX_REPORT_KEYS
        and _cumulative_as_of_end_date_from_body(body)
    )
    filter_env = _pipeline_filter_env_from_body(
        body,
        cumulative_as_of_end_date=cumulative_as_of_end_date,
    )
    general_equipment_plan_counts = _normalize_general_equipment_plan_counts(body.general_equipment_plan_counts)

    content, filename_ascii, filename_utf8, media_type = _generate_generator_pipeline_content(
        body.report_key,
        d_from,
        d_to,
        section_codes=codes,
        filter_env=filter_env,
        cumulative_as_of_end_date=cumulative_as_of_end_date,
        general_equipment_plan_counts=general_equipment_plan_counts,
    )

    return Response(
        content=content,
        media_type=media_type,
        headers=_attachment_headers(filename_ascii, filename_utf8),
    )


@router.post("/generator/export")
def generator_export(body: GeneratorExportBody, _user=Depends(current_user)):
    report_types = [rt for rt in body.report_types if rt in GENERATOR_REPORT_TYPES]
    if not report_types:
        raise HTTPException(400, "Choose at least one report type")
    d_from, d_to = _parse_range(body.date_from, body.date_to)
    codes = _section_codes_from_body(body.section_codes)

    wb = Workbook()
    wb.remove(wb.active)
    header_fill = PatternFill("solid", fgColor="1F2937")
    header_font = Font(color="FFFFFF", bold=True)

    for report_type in report_types:
        spec = GENERATOR_REPORT_TYPES[report_type]
        columns = _allowed_columns(report_type, body.columns)
        rows = _rows_for_generator(report_type, d_from, d_to, codes)
        ws = wb.create_sheet(title=str(spec["label"])[:31])
        ws.append([c["label"] for c in columns])
        for cell in ws[1]:
            cell.fill = header_fill
            cell.font = header_font
        for row in rows:
            ws.append([row.get(c["key"], "") for c in columns])
        for idx, column in enumerate(columns, start=1):
            width = max(len(str(column["label"])) + 2, 14)
            for cell in ws.iter_cols(min_col=idx, max_col=idx, min_row=2):
                for value_cell in cell:
                    width = min(max(width, len(str(value_cell.value or "")) + 2), 42)
            ws.column_dimensions[ws.cell(row=1, column=idx).column_letter].width = width
        ws.freeze_panes = "A2"

    bio = BytesIO()
    wb.save(bio)
    bio.seek(0)
    filename = f"vsm_generator_{d_from.isoformat()}_{d_to.isoformat()}.xlsx"
    headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    return StreamingResponse(
        bio,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers=headers,
    )



# ── reference deduplication ────────────────────────────────────────────────

_DEDUP_KIND_META = {
    "work_type": {
        "table": "work_types",
        "code": "code",
        "label": "name",
        "extra": "default_unit, analytics_tag, COALESCE(is_active, true) AS is_active, review_tag",
        "fk": [
            ("daily_work_items", "work_type_id"),
            ("planned_work_items", "work_type_id"),
            ("project_work_items", "work_type_id"),
            ("constructive_work_types", "work_type_id"),
            ("object_type_work_type_defaults", "work_type_id"),
            ("pipe_pile_specs", "work_type_id"),
        ],
    },
    "material": {
        "table": "materials",
        "code": "code",
        "label": "name",
        "extra": "default_unit, review_tag",
        "fk": [
            ("material_movements", "material_id"),
            ("stockpiles", "material_id"),
        ],
    },
    "object": {
        "table": "objects",
        "code": "object_code",
        "label": "name",
        "extra": "is_active, review_tag",
        "fk": [
            ("constructives", "object_id"),
            ("daily_work_items", "object_id"),
            ("isso_front_transfer_lines", "object_id"),
            ("isso_object_front_attributes", "object_id"),
            ("material_movements", "from_object_id"),
            ("material_movements", "to_object_id"),
            ("object_map_points", "object_id"),
            ("object_segments", "object_id"),
            ("pile_fields", "object_id"),
            ("pipe_pile_specs", "object_id"),
            ("planned_work_items", "object_id"),
            ("project_work_items", "object_id"),
            ("section_quarry_haul_distances", "quarry_object_id"),
            ("stockpiles", "object_id"),
            ("temporary_road_status_segments", "object_id"),
            ("temporary_roads", "object_id"),
        ],
    },
}


class ReferenceDedupMigrateBody(BaseModel):
    kind: str
    target_id: str
    source_ids: list[str]
    include_tables: Optional[list[str]] = None
    delete_sources: bool = True


def _dedup_normalize_text(value: object) -> str:
    text = str(value or "").strip().lower().replace("ё", "е")
    text = re.sub(r"[\"'«»“”„.,;:/\\()\[\]{}]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def _dedup_compact_text(value: object) -> str:
    return re.sub(r"[^0-9a-zа-я]+", "", _dedup_normalize_text(value))


def _dedup_meta(kind: str) -> dict:
    meta = _DEDUP_KIND_META.get((kind or "").strip())
    if not meta:
        raise HTTPException(400, "kind must be work_type, material or object")
    return meta


def _ensure_reference_dedup_audit_table(cur) -> None:
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS reference_dedup_audit (
            id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
            kind text NOT NULL,
            source_code text,
            source_id uuid,
            source_label text,
            target_code text,
            target_id uuid,
            target_label text,
            operation text NOT NULL,
            counts jsonb NOT NULL DEFAULT '{}'::jsonb,
            notes text,
            created_at timestamptz NOT NULL DEFAULT now(),
            created_by text
        )
        """
    )


def _dedup_reference_by_id(kind: str, ref_id: str) -> dict:
    meta = _dedup_meta(kind)
    extra_sql = f", {meta['extra']}" if meta.get("extra") else ""
    row = query_one(
        f"""
        SELECT id::text AS id,
               {meta['code']} AS code,
               {meta['label']} AS label
               {extra_sql}
        FROM {meta['table']}
        WHERE id = %s::uuid
        LIMIT 1
        """,
        (ref_id,),
    )
    if not row:
        raise HTTPException(404, "Справочник не найден")
    row["ref_count"] = sum(_dedup_reference_counts(kind, ref_id).values())
    return row


def _dedup_reference_counts(kind: str, ref_id: str) -> dict[str, int]:
    meta = _dedup_meta(kind)
    counts: dict[str, int] = {}
    for table_name, column_name in meta["fk"]:
        try:
            row = query_one(f"SELECT COUNT(*)::int AS cnt FROM {table_name} WHERE {column_name} = %s::uuid", (ref_id,))
        except Exception:
            row = {"cnt": 0}
        counts[f"{table_name}.{column_name}"] = int((row or {}).get("cnt") or 0)
    return counts


def _dedup_reference_search(kind: str, q: Optional[str], limit: int = 40) -> list[dict]:
    meta = _dedup_meta(kind)
    safe_limit = max(1, min(int(limit or 40), 120))
    text = _dedup_normalize_text(q)
    compact = _dedup_compact_text(q)
    extra_sql = f", {meta['extra']}" if meta.get("extra") else ""
    params: list = []
    where = "code NOT LIKE 'POVSR\\_%%' ESCAPE '\\'" if kind == "work_type" else "1=1"
    search_sql = f"LOWER(CONCAT_WS(' ', {meta['code']}, {meta['label']}))"
    compact_sql = f"regexp_replace(LOWER(CONCAT_WS('', {meta['code']}, {meta['label']})), '[^0-9a-zа-я]+', '', 'g')"
    score_sql = "0"
    score_params: list = []
    where_params: list = []
    if text:
        tokens = [token for token in text.split() if token]
        clauses = []
        score_parts = []
        for token in tokens:
            pattern = f"%{token}%"
            clauses.append(f"{search_sql} LIKE %s")
            where_params.append(pattern)
            score_parts.append(f"CASE WHEN {search_sql} LIKE %s THEN 1 ELSE 0 END")
            score_params.append(pattern)
        if compact:
            pattern = f"%{compact}%"
            clauses.append(f"{compact_sql} LIKE %s")
            where_params.append(pattern)
            score_parts.append(f"CASE WHEN {compact_sql} LIKE %s THEN 2 ELSE 0 END")
            score_params.append(pattern)
        score_parts.append(f"CASE WHEN {search_sql} = %s THEN 100 ELSE 0 END")
        score_params.append(text)
        score_sql = " + ".join(score_parts)
        where = f"({where}) AND (" + " OR ".join(clauses) + ")"
    params.extend(score_params)
    params.extend(where_params)
    params.append(safe_limit)
    rows = query(
        f"""
        SELECT id::text AS id,
               {meta['code']} AS code,
               {meta['label']} AS label,
               ({score_sql})::int AS score
               {extra_sql}
        FROM {meta['table']}
        WHERE {where}
        ORDER BY score DESC, lower({meta['label']}), {meta['code']}
        LIMIT %s
        """,
        params,
    )
    for row in rows:
        row["ref_count"] = sum(_dedup_reference_counts(kind, row["id"]).values())
    return rows


@router.get("/settings/dedup/references")
def settings_dedup_references(kind: str, q: str = "", limit: int = 40, _user=Depends(current_user)):
    return {"rows": _dedup_reference_search(kind, q, limit)}


@router.get("/settings/dedup/preview")
def settings_dedup_preview(kind: str, source_id: str, target_id: str, _user=Depends(current_user)):
    source = _dedup_reference_by_id(kind, source_id)
    target = _dedup_reference_by_id(kind, target_id)
    return {
        "kind": kind,
        "source": source,
        "target": target,
        "source_counts": _dedup_reference_counts(kind, source_id),
        "target_counts": _dedup_reference_counts(kind, target_id),
    }


@router.delete("/settings/dedup/references/{kind}/{ref_id}")
def settings_dedup_delete_reference(kind: str, ref_id: str, _admin=Depends(require_admin)):
    meta = _dedup_meta(kind)
    reference = _dedup_reference_by_id(kind, ref_id)
    counts = _dedup_reference_counts(kind, ref_id)
    ref_total = sum(int(value or 0) for value in counts.values())
    if ref_total:
        raise HTTPException(400, f"Нельзя удалить: есть ссылки или фактические значения ({ref_total})")
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '5s'")
                _ensure_reference_dedup_audit_table(cur)
                alias_deleted = 0
                if kind in _ALIAS_KINDS and reference.get("code"):
                    cur.execute(
                        "DELETE FROM work_type_aliases WHERE kind = %s AND canonical_code = %s",
                        (kind, reference.get("code")),
                    )
                    alias_deleted = cur.rowcount
                cur.execute(f"DELETE FROM {meta['table']} WHERE id = %s::uuid", (ref_id,))
                deleted = cur.rowcount
                if not deleted:
                    raise HTTPException(404, "Справочник не найден")
                audit_counts = dict(counts)
                audit_counts["aliases_deleted"] = alias_deleted
                audit_counts["deleted"] = deleted
                cur.execute(
                    """
                    INSERT INTO reference_dedup_audit (
                        kind, source_code, source_id, source_label,
                        operation, counts, notes, created_by
                    ) VALUES (%s, %s, %s::uuid, %s, %s, %s::jsonb, %s, %s)
                    """,
                    (
                        kind,
                        reference.get("code"),
                        ref_id,
                        reference.get("label"),
                        "delete_empty_reference",
                        json.dumps(audit_counts, ensure_ascii=False),
                        "manual empty reference delete from settings",
                        "web",
                    ),
                )
                return {"ok": True, "deleted": deleted, "aliases_deleted": alias_deleted, "reference": reference}
    finally:
        conn.close()


def _dedup_update_aliases(cur, kind: str, source_code: Optional[str], source_label: Optional[str], target_code: Optional[str]) -> int:
    if kind not in _ALIAS_KINDS or not target_code:
        return 0
    updated = 0
    if source_code:
        cur.execute(
            "UPDATE work_type_aliases SET canonical_code = %s WHERE kind = %s AND canonical_code = %s",
            (target_code, kind, source_code),
        )
        updated += cur.rowcount
    for alias in (source_code, source_label):
        alias_text = str(alias or "").strip()
        if not alias_text:
            continue
        cur.execute(
            """
            UPDATE work_type_aliases
            SET canonical_code = %s,
                kind = %s,
                notes = COALESCE(work_type_aliases.notes, 'dedup source label')
            WHERE alias_text = %s
            """,
            (target_code, kind, alias_text),
        )
        if cur.rowcount:
            continue
        cur.execute(
            """
            INSERT INTO work_type_aliases (canonical_code, alias_text, kind, notes)
            VALUES (%s, %s, %s, 'dedup source label')
            ON CONFLICT DO NOTHING
            """,
            (target_code, alias_text, kind),
        )
    return updated


def _dedup_merge_work_type_special(cur, source_id: str, target_id: str, target_tag: Optional[str], include: set[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    if "constructive_work_types.work_type_id" in include:
        cur.execute(
            """
            DELETE FROM constructive_work_types src
            WHERE src.work_type_id = %s::uuid
              AND EXISTS (
                SELECT 1 FROM constructive_work_types tgt
                WHERE tgt.constructive_id = src.constructive_id
                  AND tgt.work_type_id = %s::uuid
              )
            """,
            (source_id, target_id),
        )
        counts["constructive_work_types.conflicts_deleted"] = cur.rowcount
    if "pipe_pile_specs.work_type_id" in include:
        cur.execute(
            """
            UPDATE pipe_pile_specs tgt
            SET quantity = COALESCE(tgt.quantity, 0) + COALESCE(src.quantity, 0)
            FROM pipe_pile_specs src
            WHERE src.work_type_id = %s::uuid
              AND tgt.work_type_id = %s::uuid
              AND tgt.object_id = src.object_id
              AND tgt.pile_length_m = src.pile_length_m
              AND tgt.source_reference IS NOT DISTINCT FROM src.source_reference
            """,
            (source_id, target_id),
        )
        counts["pipe_pile_specs.conflicts_merged"] = cur.rowcount
        cur.execute(
            """
            DELETE FROM pipe_pile_specs src
            WHERE src.work_type_id = %s::uuid
              AND EXISTS (
                SELECT 1 FROM pipe_pile_specs tgt
                WHERE tgt.work_type_id = %s::uuid
                  AND tgt.object_id = src.object_id
                  AND tgt.pile_length_m = src.pile_length_m
                  AND tgt.source_reference IS NOT DISTINCT FROM src.source_reference
              )
            """,
            (source_id, target_id),
        )
        counts["pipe_pile_specs.conflicts_deleted"] = cur.rowcount
    if "daily_work_items.work_type_id" in include:
        cur.execute(
            """
            UPDATE daily_work_items
            SET work_type_id = %s::uuid,
                analytics_tag = COALESCE(NULLIF(analytics_tag, ''), %s)
            WHERE work_type_id = %s::uuid
            """,
            (target_id, target_tag, source_id),
        )
        counts["daily_work_items.work_type_id"] = cur.rowcount
    return counts


@router.post("/settings/dedup/migrate")
def settings_dedup_migrate(body: ReferenceDedupMigrateBody, _admin=Depends(require_admin)):
    kind = (body.kind or "").strip()
    meta = _dedup_meta(kind)
    if not body.source_ids:
        raise HTTPException(400, "source_ids is required")
    source_ids = [str(value).strip() for value in body.source_ids if str(value or "").strip()]
    target_id = str(body.target_id or "").strip()
    if not target_id:
        raise HTTPException(400, "target_id is required")
    if target_id in source_ids:
        raise HTTPException(400, "target_id cannot be in source_ids")
    allowed = {f"{table}.{column}" for table, column in meta["fk"]}
    include = set(body.include_tables or allowed)
    unknown = include - allowed
    if unknown:
        raise HTTPException(400, f"Unknown include_tables: {sorted(unknown)}")
    target = _dedup_reference_by_id(kind, target_id)
    target_tag = target.get("analytics_tag") if kind == "work_type" else None
    result = {"kind": kind, "target": target, "sources": []}
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '5s'")
                cur.execute("SET LOCAL statement_timeout = '120s'")
                _ensure_reference_dedup_audit_table(cur)
                for source_id in source_ids:
                    source = _dedup_reference_by_id(kind, source_id)
                    counts: dict[str, int] = {}
                    counts["aliases_updated"] = _dedup_update_aliases(cur, kind, source.get("code"), source.get("label"), target.get("code"))
                    if kind == "work_type":
                        counts.update(_dedup_merge_work_type_special(cur, source_id, target_id, target_tag, include))
                    for table_name, column_name in meta["fk"]:
                        key = f"{table_name}.{column_name}"
                        if key not in include:
                            continue
                        if kind == "work_type" and key == "daily_work_items.work_type_id":
                            continue
                        cur.execute(
                            f"UPDATE {table_name} SET {column_name} = %s::uuid WHERE {column_name} = %s::uuid",
                            (target_id, source_id),
                        )
                        counts[key] = cur.rowcount
                    remaining = {}
                    for table_name, column_name in meta["fk"]:
                        cur.execute(f"SELECT COUNT(*)::int FROM {table_name} WHERE {column_name} = %s::uuid", (source_id,))
                        remaining[f"{table_name}.{column_name}"] = cur.fetchone()[0]
                    counts["remaining_refs"] = sum(int(value or 0) for value in remaining.values())
                    deleted = 0
                    if body.delete_sources and counts["remaining_refs"] == 0:
                        cur.execute(f"DELETE FROM {meta['table']} WHERE id = %s::uuid", (source_id,))
                        deleted = cur.rowcount
                    counts["deleted"] = deleted
                    cur.execute(
                        """
                        INSERT INTO reference_dedup_audit (
                            kind, source_code, source_id, source_label,
                            target_code, target_id, target_label,
                            operation, counts, notes, created_by
                        ) VALUES (%s, %s, %s::uuid, %s, %s, %s::uuid, %s, %s, %s::jsonb, %s, %s)
                        """,
                        (
                            kind,
                            source.get("code"),
                            source_id,
                            source.get("label"),
                            target.get("code"),
                            target_id,
                            target.get("label"),
                            "merge_and_delete" if body.delete_sources else "merge",
                            json.dumps(counts, ensure_ascii=False),
                            "manual settings dedup",
                            getattr(_admin, "username", None) or "admin",
                        ),
                    )
                    result["sources"].append({"source": source, "counts": counts, "remaining": remaining})
    finally:
        conn.close()
    _refresh_norms()
    _invalidate_dashboard_response_cache("settings_dedup_migrate")
    return result


# ── aliases CRUD ──────────────────────────────────────────────────────────

_ALIAS_KINDS = {"work_type", "material", "object"}
_RD_INTAKE_ALIAS_SHEET_NAMES = {"_vsm_aliases", "vsm_aliases", "aliases", "алиасы"}


def _rd_intake_alias_header_key(value: object) -> str:
    text = re.sub(r"\s+", " ", str(value or "").replace(" ", " ")).strip().lower()
    return {
        "kind": "kind",
        "тип": "kind",
        "тип сущности": "kind",
        "alias": "alias_text",
        "alias_text": "alias_text",
        "алиас": "alias_text",
        "текст алиаса": "alias_text",
        "canonical_code": "canonical_code",
        "code": "canonical_code",
        "код": "canonical_code",
        "канонический код": "canonical_code",
        "source": "source",
        "источник": "source",
    }.get(text, text)


def _rd_intake_alias_rows_from_workbook(wb) -> list[dict[str, str]]:
    sheet = None
    for sheet_name in wb.sheetnames:
        if str(sheet_name or "").strip().lower() in _RD_INTAKE_ALIAS_SHEET_NAMES:
            sheet = wb[sheet_name]
            break
    if sheet is None or sheet.max_row < 2:
        return []

    raw_headers = [cell.value for cell in sheet[1]]
    headers = [_rd_intake_alias_header_key(value) for value in raw_headers]
    try:
        kind_idx = headers.index("kind")
        alias_idx = headers.index("alias_text")
        canonical_idx = headers.index("canonical_code")
    except ValueError:
        return []
    source_idx = headers.index("source") if "source" in headers else None

    result: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for values in sheet.iter_rows(min_row=2, values_only=True):
        kind = str(values[kind_idx] if kind_idx < len(values) else "").strip()
        alias_text = re.sub(r"\s+", " ", str(values[alias_idx] if alias_idx < len(values) else "").replace(" ", " ")).strip()
        canonical_code = str(values[canonical_idx] if canonical_idx < len(values) else "").strip()
        source = str(values[source_idx] if source_idx is not None and source_idx < len(values) else "").strip()
        if kind not in _ALIAS_KINDS or not alias_text or not canonical_code:
            continue
        if alias_text.casefold() == canonical_code.casefold():
            continue
        key = (kind, alias_text.casefold())
        if key in seen:
            continue
        seen.add(key)
        result.append({"kind": kind, "alias_text": alias_text, "canonical_code": canonical_code, "source": source or "rd_intake_result"})
    return result


def _upsert_rd_intake_aliases_from_workbook(cur, wb) -> dict[str, int]:
    counts = {"inserted": 0, "updated": 0, "skipped": 0}
    for row in _rd_intake_alias_rows_from_workbook(wb):
        kind = row["kind"]
        alias_text = row["alias_text"]
        canonical_code = row["canonical_code"]
        notes = row.get("source") or "rd_intake_result"
        cur.execute(
            """
            SELECT id::text, canonical_code, kind
            FROM work_type_aliases
            WHERE lower(alias_text) = lower(%s)
            LIMIT 1
            """,
            (alias_text,),
        )
        existing = cur.fetchone()
        if existing:
            alias_id, existing_code, existing_kind = existing
            if str(existing_code or "") == canonical_code and str(existing_kind or "") == kind:
                counts["skipped"] += 1
                continue
            cur.execute(
                """
                SELECT 1
                FROM work_type_aliases
                WHERE id <> %s::uuid
                  AND canonical_code = %s
                  AND kind = %s
                  AND regexp_replace(replace(lower(btrim(alias_text)), 'ё', 'е'), '\\s+', ' ', 'g')
                      = regexp_replace(replace(lower(btrim(%s)), 'ё', 'е'), '\\s+', ' ', 'g')
                LIMIT 1
                """,
                (alias_id, canonical_code, kind, alias_text),
            )
            if cur.fetchone():
                counts["skipped"] += 1
                continue
            cur.execute(
                """
                UPDATE work_type_aliases
                SET canonical_code = %s,
                    alias_text = %s,
                    kind = %s,
                    notes = %s
                WHERE id = %s::uuid
                """,
                (canonical_code, alias_text, kind, notes, alias_id),
            )
            counts["updated"] += cur.rowcount
            continue
        cur.execute(
            """
            INSERT INTO work_type_aliases (canonical_code, alias_text, kind, notes)
            VALUES (%s, %s, %s, %s)
            ON CONFLICT DO NOTHING
            RETURNING TRUE AS inserted
            """,
            (canonical_code, alias_text, kind, notes),
        )
        inserted = bool((cur.fetchone() or [False])[0])
        if inserted:
            counts["inserted"] += 1
        else:
            counts["skipped"] += 1
    return counts


class AliasCreateBody(BaseModel):
    canonical_code: str
    alias_text: str
    kind: str
    notes: Optional[str] = None


class AliasPatchBody(BaseModel):
    canonical_code: Optional[str] = None
    alias_text: Optional[str] = None
    kind: Optional[str] = None
    notes: Optional[str] = None


def _alias_owner_label(kind: str, canonical_code: str) -> str:
    table_sql = {
        "work_type": ("work_types", "code"),
        "material": ("materials", "code"),
        "object": ("objects", "object_code"),
    }.get(kind)
    if not table_sql:
        return canonical_code
    table_name, code_column = table_sql
    try:
        row = query_one(
            f"SELECT name FROM {table_name} WHERE {code_column} = %s LIMIT 1",
            (canonical_code,),
        )
    except Exception:
        row = None
    name = (row or {}).get("name") if row else None
    return f"{canonical_code} / {name}" if name else canonical_code


def _find_alias_by_text(alias_text: str, exclude_id: Optional[str] = None) -> Optional[dict]:
    if exclude_id:
        return query_one(
            """
            SELECT id::text AS id, canonical_code, alias_text, kind, notes
            FROM work_type_aliases
            WHERE lower(alias_text) = lower(%s) AND id <> %s::uuid
            LIMIT 1
            """,
            (alias_text, exclude_id),
        )
    return query_one(
        """
        SELECT id::text AS id, canonical_code, alias_text, kind, notes
        FROM work_type_aliases
        WHERE lower(alias_text) = lower(%s)
        LIMIT 1
        """,
        (alias_text,),
    )


def _raise_alias_conflict(existing: dict) -> None:
    owner = _alias_owner_label(existing["kind"], existing["canonical_code"])
    raise HTTPException(
        409,
        (
            f"Алиас «{existing['alias_text']}» уже привязан: "
            f"{existing['kind']} {owner}. Измените существующий алиас "
            "или используйте другой текст."
        ),
    )


@router.get("/settings/aliases")
def list_aliases():
    try:
        _ensure_settings_tables()
        _seed_aliases_if_empty()
    except Exception:
        pass
    rows = query(
        "SELECT id::text AS id, canonical_code, alias_text, kind, notes, "
        "created_at FROM work_type_aliases "
        "WHERE kind <> 'work_type' OR canonical_code NOT LIKE 'POVSR\\_%%' ESCAPE '\\' "
        "ORDER BY kind, canonical_code, alias_text"
    )
    return {
        "rows": [
            {
                "id": r["id"],
                "canonical_code": r["canonical_code"],
                "alias_text": r["alias_text"],
                "kind": r["kind"],
                "notes": r["notes"],
                "created_at": r["created_at"].isoformat() if r["created_at"] else None,
            }
            for r in rows
        ]
    }


@router.post("/settings/aliases")
def create_alias(body: AliasCreateBody, _user=Depends(current_user)):
    try:
        _ensure_settings_tables()
    except Exception:
        pass
    canonical = (body.canonical_code or "").strip()
    alias_text = (body.alias_text or "").strip()
    kind = (body.kind or "").strip()
    if not canonical or not alias_text:
        raise HTTPException(400, "canonical_code and alias_text are required")
    if kind not in _ALIAS_KINDS:
        raise HTTPException(400, f"kind must be one of {sorted(_ALIAS_KINDS)}")
    existing = _find_alias_by_text(alias_text)
    if existing:
        if existing["canonical_code"] == canonical and existing["kind"] == kind:
            return {"id": existing["id"], "ok": True, "existing": True}
        _raise_alias_conflict(existing)
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                try:
                    cur.execute(
                        "INSERT INTO work_type_aliases (canonical_code, alias_text, kind, notes) "
                        "VALUES (%s, %s, %s, %s) RETURNING id::text",
                        (canonical, alias_text, kind, body.notes),
                    )
                except Exception as e:
                    raise HTTPException(409, f"Не удалось сохранить алиас: {e}")
                row = cur.fetchone()
                return {"id": row[0] if row else None, "ok": True}
    finally:
        conn.close()


@router.patch("/settings/aliases/{alias_id}")
def update_alias(alias_id: str, body: AliasPatchBody, _user=Depends(current_user)):
    fields = []
    params: list = []
    if body.canonical_code is not None:
        canonical = body.canonical_code.strip()
        if not canonical:
            raise HTTPException(400, "canonical_code is required")
        fields.append("canonical_code = %s")
        params.append(canonical)
    if body.alias_text is not None:
        alias_text = body.alias_text.strip()
        if not alias_text:
            raise HTTPException(400, "alias_text is required")
        existing = _find_alias_by_text(alias_text, exclude_id=alias_id)
        if existing:
            _raise_alias_conflict(existing)
        fields.append("alias_text = %s")
        params.append(alias_text)
    if body.kind is not None:
        if body.kind not in _ALIAS_KINDS:
            raise HTTPException(400, f"kind must be one of {sorted(_ALIAS_KINDS)}")
        fields.append("kind = %s")
        params.append(body.kind)
    if body.notes is not None:
        fields.append("notes = %s")
        params.append(body.notes)
    if not fields:
        return {"ok": True, "changed": 0}
    params.append(alias_id)
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"UPDATE work_type_aliases SET {', '.join(fields)} WHERE id = %s",
                    params,
                )
                return {"ok": True, "changed": cur.rowcount}
    finally:
        conn.close()


@router.delete("/settings/aliases/{alias_id}")
def delete_alias(alias_id: str, _user=Depends(current_user)):
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("DELETE FROM work_type_aliases WHERE id = %s", (alias_id,))
                return {"ok": True, "deleted": cur.rowcount}
    finally:
        conn.close()


# ── statements: plan/fact by object and picket range ────────────────────────

def _parse_statement_pk(value: Optional[str]) -> Optional[float]:
    if value is None:
        return None
    raw = str(value).strip()
    if not raw:
        return None
    normalized = raw.replace(",", ".")
    if re.fullmatch(r"\d+(?:\.\d+)?", normalized):
        number = float(normalized)
        return number * 100 if abs(number) < 10000 else number
    match = re.search(
        r"(?:п\s*\.?\s*к\s*\.?|pk)?\s*(\d{1,5})(?:\s*\+\s*(\d{1,3}(?:[\.,]\d+)?))?",
        raw,
        re.IGNORECASE,
    )
    if not match:
        raise HTTPException(400, f"Не удалось распознать пикетаж: {raw}")
    pk = float(match.group(1))
    plus = float((match.group(2) or "0").replace(",", "."))
    return pk * 100 + plus


def _as_float(value, digits: int = 3) -> float:
    if value is None:
        return 0.0
    try:
        return round(float(value), digits)
    except (TypeError, ValueError):
        return 0.0


def _statement_section_sort_order_value(value, section_code: Optional[str] = None) -> Optional[int]:
    try:
        if value is not None:
            return int(value)
    except (TypeError, ValueError):
        pass
    match = re.search(r"UCH[_\s-]?(\d+)", str(section_code or ""), re.IGNORECASE)
    if match:
        return int(match.group(1))
    return None


def _statement_section_sort_key(row: dict) -> tuple[int, str, str]:
    order = _statement_section_sort_order_value(row.get("section_sort_order"), row.get("section_code"))
    return (
        order if order is not None else 9999,
        str(row.get("section_code") or ""),
        str(row.get("section_name") or ""),
    )


def _statement_pk_range(value_start, value_end) -> Optional[tuple[float, float]]:
    if value_start is None and value_end is None:
        return None
    try:
        start = float(value_start if value_start is not None else value_end)
        end = float(value_end if value_end is not None else value_start)
    except (TypeError, ValueError):
        return None
    return (start, end) if start <= end else (end, start)


def _statement_clip_volume_to_section(
    item: dict,
    volume: float,
    pk_start_key: str,
    pk_end_key: str,
) -> Optional[tuple[Optional[float], Optional[float], float, bool]]:
    explicit_range = _statement_pk_range(item.get(pk_start_key), item.get(pk_end_key))
    section_range = _statement_pk_range(item.get("section_pk_start"), item.get("section_pk_end"))
    object_range = _statement_pk_range(item.get("object_pk_start"), item.get("object_pk_end"))

    if explicit_range is None:
        pk_start = item.get("section_pk_start") if item.get("section_pk_start") is not None else item.get("object_pk_start")
        pk_end = item.get("section_pk_end") if item.get("section_pk_end") is not None else item.get("object_pk_end")
        factor = 1.0
        if section_range is not None and object_range is not None:
            section_len = max(0.0, section_range[1] - section_range[0])
            object_len = max(0.0, object_range[1] - object_range[0])
            if object_len > 0 and section_len > 0 and section_len < object_len:
                factor = section_len / object_len
        return pk_start, pk_end, volume * factor, False

    if section_range is None:
        return explicit_range[0], explicit_range[1], volume, True

    raw_start, raw_end = explicit_range
    section_start, section_end = section_range
    raw_len = raw_end - raw_start
    if raw_len <= 0:
        in_section = section_start <= raw_start < section_end or abs(section_start - section_end) < 0.001 and abs(raw_start - section_start) < 0.001
        if not in_section:
            return None
        return raw_start, raw_end, volume, True

    clipped_start = max(raw_start, section_start)
    clipped_end = min(raw_end, section_end)
    if clipped_end <= clipped_start:
        return None
    factor = (clipped_end - clipped_start) / raw_len
    keep_raw_text = abs(clipped_start - raw_start) < 0.001 and abs(clipped_end - raw_end) < 0.001
    return clipped_start, clipped_end, volume * factor, keep_raw_text


def _statement_clip_manual_plan_range_to_section(
    pk_start,
    pk_end,
    section_pk_start,
    section_pk_end,
) -> tuple[Optional[float], Optional[float], bool]:
    section_range = _statement_pk_range(section_pk_start, section_pk_end)
    if section_range is None:
        return pk_start, pk_end, False
    explicit_range = _statement_pk_range(pk_start, pk_end)
    if explicit_range is None:
        return section_range[0], section_range[1], True

    raw_start, raw_end = explicit_range
    clipped_start = max(raw_start, section_range[0])
    clipped_end = min(raw_end, section_range[1])
    if clipped_end <= clipped_start:
        return pk_start, pk_end, False
    changed = abs(clipped_start - raw_start) >= 0.001 or abs(clipped_end - raw_end) >= 0.001
    return clipped_start, clipped_end, changed


def _statement_sections() -> list[dict]:
    rows = query(
        """
        SELECT code, name, sort_order
        FROM construction_sections
        WHERE is_active = true
        ORDER BY sort_order NULLS LAST, code
        """
    )
    merged: dict[str, dict] = {}
    for row in rows:
        code = _merge_section(row.get("code")) or row.get("code")
        if not code or code in merged:
            continue
        merged[code] = {
            "code": code,
            "name": row.get("name") or code,
            "sort_order": row.get("sort_order"),
        }
    return list(merged.values())


def _statement_scope_cte() -> str:
    return f"""
    WITH object_bounds AS (
      SELECT o.id,
             o.object_code,
             o.name AS object_name,
             ot.code AS object_type_code,
             ot.name AS object_type_name,
             MAX(tr.road_code) AS temp_road_code,
             MIN(LEAST(object_pk.pk_start, object_pk.pk_end)) AS object_pk_start,
             MAX(GREATEST(object_pk.pk_start, object_pk.pk_end)) AS object_pk_end
      FROM objects o
      LEFT JOIN object_types ot ON ot.id = o.object_type_id
      LEFT JOIN temporary_roads tr ON tr.object_id = o.id
      LEFT JOIN LATERAL (
        SELECT os.pk_start, os.pk_end
        FROM object_segments os
        WHERE os.object_id = o.id
        UNION ALL
        SELECT pf.pk_start, pf.pk_end
        FROM pile_fields pf
        WHERE pf.object_id = o.id
          AND COALESCE(pf.is_demo, false) IS FALSE
          AND COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded')
      ) object_pk ON true
      WHERE COALESCE(o.is_active, true) IS TRUE
      GROUP BY o.id, o.object_code, o.name, ot.code, ot.name
    ),
    main_track_section_map(object_code, section_code) AS (
      VALUES
        ('MAIN_001', 'UCH_1'),
        ('MAIN_002', 'UCH_2'),
        ('MAIN_003', 'UCH_3'),
        ('MAIN_031', 'UCH_3'),
        ('MAIN_032', 'UCH_3'),
        ('MAIN_OH_STAGE3', 'UCH_3'),
        ('MAIN_004', 'UCH_4'),
        ('MAIN_005', 'UCH_5'),
        ('MAIN_006', 'UCH_6'),
        ('MAIN_007', 'UCH_7'),
        ('MAIN_008', 'UCH_8')
    ),
    object_sections AS (
      SELECT ob.id,
             ob.object_code,
             ob.object_name,
             ob.object_type_code,
             ob.object_type_name,
             ob.temp_road_code,
             COALESCE(section_clip.pk_start, ob.object_pk_start) AS pk_start,
             COALESCE(section_clip.pk_end, ob.object_pk_end) AS pk_end,
             ob.object_pk_start,
             ob.object_pk_end,
             COALESCE(override_cs.code, split_cs.code, fallback_cs.code, main_track_cs.code) AS section_code,
             COALESCE(override_cs.name, split_cs.name, fallback_cs.name, main_track_cs.name) AS section_name,
             COALESCE(override_cs.sort_order, split_cs.sort_order, fallback_cs.sort_order, main_track_cs.sort_order) AS section_sort_order
      FROM object_bounds ob
      LEFT JOIN construction_sections override_cs
        ON override_cs.code = CASE
          WHEN ob.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
          ELSE NULL
        END
      LEFT JOIN LATERAL (
        SELECT csv.section_id,
               GREATEST(LEAST(ob.object_pk_start, ob.object_pk_end), LEAST(csv.pk_start, csv.pk_end)) AS pk_start,
               LEAST(GREATEST(ob.object_pk_start, ob.object_pk_end), GREATEST(csv.pk_start, csv.pk_end)) AS pk_end
        FROM construction_section_versions csv
        WHERE csv.is_current
          AND override_cs.id IS NULL
          AND ob.object_pk_start IS NOT NULL
          AND ob.object_pk_end IS NOT NULL
          AND csv.boundary_kind = CASE
            WHEN ob.object_type_code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE') THEN 'temp_roads'
            WHEN ob.object_type_code IN ('PILE_FIELD', 'PILE_DRIVING_PAD', 'ISSO_ACCESS', 'PIPE', 'BRIDGE', 'OVERPASS', 'TECH_ROAD') THEN 'piles_pipes'
            ELSE 'main'
          END
          AND LEAST(GREATEST(ob.object_pk_start, ob.object_pk_end), GREATEST(csv.pk_start, csv.pk_end))
              > GREATEST(LEAST(ob.object_pk_start, ob.object_pk_end), LEAST(csv.pk_start, csv.pk_end))
        ORDER BY GREATEST(LEAST(ob.object_pk_start, ob.object_pk_end), LEAST(csv.pk_start, csv.pk_end)),
                 LEAST(GREATEST(ob.object_pk_start, ob.object_pk_end), GREATEST(csv.pk_start, csv.pk_end))
      ) section_clip ON true
      LEFT JOIN construction_sections split_cs ON split_cs.id = section_clip.section_id
      LEFT JOIN LATERAL (
        SELECT csv.section_id
        FROM construction_section_versions csv
        WHERE csv.is_current
          AND ob.object_pk_start IS NOT NULL
          AND ob.object_pk_end IS NOT NULL
          AND csv.boundary_kind = CASE
            WHEN ob.object_type_code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE') THEN 'temp_roads'
            WHEN ob.object_type_code IN ('PILE_FIELD', 'PILE_DRIVING_PAD', 'ISSO_ACCESS', 'PIPE', 'BRIDGE', 'OVERPASS', 'TECH_ROAD') THEN 'piles_pipes'
            ELSE 'main'
          END
          AND COALESCE((ob.object_pk_start + ob.object_pk_end) / 2.0, ob.object_pk_start, ob.object_pk_end) >= LEAST(csv.pk_start, csv.pk_end)
          AND COALESCE((ob.object_pk_start + ob.object_pk_end) / 2.0, ob.object_pk_start, ob.object_pk_end) < GREATEST(csv.pk_start, csv.pk_end)
        ORDER BY csv.pk_start, csv.pk_end
        LIMIT 1
      ) fallback_section ON true
      LEFT JOIN construction_sections fallback_cs ON fallback_cs.id = fallback_section.section_id
      LEFT JOIN main_track_section_map mt_map
        ON mt_map.object_code = ob.object_code
       AND ob.object_type_code = 'MAIN_TRACK'
      LEFT JOIN construction_sections main_track_cs
        ON main_track_cs.code = mt_map.section_code
       AND main_track_cs.is_active IS NOT FALSE
    )
    """


def _statement_filter_values(value) -> list[str]:
    if not value:
        return []
    raw_values = value if isinstance(value, (list, tuple, set)) else str(value).split(",")
    result: list[str] = []
    for item in raw_values:
        text = str(item or "").strip()
        if not text or text.lower() == "all":
            continue
        if text not in result:
            result.append(text)
    return result


def _statement_scope_filter_sql(
    section_codes: Optional[list[str]],
    object_id: Optional[str],
    pk_from_num: Optional[float],
    pk_to_num: Optional[float],
    object_type_code: Optional[str] = None,
) -> tuple[str, list]:
    filters = ["1=1"]
    params: list = []
    object_ids = _statement_filter_values(object_id)
    object_type_codes = _statement_filter_values(object_type_code)
    if section_codes:
        filters.append("section_code = ANY(%s)")
        params.append(section_codes)
    if object_ids:
        filters.append("id = ANY(%s::uuid[])")
        params.append(object_ids)
    if object_type_codes:
        filters.append("object_type_code = ANY(%s)")
        params.append(object_type_codes)
    if pk_from_num is not None:
        filters.append("pk_end IS NOT NULL AND pk_end >= %s")
        params.append(pk_from_num)
    if pk_to_num is not None:
        filters.append("pk_start IS NOT NULL AND pk_start <= %s")
        params.append(pk_to_num)
    return " AND ".join(filters), params


def _statement_fact_report_condition(report_alias: str = "dr") -> str:
    return (
        f"COALESCE({report_alias}.status, 'confirmed') IN ('confirmed', 'approved', 'pending_review', 'review') "
        f"AND {_non_pile_control_report_condition(report_alias)}"
    )


def _statement_fact_report_exists(table_alias: str) -> str:
    return (
        f"EXISTS (SELECT 1 FROM daily_reports dr_scope "
        f"WHERE dr_scope.id = {table_alias}.daily_report_id "
        f"AND {_statement_fact_report_condition('dr_scope')})"
    )


@router.get("/statements")
def statements(
    section: Optional[str] = None,
    object_id: Optional[str] = None,
    object_type: Optional[str] = None,
    pk_from: Optional[str] = None,
    pk_to: Optional[str] = None,
    period_from: Optional[str] = None,
    period_to: Optional[str] = None,
    work_type_id: Optional[str] = None,
    q: Optional[str] = None,
    period_mode: str = "month_third",
    _user=Depends(current_user),
):
    """Detailed plan/fact statement by section, object, and picket range."""
    section_codes = _expand_sections(section)
    pk_from_num = _parse_statement_pk(pk_from)
    pk_to_num = _parse_statement_pk(pk_to)
    if pk_from_num is not None and pk_to_num is not None and pk_from_num > pk_to_num:
        pk_from_num, pk_to_num = pk_to_num, pk_from_num
    period_from_date = _statement_parse_date(period_from, "period_from")
    period_to_date = _statement_parse_date(period_to, "period_to")
    if period_from_date and period_to_date and period_from_date > period_to_date:
        period_from_date, period_to_date = period_to_date, period_from_date
    if period_from_date is None and period_to_date is None:
        period_from_date, period_to_date = _statement_default_period_bounds()
    periods = _statement_period_buckets(period_mode, period_from_date, period_to_date)

    sections = _statement_sections()
    object_filter_sql, object_params = _statement_scope_filter_sql(section_codes, None, pk_from_num, pk_to_num, object_type)
    object_rows = query(
        _statement_scope_cte()
        + f"""
        SELECT id::text,
               object_code,
               object_name,
               object_type_code,
               object_type_name,
               section_code,
               section_name,
               pk_start,
               pk_end
        FROM object_sections
        WHERE {object_filter_sql}
        ORDER BY section_sort_order NULLS LAST, section_code NULLS LAST,
                 pk_start NULLS LAST, pk_end NULLS LAST,
                 object_name, object_code NULLS LAST
        LIMIT 2000
        """,
        object_params,
    )

    scope_filter_sql, scope_params = _statement_scope_filter_sql(section_codes, object_id, pk_from_num, pk_to_num, object_type)
    item_pk_filters: list[str] = []
    item_pk_params: list = []
    if pk_from_num is not None:
        item_pk_filters.append("COALESCE({seg}.pk_end, {pf}.pk_end, so.pk_end) IS NOT NULL AND COALESCE({seg}.pk_end, {pf}.pk_end, so.pk_end) >= %s")
        item_pk_params.append(pk_from_num)
    if pk_to_num is not None:
        item_pk_filters.append("COALESCE({seg}.pk_start, {pf}.pk_start, so.pk_start) IS NOT NULL AND COALESCE({seg}.pk_start, {pf}.pk_start, so.pk_start) <= %s")
        item_pk_params.append(pk_to_num)
    plan_item_filters = [flt.format(seg="ps", pf="pf") for flt in item_pk_filters]
    fact_item_filters = [flt.format(seg="ds", pf="pf") for flt in item_pk_filters]
    plan_item_params = list(item_pk_params)
    fact_item_params = list(item_pk_params)
    work_type_ids = _statement_filter_values(work_type_id)
    if work_type_ids:
        plan_item_filters.append("pwi.work_type_id = ANY(%s::uuid[])")
        plan_item_params.append(work_type_ids)
        fact_item_filters.append("dwi.work_type_id = ANY(%s::uuid[])")
        fact_item_params.append(work_type_ids)
    if period_from_date is not None:
        fact_item_filters.append("dr.report_date >= %s::date")
        fact_item_params.append(period_from_date)
    if period_to_date is not None:
        fact_item_filters.append("dr.report_date <= %s::date")
        fact_item_params.append(period_to_date)
    plan_pk_sql = " AND ".join(plan_item_filters) or "1=1"
    fact_pk_sql = " AND ".join(fact_item_filters) or "1=1"

    rows = query(
        _statement_scope_cte()
        + f"""
        , scoped_objects AS (
          SELECT *
          FROM object_sections
          WHERE {scope_filter_sql}
        ),
        plan_items AS (
          SELECT pwi.id::text AS item_id,
                 so.id::text AS object_id,
                 so.object_code,
                 so.object_name,
                 so.object_type_code,
                 so.object_type_name,
	               so.section_code,
	               so.section_name,
	               so.section_sort_order,
	               wt.id::text AS work_type_id,
                 wt.code AS work_type_code,
                 wt.name AS work_type_name,
                 COALESCE(pwi.unit, wt.default_unit, '') AS unit,
                 row_scope.row_pk_start AS pk_start,
                 row_scope.row_pk_end AS pk_end,
                 CASE
                   WHEN COUNT(ps.id) FILTER (WHERE ps.id IS NOT NULL) > 0
                    AND COUNT(ps.volume_segment) FILTER (WHERE ps.volume_segment IS NOT NULL) > 0
                     THEN SUM(COALESCE(ps.volume_segment, 0) * row_scope.row_pk_factor)
                   ELSE MAX(pwi.project_volume) * MAX(row_scope.row_pk_factor)
                 END AS project_volume,
                 COUNT(ps.id) FILTER (WHERE ps.id IS NOT NULL) AS project_segment_count
          FROM project_work_items pwi
          LEFT JOIN constructives con ON con.id = pwi.constructive_id
          JOIN scoped_objects so ON so.id = COALESCE(pwi.object_id, con.object_id)
          JOIN work_types wt ON wt.id = pwi.work_type_id
          LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
          LEFT JOIN project_work_item_segments ps ON ps.project_work_item_id = pwi.id
          {_statement_row_scope_lateral_sql('COALESCE(ps.pk_start, pf.pk_start)', 'COALESCE(ps.pk_end, pf.pk_end)', 'so')}
          WHERE {plan_pk_sql}
            AND row_scope.row_pk_has_overlap
          GROUP BY pwi.id, so.id, so.object_code, so.object_name, so.object_type_code, so.object_type_name,
                   so.section_code, so.section_name, so.section_sort_order, wt.id, wt.code, wt.name, pwi.unit, wt.default_unit,
                   row_scope.row_pk_start, row_scope.row_pk_end
        ),
        fact_items AS (
          SELECT dwi.id::text AS item_id,
                 so.id::text AS object_id,
                 so.object_code,
                 so.object_name,
                 so.object_type_code,
	               so.object_type_name,
	               so.section_code,
	               so.section_name,
	               so.section_sort_order,
	               wt.id::text AS work_type_id,
                 wt.code AS work_type_code,
                 wt.name AS work_type_name,
                 COALESCE(dwi.unit, wt.default_unit, '') AS unit,
                 row_scope.row_pk_start AS pk_start,
                 row_scope.row_pk_end AS pk_end,
                 CASE
                   WHEN COUNT(ds.id) FILTER (WHERE ds.id IS NOT NULL) > 0
                    AND COUNT(ds.volume_segment) FILTER (WHERE ds.volume_segment IS NOT NULL) > 0
                     THEN SUM(COALESCE(ds.volume_segment, 0) * row_scope.row_pk_factor)
                   ELSE MAX(dwi.volume) * MAX(row_scope.row_pk_factor)
                 END AS fact_volume
          FROM daily_work_items dwi
          JOIN daily_reports dr ON dr.id = dwi.daily_report_id
          LEFT JOIN constructives con ON con.id = dwi.constructive_id
          JOIN scoped_objects so ON so.id = COALESCE(dwi.object_id, con.object_id)
          JOIN work_types wt ON wt.id = dwi.work_type_id
          LEFT JOIN daily_work_item_segments ds ON ds.daily_work_item_id = dwi.id AND ds.is_demo IS NOT TRUE
          LEFT JOIN pile_fields pf ON pf.id = ds.pile_field_id
          {_statement_row_scope_lateral_sql('COALESCE(ds.pk_start, pf.pk_start)', 'COALESCE(ds.pk_end, pf.pk_end)', 'so')}
          WHERE dwi.is_demo IS NOT TRUE
            AND COALESCE(dr.is_demo, false) IS FALSE
            AND {_statement_fact_report_condition("dr")}
            AND {fact_pk_sql}
            AND row_scope.row_pk_has_overlap
          GROUP BY dwi.id, so.id, so.object_code, so.object_name, so.object_type_code, so.object_type_name,
                   so.section_code, so.section_name, so.section_sort_order, wt.id, wt.code, wt.name, dwi.unit, wt.default_unit,
                   row_scope.row_pk_start, row_scope.row_pk_end
        ),
        plan_agg AS (
          SELECT object_id, object_code, object_name, object_type_code, object_type_name,
                 section_code, section_name, work_type_id, work_type_code, work_type_name, unit,
                 MIN(pk_start) AS pk_start,
                 MAX(pk_end) AS pk_end,
                 SUM(COALESCE(project_volume, 0)) AS project_volume,
                 CASE WHEN COUNT(DISTINCT item_id) = 1 THEN MIN(item_id) ELSE NULL END AS project_item_id,
                 COUNT(DISTINCT item_id) AS project_item_count,
                 SUM(COALESCE(project_segment_count, 0))::int AS project_segment_count
          FROM plan_items
          GROUP BY object_id, object_code, object_name, object_type_code, object_type_name,
                   section_code, section_name, work_type_id, work_type_code, work_type_name, unit
        ),
        fact_agg AS (
          SELECT object_id, object_code, object_name, object_type_code, object_type_name,
                 section_code, section_name, work_type_id, work_type_code, work_type_name, unit,
                 MIN(pk_start) AS pk_start,
                 MAX(pk_end) AS pk_end,
                 SUM(COALESCE(fact_volume, 0)) AS fact_volume,
                 STRING_AGG(DISTINCT public.format_route_pk_range(pk_start, pk_end), '; ')
                   FILTER (WHERE pk_start IS NOT NULL OR pk_end IS NOT NULL) AS fact_pk_ranges
          FROM fact_items
          GROUP BY object_id, object_code, object_name, object_type_code, object_type_name,
                   section_code, section_name, work_type_id, work_type_code, work_type_name, unit
        )
        SELECT COALESCE(p.object_id, f.object_id) AS object_id,
               COALESCE(p.object_code, f.object_code) AS object_code,
               COALESCE(p.object_name, f.object_name) AS object_name,
               COALESCE(p.object_type_code, f.object_type_code) AS object_type_code,
               COALESCE(p.object_type_name, f.object_type_name) AS object_type_name,
               COALESCE(p.section_code, f.section_code) AS section_code,
               COALESCE(p.section_name, f.section_name) AS section_name,
               COALESCE(p.work_type_id, f.work_type_id) AS work_type_id,
               COALESCE(p.work_type_code, f.work_type_code) AS work_type_code,
               COALESCE(p.work_type_name, f.work_type_name) AS work_type_name,
               COALESCE(p.unit, f.unit) AS unit,
               LEAST(COALESCE(p.pk_start, f.pk_start), COALESCE(f.pk_start, p.pk_start)) AS pk_start,
               GREATEST(COALESCE(p.pk_end, f.pk_end), COALESCE(f.pk_end, p.pk_end)) AS pk_end,
               COALESCE(p.project_volume, 0) AS project_volume,
               COALESCE(f.fact_volume, 0) AS fact_volume,
               p.project_item_id,
               p.project_item_count,
               COALESCE(p.project_segment_count, 0) AS project_segment_count,
               f.fact_pk_ranges
        FROM plan_agg p
	        FULL OUTER JOIN fact_agg f
	          ON f.object_id = p.object_id
	         AND f.work_type_id = p.work_type_id
	         AND COALESCE(f.unit, '') = COALESCE(p.unit, '')
	         AND COALESCE(f.section_code, '') = COALESCE(p.section_code, '')
	         AND (
	           p.pk_start IS NULL OR p.pk_end IS NULL
	           OR f.pk_start IS NULL OR f.pk_end IS NULL
	           OR LEAST(GREATEST(f.pk_start, f.pk_end), GREATEST(p.pk_start, p.pk_end))
	              >= GREATEST(LEAST(f.pk_start, f.pk_end), LEAST(p.pk_start, p.pk_end))
	         )
        WHERE COALESCE(p.project_volume, 0) <> 0 OR COALESCE(f.fact_volume, 0) <> 0
        ORDER BY section_code NULLS LAST,
                 pk_start NULLS LAST, pk_end NULLS LAST,
                 object_name, object_code NULLS LAST,
                 work_type_name
        LIMIT 5000
        """,
        scope_params + plan_item_params + fact_item_params,
    )

    rows = _statement_filter_rows_by_query(rows, q)

    period_values_by_key: dict[str, dict[str, dict]] = {}
    if periods:
        period_start = periods[0]["start_date"]
        period_end = periods[-1]["end_date"]
        fact_period_rows = query(
            _statement_scope_cte()
            + f"""
            , scoped_objects AS (
              SELECT *
              FROM object_sections
              WHERE {scope_filter_sql}
            )
            , fact_items AS (
              SELECT dwi.id::text AS item_id,
                     so.id::text AS object_id,
                     wt.id::text AS work_type_id,
                     COALESCE(dwi.unit, wt.default_unit, '') AS unit,
                     row_scope.row_pk_start AS pk_start,
                     row_scope.row_pk_end AS pk_end,
                     dr.report_date,
                     CASE
                       WHEN COUNT(ds.id) FILTER (WHERE ds.id IS NOT NULL) > 0
                        AND COUNT(ds.volume_segment) FILTER (WHERE ds.volume_segment IS NOT NULL) > 0
                         THEN SUM(COALESCE(ds.volume_segment, 0) * row_scope.row_pk_factor)
                       ELSE MAX(dwi.volume) * MAX(row_scope.row_pk_factor)
                     END AS fact_volume
              FROM daily_work_items dwi
              JOIN daily_reports dr ON dr.id = dwi.daily_report_id
              LEFT JOIN constructives con ON con.id = dwi.constructive_id
              JOIN scoped_objects so ON so.id = COALESCE(dwi.object_id, con.object_id)
              JOIN work_types wt ON wt.id = dwi.work_type_id
              LEFT JOIN daily_work_item_segments ds ON ds.daily_work_item_id = dwi.id AND ds.is_demo IS NOT TRUE
              LEFT JOIN pile_fields pf ON pf.id = ds.pile_field_id
              {_statement_row_scope_lateral_sql('COALESCE(ds.pk_start, pf.pk_start)', 'COALESCE(ds.pk_end, pf.pk_end)', 'so')}
              WHERE dwi.is_demo IS NOT TRUE
                AND COALESCE(dr.is_demo, false) IS FALSE
                AND {_statement_fact_report_condition("dr")}
                AND dr.report_date >= %s::date
                AND dr.report_date <= %s::date
                AND {fact_pk_sql}
                AND row_scope.row_pk_has_overlap
              GROUP BY dwi.id, so.id, wt.id, COALESCE(dwi.unit, wt.default_unit, ''),
                       row_scope.row_pk_start, row_scope.row_pk_end, dr.report_date
            )
            SELECT object_id,
                   work_type_id,
                   unit,
                   pk_start,
                   pk_end,
                   report_date,
                   SUM(COALESCE(fact_volume, 0))::numeric AS fact_volume
            FROM fact_items
            GROUP BY object_id, work_type_id, unit, pk_start, pk_end, report_date
            """,
            scope_params + [period_start, period_end] + fact_item_params,
        )
        for fact_row in fact_period_rows:
            period_key = _statement_period_key_for_date(periods, fact_row.get("report_date"))
            if not period_key:
                continue
            key = _statement_period_row_key(
                fact_row.get("object_id"),
                fact_row.get("work_type_id"),
                fact_row.get("unit") or "—",
                fact_row.get("pk_start"),
                fact_row.get("pk_end"),
            )
            bucket_values = period_values_by_key.setdefault(key, _statement_period_values_template(periods))
            bucket_values[period_key]["fact_volume"] += _as_float(fact_row.get("fact_volume"))

    normalized_objects: list[dict] = []
    for row in object_rows:
        section_code = _merge_section(row.get("section_code")) or row.get("section_code")
        normalized_objects.append({
            "id": row.get("id"),
            "object_code": row.get("object_code"),
            "object_name": row.get("object_name"),
            "object_type_code": row.get("object_type_code"),
            "object_type_name": row.get("object_type_name"),
            "section_code": section_code,
            "section_name": row.get("section_name"),
            "pk_start": _as_float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": _as_float(row.get("pk_end")) if row.get("pk_end") is not None else None,
        })

    normalized_rows: list[dict] = []
    totals_by_unit: dict[str, dict] = {}
    for row in rows:
        project_volume = _as_float(row.get("project_volume"))
        fact_volume = _as_float(row.get("fact_volume"))
        remaining_volume = round(project_volume - fact_volume, 3)
        pct = round(fact_volume / project_volume * 100, 1) if project_volume else None
        unit = row.get("unit") or "—"
        bucket = totals_by_unit.setdefault(unit, {"unit": unit, "project_volume": 0.0, "fact_volume": 0.0, "remaining_volume": 0.0})
        bucket["project_volume"] += project_volume
        bucket["fact_volume"] += fact_volume
        bucket["remaining_volume"] += remaining_volume
        row_period_key = _statement_period_row_key(row.get("object_id"), row.get("work_type_id"), unit, row.get("pk_start"), row.get("pk_end"))
        row_period_values = period_values_by_key.get(row_period_key, _statement_period_values_template(periods)) if periods else {}
        normalized_rows.append({
            "object_id": row.get("object_id"),
            "object_code": row.get("object_code"),
            "object_name": row.get("object_name"),
            "object_type_code": row.get("object_type_code"),
            "object_type_name": row.get("object_type_name"),
            "section_code": _merge_section(row.get("section_code")) or row.get("section_code"),
            "section_name": row.get("section_name"),
            "work_type_id": row.get("work_type_id"),
            "work_type_code": row.get("work_type_code"),
            "work_type_name": row.get("work_type_name"),
            "work_type_analytics_tag": row.get("work_type_analytics_tag"),
            "unit": unit,
            "pk_start": _as_float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": _as_float(row.get("pk_end")) if row.get("pk_end") is not None else None,
            "project_volume": project_volume,
            "fact_volume": fact_volume,
            "fact_pk_ranges": row.get("fact_pk_ranges"),
            "remaining_volume": remaining_volume,
            "percent_complete": pct,
            "project_item_id": row.get("project_item_id"),
            "project_item_count": int(row.get("project_item_count") or 0),
            "project_segment_count": int(row.get("project_segment_count") or 0),
            "can_edit_project": bool(row.get("project_item_id")),
            "period_values": [
                {
                    "period_key": item["period_key"],
                    "planned_volume": round(item["planned_volume"], 3),
                    "fact_volume": round(item["fact_volume"], 3),
                }
                for item in row_period_values.values()
            ],
        })

    totals = []
    for bucket in totals_by_unit.values():
        bucket["project_volume"] = round(bucket["project_volume"], 3)
        bucket["fact_volume"] = round(bucket["fact_volume"], 3)
        bucket["remaining_volume"] = round(bucket["remaining_volume"], 3)
        bucket["percent_complete"] = round(bucket["fact_volume"] / bucket["project_volume"] * 100, 1) if bucket["project_volume"] else None
        totals.append(bucket)

    return {
        "filters": {
            "section": section or "all",
            "section_codes": section_codes or [],
            "object_id": object_id,
            "object_ids": _statement_filter_values(object_id),
            "object_type": object_type or "all",
            "object_types": _statement_filter_values(object_type),
            "pk_from": pk_from_num,
            "pk_to": pk_to_num,
            "period_from": period_from_date.isoformat() if period_from_date else None,
            "period_to": period_to_date.isoformat() if period_to_date else None,
            "work_type_id": work_type_id or "all",
            "work_type_ids": _statement_filter_values(work_type_id),
            "q": (q or "").strip(),
        },
        "sections": sections,
        "object_types": _statement_object_types_payload(),
        "objects": normalized_objects,
        "work_types": _statement_work_types_payload(),
        "periods": _statement_period_response(periods),
        "rows": normalized_rows,
        "totals": sorted(totals, key=lambda item: item["unit"]),
        "row_count": len(normalized_rows),
    }


