def _statement_table_exists(table_name: str) -> bool:
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", table_name or ""):
        return False
    row = query_one("SELECT to_regclass(%s) AS table_name", [f"public.{table_name}"])
    return bool(row and row.get("table_name"))


def _statement_cur_table_exists(cur, table_name: str) -> bool:
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", table_name or ""):
        return False
    cur.execute("SELECT to_regclass(%s)", (f"public.{table_name}",))
    row = cur.fetchone()
    return bool(row and row[0])


def _statement_cur_column_exists(cur, table_name: str, column_name: str) -> bool:
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", table_name or "") or not re.fullmatch(r"[a-z_][a-z0-9_]*", column_name or ""):
        return False
    cur.execute(
        """
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = %s
          AND column_name = %s
        LIMIT 1
        """,
        (table_name, column_name),
    )
    return bool(cur.fetchone())


def _statement_count_column_refs(cur, table_name: str, column_name: str, ref_id: str, *, non_demo_only: bool = False) -> int:
    if not _statement_cur_column_exists(cur, table_name, column_name):
        return 0
    non_demo_sql = ""
    if non_demo_only and _statement_cur_column_exists(cur, table_name, "is_demo"):
        non_demo_sql = " AND COALESCE(is_demo, false) = false"
    cur.execute(
        f"SELECT COUNT(*)::int FROM {table_name} WHERE {column_name} = %s::uuid{non_demo_sql}",
        (ref_id,),
    )
    row = cur.fetchone()
    return int(row[0] or 0) if row else 0


def _statement_object_delete_blockers(cur, object_id: str) -> dict[str, int]:
    blockers: dict[str, int] = {}
    checks = [
        ("daily_work_items", "object_id", "Факты работ", True),
        ("material_movements", "from_object_id", "Перевозки: источник", True),
        ("material_movements", "to_object_id", "Перевозки: получатель", True),
        ("stockpiles", "object_id", "Накопители", False),
        ("pile_fields", "object_id", "Свайные поля", False),
        ("temporary_roads", "object_id", "Временные автодороги", False),
        ("temporary_road_status_segments", "object_id", "Статусы временных автодорог", True),
        ("constructives", "object_id", "Конструктивы", False),
        ("isso_front_transfer_lines", "object_id", "Фронты ИССО", False),
        ("isso_object_front_attributes", "object_id", "Атрибуты фронтов ИССО", False),
        ("pipe_pile_specs", "object_id", "Параметры труб/свай", False),
        ("section_quarry_haul_distances", "quarry_object_id", "Расстояния от карьеров", False),
    ]
    for table_name, column_name, label, non_demo_only in checks:
        count = _statement_count_column_refs(cur, table_name, column_name, object_id, non_demo_only=non_demo_only)
        if count:
            blockers[label] = count
    return blockers


def _statement_work_types_payload() -> list[dict]:
    rows = query(
        """
        SELECT id::text, code, name, default_unit, work_group, analytics_tag
        FROM work_types
        WHERE COALESCE(is_active, true) IS TRUE
        ORDER BY work_group NULLS LAST, name, code
        LIMIT 2000
        """
    )
    for row in rows:
        source_name = row.get("name")
        display_name = _statement_work_type_display_name(row.get("code"), source_name)
        row["source_name"] = source_name
        row["name"] = display_name
        row["display_name"] = display_name
    rows.sort(key=lambda item: (str(item.get("work_group") or ""), str(item.get("name") or item.get("code") or "").lower(), str(item.get("code") or "")))
    return rows


def _statement_object_types_payload() -> list[dict]:
    return query(
        """
        SELECT id::text, code, name, sort_order, is_linear
        FROM object_types
        WHERE COALESCE(is_active, true) IS TRUE
        ORDER BY sort_order NULLS LAST, name, code
        LIMIT 1000
        """
    )


def _statement_parse_date(value: Optional[str], field: str) -> Optional[date_cls]:
    if value is None or str(value).strip() == "":
        return None
    try:
        return date_cls.fromisoformat(str(value).strip())
    except ValueError:
        raise HTTPException(400, f"{field} must be YYYY-MM-DD")


def _statement_normalize_period(period_start: Optional[str], period_end: Optional[str]) -> tuple[Optional[date_cls], Optional[date_cls]]:
    start = _statement_parse_date(period_start, "period_start")
    end = _statement_parse_date(period_end, "period_end")
    if start and not end:
        end = start
    if end and not start:
        start = end
    if start and end and start > end:
        raise HTTPException(400, "period_end must be greater than or equal to period_start")
    return start, end


STATEMENT_PERIOD_MODES = {"day", "month_quarter", "month_third", "month"}


def _statement_default_period_bounds() -> tuple[Optional[date_cls], Optional[date_cls]]:
    date_sources: list[str] = []
    if _statement_table_exists("planned_work_items"):
        date_sources.extend([
            "SELECT period_start::date AS value FROM planned_work_items WHERE COALESCE(is_active, true) IS TRUE AND period_start IS NOT NULL",
            "SELECT period_end::date AS value FROM planned_work_items WHERE COALESCE(is_active, true) IS TRUE AND period_end IS NOT NULL",
        ])
    if _statement_table_exists("daily_reports"):
        date_sources.append("SELECT report_date::date AS value FROM daily_reports WHERE COALESCE(is_demo, false) IS FALSE AND report_date IS NOT NULL")
    if not date_sources:
        return None, None
    row = query_one(
        f"""
        SELECT MIN(value)::date AS start_date, MAX(value)::date AS end_date
        FROM ({" UNION ALL ".join(date_sources)}) statement_dates
        WHERE value IS NOT NULL
        """
    )
    if not row:
        return None, None
    return row.get("start_date"), row.get("end_date")


def _statement_month_end(value: date_cls) -> date_cls:
    if value.month == 12:
        return date_cls(value.year, 12, 31)
    return date_cls(value.year, value.month + 1, 1) - timedelta(days=1)


def _statement_add_month(value: date_cls) -> date_cls:
    if value.month == 12:
        return date_cls(value.year + 1, 1, 1)
    return date_cls(value.year, value.month + 1, 1)


def _statement_period_buckets(period_mode: Optional[str], start: Optional[date_cls], end: Optional[date_cls]) -> list[dict]:
    mode = (period_mode or "month_third").strip()
    if mode not in STATEMENT_PERIOD_MODES:
        raise HTTPException(400, "period_mode must be one of: day, month_quarter, month_third, month")
    if start is None or end is None:
        return []
    if start > end:
        start, end = end, start

    buckets: list[dict] = []
    if mode == "day":
        cursor = start
        while cursor <= end:
            buckets.append({
                "key": cursor.isoformat(),
                "label": cursor.strftime("%d.%m"),
                "start_date": cursor,
                "end_date": cursor,
            })
            cursor = cursor + timedelta(days=1)
        return buckets

    month_cursor = date_cls(start.year, start.month, 1)
    while month_cursor <= end:
        month_end = _statement_month_end(month_cursor)
        if mode == "month":
            ranges = [(month_cursor, month_end, month_cursor.strftime("%m.%Y"))]
        elif mode == "month_third":
            ranges = [
                (month_cursor, min(date_cls(month_cursor.year, month_cursor.month, 10), month_end), f"1/3 {month_cursor:%m.%Y}"),
                (date_cls(month_cursor.year, month_cursor.month, 11), min(date_cls(month_cursor.year, month_cursor.month, 20), month_end), f"2/3 {month_cursor:%m.%Y}"),
                (date_cls(month_cursor.year, month_cursor.month, 21), month_end, f"3/3 {month_cursor:%m.%Y}"),
            ]
        else:
            ranges = [
                (month_cursor, min(date_cls(month_cursor.year, month_cursor.month, 7), month_end), f"1/4 {month_cursor:%m.%Y}"),
                (date_cls(month_cursor.year, month_cursor.month, 8), min(date_cls(month_cursor.year, month_cursor.month, 15), month_end), f"2/4 {month_cursor:%m.%Y}"),
                (date_cls(month_cursor.year, month_cursor.month, 16), min(date_cls(month_cursor.year, month_cursor.month, 23), month_end), f"3/4 {month_cursor:%m.%Y}"),
                (date_cls(month_cursor.year, month_cursor.month, 24), month_end, f"4/4 {month_cursor:%m.%Y}"),
            ]
        for bucket_start, bucket_end, label in ranges:
            clipped_start = max(bucket_start, start)
            clipped_end = min(bucket_end, end)
            if clipped_start <= clipped_end:
                buckets.append({
                    "key": f"{clipped_start.isoformat()}_{clipped_end.isoformat()}",
                    "label": label,
                    "start_date": clipped_start,
                    "end_date": clipped_end,
                })
        month_cursor = _statement_add_month(month_cursor)
    return buckets


def _statement_period_response(periods: list[dict]) -> list[dict]:
    return [
        {
            "key": item["key"],
            "label": item["label"],
            "start": item["start_date"].isoformat(),
            "end": item["end_date"].isoformat(),
        }
        for item in periods
    ]


def _statement_period_key_for_date(periods: list[dict], value: Optional[date_cls]) -> Optional[str]:
    if value is None:
        return None
    for period in periods:
        if period["start_date"] <= value <= period["end_date"]:
            return period["key"]
    return None


def _statement_period_values_template(periods: list[dict]) -> dict[str, dict]:
    return {
        period["key"]: {
            "period_key": period["key"],
            "planned_volume": 0.0,
            "fact_volume": 0.0,
        }
        for period in periods
    }


def _statement_period_pk_part(value) -> str:
    if value is None:
        return ""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return ""
    if abs(number) < 0.000001:
        number = 0.0
    return f"{number:.6f}".rstrip("0").rstrip(".")


def _statement_volume_base_row_key(object_id: str, work_type_id: str, unit: str) -> str:
    return f"{object_id}||{work_type_id}||{unit or '—'}"


def _statement_period_row_key(object_id: str, work_type_id: str, unit: str, pk_start=None, pk_end=None) -> str:
    base = _statement_volume_base_row_key(object_id, work_type_id, unit)
    if pk_start is None and pk_end is None:
        return base
    return f"{base}||{_statement_period_pk_part(pk_start)}||{_statement_period_pk_part(pk_end)}"


def _statement_overlap_days(left_start: date_cls, left_end: date_cls, right_start: date_cls, right_end: date_cls) -> int:
    start = max(left_start, right_start)
    end = min(left_end, right_end)
    if start > end:
        return 0
    return (end - start).days + 1


def _statement_numeric(value, field: str) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        raise HTTPException(400, f"{field} must be numeric")


def _statement_schema_flags() -> dict:
    planned = _statement_table_exists("planned_work_items")
    pile_link = False
    actual_section_binding = False
    if planned:
        col = query_one(
            """
            SELECT 1 AS ok
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = 'planned_work_items'
              AND column_name = 'assigned_section_id'
            LIMIT 1
            """
        )
        actual_section_binding = bool(col)
    if _statement_table_exists("project_work_items"):
        col = query_one(
            """
            SELECT 1 AS ok
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = 'project_work_items'
              AND column_name = 'source_pile_field_id'
            LIMIT 1
            """
        )
        pile_link = bool(col)
    return {
        "planned_work_items": planned,
        "project_work_items_source_pile_field_id": pile_link,
        "planned_work_items_assigned_section_id": actual_section_binding,
        "editable": planned,
    }


def _statement_metadata_payload(
    section: Optional[str] = None,
    pk_from: Optional[str] = None,
    pk_to: Optional[str] = None,
    object_type: Optional[str] = None,
    actual_section_binding: bool = False,
) -> dict:
    section_codes = _expand_sections(section)
    pk_from_num = _parse_statement_pk(pk_from)
    pk_to_num = _parse_statement_pk(pk_to)
    if pk_from_num is not None and pk_to_num is not None and pk_from_num > pk_to_num:
        pk_from_num, pk_to_num = pk_to_num, pk_from_num
    object_filter_sql, object_params = _statement_scope_filter_sql(
        None if actual_section_binding else section_codes,
        None,
        pk_from_num,
        pk_to_num,
        object_type,
    )
    object_rows = query(
        _statement_scope_cte()
        + f"""
        SELECT id::text,
               object_code,
               object_name,
               object_type_code,
               object_type_name,
               section_code,
               section_name,
               pk_start,
               pk_end
        FROM object_sections
        WHERE {object_filter_sql}
        ORDER BY section_sort_order NULLS LAST, section_code NULLS LAST,
                 pk_start NULLS LAST, pk_end NULLS LAST,
                 object_name, object_code NULLS LAST
        LIMIT 5000
        """,
        object_params,
    )
    work_types = _statement_work_types_payload()
    object_types = _statement_object_types_payload()
    return {
        "schema": _statement_schema_flags(),
        "sections": _statement_sections(),
        "object_types": object_types,
        "objects": [
            {
                "id": row.get("id"),
                "object_code": row.get("object_code"),
                "object_name": row.get("object_name"),
                "object_type_code": row.get("object_type_code"),
                "object_type_name": row.get("object_type_name"),
                "section_code": _merge_section(row.get("section_code")) or row.get("section_code"),
                "section_name": row.get("section_name"),
                "pk_start": _as_float(row.get("pk_start")) if row.get("pk_start") is not None else None,
                "pk_end": _as_float(row.get("pk_end")) if row.get("pk_end") is not None else None,
            }
            for row in object_rows
        ],
        "work_types": work_types,
        "actual_section_binding": bool(actual_section_binding),
        "endpoints": {
            "legacy_summary": "/api/wip/statements",
            "metadata": "/api/wip/statements/metadata",
            "rows": "/api/wip/statements/rows",
            "create": "POST /api/wip/statements/rows",
            "create_project": "POST /api/wip/statements/project-rows",
            "create_object": "POST /api/wip/statements/objects",
            "update_object_picketage": "PATCH /api/wip/statements/objects/{object_id}/picketage",
            "create_work_type": "POST /api/wip/statements/work-types",
            "update": "PATCH /api/wip/statements/rows/{row_id}",
            "export": "/api/wip/statements/export",
            "import": "POST /api/wip/statements/import",
            "period_plan": "POST /api/wip/statements/period-plan",
        },
    }


def _statement_search_terms(query_text: Optional[str]) -> list[str]:
    return [term for term in re.split(r"\s+", (query_text or "").strip().lower()) if term]


def _statement_filter_rows_by_query(rows: list[dict], query_text: Optional[str]) -> list[dict]:
    terms = _statement_search_terms(query_text)
    if not terms:
        return rows

    def row_blob(row: dict) -> str:
        values = [
            row.get("object_id"),
            row.get("object_code"),
            row.get("object_name"),
            row.get("object_type_code"),
            row.get("object_type_name"),
            row.get("section_code"),
            row.get("section_name"),
            row.get("work_type_id"),
            row.get("work_type_code"),
            row.get("work_type_name"),
            row.get("work_type_analytics_tag"),
            row.get("unit"),
            row.get("pk_start"),
            row.get("pk_end"),
            row.get("pk_raw_text"),
            _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text")),
            row.get("fact_pk_ranges"),
            row.get("period_start"),
            row.get("period_end"),
            row.get("plan_type"),
            row.get("source_reference"),
            row.get("comment"),
            row.get("plan_id"),
            row.get("project_item_id"),
        ]
        return " ".join(str(value).lower() for value in values if value is not None)

    return [row for row in rows if all(term in row_blob(row) for term in terms)]


def _legacy_statement_rows_payload(
    section: Optional[str],
    object_id: Optional[str],
    pk_from: Optional[str],
    pk_to: Optional[str],
    reason: str,
    _user,
    object_type: Optional[str] = None,
    work_type_id: Optional[str] = None,
    period_from: Optional[str] = None,
    period_to: Optional[str] = None,
    period_mode: str = "month_third",
    q: Optional[str] = None,
) -> dict:
    payload = statements(
        section=section,
        object_id=object_id,
        object_type=object_type,
        pk_from=pk_from,
        pk_to=pk_to,
        period_from=period_from,
        period_to=period_to,
        work_type_id=work_type_id,
        period_mode=period_mode,
        q=q,
        _user=_user,
    )
    rows = []
    work_type_filter_ids = set(_statement_filter_values(work_type_id))
    for row in payload.get("rows", []):
        if work_type_filter_ids and str(row.get("work_type_id") or "") not in work_type_filter_ids:
            continue
        item = dict(row)
        item.update({
            "plan_id": None,
            "planned_volume": item.get("project_volume", 0),
            "period_start": None,
            "period_end": None,
            "plan_type": "legacy_total",
            "source_reference": "project_work_items",
            "comment": None,
            "can_edit": bool(item.get("can_edit_project")),
        })
        rows.append(item)

    totals_by_unit: dict[str, dict] = {}
    for row in rows:
        unit = row.get("unit") or "—"
        project_volume = _as_float(row.get("project_volume"))
        planned_volume = _as_float(row.get("planned_volume"))
        fact_volume = _as_float(row.get("fact_volume"))
        bucket = totals_by_unit.setdefault(unit, {"unit": unit, "project_volume": 0.0, "planned_volume": 0.0, "fact_volume": 0.0, "remaining_volume": 0.0})
        bucket["project_volume"] += project_volume
        bucket["planned_volume"] += planned_volume
        bucket["fact_volume"] += fact_volume
    totals = []
    for bucket in totals_by_unit.values():
        bucket["project_volume"] = round(bucket["project_volume"], 3)
        bucket["planned_volume"] = round(bucket["planned_volume"], 3)
        bucket["fact_volume"] = round(bucket["fact_volume"], 3)
        baseline = bucket["planned_volume"] or bucket["project_volume"]
        bucket["remaining_volume"] = round(baseline - bucket["fact_volume"], 3)
        bucket["percent_complete"] = round(bucket["fact_volume"] / baseline * 100, 1) if baseline else None
        totals.append(bucket)

    payload["rows"] = rows
    payload["totals"] = sorted(totals, key=lambda item: item["unit"])
    payload["row_count"] = len(rows)
    payload["schema"] = _statement_schema_flags()
    payload["source"] = "legacy_project_work_items"
    payload["editable"] = False
    payload["fallback_reason"] = reason
    return payload


def _statement_planned_only_rows_payload(
    section: Optional[str],
    object_id: Optional[str],
    pk_from: Optional[str],
    pk_to: Optional[str],
    period_from: Optional[str],
    period_to: Optional[str],
    work_type_id: Optional[str],
    _user,
    period_mode: str = "month",
    object_type: Optional[str] = None,
    q: Optional[str] = None,
) -> dict:
    section_codes = _expand_sections(section)
    pk_from_num = _parse_statement_pk(pk_from)
    pk_to_num = _parse_statement_pk(pk_to)
    if pk_from_num is not None and pk_to_num is not None and pk_from_num > pk_to_num:
        pk_from_num, pk_to_num = pk_to_num, pk_from_num
    period_from_date = _statement_parse_date(period_from, "period_from")
    period_to_date = _statement_parse_date(period_to, "period_to")
    if period_from_date and period_to_date and period_from_date > period_to_date:
        period_from_date, period_to_date = period_to_date, period_from_date
    if period_from_date is None and period_to_date is None:
        period_from_date, period_to_date = _statement_default_period_bounds()
    periods = _statement_period_buckets(period_mode, period_from_date, period_to_date)
    work_type_ids = _statement_filter_values(work_type_id)

    scope_filter_sql, scope_params = _statement_scope_filter_sql(section_codes, object_id, pk_from_num, pk_to_num, object_type)
    plan_filters = ["COALESCE(pwi.is_active, true) IS TRUE"]
    plan_params: list = []
    if pk_from_num is not None:
        plan_filters.append("COALESCE(pwi.pk_end, pf.pk_end, so.pk_end) IS NOT NULL AND COALESCE(pwi.pk_end, pf.pk_end, so.pk_end) >= %s")
        plan_params.append(pk_from_num)
    if pk_to_num is not None:
        plan_filters.append("COALESCE(pwi.pk_start, pf.pk_start, so.pk_start) IS NOT NULL AND COALESCE(pwi.pk_start, pf.pk_start, so.pk_start) <= %s")
        plan_params.append(pk_to_num)
    if period_from_date is not None:
        plan_filters.append("COALESCE(pwi.period_end, pwi.period_start, %s::date) >= %s::date")
        plan_params.extend([period_from_date, period_from_date])
    if period_to_date is not None:
        plan_filters.append("COALESCE(pwi.period_start, pwi.period_end, %s::date) <= %s::date")
        plan_params.extend([period_to_date, period_to_date])
    if work_type_ids:
        plan_filters.append("pwi.work_type_id = ANY(%s::uuid[])")
        plan_params.append(work_type_ids)
    plan_filter_sql = " AND ".join(plan_filters)

    rows = query(
        _statement_scope_cte()
        + f"""
        , scoped_objects AS (
          SELECT *
          FROM object_sections
          WHERE {scope_filter_sql}
        )
        SELECT pwi.id::text AS plan_id,
               so.id::text AS object_id,
               so.object_code,
               so.object_name,
               so.object_type_code,
               so.object_type_name,
               so.section_code,
               so.section_name,
               wt.id::text AS work_type_id,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               wt.analytics_tag AS work_type_analytics_tag,
               COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '') AS unit,
               row_scope.row_pk_start AS pk_start,
               row_scope.row_pk_end AS pk_end,
               CASE WHEN row_scope.row_pk_clipped THEN NULL ELSE COALESCE(pwi.pk_raw_text, pf.pk_raw_text) END AS pk_raw_text,
               0::numeric AS project_volume,
               NULL::text AS project_item_id,
               0::int AS project_item_count,
               0::int AS project_segment_count,
               COALESCE(pwi.planned_volume, 0) * row_scope.row_pk_factor AS planned_volume,
               0::numeric AS fact_volume,
               NULL::text AS fact_pk_ranges,
               pwi.period_start,
               pwi.period_end,
               pwi.plan_type,
               pwi.source_reference,
               pwi.comment,
               pwi.updated_at,
               so.section_sort_order,
               pwi.created_at
        FROM planned_work_items pwi
        JOIN scoped_objects so ON so.id = pwi.object_id
        JOIN work_types wt ON wt.id = pwi.work_type_id
        LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
        {_statement_plan_row_scope_lateral_sql('pwi', 'so', 'pf')}
        WHERE {plan_filter_sql}
          AND row_scope.row_pk_has_overlap
        ORDER BY so.section_sort_order NULLS LAST, so.section_code NULLS LAST,
                 row_scope.row_pk_start NULLS LAST, row_scope.row_pk_end NULLS LAST,
                 so.object_name, so.object_code NULLS LAST,
                 COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, wt.code),
                 pwi.period_start NULLS LAST, pwi.created_at NULLS LAST
        LIMIT 5000
        """,
        scope_params + plan_params,
    )
    rows = _statement_filter_rows_by_query(rows, q)

    period_values_by_key: dict[str, dict[str, dict]] = {}
    if periods:
        plan_period_rows = query(
            _statement_scope_cte()
            + f"""
            , scoped_objects AS (
              SELECT *
              FROM object_sections
              WHERE {scope_filter_sql}
            )
            SELECT so.id::text AS object_id,
                   wt.id::text AS work_type_id,
                   COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '') AS unit,
                   row_scope.row_pk_start AS pk_start,
                   row_scope.row_pk_end AS pk_end,
                   pwi.period_start,
                   pwi.period_end,
                   COALESCE(pwi.planned_volume, 0) * row_scope.row_pk_factor AS planned_volume
            FROM planned_work_items pwi
            JOIN scoped_objects so ON so.id = pwi.object_id
            JOIN work_types wt ON wt.id = pwi.work_type_id
            LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
            {_statement_plan_row_scope_lateral_sql('pwi', 'so', 'pf')}
            WHERE {plan_filter_sql}
              AND row_scope.row_pk_has_overlap
              AND (pwi.period_start IS NOT NULL OR pwi.period_end IS NOT NULL)
            """,
            scope_params + plan_params,
        )
        for plan_row in plan_period_rows:
            start = plan_row.get("period_start") or plan_row.get("period_end")
            end = plan_row.get("period_end") or plan_row.get("period_start")
            if not start or not end:
                continue
            if start > end:
                start, end = end, start
            total_days = max(1, (end - start).days + 1)
            value = _as_float(plan_row.get("planned_volume"))
            key = _statement_period_row_key(
                plan_row.get("object_id"),
                plan_row.get("work_type_id"),
                plan_row.get("unit") or "—",
                plan_row.get("pk_start"),
                plan_row.get("pk_end"),
            )
            bucket_values = period_values_by_key.setdefault(key, _statement_period_values_template(periods))
            for period in periods:
                overlap = _statement_overlap_days(start, end, period["start_date"], period["end_date"])
                if overlap:
                    bucket_values[period["key"]]["planned_volume"] += value * overlap / total_days

    normalized_rows: list[dict] = []
    totals_by_unit: dict[str, dict] = {}
    for row in rows:
        planned_volume = _as_float(row.get("planned_volume"))
        unit = row.get("unit") or "—"
        bucket = totals_by_unit.setdefault(unit, {"unit": unit, "project_volume": 0.0, "planned_volume": 0.0, "fact_volume": 0.0, "remaining_volume": 0.0})
        bucket["planned_volume"] += planned_volume
        row_period_key = _statement_period_row_key(row.get("object_id"), row.get("work_type_id"), unit, row.get("pk_start"), row.get("pk_end"))
        row_period_values = period_values_by_key.get(row_period_key, _statement_period_values_template(periods)) if periods else {}
        normalized_rows.append({
            "plan_id": row.get("plan_id"),
            "object_id": row.get("object_id"),
            "object_code": row.get("object_code"),
            "object_name": row.get("object_name"),
            "object_type_code": row.get("object_type_code"),
            "object_type_name": row.get("object_type_name"),
            "section_code": _merge_section(row.get("section_code")) or row.get("section_code"),
            "section_name": row.get("section_name"),
            "work_type_id": row.get("work_type_id"),
            "work_type_code": row.get("work_type_code"),
            "work_type_name": row.get("work_type_name"),
            "work_type_analytics_tag": row.get("work_type_analytics_tag"),
            "unit": unit,
            "pk_start": _as_float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": _as_float(row.get("pk_end")) if row.get("pk_end") is not None else None,
            "pk_raw_text": row.get("pk_raw_text"),
            "project_volume": 0,
            "planned_volume": planned_volume,
            "fact_volume": 0,
            "fact_pk_ranges": None,
            "remaining_volume": planned_volume,
            "percent_complete": None,
            "project_item_id": None,
            "project_item_count": 0,
            "project_segment_count": 0,
            "can_edit_project": False,
            "period_start": row.get("period_start").isoformat() if row.get("period_start") else None,
            "period_end": row.get("period_end").isoformat() if row.get("period_end") else None,
            "plan_type": row.get("plan_type") or "total",
            "source_reference": row.get("source_reference"),
            "comment": row.get("comment"),
            "updated_at": row.get("updated_at").isoformat() if row.get("updated_at") else None,
            "period_values": [
                {
                    "period_key": item["period_key"],
                    "planned_volume": round(item["planned_volume"], 3),
                    "fact_volume": 0,
                }
                for item in row_period_values.values()
            ],
            "can_edit": True,
        })

    totals = []
    for bucket in totals_by_unit.values():
        bucket["planned_volume"] = round(bucket["planned_volume"], 3)
        bucket["project_volume"] = 0
        bucket["fact_volume"] = 0
        bucket["remaining_volume"] = bucket["planned_volume"]
        bucket["percent_complete"] = None
        totals.append(bucket)

    metadata = _statement_metadata_payload(section, pk_from, pk_to, object_type)
    return {
        "filters": {
            "section": section or "all",
            "section_codes": section_codes or [],
            "object_id": object_id,
            "object_type": object_type or "all",
            "pk_from": pk_from_num,
            "pk_to": pk_to_num,
            "period_from": period_from_date.isoformat() if period_from_date else None,
            "period_to": period_to_date.isoformat() if period_to_date else None,
            "work_type_id": work_type_id or "all",
            "q": (q or "").strip(),
        },
        "schema": metadata.get("schema") or _statement_schema_flags(),
        "source": "planned_work_items",
        "editable": True,
        "sections": metadata.get("sections", []),
        "object_types": metadata.get("object_types", []),
        "objects": metadata.get("objects", []),
        "work_types": metadata.get("work_types", []),
        "periods": _statement_period_response(periods),
        "rows": normalized_rows,
        "totals": sorted(totals, key=lambda item: item["unit"]),
        "row_count": len(normalized_rows),
    }


def _statement_rows_payload(
    section: Optional[str],
    object_id: Optional[str],
    pk_from: Optional[str],
    pk_to: Optional[str],
    period_from: Optional[str],
    period_to: Optional[str],
    work_type_id: Optional[str],
    source: str,
    _user,
    period_mode: str = "month_third",
    object_type: Optional[str] = None,
    q: Optional[str] = None,
    plans_only: bool = False,
) -> dict:
    if source not in {"auto", "planned", "legacy", "fact"}:
        raise HTTPException(400, "source must be one of: auto, planned, legacy, fact")
    if source == "legacy" or not _statement_table_exists("planned_work_items"):
        reason = "requested legacy source" if source == "legacy" else "planned_work_items table is not installed"
        return _legacy_statement_rows_payload(
            section,
            object_id,
            pk_from,
            pk_to,
            reason,
            _user,
            object_type=object_type,
            work_type_id=work_type_id,
            period_from=period_from,
            period_to=period_to,
            period_mode=period_mode,
            q=q,
        )

    if plans_only:
        return _statement_planned_only_rows_payload(
            section,
            object_id,
            pk_from,
            pk_to,
            period_from,
            period_to,
            work_type_id,
            _user,
            period_mode=period_mode,
            object_type=object_type,
            q=q,
        )

    section_codes = _expand_sections(section)
    pk_from_num = _parse_statement_pk(pk_from)
    pk_to_num = _parse_statement_pk(pk_to)
    if pk_from_num is not None and pk_to_num is not None and pk_from_num > pk_to_num:
        pk_from_num, pk_to_num = pk_to_num, pk_from_num
    period_from_date = _statement_parse_date(period_from, "period_from")
    period_to_date = _statement_parse_date(period_to, "period_to")
    if period_from_date and period_to_date and period_from_date > period_to_date:
        period_from_date, period_to_date = period_to_date, period_from_date
    if period_from_date is None and period_to_date is None:
        period_from_date, period_to_date = _statement_default_period_bounds()
    periods = _statement_period_buckets(period_mode, period_from_date, period_to_date)
    work_type_ids = _statement_filter_values(work_type_id)

    scope_filter_sql, scope_params = _statement_scope_filter_sql(section_codes, object_id, pk_from_num, pk_to_num, object_type)
    plan_filters = ["COALESCE(pwi.is_active, true) IS TRUE"]
    plan_params: list = []
    if pk_from_num is not None:
        plan_filters.append("COALESCE(pwi.pk_end, pf.pk_end, so.pk_end) IS NOT NULL AND COALESCE(pwi.pk_end, pf.pk_end, so.pk_end) >= %s")
        plan_params.append(pk_from_num)
    if pk_to_num is not None:
        plan_filters.append("COALESCE(pwi.pk_start, pf.pk_start, so.pk_start) IS NOT NULL AND COALESCE(pwi.pk_start, pf.pk_start, so.pk_start) <= %s")
        plan_params.append(pk_to_num)
    if period_from_date is not None:
        plan_filters.append("COALESCE(pwi.period_end, pwi.period_start, %s::date) >= %s::date")
        plan_params.extend([period_from_date, period_from_date])
    if period_to_date is not None:
        plan_filters.append("COALESCE(pwi.period_start, pwi.period_end, %s::date) <= %s::date")
        plan_params.extend([period_to_date, period_to_date])
    if work_type_ids:
        plan_filters.append("pwi.work_type_id = ANY(%s::uuid[])")
        plan_params.append(work_type_ids)
    plan_filter_sql = " AND ".join(plan_filters)

    fact_pk_filters: list[str] = []
    fact_pk_params: list = []
    if pk_from_num is not None:
        fact_pk_filters.append("COALESCE(ds.pk_end, pf.pk_end, so.pk_end) IS NOT NULL AND COALESCE(ds.pk_end, pf.pk_end, so.pk_end) >= %s")
        fact_pk_params.append(pk_from_num)
    if pk_to_num is not None:
        fact_pk_filters.append("COALESCE(ds.pk_start, pf.pk_start, so.pk_start) IS NOT NULL AND COALESCE(ds.pk_start, pf.pk_start, so.pk_start) <= %s")
        fact_pk_params.append(pk_to_num)
    if period_from_date is not None:
        fact_pk_filters.append("dr.report_date >= %s::date")
        fact_pk_params.append(period_from_date)
    if period_to_date is not None:
        fact_pk_filters.append("dr.report_date <= %s::date")
        fact_pk_params.append(period_to_date)
    if work_type_ids:
        fact_pk_filters.append("dwi.work_type_id = ANY(%s::uuid[])")
        fact_pk_params.append(work_type_ids)
    fact_pk_sql = " AND ".join(fact_pk_filters) or "1=1"

    project_filters = ["1=1"]
    project_params: list = []
    if pk_from_num is not None:
        project_filters.append("COALESCE(ps.pk_end, pf.pk_end, so.pk_end) IS NOT NULL AND COALESCE(ps.pk_end, pf.pk_end, so.pk_end) >= %s")
        project_params.append(pk_from_num)
    if pk_to_num is not None:
        project_filters.append("COALESCE(ps.pk_start, pf.pk_start, so.pk_start) IS NOT NULL AND COALESCE(ps.pk_start, pf.pk_start, so.pk_start) <= %s")
        project_params.append(pk_to_num)
    if work_type_ids:
        project_filters.append("pwi.work_type_id = ANY(%s::uuid[])")
        project_params.append(work_type_ids)
    project_filter_sql = " AND ".join(project_filters)
    existing_plan_filter_sql = plan_filter_sql.replace("pwi.", "existing.").replace("pf.", "existing_pf.")
    unplanned_union_sql = ""
    if source in {"auto", "fact"}:
        unplanned_union_sql = f"""
          UNION ALL
          SELECT NULL::text AS plan_id,
                 COALESCE(pa.object_id, f.object_id) AS object_id,
                 COALESCE(pa.object_code, f.object_code) AS object_code,
                 COALESCE(pa.object_name, f.object_name) AS object_name,
                 COALESCE(pa.object_type_code, f.object_type_code) AS object_type_code,
                 COALESCE(pa.object_type_name, f.object_type_name) AS object_type_name,
                 COALESCE(pa.section_code, f.section_code) AS section_code,
                 COALESCE(pa.section_name, f.section_name) AS section_name,
                 wt.id::text AS work_type_id,
                 wt.code AS work_type_code,
                 wt.name AS work_type_name,
                 wt.analytics_tag AS work_type_analytics_tag,
                 COALESCE(pa.unit, f.unit, wt.default_unit, '') AS unit,
                 LEAST(COALESCE(pa.pk_start, f.pk_start), COALESCE(f.pk_start, pa.pk_start)) AS pk_start,
                 GREATEST(COALESCE(pa.pk_end, f.pk_end), COALESCE(f.pk_end, pa.pk_end)) AS pk_end,
                 NULL::text AS pk_raw_text,
                 COALESCE(pa.project_volume, 0) AS project_volume,
                 pa.project_item_id,
                 COALESCE(pa.project_item_count, 0) AS project_item_count,
                 COALESCE(pa.project_segment_count, 0) AS project_segment_count,
                 0::numeric AS planned_volume,
                 COALESCE(f.fact_volume, 0) AS fact_volume,
                 f.fact_pk_ranges,
                 NULL::date AS period_start,
                 NULL::date AS period_end,
                 'project_fact_without_plan'::text AS plan_type,
                 'auto:project_or_fact'::text AS source_reference,
                 NULL::text AS comment,
                 NULL::timestamptz AS updated_at,
                 COALESCE(pa.section_sort_order, f.section_sort_order) AS section_sort_order,
                 NULL::timestamptz AS created_at
          FROM project_agg pa
          FULL OUTER JOIN fact_agg f
            ON f.object_id = pa.object_id
           AND f.work_type_id = pa.work_type_id
           AND COALESCE(f.unit, '') = COALESCE(pa.unit, '')
           AND COALESCE(f.section_code, '') = COALESCE(pa.section_code, '')
           AND (
             pa.pk_start IS NULL OR pa.pk_end IS NULL
             OR f.pk_start IS NULL OR f.pk_end IS NULL
             OR LEAST(GREATEST(f.pk_start, f.pk_end), GREATEST(pa.pk_start, pa.pk_end))
                >= GREATEST(LEAST(f.pk_start, f.pk_end), LEAST(pa.pk_start, pa.pk_end))
           )
          JOIN scoped_objects so
            ON so.id::text = COALESCE(pa.object_id, f.object_id)
           AND COALESCE(so.section_code, '') = COALESCE(pa.section_code, f.section_code, '')
          JOIN work_types wt ON wt.id::text = COALESCE(pa.work_type_id, f.work_type_id)
          LEFT JOIN LATERAL (
            SELECT existing.id
            FROM planned_work_items existing
            LEFT JOIN pile_fields existing_pf ON existing_pf.id = existing.source_pile_field_id
            WHERE existing.object_id = so.id
              AND existing.work_type_id = wt.id
              AND COALESCE(NULLIF(existing.unit, ''), wt.default_unit, '') = COALESCE(pa.unit, f.unit, wt.default_unit, '')
              AND {existing_plan_filter_sql}
            LIMIT 1
          ) existing ON true
          WHERE existing.id IS NULL
            AND (COALESCE(pa.project_volume, 0) <> 0 OR COALESCE(f.fact_volume, 0) <> 0)
        """
    row_query_params = scope_params + project_params + fact_pk_params + plan_params
    if source in {"auto", "fact"}:
        row_query_params = row_query_params + plan_params

    rows = query(
        _statement_scope_cte()
        + f"""
        , scoped_objects AS (
          SELECT *
          FROM object_sections
          WHERE {scope_filter_sql}
        ),
        project_items AS (
          SELECT pwi.id::text AS item_id,
                 so.id::text AS object_id,
                 so.object_code,
                 so.object_name,
                 so.object_type_code,
                 so.object_type_name,
                 so.section_code,
                 so.section_name,
                 so.section_sort_order,
                 wt.id::text AS work_type_id,
                 COALESCE(pwi.unit, wt.default_unit, '') AS unit,
                 row_scope.row_pk_start AS pk_start,
                 row_scope.row_pk_end AS pk_end,
                 CASE
                   WHEN COUNT(ps.id) FILTER (WHERE ps.id IS NOT NULL) > 0
                    AND COUNT(ps.volume_segment) FILTER (WHERE ps.volume_segment IS NOT NULL) > 0
                     THEN SUM(COALESCE(ps.volume_segment, 0) * row_scope.row_pk_factor)
                   ELSE MAX(pwi.project_volume) * MAX(row_scope.row_pk_factor)
                 END AS project_volume,
                 COUNT(ps.id) FILTER (WHERE ps.id IS NOT NULL) AS project_segment_count
          FROM project_work_items pwi
          LEFT JOIN constructives con ON con.id = pwi.constructive_id
          JOIN scoped_objects so ON so.id = COALESCE(pwi.object_id, con.object_id)
          JOIN work_types wt ON wt.id = pwi.work_type_id
          LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
          LEFT JOIN project_work_item_segments ps ON ps.project_work_item_id = pwi.id
          {_statement_row_scope_lateral_sql('COALESCE(ps.pk_start, pf.pk_start)', 'COALESCE(ps.pk_end, pf.pk_end)', 'so')}
          WHERE (COALESCE(pwi.project_volume, 0) <> 0 OR COALESCE(ps.volume_segment, 0) <> 0)
            AND {project_filter_sql}
            AND row_scope.row_pk_has_overlap
          GROUP BY pwi.id, so.id, so.object_code, so.object_name, so.object_type_code, so.object_type_name,
                   so.section_code, so.section_name, so.section_sort_order, wt.id, COALESCE(pwi.unit, wt.default_unit, ''),
                   row_scope.row_pk_start, row_scope.row_pk_end
        ),
        project_agg AS (
          SELECT object_id,
                 object_code,
                 object_name,
                 object_type_code,
                 object_type_name,
                 section_code,
                 section_name,
                 section_sort_order,
                 work_type_id,
                 unit,
                 MIN(pk_start) AS pk_start,
                 MAX(pk_end) AS pk_end,
                 SUM(COALESCE(project_volume, 0))::numeric AS project_volume,
                 CASE WHEN COUNT(DISTINCT item_id) = 1 THEN MIN(item_id) ELSE NULL END AS project_item_id,
                 COUNT(DISTINCT item_id) AS project_item_count,
                 SUM(COALESCE(project_segment_count, 0))::int AS project_segment_count
          FROM project_items
          GROUP BY object_id, object_code, object_name, object_type_code, object_type_name,
                   section_code, section_name, section_sort_order, work_type_id, unit
        ),
        fact_items AS (
          SELECT dwi.id::text AS item_id,
                 so.id::text AS object_id,
                 so.object_code,
                 so.object_name,
                 so.object_type_code,
                 so.object_type_name,
                 so.section_code,
                 so.section_name,
                 so.section_sort_order,
                 wt.id::text AS work_type_id,
                 COALESCE(dwi.unit, wt.default_unit, '') AS unit,
                 row_scope.row_pk_start AS pk_start,
                 row_scope.row_pk_end AS pk_end,
                 CASE
                   WHEN COUNT(ds.id) FILTER (WHERE ds.id IS NOT NULL) > 0
                    AND COUNT(ds.volume_segment) FILTER (WHERE ds.volume_segment IS NOT NULL) > 0
                     THEN SUM(COALESCE(ds.volume_segment, 0) * row_scope.row_pk_factor)
                   ELSE MAX(dwi.volume) * MAX(row_scope.row_pk_factor)
                 END AS fact_volume
          FROM daily_work_items dwi
          JOIN daily_reports dr ON dr.id = dwi.daily_report_id
          LEFT JOIN constructives con ON con.id = dwi.constructive_id
          JOIN scoped_objects so ON so.id = COALESCE(dwi.object_id, con.object_id)
          JOIN work_types wt ON wt.id = dwi.work_type_id
          LEFT JOIN daily_work_item_segments ds ON ds.daily_work_item_id = dwi.id AND ds.is_demo IS NOT TRUE
          LEFT JOIN pile_fields pf ON pf.id = ds.pile_field_id
          {_statement_row_scope_lateral_sql('COALESCE(ds.pk_start, pf.pk_start)', 'COALESCE(ds.pk_end, pf.pk_end)', 'so')}
          WHERE dwi.is_demo IS NOT TRUE
            AND COALESCE(dr.is_demo, false) IS FALSE
            AND {_statement_fact_report_condition("dr")}
            AND {fact_pk_sql}
            AND row_scope.row_pk_has_overlap
          GROUP BY dwi.id, so.id, so.object_code, so.object_name, so.object_type_code, so.object_type_name,
                   so.section_code, so.section_name, so.section_sort_order, wt.id, COALESCE(dwi.unit, wt.default_unit, ''),
                   row_scope.row_pk_start, row_scope.row_pk_end
        ),
        fact_agg AS (
          SELECT object_id,
                 object_code,
                 object_name,
                 object_type_code,
                 object_type_name,
                 section_code,
                 section_name,
                 section_sort_order,
                 work_type_id,
                 unit,
                 MIN(pk_start) AS pk_start,
                 MAX(pk_end) AS pk_end,
                 SUM(COALESCE(fact_volume, 0))::numeric AS fact_volume,
                 STRING_AGG(DISTINCT public.format_route_pk_range(pk_start, pk_end), '; ')
                   FILTER (WHERE pk_start IS NOT NULL OR pk_end IS NOT NULL) AS fact_pk_ranges
          FROM fact_items
          GROUP BY object_id, object_code, object_name, object_type_code, object_type_name,
                   section_code, section_name, section_sort_order, work_type_id, unit
        )
        SELECT *
        FROM (
          SELECT pwi.id::text AS plan_id,
                 so.id::text AS object_id,
                 so.object_code,
                 so.object_name,
                 so.object_type_code,
                 so.object_type_name,
                 so.section_code,
                 so.section_name,
                 wt.id::text AS work_type_id,
                 wt.code AS work_type_code,
                 wt.name AS work_type_name,
                 wt.analytics_tag AS work_type_analytics_tag,
                 COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '') AS unit,
                 row_scope.row_pk_start AS pk_start,
                 row_scope.row_pk_end AS pk_end,
                 CASE WHEN row_scope.row_pk_clipped THEN NULL ELSE COALESCE(pwi.pk_raw_text, pf.pk_raw_text) END AS pk_raw_text,
                 COALESCE(pa.project_volume, 0) AS project_volume,
                 pa.project_item_id,
                 pa.project_item_count,
                 COALESCE(pa.project_segment_count, 0) AS project_segment_count,
                 COALESCE(pwi.planned_volume, 0) * row_scope.row_pk_factor AS planned_volume,
                 COALESCE(f.fact_volume, 0) AS fact_volume,
                 f.fact_pk_ranges,
                 pwi.period_start,
                 pwi.period_end,
                 pwi.plan_type,
                 pwi.source_reference,
                 pwi.comment,
                 pwi.updated_at,
                 so.section_sort_order,
                 pwi.created_at
          FROM planned_work_items pwi
          JOIN scoped_objects so ON so.id = pwi.object_id
          JOIN work_types wt ON wt.id = pwi.work_type_id
          LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
          {_statement_plan_row_scope_lateral_sql('pwi', 'so', 'pf')}
          LEFT JOIN LATERAL (
            SELECT SUM(
                     CASE
                       WHEN pi.pk_start IS NOT NULL AND pi.pk_end IS NOT NULL
                        AND row_scope.row_pk_start IS NOT NULL AND row_scope.row_pk_end IS NOT NULL
                         THEN CASE
                           WHEN LEAST(GREATEST(pi.pk_start, pi.pk_end), GREATEST(row_scope.row_pk_start, row_scope.row_pk_end))
                              >= GREATEST(LEAST(pi.pk_start, pi.pk_end), LEAST(row_scope.row_pk_start, row_scope.row_pk_end))
                             THEN COALESCE(pi.project_volume, 0) * CASE
                               WHEN ABS(pi.pk_end - pi.pk_start) < 0.000001 THEN 1
                               ELSE (
                                 LEAST(GREATEST(pi.pk_start, pi.pk_end), GREATEST(row_scope.row_pk_start, row_scope.row_pk_end))
                                 - GREATEST(LEAST(pi.pk_start, pi.pk_end), LEAST(row_scope.row_pk_start, row_scope.row_pk_end))
                               ) / NULLIF(ABS(pi.pk_end - pi.pk_start), 0)
                             END
                           ELSE 0
                         END
                       ELSE COALESCE(pi.project_volume, 0)
                     END
                   )::numeric AS project_volume,
                   CASE WHEN COUNT(DISTINCT pi.item_id) = 1 THEN MIN(pi.item_id) ELSE NULL END AS project_item_id,
                   COUNT(DISTINCT pi.item_id) AS project_item_count,
                   SUM(COALESCE(pi.project_segment_count, 0))::int AS project_segment_count
            FROM project_items pi
            WHERE pi.object_id = so.id::text
	              AND pi.work_type_id = wt.id::text
	              AND COALESCE(pi.unit, '') = COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '')
	              AND COALESCE(pi.section_code, '') = COALESCE(so.section_code, '')
              AND (
                pi.pk_start IS NULL OR pi.pk_end IS NULL
                OR row_scope.row_pk_start IS NULL OR row_scope.row_pk_end IS NULL
                OR LEAST(GREATEST(pi.pk_start, pi.pk_end), GREATEST(row_scope.row_pk_start, row_scope.row_pk_end))
                   >= GREATEST(LEAST(pi.pk_start, pi.pk_end), LEAST(row_scope.row_pk_start, row_scope.row_pk_end))
              )
          ) pa ON true
          LEFT JOIN LATERAL (
            SELECT SUM(
                     CASE
                       WHEN fi.pk_start IS NOT NULL AND fi.pk_end IS NOT NULL
                        AND row_scope.row_pk_start IS NOT NULL AND row_scope.row_pk_end IS NOT NULL
                         THEN CASE
                           WHEN LEAST(GREATEST(fi.pk_start, fi.pk_end), GREATEST(row_scope.row_pk_start, row_scope.row_pk_end))
                              >= GREATEST(LEAST(fi.pk_start, fi.pk_end), LEAST(row_scope.row_pk_start, row_scope.row_pk_end))
                             THEN COALESCE(fi.fact_volume, 0) * CASE
                               WHEN ABS(fi.pk_end - fi.pk_start) < 0.000001 THEN 1
                               ELSE (
                                 LEAST(GREATEST(fi.pk_start, fi.pk_end), GREATEST(row_scope.row_pk_start, row_scope.row_pk_end))
                                 - GREATEST(LEAST(fi.pk_start, fi.pk_end), LEAST(row_scope.row_pk_start, row_scope.row_pk_end))
                               ) / NULLIF(ABS(fi.pk_end - fi.pk_start), 0)
                             END
                           ELSE 0
                         END
                       ELSE COALESCE(fi.fact_volume, 0)
                     END
                   )::numeric AS fact_volume,
                   STRING_AGG(DISTINCT public.format_route_pk_range(fi.pk_start, fi.pk_end), '; ')
                     FILTER (WHERE fi.pk_start IS NOT NULL OR fi.pk_end IS NOT NULL) AS fact_pk_ranges
            FROM fact_items fi
            WHERE fi.object_id = so.id::text
	              AND fi.work_type_id = wt.id::text
	              AND COALESCE(fi.unit, '') = COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '')
	              AND COALESCE(fi.section_code, '') = COALESCE(so.section_code, '')
              AND (
                fi.pk_start IS NULL OR fi.pk_end IS NULL
                OR row_scope.row_pk_start IS NULL OR row_scope.row_pk_end IS NULL
                OR LEAST(GREATEST(fi.pk_start, fi.pk_end), GREATEST(row_scope.row_pk_start, row_scope.row_pk_end))
                   >= GREATEST(LEAST(fi.pk_start, fi.pk_end), LEAST(row_scope.row_pk_start, row_scope.row_pk_end))
              )
          ) f ON true
          WHERE {plan_filter_sql}
            AND row_scope.row_pk_has_overlap
          {unplanned_union_sql}
        ) statement_rows
        ORDER BY section_sort_order NULLS LAST, section_code NULLS LAST,
                 pk_start NULLS LAST, pk_end NULLS LAST,
                 object_name, object_code NULLS LAST,
                 work_type_name, period_start NULLS LAST, created_at NULLS LAST
        LIMIT 5000
        """,
        row_query_params,
    )

    if source == "fact":
        rows = [row for row in rows if _as_float(row.get("fact_volume")) != 0]
    rows = _statement_filter_rows_by_query(rows, q)

    period_values_by_key: dict[str, dict[str, dict]] = {}
    if periods:
        period_start = periods[0]["start_date"]
        period_end = periods[-1]["end_date"]
        plan_period_rows = query(
            _statement_scope_cte()
            + f"""
            , scoped_objects AS (
              SELECT *
              FROM object_sections
              WHERE {scope_filter_sql}
            )
            SELECT so.id::text AS object_id,
                   wt.id::text AS work_type_id,
                   COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '') AS unit,
                   row_scope.row_pk_start AS pk_start,
                   row_scope.row_pk_end AS pk_end,
                   pwi.period_start,
                   pwi.period_end,
                   COALESCE(pwi.planned_volume, 0) * row_scope.row_pk_factor AS planned_volume
            FROM planned_work_items pwi
            JOIN scoped_objects so ON so.id = pwi.object_id
            JOIN work_types wt ON wt.id = pwi.work_type_id
            LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
            {_statement_plan_row_scope_lateral_sql('pwi', 'so', 'pf')}
            WHERE {plan_filter_sql}
              AND row_scope.row_pk_has_overlap
              AND (pwi.period_start IS NOT NULL OR pwi.period_end IS NOT NULL)
            """,
            scope_params + plan_params,
        )
        for plan_row in plan_period_rows:
            start = plan_row.get("period_start") or plan_row.get("period_end")
            end = plan_row.get("period_end") or plan_row.get("period_start")
            if not start or not end:
                continue
            if start > end:
                start, end = end, start
            total_days = max(1, (end - start).days + 1)
            value = _as_float(plan_row.get("planned_volume"))
            key = _statement_period_row_key(
                plan_row.get("object_id"),
                plan_row.get("work_type_id"),
                plan_row.get("unit") or "—",
                plan_row.get("pk_start"),
                plan_row.get("pk_end"),
            )
            bucket_values = period_values_by_key.setdefault(key, _statement_period_values_template(periods))
            for period in periods:
                overlap = _statement_overlap_days(start, end, period["start_date"], period["end_date"])
                if overlap:
                    bucket_values[period["key"]]["planned_volume"] += value * overlap / total_days

        fact_period_rows = query(
            _statement_scope_cte()
            + f"""
            , scoped_objects AS (
              SELECT *
              FROM object_sections
              WHERE {scope_filter_sql}
            )
            , fact_items AS (
              SELECT dwi.id::text AS item_id,
                     so.id::text AS object_id,
                     wt.id::text AS work_type_id,
                     COALESCE(dwi.unit, wt.default_unit, '') AS unit,
                     row_scope.row_pk_start AS pk_start,
                     row_scope.row_pk_end AS pk_end,
                     dr.report_date,
                     CASE
                       WHEN COUNT(ds.id) FILTER (WHERE ds.id IS NOT NULL) > 0
                        AND COUNT(ds.volume_segment) FILTER (WHERE ds.volume_segment IS NOT NULL) > 0
                         THEN SUM(COALESCE(ds.volume_segment, 0) * row_scope.row_pk_factor)
                       ELSE MAX(dwi.volume) * MAX(row_scope.row_pk_factor)
                     END AS fact_volume
              FROM daily_work_items dwi
              JOIN daily_reports dr ON dr.id = dwi.daily_report_id
              LEFT JOIN constructives con ON con.id = dwi.constructive_id
              JOIN scoped_objects so ON so.id = COALESCE(dwi.object_id, con.object_id)
              JOIN work_types wt ON wt.id = dwi.work_type_id
              LEFT JOIN daily_work_item_segments ds ON ds.daily_work_item_id = dwi.id AND ds.is_demo IS NOT TRUE
              LEFT JOIN pile_fields pf ON pf.id = ds.pile_field_id
              {_statement_row_scope_lateral_sql('COALESCE(ds.pk_start, pf.pk_start)', 'COALESCE(ds.pk_end, pf.pk_end)', 'so')}
              WHERE dwi.is_demo IS NOT TRUE
                AND COALESCE(dr.is_demo, false) IS FALSE
                AND {_statement_fact_report_condition("dr")}
                AND dr.report_date >= %s::date
                AND dr.report_date <= %s::date
                AND {fact_pk_sql}
                AND row_scope.row_pk_has_overlap
              GROUP BY dwi.id, so.id, wt.id, COALESCE(dwi.unit, wt.default_unit, ''),
                       row_scope.row_pk_start, row_scope.row_pk_end, dr.report_date
            )
            SELECT object_id,
                   work_type_id,
                   unit,
                   pk_start,
                   pk_end,
                   report_date,
                   SUM(COALESCE(fact_volume, 0))::numeric AS fact_volume
            FROM fact_items
            GROUP BY object_id, work_type_id, unit, pk_start, pk_end, report_date
            """,
            scope_params + [period_start, period_end] + fact_pk_params,
        )
        for fact_row in fact_period_rows:
            period_key = _statement_period_key_for_date(periods, fact_row.get("report_date"))
            if not period_key:
                continue
            key = _statement_period_row_key(
                fact_row.get("object_id"),
                fact_row.get("work_type_id"),
                fact_row.get("unit") or "—",
                fact_row.get("pk_start"),
                fact_row.get("pk_end"),
            )
            bucket_values = period_values_by_key.setdefault(key, _statement_period_values_template(periods))
            bucket_values[period_key]["fact_volume"] += _as_float(fact_row.get("fact_volume"))

    normalized_rows: list[dict] = []
    totals_by_unit: dict[str, dict] = {}
    seen_total_project: set[str] = set()
    seen_total_fact: set[str] = set()
    for row in rows:
        project_volume = _as_float(row.get("project_volume"))
        planned_volume = _as_float(row.get("planned_volume"))
        fact_volume = _as_float(row.get("fact_volume"))
        baseline_volume = planned_volume if planned_volume else project_volume
        remaining_volume = round(baseline_volume - fact_volume, 3)
        pct = round(fact_volume / baseline_volume * 100, 1) if baseline_volume else None
        unit = row.get("unit") or "—"
        row_period_key = _statement_period_row_key(row.get("object_id"), row.get("work_type_id"), unit, row.get("pk_start"), row.get("pk_end"))
        total_key = f"{unit}||{_statement_volume_base_row_key(row.get('object_id'), row.get('work_type_id'), unit)}"
        bucket = totals_by_unit.setdefault(unit, {"unit": unit, "project_volume": 0.0, "planned_volume": 0.0, "fact_volume": 0.0, "remaining_volume": 0.0})
        if total_key not in seen_total_project:
            bucket["project_volume"] += project_volume
            seen_total_project.add(total_key)
        bucket["planned_volume"] += planned_volume
        if total_key not in seen_total_fact:
            bucket["fact_volume"] += fact_volume
            seen_total_fact.add(total_key)
        row_period_values = period_values_by_key.get(row_period_key, _statement_period_values_template(periods)) if periods else {}
        normalized_rows.append({
            "plan_id": row.get("plan_id"),
            "object_id": row.get("object_id"),
            "object_code": row.get("object_code"),
            "object_name": row.get("object_name"),
            "object_type_code": row.get("object_type_code"),
            "object_type_name": row.get("object_type_name"),
            "section_code": _merge_section(row.get("section_code")) or row.get("section_code"),
            "section_name": row.get("section_name"),
            "work_type_id": row.get("work_type_id"),
            "work_type_code": row.get("work_type_code"),
            "work_type_name": row.get("work_type_name"),
            "unit": unit,
            "pk_start": _as_float(row.get("pk_start")) if row.get("pk_start") is not None else None,
            "pk_end": _as_float(row.get("pk_end")) if row.get("pk_end") is not None else None,
            "pk_raw_text": row.get("pk_raw_text"),
            "project_volume": project_volume,
            "planned_volume": planned_volume,
            "fact_volume": fact_volume,
            "fact_pk_ranges": row.get("fact_pk_ranges"),
            "remaining_volume": remaining_volume,
            "percent_complete": pct,
            "project_item_id": row.get("project_item_id"),
            "project_item_count": int(row.get("project_item_count") or 0),
            "project_segment_count": int(row.get("project_segment_count") or 0),
            "can_edit_project": bool(row.get("project_item_id")),
            "period_start": row.get("period_start").isoformat() if row.get("period_start") else None,
            "period_end": row.get("period_end").isoformat() if row.get("period_end") else None,
            "plan_type": row.get("plan_type") or "total",
            "source_reference": row.get("source_reference"),
            "comment": row.get("comment"),
            "updated_at": row.get("updated_at").isoformat() if row.get("updated_at") else None,
            "period_values": [
                {
                    "period_key": item["period_key"],
                    "planned_volume": round(item["planned_volume"], 3),
                    "fact_volume": round(item["fact_volume"], 3),
                }
                for item in row_period_values.values()
            ],
            "can_edit": True,
        })

    totals = []
    for bucket in totals_by_unit.values():
        bucket["project_volume"] = round(bucket["project_volume"], 3)
        bucket["planned_volume"] = round(bucket["planned_volume"], 3)
        bucket["fact_volume"] = round(bucket["fact_volume"], 3)
        baseline = bucket["planned_volume"] or bucket["project_volume"]
        bucket["remaining_volume"] = round(baseline - bucket["fact_volume"], 3)
        bucket["percent_complete"] = round(bucket["fact_volume"] / baseline * 100, 1) if baseline else None
        totals.append(bucket)

    metadata = _statement_metadata_payload(section, pk_from, pk_to, object_type)

    return {
        "filters": {
            "section": section or "all",
            "section_codes": section_codes or [],
            "object_id": object_id,
            "object_type": object_type or "all",
            "pk_from": pk_from_num,
            "pk_to": pk_to_num,
            "period_from": period_from_date.isoformat() if period_from_date else None,
            "period_to": period_to_date.isoformat() if period_to_date else None,
            "work_type_id": work_type_id or "all",
            "q": (q or "").strip(),
        },
        "schema": metadata.get("schema") or _statement_schema_flags(),
        "source": "fact_daily_work_items" if source == "fact" else "planned_work_items",
        "editable": True,
        "sections": metadata.get("sections", []),
        "object_types": metadata.get("object_types", []),
        "objects": metadata.get("objects", []),
        "work_types": metadata.get("work_types", []),
        "periods": _statement_period_response(periods),
        "rows": normalized_rows,
        "totals": sorted(totals, key=lambda item: item["unit"]),
        "row_count": len(normalized_rows),
    }


def _statement_group_label(row: dict, group_by: str) -> str:
    if group_by == "section":
        return row.get("section_name") or row.get("section_code") or "Без участка"
    if group_by == "object_type":
        return row.get("object_type_name") or row.get("object_type_code") or "Тип не задан"
    if group_by == "picket_segment":
        start = row.get("pk_start")
        end = row.get("pk_end")
        formatted = query_one("SELECT public.format_route_pk_range(%s, %s) AS pk", [start, end]).get("pk") if start is not None or end is not None else None
        return formatted or "Без пикетажа"
    return row.get("object_name") or row.get("object_code") or "Без объекта"


def _statement_aggregate_for_export(rows: list[dict], group_by: str) -> list[dict]:
    if group_by not in {"section", "object_type", "object", "picket_segment"}:
        return rows
    buckets: dict[tuple, dict] = {}
    for row in rows:
        label = _statement_group_label(row, group_by)
        key = (label, row.get("work_type_id"), row.get("unit"), row.get("period_start"), row.get("period_end"))
        bucket = buckets.get(key)
        if not bucket:
            bucket = dict(row)
            bucket["group_label"] = label
            bucket["source_rows"] = 0
            bucket["project_volume"] = 0.0
            bucket["planned_volume"] = 0.0
            bucket["fact_volume"] = 0.0
            bucket["remaining_volume"] = 0.0
            bucket["fact_pk_ranges"] = None
            bucket["_period_values_map"] = {}
            buckets[key] = bucket
        bucket["source_rows"] += 1
        bucket["project_volume"] += _as_float(row.get("project_volume"))
        bucket["planned_volume"] += _as_float(row.get("planned_volume") if row.get("planned_volume") is not None else row.get("project_volume"))
        bucket["fact_volume"] += _as_float(row.get("fact_volume"))
        bucket["remaining_volume"] += _as_float(row.get("remaining_volume"))
        period_map = bucket.setdefault("_period_values_map", {})
        for item in row.get("period_values") or []:
            period_key = item.get("period_key")
            if not period_key:
                continue
            period_bucket = period_map.setdefault(period_key, {"period_key": period_key, "planned_volume": 0.0, "fact_volume": 0.0})
            period_bucket["planned_volume"] += _as_float(item.get("planned_volume"))
            period_bucket["fact_volume"] += _as_float(item.get("fact_volume"))
        if row.get("pk_start") is not None:
            bucket["pk_start"] = row.get("pk_start") if bucket.get("pk_start") is None else min(bucket.get("pk_start"), row.get("pk_start"))
        if row.get("pk_end") is not None:
            bucket["pk_end"] = row.get("pk_end") if bucket.get("pk_end") is None else max(bucket.get("pk_end"), row.get("pk_end"))
        ranges = [value for value in [bucket.get("fact_pk_ranges"), row.get("fact_pk_ranges")] if value]
        bucket["fact_pk_ranges"] = "; ".join(dict.fromkeys("; ".join(ranges).split("; "))) if ranges else None
    result = []
    for bucket in buckets.values():
        baseline = bucket.get("planned_volume") or bucket.get("project_volume") or 0
        bucket["percent_complete"] = round(bucket.get("fact_volume", 0) / baseline * 100, 1) if baseline else None
        bucket["period_values"] = list(bucket.pop("_period_values_map", {}).values())
        if int(bucket.get("source_rows") or 0) > 1:
            bucket["object_id"] = None
            bucket["work_type_id"] = None
            bucket["plan_id"] = None
            bucket["project_item_id"] = None
        result.append(bucket)
    return result


def _statement_export_text(value) -> str:
    return str(value or "").strip().lower()


def _statement_export_sort_number(value) -> float:
    return float(value) if value is not None else 10**18


def _statement_export_sort_key(row: dict) -> tuple:
    return (
        _statement_export_text(row.get("section_code") or row.get("section_name")),
        _statement_export_text(row.get("object_type_code") or row.get("object_type_name")),
        _statement_export_sort_number(row.get("pk_start")),
        _statement_export_text(row.get("object_name") or row.get("object_code")),
        _statement_export_text(row.get("work_type_name") or row.get("work_type_code")),
    )


def _statement_export_row_bucket_key(row: dict) -> str:
    return "||".join(str(item or "") for item in [row.get("object_id"), row.get("work_type_id"), row.get("unit") or "—"])


def _statement_export_period_row_bucket_key(row: dict) -> str:
    base = _statement_export_row_bucket_key(row)
    if row.get("pk_start") is None and row.get("pk_end") is None:
        return base
    return f"{base}||{_statement_period_pk_part(row.get('pk_start'))}||{_statement_period_pk_part(row.get('pk_end'))}"


def _statement_export_sum_once_by_work(rows: list[dict], field: str) -> float:
    buckets: dict[str, float] = {}
    for row in rows:
        key = _statement_export_row_bucket_key(row)
        if key not in buckets:
            buckets[key] = _as_float(row.get(field))
    return sum(buckets.values())


def _statement_export_common_value(rows: list[dict], field: str):
    if not rows:
        return None
    first = rows[0].get(field)
    return first if all(row.get(field) == first for row in rows) else None


def _statement_export_picketage_sort_key(row: dict) -> tuple:
    return (
        _statement_export_sort_number(row.get("pk_start")),
        _statement_export_text(row.get("object_code") or row.get("object_name")),
        _statement_export_sort_number(row.get("pk_end")),
        _statement_export_text(row.get("work_type_code") or row.get("work_type_name")),
        _statement_export_text(row.get("section_code") or row.get("section_name")),
        _statement_export_text(row.get("object_type_code") or row.get("object_type_name")),
    )


def _statement_section_label(row: dict) -> str:
    return row.get("section_name") or row.get("section_code") or "Без участка"


def _statement_object_type_label(row: dict) -> str:
    return row.get("object_type_name") or row.get("object_type_code") or "Тип не задан"


def _statement_object_label(row: dict) -> str:
    return row.get("object_name") or row.get("object_code") or "Без объекта"


def _statement_work_label(row: dict) -> str:
    return row.get("work_type_name") or row.get("work_type_code") or "Работа"


def _statement_object_branch_label(row: dict) -> str:
    pk = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text"))
    return f"{_statement_object_label(row)} · {pk}" if pk else _statement_object_label(row)


def _statement_route_object_branch_label(row: dict) -> str:
    pk = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text"))
    return f"{pk} · {_statement_object_label(row)}" if pk else _statement_object_label(row)


def _statement_route_object_group_label(rows: list[dict]) -> str:
    first = rows[0]
    starts = [float(row.get("pk_start")) for row in rows if row.get("pk_start") is not None]
    ends = [float(row.get("pk_end") if row.get("pk_end") is not None else row.get("pk_start")) for row in rows if row.get("pk_end") is not None or row.get("pk_start") is not None]
    pk = _format_pk_range_excel(min(starts) if starts else None, max(ends) if ends else None)
    return f"{pk} · {_statement_object_label(first)}" if pk else _statement_object_label(first)


def _statement_route_work_label(row: dict) -> str:
    pk = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"), row.get("pk_raw_text"))
    return f"{pk} · {_statement_work_label(row)}" if pk else _statement_work_label(row)


def _statement_export_group_rows(rows: list[dict], key_for, label_for, sort_key_for=_statement_export_sort_key) -> list[dict]:
    buckets: dict[str, dict] = {}
    for row in rows:
        key = str(key_for(row))
        bucket = buckets.get(key)
        if bucket:
            bucket["rows"].append(row)
        else:
            buckets[key] = {"key": key, "label": label_for(row), "rows": [row]}
    return sorted(buckets.values(), key=lambda item: (sort_key_for(item["rows"][0]), item["label"]))


def _statement_export_period_values(rows: list[dict]) -> list[dict]:
    buckets: dict[str, dict] = {}
    seen_contributions: set[str] = set()
    for row in rows:
        source_key = _statement_export_period_row_bucket_key(row)
        for value in row.get("period_values") or []:
            key = value.get("period_key")
            if not key:
                continue
            planned = _as_float(value.get("planned_volume"))
            fact = _as_float(value.get("fact_volume"))
            contribution_key = f"{source_key}||{key}||{planned}||{fact}"
            if contribution_key in seen_contributions:
                continue
            seen_contributions.add(contribution_key)
            bucket = buckets.setdefault(key, {"period_key": key, "planned_volume": 0.0, "fact_volume": 0.0})
            bucket["planned_volume"] += planned
            bucket["fact_volume"] += fact
    return [
        {
            "period_key": item["period_key"],
            "planned_volume": round(item["planned_volume"], 3),
            "fact_volume": round(item["fact_volume"], 3),
        }
        for item in sorted(buckets.values(), key=lambda item: item["period_key"])
    ]


def _statement_export_display_row(rows: list[dict], label: str, depth: int, key: str, kind: str, is_group: bool) -> dict:
    first = dict(rows[0])
    project_volume = _statement_export_sum_once_by_work(rows, "project_volume")
    planned_volume = sum(_as_float(row.get("planned_volume")) for row in rows)
    fact_volume = _statement_export_sum_once_by_work(rows, "fact_volume")
    baseline = planned_volume or project_volume
    remaining_volume = baseline - fact_volume
    fact_ranges = []
    for row in rows:
        value = row.get("fact_pk_ranges") or (_format_pk_range_excel(row.get("pk_start"), row.get("pk_end")) if row.get("fact_volume") else None)
        if value and value not in fact_ranges:
            fact_ranges.append(value)
    direct_row = None if is_group or len(rows) != 1 else rows[0]
    keep_leaf_identity = kind == "work" and not is_group
    percent_values = [float(row.get("percent_complete")) for row in rows if row.get("percent_complete") is not None]
    first.update({
        "row_key": key,
        "__structure": label,
        "__depth": depth,
        "__is_group": is_group,
        "__group_kind": kind,
        "source_rows": len(rows),
        "project_volume": None if is_group else round(project_volume, 3),
        "planned_volume": None if is_group else round(planned_volume, 3),
        "fact_volume": None if is_group else round(fact_volume, 3),
        "remaining_volume": None if is_group else round(remaining_volume, 3),
        "percent_complete": (round(sum(percent_values) / len(percent_values), 1) if percent_values else None) if is_group else (round(fact_volume / baseline * 100, 1) if baseline else None),
        "fact_pk_ranges": None if is_group else ("; ".join(fact_ranges) or None),
        "period_values": [] if is_group else _statement_export_period_values(rows),
        "id": direct_row.get("id") if direct_row else None,
        "plan_id": direct_row.get("plan_id") if direct_row else None,
        "project_item_id": direct_row.get("project_item_id") if direct_row else None,
        "period_start": _statement_export_common_value(rows, "period_start"),
        "period_end": _statement_export_common_value(rows, "period_end"),
        "pk_start": _statement_export_common_value(rows, "pk_start"),
        "pk_end": _statement_export_common_value(rows, "pk_end"),
        "pk_raw_text": _statement_export_common_value(rows, "pk_raw_text"),
        "object_id": direct_row.get("object_id") if direct_row else (first.get("object_id") if keep_leaf_identity else None),
        "work_type_id": direct_row.get("work_type_id") if direct_row else (first.get("work_type_id") if keep_leaf_identity else None),
    })
    return first


def _statement_export_leaf_rows(rows: list[dict], depth: int, key_prefix: str, sort_key_for=_statement_export_sort_key, split_by_pk: bool = False) -> list[dict]:
    result = []
    for group in _statement_export_group_rows(
        rows,
        lambda row: "||".join(
            str(item)
            for item in (
                [row.get("work_type_id"), row.get("unit") or "", _statement_period_pk_part(row.get("pk_start")), _statement_period_pk_part(row.get("pk_end"))]
                if split_by_pk
                else [row.get("work_type_id"), row.get("unit") or ""]
            )
        ),
        _statement_route_work_label if split_by_pk else _statement_work_label,
        sort_key_for,
    ):
        result.append(_statement_export_display_row(group["rows"], group["label"], depth, f"{key_prefix}:work:{group['key']}", "work", False))
    return result


def _statement_export_append_object_branches(target: list[dict], rows: list[dict], depth: int, key_prefix: str, sort_key_for=_statement_export_sort_key) -> None:
    for group in _statement_export_group_rows(rows, lambda row: row.get("object_id") or _statement_object_label(row), _statement_object_branch_label, sort_key_for):
        target.append(_statement_export_display_row(group["rows"], group["label"], depth, f"{key_prefix}:object:{group['key']}", "object", True))
        target.extend(_statement_export_leaf_rows(group["rows"], depth + 1, f"{key_prefix}:object:{group['key']}", sort_key_for))


def _statement_display_rows_for_export(rows: list[dict], display_mode: Optional[str]) -> list[dict]:
    mode = (display_mode or "").strip() or "raw"
    if mode not in {"section_tree", "type_sections", "picketage", "segment", "raw"}:
        raise HTTPException(400, "display_mode must be one of: section_tree, type_sections, picketage, segment, raw")
    sort_key_for = _statement_export_picketage_sort_key if mode in {"picketage", "segment"} else _statement_export_sort_key
    sorted_rows = sorted(rows, key=sort_key_for)
    if mode == "raw":
        return [
            {
                **row,
                "__structure": f"{_statement_object_label(row)} · {_statement_work_label(row)}",
                "__depth": 0,
                "__is_group": False,
                "source_rows": 1,
            }
            for row in sorted_rows
        ]
    result: list[dict] = []
    if mode == "section_tree":
        for section_group in _statement_export_group_rows(sorted_rows, lambda row: row.get("section_code") or row.get("section_name") or "__none__", _statement_section_label):
            result.append(_statement_export_display_row(section_group["rows"], section_group["label"], 0, f"section:{section_group['key']}", "section", True))
            for type_group in _statement_export_group_rows(section_group["rows"], lambda row: row.get("object_type_code") or row.get("object_type_name") or "__none__", _statement_object_type_label):
                result.append(_statement_export_display_row(type_group["rows"], type_group["label"], 1, f"section:{section_group['key']}:type:{type_group['key']}", "object_type", True))
                _statement_export_append_object_branches(result, type_group["rows"], 2, f"section:{section_group['key']}:type:{type_group['key']}")
        return result
    if mode == "type_sections":
        for type_group in _statement_export_group_rows(sorted_rows, lambda row: row.get("object_type_code") or row.get("object_type_name") or "__none__", _statement_object_type_label):
            result.append(_statement_export_display_row(type_group["rows"], type_group["label"], 0, f"type:{type_group['key']}", "object_type", True))
            for section_group in _statement_export_group_rows(type_group["rows"], lambda row: row.get("section_code") or row.get("section_name") or "__none__", _statement_section_label):
                result.append(_statement_export_display_row(section_group["rows"], section_group["label"], 1, f"type:{type_group['key']}:section:{section_group['key']}", "section", True))
                _statement_export_append_object_branches(result, section_group["rows"], 2, f"type:{type_group['key']}:section:{section_group['key']}")
        return result
    branch_label_for = _statement_route_object_branch_label if mode in {"picketage", "segment"} else _statement_object_branch_label
    for object_group in _statement_export_group_rows(sorted_rows, lambda row: row.get("object_id") or _statement_object_label(row), branch_label_for, sort_key_for):
        label = _statement_route_object_group_label(object_group["rows"]) if mode in {"picketage", "segment"} else object_group["label"]
        result.append(_statement_export_display_row(object_group["rows"], label, 0, f"{mode}:object:{object_group['key']}", "object", True))
        result.extend(_statement_export_leaf_rows(object_group["rows"], 1, f"{mode}:object:{object_group['key']}", sort_key_for, split_by_pk=mode in {"picketage", "segment"}))
    return result


def _statement_display_excel_headers(columns: Optional[str], display_mode: Optional[str]) -> list[tuple[str, str]]:
    mode = (display_mode or "raw").strip()
    headers = [("__structure", "Структура" if mode != "raw" else "Строка")]
    skip = {"group_label"}
    if mode != "raw":
        skip.update({"section_name", "object_type_name", "object_name", "work_type_name"})
    headers.extend(header for header in _statement_excel_headers(columns) if header[0] not in skip)
    return headers


def _statement_period_excel_headers(periods: list[dict]) -> list[tuple[str, str]]:
    headers: list[tuple[str, str]] = []
    for period in periods:
        key = period.get("key")
        label = period.get("label") or key
        if not key:
            continue
        headers.append((f"period:{key}:planned_volume", f"{label} план"))
        headers.append((f"period:{key}:fact_volume", f"{label} факт"))
    return headers


def _statement_import_identity_headers(existing: list[tuple[str, str]]) -> list[tuple[str, str]]:
    existing_keys = {key for key, _label in existing}
    technical = [
        ("object_id", "object_id"),
        ("work_type_id", "work_type_id"),
        ("unit", "unit"),
        ("pk_start", "pk_start"),
        ("pk_end", "pk_end"),
        ("pk_raw_text", "pk_raw_text"),
        ("plan_id", "plan_id"),
        ("project_item_id", "project_item_id"),
        ("project_segment_count", "project_segment_count"),
        ("source_rows", "source_rows"),
        ("__is_group", "__is_group"),
    ]
    return [header for header in technical if header[0] not in existing_keys]


def _statement_label_duplicate_headers(headers: list[tuple[str, str]]) -> list[tuple[str, str]]:
    totals: dict[str, int] = {}
    for key, _label in headers:
        totals[key] = totals.get(key, 0) + 1
    occurrences: dict[str, int] = {}
    result: list[tuple[str, str]] = []
    for key, label in headers:
        occurrences[key] = occurrences.get(key, 0) + 1
        occurrence = occurrences[key]
        result.append((key, f"{label} #{occurrence}" if totals.get(key, 0) > 1 else label))
    return result


def _statement_excel_headers(columns: Optional[str]) -> list[tuple[str, str]]:
    all_headers = [
        ("group_label", "Группа"),
        ("section_name", "Участок"),
        ("object_type_name", "Тип объекта"),
        ("object_name", "Объект"),
        ("work_type_name", "Вид работ"),
        ("unit", "Ед. изм."),
        ("period_start", "Дата/период от"),
        ("period_end", "Дата/период до"),
        ("pk_start", "ПК от"),
        ("pk_end", "ПК до"),
        ("pk_raw_text", "ПК текст"),
        ("project_volume", "Проектный объем"),
        ("planned_volume", "Плановый объем"),
        ("fact_volume", "Фактический объем"),
        ("fact_pk_ranges", "Пикеты выполнения"),
        ("remaining_volume", "Остаток"),
        ("percent_complete", "% выполнения"),
        ("comment", "Комментарий"),
        ("plan_type", "Тип плана"),
        ("source_reference", "Источник"),
        ("updated_at", "Обновлено"),
        ("plan_id", "Тех. ID плана"),
        ("project_item_id", "Тех. ID проекта"),
    ]
    if not columns:
        return all_headers
    requested = [item.strip() for item in columns.split(",") if item.strip()]
    if not requested:
        return all_headers
    by_key = {key: (key, label) for key, label in all_headers}
    headers: list[tuple[str, str]] = []
    if "group_label" not in requested:
        headers.append(by_key["group_label"])
    for key in requested:
        header = by_key.get(key)
        if header:
            headers.append(header)
    return _statement_label_duplicate_headers(headers)


def _statement_excel_cell(row: dict, key: str):
    if key == "__structure":
        return row.get("__structure") or row.get("group_label") or row.get("object_name") or ""
    if key.startswith("period:"):
        _prefix, period_key, field = key.split(":", 2)
        for item in row.get("period_values") or []:
            if item.get("period_key") == period_key:
                value = round(_as_float(item.get(field)), 3)
                return value if value else None
        return None
    if key in {"pk_start", "pk_end"} and row.get(key) is not None:
        return query_one("SELECT public.format_route_pk(%s) AS pk", [row.get(key)]).get("pk")
    return row.get(key)


STATEMENT_EXPORT_EDITABLE_KEYS = {
    "unit",
    "period_start",
    "period_end",
    "pk_start",
    "pk_end",
    "pk_raw_text",
    "project_volume",
    "planned_volume",
    "comment",
}


def _statement_export_editable_key(key: str) -> bool:
    return key in STATEMENT_EXPORT_EDITABLE_KEYS or (key.startswith("period:") and key.endswith(":planned_volume"))


def _statement_excel_truthy(value) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "y", "да"}


def _statement_excel_int(value, default: int = 0) -> int:
    try:
        return int(float(str(value).replace(" ", "").replace(",", ".")))
    except (TypeError, ValueError):
        return default


def _style_statement_export_sheet(ws, headers: list[tuple[str, str]], hidden_keys: set[str], display_mode: Optional[str]) -> None:
    header_fill = PatternFill("solid", fgColor="E9EEF6")
    group_fill = PatternFill("solid", fgColor="F4F6F8")
    editable_fill = PatternFill("solid", fgColor="FFF3CD")
    locked_fill = PatternFill("solid", fgColor="FAFBFC")
    border = Border(
        left=Side(style="thin", color="D9DEE8"),
        right=Side(style="thin", color="D9DEE8"),
        top=Side(style="thin", color="D9DEE8"),
        bottom=Side(style="thin", color="D9DEE8"),
    )
    group_col = next((idx for idx, (key, _label) in enumerate(headers, start=1) if key == "__is_group"), None)
    source_rows_col = next((idx for idx, (key, _label) in enumerate(headers, start=1) if key == "source_rows"), None)
    project_segment_count_col = next((idx for idx, (key, _label) in enumerate(headers, start=1) if key == "project_segment_count"), None)
    object_id_col = next((idx for idx, (key, _label) in enumerate(headers, start=1) if key == "object_id"), None)
    work_type_id_col = next((idx for idx, (key, _label) in enumerate(headers, start=1) if key == "work_type_id"), None)
    ws.freeze_panes = "B2"
    ws.auto_filter.ref = ws.dimensions
    ws.protection.sheet = True
    ws.protection.formatColumns = False
    ws.protection.formatRows = False
    ws.protection.autoFilter = False
    ws.sheet_view.showGridLines = False
    for idx, (key, header) in enumerate(headers, start=1):
        column_letter = get_column_letter(idx)
        width = max(12, min(42, len(header) + 2))
        ws.column_dimensions[column_letter].width = width
        if key in hidden_keys:
            ws.column_dimensions[column_letter].hidden = True
        cell = ws.cell(row=1, column=idx)
        cell.font = Font(bold=True, color="1F2937")
        cell.fill = header_fill
        cell.border = border
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.protection = Protection(locked=True)
    numeric_keys = {"project_volume", "planned_volume", "fact_volume", "remaining_volume", "percent_complete"}
    for row_idx in range(2, ws.max_row + 1):
        is_group = bool(group_col and _statement_excel_truthy(ws.cell(row=row_idx, column=group_col).value))
        source_rows = _statement_excel_int(ws.cell(row=row_idx, column=source_rows_col).value, 1) if source_rows_col else 1
        project_segment_count = _statement_excel_int(ws.cell(row=row_idx, column=project_segment_count_col).value, 0) if project_segment_count_col else 0
        is_multi_source_leaf = not is_group and source_rows > 1
        has_period_identity = bool(
            object_id_col
            and work_type_id_col
            and ws.cell(row=row_idx, column=object_id_col).value
            and ws.cell(row=row_idx, column=work_type_id_col).value
        )
        for col_idx, (key, _label) in enumerate(headers, start=1):
            cell = ws.cell(row=row_idx, column=col_idx)
            editable = _statement_export_editable_key(key) and key not in hidden_keys and not is_group
            if key == "project_volume" and project_segment_count > 1:
                editable = False
            if is_multi_source_leaf:
                editable = (
                    key.startswith("period:")
                    and key.endswith(":planned_volume")
                    and key not in hidden_keys
                    and has_period_identity
                )
            cell.border = border
            cell.protection = Protection(locked=not editable)
            cell.alignment = Alignment(
                horizontal="right" if key in numeric_keys or key.startswith("period:") else "left",
                vertical="top",
                wrap_text=key in {"comment", "fact_pk_ranges", "__structure"},
            )
            if key in numeric_keys or key.startswith("period:"):
                cell.number_format = "#,##0.###"
            if editable:
                cell.fill = editable_fill
            elif is_group:
                cell.fill = group_fill
                cell.font = Font(bold=True, color="1F2937")
            elif (
                key in hidden_keys
                or key.endswith(":fact_volume")
                or key in {"fact_volume", "remaining_volume", "percent_complete", "fact_pk_ranges"}
                or (key == "project_volume" and project_segment_count > 1)
            ):
                cell.fill = locked_fill
        if display_mode and ws.max_column:
            ws.cell(row=row_idx, column=1).alignment = Alignment(indent=min(int(ws.cell(row=row_idx, column=1).alignment.indent or 0), 10), vertical="top", wrap_text=True)


STATEMENT_EXPORT_META_SHEET = "_statements_meta"


def _statement_meta_date(value, field: str) -> Optional[date_cls]:
    if value is None or str(value).strip() == "":
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date_cls):
        return value
    return _statement_parse_date(str(value).strip(), field)


def _statement_workbook_periods(wb) -> list[dict]:
    if STATEMENT_EXPORT_META_SHEET not in wb.sheetnames:
        return []
    ws = wb[STATEMENT_EXPORT_META_SHEET]
    periods: list[dict] = []
    in_periods = False
    for row in ws.iter_rows(values_only=True):
        cells = list(row or [])
        marker = str(cells[0] or "").strip() if cells else ""
        if marker == "period_key":
            in_periods = True
            continue
        if not in_periods or not marker:
            continue
        label = str(cells[1] if len(cells) > 1 and cells[1] is not None else marker).strip() or marker
        start = _statement_meta_date(cells[2] if len(cells) > 2 else None, "period_start")
        end = _statement_meta_date(cells[3] if len(cells) > 3 else None, "period_end")
        if start is None or end is None:
            continue
        if start > end:
            start, end = end, start
        periods.append({"key": marker, "label": label, "start_date": start, "end_date": end})
    return periods


def _statement_write_workbook_metadata(wb, payload: dict, period_mode: str, source: str, display_mode: Optional[str], group_by: str, columns: Optional[str]) -> None:
    ws = wb.create_sheet(STATEMENT_EXPORT_META_SHEET)
    ws.sheet_state = "hidden"
    filters = payload.get("filters") or {}
    ws.append(["schema", "vsm_statements_export_v1"])
    ws.append(["source", source])
    ws.append(["display_mode", display_mode or ""])
    ws.append(["group_by", group_by])
    ws.append(["columns", columns or ""])
    ws.append(["period_mode", period_mode])
    ws.append(["period_from", filters.get("period_from") or ""])
    ws.append(["period_to", filters.get("period_to") or ""])
    ws.append(["q", filters.get("q") or ""])
    ws.append([])
    ws.append(["period_key", "label", "start", "end"])
    for period in payload.get("periods") or []:
        key = period.get("key")
        if not key:
            continue
        ws.append([key, period.get("label") or key, period.get("start") or "", period.get("end") or ""])



def _statement_general_month_bounds(value: Optional[str]) -> tuple[str, date_cls, date_cls]:
    raw = (value or date_cls.today().strftime("%Y-%m")).strip()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
        parsed = date_cls.fromisoformat(raw)
        raw = parsed.strftime("%Y-%m")
    if not re.fullmatch(r"\d{4}-\d{2}", raw):
        raise HTTPException(400, "month must be YYYY-MM")
    year, month = [int(part) for part in raw.split("-")]
    start = date_cls(year, month, 1)
    return raw, start, _statement_month_end(start)


def _statement_general_day_response(start: date_cls, end: date_cls) -> list[dict]:
    days: list[dict] = []
    cursor = start
    while cursor <= end:
        days.append({"key": cursor.isoformat(), "date": cursor.isoformat(), "label": cursor.strftime("%d.%m")})
        cursor += timedelta(days=1)
    return days


def _statement_general_work_rule_payload() -> list[dict]:
    return [
        {
            "code": str(rule.get("code") or ""),
            "label": str(rule.get("label") or rule.get("code") or "Строка"),
            "enabled": bool(rule.get("enabled", True)),
            "include_in_totals": bool(rule.get("include_in_totals", True)),
            "filters": _general_row_filters(rule.get("filters")),
        }
        for rule in _general_report_work_rules()
        if rule.get("enabled", True)
    ]


def _statement_general_row_key(
    category: str,
    section_code: Optional[str],
    object_id: Optional[str],
    work_type_id: Optional[str],
    unit: Optional[str],
    pk_start,
    pk_end,
    pile_length_m=None,
) -> str:
    return "||".join([
        str(category or ""),
        str(_merge_section(section_code) or section_code or ""),
        str(object_id or ""),
        str(work_type_id or ""),
        str(unit or "—"),
        _statement_period_pk_part(pk_start),
        _statement_period_pk_part(pk_end),
        str(_statement_rate_length_key(pile_length_m) or ""),
    ])


STATEMENT_OBJECT_LEVEL_WORK_TYPE_CODES = {"PILE_DYNTEST"}
STATEMENT_GENERATED_PROJECT_TOTAL_SOURCE = "project_work_items:total"
STATEMENT_GENERATED_DYNTEST_PROJECT_SOURCE = "pile_fields:project_duplication"
STATEMENT_PILE_PROJECT_TOTAL_MIRROR_WORK_TYPE_CODES = (
    "PILE_MAIN",
    "PILE_TRIAL",
    "PILE_DYNTEST",
    "PILE_HEADCAP_INSTALLATION",
)


def _statement_general_is_object_level_work_type(work_type_code: Optional[str]) -> bool:
    return str(work_type_code or "").upper() in STATEMENT_OBJECT_LEVEL_WORK_TYPE_CODES


def _statement_general_row_dimensions(
    work_type_code: Optional[str],
    pk_start,
    pk_end,
    pk_raw_text: Optional[str],
    pile_length_m=None,
):
    if _statement_general_is_object_level_work_type(work_type_code):
        return None, None, None, None
    return pk_start, pk_end, pk_raw_text, pile_length_m


def _statement_general_empty_day_values(days: list[dict]) -> dict[str, dict]:
    return {
        day["date"]: {
            "date": day["date"],
            "plan_volume": 0.0,
            "material_plan_volume": 0.0,
            "fact_volume": 0.0,
            "material_fact_volume": 0.0,
            "pk_ranges": [],
            "pk_segments": [],
            "details": [],
        }
        for day in days
    }


def _statement_general_day_value_has_payload(value: dict) -> bool:
    for field in ("plan_volume", "material_plan_volume", "fact_volume", "material_fact_volume"):
        if abs(float(value.get(field) or 0)) > 0.000001:
            return True
    return bool(value.get("pk_segments") or value.get("pk_ranges") or value.get("details"))


def _statement_general_day_value_payload(value: dict) -> dict:
    return {
        **value,
        "plan_volume": round(float(value.get("plan_volume") or 0), 3),
        "material_plan_volume": round(float(value.get("material_plan_volume") or 0), 3),
        "fact_volume": round(float(value.get("fact_volume") or 0), 3),
        "material_fact_volume": round(float(value.get("material_fact_volume") or 0), 3),
    }


def _statement_general_compact_day_values(day_values: dict[str, dict]) -> list[dict]:
    return [
        _statement_general_day_value_payload(value)
        for _, value in sorted((day_values or {}).items())
        if _statement_general_day_value_has_payload(value)
    ]


def _statement_pk_segment(pk_start, pk_end) -> Optional[dict]:
    start = _as_float(pk_start) if pk_start is not None else None
    end = _as_float(pk_end) if pk_end is not None else None
    if start is None and end is None:
        return None
    if start is None:
        start = end
    if end is None:
        end = start
    if start is None or end is None:
        return None
    if start > end:
        start, end = end, start
    return {
        "pk_start": round(start, 3),
        "pk_end": round(end, 3),
        "label": _format_pk_range_excel(start, end),
    }


def _statement_general_fact_index_key(
    category: Optional[str],
    section_code: Optional[str],
    object_id: Optional[str],
    unit: Optional[str],
    pile_length_m=None,
) -> tuple[str, str, str, str, str]:
    return (
        str(category or ""),
        str(_merge_section(section_code) or section_code or ""),
        str(object_id or ""),
        str(unit or "—"),
        str(_statement_rate_length_key(pile_length_m) or ""),
    )


def _statement_general_fact_match_index(rows: dict[str, dict]) -> dict[tuple[str, str, str, str, str], list[dict]]:
    indexed: dict[tuple[str, str, str, str, str], list[dict]] = {}
    for row in rows.values():
        if not (
            float(row.get("project_volume") or 0)
            or float(row.get("month_plan") or 0)
            or float(row.get("cumulative_plan") or 0)
            or float(row.get("material_project_volume") or 0)
            or float(row.get("material_month_plan") or 0)
            or float(row.get("material_cumulative_plan") or 0)
        ):
            continue
        if _statement_pk_range(row.get("pk_start"), row.get("pk_end")) is None:
            continue
        key = _statement_general_fact_index_key(
            row.get("category"),
            row.get("section_code"),
            row.get("object_id"),
            row.get("unit"),
            row.get("pile_length_m"),
        )
        indexed.setdefault(key, []).append(row)
    return indexed


def _statement_general_find_existing_row_for_fact(
    rows: dict[str, dict],
    *,
    category: str,
    section_code: Optional[str],
    object_id: Optional[str],
    work_type_id: Optional[str],
    unit: Optional[str],
    pk_start,
    pk_end,
    pile_length_m=None,
    work_type_code: Optional[str] = None,
    row_index: Optional[dict[tuple[str, str, str, str, str], list[dict]]] = None,
) -> Optional[dict]:
    if _statement_general_is_object_level_work_type(work_type_code):
        normalized_pk_start, normalized_pk_end, _pk_raw_text, normalized_pile_length_m = _statement_general_row_dimensions(
            work_type_code,
            pk_start,
            pk_end,
            None,
            pile_length_m,
        )
        return rows.get(
            _statement_general_row_key(
                category,
                section_code,
                object_id,
                work_type_id,
                unit,
                normalized_pk_start,
                normalized_pk_end,
                normalized_pile_length_m,
            )
        )
    fact_range = _statement_pk_range(pk_start, pk_end)
    if fact_range is None:
        return None
    key = _statement_general_fact_index_key(category, section_code, object_id, unit, pile_length_m)
    candidates = row_index.get(key, []) if row_index is not None else rows.values()
    best_row: Optional[dict] = None
    best_score: Optional[float] = None
    for row in candidates:
        if row_index is None:
            if _statement_general_fact_index_key(row.get("category"), row.get("section_code"), row.get("object_id"), row.get("unit"), row.get("pile_length_m")) != key:
                continue
            if not (
                float(row.get("project_volume") or 0)
                or float(row.get("month_plan") or 0)
                or float(row.get("cumulative_plan") or 0)
                or float(row.get("material_project_volume") or 0)
                or float(row.get("material_month_plan") or 0)
                or float(row.get("material_cumulative_plan") or 0)
            ):
                continue
        row_range = _statement_pk_range(row.get("pk_start"), row.get("pk_end"))
        if row_range is None:
            continue
        if fact_range[0] < row_range[0] - 0.001 or fact_range[1] > row_range[1] + 0.001:
            continue
        requested_work_type = str(work_type_id or "")
        row_work_type = str(row.get("work_type_id") or "")
        work_type_penalty = 0.0
        if requested_work_type and row_work_type and requested_work_type != row_work_type:
            work_type_penalty = 1_000_000_000.0
        row_len = max(0.0, row_range[1] - row_range[0])
        score = work_type_penalty + row_len
        if best_score is None or score < best_score:
            best_score = score
            best_row = row
    return best_row


def _statement_merge_pk_segments(segments: list[dict], max_gap_m: float = 5.0) -> list[dict]:
    clean: list[tuple[float, float]] = []
    for segment in segments or []:
        if not isinstance(segment, dict):
            continue
        if segment.get("pk_start") is None and segment.get("pk_end") is None:
            continue
        start = _as_float(segment.get("pk_start")) if segment.get("pk_start") is not None else _as_float(segment.get("pk_end"))
        end = _as_float(segment.get("pk_end")) if segment.get("pk_end") is not None else _as_float(segment.get("pk_start"))
        if start > end:
            start, end = end, start
        clean.append((start, end))
    if not clean:
        return []
    clean.sort(key=lambda item: (item[0], item[1]))
    merged: list[list[float]] = [[clean[0][0], clean[0][1]]]
    for start, end in clean[1:]:
        current = merged[-1]
        if start <= current[1] + max_gap_m:
            current[1] = max(current[1], end)
        else:
            merged.append([start, end])
    return [
        {
            "pk_start": round(start, 3),
            "pk_end": round(end, 3),
            "label": _format_pk_range_excel(start, end),
        }
        for start, end in merged
    ]


def _statement_search_pk_range(query_text: Optional[str]) -> tuple[Optional[float], Optional[float], str]:
    raw = str(query_text or "")
    pattern = re.compile(
        r"(?:п\s*\.?\s*к\s*\.?|pk)\s*\d{1,6}(?:\s*\+\s*\d{1,3}(?:[\.,]\d+)?)?|\d{1,6}\s*\+\s*\d{1,3}(?:[\.,]\d+)?",
        re.IGNORECASE,
    )
    values: list[float] = []
    for match in pattern.finditer(raw):
        try:
            value = _parse_statement_pk(match.group(0))
        except HTTPException:
            continue
        if value is not None:
            values.append(value)
    cleaned = pattern.sub(" ", raw)
    cleaned = re.sub(r"\s*[-–—]+\s*", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    if not values:
        return None, None, cleaned
    start, end = min(values), max(values)
    return start, end, cleaned


def _statement_general_search_terms(query_text: Optional[str]) -> list[str]:
    _, _, cleaned = _statement_search_pk_range(query_text)
    return _statement_search_terms(cleaned)


def _statement_range_overlaps(row_start, row_end, query_start: Optional[float], query_end: Optional[float]) -> bool:
    if query_start is None and query_end is None:
        return True
    if row_start is None and row_end is None:
        return False
    start = _as_float(row_start) if row_start is not None else _as_float(row_end)
    end = _as_float(row_end) if row_end is not None else _as_float(row_start)
    if start > end:
        start, end = end, start
    q_start = query_start if query_start is not None else query_end
    q_end = query_end if query_end is not None else query_start
    if q_start is None or q_end is None:
        return True
    if q_start > q_end:
        q_start, q_end = q_end, q_start
    return end >= q_start and start <= q_end


def _statement_general_row_overlaps_pk(row: dict, query_start: Optional[float], query_end: Optional[float]) -> bool:
    if query_start is None and query_end is None:
        return True
    if _statement_range_overlaps(row.get("pk_start"), row.get("pk_end"), query_start, query_end):
        return True
    for ref in row.get("project_refs") or []:
        if _statement_range_overlaps(ref.get("pk_start"), ref.get("pk_end"), query_start, query_end):
            return True
    for segment in row.get("cumulative_pk_segments") or []:
        if _statement_range_overlaps(segment.get("pk_start"), segment.get("pk_end"), query_start, query_end):
            return True
    for day in row.get("day_values") or []:
        for segment in day.get("pk_segments") or []:
            if _statement_range_overlaps(segment.get("pk_start"), segment.get("pk_end"), query_start, query_end):
                return True
    return False


def _statement_compaction_rule_values(rule: dict, key: str) -> list[str]:
    raw = rule.get(key) if isinstance(rule, dict) else None
    if not isinstance(raw, list):
        return []
    result: list[str] = []
    for value in raw:
        text = str(value or "").strip()
        if text and text not in result:
            result.append(text)
    return result


def _statement_compaction_rule_matches(values: list[str], current: Optional[str], *, upper: bool = False) -> bool:
    if not values:
        return True
    current_text = str(current or "").strip()
    if upper:
        current_text = current_text.upper()
        return current_text in {str(value or "").strip().upper() for value in values}
    current_norm = _general_normalize_text(current_text)
    return current_norm in {_general_normalize_text(value) for value in values}


def _statement_compaction_rule_specificity(rule: dict) -> int:
    score = 0
    if _statement_compaction_rule_values(rule, "object_codes"):
        score += 8
    if _statement_compaction_rule_values(rule, "object_type_codes"):
        score += 4
    if _statement_compaction_rule_values(rule, "work_codes"):
        score += 2
    if _statement_compaction_rule_values(rule, "tags"):
        score += 1
    return score


def _statement_compaction_match(rules: list[dict], row: dict) -> Optional[dict]:
    best: Optional[tuple[int, int, dict]] = None
    for idx, rule in enumerate(rules or []):
        if not _statement_compaction_rule_matches(_statement_compaction_rule_values(rule, "object_codes"), row.get("object_code"), upper=True):
            continue
        row_object_type_code = row.get("source_object_type_code") or row.get("object_type_code")
        if not _statement_compaction_rule_matches(_statement_compaction_rule_values(rule, "object_type_codes"), row_object_type_code, upper=True):
            continue
        if not _statement_compaction_rule_matches(_statement_compaction_rule_values(rule, "work_codes"), row.get("work_type_code"), upper=True):
            continue
        if not _statement_compaction_rule_matches(_statement_compaction_rule_values(rule, "tags"), row.get("work_type_analytics_tag") or row.get("analytics_tag")):
            continue
        candidate = (_statement_compaction_rule_specificity(rule), idx, rule)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    return best[2] if best else None


def _statement_apply_compaction(row: dict, rules: list[dict]) -> None:
    rule = _statement_compaction_match(rules, row)
    material_factor = 1.0
    if rule:
        try:
            material_factor = float(rule.get("coefficient") or 1.0)
        except (TypeError, ValueError):
            material_factor = 1.0
    if material_factor <= 0:
        material_factor = 1.0
    report_factor = 1.0 / material_factor if material_factor else 1.0
    row["compaction_factor"] = round(report_factor, 9)
    row["compaction_coefficient"] = round(material_factor, 6)
    row["compaction_rule_id"] = rule.get("id") if rule else None
    row["compaction_label"] = f"Купл {material_factor:g}" if abs(report_factor - 1.0) > 0.000001 else None
    for field in ("project_volume", "month_plan", "month_fact", "cumulative_plan", "cumulative_fact"):
        value = float(row.get(field) or 0)
        row[f"material_{field}"] = value
        row[field] = value * report_factor
    seen_details: set[int] = set()
    for detail_list_name in ("month_details", "cumulative_details"):
        for detail in row.get(detail_list_name) or []:
            marker = id(detail)
            if marker in seen_details:
                continue
            seen_details.add(marker)
            value = float(detail.get("volume") or 0)
            detail["material_volume"] = value
            detail["volume"] = value * report_factor
    day_values = row.get("day_values")
    if isinstance(day_values, dict):
        iterator = day_values.values()
    else:
        iterator = day_values or []
    for day in iterator:
        plan_value = float(day.get("plan_volume") or 0)
        fact_value = float(day.get("fact_volume") or 0)
        day["material_plan_volume"] = plan_value
        day["material_fact_volume"] = fact_value
        day["plan_volume"] = plan_value * report_factor
        day["fact_volume"] = fact_value * report_factor
        for detail in day.get("details") or []:
            marker = id(detail)
            if marker in seen_details:
                continue
            seen_details.add(marker)
            value = float(detail.get("volume") or 0)
            detail["material_volume"] = value
            detail["volume"] = value * report_factor


