def _statement_add_dim_rule_labels(target: dict[str, str], rules: object, *, overwrite: bool) -> None:
    if not isinstance(rules, list):
        return
    for item in rules:
        if not isinstance(item, (list, tuple)) or len(item) < 2:
            continue
        code = str(item[0] or "").strip().upper()
        label = str(item[1] or "").strip()
        if not code or not label:
            continue
        if overwrite or code not in target:
            target[code] = label


@lru_cache(maxsize=1)
def _statement_dim_work_type_display_names() -> dict[str, dict[str, str]]:
    generic = dict(STATEMENT_WORK_TYPE_DISPLAY_NAMES)
    by_object_type: dict[str, dict[str, str]] = {}
    dim = _daily_template_dim_module()
    if dim is None:
        return {"generic": generic, "by_object_type": by_object_type}
    for rule_set_name in STATEMENT_DIM_WORK_RULE_SETS:
        _statement_add_dim_rule_labels(generic, getattr(dim, rule_set_name, None), overwrite=False)
    for object_type_code, rule_set_names in STATEMENT_DIM_WORK_RULES_BY_OBJECT_TYPE.items():
        labels: dict[str, str] = {}
        for rule_set_name in rule_set_names:
            _statement_add_dim_rule_labels(labels, getattr(dim, rule_set_name, None), overwrite=False)
        if labels:
            by_object_type[object_type_code] = labels
    return {"generic": generic, "by_object_type": by_object_type}


def _statement_work_type_display_name(
    work_type_code: Optional[str],
    work_type_name: Optional[str],
    object_type_code: Optional[str] = None,
    object_code: Optional[str] = None,
) -> Optional[str]:
    code = str(work_type_code or "").strip().upper()
    if not code:
        return work_type_name
    maps = _statement_dim_work_type_display_names()
    object_type = str(object_type_code or "").strip().upper()
    typed_labels = maps.get("by_object_type", {}).get(object_type) or {}
    if code in typed_labels:
        return typed_labels[code]
    if object_type == "TECH_ROAD" and str(object_code or "").strip().upper().startswith("PFT_"):
        access_labels = maps.get("by_object_type", {}).get("TECH_ROAD_REINFORCEMENT_ACCESS") or {}
        if code in access_labels:
            return access_labels[code]
    return maps.get("generic", {}).get(code, work_type_name)


def _statement_display_object_type(
    object_type_code: Optional[str],
    object_type_name: Optional[str],
    object_code: Optional[str],
    object_name: Optional[str],
) -> tuple[Optional[str], Optional[str]]:
    type_code = (object_type_code or "").strip()
    if type_code.upper() != "TECH_ROAD":
        return object_type_code, object_type_name
    code = (object_code or "").strip().upper()
    text = f"{object_code or ''} {object_name or ''}".lower()
    is_reinforcement_access = (
        code.startswith("PFT_")
        or "погружения свай" in text
        or ("участ" in text and "усилен" in text)
    )
    if is_reinforcement_access:
        return "TECH_ROAD_REINFORCEMENT_ACCESS", "Технологические проезды к участкам усиления"
    return "TECH_ROAD_GENERAL", "Технологические проезды"



WORK_TYPE_RATE_BOUNDARY_PK = 3039 * 100.0
WORK_TYPE_RATE_REGIONS = {
    "novgorod": "Новгородская область до ПК3039",
    "tver": "Тверская область после ПК3039",
}


def _ensure_work_type_unit_rates_table(cur) -> None:
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS work_type_unit_rates (
            id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
            work_type_id uuid NOT NULL REFERENCES work_types(id) ON DELETE CASCADE,
            region_code text NOT NULL,
            region_label text NOT NULL,
            rate numeric,
            currency text NOT NULL DEFAULT 'RUB',
            unit text,
            pile_length_m numeric,
            updated_at timestamptz NOT NULL DEFAULT now(),
            updated_by text,
            CONSTRAINT work_type_unit_rates_region_check CHECK (region_code IN ('novgorod', 'tver'))
        )
        """
    )
    cur.execute("ALTER TABLE work_type_unit_rates ADD COLUMN IF NOT EXISTS pile_length_m numeric")
    cur.execute("ALTER TABLE work_type_unit_rates DROP CONSTRAINT IF EXISTS work_type_unit_rates_unique")
    cur.execute(
        """
        CREATE UNIQUE INDEX IF NOT EXISTS work_type_unit_rates_unique_base_idx
        ON work_type_unit_rates(work_type_id, region_code)
        WHERE pile_length_m IS NULL
        """
    )
    cur.execute(
        """
        CREATE UNIQUE INDEX IF NOT EXISTS work_type_unit_rates_unique_length_idx
        ON work_type_unit_rates(work_type_id, region_code, pile_length_m)
        WHERE pile_length_m IS NOT NULL
        """
    )


