def _statement_rate_length_key(value) -> Optional[str]:
    if value in (None, ""):
        return None
    try:
        number = float(str(value).strip().replace(",", "."))
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number) or number <= 0:
        return None
    return f"{number:g}"


def _statement_work_type_rate_map() -> dict[str, dict[str, object]]:
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                _ensure_work_type_unit_rates_table(cur)
                cur.execute(
                    """
                    SELECT work_type_id::text, region_code, pile_length_m, rate
                    FROM work_type_unit_rates
                    WHERE region_code IN ('novgorod', 'tver')
                    """
                )
                rows = cur.fetchall()
    finally:
        conn.close()
    result: dict[str, dict[str, object]] = {}
    for work_type_id, region_code, pile_length_m, rate in rows:
        entry = result.setdefault(str(work_type_id), {"base": {}, "lengths": {}})
        length_key = _statement_rate_length_key(pile_length_m)
        target = entry["base"] if length_key is None else entry["lengths"].setdefault(length_key, {})  # type: ignore[index, union-attr]
        target[str(region_code)] = float(rate) if rate is not None else None  # type: ignore[index]
    return result


def _statement_object_rate_map() -> dict[str, dict[str, object]]:
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                _ensure_statement_object_unit_rates_table(cur)
                cur.execute(
                    """
                    SELECT object_id::text, work_type_id::text, region_code, pile_length_m, rate
                    FROM statement_object_unit_rates
                    WHERE region_code IN ('novgorod', 'tver')
                    """
                )
                rows = cur.fetchall()
    finally:
        conn.close()
    result: dict[str, dict[str, object]] = {}
    for object_id, work_type_id, region_code, pile_length_m, rate in rows:
        entry = result.setdefault(f"{object_id}:{work_type_id}", {"base": {}, "lengths": {}})
        length_key = _statement_rate_length_key(pile_length_m)
        target = entry["base"] if length_key is None else entry["lengths"].setdefault(length_key, {})  # type: ignore[index, union-attr]
        if rate is not None:
            target[str(region_code)] = float(rate)  # type: ignore[index]
    return result


def _statement_rates_for_row(row: dict, rate_map: dict[str, dict[str, object]]) -> dict[str, Optional[float]]:
    entry = rate_map.get(str(row.get("work_type_id") or ""), {})
    base = dict(entry.get("base") or {})
    length_key = _statement_rate_length_key(row.get("pile_length_m"))
    if not length_key:
        return {"novgorod": base.get("novgorod"), "tver": base.get("tver")}
    length_rates = dict((entry.get("lengths") or {}).get(length_key) or {})  # type: ignore[union-attr]
    return {
        "novgorod": length_rates.get("novgorod", base.get("novgorod")),
        "tver": length_rates.get("tver", base.get("tver")),
    }


def _statement_object_rates_for_row(
    row: dict,
    object_rate_map: dict[str, dict[str, object]],
    reference_rates: dict[str, Optional[float]],
) -> tuple[dict[str, Optional[float]], dict[str, str]]:
    object_id = str(row.get("object_id") or "")
    work_type_id = str(row.get("work_type_id") or "")
    entry = object_rate_map.get(f"{object_id}:{work_type_id}", {}) if object_id and work_type_id else {}
    base = dict(entry.get("base") or {})
    length_key = _statement_rate_length_key(row.get("pile_length_m"))
    length_rates = dict((entry.get("lengths") or {}).get(length_key) or {}) if length_key else {}  # type: ignore[union-attr]
    rates: dict[str, Optional[float]] = {}
    sources: dict[str, str] = {}
    for region in ("novgorod", "tver"):
        if region in length_rates:
            rates[region] = length_rates.get(region)
            sources[region] = "object"
        elif region in base:
            rates[region] = base.get(region)
            sources[region] = "object"
        else:
            rates[region] = reference_rates.get(region)
            sources[region] = "reference" if reference_rates.get(region) is not None else "missing"
    return rates, sources


def _statement_rate_region_shares(pk_start, pk_end) -> dict[str, float]:
    start = _as_float(pk_start) if pk_start is not None else None
    end = _as_float(pk_end) if pk_end is not None else None
    if start is None and end is None:
        return {}
    if start is None:
        start = end
    if end is None:
        end = start
    if start is None or end is None:
        return {}
    if start > end:
        start, end = end, start
    if abs(end - start) < 0.001:
        return {"novgorod" if start < WORK_TYPE_RATE_BOUNDARY_PK else "tver": 1.0}
    length = end - start
    nov_len = max(0.0, min(end, WORK_TYPE_RATE_BOUNDARY_PK) - start)
    tver_len = max(0.0, end - max(start, WORK_TYPE_RATE_BOUNDARY_PK))
    shares: dict[str, float] = {}
    if nov_len > 0:
        shares["novgorod"] = nov_len / length
    if tver_len > 0:
        shares["tver"] = tver_len / length
    if not shares:
        midpoint = (start + end) / 2.0
        shares["novgorod" if midpoint < WORK_TYPE_RATE_BOUNDARY_PK else "tver"] = 1.0
    return shares


def _statement_work_type_amount(
    row: dict,
    rates: dict[str, Optional[float]],
    volume_field: str,
    rate_sources: Optional[dict[str, str]] = None,
) -> tuple[Optional[float], bool, list[dict]]:
    volume = float(row.get(volume_field) or 0)
    if abs(volume) < 0.000001:
        return 0.0, False, []
    shares = _statement_rate_region_shares(row.get("pk_start"), row.get("pk_end"))
    if not shares:
        available = [region for region, value in (("novgorod", rates.get("novgorod")), ("tver", rates.get("tver"))) if value is not None]
        if len(available) == 1:
            shares = {available[0]: 1.0}
        elif available and all(
            math.isclose(
                float(rates[region]),
                float(rates[available[0]]),
                rel_tol=1e-12,
                abs_tol=1e-9,
            )
            for region in available[1:]
        ):
            shares = {available[0]: 1.0}
        else:
            return None, True, []
    amount = 0.0
    region_rows = []
    missing = False
    for region, share in shares.items():
        rate = rates.get(region)
        region_volume = volume * share
        region_amount = region_volume * float(rate) if rate is not None else None
        if rate is None:
            missing = True
        else:
            amount += region_amount or 0.0
        region_rows.append({
            "region_code": region,
            "region_label": WORK_TYPE_RATE_REGIONS.get(region, region),
            "share": round(share, 6),
            "volume": round(region_volume, 3),
            "rate": rate,
            "rate_source": (rate_sources or {}).get(region),
            "amount": round(region_amount, 2) if region_amount is not None else None,
        })
    return (None if missing else amount), missing, region_rows


def _statement_detail_amount(
    row: dict,
    rates: dict[str, Optional[float]],
    rate_sources: dict[str, str],
    detail: dict,
) -> tuple[Optional[float], bool]:
    amount_row = dict(row)
    amount_row["__amount_volume"] = float(detail.get("volume") or 0)
    amount_row["pk_start"] = detail.get("pk_start", row.get("pk_start"))
    amount_row["pk_end"] = detail.get("pk_end", row.get("pk_end"))
    amount, missing, _regions = _statement_work_type_amount(amount_row, rates, "__amount_volume", rate_sources)
    return amount, missing


def _statement_period_amount_from_details(
    row: dict,
    rates: dict[str, Optional[float]],
    rate_sources: dict[str, str],
    start_date: date_cls,
    end_date: date_cls,
) -> tuple[Optional[float], bool]:
    amount = 0.0
    missing = False
    for detail in row.get("cumulative_details") or []:
        raw_date = detail.get("date")
        try:
            detail_date = date_cls.fromisoformat(str(raw_date)[:10])
        except (TypeError, ValueError):
            continue
        if detail_date < start_date or detail_date > end_date:
            continue
        detail_amount, detail_missing = _statement_detail_amount(row, rates, rate_sources, detail)
        if detail_missing:
            missing = True
            continue
        amount += float(detail_amount or 0)
    return (None if missing else round(amount, 2)), missing


def _statement_current_decade_bounds(month_start: date_cls, month_end: date_cls) -> tuple[date_cls, date_cls]:
    today = date_cls.today()
    if month_start <= today <= month_end:
        anchor = today
    else:
        anchor = month_end
    if anchor.day <= 10:
        start_day = 1
    elif anchor.day <= 20:
        start_day = 11
    else:
        start_day = 21
    return date_cls(anchor.year, anchor.month, start_day), anchor


def _statement_apply_work_type_rates(
    row: dict,
    rate_map: dict[str, dict[str, object]],
    object_rate_map: dict[str, dict[str, object]],
    *,
    month_start: date_cls,
    month_end: date_cls,
) -> None:
    reference_rates = _statement_rates_for_row(row, rate_map)
    rates, rate_sources = _statement_object_rates_for_row(row, object_rate_map, reference_rates)
    row["unit_rate_novgorod"] = rates.get("novgorod")
    row["unit_rate_tver"] = rates.get("tver")
    row["unit_rate_source_novgorod"] = rate_sources.get("novgorod")
    row["unit_rate_source_tver"] = rate_sources.get("tver")
    month_plan_amount, month_plan_missing, month_plan_regions = _statement_work_type_amount(row, rates, "month_plan", rate_sources)
    year_plan_amount, year_plan_missing, year_plan_regions = _statement_work_type_amount(row, rates, "current_year_plan", rate_sources)
    decade_plan_amount, decade_plan_missing, decade_plan_regions = _statement_work_type_amount(row, rates, "current_decade_plan", rate_sources)
    month_amount, month_missing, month_regions = _statement_work_type_amount(row, rates, "month_fact", rate_sources)
    cumulative_amount, cumulative_missing, cumulative_regions = _statement_work_type_amount(row, rates, "cumulative_fact", rate_sources)
    today = date_cls.today()
    year_end = today if month_start <= today <= month_end else month_end
    year_start = date_cls(year_end.year, 1, 1)
    decade_start, decade_end = _statement_current_decade_bounds(month_start, month_end)
    year_amount, year_missing = _statement_period_amount_from_details(row, rates, rate_sources, year_start, year_end)
    decade_amount, decade_missing = _statement_period_amount_from_details(row, rates, rate_sources, decade_start, decade_end)
    row["month_plan_amount"] = month_plan_amount
    row["month_plan_amount_missing_rate"] = month_plan_missing
    row["month_plan_amount_regions"] = month_plan_regions
    row["current_year_plan_amount"] = year_plan_amount
    row["current_year_plan_amount_missing_rate"] = year_plan_missing
    row["current_year_plan_amount_regions"] = year_plan_regions
    row["current_decade_plan_amount"] = decade_plan_amount
    row["current_decade_plan_amount_missing_rate"] = decade_plan_missing
    row["current_decade_plan_amount_regions"] = decade_plan_regions
    row["month_amount"] = month_amount
    row["month_amount_missing_rate"] = month_missing
    row["month_amount_regions"] = month_regions
    row["cumulative_amount"] = cumulative_amount
    row["cumulative_amount_missing_rate"] = cumulative_missing
    row["cumulative_amount_regions"] = cumulative_regions
    row["current_year_amount"] = year_amount
    row["current_year_amount_missing_rate"] = year_missing
    row["current_decade_amount"] = decade_amount
    row["current_decade_amount_missing_rate"] = decade_missing


def _statement_material_label_from_code(material_code: object) -> str:
    code = str(material_code or "").strip().upper()
    labels = {
        "SAND": "Песок",
        "SHPGS": "ЩПГС",
        "SHPS": "ЩПС",
        "PGS": "ПГС",
        "CRUSHED_STONE": "Щебень",
        "SCHEBEN": "Щебень",
        "SOIL": "Грунт",
        "PEAT": "Торф",
    }
    return labels.get(code, code or "Материал не указан")


def _statement_dashboard_source_bucket(row: dict) -> str:
    bucket = str(row.get("contractor_bucket") or "").strip().lower()
    if bucket == "almaz":
        return "almaz"
    if bucket in {"hire", "hired"}:
        return "hired"
    return "non_hired"


def _statement_quarry_cumulative_rows(cumulative_end: date_cls, section_codes: Optional[list[str]]) -> list[dict]:
    filters = [
        "mm.report_date >= %s::date",
        "mm.report_date <= %s::date",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "src_ot.code = 'BORROW_PIT'",
        "mm.movement_type IN ('pit_to_stockpile', 'pit_to_constructive')",
        _statement_fact_report_exists("mm"),
    ]
    params: list = [PROJECT_START_DATE, cumulative_end]
    if section_codes:
        filters.append("cs.code = ANY(%s)")
        params.append(section_codes)
    return query(
        f"""
        SELECT cs.code AS section_code,
               m.code AS material,
               src.id::text AS quarry_id,
               src.id::text AS source_object_id,
               src.object_code AS source_object_code,
               src.name AS quarry_name,
               src.name AS source_object_name,
               mm.movement_type,
               mm.labor_source_type,
               COALESCE(NULLIF(mm.contractor_name, ''), c.short_name, c.name, '') AS contractor_name,
               SUM(COALESCE(mm.volume, 0))::numeric AS volume
        FROM material_movements mm
        JOIN daily_reports dr ON dr.id = mm.daily_report_id
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN contractors c ON c.id = mm.contractor_id
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
        LEFT JOIN construction_sections cs ON cs.id = mm.section_id
        WHERE {' AND '.join(filters)}
        GROUP BY cs.code, m.code, src.id, src.object_code, src.name,
                 mm.movement_type, mm.labor_source_type,
                 COALESCE(NULLIF(mm.contractor_name, ''), c.short_name, c.name, '')
        """,
        params,
    )


def _statement_add_quarry_cumulative_totals(
    sections: dict[str, dict],
    *,
    cumulative_end: date_cls,
    section_codes: Optional[list[str]],
) -> None:
    allowed_sections = {_merge_section(code) or code for code in (section_codes or [])}
    for row in _statement_quarry_cumulative_rows(cumulative_end, section_codes):
        if row.get("movement_type") not in {"pit_to_stockpile", "pit_to_constructive"}:
            continue
        if row.get("source_kind") != "quarry" and not row.get("quarry_name"):
            continue
        try:
            volume = float(row.get("volume") or 0)
        except (TypeError, ValueError):
            volume = 0.0
        if abs(volume) < 0.0005:
            continue
        section_code = _merge_section(row.get("section_code")) or row.get("section_code") or "__none__"
        if allowed_sections and section_code not in allowed_sections:
            continue
        material_code = str(row.get("material") or "").strip().upper() or "UNKNOWN"
        material_name = _statement_material_label_from_code(material_code)
        source_bucket = _general_source_bucket(row.get("labor_source_type"), row.get("contractor_name"))
        quarry_name = _quarry_display_name(row.get("quarry_name") or row.get("source_object_name") or "Карьер не указан")
        quarry_key = _quarry_label_key(quarry_name) or str(row.get("quarry_id") or row.get("source_object_id") or quarry_name)
        unit = "м3"

        section = sections.setdefault(section_code, {
            "section_code": None if section_code == "__none__" else section_code,
            "section_name": "Без участка" if section_code == "__none__" else section_code,
            "total_volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": unit,
            "quarries": {},
            "materials": {},
        })
        section["cumulative_volume"] = float(section.get("cumulative_volume") or 0) + volume
        material = section["materials"].setdefault(material_code, {
            "material_code": material_code,
            "material_name": material_name,
            "total_volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": unit,
            "sources": {},
        })
        material["cumulative_volume"] = float(material.get("cumulative_volume") or 0) + volume
        source = material["sources"].setdefault(source_bucket, {
            "source_bucket": source_bucket,
            "source_label": GENERAL_REPORT_SOURCE_BUCKET_LABELS.get(source_bucket, source_bucket),
            "total_volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": unit,
            "quarries": {},
        })
        source["cumulative_volume"] = float(source.get("cumulative_volume") or 0) + volume
        quarry = source["quarries"].setdefault(quarry_key, {
            "quarry_id": str(row.get("quarry_id") or row.get("source_object_id") or "") or None,
            "quarry_code": row.get("source_object_code"),
            "quarry_name": quarry_name,
            "volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": unit,
            "day_values": {},
        })
        top_quarry = section["quarries"].setdefault(quarry_key, {
            "quarry_id": str(row.get("quarry_id") or row.get("source_object_id") or "") or None,
            "quarry_code": row.get("source_object_code"),
            "quarry_name": quarry_name,
            "volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": unit,
            "day_values": {},
        })
        quarry["cumulative_volume"] = float(quarry.get("cumulative_volume") or 0) + volume
        top_quarry["cumulative_volume"] = float(top_quarry.get("cumulative_volume") or 0) + volume


def _statement_sand_by_section(month_start: date_cls, month_end: date_cls, section_codes: Optional[list[str]]) -> list[dict]:
    filters = [
        "mm.report_date >= %s::date",
        "mm.report_date <= %s::date",
        "COALESCE(mm.is_demo, false) IS FALSE",
        "src_ot.code = 'BORROW_PIT'",
        "mm.movement_type IN ('pit_to_stockpile', 'pit_to_constructive')",
        _statement_fact_report_exists("mm"),
    ]
    params: list = [month_start, month_end]
    if section_codes:
        filters.append("cs.code = ANY(%s)")
        params.append(section_codes)
    rows = query(
        f"""
        SELECT cs.code AS section_code,
               cs.name AS section_name,
               mm.report_date::date AS report_date,
               m.code AS material_code,
               COALESCE(NULLIF(m.name, ''), m.code, 'Материал') AS material_name,
               src.id::text AS quarry_id,
               src.object_code AS quarry_code,
               src.name AS quarry_name,
               mm.labor_source_type,
               COALESCE(NULLIF(mm.contractor_name, ''), c.short_name, c.name, '') AS contractor_name,
               COALESCE(NULLIF(mm.unit, ''), m.default_unit, 'м3') AS unit,
               SUM(COALESCE(mm.volume, 0))::numeric AS volume
        FROM material_movements mm
        JOIN materials m ON m.id = mm.material_id
        LEFT JOIN contractors c ON c.id = mm.contractor_id
        LEFT JOIN objects src ON src.id = mm.from_object_id
        LEFT JOIN object_types src_ot ON src_ot.id = src.object_type_id
        LEFT JOIN construction_sections cs ON cs.id = mm.section_id
        WHERE {' AND '.join(filters)}
        GROUP BY cs.code, cs.name, mm.report_date, m.code, COALESCE(NULLIF(m.name, ''), m.code, 'Материал'),
                 src.id, src.object_code, src.name, mm.labor_source_type,
                 COALESCE(NULLIF(mm.contractor_name, ''), c.short_name, c.name, ''),
                 COALESCE(NULLIF(mm.unit, ''), m.default_unit, 'м3')
        ORDER BY cs.code NULLS LAST, mm.report_date, material_name, src.name NULLS LAST
        LIMIT 5000
        """,
        params,
    )
    sections: dict[str, dict] = {}
    for item in rows:
        section_code = _merge_section(item.get("section_code")) or item.get("section_code") or "__none__"
        section = sections.setdefault(section_code, {
            "section_code": None if section_code == "__none__" else section_code,
            "section_name": item.get("section_name") or ("Без участка" if section_code == "__none__" else section_code),
            "total_volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": item.get("unit") or "м3",
            "quarries": {},
            "materials": {},
        })
        material_key = item.get("material_code") or item.get("material_name") or "__unknown__"
        material = section["materials"].setdefault(material_key, {
            "material_code": item.get("material_code"),
            "material_name": item.get("material_name") or item.get("material_code") or "Материал не указан",
            "total_volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": item.get("unit") or "м3",
            "sources": {},
        })
        source_bucket = _general_source_bucket(item.get("labor_source_type"), item.get("contractor_name"))
        source = material["sources"].setdefault(source_bucket, {
            "source_bucket": source_bucket,
            "source_label": GENERAL_REPORT_SOURCE_BUCKET_LABELS.get(source_bucket, source_bucket),
            "total_volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": item.get("unit") or "м3",
            "quarries": {},
        })
        quarry_name = _quarry_display_name(item.get("quarry_name") or item.get("quarry_code") or "Карьер не указан")
        quarry_key = _quarry_label_key(quarry_name) or item.get("quarry_id") or item.get("quarry_code") or "__unknown__"
        quarry = source["quarries"].setdefault(quarry_key, {
            "quarry_id": item.get("quarry_id"),
            "quarry_code": item.get("quarry_code"),
            "quarry_name": quarry_name,
            "volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": item.get("unit") or "м3",
            "day_values": {},
        })
        top_quarry = section["quarries"].setdefault(quarry_key, {
            "quarry_id": item.get("quarry_id"),
            "quarry_code": item.get("quarry_code"),
            "quarry_name": quarry_name,
            "volume": 0.0,
            "cumulative_volume": 0.0,
            "unit": item.get("unit") or "м3",
            "day_values": {},
        })
        volume = float(item.get("volume") or 0)
        report_date = item.get("report_date")
        day_key = report_date.isoformat() if hasattr(report_date, "isoformat") else str(report_date or "")
        quarry["volume"] += volume
        top_quarry["volume"] += volume
        if day_key:
            quarry["day_values"][day_key] = quarry["day_values"].get(day_key, 0.0) + volume
            top_quarry["day_values"][day_key] = top_quarry["day_values"].get(day_key, 0.0) + volume
        source["total_volume"] += volume
        material["total_volume"] += volume
        section["total_volume"] += volume

    _statement_add_quarry_cumulative_totals(sections, cumulative_end=month_end, section_codes=section_codes)

    result = []
    for section in sections.values():
        top_quarries = [
            {
                **quarry,
                "volume": round(float(quarry.get("volume") or 0), 3),
                "cumulative_volume": round(float(quarry.get("cumulative_volume") or 0), 3),
                "day_values": {date: round(float(value or 0), 3) for date, value in sorted((quarry.get("day_values") or {}).items())},
            }
            for quarry in section.pop("quarries").values()
        ]
        top_quarries.sort(key=lambda row: (-float(row.get("volume") or 0), -float(row.get("cumulative_volume") or 0), str(row.get("quarry_name") or "")))
        materials = []
        for material in section.pop("materials").values():
            sources = []
            for source in material.pop("sources").values():
                quarries = [
                    {
                        **quarry,
                        "volume": round(float(quarry.get("volume") or 0), 3),
                        "cumulative_volume": round(float(quarry.get("cumulative_volume") or 0), 3),
                        "day_values": {date: round(float(value or 0), 3) for date, value in sorted((quarry.get("day_values") or {}).items())},
                    }
                    for quarry in source.pop("quarries").values()
                ]
                quarries.sort(key=lambda row: (-float(row.get("volume") or 0), -float(row.get("cumulative_volume") or 0), str(row.get("quarry_name") or "")))
                sources.append({
                    **source,
                    "total_volume": round(float(source.get("total_volume") or 0), 3),
                    "cumulative_volume": round(float(source.get("cumulative_volume") or 0), 3),
                    "quarries": quarries,
                })
            sources.sort(key=lambda row: (str(row.get("source_label") or ""), -float(row.get("total_volume") or 0), -float(row.get("cumulative_volume") or 0)))
            materials.append({
                **material,
                "total_volume": round(float(material.get("total_volume") or 0), 3),
                "cumulative_volume": round(float(material.get("cumulative_volume") or 0), 3),
                "sources": sources,
            })
        materials.sort(key=lambda row: (-float(row.get("total_volume") or 0), -float(row.get("cumulative_volume") or 0), str(row.get("material_name") or "")))
        result.append({
            **section,
            "total_volume": round(float(section.get("total_volume") or 0), 3),
            "cumulative_volume": round(float(section.get("cumulative_volume") or 0), 3),
            "quarries": top_quarries,
            "materials": materials,
        })
    result.sort(key=lambda row: str(row.get("section_code") or ""))
    return result

def _statement_general_row_seed(
    rows: dict[str, dict],
    *,
    days: list[dict],
    category: str,
    category_label: str,
    category_sort_order: int = 9999,
    section_code: Optional[str],
    section_name: Optional[str],
    section_sort_order: Optional[int] = None,
    object_id: Optional[str],
    object_code: Optional[str],
    object_name: Optional[str],
    object_type_code: Optional[str],
    object_type_name: Optional[str],
    work_type_id: Optional[str],
    work_type_code: Optional[str],
    work_type_name: Optional[str],
    unit: Optional[str],
    pk_start,
    pk_end,
    pk_raw_text: Optional[str] = None,
    pile_length_m: Optional[float] = None,
) -> dict:
    merged_section = _merge_section(section_code) or section_code
    source_object_type_code = object_type_code
    source_object_type_name = object_type_name
    object_type_code, object_type_name = _statement_display_object_type(object_type_code, object_type_name, object_code, object_name)
    normalized_unit = unit or "—"
    pk_start, pk_end, pk_raw_text, pile_length_m = _statement_general_row_dimensions(
        work_type_code,
        pk_start,
        pk_end,
        pk_raw_text,
        pile_length_m,
    )
    key = _statement_general_row_key(category, merged_section, object_id, work_type_id, normalized_unit, pk_start, pk_end, pile_length_m)
    resolved_section_sort_order = _statement_section_sort_order_value(section_sort_order, merged_section)
    existing = rows.get(key)
    if existing:
        if existing.get("section_sort_order") is None and resolved_section_sort_order is not None:
            existing["section_sort_order"] = resolved_section_sort_order
        return existing
    row = {
        "id": key,
        "category": category,
        "category_label": category_label,
        "category_sort_order": category_sort_order,
        "section_code": merged_section,
        "section_name": section_name,
        "section_sort_order": resolved_section_sort_order,
        "object_id": object_id,
        "object_code": object_code,
        "object_name": object_name,
        "object_type_code": object_type_code,
        "object_type_name": object_type_name,
        "source_object_type_code": source_object_type_code,
        "source_object_type_name": source_object_type_name,
        "work_type_id": work_type_id,
        "work_type_code": work_type_code,
        "work_type_name": _statement_work_type_display_name(work_type_code, work_type_name, object_type_code, object_code),
        "unit": normalized_unit,
        "pk_start": _as_float(pk_start) if pk_start is not None else None,
        "pk_end": _as_float(pk_end) if pk_end is not None else None,
        "pk_raw_text": pk_raw_text,
        "pk_label": _format_pk_range_excel(pk_start, pk_end, pk_raw_text),
        "pile_length_m": pile_length_m,
        "project_volume": 0.0,
        "month_plan": 0.0,
        "current_year_plan": 0.0,
        "current_decade_plan": 0.0,
        "month_fact": 0.0,
        "cumulative_plan": 0.0,
        "cumulative_fact": 0.0,
        "material_project_volume": 0.0,
        "material_month_plan": 0.0,
        "material_month_fact": 0.0,
        "material_cumulative_plan": 0.0,
        "material_cumulative_fact": 0.0,
        "cumulative_pk_ranges": [],
        "cumulative_pk_segments": [],
        "compaction_factor": 1.0,
        "compaction_coefficient": 1.0,
        "compaction_rule_id": None,
        "compaction_label": None,
        "day_values": _statement_general_empty_day_values(days),
        "month_details": [],
        "cumulative_details": [],
        "has_source": False,
        "month_plan_locked": False,
        "month_plan_source": None,
        "project_refs": [],
        "project_item_id": None,
        "project_segment_id": None,
        "project_segment_count": 0,
        "can_edit_project": False,
    }
    rows[key] = row
    return row


def _statement_general_scope_filters(
    section_codes: Optional[list[str]],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
) -> tuple[list[str], list]:
    filters: list[str] = []
    params: list = []
    object_type_values = _statement_filter_values(object_type)
    object_id_values = _statement_filter_values(object_id)
    terms = _statement_general_search_terms(q)
    if section_codes:
        filters.append("cs_eff.code = ANY(%s)")
        params.append(section_codes)
    if object_type_values:
        filters.append("ot.code = ANY(%s)")
        params.append(object_type_values)
    if object_id_values:
        filters.append("obj.id::text = ANY(%s)")
        params.append(object_id_values)
    if terms:
        for term in terms:
            filters.append("LOWER(CONCAT_WS(' ', obj.object_code, obj.name, ot.name, ot.code, tr.road_code, REGEXP_REPLACE(COALESCE(tr.road_code, ''), '\\s+', '', 'g'), wt.code, wt.name, wt.analytics_tag, dwi.work_name_raw)) LIKE %s")
            params.append(f"%{term}%")
    return filters, params


def _statement_general_plan_scope_filters(
    section_codes: Optional[list[str]],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    *,
    section_sql: str = "so.section_code",
    object_alias: str = "so",
) -> tuple[list[str], list]:
    filters: list[str] = []
    params: list = []
    object_type_values = _statement_filter_values(object_type)
    object_id_values = _statement_filter_values(object_id)
    terms = _statement_general_search_terms(q)
    if section_codes:
        filters.append(f"{section_sql} = ANY(%s)")
        params.append(section_codes)
    if object_type_values:
        filters.append(f"{object_alias}.object_type_code = ANY(%s)")
        params.append(object_type_values)
    if object_id_values:
        filters.append(f"{object_alias}.id::text = ANY(%s)")
        params.append(object_id_values)
    if terms:
        for term in terms:
            filters.append(
                f"LOWER(CONCAT_WS(' ', {object_alias}.object_code, {object_alias}.object_name, "
                f"{object_alias}.object_type_name, {object_alias}.object_type_code, {object_alias}.temp_road_code, "
                f"REGEXP_REPLACE(COALESCE({object_alias}.temp_road_code, ''), '\\s+', '', 'g'), "
                "wt.code, wt.name, wt.analytics_tag, pwi.comment)) LIKE %s"
            )
            params.append(f"%{term}%")
    return filters, params


def _statement_general_plan_source_sql() -> str:
    if not (
        _statement_table_exists("statement_signed_pile_plan_batches")
        and _statement_table_exists("statement_signed_pile_plan_items")
    ):
        return "planned_work_items pwi"
    work_codes_sql = ", ".join(f"'{code}'" for code in STATEMENT_SIGNED_PILE_PLAN_WORK_TYPE_CODES)
    return f"""
    (
      SELECT source_plan.object_id,
             source_plan.work_type_id,
             source_plan.assigned_section_id,
             source_plan.is_active,
             source_plan.period_start,
             source_plan.period_end,
             source_plan.source_pile_field_id,
             source_plan.pk_start,
             source_plan.pk_end,
             source_plan.pk_raw_text,
             source_plan.source_reference,
             source_plan.unit,
             source_plan.plan_type,
             source_plan.planned_volume,
             source_plan.comment
      FROM planned_work_items source_plan
      JOIN work_types source_work_type ON source_work_type.id = source_plan.work_type_id
      WHERE NOT (
        source_work_type.code IN ({work_codes_sql})
        AND source_plan.period_start IS NOT NULL
        AND source_plan.period_end IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM statement_signed_pile_plan_batches signed_batch
          WHERE signed_batch.is_active
            AND signed_batch.period_start <= source_plan.period_end
            AND signed_batch.period_end >= source_plan.period_start
        )
      )

      UNION ALL

      SELECT signed_item.object_id,
             signed_item.work_type_id,
             signed_item.assigned_section_id,
             true AS is_active,
             signed_batch.period_start,
             signed_batch.period_end,
             signed_item.source_pile_field_id,
             NULL::numeric AS pk_start,
             NULL::numeric AS pk_end,
             NULL::text AS pk_raw_text,
             COALESCE(
               NULLIF(signed_item.source_reference, ''),
               '{STATEMENT_SIGNED_PILE_PLAN_SOURCE_PREFIX}' || LEFT(signed_batch.source_sha256, 16)
             ) AS source_reference,
             signed_item.unit,
             'signed_month'::varchar(30) AS plan_type,
             signed_item.planned_volume,
             signed_item.source_context AS comment
      FROM statement_signed_pile_plan_items signed_item
      JOIN statement_signed_pile_plan_batches signed_batch ON signed_batch.id = signed_item.batch_id
      WHERE signed_batch.is_active
    ) pwi
    """


def _statement_signed_pile_plan_for_period(period_start: date_cls, period_end: date_cls) -> Optional[dict]:
    if not (
        _statement_table_exists("statement_signed_pile_plan_batches")
        and _statement_table_exists("statement_signed_pile_plan_items")
    ):
        return None
    row = query_one(
        """
        SELECT batch.id::text AS id,
               batch.period_start,
               batch.period_end,
               batch.source_filename,
               batch.source_sha256,
               batch.source_reference,
               batch.imported_at,
               COUNT(item.id)::int AS item_count,
               COALESCE(SUM(item.planned_volume), 0)::numeric AS planned_volume
        FROM statement_signed_pile_plan_batches batch
        LEFT JOIN statement_signed_pile_plan_items item ON item.batch_id = batch.id
        WHERE batch.is_active
          AND batch.period_start <= %s::date
          AND batch.period_end >= %s::date
        GROUP BY batch.id
        ORDER BY batch.imported_at DESC, batch.id
        LIMIT 1
        """,
        (period_end, period_start),
    )
    if not row:
        return None
    return {
        **row,
        "period_start": row["period_start"].isoformat() if row.get("period_start") else None,
        "period_end": row["period_end"].isoformat() if row.get("period_end") else None,
        "imported_at": row["imported_at"].isoformat() if row.get("imported_at") else None,
        "planned_volume": float(row.get("planned_volume") or 0),
        "work_type_codes": list(STATEMENT_SIGNED_PILE_PLAN_WORK_TYPE_CODES),
    }


def _statement_general_add_plan_rows(
    rows_by_key: dict[str, dict],
    *,
    days: list[dict],
    period_start: date_cls,
    period_end: date_cls,
    section_codes: Optional[list[str]],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    actual_section_binding: bool = False,
) -> None:
    if not _statement_table_exists("planned_work_items"):
        return
    rules = _general_report_work_rules()
    rule_labels = {str(rule.get("code") or ""): str(rule.get("label") or rule.get("code") or "Строка") for rule in rules}
    rule_order = {str(rule.get("code") or ""): idx for idx, rule in enumerate(rules)}
    if actual_section_binding:
        section_code_sql = "COALESCE(assigned_cs.code, so.section_code)"
        section_name_sql = "COALESCE(assigned_cs.name, so.section_name)"
        section_sort_sql = "COALESCE(assigned_cs.sort_order, so.section_sort_order)"
        section_pk_start_sql = (
            "CASE WHEN assigned_cs.id IS NOT NULL "
            "THEN COALESCE(pwi.pk_start, pf.pk_start, ob.object_pk_start) ELSE so.pk_start END"
        )
        section_pk_end_sql = (
            "CASE WHEN assigned_cs.id IS NOT NULL "
            "THEN COALESCE(pwi.pk_end, pf.pk_end, ob.object_pk_end) ELSE so.pk_end END"
        )
        object_alias = "ob"
        object_scope_join = f"""
        JOIN object_bounds ob ON ob.id = pwi.object_id
        LEFT JOIN construction_sections assigned_cs
          ON assigned_cs.id = pwi.assigned_section_id
         AND assigned_cs.is_active IS NOT FALSE
        LEFT JOIN object_sections so
          ON so.id = pwi.object_id
         AND assigned_cs.id IS NULL
        """
    else:
        section_code_sql = "so.section_code"
        section_name_sql = "so.section_name"
        section_sort_sql = "so.section_sort_order"
        section_pk_start_sql = "so.pk_start"
        section_pk_end_sql = "so.pk_end"
        object_alias = "so"
        object_scope_join = "JOIN object_sections so ON so.id = pwi.object_id"
    scope_filters, scope_params = _statement_general_plan_scope_filters(
        section_codes,
        object_type,
        object_id,
        q,
        section_sql=section_code_sql,
        object_alias=object_alias,
    )
    today = date_cls.today()
    year_end = today if period_start <= today <= period_end else period_end
    year_start = date_cls(year_end.year, 1, 1)
    decade_start, decade_end = _statement_current_decade_bounds(period_start, period_end)
    filters = [
        "COALESCE(pwi.is_active, true) IS TRUE",
        "((pwi.period_start IS NULL AND pwi.period_end IS NULL) OR (pwi.period_start IS NOT NULL AND pwi.period_end IS NOT NULL AND pwi.period_start <= %s::date AND pwi.period_end >= %s::date))",
        "(pf.id IS NULL OR COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded'))",
        f"NOT (wt.code = ANY(ARRAY{list(STATEMENT_PILE_PROJECT_TOTAL_MIRROR_WORK_TYPE_CODES)!r}) AND pwi.source_reference = '{STATEMENT_GENERATED_PROJECT_TOTAL_SOURCE}')",
    ]
    params: list = [period_end, PROJECT_START_DATE, *scope_params]
    filters.extend(scope_filters)
    plan_source_sql = _statement_general_plan_source_sql()
    plan_rows = query(
        _statement_scope_cte()
        + f"""
	        SELECT {object_alias}.id::text AS object_id,
	               {object_alias}.object_code,
	               {object_alias}.object_name,
	               {object_alias}.object_type_code,
	               {object_alias}.object_type_name,
	               {section_code_sql} AS section_code,
	               {section_name_sql} AS section_name,
	               {section_sort_sql} AS section_sort_order,
	               wt.id::text AS work_type_id,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               pf.pile_type,
               pipe_spec.pile_length_m AS pipe_pile_length_m,
               COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), wt.name) AS analytics_tag,
               COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '') AS unit,
               {section_pk_start_sql} AS section_pk_start,
               {section_pk_end_sql} AS section_pk_end,
               {object_alias}.object_pk_start,
               {object_alias}.object_pk_end,
               COALESCE(pwi.pk_start, pf.pk_start) AS plan_pk_start,
               COALESCE(pwi.pk_end, pf.pk_end) AS plan_pk_end,
               COALESCE(pwi.pk_start, pf.pk_start, {section_pk_start_sql}) AS pk_start,
               COALESCE(pwi.pk_end, pf.pk_end, {section_pk_end_sql}) AS pk_end,
               COALESCE(pwi.pk_raw_text, pf.pk_raw_text) AS pk_raw_text,
               pwi.period_start,
               pwi.period_end,
               pwi.plan_type,
               pwi.source_reference,
               COALESCE(pwi.planned_volume, 0)::numeric AS planned_volume
        FROM {plan_source_sql}
        {object_scope_join}
        JOIN work_types wt ON wt.id = pwi.work_type_id
        LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
        LEFT JOIN LATERAL (
          SELECT pps.pile_length_m
          FROM pipe_pile_specs pps
          WHERE pps.object_id = {object_alias}.id
            AND pps.work_type_id = wt.id
            AND COALESCE(pps.is_active, true) IS TRUE
            AND pps.pile_length_m IS NOT NULL
          ORDER BY pps.created_at DESC, pps.id
          LIMIT 1
        ) pipe_spec ON true
        WHERE {' AND '.join(filters)}
        LIMIT 20000
        """,
        params,
    )
    normalized_plan_rows: list[dict] = []
    cumulative_only_keys: set[str] = set()
    for item in plan_rows:
        pile_length_m = _statement_pile_length_from_sources(item.get("pile_type"), item.get("pipe_pile_length_m"))
        category = _general_plan_work_category(
            rules,
            item.get("analytics_tag"),
            item.get("work_type_code"),
            item.get("object_type_code"),
            item.get("object_code"),
        )
        if not category:
            category = f"work:{item.get('work_type_code') or item.get('work_type_id') or 'unknown'}"
        start = item.get("period_start") or item.get("period_end")
        end = item.get("period_end") or item.get("period_start")
        clip = _statement_clip_volume_to_section(item, float(item.get("planned_volume") or 0), "plan_pk_start", "plan_pk_end")
        if clip is None:
            continue
        pk_start, pk_end, volume, keep_pk_raw_text = clip
        if _statement_general_is_object_level_work_type(item.get("work_type_code")) and abs(float(volume or 0)) <= 0.000001:
            continue
        is_total_only = start is None and end is None
        if not is_total_only:
            if start > end:
                start, end = end, start
            total_days = max(1, (end - start).days + 1)
        else:
            total_days = None
        row_pk_start, row_pk_end, _row_pk_raw_text, row_pile_length_m = _statement_general_row_dimensions(
            item.get("work_type_code"),
            pk_start,
            pk_end,
            item.get("pk_raw_text") if keep_pk_raw_text else None,
            pile_length_m,
        )
        row_key = _statement_general_row_key(
            category,
            item.get("section_code"),
            item.get("object_id"),
            item.get("work_type_id"),
            item.get("unit"),
            row_pk_start,
            row_pk_end,
            row_pile_length_m,
        )
        if is_total_only:
            cumulative_only_keys.add(row_key)
        normalized_plan_rows.append(
            {
                "category": category,
                "row_key": row_key,
                "item": item,
                "pk_start": pk_start,
                "pk_end": pk_end,
                "volume": volume,
                "keep_pk_raw_text": keep_pk_raw_text,
                "pile_length_m": pile_length_m,
                "is_total_only": is_total_only,
                "start": start,
                "end": end,
                "total_days": total_days,
            }
        )
    for prepared in normalized_plan_rows:
        item = prepared["item"]
        category = prepared["category"]
        row = _statement_general_row_seed(
            rows_by_key,
            days=days,
            category=category,
            category_label=rule_labels.get(category, item.get("work_type_name") or item.get("work_type_code") or category),
            category_sort_order=rule_order.get(category, 9999),
            section_code=item.get("section_code"),
            section_name=item.get("section_name"),
            section_sort_order=item.get("section_sort_order"),
            object_id=item.get("object_id"),
            object_code=item.get("object_code"),
            object_name=item.get("object_name"),
            object_type_code=item.get("object_type_code"),
            object_type_name=item.get("object_type_name"),
            work_type_id=item.get("work_type_id"),
            work_type_code=item.get("work_type_code"),
            work_type_name=item.get("work_type_name"),
            unit=item.get("unit"),
            pk_start=prepared["pk_start"],
            pk_end=prepared["pk_end"],
            pk_raw_text=item.get("pk_raw_text") if prepared["keep_pk_raw_text"] else None,
            pile_length_m=prepared.get("pile_length_m"),
        )
        row["has_source"] = True
        if str(item.get("source_reference") or "").startswith(STATEMENT_SIGNED_PILE_PLAN_SOURCE_PREFIX):
            row["month_plan_locked"] = True
            row["month_plan_source"] = "Подписанная производственная программа"
        if prepared["is_total_only"]:
            row["cumulative_plan"] += prepared["volume"]
            continue
        start = prepared["start"]
        end = prepared["end"]
        total_days = prepared["total_days"]
        for day in days:
            day_date = date_cls.fromisoformat(day["date"])
            if start <= day_date <= end:
                row["day_values"][day["date"]]["plan_volume"] += prepared["volume"] / total_days
                row["month_plan"] += prepared["volume"] / total_days
        year_overlap = _statement_overlap_days(start, end, year_start, year_end)
        if year_overlap:
            row["current_year_plan"] += prepared["volume"] * year_overlap / total_days
        decade_overlap = _statement_overlap_days(start, end, decade_start, decade_end)
        if decade_overlap:
            row["current_decade_plan"] += prepared["volume"] * decade_overlap / total_days
        if prepared["row_key"] in cumulative_only_keys:
            continue
        cumulative_overlap = _statement_overlap_days(start, end, PROJECT_START_DATE, period_end)
        if cumulative_overlap:
            row["cumulative_plan"] += prepared["volume"] * cumulative_overlap / total_days


def _statement_general_add_project_rows(
    rows_by_key: dict[str, dict],
    *,
    days: list[dict],
    section_codes: Optional[list[str]],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    actual_section_binding: bool = False,
) -> None:
    rules = _general_report_work_rules()
    rule_labels = {str(rule.get("code") or ""): str(rule.get("label") or rule.get("code") or "Строка") for rule in rules}
    rule_order = {str(rule.get("code") or ""): idx for idx, rule in enumerate(rules)}
    section_code_sql = "so.section_code"
    section_name_sql = "so.section_name"
    section_sort_sql = "so.section_sort_order"
    section_pk_start_sql = "so.pk_start"
    section_pk_end_sql = "so.pk_end"
    object_alias = "so"
    object_scope_join = "JOIN object_sections so ON so.id = COALESCE(pwi.object_id, con.object_id)"
    scope_filters, scope_params = _statement_general_plan_scope_filters(
        section_codes,
        object_type,
        object_id,
        q,
        section_sql=section_code_sql,
        object_alias=object_alias,
    )
    filters = [
        "(pf.id IS NULL OR COALESCE(NULLIF(LOWER(pf.catalog_status), ''), 'active') NOT IN ('excluded', 'superseded'))",
        *scope_filters,
    ]
    project_rows = query(
        _statement_scope_cte()
        + f"""
        SELECT pwi.id::text AS project_item_id,
               ps.id::text AS project_segment_id,
               COUNT(ps.id) OVER (PARTITION BY pwi.id)::int AS project_segment_count,
               {object_alias}.id::text AS object_id,
	               {object_alias}.object_code,
	               {object_alias}.object_name,
	               {object_alias}.object_type_code,
	               {object_alias}.object_type_name,
	               {section_code_sql} AS section_code,
	               {section_name_sql} AS section_name,
	               {section_sort_sql} AS section_sort_order,
	               wt.id::text AS work_type_id,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               pf.pile_type,
               pipe_spec.pile_length_m AS pipe_pile_length_m,
               COALESCE(NULLIF(BTRIM(wt.analytics_tag), ''), wt.name) AS analytics_tag,
               COALESCE(NULLIF(pwi.unit, ''), wt.default_unit, '') AS unit,
               {section_pk_start_sql} AS section_pk_start,
               {section_pk_end_sql} AS section_pk_end,
               {object_alias}.object_pk_start,
               {object_alias}.object_pk_end,
               COALESCE(ps.pk_start, pf.pk_start) AS project_pk_start,
               COALESCE(ps.pk_end, pf.pk_end) AS project_pk_end,
               COALESCE(ps.pk_start, pf.pk_start, {section_pk_start_sql}) AS pk_start,
               COALESCE(ps.pk_end, pf.pk_end, {section_pk_end_sql}) AS pk_end,
               COALESCE(ps.pk_raw_text, pf.pk_raw_text) AS pk_raw_text,
               pwi.source_reference,
               CASE WHEN ps.id IS NOT NULL THEN COALESCE(ps.volume_segment, 0) ELSE COALESCE(pwi.project_volume, 0) END::numeric AS project_volume
        FROM project_work_items pwi
        LEFT JOIN constructives con ON con.id = pwi.constructive_id
        {object_scope_join}
        JOIN work_types wt ON wt.id = pwi.work_type_id
        LEFT JOIN pile_fields pf ON pf.id = pwi.source_pile_field_id
        LEFT JOIN LATERAL (
          SELECT pps.pile_length_m
          FROM pipe_pile_specs pps
          WHERE pps.object_id = {object_alias}.id
            AND pps.work_type_id = wt.id
            AND COALESCE(pps.is_active, true) IS TRUE
            AND pps.pile_length_m IS NOT NULL
          ORDER BY pps.created_at DESC, pps.id
          LIMIT 1
        ) pipe_spec ON true
        LEFT JOIN project_work_item_segments ps ON ps.project_work_item_id = pwi.id
        WHERE {' AND '.join(filters)}
        LIMIT 20000
        """,
        scope_params,
    )
    for item in project_rows:
        pile_length_m = _statement_pile_length_from_sources(item.get("pile_type"), item.get("pipe_pile_length_m"))
        category = _general_configured_work_category(rules, item.get("analytics_tag"), item.get("object_type_code"), item.get("object_code"))
        if not category:
            category = f"work:{item.get('work_type_code') or item.get('work_type_id') or 'unknown'}"
        clip = _statement_clip_volume_to_section(item, float(item.get("project_volume") or 0), "project_pk_start", "project_pk_end")
        if clip is None:
            continue
        pk_start, pk_end, project_volume, keep_pk_raw_text = clip
        if (
            _statement_general_is_object_level_work_type(item.get("work_type_code"))
            and str(item.get("source_reference") or "") == STATEMENT_GENERATED_DYNTEST_PROJECT_SOURCE
            and abs(float(project_volume or 0)) <= 0.000001
        ):
            continue
        row = _statement_general_row_seed(
            rows_by_key,
            days=days,
            category=category,
            category_label=rule_labels.get(category, item.get("work_type_name") or item.get("work_type_code") or category),
            category_sort_order=rule_order.get(category, 9999),
            section_code=item.get("section_code"),
            section_name=item.get("section_name"),
            section_sort_order=item.get("section_sort_order"),
            object_id=item.get("object_id"),
            object_code=item.get("object_code"),
            object_name=item.get("object_name"),
            object_type_code=item.get("object_type_code"),
            object_type_name=item.get("object_type_name"),
            work_type_id=item.get("work_type_id"),
            work_type_code=item.get("work_type_code"),
            work_type_name=item.get("work_type_name"),
            unit=item.get("unit"),
            pk_start=pk_start,
            pk_end=pk_end,
            pk_raw_text=item.get("pk_raw_text") if keep_pk_raw_text else None,
            pile_length_m=pile_length_m,
        )
        row["has_source"] = True
        row["project_volume"] += project_volume
        if item.get("project_item_id"):
            raw_project_volume = float(item.get("project_volume") or 0)
            editable_without_clipping = abs(float(project_volume or 0) - raw_project_volume) < 0.001
            row.setdefault("project_refs", []).append({
                "project_item_id": item.get("project_item_id"),
                "project_segment_id": item.get("project_segment_id"),
                "project_segment_count": int(item.get("project_segment_count") or 0),
                "pk_start": _as_float(item.get("project_pk_start")) if item.get("project_pk_start") is not None else None,
                "pk_end": _as_float(item.get("project_pk_end")) if item.get("project_pk_end") is not None else None,
                "pk_raw_text": item.get("pk_raw_text") if keep_pk_raw_text else None,
                "project_volume": round(float(project_volume or 0), 3),
                "can_edit": editable_without_clipping,
            })


def _statement_general_add_fact_rows(
    rows_by_key: dict[str, dict],
    *,
    days: list[dict],
    month_start: date_cls,
    month_end: date_cls,
    cumulative_end: date_cls,
    section_codes: Optional[list[str]],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    actual_section_binding: bool = False,
) -> None:
    rules = _general_report_work_rules()
    rule_labels = {str(rule.get("code") or ""): str(rule.get("label") or rule.get("code") or "Строка") for rule in rules}
    rule_order = {str(rule.get("code") or ""): idx for idx, rule in enumerate(rules)}
    scope_filters, scope_params = _statement_general_scope_filters(section_codes, object_type, object_id, q)
    filters = [
        "dwi.report_date >= %s::date",
        "dwi.report_date <= %s::date",
        "COALESCE(dwi.is_demo, false) IS FALSE",
        "COALESCE(dr.is_demo, false) IS FALSE",
        _statement_fact_report_exists("dwi"),
        *scope_filters,
    ]
    params: list = [PROJECT_START_DATE, cumulative_end, *scope_params]
    actual_road_guard = ""
    effective_section_priority = """
            cs_override.id,
            road_section_clip.section_id,
            effective_section.section_id,
            road_object_section.section_id,
            cs_report.id
    """
    if actual_section_binding:
        actual_road_guard = "AND cs_report.id IS NULL"
        effective_section_priority = """
            cs_report.id,
            cs_override.id,
            road_section_clip.section_id,
            effective_section.section_id,
            road_object_section.section_id
        """
    fact_rows = query(
        f"""
	        SELECT cs_eff.code AS section_code,
	               cs_eff.name AS section_name,
	               cs_eff.sort_order AS section_sort_order,
	               dr.report_date,
               dr.id::text AS report_id,
               LOWER(COALESCE(dwi.shift, dr.shift, 'day')) AS shift,
               obj.id::text AS object_id,
               obj.object_code,
               obj.name AS object_name,
               ot.code AS object_type_code,
               ot.name AS object_type_name,
               wt.id::text AS work_type_id,
               wt.code AS work_type_code,
               wt.name AS work_type_name,
               COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw) AS analytics_tag,
               dwi.labor_source_type,
               dwi.contractor_name,
               COALESCE(dwi.unit, wt.default_unit, '') AS unit,
               pf.pile_type,
               pipe_spec.pile_length_m AS pipe_pile_length_m,
               CASE
                 WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                  AND (fact_range.pk_start IS NOT NULL OR fact_range.pk_end IS NOT NULL)
                   THEN COALESCE(road_section_clip.pk_start, cs_clip.pk_start, fact_range.pk_start)
                 ELSE fact_range.pk_start
               END AS pk_start,
               CASE
                 WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                  AND (fact_range.pk_start IS NOT NULL OR fact_range.pk_end IS NOT NULL)
                   THEN COALESCE(road_section_clip.pk_end, cs_clip.pk_end, fact_range.pk_end)
                 ELSE fact_range.pk_end
               END AS pk_end,
               CASE
                 WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                  AND (fact_range.pk_start IS NOT NULL OR fact_range.pk_end IS NOT NULL)
                   THEN ''
	                 ELSE COALESCE(NULLIF(seg.pk_raw_text, ''), NULLIF(pf.pk_raw_text, ''), '')
               END AS pk_raw_text,
               SUM(
                 CASE
                   WHEN seg.id IS NULL THEN COALESCE(dwi.volume, 0)
                   WHEN seg.volume_segment IS NOT NULL THEN seg.volume_segment
                   WHEN seg_count.cnt > 0 THEN COALESCE(dwi.volume, 0) / seg_count.cnt
                   ELSE COALESCE(dwi.volume, 0)
                 END * COALESCE(road_section_clip.section_factor, 1)
               )::numeric AS fact_volume
        FROM daily_work_items dwi
        JOIN daily_reports dr ON dr.id = dwi.daily_report_id
        JOIN work_types wt ON wt.id = dwi.work_type_id
        LEFT JOIN objects obj ON obj.id = dwi.object_id
        LEFT JOIN object_types ot ON ot.id = obj.object_type_id
        LEFT JOIN temporary_roads tr ON tr.object_id = obj.id
        LEFT JOIN LATERAL (
          SELECT MIN(os.pk_start) AS pk_start, MAX(os.pk_end) AS pk_end
          FROM object_segments os
          WHERE os.object_id = obj.id
        ) ob ON true
        LEFT JOIN construction_sections cs_report ON cs_report.id = COALESCE(dwi.section_id, dr.section_id)
        LEFT JOIN LATERAL (
          SELECT COUNT(*)::numeric AS cnt
          FROM daily_work_item_segments s_count
          WHERE s_count.daily_work_item_id = dwi.id
            AND COALESCE(s_count.is_demo, false) IS FALSE
        ) seg_count ON true
        LEFT JOIN daily_work_item_segments seg
          ON seg.daily_work_item_id = dwi.id
         AND COALESCE(seg.is_demo, false) IS FALSE
        LEFT JOIN pile_fields pf ON pf.id = seg.pile_field_id
        LEFT JOIN LATERAL (
          SELECT pps.pile_length_m
          FROM pipe_pile_specs pps
          WHERE pps.object_id = obj.id
            AND pps.work_type_id = wt.id
            AND COALESCE(pps.is_active, true) IS TRUE
            AND pps.pile_length_m IS NOT NULL
          ORDER BY pps.created_at DESC, pps.id
          LIMIT 1
        ) pipe_spec ON true
        LEFT JOIN LATERAL (
	          SELECT COALESCE(seg.pk_start, pf.pk_start, ob.pk_start) AS raw_pk_start,
	                 COALESCE(seg.pk_end, pf.pk_end, ob.pk_end) AS raw_pk_end,
	                 LEAST(
	                   COALESCE(seg.pk_start, pf.pk_start, ob.pk_start),
	                   COALESCE(seg.pk_end, pf.pk_end, ob.pk_end)
	                 ) AS raw_start,
	                 GREATEST(
	                   COALESCE(seg.pk_start, pf.pk_start, ob.pk_start),
	                   COALESCE(seg.pk_end, pf.pk_end, ob.pk_end)
	                 ) AS raw_end,
                 LEAST(ob.pk_start, ob.pk_end) AS object_start,
                 GREATEST(ob.pk_start, ob.pk_end) AS object_end,
                 LEAST(tr.ad_start_pk, tr.ad_end_pk) AS ad_start,
                 GREATEST(tr.ad_start_pk, tr.ad_end_pk) AS ad_end
        ) fact_source ON true
        LEFT JOIN LATERAL (
          SELECT CASE
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND fact_source.raw_start IS NOT NULL
                    AND fact_source.raw_end IS NOT NULL
                    AND fact_source.object_start IS NOT NULL
                    AND fact_source.object_end IS NOT NULL
                    AND fact_source.raw_start <= fact_source.object_end
                    AND fact_source.raw_end >= fact_source.object_start
                     THEN GREATEST(fact_source.raw_start, fact_source.object_start)
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND fact_source.raw_start IS NOT NULL
                    AND fact_source.raw_end IS NOT NULL
                    AND fact_source.ad_start IS NOT NULL
                    AND fact_source.ad_end IS NOT NULL
                    AND tr.rail_start_pk IS NOT NULL
                    AND tr.rail_end_pk IS NOT NULL
                    AND ABS(tr.ad_end_pk - tr.ad_start_pk) > 0.000001
                    AND fact_source.raw_start <= fact_source.ad_end
                    AND fact_source.raw_end >= fact_source.ad_start
                     THEN LEAST(
                       tr.rail_start_pk + ((GREATEST(fact_source.raw_start, fact_source.ad_start) - tr.ad_start_pk) / NULLIF(tr.ad_end_pk - tr.ad_start_pk, 0)) * (tr.rail_end_pk - tr.rail_start_pk),
                       tr.rail_start_pk + ((LEAST(fact_source.raw_end, fact_source.ad_end) - tr.ad_start_pk) / NULLIF(tr.ad_end_pk - tr.ad_start_pk, 0)) * (tr.rail_end_pk - tr.rail_start_pk)
                     )
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE') THEN NULL
                   ELSE fact_source.raw_start
                 END AS pk_start,
                 CASE
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND fact_source.raw_start IS NOT NULL
                    AND fact_source.raw_end IS NOT NULL
                    AND fact_source.object_start IS NOT NULL
                    AND fact_source.object_end IS NOT NULL
                    AND fact_source.raw_start <= fact_source.object_end
                    AND fact_source.raw_end >= fact_source.object_start
                     THEN LEAST(fact_source.raw_end, fact_source.object_end)
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND fact_source.raw_start IS NOT NULL
                    AND fact_source.raw_end IS NOT NULL
                    AND fact_source.ad_start IS NOT NULL
                    AND fact_source.ad_end IS NOT NULL
                    AND tr.rail_start_pk IS NOT NULL
                    AND tr.rail_end_pk IS NOT NULL
                    AND ABS(tr.ad_end_pk - tr.ad_start_pk) > 0.000001
                    AND fact_source.raw_start <= fact_source.ad_end
                    AND fact_source.raw_end >= fact_source.ad_start
                     THEN GREATEST(
                       tr.rail_start_pk + ((GREATEST(fact_source.raw_start, fact_source.ad_start) - tr.ad_start_pk) / NULLIF(tr.ad_end_pk - tr.ad_start_pk, 0)) * (tr.rail_end_pk - tr.rail_start_pk),
                       tr.rail_start_pk + ((LEAST(fact_source.raw_end, fact_source.ad_end) - tr.ad_start_pk) / NULLIF(tr.ad_end_pk - tr.ad_start_pk, 0)) * (tr.rail_end_pk - tr.rail_start_pk)
                     )
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE') THEN NULL
                   ELSE fact_source.raw_end
                 END AS pk_end
        ) fact_range ON true
        LEFT JOIN LATERAL (
          SELECT COALESCE((fact_range.pk_start + fact_range.pk_end) / 2.0, fact_range.pk_start, fact_range.pk_end) AS section_pk
        ) section_point ON true
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND section_point.section_pk IS NOT NULL
            AND section_point.section_pk >= LEAST(csv.pk_start, csv.pk_end)
            AND section_point.section_pk < GREATEST(csv.pk_start, csv.pk_end)
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) effective_section ON true
        LEFT JOIN construction_sections cs_override
          ON cs_override.code = CASE
            WHEN obj.object_code IN ('ASP_2840', 'BRIDGE_282952') THEN 'UCH_3'
            ELSE NULL
         END
         AND cs_override.is_active IS NOT FALSE
        LEFT JOIN LATERAL (
          SELECT csv.section_id,
                 GREATEST(LEAST(fact_range.pk_start, fact_range.pk_end), LEAST(csv.pk_start, csv.pk_end)) AS pk_start,
                 LEAST(GREATEST(fact_range.pk_start, fact_range.pk_end), GREATEST(csv.pk_start, csv.pk_end)) AS pk_end,
                 CASE
                   WHEN ABS(GREATEST(fact_range.pk_start, fact_range.pk_end) - LEAST(fact_range.pk_start, fact_range.pk_end)) < 0.001
                     THEN 1::numeric
                   ELSE (
                     LEAST(GREATEST(fact_range.pk_start, fact_range.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                     - GREATEST(LEAST(fact_range.pk_start, fact_range.pk_end), LEAST(csv.pk_start, csv.pk_end))
                   ) / NULLIF(ABS(fact_range.pk_end - fact_range.pk_start), 0)
                 END AS section_factor
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND cs_override.id IS NULL
            {actual_road_guard}
            AND ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
            AND fact_range.pk_start IS NOT NULL
            AND fact_range.pk_end IS NOT NULL
            AND csv.boundary_kind = 'temp_roads'
            AND LEAST(GREATEST(fact_range.pk_start, fact_range.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                > GREATEST(LEAST(fact_range.pk_start, fact_range.pk_end), LEAST(csv.pk_start, csv.pk_end))
          ORDER BY csv.pk_start, csv.pk_end
        ) road_section_clip ON true
        LEFT JOIN LATERAL (
          SELECT csv.section_id
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND cs_override.id IS NULL
            AND ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
            AND ob.pk_start IS NOT NULL
            AND ob.pk_end IS NOT NULL
            AND csv.boundary_kind = 'temp_roads'
            AND LEAST(GREATEST(ob.pk_start, ob.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                > GREATEST(LEAST(ob.pk_start, ob.pk_end), LEAST(csv.pk_start, csv.pk_end))
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) road_object_section ON true
        LEFT JOIN construction_sections cs_eff
          ON cs_eff.id = COALESCE({effective_section_priority})
         AND cs_eff.is_active IS NOT FALSE
        LEFT JOIN LATERAL (
          SELECT GREATEST(LEAST(fact_range.pk_start, fact_range.pk_end), LEAST(csv.pk_start, csv.pk_end)) AS pk_start,
                 LEAST(GREATEST(fact_range.pk_start, fact_range.pk_end), GREATEST(csv.pk_start, csv.pk_end)) AS pk_end
          FROM construction_section_versions csv
          WHERE csv.is_current
            AND cs_eff.id IS NOT NULL
            {actual_road_guard}
            AND csv.section_id = cs_eff.id
            AND csv.boundary_kind = {_general_boundary_kind_case_sql('ot.code')}
            AND fact_range.pk_start IS NOT NULL
            AND fact_range.pk_end IS NOT NULL
            AND LEAST(GREATEST(fact_range.pk_start, fact_range.pk_end), GREATEST(csv.pk_start, csv.pk_end))
                > GREATEST(LEAST(fact_range.pk_start, fact_range.pk_end), LEAST(csv.pk_start, csv.pk_end))
          ORDER BY csv.pk_start, csv.pk_end
          LIMIT 1
        ) cs_clip ON true
	        WHERE {' AND '.join(filters)}
	        GROUP BY cs_eff.code, cs_eff.name, cs_eff.sort_order, dr.report_date, dr.id,
                 LOWER(COALESCE(dwi.shift, dr.shift, 'day')),
                 obj.id, obj.object_code, obj.name, ot.code, ot.name,
                 wt.id, wt.code, wt.name,
                 COALESCE(NULLIF(BTRIM(seg.analytics_tag), ''), NULLIF(BTRIM(dwi.analytics_tag), ''), NULLIF(BTRIM(wt.analytics_tag), ''), wt.name, dwi.work_name_raw),
                 dwi.labor_source_type, dwi.contractor_name, COALESCE(dwi.unit, wt.default_unit, ''), pf.pile_type, pipe_spec.pile_length_m,
                 CASE
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND (fact_range.pk_start IS NOT NULL OR fact_range.pk_end IS NOT NULL)
                     THEN COALESCE(road_section_clip.pk_start, cs_clip.pk_start, fact_range.pk_start)
                   ELSE fact_range.pk_start
                 END,
                 CASE
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND (fact_range.pk_start IS NOT NULL OR fact_range.pk_end IS NOT NULL)
                     THEN COALESCE(road_section_clip.pk_end, cs_clip.pk_end, fact_range.pk_end)
                   ELSE fact_range.pk_end
                 END,
                 CASE
                   WHEN ot.code IN ('TEMP_ROAD', 'SERVICE_ROAD', 'TEMP_ROAD_PIPE')
                    AND (fact_range.pk_start IS NOT NULL OR fact_range.pk_end IS NOT NULL)
                     THEN ''
	                   ELSE COALESCE(NULLIF(seg.pk_raw_text, ''), NULLIF(pf.pk_raw_text, ''), '')
                 END
        LIMIT 50000
        """,
        params,
    )
    fact_match_index = _statement_general_fact_match_index(rows_by_key)
    for item in fact_rows:
        source_bucket = _general_source_bucket(item.get("labor_source_type"), item.get("contractor_name"))
        category = _general_configured_work_category(
            rules,
            item.get("analytics_tag"),
            item.get("object_type_code"),
            item.get("object_code"),
            source_bucket,
        )
        if not category:
            category = f"work:{item.get('work_type_code') or item.get('work_type_id') or 'unknown'}"
        fact_volume = float(item.get("fact_volume") or 0)
        if not fact_volume:
            continue
        pile_length_m = _statement_pile_length_from_sources(item.get("pile_type"), item.get("pipe_pile_length_m"))
        report_date = item.get("report_date")
        row = _statement_general_find_existing_row_for_fact(
            rows_by_key,
            category=category,
            section_code=item.get("section_code"),
            object_id=item.get("object_id"),
            work_type_id=item.get("work_type_id"),
            unit=item.get("unit"),
            pk_start=item.get("pk_start"),
            pk_end=item.get("pk_end"),
            pile_length_m=pile_length_m,
            work_type_code=item.get("work_type_code"),
            row_index=fact_match_index,
        )
        if row is None:
            row = _statement_general_row_seed(
                rows_by_key,
                days=days,
                category=category,
                category_label=rule_labels.get(category, item.get("work_type_name") or item.get("work_type_code") or category),
                category_sort_order=rule_order.get(category, 9999),
                section_code=item.get("section_code"),
                section_name=item.get("section_name"),
                section_sort_order=item.get("section_sort_order"),
                object_id=item.get("object_id"),
                object_code=item.get("object_code"),
                object_name=item.get("object_name"),
                object_type_code=item.get("object_type_code"),
                object_type_name=item.get("object_type_name"),
                work_type_id=item.get("work_type_id"),
                work_type_code=item.get("work_type_code"),
                work_type_name=item.get("work_type_name"),
                unit=item.get("unit"),
                pk_start=item.get("pk_start"),
                pk_end=item.get("pk_end"),
                pk_raw_text=item.get("pk_raw_text") or None,
                pile_length_m=pile_length_m,
            )
        elif pile_length_m is not None and row.get("pile_length_m") is None:
            row["pile_length_m"] = pile_length_m
        pk_label = _format_pk_range_excel(item.get("pk_start"), item.get("pk_end"), item.get("pk_raw_text") or None)
        pk_segment = _statement_pk_segment(item.get("pk_start"), item.get("pk_end"))
        detail = {
            "date": report_date.isoformat() if hasattr(report_date, "isoformat") else str(report_date),
            "shift": item.get("shift") or "day",
            "volume": round(fact_volume, 3),
            "material_volume": round(fact_volume, 3),
            "pk_range": pk_label,
            "pk_start": _as_float(item.get("pk_start")) if item.get("pk_start") is not None else None,
            "pk_end": _as_float(item.get("pk_end")) if item.get("pk_end") is not None else None,
            "source_bucket": source_bucket,
            "report_id": item.get("report_id"),
            "pile_length_m": pile_length_m,
        }
        row["has_source"] = True
        row["cumulative_fact"] += fact_volume
        if pk_segment:
            row["cumulative_pk_segments"].append(pk_segment)
        row["cumulative_details"].append(dict(detail))
        if month_start <= report_date <= month_end:
            day = row["day_values"].get(report_date.isoformat())
            if day is not None:
                day["fact_volume"] += fact_volume
                if pk_segment and pk_segment["label"] not in day["pk_ranges"]:
                    day["pk_ranges"].append(pk_segment["label"])
                    day["pk_segments"].append(dict(pk_segment))
                day["details"].append(dict(detail))
            row["month_fact"] += fact_volume
            row["month_details"].append(dict(detail))


def _statement_general_totals(rows: list[dict]) -> list[dict]:
    buckets: dict[str, dict] = {}
    for row in rows:
        unit = row.get("unit") or "—"
        bucket = buckets.setdefault(unit, {"unit": unit, "project_volume": 0.0, "month_plan": 0.0, "month_fact": 0.0, "cumulative_plan": 0.0, "cumulative_fact": 0.0})
        for field in ("project_volume", "month_plan", "month_fact", "cumulative_plan", "cumulative_fact"):
            bucket[field] += float(row.get(field) or 0)
    return [
        {
            **bucket,
            "project_volume": round(bucket["project_volume"], 3),
            "month_plan": round(bucket["month_plan"], 3),
            "month_fact": round(bucket["month_fact"], 3),
            "cumulative_plan": round(bucket["cumulative_plan"], 3),
            "cumulative_fact": round(bucket["cumulative_fact"], 3),
            "month_percent": round(bucket["month_fact"] / bucket["month_plan"] * 100, 1) if bucket["month_plan"] else None,
            "cumulative_percent": round(bucket["cumulative_fact"] / bucket["project_volume"] * 100, 1) if bucket["project_volume"] else None,
        }
        for bucket in sorted(buckets.values(), key=lambda item: item["unit"])
    ]


def _statement_amount_summary(rows: list[dict], amount_field: str, missing_field: str, volume_field: str) -> dict:
    amount = 0.0
    missing = False
    for row in rows:
        if row.get(missing_field) and abs(float(row.get(volume_field) or 0)) > 0.000001:
            missing = True
            continue
        if row.get(amount_field) is not None:
            amount += float(row.get(amount_field) or 0)
    return {
        "amount": round(amount, 2),
        "amount_mln": round(amount / 1_000_000.0, 6),
        "missing_rate": missing,
    }


def _statement_general_financial_summary(rows: list[dict], month_start: date_cls, month_end: date_cls) -> dict:
    today = date_cls.today()
    year_end = today if month_start <= today <= month_end else month_end
    year_start = date_cls(year_end.year, 1, 1)
    decade_start, decade_end = _statement_current_decade_bounds(month_start, month_end)
    month_fact = _statement_amount_summary(rows, "month_amount", "month_amount_missing_rate", "month_fact")
    month_plan = _statement_amount_summary(rows, "month_plan_amount", "month_plan_amount_missing_rate", "month_plan")
    year_fact = _statement_amount_summary(rows, "current_year_amount", "current_year_amount_missing_rate", "cumulative_fact")
    year_plan = _statement_amount_summary(rows, "current_year_plan_amount", "current_year_plan_amount_missing_rate", "current_year_plan")
    decade_fact = _statement_amount_summary(rows, "current_decade_amount", "current_decade_amount_missing_rate", "cumulative_fact")
    decade_plan = _statement_amount_summary(rows, "current_decade_plan_amount", "current_decade_plan_amount_missing_rate", "current_decade_plan")
    fact_amount = month_fact.get("amount")
    plan_amount = month_plan.get("amount")
    month_plan_completion_pct = None
    if fact_amount is not None and plan_amount is not None and abs(float(plan_amount or 0)) > 0.000001:
        month_plan_completion_pct = round(float(fact_amount or 0) / float(plan_amount or 0) * 100, 1)
    year_plan_completion_pct = None
    if year_fact.get("amount") is not None and year_plan.get("amount") is not None and abs(float(year_plan.get("amount") or 0)) > 0.000001:
        year_plan_completion_pct = round(float(year_fact.get("amount") or 0) / float(year_plan.get("amount") or 0) * 100, 1)
    decade_plan_completion_pct = None
    if decade_fact.get("amount") is not None and decade_plan.get("amount") is not None and abs(float(decade_plan.get("amount") or 0)) > 0.000001:
        decade_plan_completion_pct = round(float(decade_fact.get("amount") or 0) / float(decade_plan.get("amount") or 0) * 100, 1)
    return {
        "currency": "RUB",
        "all_time": _statement_amount_summary(rows, "cumulative_amount", "cumulative_amount_missing_rate", "cumulative_fact"),
        "current_year": {
            **year_fact,
            "date_from": year_start.isoformat(),
            "date_to": year_end.isoformat(),
        },
        "current_year_plan": {
            **year_plan,
            "date_from": year_start.isoformat(),
            "date_to": year_end.isoformat(),
        },
        "current_year_plan_completion_pct": year_plan_completion_pct,
        "current_month": {
            **month_fact,
            "date_from": month_start.isoformat(),
            "date_to": month_end.isoformat(),
        },
        "current_decade": {
            **decade_fact,
            "date_from": decade_start.isoformat(),
            "date_to": decade_end.isoformat(),
        },
        "current_decade_plan": {
            **decade_plan,
            "date_from": decade_start.isoformat(),
            "date_to": decade_end.isoformat(),
        },
        "current_decade_plan_completion_pct": decade_plan_completion_pct,
        "current_month_plan": month_plan,
        "current_month_plan_completion_pct": month_plan_completion_pct,
    }


def _statement_general_cache_piece(table_name: str, where_sql: str = "", params: tuple[object, ...] = ()) -> dict[str, str]:
    if not _dashboard_table_exists(table_name):
        return {"table": table_name, "missing": "1", "rows": "0", "max_xmin": "0"}
    where_clause = f"WHERE {where_sql}" if where_sql else ""
    row = query_one(
        f"""
        SELECT COUNT(*)::text AS rows,
               COALESCE(MAX(xmin::text::bigint), 0)::text AS max_xmin
        FROM {table_name}
        {where_clause}
        """,
        params,
    ) or {}
    return {
        "table": table_name,
        "rows": str(row.get("rows") or "0"),
        "max_xmin": str(row.get("max_xmin") or "0"),
    }


def _statement_general_workbook_fingerprint(month_start: date_cls, month_end: date_cls) -> str:
    pieces = [
        _statement_general_cache_piece("planned_work_items"),
        _statement_general_cache_piece("statement_signed_pile_plan_batches"),
        _statement_general_cache_piece("statement_signed_pile_plan_items"),
        _statement_general_cache_piece("project_work_items"),
        _statement_general_cache_piece("project_work_item_segments"),
        _statement_general_cache_piece("pile_fields"),
        _statement_general_cache_piece("daily_reports", "report_date BETWEEN %s AND %s", (PROJECT_START_DATE, month_end)),
        _statement_general_cache_piece("daily_work_items", "report_date BETWEEN %s AND %s", (PROJECT_START_DATE, month_end)),
        _statement_general_cache_piece("daily_work_item_segments"),
        _statement_general_cache_piece("material_movements", "report_date BETWEEN %s AND %s", (PROJECT_START_DATE, month_end)),
        _statement_general_cache_piece("objects"),
        _statement_general_cache_piece("object_segments"),
        _statement_general_cache_piece("object_types"),
        _statement_general_cache_piece("work_types"),
        _statement_general_cache_piece("work_type_unit_rates"),
        _statement_general_cache_piece("statement_object_unit_rates"),
        _statement_general_cache_piece("construction_sections"),
        _statement_general_cache_piece("construction_section_versions", "is_current IS TRUE"),
        _statement_general_cache_piece("temporary_roads"),
        _statement_general_cache_piece("equipment_norms_config", "category = 'compaction_coefficients'"),
    ]
    stable = json.dumps({
        "version": STATEMENTS_GENERAL_WORKBOOK_CACHE_VERSION,
        "month_start": month_start.isoformat(),
        "month_end": month_end.isoformat(),
        "pieces": pieces,
    }, ensure_ascii=False, sort_keys=True)
    return f"{STATEMENTS_GENERAL_WORKBOOK_CACHE_VERSION}:{hashlib.sha256(stable.encode('utf-8')).hexdigest()}"


def _statement_general_workbook_cache_params(
    *,
    month_key: str,
    section: Optional[str],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    include_metadata: bool,
    actual_section_binding: bool,
) -> dict[str, object]:
    return {
        "endpoint": "statements_general_workbook",
        "month": month_key,
        "section": section or "",
        "object_type": object_type or "",
        "object_id": object_id or "",
        "q": (q or "").strip(),
        "include_metadata": include_metadata,
        "actual_section_binding": bool(actual_section_binding),
    }


def _statement_general_workbook_short_key(cache_params: dict[str, object], fingerprint: str) -> tuple:
    return (
        cache_params["month"],
        cache_params["section"],
        cache_params["object_type"],
        cache_params["object_id"],
        cache_params["q"],
        cache_params["include_metadata"],
        cache_params["actual_section_binding"],
        fingerprint,
    )


def _statement_general_workbook_persistent_key(cache_params: dict[str, object]) -> str:
    return _dashboard_response_cache_key(cache_params)


def _statement_general_workbook_json_cache_path(persistent_key: str, fingerprint: str) -> Path:
    fingerprint_hash = hashlib.sha256(fingerprint.encode("utf-8")).hexdigest()
    return STATEMENTS_GENERAL_WORKBOOK_JSON_CACHE_DIR / f"{persistent_key}_{fingerprint_hash}.json"


def _statement_general_workbook_json_cache_glob(persistent_key: str) -> list[Path]:
    if not STATEMENTS_GENERAL_WORKBOOK_JSON_CACHE_DIR.exists():
        return []
    return sorted(
        STATEMENTS_GENERAL_WORKBOOK_JSON_CACHE_DIR.glob(f"{persistent_key}_*.json"),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )


def _statement_general_workbook_json_cache_read(path: Path, *, max_age_seconds: int) -> Optional[dict]:
    try:
        if max_age_seconds > 0 and time.time() - path.stat().st_mtime > max_age_seconds:
            return None
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    cache_info = data.get("cache") if isinstance(data.get("cache"), dict) else {}
    return {
        "payload": data,
        "fingerprint": str(cache_info.get("fingerprint") or ""),
        "created_at": str(cache_info.get("persistent_created_at") or datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat()),
    }


def _statement_general_workbook_cache_get(persistent_key: str, fingerprint: str) -> Optional[dict]:
    if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS <= 0:
        return None
    entry = _statement_general_workbook_json_cache_read(
        _statement_general_workbook_json_cache_path(persistent_key, fingerprint),
        max_age_seconds=DASHBOARD_RESPONSE_CACHE_TTL_SECONDS,
    )
    return entry["payload"] if entry else None


def _statement_general_workbook_cache_file_is_fresh(persistent_key: str, fingerprint: str) -> bool:
    if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS <= 0:
        return False
    path = _statement_general_workbook_json_cache_path(persistent_key, fingerprint)
    try:
        return path.exists() and time.time() - path.stat().st_mtime <= DASHBOARD_RESPONSE_CACHE_TTL_SECONDS
    except OSError:
        return False


def _statement_general_workbook_cache_file_response(persistent_key: str, fingerprint: str) -> Optional[FileResponse]:
    path = _statement_general_workbook_json_cache_path(persistent_key, fingerprint)
    if not _statement_general_workbook_cache_file_is_fresh(persistent_key, fingerprint):
        return None
    return FileResponse(path, media_type="application/json")


def _statement_general_workbook_cache_get_latest(persistent_key: str, max_age_seconds: int) -> Optional[dict]:
    for path in _statement_general_workbook_json_cache_glob(persistent_key):
        entry = _statement_general_workbook_json_cache_read(path, max_age_seconds=max_age_seconds)
        if entry is not None:
            return entry
    return None


def _statement_general_workbook_cache_get_latest_file(persistent_key: str, max_age_seconds: int) -> Optional[dict]:
    for path in _statement_general_workbook_json_cache_glob(persistent_key):
        try:
            stat = path.stat()
            if max_age_seconds > 0 and time.time() - stat.st_mtime > max_age_seconds:
                continue
            return {
                "path": path,
                "token": f"{path.name}:{stat.st_mtime_ns}",
                "created_at": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(),
            }
        except FileNotFoundError:
            continue
    return None


def _statement_general_workbook_cache_set(persistent_key: str, fingerprint: str, payload: dict) -> dict:
    if DASHBOARD_RESPONSE_CACHE_TTL_SECONDS <= 0:
        return payload
    STATEMENTS_GENERAL_WORKBOOK_JSON_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    created_at = datetime.now(timezone.utc).isoformat()
    cache_path = _statement_general_workbook_json_cache_path(persistent_key, fingerprint)
    tmp_path = cache_path.with_suffix(cache_path.suffix + f".{uuid.uuid4().hex}.tmp")
    file_payload = dict(payload)
    file_payload["updated_at"] = str(file_payload.get("updated_at") or created_at)
    file_payload["cache"] = {
        "status": "fresh",
        "fingerprint": fingerprint,
        "generated_at": file_payload["updated_at"],
        "persistent_created_at": created_at,
        "refreshing": False,
    }
    tmp_path.write_text(json.dumps(file_payload, ensure_ascii=False, default=str), encoding="utf-8")
    tmp_path.replace(cache_path)
    cutoff = time.time() - max(DASHBOARD_RESPONSE_CACHE_TTL_SECONDS, STATEMENTS_GENERAL_WORKBOOK_STALE_TTL_SECONDS)
    for path in _statement_general_workbook_json_cache_glob(persistent_key)[8:]:
        try:
            if path.stat().st_mtime < cutoff:
                path.unlink()
        except FileNotFoundError:
            pass
    return payload


def _statement_general_workbook_can_return_stale(cache_params: dict[str, object]) -> bool:
    return cache_params["include_metadata"] is False


def _statement_general_workbook_latest_validation_due(persistent_key: str, token: str) -> bool:
    if STATEMENTS_GENERAL_WORKBOOK_FAST_VALIDATE_SECONDS <= 0:
        return False
    now_ts = time.time()
    with _STATEMENTS_GENERAL_WORKBOOK_VALIDATION_LOCK:
        validated = _STATEMENTS_GENERAL_WORKBOOK_VALIDATED_KEYS.get(persistent_key)
        if validated and validated[0] > now_ts and validated[1] == token:
            return False
        _STATEMENTS_GENERAL_WORKBOOK_VALIDATED_KEYS[persistent_key] = (
            now_ts + STATEMENTS_GENERAL_WORKBOOK_FAST_VALIDATE_SECONDS,
            token,
        )
    return True


def _statement_general_workbook_mark_cache(
    payload: dict,
    *,
    status: str,
    fingerprint: str,
    persistent_created_at: Optional[str] = None,
    refreshing: bool = False,
) -> dict:
    out = dict(payload)
    generated_at = str(out.get("updated_at") or persistent_created_at or datetime.now(timezone.utc).isoformat())
    out["updated_at"] = generated_at
    out["cache"] = {
        "status": status,
        "fingerprint": fingerprint,
        "generated_at": generated_at,
        "persistent_created_at": persistent_created_at,
        "refreshing": refreshing,
    }
    return out


def _statement_general_workbook_try_build_lock(lock_key: str):
    conn = get_conn()
    conn.autocommit = True
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT pg_try_advisory_lock(hashtext(%s))", (lock_key,))
            locked = bool((cur.fetchone() or [False])[0])
        if locked:
            return conn
    except Exception:
        conn.close()
        raise
    conn.close()
    return None


def _statement_general_workbook_release_build_lock(conn, lock_key: str) -> None:
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT pg_advisory_unlock(hashtext(%s))", (lock_key,))
    except Exception:
        pass
    finally:
        conn.close()


def _statement_general_workbook_build_and_cache(
    *,
    month_key: str,
    section: Optional[str],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    include_metadata: bool,
    actual_section_binding: bool,
    fingerprint: str,
    persistent_key: str,
    short_key: Optional[tuple] = None,
    _user=None,
) -> dict:
    payload = _statements_general_workbook_payload(
        month=month_key,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        include_metadata=include_metadata,
        actual_section_binding=actual_section_binding,
        _user=_user,
    )
    payload = dict(payload)
    payload["updated_at"] = datetime.now(timezone.utc).isoformat()
    _statement_general_workbook_cache_set(persistent_key, fingerprint, payload)
    marked = _statement_general_workbook_mark_cache(payload, status="fresh", fingerprint=fingerprint)
    if short_key is not None:
        _dashboard_short_cache_set(_STATEMENTS_GENERAL_WORKBOOK_CACHE, short_key, marked)
    return marked


def _statement_general_workbook_build_or_wait(
    *,
    month_key: str,
    section: Optional[str],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    include_metadata: bool,
    actual_section_binding: bool,
    allow_stale: bool,
    use_file_response: bool,
    fingerprint: str,
    persistent_key: str,
    short_key: tuple,
    cache_params: dict[str, object],
    _user=None,
):
    lock_key = f"{STATEMENTS_GENERAL_WORKBOOK_CACHE_ENDPOINT}:{persistent_key}:{fingerprint}"
    lock_conn = _statement_general_workbook_try_build_lock(lock_key)
    if lock_conn is None:
        deadline = time.monotonic() + max(0.0, STATEMENTS_GENERAL_WORKBOOK_BUILD_WAIT_SECONDS)
        while time.monotonic() < deadline:
            if use_file_response:
                cached_file = _statement_general_workbook_cache_file_response(persistent_key, fingerprint)
                if cached_file is not None:
                    return cached_file
            cached = _statement_general_workbook_cache_get(persistent_key, fingerprint)
            if cached is not None:
                marked = _statement_general_workbook_mark_cache(cached, status="fresh", fingerprint=fingerprint)
                if not use_file_response:
                    return _dashboard_short_cache_set(_STATEMENTS_GENERAL_WORKBOOK_CACHE, short_key, marked)
                return marked
            time.sleep(0.25)

        if allow_stale and _statement_general_workbook_can_return_stale(cache_params):
            stale = _statement_general_workbook_cache_get_latest(persistent_key, STATEMENTS_GENERAL_WORKBOOK_STALE_TTL_SECONDS)
            if stale is not None:
                payload = _statement_general_workbook_mark_cache(
                    stale["payload"],
                    status="stale",
                    fingerprint=str(stale.get("fingerprint") or ""),
                    persistent_created_at=stale.get("created_at"),
                    refreshing=True,
                )
                payload["cache"]["expected_fingerprint"] = fingerprint
                return payload
        raise HTTPException(503, "Ведомость уже пересчитывается; обновите вкладку через несколько секунд.")

    try:
        if use_file_response:
            cached_file = _statement_general_workbook_cache_file_response(persistent_key, fingerprint)
            if cached_file is not None:
                return cached_file
        cached = _statement_general_workbook_cache_get(persistent_key, fingerprint)
        if cached is not None:
            marked = _statement_general_workbook_mark_cache(cached, status="fresh", fingerprint=fingerprint)
            if not use_file_response:
                return _dashboard_short_cache_set(_STATEMENTS_GENERAL_WORKBOOK_CACHE, short_key, marked)
            return marked
        return _statement_general_workbook_build_and_cache(
            month_key=month_key,
            section=section,
            object_type=object_type,
            object_id=object_id,
            q=q,
            include_metadata=include_metadata,
            actual_section_binding=actual_section_binding,
            fingerprint=fingerprint,
            persistent_key=persistent_key,
            short_key=None if use_file_response else short_key,
            _user=_user,
        )
    finally:
        _statement_general_workbook_release_build_lock(lock_conn, lock_key)


def _statement_general_workbook_refresh_async(
    *,
    month_key: str,
    section: Optional[str],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    include_metadata: bool,
    actual_section_binding: bool,
    fingerprint: str,
    persistent_key: str,
    short_key: tuple,
    reason: str,
) -> bool:
    refresh_key = (persistent_key, fingerprint)
    with _STATEMENTS_GENERAL_WORKBOOK_REFRESH_LOCK:
        if refresh_key in _STATEMENTS_GENERAL_WORKBOOK_REFRESHING_KEYS:
            return False
        _STATEMENTS_GENERAL_WORKBOOK_REFRESHING_KEYS.add(refresh_key)

    def run() -> None:
        lock_key = f"{STATEMENTS_GENERAL_WORKBOOK_CACHE_ENDPOINT}:{persistent_key}:{fingerprint}"
        lock_conn = None
        try:
            lock_conn = _statement_general_workbook_try_build_lock(lock_key)
            if lock_conn is None:
                return
            cached = _statement_general_workbook_cache_get(persistent_key, fingerprint)
            if cached is not None:
                _dashboard_short_cache_set(
                    _STATEMENTS_GENERAL_WORKBOOK_CACHE,
                    short_key,
                    _statement_general_workbook_mark_cache(cached, status="fresh", fingerprint=fingerprint),
                )
                return
            _statement_general_workbook_build_and_cache(
                month_key=month_key,
                section=section,
                object_type=object_type,
                object_id=object_id,
                q=q,
                include_metadata=include_metadata,
                actual_section_binding=actual_section_binding,
                fingerprint=fingerprint,
                persistent_key=persistent_key,
                short_key=short_key,
                _user=None,
            )
        except Exception as exc:
            print(f"[statements-cache] background refresh failed ({reason}): {exc}", flush=True)
        finally:
            if lock_conn is not None:
                _statement_general_workbook_release_build_lock(lock_conn, lock_key)
            with _STATEMENTS_GENERAL_WORKBOOK_REFRESH_LOCK:
                _STATEMENTS_GENERAL_WORKBOOK_REFRESHING_KEYS.discard(refresh_key)

    thread = threading.Thread(target=run, name="statements-general-workbook-refresh", daemon=True)
    thread.start()
    return True


def _statement_general_workbook_validate_latest_async(
    *,
    month_key: str,
    month_start: date_cls,
    month_end: date_cls,
    section: Optional[str],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    include_metadata: bool,
    actual_section_binding: bool,
    persistent_key: str,
    token: str,
    reason: str,
) -> bool:
    if not _statement_general_workbook_latest_validation_due(persistent_key, token):
        return False
    refresh_key = (persistent_key, "latest-validation")
    with _STATEMENTS_GENERAL_WORKBOOK_REFRESH_LOCK:
        if refresh_key in _STATEMENTS_GENERAL_WORKBOOK_REFRESHING_KEYS:
            return False
        _STATEMENTS_GENERAL_WORKBOOK_REFRESHING_KEYS.add(refresh_key)

    def run() -> None:
        lock_conn = None
        lock_key = ""
        try:
            fingerprint = _statement_general_workbook_fingerprint(month_start, month_end)
            if _statement_general_workbook_cache_file_is_fresh(persistent_key, fingerprint):
                return
            lock_key = f"{STATEMENTS_GENERAL_WORKBOOK_CACHE_ENDPOINT}:{persistent_key}:{fingerprint}"
            lock_conn = _statement_general_workbook_try_build_lock(lock_key)
            if lock_conn is None:
                return
            if _statement_general_workbook_cache_file_is_fresh(persistent_key, fingerprint):
                return
            _statement_general_workbook_build_and_cache(
                month_key=month_key,
                section=section,
                object_type=object_type,
                object_id=object_id,
                q=q,
                include_metadata=include_metadata,
                actual_section_binding=actual_section_binding,
                fingerprint=fingerprint,
                persistent_key=persistent_key,
                short_key=None,
                _user=None,
            )
        except Exception as exc:
            print(f"[statements-cache] latest validation failed ({reason}): {exc}", flush=True)
        finally:
            if lock_conn is not None:
                _statement_general_workbook_release_build_lock(lock_conn, lock_key)
            with _STATEMENTS_GENERAL_WORKBOOK_REFRESH_LOCK:
                _STATEMENTS_GENERAL_WORKBOOK_REFRESHING_KEYS.discard(refresh_key)

    thread = threading.Thread(target=run, name="statements-general-workbook-latest-validation", daemon=True)
    thread.start()
    return True


def _warm_statements_general_workbook_mode(
    *,
    month_key: str,
    fingerprint: str,
    actual_section_binding: bool,
) -> dict[str, object]:
    cache_params = _statement_general_workbook_cache_params(
        month_key=month_key,
        section=None,
        object_type=None,
        object_id=None,
        q=None,
        include_metadata=False,
        actual_section_binding=actual_section_binding,
    )
    persistent_key = _statement_general_workbook_persistent_key(cache_params)
    if _statement_general_workbook_cache_file_is_fresh(persistent_key, fingerprint):
        return {"status": "hit"}
    lock_key = f"{STATEMENTS_GENERAL_WORKBOOK_CACHE_ENDPOINT}:{persistent_key}:{fingerprint}"
    lock_conn = _statement_general_workbook_try_build_lock(lock_key)
    if lock_conn is None:
        return {"status": "locked"}
    try:
        if _statement_general_workbook_cache_file_is_fresh(persistent_key, fingerprint):
            return {"status": "hit"}
        _statement_general_workbook_build_and_cache(
            month_key=month_key,
            section=None,
            object_type=None,
            object_id=None,
            q=None,
            include_metadata=False,
            actual_section_binding=actual_section_binding,
            fingerprint=fingerprint,
            persistent_key=persistent_key,
            short_key=None,
            _user=None,
        )
        return {"status": "warmed"}
    finally:
        _statement_general_workbook_release_build_lock(lock_conn, lock_key)


def _warm_statements_general_workbook_current_month() -> dict[str, object]:
    month_key, month_start, month_end = _statement_general_month_bounds(None)
    fingerprint = _statement_general_workbook_fingerprint(month_start, month_end)
    modes: dict[str, object] = {}
    for actual_section_binding in (False, True):
        mode_key = "actual" if actual_section_binding else "nominal"
        modes[mode_key] = _warm_statements_general_workbook_mode(
            month_key=month_key,
            fingerprint=fingerprint,
            actual_section_binding=actual_section_binding,
        )
    return {"ok": True, "month": month_key, "modes": modes}


def _statements_general_workbook_warmer_loop() -> None:
    delay = max(0, STATEMENTS_GENERAL_WORKBOOK_INITIAL_WARM_DELAY_SECONDS)
    if delay:
        time.sleep(delay)
    while True:
        try:
            _warm_statements_general_workbook_current_month()
        except Exception as exc:
            print(f"[statements-cache] hourly warm failed: {exc}", flush=True)
        interval = max(300, STATEMENTS_GENERAL_WORKBOOK_WARM_INTERVAL_SECONDS)
        time.sleep(interval)


def _start_statements_general_workbook_warmer() -> bool:
    global _STATEMENTS_GENERAL_WORKBOOK_WARMER_STARTED
    if STATEMENTS_GENERAL_WORKBOOK_WARM_INTERVAL_SECONDS <= 0:
        return False
    with _STATEMENTS_GENERAL_WORKBOOK_WARMER_LOCK:
        if _STATEMENTS_GENERAL_WORKBOOK_WARMER_STARTED:
            return False
        _STATEMENTS_GENERAL_WORKBOOK_WARMER_STARTED = True
    thread = threading.Thread(target=_statements_general_workbook_warmer_loop, name="statements-general-workbook-warmer", daemon=True)
    thread.start()
    return True


def _statements_general_workbook_payload(
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    include_metadata: bool = True,
    actual_section_binding: bool = False,
    _user=Depends(current_user),
):
    """Electronic Statements view backed by Генеральный отчет work rules."""
    month_key, month_start, month_end = _statement_general_month_bounds(month)
    section_codes = _expand_sections(section)
    query_pk_start, query_pk_end, _ = _statement_search_pk_range(q)
    compaction_rules = _load_compaction_coefficient_rules()
    rate_map = _statement_work_type_rate_map()
    object_rate_map = _statement_object_rate_map()
    days = _statement_general_day_response(month_start, month_end)
    rows_by_key: dict[str, dict] = {}
    _statement_general_add_project_rows(
        rows_by_key,
        days=days,
        section_codes=section_codes,
        object_type=object_type,
        object_id=object_id,
        q=q,
        actual_section_binding=actual_section_binding,
    )
    _statement_general_add_plan_rows(
        rows_by_key,
        days=days,
        period_start=month_start,
        period_end=month_end,
        section_codes=section_codes,
        object_type=object_type,
        object_id=object_id,
        q=q,
        actual_section_binding=actual_section_binding,
    )
    _statement_general_add_fact_rows(
        rows_by_key,
        days=days,
        month_start=month_start,
        month_end=month_end,
        cumulative_end=month_end,
        section_codes=section_codes,
        object_type=object_type,
        object_id=object_id,
        q=q,
        actual_section_binding=actual_section_binding,
    )
    signed_pile_plan = _statement_signed_pile_plan_for_period(month_start, month_end)
    if signed_pile_plan:
        signed_work_codes = set(STATEMENT_SIGNED_PILE_PLAN_WORK_TYPE_CODES)
        for row in rows_by_key.values():
            if str(row.get("work_type_code") or "").upper() in signed_work_codes:
                row["month_plan_locked"] = True
                row["month_plan_source"] = "Подписанная производственная программа"
    rows = []
    for row in rows_by_key.values():
        row["cumulative_pk_segments"] = _statement_merge_pk_segments(row.get("cumulative_pk_segments") or [], 5.0)
        row["cumulative_pk_ranges"] = [segment["label"] for segment in row["cumulative_pk_segments"]]
        for value in row["day_values"].values():
            value["pk_segments"] = _statement_merge_pk_segments(value.get("pk_segments") or [], 5.0)
            value["pk_ranges"] = [segment["label"] for segment in value["pk_segments"]]
        _statement_apply_compaction(row, compaction_rules)
        row["day_values"] = _statement_general_compact_day_values(row["day_values"])
        if not _statement_general_row_overlaps_pk(row, query_pk_start, query_pk_end):
            continue
        project_refs = [ref for ref in (row.get("project_refs") or []) if ref.get("project_item_id")]
        unique_project_keys = {
            (str(ref.get("project_item_id") or ""), str(ref.get("project_segment_id") or ""), str(ref.get("pk_start") or ""), str(ref.get("pk_end") or ""))
            for ref in project_refs
        }
        editable_project_refs = [ref for ref in project_refs if ref.get("can_edit")]
        row["project_refs"] = project_refs
        row["project_segment_count"] = len(project_refs)
        row["can_edit_project"] = len(unique_project_keys) == 1 and len(editable_project_refs) == 1
        if row["can_edit_project"]:
            ref = editable_project_refs[0]
            row["project_item_id"] = ref.get("project_item_id")
            row["project_segment_id"] = ref.get("project_segment_id")
        else:
            row["project_item_id"] = None
            row["project_segment_id"] = None
        for field in ("project_volume", "month_plan", "current_year_plan", "current_decade_plan", "month_fact", "cumulative_plan", "cumulative_fact", "material_project_volume", "material_month_plan", "material_month_fact", "material_cumulative_plan", "material_cumulative_fact"):
            row[field] = round(float(row.get(field) or 0), 3)
        _statement_apply_work_type_rates(
            row,
            rate_map,
            object_rate_map,
            month_start=month_start,
            month_end=month_end,
        )
        for detail_list_name in ("month_details", "cumulative_details"):
            for detail in row.get(detail_list_name) or []:
                detail["volume"] = round(float(detail.get("volume") or 0), 3)
                detail["material_volume"] = round(float(detail.get("material_volume") or 0), 3)
        row["month_percent"] = round(row["month_fact"] / row["month_plan"] * 100, 1) if row["month_plan"] else None
        row["cumulative_percent"] = round(row["cumulative_fact"] / row["project_volume"] * 100, 1) if row["project_volume"] else None
        if row.get("has_source") or row["project_volume"] or row["month_plan"] or row["month_fact"] or row["cumulative_plan"] or row["cumulative_fact"]:
            rows.append(row)
    rows.sort(key=lambda item: (
        str(item.get("object_type_name") or item.get("object_type_code") or ""),
        _statement_section_sort_key(item),
        float(item.get("pk_start") if item.get("pk_start") is not None else 10**18),
        str(item.get("object_name") or item.get("object_code") or ""),
        int(item.get("category_sort_order") if item.get("category_sort_order") is not None else 9999),
        str(item.get("category_label") or ""),
        str(item.get("work_type_name") or item.get("work_type_code") or ""),
    ))
    metadata = _statement_metadata_payload(
        section,
        None,
        None,
        object_type,
        actual_section_binding=actual_section_binding,
    ) if include_metadata else {}
    return {
        "month": month_key,
        "month_start": month_start.isoformat(),
        "month_end": month_end.isoformat(),
        "days": days,
        "rules": _statement_general_work_rule_payload(),
        "sections": metadata.get("sections", []),
        "object_types": metadata.get("object_types", []),
        "objects": metadata.get("objects", []),
        "work_types": metadata.get("work_types", []),
        "sand_by_section": _statement_sand_by_section(month_start, month_end, section_codes),
        "rows": rows,
        "totals": _statement_general_totals(rows),
        "financial_summary": _statement_general_financial_summary(rows, month_start, month_end),
        "row_count": len(rows),
        "actual_section_binding": bool(actual_section_binding),
        "signed_pile_plan": signed_pile_plan,
    }


@router.get("/statements/general-workbook")
def statements_general_workbook(
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    include_metadata: bool = True,
    actual_section_binding: bool = False,
    allow_stale: bool = True,
    use_file_response: bool = True,
    _user=Depends(current_user),
):
    month_key, month_start, month_end = _statement_general_month_bounds(month)
    cache_params = _statement_general_workbook_cache_params(
        month_key=month_key,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        include_metadata=include_metadata,
        actual_section_binding=actual_section_binding,
    )
    persistent_key = _statement_general_workbook_persistent_key(cache_params)

    if use_file_response and allow_stale and _statement_general_workbook_can_return_stale(cache_params):
        latest_file = _statement_general_workbook_cache_get_latest_file(
            persistent_key,
            STATEMENTS_GENERAL_WORKBOOK_STALE_TTL_SECONDS,
        )
        if latest_file is not None:
            _statement_general_workbook_validate_latest_async(
                month_key=month_key,
                month_start=month_start,
                month_end=month_end,
                section=section,
                object_type=object_type,
                object_id=object_id,
                q=q,
                include_metadata=include_metadata,
                actual_section_binding=actual_section_binding,
                persistent_key=persistent_key,
                token=str(latest_file.get("token") or ""),
                reason="fast_file_response",
            )
            return FileResponse(latest_file["path"], media_type="application/json")

    fingerprint = _statement_general_workbook_fingerprint(month_start, month_end)
    short_key = _statement_general_workbook_short_key(cache_params, fingerprint)
    if not use_file_response:
        cached = _dashboard_short_cache_get(_STATEMENTS_GENERAL_WORKBOOK_CACHE, short_key)
        if cached is not None:
            return cached

    if use_file_response:
        cached_file = _statement_general_workbook_cache_file_response(persistent_key, fingerprint)
        if cached_file is not None:
            return cached_file
    cached = _statement_general_workbook_cache_get(persistent_key, fingerprint)
    if cached is not None:
        marked = _statement_general_workbook_mark_cache(cached, status="fresh", fingerprint=fingerprint)
        if not use_file_response:
            return _dashboard_short_cache_set(_STATEMENTS_GENERAL_WORKBOOK_CACHE, short_key, marked)
        return marked

    if allow_stale and _statement_general_workbook_can_return_stale(cache_params):
        stale = _statement_general_workbook_cache_get_latest(persistent_key, STATEMENTS_GENERAL_WORKBOOK_STALE_TTL_SECONDS)
        if stale is not None:
            refreshing = _statement_general_workbook_refresh_async(
                month_key=month_key,
                section=section,
                object_type=object_type,
                object_id=object_id,
                q=q,
                include_metadata=include_metadata,
                actual_section_binding=actual_section_binding,
                fingerprint=fingerprint,
                persistent_key=persistent_key,
                short_key=short_key,
                reason="stale_request",
            )
            payload = _statement_general_workbook_mark_cache(
                stale["payload"],
                status="stale",
                fingerprint=str(stale.get("fingerprint") or ""),
                persistent_created_at=stale.get("created_at"),
                refreshing=refreshing,
            )
            return payload

    return _statement_general_workbook_build_or_wait(
        month_key=month_key,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        include_metadata=include_metadata,
        actual_section_binding=actual_section_binding,
        allow_stale=allow_stale,
        use_file_response=use_file_response,
        fingerprint=fingerprint,
        persistent_key=persistent_key,
        short_key=short_key,
        cache_params=cache_params,
        _user=_user,
    )


def _statement_general_row_object_key(row: dict) -> str:
    return str(row.get("object_id") or row.get("object_code") or row.get("object_name") or "__none__")


def _statement_row_month_plan_abs(row: dict) -> float:
    return abs(float(row.get("month_plan") or 0)) + abs(float(row.get("material_month_plan") or 0))


def _statement_row_missing_visible_rate(row: dict) -> bool:
    if _statement_row_month_plan_abs(row) > 0.000001 and (row.get("month_plan_amount_missing_rate") or row.get("month_plan_amount") is None):
        return True
    if abs(float(row.get("month_fact") or 0)) + abs(float(row.get("material_month_fact") or 0)) > 0.000001 and (row.get("month_amount_missing_rate") or row.get("month_amount") is None):
        return True
    if abs(float(row.get("cumulative_fact") or 0)) + abs(float(row.get("material_cumulative_fact") or 0)) > 0.000001 and (row.get("cumulative_amount_missing_rate") or row.get("cumulative_amount") is None):
        return True
    return False


def _statement_general_filter_visible_rows(
    rows: list[dict],
    *,
    hide_zero_works: bool = False,
    hide_zero_objects: bool = False,
    only_with_plan: bool = False,
    only_missing_rate: bool = False,
) -> list[dict]:
    result = list(rows or [])
    if hide_zero_objects:
        month_fact_by_object: dict[str, float] = {}
        for row in result:
            key = _statement_general_row_object_key(row)
            month_fact_by_object[key] = (
                month_fact_by_object.get(key, 0.0)
                + abs(float(row.get("month_fact") or 0))
                + abs(float(row.get("material_month_fact") or 0))
            )
        result = [
            row for row in result
            if month_fact_by_object.get(_statement_general_row_object_key(row), 0.0) > 0.000001
            and abs(float(row.get("month_fact") or 0)) + abs(float(row.get("material_month_fact") or 0)) > 0.000001
        ]
    if hide_zero_works:
        result = [
            row for row in result
            if abs(float(row.get("cumulative_fact") or 0)) + abs(float(row.get("material_cumulative_fact") or 0)) > 0.000001
        ]
    if only_with_plan:
        result = [row for row in result if _statement_row_month_plan_abs(row) > 0.000001]
    if only_missing_rate:
        result = [row for row in result if _statement_row_missing_visible_rate(row)]
    return result


def _statement_general_export_group_key(row: dict) -> str:
    return "||".join([
        str(row.get("category") or ""),
        str(_merge_section(row.get("section_code")) or row.get("section_code") or ""),
        _statement_general_row_object_key(row),
        str(row.get("work_type_id") or row.get("work_type_code") or row.get("work_type_name") or ""),
        str(row.get("unit") or "—"),
    ])


def _statement_general_export_group_rows(rows: list[dict], days: list[dict]) -> list[dict]:
    grouped: dict[str, dict] = {}
    numeric_fields = [
        "project_volume", "month_plan", "current_year_plan", "current_decade_plan", "month_fact", "cumulative_plan", "cumulative_fact",
        "material_project_volume", "material_month_plan", "material_month_fact",
        "material_cumulative_plan", "material_cumulative_fact",
    ]
    for source in rows or []:
        key = _statement_general_export_group_key(source)
        row = grouped.get(key)
        if row is None:
            row = dict(source)
            row["id"] = f"group:{key}"
            for field in numeric_fields:
                row[field] = 0.0
            row["month_plan_amount"] = 0.0
            row["month_plan_amount_missing_rate"] = False
            row["month_amount"] = 0.0
            row["month_amount_missing_rate"] = False
            row["cumulative_amount"] = 0.0
            row["cumulative_amount_missing_rate"] = False
            row["pk_start"] = None
            row["pk_end"] = None
            row["cumulative_pk_segments"] = []
            row["cumulative_pk_ranges"] = []
            row["day_values"] = _statement_general_empty_day_values(days)
            row["source_rows"] = []
            grouped[key] = row
        row["source_rows"].append(source)
        for field in numeric_fields:
            row[field] = float(row.get(field) or 0) + float(source.get(field) or 0)
        if source.get("pk_start") is not None:
            row["pk_start"] = float(source.get("pk_start")) if row.get("pk_start") is None else min(float(row["pk_start"]), float(source.get("pk_start")))
        if source.get("pk_end") is not None:
            row["pk_end"] = float(source.get("pk_end")) if row.get("pk_end") is None else max(float(row["pk_end"]), float(source.get("pk_end")))
        if source.get("month_amount_missing_rate") and abs(float(source.get("month_fact") or 0)) > 0.000001:
            row["month_amount_missing_rate"] = True
            row["month_amount"] = None
        elif not row.get("month_amount_missing_rate"):
            row["month_amount"] = float(row.get("month_amount") or 0) + float(source.get("month_amount") or 0)
        if source.get("month_plan_amount_missing_rate") and abs(float(source.get("month_plan") or 0)) > 0.000001:
            row["month_plan_amount_missing_rate"] = True
            row["month_plan_amount"] = None
        elif not row.get("month_plan_amount_missing_rate"):
            row["month_plan_amount"] = float(row.get("month_plan_amount") or 0) + float(source.get("month_plan_amount") or 0)
        if source.get("cumulative_amount_missing_rate") and abs(float(source.get("cumulative_fact") or 0)) > 0.000001:
            row["cumulative_amount_missing_rate"] = True
            row["cumulative_amount"] = None
        elif not row.get("cumulative_amount_missing_rate"):
            row["cumulative_amount"] = float(row.get("cumulative_amount") or 0) + float(source.get("cumulative_amount") or 0)
        row["cumulative_pk_segments"].extend(source.get("cumulative_pk_segments") or [])
        target_days = row["day_values"]
        source_days = source.get("day_values") or []
        source_day_map = {item.get("date"): item for item in source_days if isinstance(item, dict) and item.get("date")}
        for day in days:
            date_key = day["date"]
            src = source_day_map.get(date_key)
            if not src:
                continue
            dst = target_days[date_key]
            for field in ("plan_volume", "material_plan_volume", "fact_volume", "material_fact_volume"):
                dst[field] = float(dst.get(field) or 0) + float(src.get(field) or 0)
            dst["pk_segments"].extend(src.get("pk_segments") or [])
            dst["details"].extend(src.get("details") or [])
    result = []
    for row in grouped.values():
        row["pk_label"] = _format_pk_range_excel(row.get("pk_start"), row.get("pk_end"))
        row["cumulative_pk_segments"] = _statement_merge_pk_segments(row.get("cumulative_pk_segments") or [], 5.0)
        row["cumulative_pk_ranges"] = [segment["label"] for segment in row["cumulative_pk_segments"]]
        for value in row["day_values"].values():
            value["pk_segments"] = _statement_merge_pk_segments(value.get("pk_segments") or [], 5.0)
            value["pk_ranges"] = [segment["label"] for segment in value["pk_segments"]]
        row["day_values"] = _statement_general_compact_day_values(row["day_values"])
        for field in numeric_fields:
            row[field] = round(float(row.get(field) or 0), 3)
        if not row.get("month_amount_missing_rate"):
            row["month_amount"] = round(float(row.get("month_amount") or 0), 2)
        if not row.get("month_plan_amount_missing_rate"):
            row["month_plan_amount"] = round(float(row.get("month_plan_amount") or 0), 2)
        if not row.get("cumulative_amount_missing_rate"):
            row["cumulative_amount"] = round(float(row.get("cumulative_amount") or 0), 2)
        row["month_percent"] = round(row["month_fact"] / row["month_plan"] * 100, 1) if row["month_plan"] else None
        row["cumulative_percent"] = round(row["cumulative_fact"] / row["project_volume"] * 100, 1) if row["project_volume"] else None
        result.append(row)
    result.sort(key=lambda item: (
        str(item.get("object_type_name") or item.get("object_type_code") or ""),
        str(item.get("section_code") or ""),
        float(item.get("pk_start") if item.get("pk_start") is not None else 10**18),
        str(item.get("object_name") or item.get("object_code") or ""),
        int(item.get("category_sort_order") if item.get("category_sort_order") is not None else 9999),
        str(item.get("category_label") or ""),
        str(item.get("work_type_name") or item.get("work_type_code") or ""),
    ))
    return result


def _statement_general_amount_mln(value) -> Optional[float]:
    if value is None:
        return None
    return round(float(value or 0) / 1_000_000.0, 6)


def _statement_general_group_amounts(rows: list[dict]) -> dict[str, Optional[float] | bool]:
    month_plan_amount = 0.0
    month_amount = 0.0
    cumulative_amount = 0.0
    month_plan_missing = False
    month_missing = False
    cumulative_missing = False
    for row in rows:
        if row.get("month_plan_amount_missing_rate") and abs(float(row.get("month_plan") or 0)) > 0.000001:
            month_plan_missing = True
        elif not month_plan_missing:
            month_plan_amount += float(row.get("month_plan_amount") or 0)
        if row.get("month_amount_missing_rate") and abs(float(row.get("month_fact") or 0)) > 0.000001:
            month_missing = True
        elif not month_missing:
            month_amount += float(row.get("month_amount") or 0)
        if row.get("cumulative_amount_missing_rate") and abs(float(row.get("cumulative_fact") or 0)) > 0.000001:
            cumulative_missing = True
        elif not cumulative_missing:
            cumulative_amount += float(row.get("cumulative_amount") or 0)
    return {
        "month_plan_amount_mln": None if month_plan_missing else _statement_general_amount_mln(month_plan_amount),
        "month_amount_mln": None if month_missing else _statement_general_amount_mln(month_amount),
        "cumulative_amount_mln": None if cumulative_missing else _statement_general_amount_mln(cumulative_amount),
        "month_plan_missing": month_plan_missing,
        "month_missing": month_missing,
        "cumulative_missing": cumulative_missing,
    }


def _statement_general_day_cell(day_value: dict) -> str:
    plan = float(day_value.get("plan_volume") or 0)
    fact = float(day_value.get("fact_volume") or 0)
    pk = "; ".join(day_value.get("pk_ranges") or [])
    parts = []
    if abs(plan) > 0.000001:
        parts.append(f"План: {round(plan, 3):g}")
    if abs(fact) > 0.000001:
        parts.append(f"Факт: {round(fact, 3):g}")
    if pk:
        parts.append(f"ПК: {pk}")
    return "\n".join(parts)


def _statement_general_export_append_group(ws, label: str, rows: list[dict], depth: int, fill: PatternFill, font: Font) -> None:
    amounts = _statement_general_group_amounts(rows)
    ws.append([label, "", "", "", "", amounts["month_plan_amount_mln"], "", amounts["month_amount_mln"], amounts["cumulative_amount_mln"], "", "", "", ""])
    excel_row = ws.max_row
    ws.cell(excel_row, 1).alignment = Alignment(indent=min(depth, 10), vertical="center")
    for col in range(1, ws.max_column + 1):
        cell = ws.cell(excel_row, col)
        cell.fill = fill
        cell.font = font
    if amounts["month_plan_missing"]:
        ws.cell(excel_row, 6).value = "нет расценки"
    if amounts["month_missing"]:
        ws.cell(excel_row, 8).value = "нет расценки"
    if amounts["cumulative_missing"]:
        ws.cell(excel_row, 9).value = "нет расценки"


def _statement_general_export_append_row(ws, row: dict, days: list[dict], depth: int) -> None:
    day_map = {item.get("date"): item for item in row.get("day_values") or [] if isinstance(item, dict)}
    values = [
        row.get("work_type_name") or row.get("work_type_code") or "Вид работ не указан",
        row.get("pk_label") or _format_pk_range_excel(row.get("pk_start"), row.get("pk_end")),
        row.get("unit") or "—",
        row.get("project_volume") or 0,
        row.get("month_plan") or 0,
        None if row.get("month_plan_amount_missing_rate") else _statement_general_amount_mln(row.get("month_plan_amount")),
        row.get("month_fact") or 0,
        None if row.get("month_amount_missing_rate") else _statement_general_amount_mln(row.get("month_amount")),
        None if row.get("cumulative_amount_missing_rate") else _statement_general_amount_mln(row.get("cumulative_amount")),
        row.get("month_percent"),
        row.get("cumulative_fact") or 0,
        "; ".join(row.get("cumulative_pk_ranges") or []),
        row.get("cumulative_percent"),
    ]
    values.extend(_statement_general_day_cell(day_map.get(day["date"], {})) for day in days)
    ws.append(values)
    excel_row = ws.max_row
    ws.cell(excel_row, 1).alignment = Alignment(indent=min(depth, 10), vertical="top", wrap_text=True)
    for col in range(2, ws.max_column + 1):
        ws.cell(excel_row, col).alignment = Alignment(vertical="top", wrap_text=True)
    if row.get("month_plan_amount_missing_rate"):
        ws.cell(excel_row, 6).value = "нет расценки"
    if row.get("month_amount_missing_rate"):
        ws.cell(excel_row, 8).value = "нет расценки"
    if row.get("cumulative_amount_missing_rate"):
        ws.cell(excel_row, 9).value = "нет расценки"


def _statement_general_export_build_rows(ws, rows: list[dict], days: list[dict], group_mode: str) -> None:
    section_fill = PatternFill("solid", fgColor="E5E7EB")
    type_fill = PatternFill("solid", fgColor="F3F4F6")
    object_fill = PatternFill("solid", fgColor="FAFAFA")
    group_font = Font(bold=True)

    def by_key(items: list[dict], key_fn):
        result: dict[str, list[dict]] = {}
        for item in items:
            result.setdefault(key_fn(item), []).append(item)
        return result

    def sorted_type_groups(items: list[dict]):
        return sorted(
            by_key(items, lambda r: str(r.get("object_type_code") or r.get("object_type_name") or "none")).items(),
            key=lambda entry: (
                str(entry[1][0].get("object_type_name") or entry[1][0].get("object_type_code") or ""),
                str(entry[0]),
            ),
        )

    def sorted_section_groups(items: list[dict]):
        return sorted(
            by_key(items, lambda r: str(r.get("section_code") or "none")).items(),
            key=lambda entry: _statement_section_sort_key(entry[1][0] if entry[1] else {"section_code": entry[0]}),
        )

    if group_mode == "objectType":
        for _type_key, type_rows in sorted_type_groups(rows):
            _statement_general_export_append_group(ws, type_rows[0].get("object_type_name") or type_rows[0].get("object_type_code") or "Без типа объекта", type_rows, 0, section_fill, group_font)
            for _section_key, section_rows in sorted_section_groups(type_rows):
                _statement_general_export_append_group(ws, section_rows[0].get("section_name") or section_rows[0].get("section_code") or "Без участка", section_rows, 1, type_fill, group_font)
                for _object_key, object_rows in by_key(section_rows, _statement_general_row_object_key).items():
                    _statement_general_export_append_group(ws, object_rows[0].get("object_name") or object_rows[0].get("object_code") or "Объект не указан", object_rows, 2, object_fill, group_font)
                    for row in object_rows:
                        _statement_general_export_append_row(ws, row, days, 3)
        return

    for _section_key, section_rows in sorted_section_groups(rows):
        _statement_general_export_append_group(ws, section_rows[0].get("section_name") or section_rows[0].get("section_code") or "Без участка", section_rows, 0, section_fill, group_font)
        for _type_key, type_rows in sorted_type_groups(section_rows):
            _statement_general_export_append_group(ws, type_rows[0].get("object_type_name") or type_rows[0].get("object_type_code") or "Без типа объекта", type_rows, 1, type_fill, group_font)
            for _object_key, object_rows in by_key(type_rows, _statement_general_row_object_key).items():
                _statement_general_export_append_group(ws, object_rows[0].get("object_name") or object_rows[0].get("object_code") or "Объект не указан", object_rows, 2, object_fill, group_font)
                for row in object_rows:
                    _statement_general_export_append_row(ws, row, days, 3)


def _statement_general_workbook_export_build_workbook(
    *,
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    group_mode: str = "section",
    hide_zero_works: bool = False,
    hide_zero_objects: bool = False,
    only_with_plan: bool = False,
    only_missing_rate: bool = False,
    actual_section_binding: bool = False,
    _user=None,
) -> tuple[Workbook, dict]:
    if group_mode not in {"section", "objectType"}:
        raise HTTPException(400, "group_mode must be section or objectType")
    payload = statements_general_workbook(
        month=month,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        include_metadata=False,
        actual_section_binding=actual_section_binding,
        allow_stale=False,
        use_file_response=False,
        _user=_user,
    )
    days = payload.get("days") or []
    rows = _statement_general_filter_visible_rows(
        payload.get("rows") or [],
        hide_zero_works=hide_zero_works,
        hide_zero_objects=hide_zero_objects,
        only_with_plan=only_with_plan,
        only_missing_rate=only_missing_rate,
    )
    export_rows = _statement_general_export_group_rows(rows, days)
    wb = Workbook()
    ws = wb.active
    ws.title = "Ведомость"
    headers = [
        "Работа", "ПК", "Ед.", "Проект", "План месяца", "Сумма плана месяца, млн руб", "Факт месяца",
        "Сумма месяца, млн руб", "Сумма накоп., млн руб", "% мес.",
        "Факт накоп.", "ПК накоп.", "% накоп.",
    ] + [day.get("label") or day.get("date") for day in days]
    ws.append(headers)
    header_fill = PatternFill("solid", fgColor="D9E2F3")
    thin = Side(style="thin", color="D9D9D9")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)
    for cell in ws[1]:
        cell.font = Font(bold=True)
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    _statement_general_export_build_rows(ws, export_rows, days, group_mode)
    ws.freeze_panes = "A2"
    widths = [46, 22, 10, 14, 14, 20, 14, 18, 18, 10, 14, 26, 10]
    for idx, width in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(idx)].width = width
    for idx in range(len(widths) + 1, len(headers) + 1):
        ws.column_dimensions[get_column_letter(idx)].width = 18
    for row in ws.iter_rows():
        for cell in row:
            cell.border = border
            if isinstance(cell.value, (int, float)):
                cell.number_format = '#,##0.000'
    ws.auto_filter.ref = ws.dimensions
    return wb, payload


def _statement_general_workbook_export_content(
    *,
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    group_mode: str = "section",
    hide_zero_works: bool = False,
    hide_zero_objects: bool = False,
    only_with_plan: bool = False,
    only_missing_rate: bool = False,
    actual_section_binding: bool = False,
    _user=None,
) -> tuple[bytes, str, str, dict]:
    wb, payload = _statement_general_workbook_export_build_workbook(
        month=month,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        group_mode=group_mode,
        hide_zero_works=hide_zero_works,
        hide_zero_objects=hide_zero_objects,
        only_with_plan=only_with_plan,
        only_missing_rate=only_missing_rate,
        actual_section_binding=actual_section_binding,
        _user=_user,
    )
    bio = BytesIO()
    wb.save(bio)
    month_key = str(payload.get("month") or month or "month")
    return bio.getvalue(), f"Vedomost_{month_key}.xlsx", f"Ведомость {month_key}.xlsx", payload


def _statement_general_workbook_export_fingerprint(
    *,
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    group_mode: str = "section",
    hide_zero_works: bool = False,
    hide_zero_objects: bool = False,
    only_with_plan: bool = False,
    only_missing_rate: bool = False,
    actual_section_binding: bool = False,
) -> tuple[str, str, date_cls, date_cls]:
    month_key, month_start, month_end = _statement_general_month_bounds(month)
    payload = {
        "cache_version": STATEMENTS_GENERAL_WORKBOOK_CACHE_VERSION,
        "export_version": 6,
        "month": month_key,
        "section": section or "",
        "object_type": object_type or "",
        "object_id": object_id or "",
        "q": (q or "").strip(),
        "group_mode": group_mode,
        "hide_zero_works": bool(hide_zero_works),
        "hide_zero_objects": bool(hide_zero_objects),
        "only_with_plan": bool(only_with_plan),
        "only_missing_rate": bool(only_missing_rate),
        "actual_section_binding": bool(actual_section_binding),
        "source_sha256": _sha256_file(Path(__file__).resolve()),
        "db": _xlsx_report_db_fingerprint(),
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest(), month_key, month_start, month_end


def _statement_general_workbook_export_job_info(
    *,
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    group_mode: str = "section",
    hide_zero_works: bool = False,
    hide_zero_objects: bool = False,
    only_with_plan: bool = False,
    only_missing_rate: bool = False,
    actual_section_binding: bool = False,
) -> dict:
    fingerprint, month_key, month_start, month_end = _statement_general_workbook_export_fingerprint(
        month=month,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        group_mode=group_mode,
        hide_zero_works=hide_zero_works,
        hide_zero_objects=hide_zero_objects,
        only_with_plan=only_with_plan,
        only_missing_rate=only_missing_rate,
        actual_section_binding=actual_section_binding,
    )
    report_key = "statements_general_workbook"
    artifact, meta_path, lock_path = _xlsx_cache_paths(report_key, month_start, month_end, fingerprint)
    job_payload = {
        "report_key": report_key,
        "date_from": month_start.isoformat(),
        "date_to": month_end.isoformat(),
        "month": month_key,
        "section": section or "",
        "object_type": object_type or "",
        "object_id": object_id or "",
        "q": (q or "").strip(),
        "group_mode": group_mode,
        "hide_zero_works": bool(hide_zero_works),
        "hide_zero_objects": bool(hide_zero_objects),
        "only_with_plan": bool(only_with_plan),
        "only_missing_rate": bool(only_missing_rate),
        "actual_section_binding": bool(actual_section_binding),
        "filename_ascii": f"Vedomost_{month_key}.xlsx",
        "filename_utf8": f"Ведомость {month_key}.xlsx",
        "fingerprint": fingerprint,
        "artifact": str(artifact),
        "meta_path": str(meta_path),
        "lock_path": str(lock_path),
        "media_type": XLSX_MEDIA_TYPE,
    }
    job_id_raw = json.dumps(job_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    job_payload["job_id"] = hashlib.sha256(job_id_raw.encode("utf-8")).hexdigest()[:32]
    return job_payload


def _ensure_cached_statement_general_workbook_artifact(
    *,
    report_key: str,
    month: str,
    section: Optional[str],
    object_type: Optional[str],
    object_id: Optional[str],
    q: Optional[str],
    group_mode: str,
    hide_zero_works: bool,
    hide_zero_objects: bool,
    only_with_plan: bool,
    only_missing_rate: bool,
    actual_section_binding: bool,
    d_from: date_cls,
    d_to: date_cls,
    fingerprint: str,
    artifact: Path,
    meta_path: Path,
    lock_path: Path,
) -> Path:
    if not REPORT_XLSX_CACHE_ENABLED:
        raise HTTPException(503, "XLSX cache is disabled; background export requires cache")
    if _cached_xlsx_ready(artifact, meta_path, fingerprint):
        return artifact

    artifact.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+") as lock_fh:
        fcntl.flock(lock_fh, fcntl.LOCK_EX)
        try:
            if _cached_xlsx_ready(artifact, meta_path, fingerprint):
                return artifact
            content, _filename_ascii, _filename_utf8, _payload = _statement_general_workbook_export_content(
                month=month,
                section=section or None,
                object_type=object_type or None,
                object_id=object_id or None,
                q=q or None,
                group_mode=group_mode,
                hide_zero_works=hide_zero_works,
                hide_zero_objects=hide_zero_objects,
                only_with_plan=only_with_plan,
                only_missing_rate=only_missing_rate,
                actual_section_binding=actual_section_binding,
                _user=None,
            )
            tmp_cache = artifact.with_suffix(artifact.suffix + ".tmp")
            tmp_cache.write_bytes(content)
            tmp_cache.replace(artifact)
            _write_cached_xlsx_metadata(
                meta_path,
                report_key=report_key,
                d_from=d_from,
                d_to=d_to,
                fingerprint=fingerprint,
                artifact_path=artifact,
                stdout="generated via statements_general_workbook export pipeline",
            )
            return artifact
        finally:
            fcntl.flock(lock_fh, fcntl.LOCK_UN)


