@router.post("/statements/general-workbook/export-jobs")
def statements_general_workbook_export_job(
    month: Optional[str] = None,
    section: Optional[str] = None,
    object_type: Optional[str] = None,
    object_id: Optional[str] = None,
    q: Optional[str] = None,
    group_mode: str = "section",
    hide_zero_works: bool = False,
    hide_zero_objects: bool = False,
    only_with_plan: bool = False,
    only_missing_rate: bool = False,
    actual_section_binding: bool = False,
    _user=Depends(current_user),
):
    if group_mode not in {"section", "objectType"}:
        raise HTTPException(400, "group_mode must be section or objectType")
    info = _statement_general_workbook_export_job_info(
        month=month,
        section=section,
        object_type=object_type,
        object_id=object_id,
        q=q,
        group_mode=group_mode,
        hide_zero_works=hide_zero_works,
        hide_zero_objects=hide_zero_objects,
        only_with_plan=only_with_plan,
        only_missing_rate=only_missing_rate,
        actual_section_binding=actual_section_binding,
    )
    job_id = str(info["job_id"])
    artifact = Path(str(info["artifact"]))
    meta_path = Path(str(info["meta_path"]))
    fingerprint = str(info["fingerprint"])
    if _cached_xlsx_ready(artifact, meta_path, fingerprint):
        job = {
            **info,
            "status": "ready",
            "message": "Файл найден в кеше",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "finished_at": datetime.now(timezone.utc).isoformat(),
        }
        with XLSX_EXPORT_JOBS_LOCK:
            XLSX_EXPORT_JOBS[job_id] = job
        return _xlsx_export_job_response(job)

    should_start = False
    with XLSX_EXPORT_JOBS_LOCK:
        existing = XLSX_EXPORT_JOBS.get(job_id)
        if existing and existing.get("status") in {"queued", "running"}:
            return _xlsx_export_job_response(existing)
        if existing and existing.get("status") == "ready" and _cached_xlsx_ready(artifact, meta_path, fingerprint):
            return _xlsx_export_job_response(existing)
        job = {
            **info,
            "status": "queued",
            "message": "Файл поставлен в очередь генерации",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "error": None,
        }
        XLSX_EXPORT_JOBS[job_id] = job
        should_start = True
    if should_start:
        thread = threading.Thread(target=_run_xlsx_export_job, args=(job_id,), daemon=True)
        thread.start()
    return _xlsx_export_job_response(job)


@router.post("/statements/general-workbook/month-plan")
def statements_general_workbook_month_plan(body: StatementGeneralWorkbookMonthPlanBody, _user=Depends(current_user)):
    if not _statement_table_exists("planned_work_items"):
        raise HTTPException(409, "planned_work_items table is not installed; apply migration first")
    month_key, month_start, month_end = _statement_general_month_bounds(body.month)
    signed_pile_plan = _statement_signed_pile_plan_for_period(month_start, month_end)
    if signed_pile_plan:
        work_type = query_one("SELECT code FROM work_types WHERE id = %s::uuid", (body.work_type_id,)) or {}
        if str(work_type.get("code") or "").upper() in STATEMENT_SIGNED_PILE_PLAN_WORK_TYPE_CODES:
            raise HTTPException(
                409,
                "План этой свайной работы за выбранный месяц зафиксирован подписанной производственной программой",
            )
    volume = _statement_numeric(body.planned_volume, "planned_volume")
    if volume is None or volume < 0:
        raise HTTPException(400, "planned_volume must be non-negative")
    pk_start = _statement_numeric(body.pk_start, "pk_start") if body.pk_start is not None else None
    pk_end = _statement_numeric(body.pk_end, "pk_end") if body.pk_end is not None else None
    if pk_start is not None and pk_end is not None and pk_start > pk_end:
        raise HTTPException(400, "pk_end must be greater than or equal to pk_start")
    section_code = _merge_section(body.section_code) or body.section_code
    pk_raw_text = body.pk_raw_text
    days = _statement_general_day_response(month_start, month_end)
    day_count = max(1, len(days))
    day_value = volume / day_count
    unit = (body.unit or "").strip() or None
    conn = get_conn()
    inserted = 0
    assigned_section_id = None
    try:
        with conn:
            with conn.cursor() as cur:
                if body.actual_section_binding:
                    if not _statement_cur_column_exists(cur, "planned_work_items", "assigned_section_id"):
                        raise HTTPException(409, "Apply the Statements actual section binding migration first")
                    if section_code:
                        cur.execute(
                            """
                            SELECT id
                            FROM construction_sections
                            WHERE code = %s
                              AND is_active IS NOT FALSE
                            LIMIT 1
                            """,
                            (section_code,),
                        )
                        assigned_section_row = cur.fetchone()
                        if not assigned_section_row:
                            raise HTTPException(400, "section_code not found")
                        assigned_section_id = assigned_section_row[0]
                if section_code and not body.actual_section_binding:
                    cur.execute(
                        _statement_scope_cte()
                        + """
                        SELECT pk_start, pk_end
                        FROM object_sections
                        WHERE id = %s::uuid
                          AND section_code = %s
                        ORDER BY section_sort_order NULLS LAST, pk_start NULLS LAST, pk_end NULLS LAST
                        LIMIT 1
                        """,
                        (body.object_id, section_code),
                    )
                    section_row = cur.fetchone()
                    if section_row:
                        pk_start, pk_end, clipped = _statement_clip_manual_plan_range_to_section(
                            pk_start,
                            pk_end,
                            section_row[0],
                            section_row[1],
                        )
                        if clipped:
                            pk_raw_text = None
                cur.execute(
                    """
                    DELETE FROM planned_work_items
                    WHERE object_id = %s::uuid
                      AND work_type_id = %s::uuid
                      AND COALESCE(unit, '') = COALESCE(NULLIF(%s, ''), unit, '')
                      AND period_start >= %s::date
                      AND period_end <= %s::date
                      AND source_reference = 'manual:statements_general_month_plan'
                      AND (%s::boolean IS FALSE OR assigned_section_id IS NOT DISTINCT FROM %s::uuid)
                      AND (
                        %s::numeric IS NULL
                        OR %s::numeric IS NULL
                        OR pk_start IS NULL
                        OR pk_end IS NULL
                        OR (pk_start IS NOT DISTINCT FROM %s::numeric AND pk_end IS NOT DISTINCT FROM %s::numeric)
                        OR (
                          LEAST(pk_start, pk_end) < GREATEST(%s::numeric, %s::numeric)
                          AND GREATEST(pk_start, pk_end) > LEAST(%s::numeric, %s::numeric)
                        )
                      )
                    """,
                    (
                        body.object_id,
                        body.work_type_id,
                        unit,
                        month_start,
                        month_end,
                        body.actual_section_binding,
                        assigned_section_id,
                        pk_start,
                        pk_end,
                        pk_start,
                        pk_end,
                        pk_start,
                        pk_end,
                        pk_start,
                        pk_end,
                    ),
                )
                deleted = cur.rowcount
                for day in days:
                    day_date = date_cls.fromisoformat(day["date"])
                    cur.execute(
                        """
                        INSERT INTO planned_work_items (
                          object_id, work_type_id, assigned_section_id, unit, planned_volume,
                          period_start, period_end, plan_type,
                          pk_start, pk_end, pk_raw_text, comment, source_reference
                        )
                        SELECT %s::uuid, wt.id, %s::uuid, COALESCE(NULLIF(%s, ''), wt.default_unit, 'шт'), %s,
                               %s, %s, 'manual_period', %s, %s, %s, %s, 'manual:statements_general_month_plan'
                        FROM work_types wt
                        WHERE wt.id = %s::uuid
                        """,
                        (body.object_id, assigned_section_id, unit, day_value, day_date, day_date, pk_start, pk_end, pk_raw_text, body.comment, body.work_type_id),
                    )
                    inserted += cur.rowcount
        return {
            "ok": True,
            "month": month_key,
            "deleted": deleted,
            "inserted": inserted,
            "daily_volume": round(day_value, 6),
            "actual_section_binding": bool(body.actual_section_binding),
            "assigned_section_code": section_code if assigned_section_id else None,
        }
    finally:
        conn.close()


def _statement_upsert_object_rate(
    cur,
    *,
    object_id: str,
    work_type_id: str,
    region_code: str,
    rate_value,
    unit: Optional[str],
    pile_length_m,
    changed_by: Optional[str],
) -> None:
    if region_code not in WORK_TYPE_RATE_REGIONS:
        raise HTTPException(400, "region_code must be novgorod or tver")
    rate = _statement_numeric(rate_value, f"rate_{region_code}") if rate_value is not None else None
    if rate is not None and rate < 0:
        raise HTTPException(400, f"rate_{region_code} must be non-negative")
    pile_length = _statement_numeric(pile_length_m, "pile_length_m") if pile_length_m is not None else None
    if pile_length is not None and pile_length <= 0:
        raise HTTPException(400, "pile_length_m must be positive")
    if rate is None:
        if pile_length is None:
            cur.execute(
                """
                DELETE FROM statement_object_unit_rates
                WHERE object_id = %s::uuid
                  AND work_type_id = %s::uuid
                  AND region_code = %s
                  AND pile_length_m IS NULL
                """,
                (object_id, work_type_id, region_code),
            )
        else:
            cur.execute(
                """
                DELETE FROM statement_object_unit_rates
                WHERE object_id = %s::uuid
                  AND work_type_id = %s::uuid
                  AND region_code = %s
                  AND pile_length_m = %s
                """,
                (object_id, work_type_id, region_code, pile_length),
            )
        return
    if pile_length is None:
        cur.execute(
            """
            INSERT INTO statement_object_unit_rates (
              object_id, work_type_id, region_code, region_label,
              rate, unit, pile_length_m, updated_at, updated_by
            )
            VALUES (%s::uuid, %s::uuid, %s, %s, %s, %s, NULL, now(), %s)
            ON CONFLICT (object_id, work_type_id, region_code) WHERE pile_length_m IS NULL DO UPDATE
            SET rate = EXCLUDED.rate,
                unit = EXCLUDED.unit,
                region_label = EXCLUDED.region_label,
                updated_at = now(),
                updated_by = EXCLUDED.updated_by
            """,
            (object_id, work_type_id, region_code, WORK_TYPE_RATE_REGIONS[region_code], rate, unit, changed_by or "dashboard"),
        )
        return
    cur.execute(
        """
        INSERT INTO statement_object_unit_rates (
          object_id, work_type_id, region_code, region_label,
          rate, unit, pile_length_m, updated_at, updated_by
        )
        VALUES (%s::uuid, %s::uuid, %s, %s, %s, %s, %s, now(), %s)
        ON CONFLICT (object_id, work_type_id, region_code, pile_length_m) WHERE pile_length_m IS NOT NULL DO UPDATE
        SET rate = EXCLUDED.rate,
            unit = EXCLUDED.unit,
            region_label = EXCLUDED.region_label,
            updated_at = now(),
            updated_by = EXCLUDED.updated_by
        """,
        (object_id, work_type_id, region_code, WORK_TYPE_RATE_REGIONS[region_code], rate, unit, pile_length, changed_by or "dashboard"),
    )


@router.post("/statements/object-unit-rates")
def statements_object_unit_rates(body: StatementObjectUnitRatesBody, _user=Depends(require_statements_project_writer)):
    unit = (body.unit or "").strip() or None
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                _ensure_statement_object_unit_rates_table(cur)
                cur.execute(
                    """
                    SELECT o.id::text, wt.id::text
                    FROM objects o
                    CROSS JOIN work_types wt
                    WHERE o.id = %s::uuid
                      AND wt.id = %s::uuid
                    """,
                    (body.object_id, body.work_type_id),
                )
                if not cur.fetchone():
                    raise HTTPException(404, "object_id or work_type_id not found")
                changed_by = getattr(_user, "email", None) or getattr(_user, "username", None) or "dashboard"
                _statement_upsert_object_rate(
                    cur,
                    object_id=body.object_id,
                    work_type_id=body.work_type_id,
                    region_code="novgorod",
                    rate_value=body.rate_novgorod,
                    unit=unit,
                    pile_length_m=body.pile_length_m,
                    changed_by=changed_by,
                )
                _statement_upsert_object_rate(
                    cur,
                    object_id=body.object_id,
                    work_type_id=body.work_type_id,
                    region_code="tver",
                    rate_value=body.rate_tver,
                    unit=unit,
                    pile_length_m=body.pile_length_m,
                    changed_by=changed_by,
                )
        _invalidate_dashboard_response_cache("statements_object_unit_rates")
        return {"ok": True}
    finally:
        conn.close()


