def _statement_required_text(value: Optional[str], field: str, max_len: int = 255) -> str:
    text = (value or "").strip()
    if not text:
        raise HTTPException(400, f"{field} is required")
    return text[:max_len]


def _statement_code(value: Optional[str], field: str, max_len: int = 100) -> str:
    text = (value or "").strip().upper()
    text = re.sub(r"[^0-9A-ZА-Я_]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    if not text:
        raise HTTPException(400, f"{field} is required")
    return text[:max_len]


STATEMENT_OPTIONAL_OBJECT_PK_CODES = {"BORROW_PIT", "STOCKPILE", "TEMP_DUMP", "OTHER"}
STATEMENT_ROUTE_OBJECT_PK_CODES = {
    "MAIN_TRACK",
    "TEMP_ROAD",
    "TEMP_ROAD_PIPE",
    "ISSO_ACCESS",
    "PILE_FIELD",
    "PILE_DRIVING_PAD",
    "PIPE",
    "BRIDGE",
    "OVERPASS",
    "TECH_ROAD",
    "SERVICE_ROAD",
    "STATION_TRACK",
    "INTERSECTION_PROP",
    "INTERSECTION_FIN",
}


def _statement_object_boundary_kind(object_type_code: Optional[str]) -> str:
    code = (object_type_code or "").strip().upper()
    if code in {"TEMP_ROAD", "SERVICE_ROAD", "TEMP_ROAD_PIPE"}:
        return "temp_roads"
    if code in {"PILE_FIELD", "PILE_DRIVING_PAD", "ISSO_ACCESS", "PIPE", "BRIDGE", "OVERPASS", "TECH_ROAD"}:
        return "piles_pipes"
    return "main"


def _statement_row_scope_lateral_sql(pk_start_expr: str, pk_end_expr: str, scope_alias: str = "so") -> str:
    return f"""
          CROSS JOIN LATERAL (
            SELECT {pk_start_expr} AS explicit_pk_start,
                   {pk_end_expr} AS explicit_pk_end
          ) row_pk_source
          CROSS JOIN LATERAL (
            SELECT LEAST(row_pk_source.explicit_pk_start, row_pk_source.explicit_pk_end) AS explicit_start,
                   GREATEST(row_pk_source.explicit_pk_start, row_pk_source.explicit_pk_end) AS explicit_end,
                   LEAST({scope_alias}.pk_start, {scope_alias}.pk_end) AS section_start,
                   GREATEST({scope_alias}.pk_start, {scope_alias}.pk_end) AS section_end,
                   LEAST({scope_alias}.object_pk_start, {scope_alias}.object_pk_end) AS object_start,
                   GREATEST({scope_alias}.object_pk_start, {scope_alias}.object_pk_end) AS object_end
          ) row_clip_bounds
          CROSS JOIN LATERAL (
            SELECT CASE
                     WHEN row_clip_bounds.explicit_start IS NOT NULL
                      AND row_clip_bounds.explicit_end IS NOT NULL
                      AND row_clip_bounds.section_start IS NOT NULL
                      AND row_clip_bounds.section_end IS NOT NULL
                       THEN GREATEST(row_clip_bounds.explicit_start, row_clip_bounds.section_start)
                     ELSE COALESCE(row_pk_source.explicit_pk_start, {scope_alias}.pk_start)
                   END AS row_pk_start,
                   CASE
                     WHEN row_clip_bounds.explicit_start IS NOT NULL
                      AND row_clip_bounds.explicit_end IS NOT NULL
                      AND row_clip_bounds.section_start IS NOT NULL
                      AND row_clip_bounds.section_end IS NOT NULL
                       THEN LEAST(row_clip_bounds.explicit_end, row_clip_bounds.section_end)
                     ELSE COALESCE(row_pk_source.explicit_pk_end, {scope_alias}.pk_end)
                   END AS row_pk_end,
                   CASE
                     WHEN row_clip_bounds.explicit_start IS NOT NULL
                      AND row_clip_bounds.explicit_end IS NOT NULL
                      AND row_clip_bounds.section_start IS NOT NULL
                      AND row_clip_bounds.section_end IS NOT NULL
                       THEN CASE
                         WHEN ABS(row_clip_bounds.explicit_end - row_clip_bounds.explicit_start) < 0.001
                           THEN row_clip_bounds.explicit_start >= row_clip_bounds.section_start
                            AND row_clip_bounds.explicit_start < row_clip_bounds.section_end
                         ELSE LEAST(row_clip_bounds.explicit_end, row_clip_bounds.section_end)
                              > GREATEST(row_clip_bounds.explicit_start, row_clip_bounds.section_start)
                       END
                     ELSE true
                   END AS row_pk_has_overlap,
                   CASE
                     WHEN row_clip_bounds.explicit_start IS NOT NULL
                      AND row_clip_bounds.explicit_end IS NOT NULL
                      AND row_clip_bounds.section_start IS NOT NULL
                      AND row_clip_bounds.section_end IS NOT NULL
                       THEN ABS(GREATEST(row_clip_bounds.explicit_start, row_clip_bounds.section_start) - row_clip_bounds.explicit_start) >= 0.001
                         OR ABS(LEAST(row_clip_bounds.explicit_end, row_clip_bounds.section_end) - row_clip_bounds.explicit_end) >= 0.001
                     ELSE false
                   END AS row_pk_clipped,
                   CASE
                     WHEN row_clip_bounds.explicit_start IS NOT NULL
                      AND row_clip_bounds.explicit_end IS NOT NULL
                      AND row_clip_bounds.section_start IS NOT NULL
                      AND row_clip_bounds.section_end IS NOT NULL
                      AND ABS(row_clip_bounds.explicit_end - row_clip_bounds.explicit_start) >= 0.001
                       THEN GREATEST(
                         0,
                         LEAST(row_clip_bounds.explicit_end, row_clip_bounds.section_end)
                         - GREATEST(row_clip_bounds.explicit_start, row_clip_bounds.section_start)
                       ) / NULLIF(ABS(row_clip_bounds.explicit_end - row_clip_bounds.explicit_start), 0)
                     WHEN row_clip_bounds.section_start IS NOT NULL
                      AND row_clip_bounds.section_end IS NOT NULL
                      AND row_clip_bounds.object_start IS NOT NULL
                      AND row_clip_bounds.object_end IS NOT NULL
                      AND ABS(row_clip_bounds.object_end - row_clip_bounds.object_start) > 0.001
                      AND ABS(row_clip_bounds.section_end - row_clip_bounds.section_start) > 0.001
                      AND ABS(row_clip_bounds.section_end - row_clip_bounds.section_start)
                          < ABS(row_clip_bounds.object_end - row_clip_bounds.object_start)
                       THEN ABS(row_clip_bounds.section_end - row_clip_bounds.section_start)
                         / NULLIF(ABS(row_clip_bounds.object_end - row_clip_bounds.object_start), 0)
                     ELSE 1
                   END AS row_pk_factor
          ) row_scope
    """


def _statement_plan_row_scope_lateral_sql(
    plan_alias: str = "pwi",
    scope_alias: str = "so",
    source_pile_field_alias: Optional[str] = None,
) -> str:
    pk_start_expr = f"{plan_alias}.pk_start"
    pk_end_expr = f"{plan_alias}.pk_end"
    if source_pile_field_alias:
        pk_start_expr = f"COALESCE({plan_alias}.pk_start, {source_pile_field_alias}.pk_start)"
        pk_end_expr = f"COALESCE({plan_alias}.pk_end, {source_pile_field_alias}.pk_end)"
    return _statement_row_scope_lateral_sql(pk_start_expr, pk_end_expr, scope_alias)


def _statement_object_type_requires_pk(object_type_code: Optional[str], is_linear: Optional[bool] = None) -> bool:
    code = (object_type_code or "").strip().upper()
    if code in STATEMENT_OPTIONAL_OBJECT_PK_CODES:
        return False
    if code in STATEMENT_ROUTE_OBJECT_PK_CODES:
        return True
    return bool(is_linear)


def _statement_object_response_from_cursor(cur, object_id: str) -> dict:
    cur.execute(
        _statement_scope_cte()
        + """
        SELECT id::text,
               object_code,
               object_name,
               object_type_code,
               object_type_name,
               section_code,
               section_name,
               pk_start,
               pk_end
        FROM object_sections
        WHERE id = %s::uuid
        LIMIT 1
        """,
        (object_id,),
    )
    row = cur.fetchone()
    if not row:
        raise HTTPException(404, "object not found")
    return {
        "id": row[0],
        "object_code": row[1],
        "object_name": row[2],
        "object_type_code": row[3],
        "object_type_name": row[4],
        "section_code": _merge_section(row[5]) or row[5],
        "section_name": row[6],
        "pk_start": float(row[7]) if row[7] is not None else None,
        "pk_end": float(row[8]) if row[8] is not None else None,
    }


@router.post("/statements/objects")
def statements_create_object(body: StatementObjectCreateBody, _user=Depends(require_statements_project_writer)):
    code = _statement_code(body.object_code, "object_code")
    name = _statement_required_text(body.object_name, "object_name")
    object_type_code = _statement_code(body.object_type_code, "object_type_code")
    section_code = _statement_code(body.section_code, "section_code") if body.section_code else None
    boundary_kind = _statement_object_boundary_kind(object_type_code)
    pk_start = _statement_numeric(body.pk_start, "pk_start") if body.pk_start is not None else None
    pk_end = _statement_numeric(body.pk_end, "pk_end") if body.pk_end is not None else None
    if pk_start is not None and pk_end is None:
        pk_end = pk_start
    if pk_end is not None and pk_start is None:
        pk_start = pk_end
    if pk_start is not None and pk_end is not None and pk_start > pk_end:
        raise HTTPException(400, "pk_end must be greater than or equal to pk_start")
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT id, code, is_linear
                    FROM object_types
                    WHERE code = %s
                      AND COALESCE(is_active, true) IS TRUE
                    LIMIT 1
                    """,
                    (object_type_code,),
                )
                type_row = cur.fetchone()
                if not type_row:
                    raise HTTPException(400, f"object_type_code not found: {object_type_code}")
                object_requires_pk = _statement_object_type_requires_pk(object_type_code, type_row[2] if len(type_row) > 2 else None)
                section_row = None
                if section_code:
                    section_codes = _expand_sections(section_code) or [section_code]
                    cur.execute(
                        """
                        SELECT cs.id::text, cs.code, cs.name, csv.pk_start, csv.pk_end, csv.pk_raw_text
                        FROM construction_sections cs
                        JOIN construction_section_versions csv
                          ON csv.section_id = cs.id
                         AND csv.is_current = true
                         AND csv.boundary_kind = %s
                        WHERE cs.code = ANY(%s)
                          AND COALESCE(cs.is_active, true) IS TRUE
                        ORDER BY CASE WHEN cs.code = %s THEN 0 ELSE 1 END,
                                 cs.sort_order NULLS LAST, cs.code, csv.pk_start
                        LIMIT 1
                        """,
                        (boundary_kind, section_codes, section_code),
                    )
                    section_row = cur.fetchone()
                    if not section_row:
                        raise HTTPException(400, f"section_code not found for {boundary_kind}: {section_code}")
                    section_start = float(section_row[3]) if section_row[3] is not None else None
                    section_end = float(section_row[4]) if section_row[4] is not None else None
                    if pk_start is None and pk_end is None and object_requires_pk and section_start is not None and section_end is not None:
                        pk_start = min(section_start, section_end)
                        pk_end = max(section_start, section_end)
                    elif pk_start is not None and pk_end is not None and section_start is not None and section_end is not None:
                        center = (pk_start + pk_end) / 2.0
                        lo = min(section_start, section_end)
                        hi = max(section_start, section_end)
                        if center < lo or center >= hi:
                            raise HTTPException(400, f"object PK range is outside section {section_code}")
                if object_requires_pk and (pk_start is None or pk_end is None):
                    raise HTTPException(400, f"object type {object_type_code} requires route PK or section")
                cur.execute(
                    """
                    INSERT INTO objects (object_code, name, object_type_id, is_active, comment, review_tag)
                    VALUES (%s, %s, %s, true, %s, %s)
                    ON CONFLICT (object_code) DO UPDATE
                    SET name = EXCLUDED.name,
                        object_type_id = EXCLUDED.object_type_id,
                        is_active = true,
                        comment = COALESCE(EXCLUDED.comment, objects.comment)
                    RETURNING id::text, object_code, name
                    """,
                    (code, name, type_row[0], body.comment, "pending_admin_review"),
                )
                object_row = cur.fetchone()
                if pk_start is not None and pk_end is not None:
                    raw_pk = (body.pk_raw_text or "").strip() or (section_row[5] if section_row else None)
                    cur.execute(
                        """
                        SELECT 1 FROM object_segments
                        WHERE object_id = %s::uuid AND pk_start = %s AND pk_end = %s
                        LIMIT 1
                        """,
                        (object_row[0], pk_start, pk_end),
                    )
                    if not cur.fetchone():
                        cur.execute(
                            """
                            INSERT INTO object_segments (object_id, pk_start, pk_end, pk_raw_text, comment, review_tag)
                            VALUES (%s::uuid, %s, %s, %s, %s, %s)
                            """,
                            (object_row[0], pk_start, pk_end, raw_pk, body.comment or "created from statements", "pending_admin_review"),
                        )
                return {
                    "id": object_row[0],
                    "object_code": object_row[1],
                    "object_name": object_row[2],
                    "object_type_code": object_type_code,
                    "object_type_name": None,
                    "section_code": (_merge_section(section_row[1]) or section_row[1]) if section_row else None,
                    "section_name": section_row[2] if section_row else None,
                    "pk_start": pk_start,
                    "pk_end": pk_end,
                }
    finally:
        conn.close()


@router.patch("/statements/objects/{object_id}/picketage")
def statements_update_object_picketage(object_id: str, body: StatementObjectPicketageBody, _user=Depends(require_statements_project_writer)):
    raw_pk_start = getattr(body, "pk_start", None)
    raw_pk_end = getattr(body, "pk_end", None)
    pk_start = _statement_numeric(raw_pk_start, "pk_start") if raw_pk_start is not None else None
    pk_end = _statement_numeric(raw_pk_end, "pk_end") if raw_pk_end is not None else None
    if pk_start is not None and pk_end is None:
        pk_end = pk_start
    if pk_end is not None and pk_start is None:
        pk_start = pk_end
    if pk_start is not None and pk_end is not None and pk_start > pk_end:
        raise HTTPException(400, "pk_end must be greater than or equal to pk_start")

    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT o.id::text, o.object_code, o.name, ot.code, ot.name, ot.is_linear
                    FROM objects o
                    JOIN object_types ot ON ot.id = o.object_type_id
                    WHERE o.id = %s::uuid
                      AND COALESCE(o.is_active, true) IS TRUE
                    LIMIT 1
                    """,
                    (object_id,),
                )
                object_row = cur.fetchone()
                if not object_row:
                    raise HTTPException(404, "object not found")
                object_type_code = object_row[3]
                object_requires_pk = _statement_object_type_requires_pk(object_type_code, object_row[5] if len(object_row) > 5 else None)

                clearing = bool(getattr(body, "clear", False)) or (pk_start is None and pk_end is None)
                if clearing and object_requires_pk:
                    raise HTTPException(400, f"object type {object_type_code} requires route PK")

                section_row = None
                section_code = _statement_code(getattr(body, "section_code", None), "section_code") if getattr(body, "section_code", None) else None
                if section_code and pk_start is not None and pk_end is not None:
                    section_codes = _expand_sections(section_code) or [section_code]
                    boundary_kind = _statement_object_boundary_kind(object_type_code)
                    cur.execute(
                        """
                        SELECT cs.id::text, cs.code, cs.name, csv.pk_start, csv.pk_end, csv.pk_raw_text
                        FROM construction_sections cs
                        JOIN construction_section_versions csv
                          ON csv.section_id = cs.id
                         AND csv.is_current = true
                         AND csv.boundary_kind = %s
                        WHERE cs.code = ANY(%s)
                          AND COALESCE(cs.is_active, true) IS TRUE
                        ORDER BY CASE WHEN cs.code = %s THEN 0 ELSE 1 END,
                                 cs.sort_order NULLS LAST, cs.code, csv.pk_start
                        LIMIT 1
                        """,
                        (boundary_kind, section_codes, section_code),
                    )
                    section_row = cur.fetchone()
                    if not section_row:
                        raise HTTPException(400, f"section_code not found for {boundary_kind}: {section_code}")
                    section_start = float(section_row[3]) if section_row[3] is not None else None
                    section_end = float(section_row[4]) if section_row[4] is not None else None
                    if section_start is not None and section_end is not None:
                        center = (pk_start + pk_end) / 2.0
                        lo = min(section_start, section_end)
                        hi = max(section_start, section_end)
                        if center < lo or center >= hi:
                            raise HTTPException(400, f"object PK range is outside section {section_code}")

                cur.execute("DELETE FROM object_segments WHERE object_id = %s::uuid", (object_id,))
                if not clearing and pk_start is not None and pk_end is not None:
                    raw_pk = (getattr(body, "pk_raw_text", None) or "").strip() or (section_row[5] if section_row else None)
                    cur.execute(
                        """
                        INSERT INTO object_segments (object_id, pk_start, pk_end, pk_raw_text, comment, review_tag)
                        VALUES (%s::uuid, %s, %s, %s, %s, %s)
                        """,
                        (object_id, pk_start, pk_end, raw_pk, getattr(body, "comment", None) or "updated from statements", "pending_admin_review"),
                    )
                return _statement_object_response_from_cursor(cur, object_id)
    finally:
        conn.close()


@router.delete("/statements/object-work")
def statements_delete_object_work(body: StatementObjectWorkDeleteBody, _admin=Depends(require_admin)):
    unit = (body.unit or "").strip() or None
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '5s'")
                cur.execute(
                    """
                    SELECT o.id::text,
                           COALESCE(NULLIF(o.object_code, ''), o.name),
                           wt.id::text,
                           COALESCE(NULLIF(wt.name, ''), wt.code)
                    FROM objects o
                    CROSS JOIN work_types wt
                    WHERE o.id = %s::uuid
                      AND wt.id = %s::uuid
                    LIMIT 1
                    """,
                    (body.object_id, body.work_type_id),
                )
                ref_row = cur.fetchone()
                if not ref_row:
                    raise HTTPException(404, "object_id or work_type_id not found")

                unit_filter = ""
                unit_params: list = []
                if unit:
                    unit_filter = " AND COALESCE(unit, '') = %s"
                    unit_params.append(unit)

                cur.execute(
                    f"""
                    SELECT COUNT(*)::int
                    FROM daily_work_items
                    WHERE object_id = %s::uuid
                      AND work_type_id = %s::uuid
                      {unit_filter}
                      AND COALESCE(is_demo, false) = false
                    """,
                    [body.object_id, body.work_type_id, *unit_params],
                )
                fact_count = int((cur.fetchone() or [0])[0] or 0)
                if fact_count:
                    raise HTTPException(409, f"Нельзя удалить работу: по ней есть фактические значения ({fact_count})")

                deleted_plan_rows = 0
                deleted_project_segments = 0
                deleted_project_rows = 0

                if _statement_cur_table_exists(cur, "planned_work_items"):
                    cur.execute(
                        f"""
                        DELETE FROM planned_work_items
                        WHERE object_id = %s::uuid
                          AND work_type_id = %s::uuid
                          {unit_filter}
                        """,
                        [body.object_id, body.work_type_id, *unit_params],
                    )
                    deleted_plan_rows = cur.rowcount

                if _statement_cur_table_exists(cur, "project_work_items"):
                    project_unit_filter = ""
                    if unit:
                        project_unit_filter = " AND COALESCE(pwi.unit, '') = %s"
                    if _statement_cur_table_exists(cur, "project_work_item_segments"):
                        cur.execute(
                            f"""
                            DELETE FROM project_work_item_segments seg
                            USING project_work_items pwi
                            WHERE seg.project_work_item_id = pwi.id
                              AND pwi.object_id = %s::uuid
                              AND pwi.work_type_id = %s::uuid
                              {project_unit_filter}
                            """,
                            [body.object_id, body.work_type_id, *unit_params],
                        )
                        deleted_project_segments = cur.rowcount
                    cur.execute(
                        f"""
                        DELETE FROM project_work_items pwi
                        WHERE pwi.object_id = %s::uuid
                          AND pwi.work_type_id = %s::uuid
                          {project_unit_filter}
                        """,
                        [body.object_id, body.work_type_id, *unit_params],
                    )
                    deleted_project_rows = cur.rowcount

                return {
                    "ok": True,
                    "object_id": body.object_id,
                    "work_type_id": body.work_type_id,
                    "unit": unit,
                    "deleted_plan_rows": deleted_plan_rows,
                    "deleted_project_rows": deleted_project_rows,
                    "deleted_project_segments": deleted_project_segments,
                }
    finally:
        conn.close()


@router.delete("/statements/objects/{object_id}")
def statements_delete_object(object_id: str, _admin=Depends(require_admin)):
    conn = get_conn()
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '5s'")
                cur.execute(
                    """
                    SELECT o.id::text,
                           o.object_code,
                           o.name,
                           ot.code AS object_type_code
                    FROM objects o
                    LEFT JOIN object_types ot ON ot.id = o.object_type_id
                    WHERE o.id = %s::uuid
                    LIMIT 1
                    """,
                    (object_id,),
                )
                object_row = cur.fetchone()
                if not object_row:
                    raise HTTPException(404, "object not found")

                blockers = _statement_object_delete_blockers(cur, object_id)
                if blockers:
                    total = sum(int(value or 0) for value in blockers.values())
                    detail = "; ".join(f"{label}: {count}" for label, count in blockers.items())
                    raise HTTPException(409, f"Нельзя удалить объект: есть ссылки или фактические значения ({total}). {detail}")

                deleted: dict[str, int] = {}

                if _statement_cur_table_exists(cur, "planned_work_items"):
                    cur.execute("DELETE FROM planned_work_items WHERE object_id = %s::uuid", (object_id,))
                    deleted["planned_work_items"] = cur.rowcount

                if _statement_cur_table_exists(cur, "project_work_items"):
                    if _statement_cur_table_exists(cur, "project_work_item_segments"):
                        cur.execute(
                            """
                            DELETE FROM project_work_item_segments seg
                            USING project_work_items pwi
                            WHERE seg.project_work_item_id = pwi.id
                              AND pwi.object_id = %s::uuid
                            """,
                            (object_id,),
                        )
                        deleted["project_work_item_segments"] = cur.rowcount
                    cur.execute("DELETE FROM project_work_items WHERE object_id = %s::uuid", (object_id,))
                    deleted["project_work_items"] = cur.rowcount

                if _statement_cur_column_exists(cur, "object_map_points", "object_id"):
                    cur.execute("DELETE FROM object_map_points WHERE object_id = %s::uuid", (object_id,))
                    deleted["object_map_points"] = cur.rowcount

                if _statement_cur_column_exists(cur, "object_segments", "object_id"):
                    cur.execute("DELETE FROM object_segments WHERE object_id = %s::uuid", (object_id,))
                    deleted["object_segments"] = cur.rowcount

                cur.execute(
                    "DELETE FROM objects WHERE id = %s::uuid RETURNING id::text, object_code, name",
                    (object_id,),
                )
                deleted_row = cur.fetchone()
                if not deleted_row:
                    raise HTTPException(404, "object not found")
                deleted["objects"] = 1

                return {
                    "ok": True,
                    "object_id": deleted_row[0],
                    "object_code": deleted_row[1],
                    "object_name": deleted_row[2],
                    "deleted": deleted,
                }
    except psycopg2.errors.ForeignKeyViolation as exc:
        raise HTTPException(409, "Нельзя удалить объект: в БД остались связанные записи. Сначала удалите или перенесите ссылки.") from exc
    finally:
        conn.close()


